def render_configure_init(tools: dict[str, str]) -> bytes:
    """Force exact VC4.2 producer seats/facts without executing a probe."""
    require(isinstance(tools, dict)
            and set(tools) == {"compiler", "rc", "lib", "link"},
            "resident configure tool map is invalid")
    normalized = {}
    for role, value in tools.items():
        require(isinstance(value, str) and Path(value).is_absolute()
                and "\0" not in value and "\n" not in value
                and "\r" not in value and '"' not in value,
                f"resident configure {role} path is invalid")
        normalized[role] = value.replace("\\", "/")
    return f"""# Resident-authored hard-mode compiler facts; do not edit.
set(CMAKE_CXX_COMPILER \"{normalized['compiler']}\" CACHE FILEPATH \"resident pinned compiler\" FORCE)
set(CMAKE_RC_COMPILER \"{normalized['rc']}\" CACHE FILEPATH \"resident pinned RC\" FORCE)
set(CMAKE_AR \"{normalized['lib']}\" CACHE FILEPATH \"resident pinned LIB\" FORCE)
set(CMAKE_LINKER \"{normalized['link']}\" CACHE FILEPATH \"resident pinned LINK\" FORCE)
set(CMAKE_CXX_COMPILER_LINKER \"{normalized['link']}\" CACHE FILEPATH \"resident pinned CXX LINK\" FORCE)
set(CMAKE_CXX_COMPILER_LINKER_ID MSVC CACHE STRING \"resident pinned linker id\" FORCE)
set(CMAKE_CXX_COMPILER_LINKER_VERSION 4.20 CACHE STRING \"resident pinned linker version\" FORCE)
set(CMAKE_CXX_COMPILER_LINKER_FRONTEND_VARIANT MSVC CACHE STRING \"resident pinned linker frontend\" FORCE)
set(CMAKE_SYSTEM_NAME Windows CACHE STRING \"resident pinned target system\" FORCE)\n\
set(CMAKE_SYSTEM_PROCESSOR x86 CACHE STRING \"resident pinned target processor\" FORCE)\n\
set(CMAKE_CXX_COMPILER_ID MSVC CACHE STRING \"resident pinned compiler id\" FORCE)\n\
set(CMAKE_CXX_COMPILER_VERSION 10.20 CACHE STRING \"resident pinned compiler version\" FORCE)\n\
set(CMAKE_CXX_PLATFORM_ID Windows CACHE STRING \"resident pinned compiler platform\" FORCE)\n\
set(CMAKE_CXX_COMPILER_ARCHITECTURE_ID X86 CACHE STRING \"resident pinned compiler architecture\" FORCE)\n\
set(CMAKE_CXX_COMPILER_ID_RUN 1 CACHE INTERNAL \"resident disabled compiler id probe\" FORCE)\n\
set(CMAKE_CXX_COMPILER_FORCED TRUE CACHE INTERNAL \"resident disabled compiler test\" FORCE)\n\
set(CMAKE_CXX_COMPILER_WORKS TRUE CACHE INTERNAL \"resident disabled compiler works probe\" FORCE)\n\
set(CMAKE_CXX_ABI_COMPILED TRUE CACHE INTERNAL \"resident disabled compiler ABI probe\" FORCE)\n\
set(CMAKE_CXX_SIZEOF_DATA_PTR 4 CACHE INTERNAL \"resident pinned pointer size\" FORCE)\n\
set(CMAKE_CXX_BYTE_ORDER LITTLE_ENDIAN CACHE INTERNAL \"resident pinned byte order\" FORCE)\n\
set(CMAKE_SIZEOF_VOID_P 4 CACHE INTERNAL \"resident pinned pointer size\" FORCE)\n\
set(CMAKE_CXX_IMPLICIT_INCLUDE_DIRECTORIES \"\" CACHE INTERNAL \"resident pinned empty implicit includes\" FORCE)\n\
set(CMAKE_CXX_IMPLICIT_LINK_LIBRARIES \"\" CACHE INTERNAL \"resident pinned empty implicit libraries\" FORCE)\n\
set(CMAKE_CXX_IMPLICIT_LINK_DIRECTORIES \"\" CACHE INTERNAL \"resident pinned empty implicit link dirs\" FORCE)\n\
set(CMAKE_CXX_IMPLICIT_LINK_FRAMEWORK_DIRECTORIES \"\" CACHE INTERNAL \"resident pinned empty frameworks\" FORCE)\n\
set(CMAKE_TRY_COMPILE_TARGET_TYPE STATIC_LIBRARY CACHE STRING \"resident forbids executable probes\" FORCE)\n\
set(COMPILER_SUPPORTS_Wparentheses \"\" CACHE INTERNAL \"resident pinned unsupported warning probe\" FORCE)\n\
""".encode("utf-8")


