def validate_native_reccmp_transaction_operand(
    physical: Path, build_dir: Path, nonce: str, context: str,
) -> tuple[tuple[str, ...], tuple[str, ...]]:
    """Bind one removed private operand to the exact session-owned seat."""
    authority = active_build_authority()
    run_parts = authority.parts(
        native_reccmp_transaction_path(build_dir, nonce)
    )
    parts = authority.parts(physical)
    require(
        len(parts) > len(run_parts) and parts[:len(run_parts)] == run_parts,
        f"{context} physical operand is outside its run-private snapshot",
    )
    return parts, run_parts


