def validate_composition_audit_schema(value: object, context: str) -> None:
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, COMPOSITION_AUDIT_KEYS, context)
    for key, allowed in (
        ("retail_oracle", COMPOSITION_RETAIL_ORACLE_KEYS),
        ("codeview_range", COMPOSITION_CODEVIEW_RANGE_KEYS),
        ("provenance", COMPOSITION_PROVENANCE_KEYS),
    ):
        nested = value.get(key)
        require(isinstance(nested, dict), f"{context}.{key} must be an object")
        exact_audit_keys(nested, allowed, f"{context}.{key}")
    validate_manifest_fpo_record(value.get("seed_fpo"), f"{context}.seed_fpo")
    validate_manifest_fpo_record(value.get("donor_fpo"), f"{context}.donor_fpo")


def require_exact_flat_build_namespace(
    authority: BuildRootAuthority,
    directory: Path,
    expected_names: set[str],
    context: str,
) -> None:
    names = set(authority.list_names(directory))
    require(names == expected_names,
            f"{context} has missing or extra entries")
    for name in sorted(names):
        metadata = authority.lstat(directory / name)
        require(metadata is not None and stat.S_ISREG(metadata.st_mode),
                f"{context} entry is not a regular file: {name}")


def require_exact_build_namespace(
    authority: BuildRootAuthority,
    directory: Path,
    expected: dict[str, str],
    context: str,
    *, replace_pin: bool = False,
) -> None:
    parts = authority.parts(directory, allow_root=True)
    if replace_pin:
        authority.directory_membership_pins.pop(parts, None)
    names = set(authority.list_names(directory))
    require(names == set(expected), f"{context} has missing or extra entries")
    for name, expected_kind in sorted(expected.items()):
        metadata = authority.lstat(directory / name)
        require(
            metadata is not None
            and authority._entry_kind(metadata.st_mode) == expected_kind,
            f"{context} entry has the wrong type: {name}",
        )


def validate_private_auxiliary_audit(
    authority: BuildRootAuthority,
    records: object,
    private_object: Path,
    private_pdb: Path,
    context: str,
) -> None:
    require(isinstance(records, list), f"{context} must be an array")
    area = private_object.parent
    require(private_pdb.parent == area,
            f"{context} private OBJ/PDB areas differ")
    allowed = {
        private_object.with_suffix(".idb").name: "incremental_state",
        f"{private_object.name}.sbr": "wrapper_browser_database",
    }
    expected_namespace = {
        private_object.name: "file",
        private_pdb.name: "file",
        "tmp": "directory",
    }
    observed_names = []
    for index, record in enumerate(records):
        item_context = f"{context}[{index}]"
        require(isinstance(record, dict), f"{item_context} must be an object")
        exact_audit_keys(
            record, AUXILIARY_COMPILER_OUTPUT_KEYS, item_context
        )
        name = record.get("name")
        require(isinstance(name, str) and name in allowed,
                f"{item_context}.name is unsupported")
        require(record.get("kind") == allowed[name],
                f"{item_context}.kind differs")
        require(name not in observed_names,
                f"{context} contains duplicate auxiliary outputs")
        observed_names.append(name)
        path = Path(record.get("path", ""))
        require(
            authority.parts(path) == authority.parts(area / name)
            and authority.is_regular_file(path),
            f"{item_context}.path differs",
        )
        data = authority.read_bytes(path)
        require(
            isinstance(record.get("size"), int)
            and not isinstance(record.get("size"), bool)
            and record["size"] == len(data)
            and require_sha(record.get("sha256"), f"{item_context}.sha256")
            == sha256_bytes(data),
            f"{item_context} content differs",
        )
        expected_namespace[name] = "file"
    require(observed_names == sorted(observed_names),
            f"{context} is not canonically ordered")
    require_exact_build_namespace(
        authority,
        area / "tmp",
        {},
        f"{context} private compiler temporary namespace",
    )
    require_exact_build_namespace(
        authority,
        area,
        expected_namespace,
        f"{context} private compiler namespace",
    )


def validate_dependency_audit(
    authority: BuildRootAuthority,
    state: dict,
    audit: dict,
    command_entry: dict,
    source: Path,
    expected_output: Path,
    context: str,
) -> None:
    output_value = audit.get("dependency_output")
    require(isinstance(output_value, str) and output_value,
            f"{context}.dependency_output must be a non-empty string")
    output = Path(output_value)
    require(authority.parts(output) == authority.parts(expected_output),
            f"{context}.dependency_output differs")
    require(authority.is_regular_file(output),
            f"{context}.dependency_output is not a regular file")
    data = authority.read_bytes(output)
    require(
        require_sha(
            audit.get("dependency_output_sha256"),
            f"{context}.dependency_output_sha256",
        ) == sha256_bytes(data),
        f"{context}.dependency_output_sha256 differs",
    )
    command = derive_dependency_command(command_entry["argv"], output)
    require(
        require_sha(
            audit.get("dependency_command_sha256"),
            f"{context}.dependency_command_sha256",
        ) == sha256_bytes(json.dumps(
            command, ensure_ascii=True, separators=(",", ":")
        ).encode("utf-8")),
        f"{context}.dependency_command_sha256 differs",
    )
    transport = audit.get("dependency_transport")
    require(isinstance(transport, dict),
            f"{context}.dependency_transport is not an object")
    exact_audit_keys(
        transport, DEPENDENCY_TRANSPORT_AUDIT_KEYS,
        f"{context}.dependency_transport",
    )
    validate_snapshotted_compiler_command_hash(
        state, command, transport,
        audit.get("dependency_executed_command_sha256"),
        f"{context}.dependency_executed_command_sha256",
    )
    evidence = validate_execution_projection_evidence(
        transport.get("execution_projection_root"),
        transport.get("execution_projection_descriptor_sha256"),
        authority.build_root, f"{context}.dependency_transport",
    )
    validate_execution_projection_source_overlay_evidence(
        state, evidence, f"{context}.dependency_transport"
    )
    require(
        transport.get("schema") == 1
        and transport.get("policy")
        == "preauthenticated_projection_dependency_pass_v1"
        and transport.get("toolchain_snapshot_sha256")
        == sha256_file(toolchain_snapshot_path(authority.build_root) / "snapshot.json")
        and transport.get("command_snapshot_sha256")
        == sha256_file(command_snapshot_path(authority.build_root) / "snapshot.json")
        and transport.get("writable_build_branch_cleared") is True
        and transport.get("run_private_namespace_removed") is True
        and transport.get("immutable_entry_count")
        == evidence.get("immutable_entry_count")
        and transport.get("immutable_records_sha256")
        == evidence.get("immutable_records_sha256")
        and transport.get("toolchain_snapshot_sha256")
        == evidence.get("toolchain_snapshot_sha256")
        and transport.get("command_snapshot_sha256")
        == evidence.get("command_snapshot_sha256"),
        f"{context}.dependency_transport identity differs",
    )
    records = audit.get("consumed_dependencies")
    require(isinstance(records, list) and records,
            f"{context}.consumed_dependencies must be a non-empty array")
    for index, record in enumerate(records):
        item_context = f"{context}.consumed_dependencies[{index}]"
        require(isinstance(record, dict), f"{item_context} must be an object")
        exact_audit_keys(record, {"path", "sha256"}, item_context)
        path = record.get("path")
        require(isinstance(path, str) and Path(path).is_absolute(),
                f"{item_context}.path must be absolute")
        require_sha(record.get("sha256"), f"{item_context}.sha256")
    projection = authority.execution_projection
    require(
        isinstance(projection, dict)
        and Path(projection["root"])
        == Path(transport["execution_projection_root"])
        and projection["descriptor_sha256"]
        == transport["execution_projection_descriptor_sha256"]
        and projection.get("finalized") is True
        and projection.get("removed") is True,
        f"{context} lacks the terminal in-memory projection authority",
    )
    projection_records = projection["immutable_by_path"]
    require(
        len(projection_records) == len(projection["immutable_records"]),
        f"{context} projection record paths are duplicated",
    )
    reconstructed = parse_preprocessed_dependencies(
        data, source, command_entry["input_trees"],
        virtual_z_root=Path(projection["root"]) / "z",
        virtual_z_records=projection_records,
    )
    require(exact_json_equal(records, reconstructed),
            f"{context}.consumed_dependencies differ")
    require_exact_build_namespace(
        authority,
        output.parent,
        {"dependencies.i": "file", "tmp": "directory"},
        f"{context} private dependency namespace",
    )
    require_exact_build_namespace(
        authority,
        output.parent / "tmp",
        {},
        f"{context} private dependency temporary namespace",
    )


EXECUTION_PROJECTION_FINALIZATION_KEYS = {
    "schema", "status", "backend", "transport_schema", "projection_root",
    "projection_descriptor_sha256", "toolchain_snapshot_sha256",
    "command_snapshot_sha256", "immutable_entry_count",
    "immutable_records_sha256", "terminal_immutable_records_sha256",
    "source_record_count", "unique_record_install_count",
    "projection_materialization_count", "seat_capacity", "lease_count",
    "prefix_materialization_count", "prefix_use_count",
    "prefix_initial_content_sha256", "prefix_terminal_content_sha256",
    "prefix_server_quiescent",
    "writable_build_branch_empty", "projection_removed",
    "source_overlay_enabled", "source_overlay_policy_sha256",
    "source_overlay_actual_records_sha256",
    "source_overlay_receipt_sha256", "source_overlay_output_count",
}


def validate_execution_projection_evidence(
    root_value: object, descriptor_sha_value: object,
    build_dir: Path, context: str,
) -> dict:
    """Bind a producer to the one live or terminally removed projection."""
    require(isinstance(root_value, str),
            f"{context} execution projection root is invalid")
    descriptor_sha = require_sha(
        descriptor_sha_value,
        f"{context} execution projection descriptor SHA-256",
    )
    authority = active_build_authority()
    root = Path(root_value)
    parts = authority.parts(root)
    require(
        len(parts) == 3
        and parts[:2] == ("byte-identity", "execution-projections")
        and re.fullmatch(r"session-[0-9a-f]{32}", parts[2]) is not None,
        f"{context} execution projection root differs",
    )
    live = authority.execution_projection
    if isinstance(live, dict) and live.get("removed") is not True:
        require(
            Path(live["root"]) == root
            and live["descriptor_sha256"] == descriptor_sha
            and live.get("poisoned") is False,
            f"{context} live execution projection differs",
        )
        live["holder"].revalidate()
        return {
            "status": "LIVE_HELD_EXECUTION_PROJECTION",
            "immutable_entry_count": live["immutable_entry_count"],
            "immutable_records_sha256": live["immutable_records_sha256"],
            "toolchain_snapshot_sha256": live["toolchain_snapshot_sha256"],
            "command_snapshot_sha256": live["command_snapshot_sha256"],
            "source_overlay_enabled": live["source_overlay_enabled"],
            "source_overlay_policy_sha256": live[
                "source_overlay_policy_sha256"
            ],
            "source_overlay_actual_records_sha256": live[
                "source_overlay_actual_records_sha256"
            ],
            "source_overlay_receipt_sha256": live[
                "source_overlay_receipt_sha256"
            ],
            "source_overlay_output_count": live[
                "source_overlay_output_count"
            ],
        }
    receipt_path = execution_projection_finalization_path(build_dir)
    receipt = strict_json_loads(authority.read_bytes(receipt_path))
    require(isinstance(receipt, dict),
            f"{context} execution projection receipt is invalid")
    exact_audit_keys(
        receipt, EXECUTION_PROJECTION_FINALIZATION_KEYS,
        f"{context} execution projection receipt",
    )
    require(
        authority.execution_projection_receipt is not None
        and exact_json_equal(
            authority.execution_projection_receipt, receipt
        ),
        f"{context} finalization receipt was not produced by this resident transaction",
    )
    require(
        receipt.get("schema") == 1
        and receipt.get("status")
        == "EXECUTION_PROJECTION_FINALIZED_AND_REMOVED"
        and receipt.get("projection_root") == str(root)
        and receipt.get("projection_descriptor_sha256") == descriptor_sha
        and receipt.get("backend") == selected_backend()
        and receipt.get("toolchain_snapshot_sha256")
        == sha256_file(toolchain_snapshot_path(build_dir) / "snapshot.json")
        and receipt.get("command_snapshot_sha256")
        == sha256_file(command_snapshot_path(build_dir) / "snapshot.json")
        and receipt.get("immutable_records_sha256")
        == receipt.get("terminal_immutable_records_sha256")
        and type(receipt.get("immutable_entry_count")) is int
        and receipt["immutable_entry_count"] > 0
        and type(receipt.get("source_record_count")) is int
        and type(receipt.get("unique_record_install_count")) is int
        and 0 < receipt["unique_record_install_count"]
        <= receipt["source_record_count"]
        and receipt.get("projection_materialization_count") == 1
        and receipt.get("prefix_materialization_count") == 1
        and receipt.get("prefix_use_count") == receipt.get("lease_count")
        and receipt.get("prefix_initial_content_sha256")
        == receipt.get("prefix_terminal_content_sha256")
        and SHA256_RE.fullmatch(
            receipt.get("prefix_initial_content_sha256", "")
        ) is not None
        and receipt.get("prefix_server_quiescent") is True
        and receipt.get("seat_capacity") == 1
        and type(receipt.get("lease_count")) is int
        and receipt["lease_count"] > 0
        and receipt.get("writable_build_branch_empty") is True
        and receipt.get("projection_removed") is True
        and type(receipt.get("source_overlay_enabled")) is bool
        and type(receipt.get("source_overlay_output_count")) is int
        and receipt["source_overlay_output_count"] >= 0
        and (
            all(
                SHA256_RE.fullmatch(receipt.get(key) or "") is not None
                for key in (
                    "source_overlay_policy_sha256",
                    "source_overlay_actual_records_sha256",
                    "source_overlay_receipt_sha256",
                )
            )
            and receipt["source_overlay_output_count"] > 0
            if receipt["source_overlay_enabled"] else
            receipt.get("source_overlay_policy_sha256") is None
            and receipt.get("source_overlay_actual_records_sha256") is None
            and receipt.get("source_overlay_receipt_sha256") is None
            and receipt["source_overlay_output_count"] == 0
        ),
        f"{context} execution projection finalization differs",
    )
    authority.assert_absent(root)
    return receipt


def validate_execution_projection_source_overlay_evidence(
    state: dict, evidence: dict, context: str,
) -> Path | None:
    """Bind one producer/terminal audit to this manifest's typed overlay.

    The projection descriptor and resident-produced terminal receipt carry the
    compact source-overlay identity.  The separate materialization receipt is
    retained outside the ephemeral projection root and is itself recorded in
    the resident causal DAG; its hash is never accepted merely from disk.
    """
    overlay = state["source_overlay"]
    enabled = overlay["enabled"]
    expected = {
        "source_overlay_enabled": enabled,
        "source_overlay_policy_sha256": (
            overlay["policy_sha256"] if enabled else None
        ),
        "source_overlay_actual_records_sha256": (
            overlay["actual_records_sha256"] if enabled else None
        ),
        "source_overlay_output_count": (
            len(overlay["outputs"]) if enabled else 0
        ),
    }
    require(
        all(evidence.get(key) == value for key, value in expected.items())
        and (
            SHA256_RE.fullmatch(
                evidence.get("source_overlay_receipt_sha256") or ""
            ) is not None
            if enabled else
            evidence.get("source_overlay_receipt_sha256") is None
        ),
        f"{context} typed source overlay projection identity differs",
    )
    if not enabled:
        return None
    path = source_overlay_receipt_path(Path(state["build_dir"]))
    authority = active_build_authority()
    receipt = authority.execution_projection
    receipt = (
        receipt.get("source_overlay_receipt")
        if isinstance(receipt, dict) else None
    )
    require(
        isinstance(receipt, dict)
        and receipt.get("schema") == 1
        and receipt.get("status") == "TYPED_SOURCE_OVERLAY_MATERIALIZED"
        and receipt.get("manifest_sha256") == state["manifest_sha256"]
        and receipt.get("renderer") == SOURCE_OVERLAY_RENDERER
        and receipt.get("policy_sha256") == overlay["policy_sha256"]
        and receipt.get("actual_records_sha256")
        == overlay["actual_records_sha256"]
        and receipt.get("anchor_evidence_sha256")
        == overlay["anchor_evidence_sha256"]
        and receipt.get("physical_output_count") == len(overlay["outputs"])
        and sha256_file(path) == evidence["source_overlay_receipt_sha256"]
        and exact_json_equal(
            strict_json_loads(authority.read_bytes(path)), receipt
        ),
        f"{context} typed source overlay materialization receipt differs",
    )
    return path


def validate_transport_audit(
    authority: BuildRootAuthority,
    value: object,
    *,
    state: dict,
    command_inventory: dict,
    command_entry: dict,
    object_path: Path,
    pdb_path: Path,
    context: str,
) -> None:
    """Validate the exact run-private virtual-Z provenance record."""
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, TRANSPORT_AUDIT_KEYS, context)
    require(
        type(value.get("schema")) is int
        and value.get("schema") == 1
        and value.get("policy") == "transaction_execution_projection_v1"
        and value.get("backend") == state["execution_backend"]["id"]
        and value.get("execution_projection_policy")
        == "transaction_scoped_immutable_inputs_single_writable_build_seat_v1"
        and value.get("execution_projection_seat_capacity") == 1
        and value.get("execution_projection_writable_empty_prelease") is True
        and value.get("execution_projection_input_postflight_clear") is True
        and value.get("execution_projection_lease_released") is True
        and value.get("run_private_namespace_removed") is True,
        f"{context} policy differs",
    )
    details = value.get("backend_details")
    require(isinstance(details, dict),
            f"{context}.backend_details is not an object")
    if value["backend"] == POSIX_WINE_BACKEND:
        exact_audit_keys(
            details, POSIX_WINE_TRANSPORT_DETAILS_KEYS,
            f"{context}.backend_details",
        )
        require(
            details.get("schema") == "posix_wine_private_prefix_v1"
            and details.get("server_shutdown_policy")
            == state["transport"]["server_shutdown"]
            and details.get("server_preflight_clear") is True
            and details.get("server_postflight_clear") is True,
            f"{context}.backend_details differs",
        )
    else:
        require(
            value["backend"] == WINDOWS_NATIVE_BACKEND
            and details.get("schema") == "windows_native_private_job_v1",
            f"{context}.backend_details backend is unsupported",
        )
    projection_evidence = validate_execution_projection_evidence(
        value.get("execution_projection_root"),
        value.get("execution_projection_descriptor_sha256"),
        Path(state["build_dir"]), context,
    )
    validate_execution_projection_source_overlay_evidence(
        state, projection_evidence, context
    )
    require(
        value.get("logical_cwd") == command_entry["directory"],
        f"{context}.logical_cwd differs",
    )
    logical_object = Path(value.get("logical_object", ""))
    logical_pdb = Path(value.get("logical_pdb", ""))
    require(
        authority.parts(logical_object) == authority.parts(object_path)
        and authority.parts(logical_pdb) == authority.parts(pdb_path),
        f"{context} logical compiler outputs differ",
    )
    validate_toolchain_snapshot(state, Path(state["build_dir"]))
    command_audit = validate_command_snapshot(
        command_inventory["entries"],
        Path(state["build_dir"]),
        command_inventory["transport_snapshot"],
        state=state, inventory=state["inventory"],
    )
    require(
        require_sha(
            value.get("toolchain_snapshot_sha256"),
            f"{context}.toolchain_snapshot_sha256",
        )
        == sha256_file(toolchain_snapshot_path(Path(state["build_dir"])) / "snapshot.json")
        and require_sha(
            value.get("command_snapshot_sha256"),
            f"{context}.command_snapshot_sha256",
        )
        == sha256_file(command_snapshot_path(Path(state["build_dir"])) / "snapshot.json")
        and exact_json_equal(
            command_audit,
            command_inventory["transport_snapshot"],
        ),
        f"{context} snapshot identity differs",
    )


def recover_unambiguous_audit_outputs(raw: str) -> list[str]:
    """Salvage only unambiguous top-level OBJ/PDB paths from a rejected audit."""
    try:
        value = strict_json_loads(raw, preserve_pairs=True)
    except (json.JSONDecodeError, UnicodeError):
        return []
    if not isinstance(value, PreservedJsonObject):
        return []
    outputs = []
    for key in ("object", "pdb"):
        values = [item for name, item in value if name == key]
        if (values and all(isinstance(item, str) and item for item in values)
                and len(set(values)) == 1):
            outputs.append(values[0])
    return outputs


def unlink_invalid_audit_entry(parent_fd: int, name: str) -> bool:
    """Prune only a non-directory audit entry without following it."""
    try:
        metadata = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except (FileNotFoundError, OSError):
        return False
    if stat.S_ISDIR(metadata.st_mode):
        return False
    try:
        os.unlink(name, dir_fd=parent_fd)
    except (FileNotFoundError, IsADirectoryError, OSError):
        return False
    return True


def open_or_prune_audit_directory(
    root_fd: int, parts: tuple[str, ...]
) -> int | None:
    """Open an audit directory chain or prune the first redirected entry."""
    descriptor = os.dup(root_fd)
    try:
        for part in parts:
            try:
                metadata = os.stat(
                    part, dir_fd=descriptor, follow_symlinks=False
                )
            except FileNotFoundError:
                os.close(descriptor)
                return None
            if not stat.S_ISDIR(metadata.st_mode):
                unlink_invalid_audit_entry(descriptor, part)
                os.close(descriptor)
                return None
            try:
                child = os.open(part, DIRECTORY_FD_FLAGS, dir_fd=descriptor)
            except OSError:
                unlink_invalid_audit_entry(descriptor, part)
                os.close(descriptor)
                return None
            opened = os.fstat(child)
            if ((opened.st_dev, opened.st_ino)
                    != (metadata.st_dev, metadata.st_ino)):
                os.close(child)
                raise ByteIdentityError(
                    f"compiler audit directory changed during cleanup: {part}"
                )
            os.close(descriptor)
            descriptor = child
        return descriptor
    except BaseException:
        os.close(descriptor)
        raise


def read_audit_at(
    parent_fd: int, name: str, expected_identity: tuple[int, int]
) -> str | None:
    """Read one audit through a held parent fd and a no-follow file fd."""
    try:
        descriptor = os.open(name, AUDIT_FILE_FD_FLAGS, dir_fd=parent_fd)
    except OSError:
        unlink_invalid_audit_entry(parent_fd, name)
        return None
    try:
        metadata = os.fstat(descriptor)
        if (not stat.S_ISREG(metadata.st_mode)
                or not 0 <= metadata.st_size <= MAX_AUDIT_FILE_BYTES
                or (metadata.st_dev, metadata.st_ino) != expected_identity):
            return None
        remaining = metadata.st_size
        chunks = []
        while remaining:
            chunk = os.read(descriptor, min(remaining, 1024 * 1024))
            if not chunk:
                return None
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            return None
        after = os.fstat(descriptor)
        try:
            visible = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError:
            return None
        if (
            (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns)
            != (
                metadata.st_dev,
                metadata.st_ino,
                metadata.st_size,
                metadata.st_mtime_ns,
            )
            or (visible.st_dev, visible.st_ino) != expected_identity
        ):
            return None
        return b"".join(chunks).decode("utf-8")
    except (OSError, UnicodeError):
        return None
    finally:
        os.close(descriptor)


def cleanup_audit_directory_fd(
    root_fd: int,
    directory_fd: int,
    unlink_output,
) -> None:
    """Remove compiler audits through stable directory/file descriptors."""
    try:
        names = sorted(os.listdir(directory_fd))
    except OSError:
        return
    for name in names:
        if (not name or name in (".", "..")
                or "/" in name or "\0" in name):
            continue
        try:
            metadata = os.stat(
                name, dir_fd=directory_fd, follow_symlinks=False
            )
        except (FileNotFoundError, OSError):
            continue
        if stat.S_ISLNK(metadata.st_mode):
            unlink_invalid_audit_entry(directory_fd, name)
            continue
        if stat.S_ISDIR(metadata.st_mode):
            try:
                child_fd = os.open(
                    name, DIRECTORY_FD_FLAGS, dir_fd=directory_fd
                )
            except OSError:
                unlink_invalid_audit_entry(directory_fd, name)
                continue
            try:
                opened = os.fstat(child_fd)
                require(
                    (opened.st_dev, opened.st_ino)
                    == (metadata.st_dev, metadata.st_ino),
                    f"compiler audit directory changed during cleanup: {name}",
                )
                cleanup_audit_directory_fd(root_fd, child_fd, unlink_output)
            finally:
                os.close(child_fd)
            continue
        if not (stat.S_ISREG(metadata.st_mode) and name.endswith(".json")):
            continue
        raw = read_audit_at(
            directory_fd, name, (metadata.st_dev, metadata.st_ino)
        )
        if raw is not None:
            try:
                audit = strict_json_loads(raw)
                values = (
                    [audit.get(key) for key in ("object", "pdb")]
                    if isinstance(audit, dict) else []
                )
            except (json.JSONDecodeError, ByteIdentityError, ValueError):
                values = recover_unambiguous_audit_outputs(raw)
            for value in values:
                if isinstance(value, str) and value:
                    unlink_output(value, root_fd)
        # The name may have been atomically replaced after it was read. unlinkat
        # still removes only the current lexical entry, never a redirected target.
        unlink_invalid_audit_entry(directory_fd, name)


def cleanup_compiler_audits_fd(root_fd: int, unlink_output) -> None:
    """Sweep both exact compiler-audit roots without pathname traversal."""
    for relative_root in COMPILER_AUDIT_RELATIVE_ROOTS:
        directory_fd = open_or_prune_audit_directory(
            root_fd, tuple(relative_root.parts)
        )
        if directory_fd is None:
            continue
        try:
            cleanup_audit_directory_fd(root_fd, directory_fd, unlink_output)
        finally:
            os.close(directory_fd)


def invalidate_framework_verdict(build_dir: Path) -> Path:
    authority = active_build_authority()
    verdict_path = (
        authority.build_root / "byte-identity/audit/framework-verdict.json"
    )
    authority.prune_leaf_or_redirect(verdict_path)
    authority.assert_absent(verdict_path)
    return verdict_path


def invalidate_build_paths(paths: list[Path]) -> None:
    """Fail-closed removal that prunes only in-build redirecting entries."""
    authority = active_build_authority()
    failures = []
    for path in paths:
        try:
            redirected = authority.prune_leaf_or_redirect(path)
            authority.assert_absent(path)
            if redirected:
                failures.append(f"{path}: redirected ancestor was pruned")
        except (ByteIdentityError, OSError, ValueError) as error:
            failures.append(f"{path}: {error}")
    require(not failures, "build-state invalidation failed: " + "; ".join(failures))


def validate_execution_backends(value: object | None) -> dict:
    """Validate the platform-neutral backend registry and select this host."""
    if value is None:
        # Schema-2 native fixtures predate the explicit registry. Preserve
        # their POSIX policy surface without silently admitting Windows.
        require(
            host_backend() == POSIX_WINE_BACKEND,
            "manifest has no native-Windows execution backend registry",
        )
        return {
            "id": POSIX_WINE_BACKEND,
            "host": "posix",
            "status": "framework_implemented",
            "transport": "wine_virtual_z_v1",
            "filesystem_authority": "root_fd_openat_nofollow",
            "process_tree": "posix_process_group",
        }
    require(isinstance(value, dict), "execution_backends must be an object")
    exact_audit_keys(
        value, {"selection", "profiles"}, "execution_backends"
    )
    require(
        value.get("selection") == "host_os_exact_no_cross_backend_v1",
        "execution backend selection policy differs",
    )
    profiles = value.get("profiles")
    require(isinstance(profiles, list) and len(profiles) == 2,
            "execution_backends.profiles must contain exactly two profiles")
    normalized = {}
    for index, profile in enumerate(profiles):
        context = f"execution_backends.profiles[{index}]"
        require(isinstance(profile, dict), f"{context} must be an object")
        identifier = profile.get("id")
        if identifier == POSIX_WINE_BACKEND:
            exact_audit_keys(
                profile,
                {
                    "id", "host", "status", "transport",
                    "filesystem_authority", "process_tree",
                },
                context,
            )
            require(
                exact_json_equal(profile, {
                    "id": POSIX_WINE_BACKEND,
                    "host": "posix",
                    "status": "framework_implemented",
                    "transport": "wine_virtual_z_v1",
                    "filesystem_authority": "root_fd_openat_nofollow",
                    "process_tree": "posix_process_group",
                }),
                f"{context} policy differs",
            )
        elif identifier == WINDOWS_NATIVE_BACKEND:
            exact_audit_keys(
                profile,
                {
                    "id", "host", "status", "transport", "logical_drive",
                    "filesystem_authority", "process_tree",
                    "toolchain_repository", "toolchain_commit",
                    "toolchain_files", "ci_contract",
                },
                context,
            )
            require(
                profile.get("host") == "nt"
                and profile.get("status")
                == "architectural_seam_deferred_untested"
                and profile.get("transport") == "native_windows_logical_z_v1"
                and profile.get("logical_drive") == "Z:"
                and profile.get("filesystem_authority")
                == "held_nofollow_handle_chain"
                and profile.get("process_tree")
                == "windows_kill_on_close_job_object"
                and profile.get("toolchain_repository") == "itsmattkc/msvc420"
                and profile.get("toolchain_commit")
                == "df2c13aad74c094988c6c7e784234c2e778a0e91"
                and exact_json_equal(
                    profile.get("toolchain_files"), WINDOWS_NATIVE_TOOLCHAIN_PINS
                )
                and profile.get("ci_contract") == "deferred_nonblocking_v1",
                f"{context} native Windows authority contract differs",
            )
        else:
            raise ByteIdentityError(f"{context}.id is unsupported")
        require(identifier not in normalized,
                f"duplicate execution backend profile: {identifier}")
        normalized[identifier] = profile
    require(set(normalized) == {POSIX_WINE_BACKEND, WINDOWS_NATIVE_BACKEND},
            "execution backend registry is incomplete")
    return dict(normalized[selected_backend()])


TOOLCHAIN_COMMON_KEYS = {
    "compiler_sha256", "compiler_id", "compiler_version",
    "python_sha256", "python_version", "keep_compile_debug",
    "max_child_seconds", "provenance",
}
TOOLCHAIN_POSIX_PROFILE_KEYS = {
    "status", "transport_schema", "compiler_root_parent_levels",
    "compiler_support_files", "producer_support_files",
    "required_absent_toolchain_files",
    "runtime_executables", "sealed_include_trees", "runtime_closure",
    "transport", "child_environment",
}
TOOLCHAIN_LEGACY_POSIX_KEYS = (
    TOOLCHAIN_POSIX_PROFILE_KEYS - {"status", "transport_schema"}
)


def select_toolchain_backend_profile(
    toolchain: object, *, explicit_registry: bool, execution_backend: dict,
) -> tuple[dict, bool]:
    """Select transport policy before resolving any backend host pathname."""
    require(isinstance(toolchain, dict), "toolchain must be an object")
    if not explicit_registry:
        exact_keys(
            toolchain, TOOLCHAIN_COMMON_KEYS | TOOLCHAIN_LEGACY_POSIX_KEYS,
            "toolchain",
        )
        require(execution_backend["id"] == POSIX_WINE_BACKEND,
                "legacy toolchain policy is POSIX/Wine only")
        return ({
            "status": "framework_implemented",
            "transport_schema": "wine_virtual_z_v1",
            **{key: toolchain[key] for key in TOOLCHAIN_LEGACY_POSIX_KEYS},
        }, True)

    exact_keys(toolchain, TOOLCHAIN_COMMON_KEYS | {"backend_profiles"},
               "toolchain")
    profiles = toolchain.get("backend_profiles")
    require(isinstance(profiles, dict)
            and set(profiles) == {
                POSIX_WINE_BACKEND, WINDOWS_NATIVE_BACKEND,
            }, "toolchain backend profile universe differs")
    posix = profiles[POSIX_WINE_BACKEND]
    require(isinstance(posix, dict),
            "POSIX/Wine toolchain backend profile is not an object")
    exact_audit_keys(posix, TOOLCHAIN_POSIX_PROFILE_KEYS,
                     "POSIX/Wine toolchain backend profile")
    require(
        posix.get("status") == "framework_implemented"
        and posix.get("transport_schema") == "wine_virtual_z_v1",
        "POSIX/Wine toolchain backend profile differs",
    )
    windows = profiles[WINDOWS_NATIVE_BACKEND]
    require(isinstance(windows, dict),
            "native-Windows toolchain backend profile is not an object")
    exact_audit_keys(
        windows, {"status", "transport_schema"},
        "native-Windows toolchain backend profile",
    )
    require(
        windows == {
            "status": "architectural_seam_deferred_untested",
            "transport_schema": "native_windows_logical_z_v1",
        },
        "native-Windows toolchain backend profile differs",
    )
    selected = profiles[execution_backend["id"]]
    require(
        selected.get("status") == "framework_implemented",
        "toolchain backend is explicitly deferred: "
        f"{execution_backend['id']}",
    )
    return dict(selected), False


def validate_manifest(
    manifest_path: Path,
    source_dir: Path,
    build_dir: Path,
    *,
    configured_compiler: str | None = None,
    compiler_id: str | None = None,
    compiler_version: str | None = None,
    generator: str | None = None,
) -> dict:
    """Load the fixed schema and return normalized, fully validated state."""
    build_root = (
        ACTIVE_BUILD_AUTHORITIES[-1].build_root
        if ACTIVE_BUILD_AUTHORITIES else build_dir.resolve()
    )
    source_root, _ = require_disjoint_source_build(source_dir, build_root)
    try:
        authority = (
            ACTIVE_BUILD_AUTHORITIES[-1] if ACTIVE_BUILD_AUTHORITIES else None
        )
        raw = (
            authority.read_bytes(manifest_path)
            if authority is not None
            and active_authority_for_path(manifest_path) is authority
            else authority.read_external_bytes(manifest_path)
            if authority is not None
            else manifest_path.read_bytes()
        )
        manifest = strict_json_loads(raw)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot read manifest {manifest_path}: {error}") from error
    require(isinstance(manifest, dict), "manifest root must be an object")
    exact_keys(
        manifest,
        {
            "schema", "phase", "toolchain", "target_policies",
            "translation_units", "archives", "images", "execution_backends",
            "terminal_producers", "source_overlay", "diagnostic_policy",
        },
        "manifest",
    )
    require(type(manifest.get("schema")) is int
            and manifest.get("schema") == SCHEMA_VERSION,
            "unsupported byte-identity schema")
    require(manifest.get("phase") == PHASE, f"manifest phase must be {PHASE}")
    diagnostic_policy = manifest.get("diagnostic_policy")
    require(
        diagnostic_policy is None
        or diagnostic_policy == NATIVE_DIAGNOSTIC_MANIFEST_POLICY,
        "manifest diagnostic policy is unsupported",
    )
    execution_backend = validate_execution_backends(
        manifest.get("execution_backends")
    )
    source_overlay = validate_source_overlay(
        manifest.get("source_overlay"), source_dir
    )
    source_overlay_by_path = {
        item["logical_path"]: item for item in source_overlay["outputs"]
    }

    toolchain = manifest.get("toolchain")
    toolchain_profile, _legacy_toolchain_profile = (
        select_toolchain_backend_profile(
            toolchain,
            explicit_registry=manifest.get("execution_backends") is not None,
            execution_backend=execution_backend,
        )
    )
    # Backend-specific physical roots are intentionally captured only after
    # the selected transport has been admitted.  A deferred native-Windows
    # profile therefore never resolves Darwin/Homebrew/Wine path tokens.
    host_roots = manifest_host_roots()
    expected_compiler_sha = require_sha(toolchain.get("compiler_sha256"), "compiler_sha256")
    require(toolchain.get("compiler_id") == "MSVC", "only the pinned MSVC toolchain is supported")
    require(toolchain.get("compiler_version") == "10.20", "only MSVC 4.20 is supported")
    expected_python_sha = require_sha(toolchain.get("python_sha256"), "python_sha256")
    expected_python_version = toolchain.get("python_version")
    require(
        isinstance(expected_python_version, str)
        and re.fullmatch(r"[0-9]+[.][0-9]+[.][0-9]+", expected_python_version),
        "python_version must pin an exact three-component version",
    )
    current_python = Path(sys.executable).resolve()
    require(current_python.is_file() and os.access(current_python, os.X_OK),
            "active Python interpreter is not executable")
    require(sha256_file(current_python) == expected_python_sha,
            f"active Python interpreter hash differs: {current_python}")
    current_python_version = ".".join(str(value) for value in sys.version_info[:3])
    require(current_python_version == expected_python_version,
            "active Python interpreter version differs")
    require(toolchain.get("keep_compile_debug") == "/Zi", "byte-identity compiles must retain /Zi")
    timeout = toolchain.get("max_child_seconds")
    require(isinstance(timeout, int) and not isinstance(timeout, bool)
            and 1 <= timeout <= 900, "max_child_seconds is out of range")
    provenance = toolchain.get("provenance")
    require(isinstance(provenance, dict), "toolchain provenance must be an object")
    exact_keys(
        provenance,
        {
            "retail_use",
            "payload_source",
            "forbid_emitted_padding",
            "forbid_opaque_objects",
            "forbid_source_tree_writes",
        },
        "toolchain provenance",
    )
    require(
        exact_json_equal(provenance, {
            "retail_use": "oracle_only_no_payload_copy",
            "payload_source": "configured_compiler_output",
            "forbid_emitted_padding": True,
            "forbid_opaque_objects": True,
            "forbid_source_tree_writes": True,
        }),
        "hard provenance policy changed",
    )

    root_parent_levels = toolchain_profile.get("compiler_root_parent_levels")
    require(isinstance(root_parent_levels, int) and not isinstance(root_parent_levels, bool)
            and 0 <= root_parent_levels <= 6,
            "compiler_root_parent_levels is out of range")
    support_files = toolchain_profile.get("compiler_support_files")
    require(isinstance(support_files, list), "compiler_support_files must be an array")
    normalized_support = []
    support_names = set()
    for support_index, support in enumerate(support_files):
        support_context = f"compiler_support_files[{support_index}]"
        require(isinstance(support, dict), f"{support_context} must be an object")
        exact_keys(support, {"path", "sha256"}, support_context)
        relative = support.get("path")
        require(isinstance(relative, str) and relative, f"{support_context}.path is invalid")
        pure = PurePosixPath(relative)
        require("\\" not in relative and ";" not in relative
                and not pure.is_absolute() and ".." not in pure.parts
                and pure.as_posix() == relative,
                f"{support_context}.path must stay below the compiler root")
        relative = pure.as_posix()
        require(relative not in support_names, f"duplicate compiler support file: {relative}")
        support_names.add(relative)
        normalized_support.append(
            {"path": relative, "sha256": require_sha(support.get("sha256"), f"{support_context}.sha256")}
        )
    producer_support_files = toolchain_profile.get("producer_support_files")
    require(isinstance(producer_support_files, list),
            "producer_support_files must be an array")
    normalized_producer_support = []
    producer_support_names = set()
    for support_index, support in enumerate(producer_support_files):
        context = f"producer_support_files[{support_index}]"
        require(isinstance(support, dict), f"{context} must be an object")
        exact_keys(support, {"path", "sha256", "roles"}, context)
        relative = support.get("path")
        require(isinstance(relative, str) and relative,
                f"{context}.path is invalid")
        pure = PurePosixPath(relative)
        require("\\" not in relative and ";" not in relative
                and not pure.is_absolute() and ".." not in pure.parts
                and pure.as_posix() == relative,
                f"{context}.path must stay below the compiler root")
        require(relative not in producer_support_names,
                f"duplicate producer support file: {relative}")
        producer_support_names.add(relative)
        roles = support.get("roles")
        require(isinstance(roles, list) and roles
                and all(isinstance(role, str) for role in roles)
                and len(roles) == len(set(roles))
                and set(roles) <= PRODUCER_SUPPORT_ROLES
                and roles == sorted(roles),
                f"{context}.roles is not a canonical producer-role set")
        normalized_producer_support.append({
            "path": relative,
            "sha256": require_sha(
                support.get("sha256"), f"{context}.sha256"
            ),
            "roles": roles,
        })
    normalized_producer_support.sort(key=lambda item: item["path"])
    require(not producer_support_names.intersection(support_names),
            "compiler and producer support files overlap")
    required_absent = toolchain_profile.get("required_absent_toolchain_files")
    require(isinstance(required_absent, list)
            and all(isinstance(item, str) and item for item in required_absent),
            "required_absent_toolchain_files must be strings")
    normalized_absent = []
    for absent_index, relative in enumerate(required_absent):
        pure = PurePosixPath(relative)
        require("\\" not in relative and ";" not in relative
                and not pure.is_absolute() and ".." not in pure.parts,
                f"required_absent_toolchain_files[{absent_index}] is unsafe")
        normalized_absent.append(pure.as_posix())
    require(len(set(normalized_absent)) == len(normalized_absent),
            "required_absent_toolchain_files contains duplicates")
    require(not set(normalized_absent).intersection(
                support_names | producer_support_names),
            "toolchain files cannot be both required and absent")

    runtime_executables = toolchain_profile.get("runtime_executables")
    require(isinstance(runtime_executables, list) and runtime_executables,
            "runtime_executables must be a non-empty array")
    normalized_runtimes = []
    runtime_names = set()
    for runtime_index, runtime in enumerate(runtime_executables):
        runtime_context = f"runtime_executables[{runtime_index}]"
        require(isinstance(runtime, dict), f"{runtime_context} must be an object")
        exact_keys(runtime, {"name", "sha256"}, runtime_context)
        name = runtime.get("name")
        require(isinstance(name, str) and TARGET_RE.fullmatch(name) is not None,
                f"{runtime_context}.name is invalid")
        require(name not in runtime_names, f"duplicate runtime executable: {name}")
        runtime_names.add(name)
        normalized_runtimes.append(
            {"name": name, "sha256": require_sha(runtime.get("sha256"), f"{runtime_context}.sha256")}
        )
    require(
        {
            "bash", "dirname", "sed", "grep",
            "wine", "winepath", "wineserver",
        } <= runtime_names,
        "POSIX/Wine runtime executable closure is incomplete",
    )

    sealed_include_trees = toolchain_profile.get("sealed_include_trees")
    require(isinstance(sealed_include_trees, list)
            and len(sealed_include_trees) == 2,
            "sealed_include_trees must pin the MSVC and MFC include roots")
    normalized_include_trees = []
    include_tree_roles = set()
    for tree_index, tree in enumerate(sealed_include_trees):
        tree_context = f"sealed_include_trees[{tree_index}]"
        require(isinstance(tree, dict), f"{tree_context} must be an object")
        exact_audit_keys(
            tree,
            {"role", "path", "entry_count", "max_depth",
             "membership_sha256", "content_sha256"},
            tree_context,
        )
        role = tree.get("role")
        require(role in ("msvc_include", "mfc_include")
                and role not in include_tree_roles,
                f"{tree_context}.role is invalid or duplicated")
        include_tree_roles.add(role)
        relative = tree.get("path")
        require(isinstance(relative, str) and relative,
                f"{tree_context}.path is invalid")
        pure = PurePosixPath(relative)
        require(not pure.is_absolute() and ".." not in pure.parts
                and "\\" not in relative and ";" not in relative,
                f"{tree_context}.path must stay below the compiler root")
        entry_count = tree.get("entry_count")
        maximum_depth = tree.get("max_depth")
        require(type(entry_count) is int and 1 <= entry_count <= 20000,
                f"{tree_context}.entry_count is invalid")
        require(type(maximum_depth) is int and 0 <= maximum_depth <= 32,
                f"{tree_context}.max_depth is invalid")
        normalized_include_trees.append({
            "role": role,
            "path": pure.as_posix(),
            "entry_count": entry_count,
            "max_depth": maximum_depth,
            "membership_sha256": require_sha(
                tree.get("membership_sha256"), f"{tree_context}.membership_sha256"
            ),
            "content_sha256": require_sha(
                tree.get("content_sha256"), f"{tree_context}.content_sha256"
            ),
        })
    require(include_tree_roles == {"msvc_include", "mfc_include"},
            "sealed include tree roles are incomplete")

    runtime_closure = toolchain_profile.get("runtime_closure")
    require(isinstance(runtime_closure, dict), "runtime_closure must be an object")
    exact_audit_keys(
        runtime_closure,
        {
            "schema", "membership_roots", "loaded_files",
            "host_identity", "system_imports", "resolution_policy",
        },
        "runtime_closure",
    )
    require(runtime_closure.get("schema") == "wine_runtime_closure_v1"
            and runtime_closure.get("resolution_policy")
            == "casefold_unique_first_match_v1",
            "runtime_closure schema/resolution policy differs")
    runtime_roots = runtime_closure.get("membership_roots")
    require(isinstance(runtime_roots, list) and runtime_roots,
            "runtime_closure.membership_roots must be non-empty")
    normalized_runtime_roots = []
    runtime_root_roles = set()
    for root_index, root_pin in enumerate(runtime_roots):
        root_context = f"runtime_closure.membership_roots[{root_index}]"
        require(isinstance(root_pin, dict), f"{root_context} must be an object")
        exact_audit_keys(
            root_pin,
            {
                "role", "path", "entry_count", "max_depth",
                "membership_sha256", "content_sha256",
            },
            root_context,
        )
        role = root_pin.get("role")
        path_value = root_pin.get("path")
        require(isinstance(role, str) and TARGET_RE.fullmatch(role) is not None
                and role not in runtime_root_roles,
                f"{root_context}.role is invalid or duplicated")
        runtime_root_roles.add(role)
        root_path = manifest_host_path(path_value, f"{root_context}.path", host_roots)
        entry_count = root_pin.get("entry_count")
        maximum_depth = root_pin.get("max_depth")
        require(type(entry_count) is int and 1 <= entry_count <= 20000,
                f"{root_context}.entry_count is invalid")
        require(type(maximum_depth) is int and 0 <= maximum_depth <= 32,
                f"{root_context}.max_depth is invalid")
        normalized_runtime_roots.append({
            "role": role, "path": str(root_path),
            "entry_count": entry_count, "max_depth": maximum_depth,
            "membership_sha256": require_sha(
                root_pin.get("membership_sha256"),
                f"{root_context}.membership_sha256",
            ),
            "content_sha256": require_sha(
                root_pin.get("content_sha256"),
                f"{root_context}.content_sha256",
            ),
        })
    runtime_loaded = runtime_closure.get("loaded_files")
    require(isinstance(runtime_loaded, list) and runtime_loaded,
            "runtime_closure.loaded_files must be non-empty")
    normalized_runtime_loaded = []
    loaded_roles = set()
    loaded_paths = set()
    for loaded_index, loaded in enumerate(runtime_loaded):
        loaded_context = f"runtime_closure.loaded_files[{loaded_index}]"
        require(isinstance(loaded, dict), f"{loaded_context} must be an object")
        exact_audit_keys(loaded, {"role", "path", "sha256"}, loaded_context)
        role = loaded.get("role")
        path_value = loaded.get("path")
        require(isinstance(role, str) and TARGET_RE.fullmatch(role) is not None
                and role not in loaded_roles,
                f"{loaded_context}.role is invalid or duplicated")
        loaded_roles.add(role)
        loaded_path = manifest_host_path(
            path_value, f"{loaded_context}.path", host_roots
        )
        canonical_loaded = str(loaded_path.resolve(strict=True))
        require(canonical_loaded not in loaded_paths,
                f"{loaded_context}.path is duplicated")
        loaded_paths.add(canonical_loaded)
        normalized_runtime_loaded.append({
            "role": role, "path": canonical_loaded,
            "sha256": require_sha(loaded.get("sha256"), f"{loaded_context}.sha256"),
        })
    host_identity = runtime_closure.get("host_identity")
    require(isinstance(host_identity, dict),
            "runtime_closure.host_identity must be an object")
    expected_host_identity = current_host_runtime_identity()
    exact_audit_keys(
        host_identity, set(expected_host_identity),
        "runtime_closure.host_identity",
    )
    require(exact_json_equal(host_identity, expected_host_identity),
            "runtime_closure host/dyld identity differs")
    system_imports = runtime_closure.get("system_imports")
    require(exact_json_equal(system_imports, EXPECTED_DYLD_IMPORT_IDENTITIES),
            "runtime_closure dyld-cache import identities differ")
    normalized_runtime_closure = {
        "schema": "wine_runtime_closure_v1",
        "membership_roots": normalized_runtime_roots,
        "loaded_files": normalized_runtime_loaded,
        "host_identity": expected_host_identity,
        "system_imports": list(EXPECTED_DYLD_IMPORT_IDENTITIES),
        "resolution_policy": "casefold_unique_first_match_v1",
    }

    transport = toolchain_profile.get("transport")
    require(isinstance(transport, dict), "toolchain.transport must be an object")
    exact_audit_keys(
        transport,
        {
            "schema", "copy_policy", "runtime_snapshot_policy",
            "prefix_template_files", "prefix_directories", "dosdevices",
            "server_shutdown", "msvc_environment",
        },
        "toolchain.transport",
    )
    require(
        transport.get("schema") == "wine_virtual_z_v1"
        and transport.get("copy_policy")
        == "independent_regular_files_no_hardlinks_v1"
        and transport.get("runtime_snapshot_policy")
        == "selected_loaded_closure_with_full_root_content_merkle_v1"
        and transport.get("server_shutdown")
        == "prefix_scoped_kill_wait_bounded_v1"
        and exact_json_equal(transport.get("dosdevices"), ["c:", "z:"]),
        "toolchain.transport policy differs",
    )
    prefix_files = transport.get("prefix_template_files")
    require(isinstance(prefix_files, list) and prefix_files,
            "toolchain.transport.prefix_template_files must be non-empty")
    normalized_prefix_files = []
    prefix_names = set()
    for index, item in enumerate(prefix_files):
        context = f"toolchain.transport.prefix_template_files[{index}]"
        require(isinstance(item, dict), f"{context} must be an object")
        exact_audit_keys(item, {"name", "path", "sha256", "mode"}, context)
        name = item.get("name")
        path_value = item.get("path")
        require(isinstance(name, str) and name
                and PurePosixPath(name).name == name
                and name not in prefix_names,
                f"{context}.name is invalid or duplicated")
        prefix_names.add(name)
        prefix_path = manifest_host_path(
            path_value, f"{context}.path", host_roots
        )
        mode = require_exact_int(item.get("mode"), f"{context}.mode",
                                 minimum=0, maximum=0o777)
        require(mode == 0o444,
                f"{context}.mode must be the immutable 0444 template mode")
        normalized_prefix_files.append({
            "name": name,
            "path": str(prefix_path),
            "sha256": require_sha(item.get("sha256"), f"{context}.sha256"),
            "mode": mode,
        })
    require(prefix_names == {
                ".update-timestamp", "system.reg", "user.reg", "userdef.reg"
            }, "Wine prefix template file set differs")
    prefix_template_root = validate_wine_prefix_template(
        normalized_prefix_files
    )
    prefix_directories = transport.get("prefix_directories")
    require(isinstance(prefix_directories, list) and prefix_directories,
            "toolchain.transport.prefix_directories must be non-empty")
    normalized_prefix_directories = []
    for index, value in enumerate(prefix_directories):
        context = f"toolchain.transport.prefix_directories[{index}]"
        require(isinstance(value, str) and value and "\\" not in value,
                f"{context} is invalid")
        pure = PurePosixPath(value)
        require(not pure.is_absolute() and ".." not in pure.parts
                and pure.as_posix() == value,
                f"{context} escapes the prefix")
        normalized_prefix_directories.append(value)
    require(len(normalized_prefix_directories)
            == len(set(normalized_prefix_directories))
            and "drive_c" in normalized_prefix_directories,
            "Wine prefix directory set is duplicated or incomplete")
    msvc_environment = transport.get("msvc_environment")
    require(isinstance(msvc_environment, dict),
            "toolchain.transport.msvc_environment must be an object")
    exact_audit_keys(
        msvc_environment,
        {
            "include_order", "winepath_order", "winedlloverrides",
            "root_transform", "wrapper_invocation_transform",
            "argument_path_transform",
        },
        "toolchain.transport.msvc_environment",
    )
    root_transform = msvc_environment.get("root_transform")
    require(isinstance(root_transform, dict),
            "toolchain.transport.msvc_environment.root_transform must be an object")
    exact_audit_keys(
        root_transform, {"schema", "script"},
        "toolchain.transport.msvc_environment.root_transform",
    )
    root_transform_script = root_transform.get("script")
    require(
        root_transform.get("schema")
        == MSVC_ENVIRONMENT_ROOT_TRANSFORM_SCHEMA
        and root_transform_script == "wine/x86/msvcenv.sh"
        and root_transform_script in support_names,
        "toolchain.transport MSVC root transform differs",
    )
    wrapper_transform = msvc_environment.get("wrapper_invocation_transform")
    require(isinstance(wrapper_transform, dict),
            "toolchain.transport MSVC wrapper transform must be an object")
    exact_audit_keys(
        wrapper_transform, {"schema", "scripts"},
        "toolchain.transport.msvc_environment.wrapper_invocation_transform",
    )
    wrapper_transform_scripts = wrapper_transform.get("scripts")
    require(
        wrapper_transform.get("schema")
        == MSVC_WRAPPER_INVOCATION_TRANSFORM_SCHEMA
        and exact_json_equal(
            wrapper_transform_scripts, list(MSVC_WRAPPER_TRANSFORM_SCRIPTS)
        ),
        "toolchain.transport MSVC wrapper invocation transform differs",
    )
    argument_transform = msvc_environment.get("argument_path_transform")
    require(isinstance(argument_transform, dict),
            "toolchain.transport MSVC argument transform must be an object")
    exact_audit_keys(
        argument_transform, {"schema", "script"},
        "toolchain.transport.msvc_environment.argument_path_transform",
    )
    require(
        argument_transform.get("schema")
        == MSVC_WINE_ARGUMENT_TRANSFORM_SCHEMA
        and argument_transform.get("script") == "wine/x86/wine-msvc.sh"
        and argument_transform.get("script") in support_names,
        "toolchain.transport MSVC argument transform differs",
    )
    include_order = msvc_environment.get("include_order")
    require(isinstance(include_order, list) and len(include_order) == 2
            and len(set(include_order)) == 2
            and all(
                isinstance(value, str) and value
                and not PurePosixPath(value).is_absolute()
                and ".." not in PurePosixPath(value).parts
                and PurePosixPath(value).as_posix() == value
                for value in include_order
            ) and exact_json_equal(
                msvc_environment.get("winepath_order"),
                ["bin", "bin/winnt"],
            )
            and msvc_environment.get("winedlloverrides")
            == "msvcrt40=n;msvcrt20=n",
            "toolchain.transport MSVC wrapper environment differs")
    normalized_transport = {
        "schema": "wine_virtual_z_v1",
        "copy_policy": "independent_regular_files_no_hardlinks_v1",
        "runtime_snapshot_policy":
            "selected_loaded_closure_with_full_root_content_merkle_v1",
        "prefix_template_files": normalized_prefix_files,
        "prefix_template_root": prefix_template_root,
        "prefix_directories": normalized_prefix_directories,
        "dosdevices": ["c:", "z:"],
        "server_shutdown": "prefix_scoped_kill_wait_bounded_v1",
        "msvc_environment": msvc_environment,
    }

    child_environment = toolchain_profile.get("child_environment")
    require(exact_json_equal(child_environment, CHILD_ENVIRONMENT_POLICY),
            "child_environment must match the strict compiler allowlist policy")
    toolchain_fingerprint = sha256_bytes(
        json.dumps(
            {
                "compiler_sha256": expected_compiler_sha,
                "python_sha256": expected_python_sha,
                "python_version": expected_python_version,
                "root_parent_levels": root_parent_levels,
                "support_files": normalized_support,
                "producer_support_files": normalized_producer_support,
                "required_absent": normalized_absent,
                "runtime_executables": normalized_runtimes,
                "sealed_include_trees": normalized_include_trees,
                "runtime_closure": normalized_runtime_closure,
                "transport": normalized_transport,
                "child_environment": CHILD_ENVIRONMENT_POLICY,
                "transport_backend": {
                    "backend": execution_backend["id"],
                    "schema": toolchain_profile["transport_schema"],
                },
                "execution_backend": execution_backend,
            },
            sort_keys=True,
            separators=(",", ":"),
        ).encode("utf-8")
    )
    compiler_root = None
    if configured_compiler is not None:
        configured = compiler_path(configured_compiler)
        require(sha256_file(configured) == expected_compiler_sha,
                f"configured compiler hash differs: {configured}")
        compiler_root = configured.parent
        for _ in range(root_parent_levels):
            compiler_root = compiler_root.parent
        for support in normalized_support:
            _, support_path = declared_toolchain_path(
                compiler_root, support["path"], f"compiler support file {support['path']}"
            )
            require(support_path.is_file(), f"compiler support file is absent: {support['path']}")
            require(sha256_file(support_path) == support["sha256"],
                    f"compiler support file hash differs: {support['path']}")
            support["absolute_path"] = str(support_path)
        for support in normalized_producer_support:
            _, support_path = declared_toolchain_path(
                compiler_root, support["path"],
                f"producer support file {support['path']}",
            )
            require(support_path.is_file(),
                    f"producer support file is absent: {support['path']}")
            require(sha256_file(support_path) == support["sha256"],
                    f"producer support file hash differs: {support['path']}")
            support["absolute_path"] = str(support_path)
        for relative in normalized_absent:
            _, absent_path = declared_toolchain_path(
                compiler_root, relative, f"required absent toolchain file {relative}"
            )
            if ACTIVE_BUILD_AUTHORITIES:
                ACTIVE_BUILD_AUTHORITIES[-1].require_external_absent(absent_path)
            else:
                require(not absent_path.exists() and not absent_path.is_symlink(),
                        f"toolchain file must remain absent: {relative}")
        for runtime in normalized_runtimes:
            located = shutil.which(runtime["name"])
            require(located is not None,
                    f"runtime executable is absent from PATH: {runtime['name']}")
            located_path = Path(located).resolve()
            require(sha256_file(located_path) == runtime["sha256"],
                    f"runtime executable hash differs: {runtime['name']}")
            runtime["absolute_path"] = str(located_path)
            metadata = located_path.stat(follow_symlinks=False)
            runtime["materialization"] = (
                "system_direct_immutable_v1"
                if (
                    str(located_path).startswith(("/bin/", "/usr/bin/"))
                    and located_path.resolve(strict=True) == located_path
                    and not located_path.is_symlink()
                    and metadata.st_uid == 0
                    and stat.S_ISREG(metadata.st_mode)
                    and not (stat.S_IMODE(metadata.st_mode) & 0o022)
                )
                else "private_snapshot_copy_v1"
            )
        for tree in normalized_include_trees:
            _, tree_path = declared_toolchain_path(
                compiler_root, tree["path"], f"sealed include tree {tree['role']}"
            )
            snapshot = canonical_tree_snapshot(
                tree_path, hash_files=True,
                max_entries=tree["entry_count"], max_depth=tree["max_depth"],
            )
            require(snapshot["entry_count"] == tree["entry_count"]
                    and snapshot["max_depth"] == tree["max_depth"]
                    and snapshot["membership_sha256"] == tree["membership_sha256"]
                    and snapshot["content_sha256"] == tree["content_sha256"],
                    f"sealed include tree differs: {tree['role']}")
            tree["absolute_path"] = str(tree_path)
            tree["metadata_sha256"] = snapshot["metadata_sha256"]
        # The resident materializes and validates the complete Wine membership
        # once. Common compiler/RC/LIB/LINK manifest revalidation must not
        # reread this ~843 MiB host closure for every producer role.
        for prefix_file in normalized_prefix_files:
            prefix_path = Path(prefix_file["path"])
            require(prefix_path.is_file()
                    and not prefix_path.is_symlink()
                    and stat.S_IMODE(prefix_path.stat().st_mode)
                    == prefix_file["mode"]
                    and sha256_file(prefix_path) == prefix_file["sha256"],
                    f"Wine prefix template file differs: {prefix_file['name']}")
        expected_include_order = [
            str(Path(tree["absolute_path"]))
            for tree in normalized_include_trees
        ]
        expected_winepath = [
            str(compiler_root / "bin"), str(compiler_root / "bin/winnt")
        ]
        require(
            exact_json_equal(
                [str(compiler_root / value)
                 for value in msvc_environment["include_order"]],
                expected_include_order,
            ) and exact_json_equal(
                [str(compiler_root / value)
                 for value in msvc_environment["winepath_order"]],
                expected_winepath,
            ),
            "pinned MSVC wrapper search environment differs from compiler root",
        )
        normalized_transport["msvc_environment"] = {
            **msvc_environment,
            "include_order": expected_include_order,
            "winepath_order": expected_winepath,
        }
    if compiler_id is not None:
        require(compiler_id == toolchain["compiler_id"], "configured compiler ID differs")
    if compiler_version is not None:
        require(compiler_version == toolchain["compiler_version"], "configured compiler version differs")
    if generator is not None:
        require(generator in SUPPORTED_GENERATORS, f"unsupported CMake generator: {generator}")

    target_policies = manifest.get("target_policies")
    require(isinstance(target_policies, list) and target_policies,
            "target_policies must be a non-empty array")
    normalized_target_policies = []
    target_policy_by_name = {}
    for policy_index, policy in enumerate(target_policies):
        policy_context = f"target_policies[{policy_index}]"
        require(isinstance(policy, dict), f"{policy_context} must be an object")
        exact_keys(policy, {"target", "allowed_force_includes"}, policy_context)
        target = policy.get("target")
        require(isinstance(target, str) and TARGET_RE.fullmatch(target) is not None,
                f"{policy_context}.target is invalid")
        require(target not in target_policy_by_name,
                f"duplicate target policy: {target}")
        allowed_force_includes = policy.get("allowed_force_includes")
        require(isinstance(allowed_force_includes, list),
                f"{policy_context}.allowed_force_includes must be an array")
        normalized_force_includes = []
        seen_force_includes = set()
        for include_index, include in enumerate(allowed_force_includes):
            include_context = (
                f"{policy_context}.allowed_force_includes[{include_index}]"
            )
            require(isinstance(include, dict), f"{include_context} must be an object")
            exact_keys(include, {"path", "sha256"}, include_context)
            include_relative = source_overlay_relative_path(
                include.get("path"), f"{include_context}.path"
            )
            include_path = source_overlay_logical_path(
                source_dir, include_relative
            )
            include_sha = require_sha(
                include.get("sha256"), f"{include_context}.sha256"
            )
            require(include_relative not in seen_force_includes,
                    f"duplicate force-include in {policy_context}: {include_relative}")
            seen_force_includes.add(include_relative)
            overlay_output = source_overlay_by_path.get(include_relative)
            effective_include_sha = include_sha
            if overlay_output is None:
                require(include_path.is_file()
                        and sha256_file(include_path) == include_sha,
                        f"force-include hash differs: {include_relative}")
            else:
                require(
                    overlay_output["effective"]["baseline_sha256"] == include_sha,
                    f"overlay force-include baseline hash differs: {include_relative}",
                )
                effective_include_sha = source_overlay[
                    "effective_by_path"
                ][include_relative]["sha256"]
            normalized_force_includes.append(
                {
                    "path": include_relative,
                    "absolute_path": str(include_path),
                    "sha256": effective_include_sha,
                }
            )
        normalized_policy = {
            "target": target,
            "allowed_force_includes": normalized_force_includes,
        }
        normalized_target_policies.append(normalized_policy)
        target_policy_by_name[target] = normalized_policy

    translation_units = manifest.get("translation_units")
    require(isinstance(translation_units, list) and translation_units,
            "translation_units must be a non-empty array")
    normalized_units = []
    owners = set()
    recipe_registry = {}
    recipe_order = []
    retail_identities = set()
    for unit_index, unit in enumerate(translation_units):
        context = f"translation_units[{unit_index}]"
        require(isinstance(unit, dict), f"{context} must be an object")
        exact_audit_keys(
            unit,
            {
                "target", "source", "source_sha256", "mode", "command_policy",
                "donors", "functions", "completion",
            },
            context,
        )
        target = unit.get("target")
        require(isinstance(target, str) and TARGET_RE.fullmatch(target) is not None,
                f"{context}.target is invalid")
        require(target in target_policy_by_name,
                f"{context}.target has no build-wide target policy")
        source_relative = source_overlay_relative_path(
            unit.get("source"), f"{context}.source"
        )
        source_path = source_overlay_logical_path(source_dir, source_relative)
        source_sha = require_sha(unit.get("source_sha256"), f"{context}.source_sha256")
        overlay_output = source_overlay_by_path.get(source_relative)
        effective_source_sha = source_sha
        if overlay_output is None:
            require(source_path.is_file() and sha256_file(source_path) == source_sha,
                    f"source hash differs: {source_relative}")
        else:
            require(overlay_output["effective"]["baseline_sha256"] == source_sha,
                    f"overlay source baseline hash differs: {source_relative}")
            effective_source_sha = source_overlay[
                "effective_by_path"
            ][source_relative]["sha256"]
        owner = (target, source_relative)
        require(owner not in owners, f"duplicate translation-unit owner: {owner}")
        owners.add(owner)
        mode = unit.get("mode")
        require(
            mode == "compose_equal_linked_span_fpo"
            or (
                mode == "pass_through"
                and diagnostic_policy == NATIVE_DIAGNOSTIC_MANIFEST_POLICY
            ),
            f"{context}.mode is unsupported outside a non-authoritative "
            "native diagnostic manifest",
        )

        command_policy = unit.get("command_policy")
        require(isinstance(command_policy, dict), f"{context}.command_policy must be an object")
        exact_audit_keys(
            command_policy,
            {"required_flags", "forbidden_prefixes"},
            f"{context}.command_policy",
        )
        required_flags = command_policy.get("required_flags")
        forbidden_prefixes = command_policy.get("forbidden_prefixes")
        require(isinstance(required_flags, list)
                and all(isinstance(item, str) for item in required_flags),
                f"{context}.required_flags must be strings")
        require(isinstance(forbidden_prefixes, list)
                and all(isinstance(item, str) for item in forbidden_prefixes),
                f"{context}.forbidden_prefixes must be strings")
        require(any(item in required_flags for item in ("/Zi", "-Zi"))
                and any(item in required_flags for item in ("/c", "-c")),
                f"{context} must require /Zi and a compile-only flag")
        folded_forbidden = {item.casefold() for item in forbidden_prefixes}
        require({"/gl", "-gl", "/z7", "-z7"}.issubset(folded_forbidden),
                f"{context} must forbid alternate code/debug modes")
        donors = unit.get("donors")
        require(isinstance(donors, list) and donors,
                f"{context}.donors must be a non-empty array")
        normalized_donors = []
        local_recipe_ids = set()
        for donor_index, donor in enumerate(donors):
            donor_context = f"{context}.donors[{donor_index}]"
            require(isinstance(donor, dict), f"{donor_context} must be an object")
            exact_keys(
                donor, {"id", "status", "authenticity", "recipe"},
                donor_context,
            )
            recipe_id = donor.get("id")
            require(isinstance(recipe_id, str) and RECIPE_ID_RE.fullmatch(recipe_id) is not None,
                    f"{donor_context}.id is invalid")
            require(recipe_id not in local_recipe_ids,
                    f"{donor_context}.id is duplicated within this TU")
            local_recipe_ids.add(recipe_id)
            expected_status = (
                "compiler_generated_current_source"
                if mode == "compose_equal_linked_span_fpo"
                else "planned_not_composed"
            )
            require(donor.get("status") == expected_status,
                    f"{donor_context}.status must be {expected_status}")
            require(
                donor.get("authenticity") == "synthetic_baseline_only",
                f"{donor_context}.authenticity must be synthetic_baseline_only",
            )
            recipe = donor.get("recipe")
            require(isinstance(recipe, dict), f"{donor_context}.recipe must be an object")
            kind = recipe.get("kind")
            require(
                kind == "declaration_shape",
                f"{donor_context}: donors require declaration_shape",
            )
            exact_keys(
                recipe,
                {
                    "kind", "classes", "functions", "generated_header_sha256",
                    "emission_policy", "authenticity_rationale",
                },
                f"{donor_context}.recipe",
            )
            classes = recipe.get("classes")
            functions = recipe.get("functions")
            require(isinstance(classes, int) and not isinstance(classes, bool)
                    and 1 <= classes <= 10,
                    f"{donor_context}.classes is invalid")
            require(isinstance(functions, int) and not isinstance(functions, bool)
                    and classes <= functions <= 10 * classes,
                    f"{donor_context}.functions is invalid")
            generated = entropy_generator.generate_shape(
                classes, functions
            ).encode("utf-8")
            required_prefix = "d_"
            serialized_recipe = json.dumps(recipe, sort_keys=True).casefold()
            require(not any(word in serialized_recipe for word in FORBIDDEN_RECIPE_WORDS),
                    f"{donor_context} contains forbidden provenance")
            header_sha = require_sha(
                recipe.get("generated_header_sha256"),
                f"{donor_context}.generated_header_sha256",
            )
            require(recipe_id == f"{required_prefix}{header_sha[:12]}",
                    f"{donor_context}.id is not the header content ID")
            require(sha256_bytes(generated) == header_sha,
                    f"{donor_context}: declaration generator/hash drift")
            require(recipe.get("emission_policy") == "non_emitting_declarations_only",
                    f"{donor_context}: recipe must be non-emitting declarations")
            rationale = recipe.get("authenticity_rationale")
            require(isinstance(rationale, str) and len(rationale) >= 32,
                    f"{donor_context}: authenticity rationale is too weak")
            header_output = str(recipe_output(build_dir, recipe_id, header_sha))
            existing_recipe = recipe_registry.get(recipe_id)
            if existing_recipe is None:
                recipe_registry[recipe_id] = {
                    "id": recipe_id,
                    "recipe": recipe,
                    "header_output": header_output,
                    "users": [],
                }
                recipe_order.append(recipe_id)
            else:
                require(existing_recipe["recipe"] == recipe
                        and existing_recipe["header_output"] == header_output,
                        f"duplicate recipe definition differs: {recipe_id}")
            normalized_donors.append(
                {
                    **donor,
                    "header_output": header_output,
                }
            )

        functions = unit.get("functions")
        require(isinstance(functions, list), f"{context}.functions must be an array")
        normalized_functions = []
        seen_functions = set()
        seen_section_numbers = set()
        function_recipe_ids = set()
        allowed_function_keys = {
            "mangled", "donor", "splice_class", "expected_section_number",
            "expected_seed_length", "expected_donor_length", "expected_linked_span",
            "expected_characteristics", "expected_selection", "expected_relocation_count",
            "expected_seed_line_count", "expected_donor_line_count",
            "expected_local_symbol_updates", "compiler_output_body_sha256",
            "expected_donor_fpo", "retail_oracle",
        }
        for function_index, function in enumerate(functions):
            function_context = f"{context}.functions[{function_index}]"
            require(isinstance(function, dict), f"{function_context} must be an object")
            exact_keys(function, allowed_function_keys, function_context)
            mangled = function.get("mangled")
            require(isinstance(mangled, str) and mangled.startswith("?") and len(mangled) >= 8,
                    f"{function_context}.mangled is invalid")
            require(mangled not in seen_functions,
                    f"{function_context}.mangled is duplicated")
            seen_functions.add(mangled)
            donor_id = function.get("donor")
            require(donor_id in local_recipe_ids,
                    f"{function_context}.donor is not declared by this TU")
            function_recipe_ids.add(donor_id)
            require(function.get("splice_class") == "equal_linked_span_fpo",
                    f"{function_context}: unsupported splice class")
            for name in (
                "expected_section_number", "expected_seed_length", "expected_donor_length",
                "expected_linked_span", "expected_characteristics", "expected_selection",
                "expected_relocation_count", "expected_seed_line_count",
                "expected_donor_line_count", "expected_local_symbol_updates",
            ):
                value = function.get(name)
                require(isinstance(value, int) and not isinstance(value, bool) and value >= 0,
                        f"{function_context}.{name} is invalid")
            require(function["expected_section_number"] > 0,
                    f"{function_context}.expected_section_number is invalid")
            require(function["expected_section_number"] not in seen_section_numbers,
                    f"{function_context}.expected_section_number is duplicated within this TU")
            seen_section_numbers.add(function["expected_section_number"])
            require(function["expected_seed_length"] > 0
                    and function["expected_donor_length"] > 0,
                    f"{function_context}: zero-length functions are unsupported")
            require(function["expected_linked_span"] > 0
                    and function["expected_linked_span"] % 16 == 0,
                    f"{function_context}.expected_linked_span is invalid")
            require(((function["expected_seed_length"] + 15) // 16) * 16
                    == function["expected_linked_span"]
                    == ((function["expected_donor_length"] + 15) // 16) * 16,
                    f"{function_context}: declared linked spans are not equal")
            require(function["expected_selection"] == 2,
                    f"{function_context}: only select-any FPO COMDATs are supported")
            require_sha(function.get("compiler_output_body_sha256"),
                        f"{function_context}.compiler_output_body_sha256")
            expected_donor_fpo = validate_manifest_fpo_record(
                function.get("expected_donor_fpo"),
                f"{function_context}.expected_donor_fpo",
            )
            require(expected_donor_fpo["cbProcSize"]
                    == function["expected_donor_length"],
                    f"{function_context}.expected_donor_fpo size differs")
            retail = function.get("retail_oracle")
            require(isinstance(retail, dict), f"{function_context}.retail_oracle must be an object")
            exact_keys(retail, {"image", "address", "verdict", "length"},
                       f"{function_context}.retail_oracle")
            require(retail.get("image") in ("LEGO1.DLL", "ISLE.EXE"),
                    f"{function_context}.retail_oracle.image is invalid")
            require(isinstance(retail.get("address"), str)
                    and ADDRESS_RE.fullmatch(retail["address"]) is not None,
                    f"{function_context}.retail_oracle.address is invalid")
            retail_identity = (retail.get("image"), retail.get("address"))
            require(retail_identity not in retail_identities,
                    f"{function_context}.retail_oracle identity/address is duplicated")
            retail_identities.add(retail_identity)
            require(retail.get("verdict") == "MATCH"
                    and type(retail.get("length")) is int
                    and retail.get("length") == function["expected_donor_length"],
                    f"{function_context}: retail oracle is not a pinned exact-length match")
            normalized_functions.append({
                **function, "expected_donor_fpo": expected_donor_fpo,
            })

        if mode == "pass_through":
            require(not functions, f"{context}: pass_through cannot request functions")
        else:
            require(functions, f"{context}: composer mode requires functions")
            require(function_recipe_ids == local_recipe_ids,
                    f"{context}: every compiler donor must own at least one function")

        completion = unit.get("completion")
        require(isinstance(completion, dict), f"{context}.completion must be an object")
        exact_keys(completion, {"state", "reason", "may_replace_compiler_output"},
                   f"{context}.completion")
        expected_completion = (
            "object_composition_enabled_final_gates_incomplete"
            if mode == "compose_equal_linked_span_fpo"
            else "planned_not_composed"
        )
        require(completion.get("state") == expected_completion,
                f"{context}.completion.state must be {expected_completion}")
        require(completion.get("may_replace_compiler_output")
                is (mode == "compose_equal_linked_span_fpo"),
                f"{context}.completion replacement policy is invalid")
        require(isinstance(completion.get("reason"), str) and len(completion["reason"]) >= 24,
                f"{context}.completion.reason is too weak")

        normalized_units.append(
            {
                **unit,
                "source": source_relative,
                "source_path": str(source_path),
                "source_sha256": effective_source_sha,
                "command_policy": {
                    **command_policy,
                    "allowed_force_includes": target_policy_by_name[target][
                        "allowed_force_includes"
                    ],
                },
                "donors": normalized_donors,
                "functions": normalized_functions,
            }
        )
        for donor in normalized_donors:
            recipe_registry[donor["id"]]["users"].append(
                {
                    "target": target,
                    "source": source_relative,
                    "mode": mode,
                    "completion": completion["state"],
                }
            )

    archives = manifest.get("archives")
    require(isinstance(archives, list), "archives must be an array")
    normalized_archives = []
    archive_identities = set()
    for archive_index, archive in enumerate(archives):
        context = f"archives[{archive_index}]"
        require(isinstance(archive, dict), f"{context} must be an object")
        exact_audit_keys(
            archive,
            {
                "kind", "identity", "source", "source_sha256",
                "payload_policy", "imported_target", "link_contract",
                "completion",
            },
            context,
        )
        require(
            archive.get("kind") == "third_party_reconstructed_archive",
            f"{context}.kind is not the narrow third-party archive exception",
        )
        identity = archive.get("identity")
        require(
            identity in THIRD_PARTY_RETAIL_ARCHIVES
            and identity not in archive_identities,
            f"{context}.identity is unsupported or duplicated",
        )
        archive_identities.add(identity)
        expected_relative = THIRD_PARTY_RETAIL_ARCHIVES[identity]
        require(
            archive.get("source") == expected_relative,
            f"{context}.source is not the exact {identity} archive seat",
        )
        source_path = source_root.joinpath(*PurePosixPath(expected_relative).parts)
        try:
            source_canonical = source_path.resolve(strict=True)
        except OSError as error:
            raise ByteIdentityError(
                f"{context}.source cannot be resolved: {error}"
            ) from error
        require(
            lexical_absolute_path(source_path) == source_canonical
            and source_canonical.is_file(),
            f"{context}.source is absent or redirected",
        )
        source_sha = require_sha(
            archive.get("source_sha256"), f"{context}.source_sha256"
        )
        source_bytes = (
            active_build_authority().read_external_bytes(source_path)
            if ACTIVE_BUILD_AUTHORITIES else source_path.read_bytes()
        )
        require(
            source_bytes.startswith(b"!<arch>\n")
            and sha256_bytes(source_bytes) == source_sha,
            f"{context}.source archive bytes differ from their pin",
        )
        require(
            archive.get("payload_policy") == THIRD_PARTY_RETAIL_ARCHIVE_POLICY,
            f"{context}.payload_policy is not the exact named exception",
        )
        imported_target = archive.get("imported_target")
        expected_imported_target = f"{identity}::{identity}"
        require(
            imported_target == expected_imported_target,
            f"{context}.imported_target must be {expected_imported_target}",
        )
        link_contract = archive.get("link_contract")
        require(
            isinstance(link_contract, list) and link_contract,
            f"{context}.link_contract must be a non-empty array",
        )
        normalized_link_contract = []
        contract_targets = set()
        for contract_index, contract in enumerate(link_contract):
            contract_context = f"{context}.link_contract[{contract_index}]"
            require(isinstance(contract, dict),
                    f"{contract_context} must be an object")
            exact_audit_keys(
                contract,
                {"target", "direct_link_sequence", "occurrences"},
                contract_context,
            )
            target = contract.get("target")
            sequence = contract.get("direct_link_sequence")
            occurrences = contract.get("occurrences")
            require(
                isinstance(target, str)
                and TARGET_RE.fullmatch(target) is not None
                and target not in contract_targets,
                f"{contract_context}.target is invalid or duplicated",
            )
            contract_targets.add(target)
            require(
                isinstance(sequence, list)
                and len(sequence) >= 2
                and all(isinstance(token, str) and token for token in sequence)
                and imported_target in sequence,
                f"{contract_context}.direct_link_sequence is invalid",
            )
            require_exact_int(
                occurrences,
                f"{contract_context}.occurrences",
                minimum=1,
            )
            normalized_link_contract.append({
                "target": target,
                "direct_link_sequence": sequence,
                "occurrences": occurrences,
            })
        completion = archive.get("completion")
        require(isinstance(completion, dict), f"{context}.completion must be an object")
        exact_audit_keys(
            completion,
            {"state", "reason", "may_supply_linker_payload"},
            f"{context}.completion",
        )
        require(
            completion.get("state")
            == "authorized_exact_archive_materialization_enabled"
            and completion.get("may_supply_linker_payload") is True
            and isinstance(completion.get("reason"), str)
            and len(completion["reason"]) >= 24,
            f"{context}.completion must authorize only exact materialization",
        )
        output = archive_output(build_root, identity, expected_relative)
        normalized_archives.append({
            **archive,
            "source_path": str(source_path),
            "source_size": len(source_bytes),
            "output": str(output),
            "audit": str(archive_audit_path(build_root, identity)),
            "link_contract": normalized_link_contract,
        })
    images = manifest.get("images")
    require(isinstance(images, dict), "images must be an object")
    require(set(images) <= {"LEGO1"}, "images contains an unsupported identity")
    normalized_images = []
    for identity, image in images.items():
        context = f"images.{identity}"
        require(identity == "LEGO1" and isinstance(image, dict),
                f"{context} must be the supported LEGO1 image gate")
        exact_audit_keys(
            image,
            {
                "kind", "target", "original", "original_sha256",
                "original_md5", "original_size", "recompiled",
                "reccmp_report", "reccmp_schema", "required_row_count",
                "row_identity_sha256", "iteration_baseline", "completion",
            },
            context,
        )
        require(
            image.get("kind") == "final_image_identity_gate"
            and image.get("target") == "lego1",
            f"{context} target/kind differs",
        )
        original_relative, original_path = resolve_relative(
            source_root, image.get("original"), f"{context}.original"
        )
        require(original_relative == "legobin/LEGO1.DLL",
                f"{context}.original must use the fixed retail oracle seat")
        original_data = (
            active_build_authority().read_external_bytes(original_path)
            if ACTIVE_BUILD_AUTHORITIES else original_path.read_bytes()
        )
        original_sha256 = require_sha(
            image.get("original_sha256"), f"{context}.original_sha256"
        )
        original_md5 = require_md5(
            image.get("original_md5"), f"{context}.original_md5"
        )
        original_size = require_exact_int(
            image.get("original_size"), f"{context}.original_size", minimum=1
        )
        require(
            original_data.startswith(b"MZ")
            and len(original_data) == original_size
            and sha256_bytes(original_data) == original_sha256
            and md5_bytes(original_data) == original_md5,
            f"{context} retail oracle image differs from its pins",
        )
        require(
            image.get("recompiled") == "LEGO1.DLL"
            and image.get("reccmp_report")
            == "byte-identity/final/LEGO1.json"
            and image.get("reccmp_schema")
            == "reccmp_json_diet_exact_rows_v1",
            f"{context} build output/report contract differs",
        )
        required_rows = require_exact_int(
            image.get("required_row_count"),
            f"{context}.required_row_count",
            minimum=4933,
            maximum=4933,
        )
        row_identity_sha256 = require_sha(
            image.get("row_identity_sha256"),
            f"{context}.row_identity_sha256",
        )
        iteration = image.get("iteration_baseline")
        require(isinstance(iteration, dict),
                f"{context}.iteration_baseline must be an object")
        exact_audit_keys(
            iteration,
            {
                "state", "exact_raw_1_0_count",
                "accepted_row_identity_sha256", "require_zero_losses",
                "reference_target",
            },
            f"{context}.iteration_baseline",
            optional={"reference_target"},
        )
        iteration_count = require_exact_int(
            iteration.get("exact_raw_1_0_count"),
            f"{context}.iteration_baseline.exact_raw_1_0_count",
            minimum=1, maximum=required_rows,
        )
        iteration_sha = require_sha(
            iteration.get("accepted_row_identity_sha256"),
            f"{context}.iteration_baseline.accepted_row_identity_sha256",
        )
        require(
            iteration.get("state") in {
                "accepted_raw_score_set_pinned_v1",
                "accepted_raw_score_set_pinned_v2_source_true",
            }
            and iteration.get("require_zero_losses") is True,
            f"{context}.iteration_baseline policy differs",
        )
        completion = image.get("completion")
        require(isinstance(completion, dict), f"{context}.completion must be an object")
        exact_audit_keys(
            completion,
            {
                "state", "require_all_rows_raw_1_0",
                "require_recompiled_md5_equal_original",
                "require_recompiled_sha256_equal_original",
                "require_recompiled_address_equal_retail",
            },
            f"{context}.completion",
        )
        require(
            exact_json_equal(completion, {
                "state": "required_for_byte_identity_complete",
                "require_all_rows_raw_1_0": True,
                "require_recompiled_md5_equal_original": True,
                "require_recompiled_sha256_equal_original": True,
                "require_recompiled_address_equal_retail": True,
            }),
            f"{context}.completion policy differs",
        )
        normalized_images.append({
            **image,
            "identity": identity,
            "original": original_relative,
            "original_path": str(original_path),
            "original_sha256": original_sha256,
            "original_md5": original_md5,
            "original_size": original_size,
            "recompiled_path": str(final_image_path(build_root, identity)),
            "reccmp_report_path": str(final_report_path(build_root, identity)),
            "required_row_count": required_rows,
            "row_identity_sha256": row_identity_sha256,
            "iteration_baseline": {
                **iteration,
                "exact_raw_1_0_count": iteration_count,
                "accepted_row_identity_sha256": iteration_sha,
            },
        })
    # A manifest that can ever publish a final image verdict must declare both
    # narrowly authorized third-party archives.  An empty/subset declaration
    # would otherwise let a stale host-tree archive satisfy LINK while the
    # manifest still appeared to govern the final image.
    if normalized_images:
        require(
            archive_identities == REQUIRED_THIRD_PARTY_ARCHIVES,
            "final byte identity requires exactly SmartHeap and Smacker archives",
        )

    terminal = manifest.get("terminal_producers")
    require(isinstance(terminal, dict), "terminal_producers must be an object")
    if not normalized_images:
        require(not terminal,
                "terminal_producers require a declared final image gate")
        normalized_terminal = {}
    else:
        exact_audit_keys(terminal, {"link", "reccmp"}, "terminal_producers")
        link = terminal.get("link")
        require(isinstance(link, dict), "terminal_producers.link must be an object")
        exact_audit_keys(
            link,
            {
                "schema", "tools", "library_trees", "project_sdk_libraries",
                "imported_targets",
                "release_required_options", "analysis_added_options",
                "generator_standard_libraries",
                "verified_nonterminal_leaf_audits",
                "ordered_library_occurrence_count",
                "ordered_library_identity_sha256",
                "map_evidence", "member_evidence", "max_child_seconds",
            },
            "terminal_producers.link",
        )
        require(link.get("schema") == "msvc42_dual_link_map_pdb_v1",
                "terminal link producer schema differs")
        link_timeout = require_exact_int(
            link.get("max_child_seconds"),
            "terminal_producers.link.max_child_seconds", minimum=1, maximum=900,
        )
        tools = link.get("tools")
        require(isinstance(tools, list) and len(tools) == 6,
                "terminal link producer must pin six exact tools")
        required_tool_roles = {
            "link_wrapper", "link_binary", "lib_wrapper", "lib_binary",
            "rc_wrapper", "rc_binary",
        }
        normalized_link_tools = []
        tool_roles = set()
        tool_paths = set()
        for index, item in enumerate(tools):
            context = f"terminal_producers.link.tools[{index}]"
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(item, {"role", "path", "sha256"}, context)
            role = item.get("role")
            require(role in required_tool_roles and role not in tool_roles,
                    f"{context}.role is unsupported or duplicated")
            tool_roles.add(role)
            relative = item.get("path")
            require(isinstance(relative, str) and relative,
                    f"{context}.path is invalid")
            pure = PurePosixPath(relative)
            require(not pure.is_absolute() and ".." not in pure.parts
                    and "\\" not in relative and ";" not in relative,
                    f"{context}.path escapes the compiler root")
            relative = pure.as_posix()
            require(relative not in tool_paths,
                    f"{context}.path is duplicated")
            tool_paths.add(relative)
            normalized = {
                "role": role, "path": relative,
                "sha256": require_sha(item.get("sha256"), f"{context}.sha256"),
            }
            if compiler_root is not None:
                logical = compiler_root.joinpath(*pure.parts)
                try:
                    path = logical.resolve(strict=True)
                    metadata = logical.stat(follow_symlinks=False)
                except OSError as error:
                    raise ByteIdentityError(
                        f"terminal link tool is absent: {logical}"
                    ) from error
                require(
                    path == logical
                    and stat.S_ISREG(metadata.st_mode)
                    and not logical.is_symlink(),
                    f"terminal link tool is redirected or non-regular: {logical}",
                )
                if role.endswith("_wrapper"):
                    require(os.access(path, os.X_OK),
                            f"terminal link wrapper is not executable: {path}")
                require(sha256_file(path) == normalized["sha256"],
                        f"terminal link tool hash differs: {role}")
                normalized["absolute_path"] = str(path)
            normalized_link_tools.append(normalized)
        require(tool_roles == required_tool_roles,
                "terminal link producer tool role set is incomplete")

        library_trees = link.get("library_trees")
        require(isinstance(library_trees, list) and len(library_trees) == 2,
                "terminal link producer must pin MSVC and MFC library trees")
        normalized_library_trees = []
        library_roles = set()
        for index, item in enumerate(library_trees):
            context = f"terminal_producers.link.library_trees[{index}]"
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(
                item,
                {"role", "path", "entry_count", "max_depth",
                 "membership_sha256", "content_sha256"},
                context,
            )
            role = item.get("role")
            require(role in {"msvc_lib", "mfc_lib"} and role not in library_roles,
                    f"{context}.role is unsupported or duplicated")
            library_roles.add(role)
            relative = item.get("path")
            require(isinstance(relative, str) and relative,
                    f"{context}.path is invalid")
            pure = PurePosixPath(relative)
            require(not pure.is_absolute() and ".." not in pure.parts
                    and "\\" not in relative and ";" not in relative,
                    f"{context}.path escapes the compiler root")
            pin = {
                "role": role,
                "path": pure.as_posix(),
                "entry_count": require_exact_int(
                    item.get("entry_count"), f"{context}.entry_count",
                    minimum=1, maximum=20000,
                ),
                "max_depth": require_exact_int(
                    item.get("max_depth"), f"{context}.max_depth",
                    minimum=0, maximum=32,
                ),
                "membership_sha256": require_sha(
                    item.get("membership_sha256"), f"{context}.membership_sha256"
                ),
                "content_sha256": require_sha(
                    item.get("content_sha256"), f"{context}.content_sha256"
                ),
            }
            if compiler_root is not None:
                _, path = declared_toolchain_path(
                    compiler_root, pin["path"], f"terminal library tree {role}"
                )
                snapshot = canonical_tree_snapshot(
                    path, hash_files=True, max_entries=pin["entry_count"],
                    max_depth=pin["max_depth"],
                )
                require(
                    snapshot["entry_count"] == pin["entry_count"]
                    and snapshot["max_depth"] == pin["max_depth"]
                    and snapshot["membership_sha256"] == pin["membership_sha256"]
                    and snapshot["content_sha256"] == pin["content_sha256"],
                    f"terminal library tree differs: {role}",
                )
                pin["absolute_path"] = str(path)
                pin["metadata_sha256"] = snapshot["metadata_sha256"]
            normalized_library_trees.append(pin)
        require(library_roles == {"msvc_lib", "mfc_lib"},
                "terminal library tree role set is incomplete")

        project_sdk_libraries = link.get("project_sdk_libraries")
        require(isinstance(project_sdk_libraries, list),
                "terminal project SDK library pins must be an array")
        normalized_project_sdk_libraries = []
        sdk_paths = set()
        for index, item in enumerate(project_sdk_libraries):
            context = f"terminal_producers.link.project_sdk_libraries[{index}]"
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(item, {"path", "sha256"}, context)
            relative = item.get("path")
            require(isinstance(relative, str) and relative,
                    f"{context}.path is invalid")
            pure = PurePosixPath(relative)
            require(not pure.is_absolute() and ".." not in pure.parts
                    and "\\" not in relative and ";" not in relative,
                    f"{context}.path escapes the source root")
            relative = pure.as_posix()
            require(relative not in sdk_paths,
                    f"{context}.path is duplicated")
            sdk_paths.add(relative)
            path = source_dir / PurePosixPath(relative)
            try:
                resolved_sdk = path.resolve(strict=True)
            except OSError as error:
                raise ByteIdentityError(
                    f"{context}.path is absent or redirected: {error}"
                ) from error
            require(resolved_sdk == path and path.is_file()
                    and not path.is_symlink(),
                    f"{context}.path is absent or redirected")
            expected_sha = require_sha(
                item.get("sha256"), f"{context}.sha256"
            )
            require(sha256_file(path) == expected_sha,
                    f"{context}.sha256 differs")
            normalized_project_sdk_libraries.append({
                "path": relative, "absolute_path": str(path),
                "sha256": expected_sha,
            })
        require(sdk_paths == REQUIRED_PROJECT_SDK_LIBRARIES,
                "terminal project SDK library set differs from exact DirectX 5 closure")

        imported_targets = link.get("imported_targets")
        require(isinstance(imported_targets, list),
                "terminal imported-target contracts must be an array")
        normalized_imported_targets = []
        imported_names = set()
        source_root_text = str(source_dir)
        for index, item in enumerate(imported_targets):
            context = f"terminal_producers.link.imported_targets[{index}]"
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(
                item, {"name", "type", "global", "location", "properties"},
                context,
            )
            name = item.get("name")
            target_type = item.get("type")
            require(isinstance(name, str) and IMPORTED_TARGET_RE.fullmatch(name)
                    and name not in imported_names,
                    f"{context}.name is invalid or duplicated")
            imported_names.add(name)
            require(target_type in {"STATIC_LIBRARY", "INTERFACE_LIBRARY"},
                    f"{context}.type is unsupported")
            require(type(item.get("global")) is bool,
                    f"{context}.global must be boolean")
            location = item.get("location")
            require(location is None or (isinstance(location, str) and location),
                    f"{context}.location is invalid")
            require((target_type == "STATIC_LIBRARY") is (location is not None),
                    f"{context}.location/type contract differs")
            properties = item.get("properties")
            require(isinstance(properties, dict),
                    f"{context}.properties must be an object")
            exact_audit_keys(
                properties, set(IMPORTED_TARGET_INTERFACE_PROPERTIES),
                f"{context}.properties",
            )

            def expand_imported_value(value: object, value_context: str) -> str:
                require(isinstance(value, str) and value and "\0" not in value
                        and ";" not in value,
                        f"{value_context} must be one non-empty CMake list item")
                expanded = value.replace("<SOURCE_ROOT>", source_root_text)
                require("<" not in expanded and ">" not in expanded,
                        f"{value_context} contains an unknown placeholder")
                return expanded

            normalized_properties = {}
            for property_name in IMPORTED_TARGET_INTERFACE_PROPERTIES:
                values = properties.get(property_name)
                require(isinstance(values, list)
                        and all(isinstance(value, str) for value in values),
                        f"{context}.properties.{property_name} must be an array")
                normalized_properties[property_name] = [
                    expand_imported_value(
                        value,
                        f"{context}.properties.{property_name}[{value_index}]",
                    )
                    for value_index, value in enumerate(values)
                ]
            normalized_location = (
                expand_imported_value(location, f"{context}.location")
                if location is not None else None
            )
            normalized_imported_targets.append({
                "name": name,
                "type": target_type,
                "global": item["global"],
                "location": normalized_location,
                "properties": normalized_properties,
            })
        require(imported_names == REQUIRED_IMPORTED_TARGETS,
                "terminal imported-target name universe differs")
        normalized_imported_targets.sort(key=lambda item: item["name"])

        release_options = link.get("release_required_options")
        analysis_options = link.get("analysis_added_options")
        require(exact_json_equal(release_options, ["/MAP", "/VERBOSE:LIB"]),
                "terminal release link option contract differs")
        require(exact_json_equal(analysis_options, ["/DEBUG"]),
                "terminal analysis link option contract differs")
        standard_libraries = link.get("generator_standard_libraries")
        require(isinstance(standard_libraries, dict),
                "terminal generator standard-library contract must be an object")
        exact_audit_keys(
            standard_libraries,
            {"configuration", "base", "configuration_specific"},
            "terminal_producers.link.generator_standard_libraries",
        )
        require(standard_libraries.get("configuration") == "RelWithDebInfo",
                "terminal generator standard-library configuration differs")
        normalized_standard_libraries = {}
        for key in ("base", "configuration_specific"):
            values = standard_libraries.get(key)
            require(isinstance(values, list)
                    and all(isinstance(value, str) for value in values),
                    "terminal generator standard-library sequence is invalid")
            require(all(re.fullmatch(r"[a-z0-9_+.\-]+\.lib", value)
                        for value in values),
                    "terminal generator standard-library name is noncanonical")
            require(len(values) == len(set(values)),
                    "terminal generator standard-library sequence is duplicated")
            normalized_standard_libraries[key] = list(values)
        require(not normalized_standard_libraries["configuration_specific"],
                "terminal config-specific standard libraries are unsupported")
        require(normalized_standard_libraries["base"],
                "terminal base standard-library sequence is empty")
        normalized_standard_libraries["configuration"] = "RelWithDebInfo"
        leaf_audits = link.get("verified_nonterminal_leaf_audits")
        require(isinstance(leaf_audits, list),
                "verified nonterminal leaf-audit policy must be an array")
        normalized_leaf_audits = []
        leaf_targets = set()
        for index, item in enumerate(leaf_audits):
            context = (
                f"terminal_producers.link.verified_nonterminal_leaf_audits[{index}]"
            )
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(
                item,
                {"target", "compiler_audit_count", "resource_audit_count"},
                context,
            )
            target = item.get("target")
            require(isinstance(target, str) and TARGET_RE.fullmatch(target)
                    and target != "lego1" and target not in leaf_targets,
                    f"{context}.target is invalid or duplicated")
            leaf_targets.add(target)
            normalized_leaf_audits.append({
                "target": target,
                "compiler_audit_count": require_exact_int(
                    item.get("compiler_audit_count"),
                    f"{context}.compiler_audit_count", minimum=0, maximum=1000,
                ),
                "resource_audit_count": require_exact_int(
                    item.get("resource_audit_count"),
                    f"{context}.resource_audit_count", minimum=0, maximum=1000,
                ),
            })
        require(normalized_leaf_audits
                == sorted(normalized_leaf_audits,
                          key=lambda item: item["target"]),
                "verified nonterminal leaf-audit policy is not target-sorted")
        ordered_library_occurrence_count = require_exact_int(
            link.get("ordered_library_occurrence_count"),
            "terminal_producers.link.ordered_library_occurrence_count",
            minimum=1, maximum=1000,
        )
        ordered_library_identity_sha256 = require_sha(
            link.get("ordered_library_identity_sha256"),
            "terminal_producers.link.ordered_library_identity_sha256",
        )

        def normalize_evidence(values: object, context: str, keys: set[str]) -> list[dict]:
            require(isinstance(values, list) and values,
                    f"{context} must be a non-empty array")
            result = []
            seen = set()
            for index, item in enumerate(values):
                item_context = f"{context}[{index}]"
                require(isinstance(item, dict), f"{item_context} must be an object")
                exact_audit_keys(item, keys, item_context)
                require(all(isinstance(item.get(key), str) and item.get(key)
                            for key in keys),
                        f"{item_context} values must be non-empty strings")
                identity = tuple(item[key] for key in sorted(keys))
                require(identity not in seen, f"{item_context} is duplicated")
                seen.add(identity)
                result.append(dict(item))
            return result

        normalized_map_evidence = normalize_evidence(
            link.get("map_evidence"), "terminal_producers.link.map_evidence",
            {"symbol", "address", "library", "member"},
        )
        normalized_member_evidence = normalize_evidence(
            link.get("member_evidence"),
            "terminal_producers.link.member_evidence",
            {"symbol", "referenced_in", "library", "member"},
        )
        required_member_triples = {
            ("SHLW32MT.LIB", "shnew.obj"),
            ("smackw32.lib", "smackw32.obj"),
            ("libcmt.lib", "strstr.obj"),
        }
        require(
            {(item["library"], item["member"])
             for item in normalized_member_evidence} >= required_member_triples,
            "terminal member evidence omits SmartHeap, Smacker, or libcmt strstr",
        )

        reccmp = terminal.get("reccmp")
        require(isinstance(reccmp, dict),
                "terminal_producers.reccmp must be an object")
        require(reccmp.get("schema") == "reccmp_paths_json_diet_producer_v1",
                "terminal reccmp producer schema differs")
        if "backend_profiles" in reccmp:
            exact_audit_keys(
                reccmp,
                {"schema", "backend_profiles", "argv_template",
                 "max_child_seconds"},
                "terminal_producers.reccmp",
            )
            profiles = reccmp.get("backend_profiles")
            require(isinstance(profiles, dict)
                    and set(profiles) == {
                        POSIX_WINE_BACKEND, WINDOWS_NATIVE_BACKEND,
                    }, "terminal reccmp backend profile universe differs")
            posix_profile = profiles[POSIX_WINE_BACKEND]
            require(isinstance(posix_profile, dict),
                    "terminal POSIX reccmp profile is not an object")
            exact_audit_keys(posix_profile, {
                "status", "transport_schema", "executable",
                "executable_sha256", "interpreter", "interpreter_sha256",
                "private_runtime", "closure_roots",
            }, "terminal POSIX reccmp profile")
            require(
                posix_profile.get("status") == "framework_implemented"
                and posix_profile.get("transport_schema")
                == "darwin_native_python_private_cvdump_wine_v1",
                "terminal POSIX reccmp backend profile differs",
            )
            windows_profile = profiles[WINDOWS_NATIVE_BACKEND]
            require(isinstance(windows_profile, dict),
                    "terminal Windows reccmp profile is not an object")
            exact_audit_keys(windows_profile, {"status", "transport_schema"},
                             "terminal Windows reccmp profile")
            require(
                windows_profile == {
                    "status": "architectural_seam_deferred_untested",
                    "transport_schema": "windows_native_python_cvdump_v1",
                }, "terminal Windows reccmp backend profile differs",
            )
            profile = profiles[execution_backend["id"]]
            require(profile.get("status") == "framework_implemented",
                    f"terminal reccmp backend is explicitly deferred: "
                    f"{execution_backend['id']}")
        else:
            # Native test fixtures without the explicit backend registry retain
            # the POSIX profile only. Production manifests must be keyed before
            # any host-specific pathname is resolved.
            require(manifest.get("execution_backends") is None
                    and execution_backend["id"] == POSIX_WINE_BACKEND,
                    "terminal reccmp host paths are not backend-keyed")
            exact_audit_keys(
                reccmp,
                {
                    "schema", "executable", "executable_sha256",
                    "interpreter", "interpreter_sha256", "private_runtime",
                    "closure_roots", "argv_template", "max_child_seconds",
                },
                "terminal_producers.reccmp",
            )
            profile = {
                **reccmp,
                "status": "framework_implemented",
                "transport_schema":
                    "darwin_native_python_private_cvdump_wine_v1",
            }
        normalized_reccmp_paths = {}
        for name in ("executable", "interpreter"):
            value = profile.get(name)
            path = manifest_host_path(
                value, f"terminal reccmp {name}", host_roots
            )
            expected = require_sha(
                profile.get(f"{name}_sha256"),
                f"terminal_producers.reccmp.{name}_sha256",
            )
            normalized_reccmp_paths[f"{name}_path"] = str(path)
            normalized_reccmp_paths[f"{name}_sha256"] = expected
        private_runtime = profile.get("private_runtime")
        require(isinstance(private_runtime, dict),
                "terminal reccmp private_runtime must be an object")
        exact_audit_keys(
            private_runtime,
            {
                "schema", "app_binary", "app_binary_sha256",
                "framework_dylib", "framework_dylib_sha256", "stdlib",
                "external_dylibs",
            },
            "terminal_producers.reccmp.private_runtime",
        )
        require(private_runtime.get("schema")
                == "darwin_relocated_cpython312_v1",
                "terminal reccmp private runtime schema differs")
        normalized_private_runtime = {"schema": private_runtime["schema"]}
        for name in ("app_binary", "framework_dylib"):
            value = private_runtime.get(name)
            path = manifest_host_path(
                value, f"terminal private runtime {name}", host_roots
            )
            expected = require_sha(
                private_runtime.get(f"{name}_sha256"),
                f"terminal private runtime {name}_sha256",
            )
            normalized_private_runtime[name] = str(path)
            normalized_private_runtime[f"{name}_sha256"] = expected
        stdlib = private_runtime.get("stdlib")
        require(isinstance(stdlib, dict),
                "terminal private runtime stdlib must be an object")
        exact_audit_keys(
            stdlib,
            {"path", "entry_count", "max_depth", "membership_sha256",
             "content_sha256"},
            "terminal private runtime stdlib",
        )
        stdlib_path = manifest_host_path(
            stdlib.get("path"), "terminal private runtime stdlib.path",
            host_roots,
        )
        stdlib_pin = {
            "path": str(stdlib_path),
            "entry_count": require_exact_int(
                stdlib.get("entry_count"), "private runtime stdlib entry_count",
                minimum=1, maximum=10000,
            ),
            "max_depth": require_exact_int(
                stdlib.get("max_depth"), "private runtime stdlib max_depth",
                minimum=0, maximum=32,
            ),
            "membership_sha256": require_sha(
                stdlib.get("membership_sha256"),
                "private runtime stdlib membership_sha256",
            ),
            "content_sha256": require_sha(
                stdlib.get("content_sha256"),
                "private runtime stdlib content_sha256",
            ),
        }
        normalized_private_runtime["stdlib"] = stdlib_pin
        external_dylibs = private_runtime.get("external_dylibs")
        require(isinstance(external_dylibs, list) and external_dylibs,
                "terminal private runtime dylib closure must be non-empty")
        normalized_dylibs = []
        private_names = set()
        install_names = set()
        for dylib_index, dylib in enumerate(external_dylibs):
            context = f"terminal private runtime dylib[{dylib_index}]"
            require(isinstance(dylib, dict), f"{context} must be an object")
            exact_audit_keys(
                dylib, {"path", "private_name", "sha256", "install_names"},
                context,
            )
            path = manifest_host_path(
                dylib.get("path"), f"{context}.path", host_roots
            )
            private_name = dylib.get("private_name")
            require(isinstance(private_name, str)
                    and PurePosixPath(private_name).name == private_name
                    and private_name.endswith(".dylib")
                    and private_name not in private_names,
                    f"{context} path/private name differs")
            private_names.add(private_name)
            expected = require_sha(dylib.get("sha256"), f"{context}.sha256")
            aliases = dylib.get("install_names")
            require(isinstance(aliases, list) and aliases,
                    f"{context} install_names are invalid")
            expanded_aliases = [
                manifest_host_string(
                    alias, f"{context}.install_names[{alias_index}]",
                    host_roots,
                )
                for alias_index, alias in enumerate(aliases)
            ]
            require(not (set(expanded_aliases) & install_names),
                    f"{context} install_names are invalid or duplicated")
            install_names.update(expanded_aliases)
            normalized_dylibs.append({
                "path": str(path), "private_name": private_name,
                "sha256": expected, "install_names": expanded_aliases,
            })
        normalized_private_runtime["external_dylibs"] = normalized_dylibs
        closure_roots = profile.get("closure_roots")
        require(isinstance(closure_roots, list) and closure_roots,
                "terminal reccmp closure_roots must be non-empty")
        normalized_closure_roots = []
        closure_roles = set()
        for index, item in enumerate(closure_roots):
            context = f"terminal_producers.reccmp.closure_roots[{index}]"
            require(isinstance(item, dict), f"{context} must be an object")
            exact_audit_keys(
                item,
                {"role", "path", "entry_count", "max_depth",
                 "membership_sha256", "content_sha256"},
                context,
            )
            role = item.get("role")
            path_value = item.get("path")
            require(isinstance(role, str) and TARGET_RE.fullmatch(role) is not None
                    and role not in closure_roles,
                    f"{context}.role is invalid or duplicated")
            closure_roles.add(role)
            path = manifest_host_path(
                path_value, f"{context}.path", host_roots
            )
            count = require_exact_int(
                item.get("entry_count"), f"{context}.entry_count",
                minimum=1, maximum=20000,
            )
            depth = require_exact_int(
                item.get("max_depth"), f"{context}.max_depth",
                minimum=0, maximum=32,
            )
            membership = require_sha(
                item.get("membership_sha256"), f"{context}.membership_sha256"
            )
            content = require_sha(
                item.get("content_sha256"), f"{context}.content_sha256"
            )
            normalized_closure_roots.append({
                **item, "path": str(path),
            })
        require([item["role"] for item in normalized_closure_roots]
                == ["reccmp_source", "reccmp_environment"],
                "terminal reccmp closure roles/order differs")
        argv_template = reccmp.get("argv_template")
        require(exact_json_equal(argv_template, [
                    "--paths", "<ORIGINAL>", "<IMAGE>", "<PDB>",
                    "<SOURCE_ROOT>", "--json", "<REPORT>", "--json-diet",
                    "--print-rec-addr", "--silent",
                ]), "terminal reccmp argv template differs")
        reccmp_timeout = require_exact_int(
            reccmp.get("max_child_seconds"),
            "terminal_producers.reccmp.max_child_seconds",
            minimum=1, maximum=1800,
        )
        normalized_terminal = {
            "link": {
                **link,
                "tools": normalized_link_tools,
                "library_trees": normalized_library_trees,
                "project_sdk_libraries": normalized_project_sdk_libraries,
                "imported_targets": normalized_imported_targets,
                "map_evidence": normalized_map_evidence,
                "member_evidence": normalized_member_evidence,
                "ordered_library_occurrence_count":
                    ordered_library_occurrence_count,
                "ordered_library_identity_sha256":
                    ordered_library_identity_sha256,
                "generator_standard_libraries":
                    normalized_standard_libraries,
                "verified_nonterminal_leaf_audits": normalized_leaf_audits,
                "max_child_seconds": link_timeout,
            },
            "reccmp": {
                "schema": reccmp["schema"],
                "backend": execution_backend["id"],
                "transport_schema": profile["transport_schema"],
                **normalized_reccmp_paths,
                "private_runtime": normalized_private_runtime,
                "closure_roots": normalized_closure_roots,
                "argv_template": argv_template,
                "max_child_seconds": reccmp_timeout,
            },
        }
    return {
        "manifest": manifest,
        "manifest_path": str(manifest_path.resolve()),
        "manifest_sha256": sha256_bytes(raw),
        "source_dir": str(source_dir.resolve()),
        "build_dir": str(build_root),
        "host_roots": host_roots,
        "source_overlay": source_overlay,
        "diagnostic_policy": diagnostic_policy,
        "translation_units": normalized_units,
        "target_policies": normalized_target_policies,
        "recipes": [recipe_registry[recipe_id] for recipe_id in recipe_order],
        "archives": normalized_archives,
        "images": normalized_images,
        "terminal_producers": normalized_terminal,
        "compiler_sha256": expected_compiler_sha,
        "compiler_path": (
            str(compiler_path(configured_compiler))
            if configured_compiler is not None else None
        ),
        "compiler_root": str(compiler_root) if compiler_root is not None else None,
        "python_executable": str(current_python),
        "python_sha256": expected_python_sha,
        "python_version": expected_python_version,
        "compiler_support_files": normalized_support,
        "producer_support_files": normalized_producer_support,
        "required_absent_toolchain_files": normalized_absent,
        "runtime_executables": normalized_runtimes,
        "sealed_include_trees": normalized_include_trees,
        "runtime_closure": normalized_runtime_closure,
        "transport": normalized_transport,
        "toolchain_transport": {
            "backend": execution_backend["id"],
            "schema": toolchain_profile["transport_schema"],
        },
        "execution_backend": execution_backend,
        "toolchain_fingerprint": toolchain_fingerprint,
        "framework_tool_sha256": sha256_file(Path(__file__).resolve()),
        "backend_tool_path": str(Path(execution_backend_module.__file__).resolve()),
        "backend_tool_sha256": sha256_file(
            Path(execution_backend_module.__file__).resolve()
        ),
        "entropy_tool_sha256": sha256_file(Path(entropy_generator.__file__).resolve()),
        "child_environment": CHILD_ENVIRONMENT_POLICY,
        "max_child_seconds": timeout,
    }


def cmake_quote(value: str) -> str:
    require(";" not in value and "\n" not in value and "\r" not in value,
            "unsafe value for generated CMake plan")
    return value.replace("\\", "\\\\").replace('"', '\\"')


def append_cmake_list(lines: list[str], variable: str, values: list[str]) -> None:
    """Render a CMake list without smuggling separators through quoting."""
    require(re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", variable) is not None,
            "unsafe variable for generated CMake plan")
    lines.append(f"set({variable})")
    for value in values:
        lines.append(
            f'list(APPEND {variable} "{cmake_quote(value)}")'
        )


def render_plan(state: dict) -> bytes:
    completion = (
        "object_composition_enabled_final_gates_incomplete"
        if any(unit["mode"] == "compose_equal_linked_span_fpo"
               for unit in state["translation_units"])
        else "planned_not_composed"
    )
    lines = [
        "# Generated atomically by tools/byte_identity.py; do not edit.",
        f'set(ISLE_BYTE_IDENTITY_PHASE "{PHASE}")',
        f'set(ISLE_BYTE_IDENTITY_COMPLETION "{completion}")',
        f'set(ISLE_BYTE_IDENTITY_EXECUTION_BACKEND '
        f'"{cmake_quote(state["execution_backend"]["id"])}")',
        f'set(ISLE_BYTE_IDENTITY_MANIFEST_SHA256 "{state["manifest_sha256"]}")',
        f'set(ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_ENABLED '
        f'{"TRUE" if state["source_overlay"]["enabled"] else "FALSE"})',
        f'set(ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_POLICY_SHA256 '
        f'"{state["source_overlay"]["policy_sha256"]}")',
    ]
    graph = state["source_overlay"]["graph"]
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_OUTPUTS",
        [item["logical_path"] for item in state["source_overlay"]["outputs"]],
    )
    graph_units = graph["generated_translation_units"]
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_TU_INDICES",
        [str(index) for index in range(len(graph_units))],
    )
    for index, item in enumerate(graph_units):
        prefix = f"ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_TU_{index}"
        lines.extend([
            f'set({prefix}_PATH "{cmake_quote(item["logical_path"])}")',
            f'set({prefix}_LANGUAGE "{item["language"]}")',
            f'set({prefix}_TARGET_FAMILY "{item["target_family"]}")',
            f'set({prefix}_SOURCE_ORDINAL "{item["source_ordinal"]}")',
            f'set({prefix}_INSERT_AFTER "{cmake_quote(item["insert_after"])}")',
            f'set({prefix}_INSERT_BEFORE "{cmake_quote(item["insert_before"] or "")}")',
            f'set({prefix}_OUTPUT_SHA256 '
            f'"{item["generated_output"]["baseline_sha256"]}")',
            f'set({prefix}_OUTPUT_SIZE '
            f'"{item["generated_output"]["baseline_size"]}")',
            f'set({prefix}_OUTPUT_LINE_COUNT '
            f'"{item["generated_output"]["baseline_line_count"]}")',
            f'set({prefix}_OUTPUT_TOKEN_SHA256 '
            f'"{item["generated_output"]["baseline_significant_token_sha256"]}")',
        ])
        append_cmake_list(lines, prefix + "_TARGETS", item["targets"])
        append_cmake_list(
            lines, prefix + "_GENERATION_OPERATION_IDS",
            item["generation_operation_ids"],
        )
    graph_links = graph["link_admissions"]
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_LINK_INDICES",
        [str(index) for index in range(len(graph_links))],
    )
    for index, item in enumerate(graph_links):
        prefix = f"ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_LINK_{index}"
        lines.extend([
            f'set({prefix}_ADMISSION_ID "{item["admission_id"]}")',
            f'set({prefix}_TARGET "{item["target"]}")',
            f'set({prefix}_VISIBILITY "{item["visibility"]}")',
            f'set({prefix}_LIBRARY "{item["library"]}")',
            f'set({prefix}_INSERT_AFTER "{item["insert_after"]}")',
            f'set({prefix}_INSERT_BEFORE "{item["insert_before"]}")',
            f'set({prefix}_SOURCE_OUTPUT '
            f'"{cmake_quote(item["source_output"])}")',
        ])
        append_cmake_list(
            lines, prefix + "_REQUIRED_OPERATION_IDS",
            item["required_operation_ids"],
        )
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_FORBIDDEN_INTERFACES",
        graph["forbidden_legacy_interfaces"],
    )
    lines.append(
        'set(ISLE_BYTE_IDENTITY_SOURCE_OVERLAY_PREBUILT_SOURCE_ARTIFACTS '
        f'"{graph["prebuilt_source_artifacts"]}")'
    )
    indices = [str(index) for index in range(len(state["translation_units"]))]
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_TU_INDICES", indices)
    append_cmake_list(
        lines,
        "ISLE_BYTE_IDENTITY_TARGETS",
        [policy["target"] for policy in state["target_policies"]],
    )
    policy_inputs = [
        state["compiler_path"],
        state["python_executable"],
        state["backend_tool_path"],
        *(item["absolute_path"] for item in state["compiler_support_files"]),
        *(item["absolute_path"] for item in state["runtime_executables"]),
    ]
    if state["terminal_producers"]:
        policy_inputs.extend(
            item["absolute_path"]
            for item in state["terminal_producers"]["link"]["tools"]
        )
        policy_inputs.extend([
            state["terminal_producers"]["reccmp"]["executable_path"],
            state["terminal_producers"]["reccmp"]["interpreter_path"],
        ])
    require(all(policy_inputs), "configured policy input paths are incomplete")
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_POLICY_INPUTS", policy_inputs)
    for index, unit in enumerate(state["translation_units"]):
        outputs = [donor["header_output"] for donor in unit["donors"]]
        ids = [donor["id"] for donor in unit["donors"]]
        prefix = f"ISLE_BYTE_IDENTITY_TU_{index}"
        audit = audit_object_path(
            Path(state["build_dir"]), unit["target"], unit["source"]
        )
        lines.extend(
            [
                f'set({prefix}_TARGET "{cmake_quote(unit["target"])}")',
                f'set({prefix}_SOURCE "{cmake_quote(unit["source_path"])}")',
                f'set({prefix}_SOURCE_REL "{cmake_quote(unit["source"])}")',
            ]
        )
        append_cmake_list(lines, f"{prefix}_OUTPUTS", outputs)
        append_cmake_list(lines, f"{prefix}_RECIPE_IDS", ids)
        lines.append(f'set({prefix}_AUDIT "{cmake_quote(str(audit))}")')
    recipe_ids = [recipe["id"] for recipe in state["recipes"]]
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_RECIPE_IDS", recipe_ids)
    for recipe in state["recipes"]:
        recipe_id = recipe["id"]
        lines.append(
            f'set(ISLE_BYTE_IDENTITY_RECIPE_{recipe_id}_OUTPUT '
            f'"{cmake_quote(recipe["header_output"])}")'
        )
    archive_indices = [str(index) for index in range(len(state["archives"]))]
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_ARCHIVE_INDICES", archive_indices)
    for archive_index, archive in enumerate(state["archives"]):
        prefix = f"ISLE_BYTE_IDENTITY_ARCHIVE_{archive_index}"
        lines.extend([
            f'set({prefix}_IDENTITY "{cmake_quote(archive["identity"])}")',
            f'set({prefix}_IMPORTED_TARGET '
            f'"{cmake_quote(archive["imported_target"])}")',
            f'set({prefix}_SOURCE "{cmake_quote(archive["source_path"])}")',
            f'set({prefix}_OUTPUT "{cmake_quote(archive["output"])}")',
            f'set({prefix}_AUDIT "{cmake_quote(archive["audit"])}")',
        ])
        contract_indices = [
            str(index) for index in range(len(archive["link_contract"]))
        ]
        append_cmake_list(lines, f"{prefix}_CONTRACT_INDICES", contract_indices)
        for contract_index, contract in enumerate(archive["link_contract"]):
            contract_prefix = f"{prefix}_CONTRACT_{contract_index}"
            lines.extend([
                f'set({contract_prefix}_TARGET '
                f'"{cmake_quote(contract["target"])}")',
                f'set({contract_prefix}_OCCURRENCES '
                f'"{contract["occurrences"]}")',
            ])
            append_cmake_list(
                lines,
                f"{contract_prefix}_SEQUENCE",
                contract["direct_link_sequence"],
            )
    image_indices = [str(index) for index in range(len(state["images"]))]
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_IMAGE_INDICES", image_indices)
    for image_index, image_gate in enumerate(state["images"]):
        prefix = f"ISLE_BYTE_IDENTITY_IMAGE_{image_index}"
        lines.extend([
            f'set({prefix}_IDENTITY "{cmake_quote(image_gate["identity"])}")',
            f'set({prefix}_TARGET "{cmake_quote(image_gate["target"])}")',
            f'set({prefix}_RECOMPILED '
            f'"{cmake_quote(image_gate["recompiled_path"])}")',
            f'set({prefix}_RECCMP_REPORT '
            f'"{cmake_quote(image_gate["reccmp_report_path"])}")',
        ])
    imported_targets = (
        state.get("terminal_producers", {}).get("link", {})
        .get("imported_targets", [])
    )
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_IMPORTED_TARGET_INDICES",
        [str(index) for index in range(len(imported_targets))],
    )
    for index, imported in enumerate(imported_targets):
        prefix = f"ISLE_BYTE_IDENTITY_IMPORTED_TARGET_{index}"
        lines.extend([
            f'set({prefix}_NAME "{cmake_quote(imported["name"])}")',
            f'set({prefix}_TYPE "{cmake_quote(imported["type"])}")',
            f'set({prefix}_GLOBAL "{"TRUE" if imported["global"] else "FALSE"}")',
            f'set({prefix}_LOCATION "{cmake_quote(imported["location"] or "")}")',
        ])
        for property_name in IMPORTED_TARGET_INTERFACE_PROPERTIES:
            append_cmake_list(
                lines, f"{prefix}_{property_name}",
                imported["properties"][property_name],
            )
    lines.append("set(ISLE_BYTE_IDENTITY_PLAN_COMPLETE TRUE)")
    return ("\n".join(lines) + "\n").encode("utf-8")


def command_plan_locked(arguments: argparse.Namespace) -> int:
    authority = active_build_authority()
    expected_plan = authority.build_root / "byte-identity/plan.cmake"
    require(authority.parts(arguments.output) == authority.parts(expected_plan),
            "plan output must be the fixed build-tree byte-identity/plan.cmake")
    invalidate_framework_verdict(arguments.build_dir)
    try:
        state = validate_manifest(
            arguments.manifest,
            arguments.source_dir,
            arguments.build_dir,
            configured_compiler=arguments.compiler,
            compiler_id=arguments.compiler_id,
            compiler_version=arguments.compiler_version,
            generator=arguments.generator,
        )
        rendered = render_plan(state)
        atomic_write(arguments.output, rendered, if_changed=True)
    except BaseException:
        invalidate_build_paths([expected_plan])
        raise
    if arguments.emit_cmake:
        sys.stdout.buffer.write(rendered)
    else:
        print(
            json.dumps(
                {
                    "status": "COMPILER_OUTPUT_COMDAT_PLAN",
                    "translation_units": len(state["translation_units"]),
                    "recipes": len(state["recipes"]),
                    "manifest_sha256": state["manifest_sha256"],
                    "output": str(arguments.output),
                },
                sort_keys=True,
            )
        )
    return 0


def command_plan(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_plan_locked(arguments)


def _tree_pin(snapshot: dict) -> dict:
    return {
        key: snapshot[key]
        for key in (
            "root", "entry_count", "max_depth",
            "membership_sha256", "content_sha256",
        )
    }


def macho_loader_dependencies(path: Path) -> list[str]:
    require(sys.platform == "darwin",
            "private reccmp runtime relocation is implemented only on Darwin")
    result = subprocess.run(
        ["/usr/bin/otool", "-L", str(path)],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False,
        text=True,
        env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
    )
    require(result.returncode == 0,
            f"cannot inspect private runtime Mach-O {path}: {result.stderr}")
    dependencies = []
    for line in result.stdout.splitlines()[1:]:
        value = line.strip().split(" (compatibility version ", 1)[0]
        if value:
            dependencies.append(value)
    require(len(dependencies) == len(set(dependencies)),
            f"private runtime Mach-O dependencies are duplicated: {path}")
    return dependencies


def is_macho_file(path: Path) -> bool:
    data = active_build_authority().read_bytes(path)
    return data[:4] in {
        b"\xfe\xed\xfa\xce", b"\xce\xfa\xed\xfe",
        b"\xfe\xed\xfa\xcf", b"\xcf\xfa\xed\xfe",
        b"\xca\xfe\xba\xbe", b"\xbe\xba\xfe\xca",
    }


def private_reccmp_macho_dependency_allowed(value: str) -> bool:
    """Admit only private-relative or Darwin system loader identities."""
    return value.startswith((
        "@loader_path/", "@executable_path/", "@rpath/",
        "/usr/lib/", "/System/Library/",
        "/System/Volumes/Preboot/Cryptexes/OS/usr/lib/",
        "/System/Volumes/Preboot/Cryptexes/OS/System/Library/",
    ))


def relocate_private_macho(
    path: Path, changes: dict[str, str], *, expected_input: dict,
    install_id: str | None = None,
) -> dict:
    require(
        exact_json_equal(
            resident_produced_file_receipt(
                path, "private runtime Mach-O relocation input"
            ),
            expected_input,
        ),
        f"private runtime Mach-O relocation input changed: {path}",
    )
    dependencies = macho_loader_dependencies(path)
    arguments = ["/usr/bin/install_name_tool"]
    if install_id is not None:
        arguments.extend(["-id", install_id])
    for dependency in dependencies:
        replacement = changes.get(dependency)
        if replacement is not None:
            arguments.extend(["-change", dependency, replacement])
    require(len(arguments) > 1,
            f"private runtime Mach-O required no declared relocation: {path}")
    result = subprocess.run(
        [*arguments, str(path)], stdout=subprocess.PIPE,
        stderr=subprocess.PIPE, check=False,
        env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
    )
    require(result.returncode == 0,
            f"private runtime relocation failed for {path}: "
            + result.stderr.decode("utf-8", errors="replace"))
    signed = subprocess.run(
        ["/usr/bin/codesign", "--force", "--sign", "-", str(path)],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False,
        env={"PATH": "/usr/bin:/bin", "LANG": "C", "LC_ALL": "C"},
    )
    require(signed.returncode == 0,
            f"private runtime ad-hoc signing failed for {path}: "
            + signed.stderr.decode("utf-8", errors="replace"))
    return resident_produced_file_receipt(
        path, "private runtime Mach-O relocation"
    )


def materialize_private_reccmp_runtime(state: dict, root: Path) -> dict:
    authority = active_build_authority()
    policy = state["terminal_producers"]["reccmp"]["private_runtime"]
    require(policy["schema"] == "darwin_relocated_cpython312_v1"
            and sys.platform == "darwin",
            "selected private reccmp runtime is unsupported on this host")
    authority.remove_tree(root)
    authority.mkdirs(root / "bin")
    authority.mkdirs(root / "lib")
    expected_root = new_snapshot_destination_expectation(root)
    app = root / "bin/python3.12"
    framework = root / "lib/Python"
    app_record = copy_external_file_to_snapshot(
        Path(policy["app_binary"]), app, policy["app_binary_sha256"]
    )
    add_expected_snapshot_file(expected_root, app, app_record)
    framework_record = copy_external_file_to_snapshot(
        Path(policy["framework_dylib"]), framework,
        policy["framework_dylib_sha256"],
    )
    add_expected_snapshot_file(expected_root, framework, framework_record)
    stdlib = policy["stdlib"]
    stdlib_source_proof = []
    copied_stdlib = copy_filtered_external_tree_to_snapshot(
        Path(stdlib["path"]), root / "lib/python3.12", excluded_names=set(),
        source_proof=stdlib_source_proof,
    )
    require(len(stdlib_source_proof) == 1,
            "private reccmp stdlib produced no unique source proof")
    source_stdlib = stdlib_source_proof[0]
    require(
        source_stdlib["entry_count"] == stdlib["entry_count"]
        and source_stdlib["max_depth"] == stdlib["max_depth"]
        and source_stdlib["membership_sha256"] == stdlib["membership_sha256"]
        and source_stdlib["content_sha256"] == stdlib["content_sha256"],
        "private reccmp stdlib changed during materialization",
    )
    add_expected_snapshot_tree(
        expected_root, root / "lib/python3.12", source_stdlib["records"]
    )
    alias_changes = {}
    dylib_records = []
    for dylib in policy["external_dylibs"]:
        destination = root / "lib" / dylib["private_name"]
        record = copy_external_file_to_snapshot(
            Path(dylib["path"]), destination, dylib["sha256"]
        )
        add_expected_snapshot_file(expected_root, destination, record)
        for alias in dylib["install_names"]:
            alias_changes[alias] = f"@loader_path/{dylib['private_name']}"
        dylib_records.append((dylib, destination))

    # Authenticate the verbatim copy phase before any approved Mach-O
    # transformation can consume it.  A copied byte may not silently become
    # the relocation input baseline.
    validate_expected_snapshot_destination(
        expected_root, "private reccmp pre-relocation runtime",
        max_entries=30000,
    )

    app_receipt = relocate_private_macho(
        app,
        {policy["framework_dylib"]: "@loader_path/../lib/Python"},
        expected_input=validate_expected_snapshot_file(
            expected_root, app, "private reccmp app relocation input"
        ),
    )
    replace_expected_snapshot_with_produced_file(
        expected_root, app, app_receipt, "private reccmp app relocation"
    )
    # The first loader entry of a dylib is its install id.  Give every private
    # image a loader-relative id and rewrite its external Homebrew closure.
    validate_expected_snapshot_file(
        expected_root, framework,
        "private reccmp framework dependency inspection input",
    )
    framework_dependencies = macho_loader_dependencies(framework)
    framework_changes = {
        dependency: alias_changes[dependency]
        for dependency in framework_dependencies
        if dependency in alias_changes
    }
    if framework_dependencies and not private_reccmp_macho_dependency_allowed(
        framework_dependencies[0]
    ):
        # `otool -L` reports a dylib's own install id first. The separately
        # supplied `-id` is authoritative; rewriting the old id as a change
        # also covers tool versions that expose it as an ordinary load entry.
        framework_changes[framework_dependencies[0]] = "@loader_path/Python"
    framework_receipt = relocate_private_macho(
        framework, framework_changes,
        expected_input=expected_snapshot_file_receipt(
            expected_root, framework, "private reccmp framework relocation"
        ),
        install_id="@loader_path/Python",
    )
    replace_expected_snapshot_with_produced_file(
        expected_root, framework, framework_receipt,
        "private reccmp framework relocation",
    )
    for dylib, destination in dylib_records:
        receipt = relocate_private_macho(
            destination, alias_changes,
            expected_input=validate_expected_snapshot_file(
                expected_root, destination,
                "private reccmp dylib relocation input",
            ),
            install_id=f"@loader_path/{dylib['private_name']}",
        )
        replace_expected_snapshot_with_produced_file(
            expected_root, destination, receipt,
            "private reccmp dylib relocation",
        )
    extension_records = []
    stdlib_root = root / "lib/python3.12"
    for relative in canonical_tree_snapshot(
        stdlib_root, hash_files=False
    )["records"]:
        if relative["type"] != "file":
            continue
        candidate = stdlib_root.joinpath(
            *PurePosixPath(relative["path"]).parts
        )
        validate_expected_snapshot_file(
            expected_root, candidate,
            "private reccmp extension inspection input",
        )
        if not is_macho_file(candidate):
            continue
        dependencies = macho_loader_dependencies(candidate)
        changes = {
            dependency: "@loader_path/../../" + Path(replacement).name
            for dependency, replacement in alias_changes.items()
            if dependency in dependencies
        }
        if changes:
            receipt = relocate_private_macho(
                candidate, changes,
                expected_input=expected_snapshot_file_receipt(
                    expected_root, candidate,
                    "private reccmp extension relocation",
                ),
            )
            replace_expected_snapshot_with_produced_file(
                expected_root, candidate, receipt,
                "private reccmp extension relocation",
            )
        extension_records.append(str(candidate.relative_to(root)))

    all_macho = [app, framework, *(path for _, path in dylib_records)]
    all_macho.extend(root / relative for relative in extension_records)
    for candidate in all_macho:
        validate_expected_snapshot_file(
            expected_root, candidate,
            "private reccmp relocated loader inspection input",
        )
        dependencies = macho_loader_dependencies(candidate)
        require(all(private_reccmp_macho_dependency_allowed(value)
                    for value in dependencies),
                f"private reccmp runtime retains an ambient dependency: {candidate}")
    runtime_snapshot = validate_expected_snapshot_destination(
        expected_root, "private reccmp relocated runtime",
        max_entries=30000,
    )
    tree = _tree_pin(runtime_snapshot)
    return {
        "schema": policy["schema"],
        "root": str(root),
        "tree": tree,
        "stdlib_source": {
            key: stdlib[key] for key in (
                "path", "entry_count", "max_depth",
                "membership_sha256", "content_sha256",
            )
        },
        "copied_stdlib": copied_stdlib,
        "external_dylibs": [
            {"private_name": item["private_name"], "source_sha256": item["sha256"]}
            for item, _ in dylib_records
        ],
        "extension_modules": sorted(extension_records),
        "records": runtime_snapshot["records"],
    }


def validate_private_reccmp_runtime(
    state: dict, root: Path, document: object,
) -> dict:
    require(isinstance(document, dict),
            "private reccmp runtime descriptor is invalid")
    exact_audit_keys(document, {
        "schema", "root", "tree", "stdlib_source", "copied_stdlib",
        "external_dylibs", "extension_modules", "records",
    }, "private reccmp runtime descriptor")
    policy = state["terminal_producers"]["reccmp"]["private_runtime"]
    observed = canonical_tree_snapshot(root, hash_files=True)
    require(document.get("schema") == policy["schema"]
            and active_build_authority().parts(Path(document.get("root", "")))
            == active_build_authority().parts(root)
            and exact_json_equal(
                document.get("tree"),
                _tree_pin(observed),
            ), "private reccmp runtime tree differs")
    records = document.get("records")
    require(isinstance(records, list) and records
            and exact_json_equal(
                records, observed["records"]
            ), "private reccmp runtime detailed records differ")
    require(exact_json_equal(document.get("external_dylibs"), [
        {"private_name": item["private_name"], "source_sha256": item["sha256"]}
        for item in policy["external_dylibs"]
    ]), "private reccmp dylib closure differs")
    extensions = document.get("extension_modules")
    require(isinstance(extensions, list) and extensions == sorted(set(extensions)),
            "private reccmp extension closure differs")
    for relative in ["bin/python3.12", "lib/Python", *extensions]:
        path = root / relative
        require(active_build_authority().is_regular_file(path)
                and all(private_reccmp_macho_dependency_allowed(value)
                        for value in macho_loader_dependencies(path)),
                f"private reccmp runtime loader closure escaped: {relative}")
    return document


def _native_reccmp_cache_key(build_dir: Path) -> str:
    return "native-reccmp:" + str(native_reccmp_snapshot_path(build_dir))


def require_posix_reccmp_backend(state: dict, context: str) -> dict:
    """Select the implemented reccmp adapter before host-specific work."""
    backend = state.get("execution_backend", {}).get("id")
    policy = state.get("terminal_producers", {}).get("reccmp")
    require(backend == POSIX_WINE_BACKEND and isinstance(policy, dict)
            and policy.get("backend") == POSIX_WINE_BACKEND
            and policy.get("transport_schema")
            == "darwin_native_python_private_cvdump_wine_v1",
            f"{context} requires the implemented POSIX/Wine reccmp adapter")
    return policy


def require_posix_toolchain_backend(state: dict, context: str) -> dict:
    """Dispatch current producer transport only to its implemented adapter."""
    backend = state.get("execution_backend", {}).get("id")
    policy = state.get("toolchain_transport")
    require(
        backend == POSIX_WINE_BACKEND and isinstance(policy, dict)
        and policy.get("backend") == POSIX_WINE_BACKEND
        and policy.get("schema") == "wine_virtual_z_v1",
        f"{context} requires the implemented POSIX/Wine toolchain adapter",
    )
    return policy


def required_absent_toolchain_paths(state: dict) -> list[Path]:
    """Resolve the exact wrapper branch-switch files that must not exist."""
    root = state.get("compiler_root")
    require(isinstance(root, str) and Path(root).is_absolute(),
            "required-absent toolchain policy lacks a compiler root")
    result = []
    for index, relative in enumerate(
        state.get("required_absent_toolchain_files", [])
    ):
        _normalized, path = declared_toolchain_path(
            Path(root), relative,
            f"required absent toolchain file {index}",
        )
        result.append(path)
    return result


def _require_native_reccmp_external_file(
    path: Path, expected_sha256: str, context: str, *, executable: bool = False,
) -> None:
    lexical = lexical_absolute_path(path)
    try:
        canonical = lexical.resolve(strict=True)
        metadata = lexical.stat(follow_symlinks=False)
    except OSError as error:
        raise ByteIdentityError(f"{context} is absent: {lexical}") from error
    require(canonical == lexical and stat.S_ISREG(metadata.st_mode)
            and not lexical.is_symlink(),
            f"{context} is redirected or non-regular: {lexical}")
    if executable:
        require(os.access(lexical, os.X_OK),
                f"{context} is not executable: {lexical}")
    require(sha256_file(lexical) == expected_sha256,
            f"{context} hash differs: {lexical}")


def _materialize_native_reccmp_snapshot(
    state: dict, build_dir: Path,
) -> dict | None:
    """Materialize native analysis inputs outside Wine/toolchain/fake-Z state."""
    policy = state.get("terminal_producers", {}).get("reccmp")
    if policy is None:
        return None
    authority = active_build_authority()
    root = native_reccmp_snapshot_path(build_dir)
    previous_cache = authority.snapshot_validation_cache.pop(
        _native_reccmp_cache_key(build_dir), None
    )
    if previous_cache is not None:
        previous_cache["holder"].close()
    authority.remove_tree(root)
    tool_root = root / "tool"
    interpreter_root = root / "interpreter"
    runtime_root = root / "runtime"
    closures_root = root / "closures"
    for directory in (tool_root, interpreter_root, closures_root):
        authority.mkdirs(directory)
    expected_root = new_snapshot_destination_expectation(root)

    executable_source = Path(policy["executable_path"])
    interpreter_source = Path(policy["interpreter_path"])
    _require_native_reccmp_external_file(
        executable_source, policy["executable_sha256"],
        "native reccmp executable", executable=True,
    )
    _require_native_reccmp_external_file(
        interpreter_source, policy["interpreter_sha256"],
        "native reccmp source interpreter", executable=True,
    )
    executable = tool_root / "reccmp.py"
    interpreter = interpreter_root / "pinned-interpreter"
    executable_record = copy_external_file_to_snapshot(
        executable_source, executable, policy["executable_sha256"]
    )
    add_expected_snapshot_file(expected_root, executable, executable_record)
    interpreter_record = copy_external_file_to_snapshot(
        interpreter_source, interpreter, policy["interpreter_sha256"]
    )
    add_expected_snapshot_file(expected_root, interpreter, interpreter_record)

    runtime_policy = policy["private_runtime"]
    for name in ("app_binary", "framework_dylib"):
        _require_native_reccmp_external_file(
            Path(runtime_policy[name]), runtime_policy[f"{name}_sha256"],
            f"native reccmp private runtime {name}",
        )
    for index, dylib in enumerate(runtime_policy["external_dylibs"]):
        _require_native_reccmp_external_file(
            Path(dylib["path"]), dylib["sha256"],
            f"native reccmp private dylib {index}",
        )
    runtime = materialize_private_reccmp_runtime(state, runtime_root)
    add_expected_snapshot_tree(
        expected_root, runtime_root, runtime["records"],
        directory_policy="exact",
    )

    closures = []
    for tree in policy["closure_roots"]:
        destination = closures_root / tree["role"]
        source_snapshot = copy_external_tree_to_snapshot(
            Path(tree["path"]), destination, tree
        )
        add_expected_snapshot_tree(
            expected_root, destination, source_snapshot["records"]
        )
        observed = canonical_tree_snapshot(
            destination, hash_files=True,
            max_entries=tree["entry_count"], max_depth=tree["max_depth"],
        )
        closures.append({
            "role": tree["role"], "logical_path": tree["path"],
            "snapshot_path": str(destination),
            "source_entry_count": tree["entry_count"],
            "source_max_depth": tree["max_depth"],
            "source_membership_sha256": tree["membership_sha256"],
            "source_content_sha256": tree["content_sha256"],
            "tree": _tree_pin(observed), "records": observed["records"],
        })

    held_snapshot = validate_expected_snapshot_destination(
        expected_root, "native reccmp held snapshot", max_entries=30000
    )

    descriptor = {
        "schema": 1,
        "status": "IMMUTABLE_NATIVE_RECCMP_SNAPSHOT",
        "root": str(root),
        "tool": {
            **executable_record, "snapshot_path": str(executable),
        },
        "interpreter": {
            **interpreter_record, "snapshot_path": str(interpreter),
        },
        "runtime": runtime,
        "closures": closures,
    }
    descriptor_path = root / "snapshot.json"
    descriptor_bytes = atomic_json(descriptor_path, descriptor)
    holder = authority.retain_directories([
        root, tool_root, interpreter_root, runtime_root, closures_root,
        *(closures_root / item["role"] for item in closures),
    ])
    require(holder.read_bytes(descriptor_path) == descriptor_bytes,
            "native reccmp descriptor changed before hold")
    holder.read_bytes(executable)
    holder.read_bytes(interpreter)
    holder.revalidate()
    authority.snapshot_validation_cache[_native_reccmp_cache_key(build_dir)] = {
        "descriptor": descriptor,
        "descriptor_sha256": sha256_bytes(descriptor_bytes),
        "holder": holder,
        "held_snapshot": held_snapshot,
        "resident_materialized": active_resident_receipt_ledger() is not None,
        "finalized": False,
    }
    return descriptor


def materialize_native_reccmp_snapshot(
    state: dict, build_dir: Path,
) -> dict | None:
    """Failure-atomically materialize the native analysis snapshot."""
    if state.get("terminal_producers", {}).get("reccmp") is None:
        return None
    require_posix_reccmp_backend(state, "native reccmp materialization")
    authority = active_build_authority()
    root = native_reccmp_snapshot_path(build_dir)
    try:
        return _materialize_native_reccmp_snapshot(state, build_dir)
    except BaseException:
        cached = authority.snapshot_validation_cache.pop(
            _native_reccmp_cache_key(build_dir), None
        )
        if cached is not None:
            cached["holder"].close()
        rollback_exact_private_run(authority, root)
        raise


def validate_native_reccmp_snapshot(state: dict, build_dir: Path) -> dict:
    """Validate once and retain the separate native reccmp snapshot."""
    authority = active_build_authority()
    root = native_reccmp_snapshot_path(build_dir)
    descriptor_path = root / "snapshot.json"
    raw = authority.read_bytes(descriptor_path, max_bytes=64 * 1024 * 1024)
    document = strict_json_loads(raw)
    require(isinstance(document, dict),
            "native reccmp snapshot descriptor is invalid")
    exact_audit_keys(document, {
        "schema", "status", "root", "tool", "interpreter", "runtime",
        "closures",
    }, "native reccmp snapshot descriptor")
    require(document.get("schema") == 1
            and document.get("status") == "IMMUTABLE_NATIVE_RECCMP_SNAPSHOT"
            and authority.parts(Path(document.get("root", "")))
            == authority.parts(root),
            "native reccmp snapshot identity differs")
    cache_key = _native_reccmp_cache_key(build_dir)
    cached = authority.snapshot_validation_cache.get(cache_key)
    if cached is not None:
        require(cached["descriptor_sha256"] == sha256_bytes(raw)
                and exact_json_equal(cached["descriptor"], document),
                "held native reccmp descriptor changed")
        cached["holder"].revalidate()
        require_exact_build_namespace(
            authority, root, {
                "tool": "directory", "interpreter": "directory",
                "runtime": "directory", "closures": "directory",
                "snapshot.json": "file",
            }, "held native reccmp snapshot root", replace_pin=True,
        )
        return document
    # A configure descendant cannot leave durable authority for a relocated
    # native runtime: snapshot.json and the copied trees share the same mutable
    # build namespace.  The outer resident therefore rematerializes this
    # snapshot from manifest-authenticated source inputs and retains the exact
    # descriptor/tree holder in this BuildRootAuthority for the entire producer
    # transaction.  Never mint that authority from an on-disk, self-consistent
    # descriptor in a later process/transaction.
    raise ByteIdentityError(
        "native reccmp snapshot lacks same-transaction materialization authority"
    )


def finalize_native_reccmp_snapshot_validation(
    state: dict, build_dir: Path,
) -> None:
    """Rescan the native analysis snapshot once before resident publication."""
    authority = active_build_authority()
    root = native_reccmp_snapshot_path(build_dir)
    cached = authority.snapshot_validation_cache.get(
        _native_reccmp_cache_key(build_dir)
    )
    require(cached is not None,
            "native reccmp snapshot was not held by the resident transaction")
    if cached.get("finalized") is True:
        return
    document = cached["descriptor"]
    cached["holder"].revalidate()
    raw = authority.read_bytes(root / "snapshot.json", max_bytes=64 * 1024 * 1024)
    require(cached["descriptor_sha256"] == sha256_bytes(raw)
            and exact_json_equal(strict_json_loads(raw), document),
            "native reccmp descriptor changed before completion")
    terminal = canonical_tree_snapshot(
        root, hash_files=True, max_entries=30001,
        include_metadata_records=True,
    )

    def immutable_values(snapshot: dict, key: str) -> list[dict]:
        return [
            record for record in snapshot[key]
            if record["path"] not in {".", "snapshot.json"}
        ]

    initial = cached["held_snapshot"]
    require(
        exact_json_equal(
            immutable_values(terminal, "records"),
            immutable_values(initial, "records"),
        )
        and exact_json_equal(
            immutable_values(terminal, "metadata_records"),
            immutable_values(initial, "metadata_records"),
        ),
        "native reccmp held snapshot changed before completion",
    )
    cached["holder"].revalidate()
    cached["finalized"] = True


def authenticated_external_snapshot_file(
    source: Path, expected_sha256: str, context: str,
) -> dict:
    """Rederive one source receipt without trusting a destination document."""
    authority = active_build_authority()
    source = lexical_absolute_path(source)
    try:
        metadata = source.stat(follow_symlinks=False)
        canonical = source.resolve(strict=True)
    except OSError as error:
        raise ByteIdentityError(f"{context} source is absent: {source}") from error
    data = authority.read_external_bytes(source, max_bytes=1 << 30)
    require(canonical == source and stat.S_ISREG(metadata.st_mode)
            and not source.is_symlink()
            and sha256_bytes(data) == expected_sha256,
            f"{context} source differs: {source}")
    return {
        "mode": stat.S_IMODE(metadata.st_mode) & 0o555,
        "size": len(data), "sha256": expected_sha256,
    }


def render_msvc_environment_root_transform(
    source: bytes, *, source_path: Path, source_sha256: str,
    logical_root: Path, source_mode: int,
) -> dict:
    """Replace only msvcenv.sh's physical-$0 root with its logical Z root."""
    require(isinstance(source, bytes)
            and sha256_bytes(source) == source_sha256,
            "MSVC environment transform source hash differs")
    require(
        source.count(MSVC_ENVIRONMENT_ROOT_DERIVATION_LINE) == 1,
        "MSVC environment transform requires one exact root derivation line",
    )
    logical_root = lexical_absolute_path(logical_root)
    root_text = str(logical_root)
    require(
        logical_root.is_absolute() and logical_root.anchor == "/"
        and "\\" not in root_text and "'" not in root_text
        and all(ord(character) >= 0x20 and ord(character) != 0x7f
                for character in root_text),
        "MSVC environment logical root is not safely representable",
    )
    replacement = f"MSVC_ROOT='{root_text}'\n".encode("utf-8")
    output = source.replace(
        MSVC_ENVIRONMENT_ROOT_DERIVATION_LINE, replacement, 1
    )
    output_sha256 = sha256_bytes(output)
    mode = source_mode & 0o555
    receipt = {
        "schema": MSVC_ENVIRONMENT_ROOT_TRANSFORM_SCHEMA,
        "source_path": str(lexical_absolute_path(source_path)),
        "source_sha256": source_sha256,
        "generator_version": MSVC_ENVIRONMENT_ROOT_TRANSFORM_GENERATOR,
        "logical_root": root_text,
        "output_sha256": output_sha256,
        "output_size": len(output),
    }
    return {
        "data": output,
        "record": {
            "mode": mode, "size": len(output), "sha256": output_sha256,
        },
        "receipt": receipt,
    }


def derive_msvc_environment_root_transform(state: dict) -> dict:
    """Rederive the POSIX/Wine wrapper transform from manifest-pinned source."""
    require_posix_toolchain_backend(state, "MSVC environment root transform")
    policy = state["transport"]["msvc_environment"]["root_transform"]
    require(exact_json_equal(policy, {
                "schema": MSVC_ENVIRONMENT_ROOT_TRANSFORM_SCHEMA,
                "script": "wine/x86/msvcenv.sh",
            }), "MSVC environment root transform policy differs")
    matches = [
        item for item in state["compiler_support_files"]
        if item["path"] == policy["script"]
    ]
    require(len(matches) == 1,
            "MSVC environment transform source is not uniquely pinned")
    support = matches[0]
    compiler_root_value = state.get("compiler_root")
    require(isinstance(compiler_root_value, str) and compiler_root_value,
            "MSVC environment logical compiler root is absent")
    compiler_root = lexical_absolute_path(Path(compiler_root_value))
    source = lexical_absolute_path(Path(support["absolute_path"]))
    expected_source = compiler_root.joinpath(
        *PurePosixPath(policy["script"]).parts
    )
    compiler = lexical_absolute_path(Path(state["compiler_path"]))
    require(
        source == expected_source and source.resolve(strict=True) == source
        and compiler.is_relative_to(compiler_root),
        "MSVC environment transform source/root mapping differs",
    )
    metadata = source.stat(follow_symlinks=False)
    require(stat.S_ISREG(metadata.st_mode) and not source.is_symlink(),
            "MSVC environment transform source is not regular")
    data = active_build_authority().read_external_bytes(source)
    transformed = render_msvc_environment_root_transform(
        data, source_path=source, source_sha256=support["sha256"],
        logical_root=compiler_root,
        source_mode=stat.S_IMODE(metadata.st_mode),
    )
    transformed.update({
        "source": source, "logical_root": compiler_root,
        "source_sha256": support["sha256"],
    })
    return transformed


def render_msvc_wrapper_invocation_transform(
    source: bytes, *, source_path: Path, source_sha256: str,
    script: str, source_mode: int, held_bash: Path,
) -> dict:
    """Make one pinned wrapper call wine-msvc through strict-PATH bash."""
    require(isinstance(source, bytes)
            and sha256_bytes(source) == source_sha256,
            "MSVC wrapper transform source hash differs")
    require(source.count(MSVC_WRAPPER_WINE_CALL) == 1,
            "MSVC wrapper transform requires one exact wine-msvc call")
    held_bash = lexical_absolute_path(held_bash)
    held_bash_text = str(held_bash)
    require(
        held_bash.is_absolute() and held_bash.anchor == "/"
        and "\\" not in held_bash_text and "'" not in held_bash_text
        and all(ord(character) >= 0x20 and ord(character) != 0x7f
                for character in held_bash_text),
        "MSVC wrapper held bash path is not safely representable",
    )
    replacement = (
        f"'{held_bash_text}' ".encode("utf-8") + MSVC_WRAPPER_WINE_CALL
    )
    output = source.replace(
        MSVC_WRAPPER_WINE_CALL, replacement, 1
    )
    mode = source_mode & 0o555
    output_sha256 = sha256_bytes(output)
    return {
        "data": output,
        "record": {
            "mode": mode, "size": len(output), "sha256": output_sha256,
        },
        "receipt": {
            "schema": MSVC_WRAPPER_INVOCATION_TRANSFORM_SCHEMA,
            "script": script,
            "source_path": str(lexical_absolute_path(source_path)),
            "source_sha256": source_sha256,
            "generator_version": MSVC_WRAPPER_INVOCATION_TRANSFORM_GENERATOR,
            "held_bash": held_bash_text,
            "output_sha256": output_sha256,
            "output_size": len(output),
        },
    }


def render_msvc_wine_argument_transform(
    source: bytes, *, source_path: Path, source_sha256: str, source_mode: int,
) -> dict:
    """Make wine-msvc resolve absolute argument parents inside held Z."""
    require(isinstance(source, bytes)
            and sha256_bytes(source) == source_sha256,
            "MSVC argument transform source hash differs")
    require(source.count(MSVC_WINE_ARGUMENT_DIRECTORY_PREDICATE) == 1,
            "MSVC argument transform requires one exact directory predicate")
    replacement = (
        b'{ [ -n "${ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT:-}" ] && '
        b'[ -d "${ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT}'
        b'$(dirname "$path")" ] || exit 97; }'
    )
    output = source.replace(
        MSVC_WINE_ARGUMENT_DIRECTORY_PREDICATE, replacement, 1
    )
    mode = source_mode & 0o555
    output_sha256 = sha256_bytes(output)
    return {
        "data": output,
        "record": {
            "mode": mode, "size": len(output), "sha256": output_sha256,
        },
        "receipt": {
            "schema": MSVC_WINE_ARGUMENT_TRANSFORM_SCHEMA,
            "source_path": str(lexical_absolute_path(source_path)),
            "source_sha256": source_sha256,
            "generator_version": MSVC_WINE_ARGUMENT_TRANSFORM_GENERATOR,
            "environment_variable": "ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT",
            "output_sha256": output_sha256,
            "output_size": len(output),
        },
    }


def derive_msvc_wine_argument_transform(state: dict) -> dict:
    """Rederive the exact projected-path predicate from its pinned source."""
    require_posix_toolchain_backend(state, "MSVC argument path transform")
    policy = state["transport"]["msvc_environment"][
        "argument_path_transform"
    ]
    require(policy.get("schema") == MSVC_WINE_ARGUMENT_TRANSFORM_SCHEMA
            and policy.get("script") == "wine/x86/wine-msvc.sh",
            "MSVC argument path transform policy differs")
    compiler_root = lexical_absolute_path(Path(state["compiler_root"]))
    source = compiler_root.joinpath(*PurePosixPath(policy["script"]).parts)
    matches = [
        item for item in state["compiler_support_files"]
        if item["absolute_path"] == str(source)
    ]
    require(len(matches) == 1 and source.resolve(strict=True) == source,
            "MSVC argument transform source is not uniquely pinned")
    metadata = source.stat(follow_symlinks=False)
    require(stat.S_ISREG(metadata.st_mode) and not source.is_symlink(),
            "MSVC argument transform source is not regular")
    transformed = render_msvc_wine_argument_transform(
        active_build_authority().read_external_bytes(source),
        source_path=source, source_sha256=matches[0]["sha256"],
        source_mode=stat.S_IMODE(metadata.st_mode),
    )
    transformed.update({
        "source": source, "source_sha256": matches[0]["sha256"],
        "role": "wine_msvc_transport", "script": policy["script"],
    })
    return transformed


def derive_msvc_wrapper_invocation_transforms(state: dict) -> list[dict]:
    """Rederive every exact wrapper source/output receipt from manifest pins."""
    require_posix_toolchain_backend(state, "MSVC wrapper invocation transform")
    policy = state["transport"]["msvc_environment"][
        "wrapper_invocation_transform"
    ]
    require(policy.get("schema")
            == MSVC_WRAPPER_INVOCATION_TRANSFORM_SCHEMA,
            "MSVC wrapper invocation transform policy differs")
    compiler_root_value = state.get("compiler_root")
    require(isinstance(compiler_root_value, str) and compiler_root_value,
            "MSVC wrapper logical compiler root is absent")
    compiler_root = lexical_absolute_path(Path(compiler_root_value))
    held_bash = runtime_bin_path(Path(state["build_dir"])) / "bash"
    candidates = {
        str(lexical_absolute_path(Path(state["compiler_path"]))): {
            "sha256": state["compiler_sha256"], "role": "compiler_wrapper",
        },
    }
    expected_roles = {
        "wine/x86/cl": "compiler_wrapper",
        "wine/x86/rc": "rc_wrapper",
        "wine/x86/lib": "lib_wrapper",
        "wine/x86/link": "link_wrapper",
    }
    for item in state["compiler_support_files"]:
        relative = item["path"]
        if relative in expected_roles:
            candidates[item["absolute_path"]] = {
                "sha256": item["sha256"], "role": expected_roles[relative],
            }
    terminal_link = state.get("terminal_producers", {}).get("link")
    if terminal_link is not None:
        for role in ("rc_wrapper", "lib_wrapper", "link_wrapper"):
            tool = terminal_link_tool(state, role)
            candidates[tool["absolute_path"]] = {
                "sha256": tool["sha256"], "role": role,
            }
    result = []
    for script in policy["scripts"]:
        source = compiler_root.joinpath(*PurePosixPath(script).parts)
        source = lexical_absolute_path(source)
        candidate = candidates.get(str(source))
        require(candidate is not None
                and candidate["role"] == expected_roles[script]
                and source.resolve(strict=True) == source,
                f"MSVC wrapper transform source is not a pinned tool: {script}")
        metadata = source.stat(follow_symlinks=False)
        require(stat.S_ISREG(metadata.st_mode) and not source.is_symlink(),
                f"MSVC wrapper transform source is not regular: {script}")
        data = active_build_authority().read_external_bytes(source)
        transformed = render_msvc_wrapper_invocation_transform(
            data, source_path=source,
            source_sha256=candidate["sha256"], script=script,
            source_mode=stat.S_IMODE(metadata.st_mode), held_bash=held_bash,
        )
        transformed.update({
            "source": source, "source_sha256": candidate["sha256"],
            "role": candidate["role"], "script": script,
        })
        result.append(transformed)
    return result


def is_system_direct_runtime(runtime: dict) -> bool:
    return runtime.get("materialization") == "system_direct_immutable_v1"


def validate_system_direct_runtime(runtime: dict, *, hash_content: bool) -> dict:
    """Authenticate one canonical root-owned Darwin system executable."""
    path = lexical_absolute_path(Path(runtime["absolute_path"]))
    require(
        str(path).startswith(("/bin/", "/usr/bin/"))
        and path.resolve(strict=True) == path and not path.is_symlink(),
        f"system-direct runtime path is not canonical: {path}",
    )
    metadata = path.stat(follow_symlinks=False)
    require(
        stat.S_ISREG(metadata.st_mode) and metadata.st_uid == 0
        and bool(metadata.st_mode & 0o111)
        and not (stat.S_IMODE(metadata.st_mode) & 0o022),
        f"system-direct runtime metadata differs: {path}",
    )
    if hash_content:
        require(sha256_file(path) == runtime["sha256"],
                f"system-direct runtime hash differs: {path}")
    return {
        "name": runtime["name"], "path": str(path),
        "sha256": runtime["sha256"],
        "mode": stat.S_IMODE(metadata.st_mode),
        "owner": metadata.st_uid,
        "identity": list(active_build_authority().stable_regular_file_identity(path)),
    }


def system_direct_runtime_records(
    state: dict, *, hash_content: bool,
) -> list[dict]:
    return [
        validate_system_direct_runtime(item, hash_content=hash_content)
        for item in state["runtime_executables"]
        if is_system_direct_runtime(item)
    ]


def runtime_target_path(build_dir: Path, runtime: dict) -> Path:
    # The pinned host runtime executes in place.  Its authenticity comes from
    # the per-entry sha256 pin re-verified at every runtime-bin validation,
    # not from a private copy: a copied macOS Wine bundle cannot load its
    # 32-bit builtins (kernel32 c0000135), and output gates - not runtime
    # residency - are what carry byte-identity authority.
    return Path(runtime["absolute_path"])


def expected_toolchain_snapshot_destinations(
    state: dict, build_dir: Path,
) -> tuple[dict, dict, dict, dict, list[dict], dict]:
    """Independently derive durable toolchain destinations from manifest pins."""
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    z_root = root / "z"
    host_root = root / "host"
    prefix_root = root / "prefix-template"
    expected_z = new_snapshot_destination_expectation(z_root)
    expected_host = new_snapshot_destination_expectation(host_root)
    expected_prefix = new_snapshot_destination_expectation(prefix_root)
    environment_transform = derive_msvc_environment_root_transform(state)
    wrapper_transforms = derive_msvc_wrapper_invocation_transforms(state)
    argument_transform = derive_msvc_wine_argument_transform(state)
    transforms_by_source = {
        str(environment_transform["source"]): environment_transform,
        str(argument_transform["source"]): argument_transform,
        **{str(item["source"]): item for item in wrapper_transforms},
    }

    guest_files = [
        (Path(state["compiler_path"]), state["compiler_sha256"], "compiler"),
        *(
            (Path(item["absolute_path"]), item["sha256"], "compiler support")
            for item in state["compiler_support_files"]
        ),
        *(
            (Path(item["absolute_path"]), item["sha256"], "producer support")
            for item in state["producer_support_files"]
        ),
    ]
    terminal_link = state.get("terminal_producers", {}).get("link")
    if terminal_link is not None:
        guest_files.extend(
            (Path(item["absolute_path"]), item["sha256"], "terminal LINK tool")
            for item in terminal_link["tools"]
        )
    for source, expected_sha, context in guest_files:
        transform = transforms_by_source.get(str(source))
        if transform is not None:
            require(expected_sha == transform["source_sha256"],
                    "MSVC transport transform source pin conflicts")
            record = transform["record"]
        else:
            record = authenticated_external_snapshot_file(
                source, expected_sha, context
            )
        add_expected_snapshot_file(
            expected_z, absolute_snapshot_seat(z_root, source), record,
        )
    for tree, source_key, context in [
        *( (item, "absolute_path", "toolchain sealed include")
           for item in state["sealed_include_trees"] ),
        *( (item, "absolute_path", "toolchain sealed library")
           for item in (terminal_link or {}).get("library_trees", []) ),
    ]:
        source = Path(tree[source_key])
        snapshot = authenticated_source_tree_snapshot(source, tree, context)
        add_expected_snapshot_tree(
            expected_z, absolute_snapshot_seat(z_root, source),
            snapshot["records"],
        )
    for tree in state["runtime_closure"]["membership_roots"]:
        source = Path(tree["path"])
        snapshot = authenticated_source_tree_snapshot(
            source, tree, "Wine runtime membership"
        )
        _validate_wine_runtime_symlink_targets(
            source, snapshot["records"], "Wine runtime membership"
        )
        add_expected_snapshot_tree(
            expected_host, absolute_snapshot_seat(host_root, source),
            snapshot["records"], directory_policy="readonly_source",
        )
    host_files = {}
    for item in state["runtime_executables"]:
        if is_system_direct_runtime(item):
            continue
        host_files[item["absolute_path"]] = item["sha256"]
    for item in state["runtime_closure"]["loaded_files"]:
        previous = host_files.get(item["path"])
        require(previous is None or previous == item["sha256"],
                f"runtime source has conflicting pins: {item['path']}")
        host_files[item["path"]] = item["sha256"]
    for logical in sorted(host_files):
        source = Path(logical)
        add_expected_snapshot_file(
            expected_host, absolute_snapshot_seat(host_root, source),
            authenticated_external_snapshot_file(
                source, host_files[logical], "Wine loaded runtime"
            ),
        )
    for item in state["transport"]["prefix_template_files"]:
        source = Path(item["path"])
        record = authenticated_external_snapshot_file(
            source, item["sha256"], "Wine prefix template"
        )
        require(stat.S_IMODE(source.stat(follow_symlinks=False).st_mode)
                == item["mode"],
                f"Wine prefix template source mode differs: {source}")
        add_expected_snapshot_file(
            expected_prefix, prefix_root / item["name"], record
        )

    for logical in required_absent_toolchain_paths(state):
        seat = absolute_snapshot_seat(z_root, logical)
        require(
            _snapshot_destination_relative(expected_z, seat)
            not in expected_z["records"]
            and authority.lstat(seat) is None,
            f"required-absent toolchain file entered its snapshot: {logical}",
        )
    return (
        expected_z, expected_host, expected_prefix,
        environment_transform["receipt"],
        [item["receipt"] for item in wrapper_transforms],
        argument_transform["receipt"],
    )


def _materialize_toolchain_snapshot(state: dict, build_dir: Path) -> dict:
    """Copy every non-source compiler/runtime input into build authority."""
    require_posix_toolchain_backend(state, "toolchain materialization")
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    previous_cache = authority.snapshot_validation_cache.pop(
        "toolchain:" + str(root), None
    )
    if previous_cache is not None:
        previous_cache["holder"].close()
    z_root = root / "z"
    host_root = root / "host"
    prefix_root = root / "prefix-template"
    authority.remove_tree(root)
    for directory in (z_root, host_root, prefix_root):
        authority.mkdirs(directory)
    expected_z = new_snapshot_destination_expectation(z_root)
    expected_host = new_snapshot_destination_expectation(host_root)
    expected_prefix = new_snapshot_destination_expectation(prefix_root)
    environment_transform = derive_msvc_environment_root_transform(state)
    wrapper_transforms = derive_msvc_wrapper_invocation_transforms(state)
    argument_transform = derive_msvc_wine_argument_transform(state)
    transforms_by_source = {
        str(environment_transform["source"]): environment_transform,
        str(argument_transform["source"]): argument_transform,
        **{str(item["source"]): item for item in wrapper_transforms},
    }

    copied_guest_by_path = {}
    copied_guest_source_sha_by_path = {}

    def copy_guest(source: Path, expected_sha256: str) -> None:
        key = str(source)
        previous = copied_guest_by_path.get(key)
        if previous is not None:
            require(copied_guest_source_sha_by_path[key] == expected_sha256,
                    f"guest toolchain file has conflicting pins: {source}")
            return
        destination = absolute_snapshot_seat(z_root, source)
        transform = transforms_by_source.get(str(source))
        if transform is not None:
            require(expected_sha256 == transform["source_sha256"],
                    "MSVC transport transform source pin conflicts")
            transformed = transform["record"]
            authority.atomic_write(
                destination, transform["data"],
                mode=transformed["mode"],
            )
            record = {
                "logical_path": str(source),
                "snapshot_path": str(destination),
                **transformed,
            }
        else:
            record = copy_external_file_to_snapshot(
                source, destination, expected_sha256,
            )
        copied_guest_by_path[key] = record
        copied_guest_source_sha_by_path[key] = expected_sha256
        add_expected_snapshot_file(expected_z, destination, record)

    compiler = Path(state["compiler_path"])
    copy_guest(compiler, state["compiler_sha256"])
    for support in [
        *state["compiler_support_files"],
        *state["producer_support_files"],
    ]:
        copy_guest(Path(support["absolute_path"]), support["sha256"])
    terminal_link = state.get("terminal_producers", {}).get("link")
    if terminal_link is not None:
        for tool in terminal_link["tools"]:
            copy_guest(Path(tool["absolute_path"]), tool["sha256"])
    copied_guest_files = [
        copied_guest_by_path[path] for path in sorted(copied_guest_by_path)
    ]
    for tree in state["sealed_include_trees"]:
        source = Path(tree["absolute_path"])
        destination = absolute_snapshot_seat(z_root, source)
        source_snapshot = copy_external_tree_to_snapshot(
            source, destination, tree,
        )
        add_expected_snapshot_tree(
            expected_z, destination, source_snapshot["records"]
        )
    if terminal_link is not None:
        for tree in terminal_link["library_trees"]:
            source = Path(tree["absolute_path"])
            destination = absolute_snapshot_seat(z_root, source)
            source_snapshot = copy_external_tree_to_snapshot(
                source, destination, tree,
            )
            add_expected_snapshot_tree(
                expected_z, destination, source_snapshot["records"]
            )
    # Consume a build-local copy of the entire bounded Wine bundle closure.
    # The selected loaded-file pins below remain an exact executable closure
    # audit, while these tree copies prevent an untraced resource/builtin lookup
    # from falling back to a mutable external bundle during the compiler run.
    for tree in state["runtime_closure"]["membership_roots"]:
        source = Path(tree["path"])
        destination = absolute_snapshot_seat(host_root, source)
        source_proof = []
        copy_wine_runtime_tree_to_snapshot(
            source, destination, tree, source_proof=source_proof,
            defer_destination_validation=True,
        )
        require(len(source_proof) == 1,
                "Wine runtime copy produced no unique source proof")
        source_snapshot = source_proof[0]
        _validate_wine_runtime_symlink_targets(
            source, source_snapshot["records"], "Wine runtime membership"
        )
        add_expected_snapshot_tree(
            expected_host, destination, source_snapshot["records"],
            directory_policy="readonly_source",
        )

    copied_host_files = []
    host_sources: dict[str, tuple[Path, str]] = {}
    for runtime in state["runtime_executables"]:
        if is_system_direct_runtime(runtime):
            continue
        source = Path(runtime["absolute_path"])
        host_sources[str(source)] = (source, runtime["sha256"])
    for loaded in state["runtime_closure"]["loaded_files"]:
        source = Path(loaded["path"])
        previous = host_sources.get(str(source))
        require(previous is None or previous[1] == loaded["sha256"],
                f"runtime snapshot has conflicting hash pins: {source}")
        host_sources[str(source)] = (source, loaded["sha256"])
    for source, expected in (host_sources[key] for key in sorted(host_sources)):
        destination = absolute_snapshot_seat(host_root, source)
        record = copy_external_file_to_snapshot(
            source, absolute_snapshot_seat(host_root, source), expected,
        )
        copied_host_files.append(record)
        add_expected_snapshot_file(expected_host, destination, record)

    copied_prefix_files = []
    for item in state["transport"]["prefix_template_files"]:
        source = Path(item["path"])
        record = copy_external_file_to_snapshot(
            source, prefix_root / item["name"], item["sha256"],
        )
        require(stat.S_IMODE(source.stat().st_mode) == item["mode"],
                f"Wine prefix template mode differs: {source}")
        copied_prefix_files.append(record)
        add_expected_snapshot_file(
            expected_prefix, prefix_root / item["name"], record
        )

    z_snapshot = validate_expected_snapshot_destination(
        expected_z, "toolchain virtual-Z snapshot"
    )
    host_snapshot = validate_expected_snapshot_destination(
        expected_host, "toolchain host-runtime snapshot"
    )
    prefix_snapshot = validate_expected_snapshot_destination(
        expected_prefix, "toolchain prefix-template snapshot"
    )
    descriptor = {
        "schema": 1,
        "status": "IMMUTABLE_VIRTUAL_Z_TOOLCHAIN_SNAPSHOT",
        "transport_schema": state["transport"]["schema"],
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "root": str(root),
        "z": _tree_pin(z_snapshot),
        "host": _tree_pin(host_snapshot),
        "prefix_template": _tree_pin(prefix_snapshot),
        "guest_files": copied_guest_files,
        "host_files": copied_host_files,
        "prefix_files": copied_prefix_files,
        "msvc_environment_transform": environment_transform["receipt"],
        "msvc_wrapper_transforms": [
            item["receipt"] for item in wrapper_transforms
        ],
        "msvc_argument_transform": argument_transform["receipt"],
        "system_direct_runtimes": system_direct_runtime_records(
            state, hash_content=True
        ),
    }
    descriptor_path = root / "snapshot.json"
    descriptor_bytes = atomic_json(descriptor_path, descriptor)
    holder = authority.retain_directories([
        root, z_root, host_root, prefix_root,
    ])
    require(holder.read_bytes(descriptor_path) == descriptor_bytes,
            "toolchain descriptor changed before hold")
    holder.revalidate()
    authority.snapshot_validation_cache["toolchain:" + str(root)] = {
        "descriptor": descriptor,
        "descriptor_sha256": sha256_bytes(descriptor_bytes),
        "trees": {
            str(z_root): z_snapshot,
            str(host_root): host_snapshot,
            str(prefix_root): prefix_snapshot,
        },
        "holder": holder,
        "finalized": False,
    }

    # Expose only internal snapshot executables.  Keeping their original
    # absolute suffix under host/ preserves Wine's @executable_path bundle
    # lookups while the strict PATH has no ambient host directory.
    directory = runtime_bin_path(build_dir)
    authority.remove_tree(directory)
    authority.mkdirs(directory)
    expected = {}
    for runtime in state["runtime_executables"]:
        absolute = runtime.get("absolute_path")
        require(isinstance(absolute, str),
                f"runtime path was not validated: {runtime['name']}")
        expected[runtime["name"]] = runtime_target_path(build_dir, runtime)
    for name, target in expected.items():
        link = directory / name
        authority.atomic_symlink(link, target)
    validate_runtime_bin(state, build_dir)
    return descriptor


def materialize_toolchain_snapshot(state: dict, build_dir: Path) -> dict:
    """Failure-atomically materialize toolchain and strict runtime seats."""
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    runtime = runtime_bin_path(build_dir)
    try:
        return _materialize_toolchain_snapshot(state, build_dir)
    except BaseException:
        cached = authority.snapshot_validation_cache.pop(
            "toolchain:" + str(root), None
        )
        if cached is not None:
            cached["holder"].close()
        rollback_exact_private_roots(
            authority, [runtime, root],
            "toolchain/runtime snapshot rollback could not be proven",
        )
        raise


def validate_toolchain_snapshot(state: dict, build_dir: Path) -> dict:
    require_posix_toolchain_backend(state, "toolchain snapshot validation")
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    descriptor_path = root / "snapshot.json"
    raw = authority.read_bytes(descriptor_path)
    document = strict_json_loads(raw)
    require(isinstance(document, dict), "toolchain snapshot audit is invalid")
    exact_audit_keys(
        document,
        {
            "schema", "status", "transport_schema", "toolchain_fingerprint",
            "root", "z", "host", "prefix_template", "guest_files",
            "host_files", "prefix_files", "msvc_environment_transform",
            "msvc_wrapper_transforms", "msvc_argument_transform",
            "system_direct_runtimes",
        },
        "toolchain snapshot audit",
    )
    require(type(document.get("schema")) is int and document.get("schema") == 1
            and document.get("status")
            == "IMMUTABLE_VIRTUAL_Z_TOOLCHAIN_SNAPSHOT"
            and document.get("transport_schema") == "wine_virtual_z_v1"
            and document.get("toolchain_fingerprint")
            == state["toolchain_fingerprint"]
            and authority.parts(Path(document.get("root", "")))
            == authority.parts(root),
            "toolchain snapshot identity differs")
    cache_key = "toolchain:" + str(root)
    cached = authority.snapshot_validation_cache.get(cache_key)
    if cached is not None:
        require(cached["descriptor_sha256"] == sha256_bytes(raw)
                and exact_json_equal(cached["descriptor"], document),
                "held toolchain snapshot descriptor changed")
        cached["holder"].revalidate()
        require_exact_build_namespace(
            authority, root, {
                "z": "directory", "host": "directory",
                "prefix-template": "directory", "snapshot.json": "file",
            }, "held toolchain snapshot root", replace_pin=True,
        )
        return document
    require(active_resident_receipt_ledger() is None,
            "resident toolchain snapshot lacks materialization authority")
    require(raw == canonical_json_bytes(document),
            "toolchain descriptor differs from canonical resident bytes")
    trees = {}
    expected_destinations = expected_toolchain_snapshot_destinations(
        state, build_dir
    )
    for (key, path), expectation in zip((
        ("z", root / "z"),
        ("host", root / "host"),
        ("prefix_template", root / "prefix-template"),
    ), expected_destinations[:3]):
        observed = validate_expected_snapshot_destination(
            expectation, f"toolchain fresh {key} snapshot"
        )
        require(exact_json_equal(document.get(key), _tree_pin(observed)),
                f"toolchain snapshot {key} tree differs")
        trees[str(path)] = observed
    require(exact_json_equal(
                document.get("msvc_environment_transform"),
                expected_destinations[3],
            ), "toolchain MSVC environment transform receipt differs")
    require(exact_json_equal(
                document.get("msvc_wrapper_transforms"),
                expected_destinations[4],
            ), "toolchain MSVC wrapper transform receipts differ")
    require(exact_json_equal(
                document.get("msvc_argument_transform"),
                expected_destinations[5],
            ), "toolchain MSVC argument transform receipt differs")
    require(exact_json_equal(
                document.get("system_direct_runtimes"),
                system_direct_runtime_records(state, hash_content=True),
            ), "toolchain system-direct runtime receipts differ")
    require_exact_build_namespace(
        authority, root, {
            "z": "directory", "host": "directory",
            "prefix-template": "directory", "snapshot.json": "file",
        }, "toolchain snapshot root",
    )
    # Complete every cold validation before publishing the fast-path cache.
    # A caller that catches a one-shot loaded-image failure must not be able to
    # retry through a partially authenticated holder.
    validate_toolchain_loaded_runtime_files(state, build_dir)
    holder = authority.retain_directories([
        root, root / "z", root / "host", root / "prefix-template"
    ])
    holder.read_bytes(descriptor_path)
    holder.revalidate()
    authority.snapshot_validation_cache[cache_key] = {
        "descriptor": document, "descriptor_sha256": sha256_bytes(raw),
        "trees": trees, "holder": holder, "finalized": False,
    }
    return document


def validate_toolchain_loaded_runtime_files(state: dict, build_dir: Path) -> None:
    """Verify the small exact host image set used by each producer launch."""
    authority = active_build_authority()
    host = toolchain_snapshot_path(build_dir) / "host"
    expected = {}
    for item in state["runtime_executables"]:
        if is_system_direct_runtime(item):
            continue
        expected[item["absolute_path"]] = item["sha256"]
    for item in state["runtime_closure"]["loaded_files"]:
        previous = expected.get(item["path"])
        require(previous is None or previous == item["sha256"],
                f"Wine loaded runtime pin conflicts: {item['path']}")
        expected[item["path"]] = item["sha256"]
    for logical, expected_sha in sorted(expected.items()):
        path = absolute_snapshot_seat(host, Path(logical))
        metadata = authority.lstat(path)
        require(metadata is not None and stat.S_ISREG(metadata.st_mode)
                and not (stat.S_IMODE(metadata.st_mode) & 0o222)
                and sha256_file(path) == expected_sha,
                f"held Wine loaded runtime file differs: {logical}")


def finalize_toolchain_snapshot_validation(state: dict, build_dir: Path) -> None:
    """Perform the one bounded terminal rescan of the held shared snapshot."""
    require_posix_toolchain_backend(state, "toolchain final validation")
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    cache_key = "toolchain:" + str(root)
    cached = authority.snapshot_validation_cache.get(cache_key)
    require(cached is not None,
            "toolchain snapshot was not held by the resident transaction")
    if cached["finalized"]:
        return
    cached["holder"].revalidate()
    for path_text, expected in cached["trees"].items():
        observed = canonical_tree_snapshot(
            Path(path_text), hash_files=True, include_metadata_records=True
        )
        require_held_snapshot_unchanged(
            expected, observed,
            f"held toolchain snapshot {path_text}",
        )
    validate_toolchain_loaded_runtime_files(state, build_dir)
    require(exact_json_equal(
                cached["descriptor"].get("system_direct_runtimes"),
                system_direct_runtime_records(state, hash_content=True),
            ), "system-direct runtime changed before completion")
    runtime_cache = cached.get("runtime_bin")
    if runtime_cache is not None:
        runtime_cache["holder"].revalidate()
    cached["finalized"] = True


def materialize_runtime_bin(state: dict, build_dir: Path) -> Path:
    """Create the toolchain snapshot and its strict internal runtime PATH."""
    authority = active_build_authority()
    root = toolchain_snapshot_path(build_dir)
    runtime = runtime_bin_path(build_dir)
    try:
        materialize_toolchain_snapshot(state, build_dir)
        return validate_runtime_bin(state, build_dir)
    except BaseException:
        cached = authority.snapshot_validation_cache.pop(
            "toolchain:" + str(root), None
        )
        if cached is not None:
            cached["holder"].close()
        rollback_exact_private_roots(
            authority, [runtime, root],
            "runtime/toolchain materialization rollback could not be proven",
        )
        raise


def materialize_compiler_slots(build_dir: Path) -> Path:
    """Create the fixed semaphore namespace during the exclusive inventory."""
    authority = active_build_authority()
    directory = authority.build_root / "byte-identity/locks/compiler-slots"
    authority.mkdirs(directory)
    expected = {f"slot-{index}.lock" for index in range(MAX_COMPILER_PROCESSES)}
    existing = set(authority.list_names(directory))
    require(existing.issubset(expected),
            "compiler semaphore directory contains unexpected entries")
    for name in sorted(expected):
        handle = authority.open_lock(directory / name)
        handle.close()
    require(set(authority.list_names(directory)) == expected,
            "compiler semaphore namespace is incomplete")
    return directory


def normalized_inventory_entries(
    state: dict, source_dir: Path, build_dir: Path,
    raw_entries: list[list[str]],
) -> list[dict]:
    require(raw_entries, "configure-time C/C++ inventory must not be empty")
    declared_targets = {item["target"] for item in state["target_policies"]}
    listed_owners = {
        (item["target"], item["source"]) for item in state["translation_units"]
    }
    owners = set()
    audit_paths = set()
    entries = []
    overlay_state = state.get("source_overlay") or {
        "outputs": [], "effective_by_path": {}, "policy_sha256": None,
    }
    overlay_by_path = {
        item["logical_path"]: item
        for item in overlay_state["outputs"]
    }
    implicit_ordinals: dict[str, int] = defaultdict(int)
    for index, values in enumerate(raw_entries):
        require(isinstance(values, list) and len(values) in (3, 4, 5),
                f"inventory entry {index} must contain target, source, language, optional ordinal, and optional source authority")
        target, source_value, language = values[:3]
        if len(values) >= 4:
            require(values[3].isdigit(),
                    f"inventory entry {index} ordinal is invalid")
            target_ordinal = int(values[3])
        else:
            target_ordinal = implicit_ordinals[target]
        implicit_ordinals[target] = max(
            implicit_ordinals[target], target_ordinal + 1
        )
        source_authority = values[4] if len(values) == 5 else "CLEAN_SOURCE"
        require(source_authority in {"CLEAN_SOURCE", "TYPED_SOURCE_OVERLAY"},
                f"inventory entry {index} source authority differs")
        require(target in declared_targets,
                f"inventory entry target is undeclared: {target}")
        require(language in SUPPORTED_SOURCE_LANGUAGES,
                f"inventory entry has unsupported effective language: {language}")
        source_path = lexical_absolute_path(Path(source_value))
        try:
            source_relative = source_path.relative_to(source_dir.resolve()).as_posix()
        except ValueError as error:
            raise ByteIdentityError(
                f"inventory source is outside the source tree: {source_path}"
            ) from error
        source_relative = canonical_source_relative_path(
            source_relative, f"inventory entry {index} source"
        )
        require(
            source_path
            == source_overlay_logical_path(source_dir, source_relative),
            f"inventory source has a noncanonical spelling: {source_path}",
        )
        overlay_output = overlay_by_path.get(source_relative)
        if overlay_output is None:
            require(source_authority == "CLEAN_SOURCE" and source_path.is_file(),
                    f"inventory entry source is absent/unowned: {source_path}")
        else:
            require(source_authority == "TYPED_SOURCE_OVERLAY",
                    f"inventory overlay source authority differs: {source_path}")
            if overlay_output["clean"]["state"] == "absent":
                require(not source_path.exists(),
                        f"generated-only inventory source exists: {source_path}")
            else:
                require(source_path.is_file(),
                        f"clean overlay inventory source is absent: {source_path}")
        owner = (target, source_relative)
        require(owner not in owners, f"duplicate inventory owner: {owner}")
        owners.add(owner)
        listed = owner in listed_owners
        audit = (
            audit_object_path(build_dir, target, source_relative)
            if listed else audit_unlisted_path(build_dir, target, source_relative)
        )
        require(str(audit) not in audit_paths,
                f"duplicate inventory audit output: {audit}")
        audit_paths.add(str(audit))
        normalized_entry = {
            "target": target,
            "source": source_relative,
            "source_path": str(source_path),
            "language": language,
            "target_ordinal": target_ordinal,
            "listed": listed,
            "audit": str(audit),
            "output_role": "cmake_compiler_object_from_Fo",
        }
        if overlay_state.get("enabled"):
            normalized_entry.update({
                "source_authority": source_authority,
                "effective_source_sha256": (
                    overlay_state["effective_by_path"][
                        source_relative
                    ]["sha256"]
                    if overlay_output is not None else sha256_file(source_path)
                ),
                "source_overlay_policy_sha256": (
                    overlay_state["policy_sha256"]
                    if overlay_output is not None else None
                ),
            })
        entries.append(normalized_entry)
    require(all(
        len(values) == len(set(values))
        for values in (
            [item["target_ordinal"] for item in entries
             if item["target"] == target]
            for target in {item["target"] for item in entries}
        )
    ), "configure inventory target source ordinals are duplicated")
    entries.sort(key=lambda item: (item["target"], item["target_ordinal"]))
    require(listed_owners.issubset(owners),
            "configure inventory omits a manifest-listed translation unit")
    return entries


def normalized_inventory_targets(
    state: dict, raw_targets: list[list[str]], *, authoritative: bool,
) -> list[dict]:
    """Attest every non-imported user target, not only compiler owners."""
    require(raw_targets, "configure-time target inventory must not be empty")
    result = []
    names = set()
    for index, values in enumerate(raw_targets):
        require(isinstance(values, list) and len(values) == 3,
                f"target inventory entry {index} must contain name, type, and default state")
        name, kind, default_text = values
        require(isinstance(name, str) and TARGET_RE.fullmatch(name) is not None
                and name not in names,
                f"target inventory entry {index} has an invalid or duplicate name")
        names.add(name)
        require(kind in SUPPORTED_TARGET_KINDS,
                f"target inventory entry {name} has unsupported type: {kind}")
        require(default_text in ("TRUE", "FALSE"),
                f"target inventory entry {name} has invalid default state")
        require(not (authoritative and kind == "NATIVE_TEST_OBJECTS_ONLY"),
                "test-only target kind is forbidden in an authoritative session")
        result.append({
            "target": name,
            "kind": kind,
            "default_build": default_text == "TRUE",
        })
    declared = {item["target"] for item in state["target_policies"]}
    require(declared.issubset(names),
            "configure target inventory omits a compiler-policy target")
    result.sort(key=lambda item: item["target"])
    return result


def _resolve_link_graph_token(token: str, context: str) -> list[str]:
    """Resolve only the tiny, explicit generator-expression grammar in use.

    The raw token remains in the inventory as evidence.  This helper produces
    the link-graph edges used to authorize generated LINK library inputs; an
    unrecognized expression is never treated as an inert string.
    """
    require(isinstance(token, str) and token and "\0" not in token
            and "\n" not in token and "\r" not in token,
            f"{context} is empty or unsafe")
    require("TARGET_OBJECTS:" not in token and "$<TARGET_OBJECTS" not in token,
            f"{context} injects an object expression")
    require(PurePosixPath(token.replace("\\", "/")).suffix.casefold()
            not in FORBIDDEN_OPAQUE_SOURCE_SUFFIXES,
            f"{context} injects an opaque object/archive payload")
    if not token.startswith("$<"):
        require("$<" not in token and ">" not in token,
                f"{context} contains a malformed generator expression")
        return [token]
    link_only = re.fullmatch(r"\$<LINK_ONLY:(.+)>", token)
    if link_only:
        return _resolve_link_graph_token(link_only.group(1), context)
    build_interface = re.fullmatch(r"\$<BUILD_INTERFACE:(.+)>", token)
    if build_interface:
        return _resolve_link_graph_token(build_interface.group(1), context)
    install_interface = re.fullmatch(r"\$<INSTALL_INTERFACE:.*>", token)
    if install_interface:
        return []
    conditional = re.fullmatch(
        r"\$<\$<BOOL:(0|1|ON|OFF|TRUE|FALSE)>:(.+)>", token,
        flags=re.IGNORECASE,
    )
    if conditional:
        enabled = conditional.group(1).casefold() in {"1", "on", "true"}
        return (
            _resolve_link_graph_token(conditional.group(2), context)
            if enabled else []
        )
    target_if_exists = re.fullmatch(r"\$<TARGET_NAME_IF_EXISTS:([^<>]+)>", token)
    if target_if_exists:
        return [target_if_exists.group(1)]
    raise ByteIdentityError(f"{context} uses an unsupported generator expression")


def normalized_link_graph(
    targets: list[dict], raw_counts: list[list[str]],
    raw_items: list[list[str]],
) -> list[dict]:
    target_names = {item["target"] for item in targets}
    counts: dict[tuple[str, str], int] = {}
    for index, values in enumerate(raw_counts):
        require(isinstance(values, list) and len(values) == 3,
                f"link graph count {index} must contain target/property/count")
        target, property_name, count_text = values
        require(target in target_names,
                f"link graph count target is not inventoried: {target}")
        require(property_name in NORMAL_TARGET_LINK_PROPERTIES,
                f"link graph property is unsupported: {property_name}")
        require(isinstance(count_text, str) and count_text.isdigit(),
                f"link graph count is invalid: {target}:{property_name}")
        key = (target, property_name)
        require(key not in counts,
                f"link graph count is duplicated: {target}:{property_name}")
        counts[key] = int(count_text)
    expected_keys = {
        (target, property_name)
        for target in target_names
        for property_name in NORMAL_TARGET_LINK_PROPERTIES
    }
    require(set(counts) == expected_keys,
            "link graph property/count universe is incomplete or extra")
    items: dict[tuple[str, str], list[str]] = defaultdict(list)
    for index, values in enumerate(raw_items):
        require(isinstance(values, list) and len(values) == 3,
                f"link graph item {index} must contain target/property/value")
        target, property_name, value = values
        key = (target, property_name)
        require(key in counts,
                f"link graph item has no declared property count: {key}")
        _resolve_link_graph_token(
            value, f"link graph {target}.{property_name}[{len(items[key])}]"
        )
        folded = value.casefold()
        if property_name in {
            "LINK_OPTIONS", "INTERFACE_LINK_OPTIONS", "LINK_FLAGS",
            "LINK_FLAGS_CONFIG",
        }:
            require(not any(marker in folded for marker in (
                "/defaultlib", "-defaultlib", "/nodefaultlib", "-nodefaultlib",
                "/include", "-include", "/wholearchive", "-wholearchive",
                "@", "shell:", "linker:",
            )), f"link graph {target}.{property_name} can inject a library/member")
        if property_name in {
            "INTERFACE_LINK_LIBRARIES_DIRECT",
            "INTERFACE_LINK_LIBRARIES_DIRECT_EXCLUDE",
        }:
            raise ByteIdentityError(
                f"link graph {target}.{property_name} is unsupported in the "
                "closed resident link plan"
            )
        if property_name == "LINK_LIBRARIES_STRATEGY":
            require(value == "REORDER_MINIMALLY",
                    f"link graph {target} has an unsupported library strategy")
        if property_name in {
            "LINK_INTERFACE_MULTIPLICITY",
            "LINK_INTERFACE_MULTIPLICITY_CONFIG",
        }:
            require(value.isdigit() and int(value) >= 1,
                    f"link graph {target}.{property_name} is invalid")
        items[key].append(value)
    require(all(len(items[key]) == count for key, count in counts.items()),
            "link graph item counts differ from CMake's exact property lengths")
    result = []
    for target in sorted(target_names):
        properties = {
            property_name: list(items[(target, property_name)])
            for property_name in NORMAL_TARGET_LINK_PROPERTIES
        }
        resolved_links = []
        for property_name in (
            "LINK_LIBRARIES", "INTERFACE_LINK_LIBRARIES",
            "LINK_INTERFACE_LIBRARIES_CONFIG",
        ):
            for index, token in enumerate(properties[property_name]):
                resolved_links.extend(_resolve_link_graph_token(
                    token, f"link graph {target}.{property_name}[{index}]"
                ))
        result.append({
            "target": target,
            "properties": properties,
            "resolved_links": resolved_links,
        })
    return result


def normalized_generator_standard_libraries(
    state: dict, configuration: str | None,
    base_count: str | None, base_items: list[str],
    config_count: str | None, config_items: list[str],
) -> dict | None:
    """Bind CMake's live generator-added library tail for this configuration."""
    link = state.get("terminal_producers", {}).get("link")
    if link is None:
        require(configuration is None and base_count is None
                and config_count is None and not base_items and not config_items,
                "generator standard libraries require a terminal link policy")
        return None
    require(configuration == "RelWithDebInfo",
            "generator standard-library configuration differs")
    require(isinstance(base_count, str) and base_count.isdigit()
            and isinstance(config_count, str) and config_count.isdigit(),
            "generator standard-library counts are absent or invalid")
    require(int(base_count) == len(base_items)
            and int(config_count) == len(config_items),
            "generator standard-library counts differ from their sequences")
    observed = {
        "configuration": configuration,
        "base": list(base_items),
        "configuration_specific": list(config_items),
    }
    require(all(isinstance(value, str)
                and re.fullmatch(r"[a-z0-9_+.\-]+\.lib", value)
                for value in [*base_items, *config_items]),
            "generator standard-library item is noncanonical")
    require(exact_json_equal(
        observed, link["generator_standard_libraries"]
    ), "live generator standard-library sequence differs from the manifest")
    return observed


def normalized_inventory_inputs(
    source_dir: Path, build_dir: Path, targets: list[dict],
    raw_inputs: list[list[str]],
) -> list[dict]:
    """Attest every admitted non-C/C++ source as non-emitting or produced."""
    target_names = {item["target"] for item in targets}
    result = []
    owners = set()
    implicit_ordinals: dict[str, int] = defaultdict(int)
    source_root = source_dir.resolve()
    for index, values in enumerate(raw_inputs):
        require(isinstance(values, list) and len(values) in (3, 4),
                f"noncompile input {index} must contain target, path, kind, and optional ordinal")
        target, source_value, kind = values[:3]
        if len(values) == 4:
            require(values[3].isdigit(),
                    f"noncompile input {index} ordinal is invalid")
            target_ordinal = int(values[3])
        else:
            target_ordinal = implicit_ordinals[target]
        implicit_ordinals[target] = max(
            implicit_ordinals[target], target_ordinal + 1
        )
        require(target in target_names,
                f"noncompile input target is not inventoried: {target}")
        require(kind in SUPPORTED_NONCOMPILE_INPUT_KINDS,
                f"noncompile input has unsupported kind: {kind}")
        source_path = Path(source_value).resolve(strict=True)
        require(source_path.is_file() and not source_path.is_symlink(),
                f"noncompile input is absent or redirected: {source_path}")
        try:
            source_relative = source_path.relative_to(source_root).as_posix()
        except ValueError as error:
            raise ByteIdentityError(
                f"noncompile input is outside the source tree: {source_path}"
            ) from error
        suffix = source_path.suffix.casefold()
        require(suffix not in FORBIDDEN_OPAQUE_SOURCE_SUFFIXES,
                f"opaque linker payload source is forbidden: {source_relative}")
        if kind == "RC":
            require(suffix == ".rc", f"RC input has a non-.rc suffix: {source_relative}")
        elif kind == "LINKER_DEF":
            require(suffix == ".def",
                    f"linker definition input has a non-.def suffix: {source_relative}")
        else:
            require(suffix in {".h", ".hh", ".hpp", ".hxx", ".inc", ".inl"},
                    f"header input has an unsupported suffix: {source_relative}")
        owner = (target, source_relative)
        require(owner not in owners, f"duplicate noncompile input owner: {owner}")
        owners.add(owner)
        record = {
            "target": target,
            "source": source_relative,
            "source_path": str(source_path),
            "kind": kind,
            "target_ordinal": target_ordinal,
            "source_sha256": sha256_file(source_path),
            "emission": (
                "resource_compiler_output" if kind == "RC"
                else "linker_definition_input" if kind == "LINKER_DEF"
                else "non_emitting_header"
            ),
        }
        if kind == "RC":
            record["audit"] = str(
                resource_audit_path(build_dir, target, source_relative)
            )
        result.append(record)
    result.sort(key=lambda item: (item["target"], item["target_ordinal"]))
    return result


def inventory_policy_payload(
    state: dict, cmake_module: Path, entries: list[dict],
    targets: list[dict], inputs: list[dict], link_graph: list[dict],
    generator_standard_libraries: dict | None,
) -> dict:
    return {
        "manifest_sha256": state["manifest_sha256"],
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "framework_tool_sha256": state["framework_tool_sha256"],
        "backend_tool_sha256": state["backend_tool_sha256"],
        "entropy_tool_sha256": state["entropy_tool_sha256"],
        "cmake_module": str(cmake_module.resolve()),
        "cmake_module_sha256": sha256_file(cmake_module.resolve()),
        "python_executable": state["python_executable"],
        "python_sha256": state["python_sha256"],
        "python_version": state["python_version"],
        "child_environment": state["child_environment"],
        "runtime_executables": state["runtime_executables"],
        "configured_compiler": state["compiler_path"],
        "targets": targets,
        "inputs": inputs,
        "link_graph": link_graph,
        "generator_standard_libraries": generator_standard_libraries,
        "entries": entries,
    }


def render_inventory_plan(inventory: dict) -> bytes:
    lines = ["# Generated atomically by tools/byte_identity.py; do not edit."]
    indices = [str(index) for index in range(len(inventory["entries"]))]
    append_cmake_list(lines, "ISLE_BYTE_IDENTITY_INVENTORY_INDICES", indices)
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_GRAPH_TARGET_INDICES",
        [str(index) for index in range(len(inventory["targets"]))],
    )
    append_cmake_list(
        lines, "ISLE_BYTE_IDENTITY_GRAPH_INPUT_INDICES",
        [str(index) for index in range(len(inventory["inputs"]))],
    )
    lines.extend(
        [
            f'set(ISLE_BYTE_IDENTITY_INVENTORY "{cmake_quote(inventory["path"])}")',
            f'set(ISLE_BYTE_IDENTITY_POLICY_STAMP "{cmake_quote(inventory["policy_stamp"])}")',
            f'set(ISLE_BYTE_IDENTITY_POLICY_SHA256 "{inventory["policy_sha256"]}")',
        ]
    )
    for index, entry in enumerate(inventory["entries"]):
        prefix = f"ISLE_BYTE_IDENTITY_INVENTORY_{index}"
        lines.extend(
            [
                f'set({prefix}_TARGET "{cmake_quote(entry["target"])}")',
                f'set({prefix}_SOURCE "{cmake_quote(entry["source_path"])}")',
                f'set({prefix}_AUDIT "{cmake_quote(entry["audit"])}")',
            ]
        )
    for index, target in enumerate(inventory["targets"]):
        prefix = f"ISLE_BYTE_IDENTITY_GRAPH_TARGET_{index}"
        lines.extend([
            f'set({prefix}_NAME "{cmake_quote(target["target"])}")',
            f'set({prefix}_KIND "{cmake_quote(target["kind"])}")',
            f'set({prefix}_DEFAULT "{"TRUE" if target["default_build"] else "FALSE"}")',
        ])
    for index, item in enumerate(inventory["inputs"]):
        prefix = f"ISLE_BYTE_IDENTITY_GRAPH_INPUT_{index}"
        lines.extend([
            f'set({prefix}_TARGET "{cmake_quote(item["target"])}")',
            f'set({prefix}_SOURCE "{cmake_quote(item["source_path"])}")',
            f'set({prefix}_KIND "{cmake_quote(item["kind"])}")',
        ])
        if item["kind"] == "RC":
            lines.append(
                f'set({prefix}_AUDIT "{cmake_quote(item["audit"])}")'
            )
    lines.append("set(ISLE_BYTE_IDENTITY_INVENTORY_COMPLETE TRUE)")
    return ("\n".join(lines) + "\n").encode("utf-8")


def invalidate_audited_outputs_for_policy_change(build_dir: Path) -> None:
    """Remove only compiler outputs named by exact prior audits.

    Apple Make 3.81 compares prerequisite mtimes at whole-second resolution.
    A configure-time policy stamp and an object produced earlier in the same
    second can therefore compare equal even when the stamp content changed.
    The inventory command already owns the exclusive build transaction, so a
    changed policy safely invalidates the precise prior compiler outputs and
    audits before CMake resumes the build.
    """
    authority = active_build_authority()
    build_root = authority.build_root
    for audit_path in compiler_audit_files(build_dir):
        audit = read_unique_audit(
            audit_path, build_root, "prior compiler audit"
        )
        outputs = []
        for key in ("object", "pdb"):
            value = audit.get(key)
            require(isinstance(value, str) and value,
                    f"prior compiler audit omits {key}: {audit_path}")
            output = Path(value)
            authority.parts(output)
            outputs.append(output)
        invalidate_build_paths([*outputs, audit_path])


def visible_output_arguments(arguments: list[str], option: str) -> list[str]:
    """Return only directly visible option values without expanding @rsp."""
    result = []
    index = 0
    folded_option = option.casefold()
    while index < len(arguments):
        value = arguments[index]
        folded = value.casefold()
        if folded in (f"/{folded_option}", f"-{folded_option}"):
            if index + 1 < len(arguments):
                result.append(arguments[index + 1])
                index += 2
                continue
        elif folded.startswith(f"/{folded_option}") or folded.startswith(
            f"-{folded_option}"
        ):
            candidate = value[len(option) + 1:]
            if candidate:
                result.append(candidate)
        index += 1
    return result


def invalidate_response_file_compiler_state(
    build_dir: Path, child: list[str], cwd: Path
) -> None:
    """Fail closed when @rsp prevents trustworthy command attribution.

    The response file may hide the source and both output paths, so no single
    TU can be selected safely.  The caller owns the exclusive build
    transaction: remove the entire prior compiler-audit universe and only the
    installed OBJ/PDB files named by those audits.  Directly visible /Fo and
    /Fd values are also removed best-effort, without ever reading the rsp.
    """
    authority = active_build_authority()

    def unlink_build_file(value: str, _root_fd: int) -> None:
        try:
            path = Path(value.strip('"'))
            parts = authority.parts(path, cwd=cwd)
            canonical = authority.path(parts)
            authority.prune_leaf_or_redirect(canonical)
            authority.assert_absent(canonical)
        except (ByteIdentityError, OSError, ValueError):
            pass

    # Keep verdict, visible-output, audit-read, audited-output, and audit
    # invalidation in the transaction's single build-root descriptor epoch.
    verdict = invalidate_framework_verdict(build_dir)
    for option in ("Fo", "Fd"):
        for value in visible_output_arguments(child, option):
            unlink_build_file(value, authority.root_fd)
    cleanup_compiler_audits_fd(authority.root_fd, unlink_build_file)
    authority.assert_absent(verdict)
    require(
        authority.enumerate_json_files(COMPILER_AUDIT_RELATIVE_ROOTS) == [],
        "response-file invalidation left compiler audit claims",
    )


def validate_inventory_publication_preflight(
    arguments: argparse.Namespace,
) -> tuple[Path, Path, Path, dict | None, Path]:
    """Validate immutable inventory argv before owning its prior bundle."""
    authority = active_build_authority()
    expected_output = inventory_path(arguments.build_dir)
    expected_plan = inventory_plan_path(arguments.build_dir)
    expected_stamp = policy_stamp_path(arguments.build_dir)
    require(authority.parts(arguments.output) == authority.parts(expected_output),
            "inventory output path is not canonical")
    require(authority.parts(arguments.cmake_output) == authority.parts(expected_plan),
            "inventory CMake output path is not canonical")
    require(authority.parts(arguments.policy_stamp) == authority.parts(expected_stamp),
            "policy stamp path is not canonical")
    outer_session = validate_active_session_authority(authority)
    expected_module = (
        Path(outer_session["controller_root"])
        / "framework/cmake/byte_identity.cmake"
        if outer_session is not None
        else arguments.source_dir.resolve() / "cmake/byte_identity.cmake"
    )
    if outer_session is not None:
        require(
            authority.parts(arguments.cmake_module)
            == authority.parts(expected_module)
            and authority.is_regular_file(expected_module),
            "byte-identity CMake module path is not the controller snapshot",
        )
    else:
        require(arguments.cmake_module.resolve() == expected_module
                and expected_module.is_file(),
                "byte-identity CMake module path is not canonical")
    return (
        expected_output, expected_plan, expected_stamp, outer_session,
        expected_module,
    )


def _command_inventory_locked(
    arguments: argparse.Namespace,
    preflight: tuple[Path, Path, Path, dict | None, Path],
) -> int:
    authority = active_build_authority()
    (
        expected_output, expected_plan, expected_stamp, outer_session,
        expected_module,
    ) = preflight
    invalidate_framework_verdict(arguments.build_dir)
    invalidate_build_paths([expected_output, expected_plan])
    state = validate_manifest(
        arguments.manifest,
        arguments.source_dir,
        arguments.build_dir,
        configured_compiler=arguments.compiler,
    )
    entries = normalized_inventory_entries(
        state, arguments.source_dir, arguments.build_dir, arguments.entry
    )
    targets = normalized_inventory_targets(
        state,
        arguments.target_entry,
        authoritative=outer_session is not None,
    )
    inputs = normalized_inventory_inputs(
        arguments.source_dir,
        arguments.build_dir,
        targets,
        arguments.input_entry,
    )
    link_graph = normalized_link_graph(
        targets, arguments.graph_count, arguments.graph_item
    )
    generator_standard_libraries = normalized_generator_standard_libraries(
        state,
        getattr(arguments, "standard_library_configuration", None),
        getattr(arguments, "standard_library_base_count", None),
        getattr(arguments, "standard_library_base_item", []),
        getattr(arguments, "standard_library_config_count", None),
        getattr(arguments, "standard_library_config_item", []),
    )
    runtime_bin = runtime_bin_path(arguments.build_dir)
    resident_ledger = active_resident_receipt_ledger()
    if resident_ledger is None:
        # Configure is deliberately plan-only.  A short-lived CMake child
        # cannot leave durable authority for either the broad Wine/toolchain
        # projection or the relocated native analysis runtime.  Retire any
        # stale exact seats and publish only their deterministic logical path;
        # the long-lived outer resident rematerializes both from manifest-
        # authenticated sources and holds them through every producer.
        close_resident_input_snapshot_holders(
            authority, arguments.build_dir
        )
        rollback_exact_private_roots(
            authority,
            [
                runtime_bin,
                native_reccmp_snapshot_path(arguments.build_dir),
                toolchain_snapshot_path(arguments.build_dir),
                command_snapshot_path(arguments.build_dir),
            ],
            "configure-only snapshot retirement could not be proven",
        )
    else:
        cached_native = authority.snapshot_validation_cache.pop(
            _native_reccmp_cache_key(arguments.build_dir), None
        )
        if cached_native is not None:
            cached_native["holder"].close()
        rollback_exact_private_run(
            authority, native_reccmp_snapshot_path(arguments.build_dir)
        )
        runtime_bin = materialize_runtime_bin(state, arguments.build_dir)
    materialize_compiler_slots(arguments.build_dir)
    policy = inventory_policy_payload(
        state, expected_module, entries, targets, inputs, link_graph,
        generator_standard_libraries,
    )
    policy_sha = sha256_bytes(
        json.dumps(policy, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    stamp_metadata = authority.lstat(expected_stamp)
    if stamp_metadata is None:
        previous_policy_sha = None
    else:
        require(stat.S_ISREG(stamp_metadata.st_mode),
                "prior policy stamp is not a regular build file")
        previous_policy_sha = authority.read_text(
            expected_stamp, encoding="ascii"
        ).strip()
    if previous_policy_sha != policy_sha:
        invalidate_audited_outputs_for_policy_change(arguments.build_dir)
    inventory = {
        "schema": 1,
        "status": "EXACT_CONFIGURE_TIME_CPP_TU_INVENTORY",
        "path": str(expected_output),
        "cmake_output": str(expected_plan),
        "policy_stamp": str(expected_stamp),
        "policy_sha256": policy_sha,
        "runtime_bin": str(runtime_bin),
        **policy,
    }
    inventory_bytes = (
        json.dumps(inventory, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    rendered = render_inventory_plan(inventory)
    # The stamp is the bundle's commit marker.  It is absent throughout data
    # publication and appears only after both independently rendered payloads.
    invalidate_build_paths([expected_stamp])
    atomic_write(expected_output, inventory_bytes)
    atomic_write(expected_plan, rendered, if_changed=True)
    atomic_write(expected_stamp, (policy_sha + "\n").encode("ascii"))
    if arguments.emit_cmake:
        sys.stdout.buffer.write(rendered)
    else:
        print(json.dumps({
            "status": inventory["status"],
            "translation_units": len(entries),
            "targets": len(targets),
            "noncompile_inputs": len(inputs),
            "policy_sha256": policy_sha,
            "output": str(expected_output),
        }, sort_keys=True))
    return 0


def command_inventory_locked(arguments: argparse.Namespace) -> int:
    """Publish configure inventory/stamp/plan as one invalidatable bundle."""
    preflight = validate_inventory_publication_preflight(arguments)
    require(
        active_build_authority().lstat(
            execution_projection_recovery_path(arguments.build_dir)
        ) is None,
        "configure inventory is blocked by an unrecovered execution transaction",
    )
    try:
        return _command_inventory_locked(arguments, preflight)
    except BaseException as original:
        failures = []
        try:
            invalidate_build_paths([
                inventory_path(arguments.build_dir),
                inventory_plan_path(arguments.build_dir),
                policy_stamp_path(arguments.build_dir),
            ])
        except BaseException as error:
            failures.append(f"published paths: {error}")
        authority = active_build_authority()
        try:
            close_resident_input_snapshot_holders(
                authority, arguments.build_dir
            )
        except BaseException as error:
            failures.append(f"snapshot caches: {error}")
        try:
            rollback_exact_private_roots(
                authority,
                [
                    runtime_bin_path(arguments.build_dir),
                    native_reccmp_snapshot_path(arguments.build_dir),
                    toolchain_snapshot_path(arguments.build_dir),
                    command_snapshot_path(arguments.build_dir),
                ],
                "inventory materialization rollback could not be proven",
            )
        except BaseException as error:
            failures.append(f"materialized snapshots: {error}")
        if failures:
            raise ByteIdentityError(
                "inventory publication rollback failed: "
                + "; ".join(failures)
            ) from original
        raise


def command_inventory(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_inventory_locked(arguments)


def load_inventory(
    state: dict, build_dir: Path, *, require_runtime_authority: bool = True,
) -> dict:
    authority = active_build_authority()
    path = inventory_path(build_dir)
    try:
        inventory = strict_json_loads(authority.read_text(path))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot read configure inventory {path}: {error}") from error
    require(isinstance(inventory, dict), "configure inventory is not an object")
    exact_keys(
        inventory,
        {
            "schema", "status", "path", "cmake_output", "policy_stamp",
            "policy_sha256", "runtime_bin", "manifest_sha256",
            "toolchain_fingerprint", "framework_tool_sha256",
            "backend_tool_sha256", "entropy_tool_sha256",
            "cmake_module", "cmake_module_sha256",
            "python_executable", "python_sha256", "python_version",
            "child_environment", "runtime_executables", "targets", "inputs",
            "configured_compiler", "entries",
            "link_graph", "generator_standard_libraries",
        },
        "configure inventory",
    )
    require(type(inventory.get("schema")) is int and inventory.get("schema") == 1
            and inventory.get("status") == "EXACT_CONFIGURE_TIME_CPP_TU_INVENTORY",
            "configure inventory schema/status differs")
    require(authority.parts(Path(inventory.get("path", "")))
            == authority.parts(path)
            and authority.parts(Path(inventory.get("cmake_output", "")))
            == authority.parts(inventory_plan_path(build_dir))
            and authority.parts(Path(inventory.get("policy_stamp", "")))
            == authority.parts(policy_stamp_path(build_dir))
            and authority.parts(Path(inventory.get("runtime_bin", "")))
            == authority.parts(runtime_bin_path(build_dir)),
            "configure inventory output paths are not canonical")
    raw_entries = inventory.get("entries")
    require(isinstance(raw_entries, list), "configure inventory entries are invalid")
    reconstructed = normalized_inventory_entries(
        state,
        Path(state["source_dir"]),
        build_dir,
        [[item.get("target"), item.get("source_path"), item.get("language"),
          str(item.get("target_ordinal")), item.get("source_authority")]
         if state.get("source_overlay", {}).get("enabled") else
         [item.get("target"), item.get("source_path"), item.get("language"),
          str(item.get("target_ordinal"))]
         for item in raw_entries if isinstance(item, dict)],
    )
    require(exact_json_equal(reconstructed, raw_entries),
            "configure inventory entries are noncanonical or altered")
    raw_targets = inventory.get("targets")
    require(isinstance(raw_targets, list),
            "configure target inventory is invalid")
    reconstructed_targets = normalized_inventory_targets(
        state,
        [
            [item.get("target"), item.get("kind"),
             "TRUE" if item.get("default_build") is True else "FALSE"]
            for item in raw_targets if isinstance(item, dict)
        ],
        # Whether the graph was authoritative is enforced when inventory is
        # created under the outer session.  Loading must reproduce the exact
        # serialized policy independently of the caller's current session.
        authoritative=False,
    )
    require(exact_json_equal(reconstructed_targets, raw_targets),
            "configure target inventory is noncanonical or altered")
    raw_inputs = inventory.get("inputs")
    require(isinstance(raw_inputs, list),
            "configure noncompile input inventory is invalid")
    reconstructed_inputs = normalized_inventory_inputs(
        Path(state["source_dir"]),
        build_dir,
        reconstructed_targets,
        [
            [item.get("target"), item.get("source_path"), item.get("kind"),
             str(item.get("target_ordinal"))]
            for item in raw_inputs if isinstance(item, dict)
        ],
    )
    require(exact_json_equal(reconstructed_inputs, raw_inputs),
            "configure noncompile input inventory is noncanonical or altered")
    raw_link_graph = inventory.get("link_graph")
    require(isinstance(raw_link_graph, list),
            "configure link graph inventory is invalid")
    reconstructed_link_graph = normalized_link_graph(
        reconstructed_targets,
        [
            [entry.get("target"), property_name, str(len(values))]
            for entry in raw_link_graph if isinstance(entry, dict)
            for property_name, values in (
                entry.get("properties", {}).items()
                if isinstance(entry.get("properties"), dict) else []
            )
        ],
        [
            [entry.get("target"), property_name, value]
            for entry in raw_link_graph if isinstance(entry, dict)
            for property_name, values in (
                entry.get("properties", {}).items()
                if isinstance(entry.get("properties"), dict) else []
            )
            if isinstance(values, list)
            for value in values
        ],
    )
    require(exact_json_equal(reconstructed_link_graph, raw_link_graph),
            "configure link graph inventory is noncanonical or altered")
    raw_standard_libraries = inventory.get("generator_standard_libraries")
    if raw_standard_libraries is None:
        reconstructed_standard_libraries = (
            normalized_generator_standard_libraries(
                state, None, None, [], None, []
            )
        )
    else:
        require(isinstance(raw_standard_libraries, dict),
                "configure generator standard-library inventory is invalid")
        base = raw_standard_libraries.get("base")
        config = raw_standard_libraries.get("configuration_specific")
        require(isinstance(base, list) and isinstance(config, list),
                "configure generator standard-library arrays are invalid")
        reconstructed_standard_libraries = (
            normalized_generator_standard_libraries(
                state, raw_standard_libraries.get("configuration"),
                str(len(base)), base, str(len(config)), config,
            )
        )
    require(exact_json_equal(
        reconstructed_standard_libraries, raw_standard_libraries
    ), "configure generator standard-library inventory is altered")
    cmake_module = Path(inventory.get("cmake_module", ""))
    outer_session = validate_active_session_authority(authority)
    expected_module = (
        Path(outer_session["controller_root"])
        / "framework/cmake/byte_identity.cmake"
        if outer_session is not None
        else Path(state["source_dir"]) / "cmake/byte_identity.cmake"
    )
    if outer_session is not None:
        require(
            authority.parts(cmake_module) == authority.parts(expected_module)
            and authority.is_regular_file(cmake_module),
            "configure inventory CMake module differs from controller snapshot",
        )
    else:
        require(cmake_module.resolve() == expected_module
                and cmake_module.is_file(),
                "configure inventory CMake module differs")
    policy = inventory_policy_payload(
        state,
        cmake_module,
        reconstructed,
        reconstructed_targets,
        reconstructed_inputs,
        reconstructed_link_graph,
        reconstructed_standard_libraries,
    )
    policy_sha = sha256_bytes(
        json.dumps(policy, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    require(policy_sha == inventory.get("policy_sha256"),
            "configure inventory policy hash differs")
    require(sha256_file(cmake_module) == inventory.get("cmake_module_sha256"),
            "configure inventory CMake module hash differs")
    try:
        stamp = authority.read_text(policy_stamp_path(build_dir), encoding="ascii")
    except (OSError, ByteIdentityError) as error:
        raise ByteIdentityError(f"cannot read policy stamp: {error}") from error
    require(stamp == policy_sha + "\n", "compiler policy stamp differs")
    if require_runtime_authority:
        validate_runtime_bin(state, build_dir)
    return inventory


def _command_database_tokens(command: str, context: str) -> list[str]:
    require(isinstance(command, str) and command and "\0" not in command
            and "\n" not in command and "\r" not in command,
            f"{context} command text is invalid")
    try:
        tokens = shlex.split(command, comments=False, posix=True)
    except ValueError as error:
        raise ByteIdentityError(f"{context} command quoting is invalid: {error}") from error
    require(tokens, f"{context} command is empty")
    require(not any(token in {";", "&&", "||", "|", "&", "<", ">", "`"}
                    for token in tokens),
            f"{context} contains a shell command boundary")
    require(not raw_argument_token_errors(tokens),
            f"{context} produces literal quoted compiler argv")
    return tokens


def _database_output_owner(output: Path, source: Path, inventory: dict) -> dict:
    output_text = output.as_posix()
    source_candidates = [
        entry for entry in inventory["entries"]
        if Path(entry["source_path"]).resolve() == source
    ]
    if len(source_candidates) == 1:
        return source_candidates[0]
    matches = []
    for entry in source_candidates:
        marker = f"/CMakeFiles/{entry['target']}.dir/"
        if marker in f"/{output_text.lstrip('/')}":
            matches.append(entry)
    require(len(matches) == 1,
            f"compile database output has no unique inventory target owner: {output}")
    return matches[0]


def normalized_command_inventory_entries(
    state: dict, inventory: dict, build_dir: Path, raw_database: object,
) -> list[dict]:
    require(isinstance(raw_database, list) and raw_database,
            "compile_commands.json must be a non-empty array")
    configured_value = state.get("compiler_path")
    require(isinstance(configured_value, str) and configured_value,
            "configured compiler is absent from command attestation state")
    configured = Path(configured_value).resolve()
    source_root = Path(state["source_dir"]).resolve()
    owners = set()
    normalized = []
    tree_cache: dict[str, dict] = {}
    for index, record in enumerate(raw_database):
        context = f"compile_commands[{index}]"
        require(isinstance(record, dict), f"{context} must be an object")
        exact_audit_keys(record, {"directory", "command", "file", "output"}, context)
        directory_value = record.get("directory")
        file_value = record.get("file")
        output_value = record.get("output")
        require(all(isinstance(item, str) and item
                    for item in (directory_value, file_value, output_value)),
                f"{context} paths must be non-empty strings")
        authority = active_build_authority()
        directory_parts = authority.parts(
            lexical_absolute_path(Path(directory_value), build_dir),
            allow_root=True,
        )
        # Subdirectory generators legitimately compile from their binary
        # directory.  Keep that exact cwd in the command policy, but require
        # its whole lexical ancestry to remain inside the held build authority.
        directory = authority.path(directory_parts)
        directory_fd = authority.open_directory_parts(directory_parts)
        os.close(directory_fd)
        source = resolved_argument_path(file_value, directory)
        try:
            source_relative = source.relative_to(source_root).as_posix()
        except ValueError as error:
            raise ByteIdentityError(f"{context} source escapes the source tree") from error
        # CMake's compile database records `directory` as the command cwd but
        # writes `output` relative to the top-level binary directory (including
        # the subdirectory prefix).  Attribute both spellings independently
        # and require them to converge on one exact object.
        output = lexical_argument_path(output_value, build_dir)
        owner = _database_output_owner(output, source, inventory)
        require(owner["source"] == source_relative,
                f"{context} target/source owner differs from configure inventory")
        owner_key = (owner["target"], owner["source"])
        require(owner_key not in owners,
                f"duplicate compile database owner: {owner_key}")
        owners.add(owner_key)
        database_argv = _command_database_tokens(record.get("command"), context)
        live_session = validate_active_session_authority(authority)
        launcher_python = (
            live_session["python"] if live_session is not None
            else state["python_executable"]
        )
        launcher_tool = (
            live_session["framework"] if live_session is not None
            else str(Path(__file__).resolve())
        )
        launcher_manifest = (
            str(Path(live_session["controller_root"])
                / "framework/tools/byte_identity_manifest.json")
            if live_session is not None else state["manifest_path"]
        )
        expected_launcher = [
            launcher_python, "-I", "-B",
            launcher_tool, "compile-launch",
            "--manifest", launcher_manifest,
            "--source-dir", state["source_dir"],
            "--build-dir", state["build_dir"],
            "--target", owner["target"],
            "--configured-compiler", state["compiler_path"], "--",
        ]
        # CMake 4.3's generator-authoritative compile database intentionally
        # records the raw compiler rule and omits both RULE_LAUNCH_COMPILE and
        # compiler-launcher prefixes.  Do not use this projection to prove the
        # target-level RC dispatcher.  The resident closed-plan parser binds
        # the exact generated Make recipe separately, including the required
        # compile-dispatch -> compile-launch -> compiler order for every C/C++
        # owner of an RC-bearing target.
        if Path(database_argv[0]).resolve() == configured:
            launcher_prefix = []
            argv = database_argv
        else:
            require(database_argv[:len(expected_launcher)] == expected_launcher,
                    f"{context} compiler launcher prefix differs from policy")
            launcher_prefix = database_argv[:len(expected_launcher)]
            argv = database_argv[len(expected_launcher):]
        parsed = validate_compile_arguments(argv)
        if owner["language"] == "CXX":
            validate_generated_cxx_semantic_profile(parsed, context)
        require(argv and Path(argv[0]).resolve() == configured,
                f"{context} compiler differs from the configured compiler")
        require(resolved_argument_path(parsed["source_token"], directory) == source,
                f"{context} final compiler source differs")
        object_path = lexical_argument_path(parsed["Fo"][1], directory)
        pdb_path = lexical_argument_path(parsed["Fd"][1], directory)
        require(object_path == output,
                f"{context} /Fo differs from the compile database output")
        require(pdb_path != object_path,
                f"{context} /Fo and /Fd must name distinct outputs")
        if parsed["language_mode"] is not None:
            require(parsed["language_mode"] == owner["language"],
                    f"{context} explicit language differs from inventory")
        implicit_language = implicit_cmake_source_language(source)
        if implicit_language != owner["language"]:
            require(parsed["language_mode"] == owner["language"],
                    f"{context} requires exact /TC or /TP language attribution")
        ordered_roots = [source.parent]
        ordered_roots.extend(
            resolved_argument_path(value, directory)
            for _, value, _ in parsed["include_paths"]
        )
        ordered_roots.extend(
            resolved_argument_path(value, directory).parent
            for _, value, _ in parsed["force_includes"]
        )
        ordered_roots.extend(
            Path(tree["absolute_path"])
            for tree in state["sealed_include_trees"]
        )
        normalized_roots = []
        seen_roots = set()
        sealed_roots = {
            Path(tree["absolute_path"]).resolve()
            for tree in state["sealed_include_trees"]
        }
        for root_index, root in enumerate(ordered_roots):
            canonical_root = root.resolve(strict=True)
            require(canonical_root.is_dir(),
                    f"{context} include search root is not a directory: {root}")
            if canonical_root in seen_roots:
                continue
            seen_roots.add(canonical_root)
            in_source = False
            try:
                canonical_root.relative_to(source_root)
                in_source = True
            except ValueError:
                pass
            require(in_source or canonical_root in sealed_roots,
                    f"{context} include search root is outside the sealed closure: {canonical_root}")
            cache_key = str(canonical_root)
            snapshot = tree_cache.get(cache_key)
            if snapshot is None:
                snapshot = canonical_tree_snapshot(
                    canonical_root, hash_files=True,
                    max_entries=20000, max_depth=32,
                )
                tree_cache[cache_key] = snapshot
            normalized_roots.append({
                "ordinal": root_index,
                "root": snapshot["root"],
                "entry_count": snapshot["entry_count"],
                "max_depth": snapshot["max_depth"],
                "membership_sha256": snapshot["membership_sha256"],
                "content_sha256": snapshot["content_sha256"],
                "metadata_sha256": snapshot["metadata_sha256"],
            })
        normalized_entry = {
            "target": owner["target"],
            "source": owner["source"],
            "source_path": owner["source_path"],
            "language": owner["language"],
            "target_ordinal": owner["target_ordinal"],
                "directory": str(directory),
                "object": str(object_path),
                "pdb": str(pdb_path),
                "argv": argv,
                "launcher_prefix": launcher_prefix,
                "argv_sha256": sha256_bytes(
                    json.dumps(argv, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
                ),
                "roles": parsed["roles"],
                "definitions": [item[1] for item in parsed["definitions"]],
                "undefinitions": [item[1] for item in parsed["undefinitions"]],
                "include_paths": [item[1] for item in parsed["include_paths"]],
                "force_includes": [item[1] for item in parsed["force_includes"]],
                "flags": [item["token"] for item in parsed["roles"]
                          if item.get("role") == "flag"],
                "input_trees": normalized_roots,
        }
        if state.get("source_overlay", {}).get("enabled"):
            normalized_entry.update({
                "source_authority": owner["source_authority"],
                "effective_source_sha256": owner["effective_source_sha256"],
                "source_overlay_policy_sha256":
                    owner["source_overlay_policy_sha256"],
            })
        normalized.append(normalized_entry)
    normalized.sort(key=lambda item: (item["target"], item["source"]))
    expected = {(item["target"], item["source"]) for item in inventory["entries"]}
    require(owners == expected,
            "compile database owner universe differs from configure inventory")
    return normalized


def command_attestation_payload(
    state: dict, inventory: dict, compile_database_sha256: str,
    entries: list[dict], transport_snapshot: dict,
) -> dict:
    return {
        "manifest_sha256": state["manifest_sha256"],
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "configure_inventory_sha256": sha256_file(
            inventory_path(Path(state["build_dir"]))
        ),
        "configure_policy_sha256": inventory["policy_sha256"],
        "compile_database_sha256": compile_database_sha256,
        "entries": entries,
        "transport_snapshot": transport_snapshot,
    }


COMMAND_INPUT_TREE_IDENTITY_KEYS = (
    "root", "entry_count", "max_depth", "membership_sha256",
    "content_sha256", "metadata_sha256",
)


def command_input_tree_identity(tree: dict) -> dict:
    """Project one per-command search entry to its immutable tree identity."""
    return {key: tree[key] for key in COMMAND_INPUT_TREE_IDENTITY_KEYS}


def _materialize_command_snapshot(
    state: dict, inventory: dict, entries: list[dict], build_dir: Path,
) -> dict:
    """Copy the exact attributed source/header search universe into fake Z."""
    authority = active_build_authority()
    root = command_snapshot_path(build_dir)
    previous_cache = authority.snapshot_validation_cache.pop(
        command_snapshot_cache_key(build_dir), None
    )
    if previous_cache is not None:
        previous_cache["holder"].close()
    z_root = root / "z"
    authority.remove_tree(root)
    authority.mkdirs(z_root)
    expected_z = new_snapshot_destination_expectation(z_root)
    roots: dict[str, dict] = {}
    for entry in entries:
        for tree in entry["input_trees"]:
            identity = command_input_tree_identity(tree)
            logical = identity["root"]
            previous = roots.get(logical)
            if previous is not None:
                require(exact_json_equal(previous, identity),
                        f"command snapshot input tree has conflicting pins: {logical}")
                continue
            roots[logical] = identity
    normalized_roots = []
    excluded_opaque_inputs = []
    for logical in sorted(roots):
        tree = roots[logical]
        source = Path(logical)
        destination = absolute_snapshot_seat(z_root, source)
        copy_result = copy_command_tree_to_snapshot(
            source, destination, tree,
        )
        excluded_opaque_inputs.extend(copy_result)
        source_snapshot = copy_result.source_snapshot
        add_expected_snapshot_tree(
            expected_z, destination, source_snapshot["records"],
            include_file=lambda record, source=source: (
                source.joinpath(*PurePosixPath(record["path"]).parts)
                .suffix.casefold() not in FORBIDDEN_OPAQUE_SOURCE_SUFFIXES
            ),
        )
        normalized_roots.append(tree)
    generated_external_inputs = []
    external_pins = [
        {
            "role": "sealed_project_sdk_library",
            "logical_path": item["absolute_path"],
            "sha256": item["sha256"],
        }
        for item in state.get("terminal_producers", {}).get("link", {}).get(
            "project_sdk_libraries", []
        )
    ]
    external_pins.extend({
        "role": "linker_definition",
        "logical_path": item["source_path"],
        "sha256": item["source_sha256"],
    } for item in inventory.get("inputs", []) if item["kind"] == "LINKER_DEF")
    seen_external = set()
    for item in sorted(external_pins, key=lambda value: (
        value["logical_path"], value["role"]
    )):
        logical = Path(item["logical_path"])
        require(str(logical) not in seen_external,
                f"generated external command input is duplicated: {logical}")
        seen_external.add(str(logical))
        record = copy_external_file_to_snapshot(
            logical, absolute_snapshot_seat(z_root, logical), item["sha256"]
        )
        add_expected_snapshot_file(
            expected_z, absolute_snapshot_seat(z_root, logical), record
        )
        generated_external_inputs.append({
            **item,
            "snapshot_path": record["snapshot_path"],
            "size": record["size"],
            "mode": record["mode"],
        })
    # An explicitly pinned LINK input may share an include directory.  It is
    # admitted by its concrete role above, never by the generic tree copy.
    excluded_opaque_inputs = [
        item for item in excluded_opaque_inputs
        if item["logical_path"] not in seen_external
    ]
    excluded_by_path = {}
    for item in excluded_opaque_inputs:
        prior = excluded_by_path.get(item["logical_path"])
        require(prior is None or exact_json_equal(prior, item),
                f"opaque command input has conflicting exclusions: {item['logical_path']}")
        excluded_by_path[item["logical_path"]] = item
    excluded_opaque_inputs = [
        excluded_by_path[key] for key in sorted(excluded_by_path)
    ]
    for item in excluded_opaque_inputs:
        authority.assert_absent(absolute_snapshot_seat(
            z_root, Path(item["logical_path"])
        ))
    for logical in required_absent_toolchain_paths(state):
        seat = absolute_snapshot_seat(z_root, logical)
        require(
            _snapshot_destination_relative(expected_z, seat)
            not in expected_z["records"]
            and authority.lstat(seat) is None,
            f"required-absent toolchain file entered command inputs: {logical}",
        )
    z_snapshot = validate_expected_snapshot_destination(
        expected_z, "command virtual-Z snapshot"
    )
    document = {
        "schema": 1,
        "status": "IMMUTABLE_VIRTUAL_Z_COMMAND_INPUT_SNAPSHOT",
        "root": str(root),
        "z": _tree_pin(z_snapshot),
        "input_trees": normalized_roots,
        "generated_external_inputs": generated_external_inputs,
        "excluded_opaque_inputs": excluded_opaque_inputs,
    }
    descriptor_path = root / "snapshot.json"
    descriptor_bytes = atomic_json(descriptor_path, document)
    holder = authority.retain_directories([root, z_root])
    require(holder.read_bytes(descriptor_path) == descriptor_bytes,
            "command snapshot descriptor changed before hold")
    holder.revalidate()
    authority.snapshot_validation_cache[
        command_snapshot_cache_key(build_dir)
    ] = {
        "descriptor": document,
        "descriptor_sha256": sha256_bytes(descriptor_bytes),
        "entries_object": entries,
        "tree": z_snapshot,
        "trees": {str(z_root): z_snapshot},
        "holder": holder,
        "finalized": False,
    }
    return document


def materialize_command_snapshot(
    state: dict, inventory: dict, entries: list[dict], build_dir: Path,
) -> dict:
    """Failure-atomically materialize the authenticated command snapshot."""
    authority = active_build_authority()
    root = command_snapshot_path(build_dir)
    try:
        return _materialize_command_snapshot(
            state, inventory, entries, build_dir
        )
    except BaseException:
        cached = authority.snapshot_validation_cache.pop(
            command_snapshot_cache_key(build_dir), None
        )
        if cached is not None:
            cached["holder"].close()
        rollback_exact_private_run(authority, root)
        raise


def validate_command_snapshot(
    entries: list[dict], build_dir: Path, document: object,
    *, state: dict | None = None, inventory: dict | None = None,
) -> dict:
    authority = active_build_authority()
    root = command_snapshot_path(build_dir)
    require(isinstance(document, dict), "command transport snapshot is invalid")
    exact_audit_keys(
        document, {
            "schema", "status", "root", "z", "input_trees",
            "generated_external_inputs", "excluded_opaque_inputs",
        },
        "command transport snapshot",
    )
    require(type(document.get("schema")) is int and document.get("schema") == 1
            and document.get("status")
            == "IMMUTABLE_VIRTUAL_Z_COMMAND_INPUT_SNAPSHOT"
            and authority.parts(Path(document.get("root", "")))
            == authority.parts(root),
            "command transport snapshot identity differs")
    descriptor_path = root / "snapshot.json"
    descriptor_raw = authority.read_bytes(descriptor_path)
    stored = strict_json_loads(descriptor_raw)
    require(exact_json_equal(stored, document),
            "command transport snapshot audit differs")
    cache_key = command_snapshot_cache_key(build_dir)
    cached = authority.snapshot_validation_cache.get(cache_key)
    if cached is not None and (
        entries is cached["entries_object"]
        or exact_json_equal(entries, cached["entries_object"])
    ):
        require(
            cached["descriptor_sha256"] == sha256_bytes(descriptor_raw)
            and exact_json_equal(cached["descriptor"], document),
            "held command snapshot descriptor changed",
        )
        cached["holder"].revalidate()
        cached["entries_object"] = entries
        require_exact_build_namespace(
            authority, root, {"z": "directory", "snapshot.json": "file"},
            "held command snapshot root", replace_pin=True,
        )
        return document
    require(active_resident_receipt_ledger() is None,
            "resident command snapshot lacks materialization authority")
    require(descriptor_raw == canonical_json_bytes(document),
            "command snapshot descriptor differs from canonical resident bytes")
    expected_roots = {}
    for entry in entries:
        for tree in entry["input_trees"]:
            pin = command_input_tree_identity(tree)
            previous = expected_roots.get(tree["root"])
            require(previous is None or exact_json_equal(previous, pin),
                    f"command input tree pin conflicts: {tree['root']}")
            expected_roots[tree["root"]] = pin
    require(exact_json_equal(
                document.get("input_trees"),
                [expected_roots[key] for key in sorted(expected_roots)],
            ), "command transport input tree universe differs")
    expected_z = new_snapshot_destination_expectation(root / "z")
    for logical in sorted(expected_roots):
        tree = expected_roots[logical]
        source = Path(logical)
        source_snapshot = authenticated_source_tree_snapshot(
            source, tree, "fresh command snapshot input"
        )
        add_expected_snapshot_tree(
            expected_z, absolute_snapshot_seat(root / "z", source),
            source_snapshot["records"],
            include_file=lambda record, source=source: (
                source.joinpath(*PurePosixPath(record["path"]).parts)
                .suffix.casefold() not in FORBIDDEN_OPAQUE_SOURCE_SUFFIXES
            ),
        )
    generated_for_expectation = document.get("generated_external_inputs")
    require(isinstance(generated_for_expectation, list),
            "command transport generated external inputs are invalid")
    for index, item in enumerate(generated_for_expectation):
        require(isinstance(item, dict),
                f"command generated input {index} is invalid")
        logical = Path(item.get("logical_path", ""))
        record = authenticated_external_snapshot_file(
            logical, require_sha(
                item.get("sha256"), f"command generated input {index}"
            ), "command generated external input",
        )
        add_expected_snapshot_file(
            expected_z, absolute_snapshot_seat(root / "z", logical), record
        )
    observed_z = validate_expected_snapshot_destination(
        expected_z, "fresh command virtual-Z snapshot"
    )
    require(exact_json_equal(document.get("z"), _tree_pin(observed_z)),
            "command transport snapshot content differs")
    generated = document.get("generated_external_inputs")
    require(isinstance(generated, list),
            "command transport generated external inputs are invalid")
    seen_generated = set()
    for index, item in enumerate(generated):
        context = f"command transport generated_external_inputs[{index}]"
        require(isinstance(item, dict), f"{context} must be an object")
        exact_audit_keys(item, {
            "role", "logical_path", "snapshot_path", "sha256", "size", "mode",
        }, context)
        logical = Path(item.get("logical_path", ""))
        snapshot_path = absolute_snapshot_seat(root / "z", logical)
        require(str(logical) not in seen_generated
                and item.get("snapshot_path") == str(snapshot_path),
                f"{context} identity/path differs")
        seen_generated.add(str(logical))
        data = authority.read_bytes(snapshot_path)
        metadata = authority.lstat(snapshot_path)
        require(metadata is not None and stat.S_ISREG(metadata.st_mode)
                and sha256_bytes(data) == item.get("sha256")
                and len(data) == item.get("size")
                and stat.S_IMODE(metadata.st_mode) == item.get("mode"),
                f"{context} snapshot bytes/mode differ")
    if state is not None and inventory is not None:
        expected_generated = [
            ("sealed_project_sdk_library", item["absolute_path"], item["sha256"])
            for item in state.get("terminal_producers", {}).get("link", {}).get(
                "project_sdk_libraries", []
            )
        ]
        expected_generated.extend(
            ("linker_definition", item["source_path"], item["source_sha256"])
            for item in inventory.get("inputs", [])
            if item["kind"] == "LINKER_DEF"
        )
        expected_generated.sort(key=lambda item: (item[1], item[0]))
        require(
            [(item["role"], item["logical_path"], item["sha256"])
             for item in generated] == expected_generated,
            "command transport generated external input universe differs",
        )
    excluded = document.get("excluded_opaque_inputs")
    require(isinstance(excluded, list),
            "command transport opaque exclusion list is invalid")
    previous_excluded = ""
    for index, item in enumerate(excluded):
        context = f"command transport excluded_opaque_inputs[{index}]"
        require(isinstance(item, dict), f"{context} must be an object")
        exact_audit_keys(
            item, {"logical_path", "sha256", "size", "reason"}, context
        )
        logical = Path(item.get("logical_path", ""))
        require(logical.is_absolute()
                and logical.suffix.casefold() in FORBIDDEN_OPAQUE_SOURCE_SUFFIXES
                and str(logical) > previous_excluded
                and item.get("reason")
                == "generic_include_tree_opaque_payload_forbidden"
                and isinstance(item.get("size"), int)
                and item["size"] >= 0,
                f"{context} identity differs")
        require_sha(item.get("sha256"), f"{context}.sha256")
        previous_excluded = str(logical)
        authority.assert_absent(absolute_snapshot_seat(root / "z", logical))
    require_exact_build_namespace(
        authority, root, {"z": "directory", "snapshot.json": "file"},
        "command snapshot root",
    )
    if cached is not None:
        cached["holder"].close()
    holder = authority.retain_directories([root, root / "z"])
    holder.read_bytes(descriptor_path)
    holder.revalidate()
    authority.snapshot_validation_cache[cache_key] = {
        "descriptor": document,
        "descriptor_sha256": sha256_bytes(descriptor_raw),
        "entries_object": entries,
        "tree": observed_z,
        "trees": {str(root / "z"): observed_z},
        "holder": holder,
        "finalized": False,
    }
    return document


def finalize_command_snapshot_validation(
    entries: list[dict], build_dir: Path, document: dict,
) -> None:
    """Perform the one terminal full rescan of the held command snapshot."""
    authority = active_build_authority()
    cache_key = command_snapshot_cache_key(build_dir)
    cached = authority.snapshot_validation_cache.get(cache_key)
    require(cached is not None
            and (entries is cached["entries_object"]
                 or exact_json_equal(entries, cached["entries_object"])),
            "command snapshot was not held by the resident transaction")
    if cached["finalized"]:
        return
    root = command_snapshot_path(build_dir)
    cached["holder"].revalidate()
    raw = authority.read_bytes(root / "snapshot.json")
    observed = canonical_tree_snapshot(
        root / "z", hash_files=True, include_metadata_records=True
    )
    require(
        cached["descriptor_sha256"] == sha256_bytes(raw)
        and exact_json_equal(strict_json_loads(raw), document)
        and exact_json_equal(_tree_pin(observed), document["z"]),
        "held command snapshot changed before completion",
    )
    require_held_snapshot_unchanged(
        cached["tree"], observed, "held command snapshot"
    )
    cached["holder"].revalidate()
    cached["finalized"] = True


def validate_command_attestation_publication_preflight(
    arguments: argparse.Namespace,
) -> tuple[Path, Path, Path]:
    """Validate immutable command-attestation argv before bundle mutation."""
    authority = active_build_authority()
    output = command_inventory_path(arguments.build_dir)
    stamp = command_policy_stamp_path(arguments.build_dir)
    compile_database = lexical_absolute_path(arguments.compile_commands)
    require(authority.parts(arguments.output) == authority.parts(output)
            and authority.parts(arguments.policy_stamp) == authority.parts(stamp),
            "command attestation output paths are not canonical")
    require(authority.parts(compile_database)
            == authority.parts(arguments.build_dir / "compile_commands.json"),
            "compile database path is not canonical")
    return output, stamp, compile_database


def _command_attest_commands_locked(
    arguments: argparse.Namespace, preflight: tuple[Path, Path, Path],
) -> int:
    authority = active_build_authority()
    output, stamp, compile_database = preflight
    invalidate_framework_verdict(arguments.build_dir)
    invalidate_build_paths([output])
    state = validate_manifest(
        arguments.manifest, arguments.source_dir, arguments.build_dir,
        configured_compiler=arguments.compiler,
    )
    inventory = load_inventory(
        state, arguments.build_dir,
        require_runtime_authority=(
            active_resident_receipt_ledger() is not None
        ),
    )
    try:
        raw_database = strict_json_loads(authority.read_text(compile_database))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot read compile database: {error}") from error
    compile_database_sha = sha256_file(compile_database)
    entries = normalized_command_inventory_entries(
        state, inventory, arguments.build_dir, raw_database
    )
    transport_snapshot = materialize_command_snapshot(
        state, inventory, entries, arguments.build_dir
    )
    payload = command_attestation_payload(
        state, inventory, compile_database_sha, entries, transport_snapshot
    )
    policy_sha = sha256_bytes(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    previous = None
    metadata = authority.lstat(stamp)
    if metadata is not None:
        require(stat.S_ISREG(metadata.st_mode),
                "prior command policy stamp is not a regular file")
        previous = authority.read_text(stamp, encoding="ascii").strip()
    if previous != policy_sha:
        invalidate_audited_outputs_for_policy_change(arguments.build_dir)
    document = {
        "schema": 1,
        "status": "EXACT_GENERATED_COMPILER_COMMAND_INVENTORY",
        "path": str(output),
        "policy_stamp": str(stamp),
        "policy_sha256": policy_sha,
        **payload,
    }
    document_bytes = (
        json.dumps(document, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    invalidate_build_paths([stamp])
    atomic_write(output, document_bytes)
    atomic_write(stamp, (policy_sha + "\n").encode("ascii"))
    print(json.dumps({
        "status": document["status"],
        "translation_units": len(entries),
        "policy_sha256": policy_sha,
    }, sort_keys=True))
    return 0


def command_attest_commands_locked(arguments: argparse.Namespace) -> int:
    """Publish command inventory/stamp/snapshot as one atomic claim bundle."""
    preflight = validate_command_attestation_publication_preflight(arguments)
    try:
        return _command_attest_commands_locked(arguments, preflight)
    except BaseException as original:
        failures = []
        try:
            invalidate_build_paths([
                command_inventory_path(arguments.build_dir),
                command_policy_stamp_path(arguments.build_dir),
            ])
        except BaseException as error:
            failures.append(f"published paths: {error}")
        try:
            rollback_exact_private_run(
                active_build_authority(),
                command_snapshot_path(arguments.build_dir),
            )
        except BaseException as error:
            failures.append(f"command snapshot: {error}")
        if failures:
            raise ByteIdentityError(
                "command attestation publication rollback failed: "
                + "; ".join(failures)
            ) from original
        raise


def command_attest_commands(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_attest_commands_locked(arguments)


def load_command_inventory(state: dict, inventory: dict, build_dir: Path) -> dict:
    authority = active_build_authority()
    path = command_inventory_path(build_dir)
    try:
        document = strict_json_loads(authority.read_text(path))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot read generated command inventory: {error}") from error
    require(isinstance(document, dict), "generated command inventory is not an object")
    exact_audit_keys(
        document,
        {
            "schema", "status", "path", "policy_stamp", "policy_sha256",
            "manifest_sha256", "toolchain_fingerprint",
            "configure_inventory_sha256", "configure_policy_sha256",
            "compile_database_sha256", "entries", "transport_snapshot",
        },
        "generated command inventory",
    )
    require(type(document.get("schema")) is int and document.get("schema") == 1
            and document.get("status") == "EXACT_GENERATED_COMPILER_COMMAND_INVENTORY",
            "generated command inventory schema/status differs")
    require(authority.parts(Path(document.get("path", ""))) == authority.parts(path)
            and authority.parts(Path(document.get("policy_stamp", "")))
            == authority.parts(command_policy_stamp_path(build_dir)),
            "generated command inventory paths differ")
    compile_database = authority.build_root / "compile_commands.json"
    require(sha256_file(compile_database) == document.get("compile_database_sha256"),
            "compile database changed after command attestation")
    try:
        raw_database = strict_json_loads(authority.read_text(compile_database))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot reread compile database: {error}") from error
    entries = normalized_command_inventory_entries(
        state, inventory, build_dir, raw_database
    )
    transport_snapshot = validate_command_snapshot(
        entries, build_dir, document.get("transport_snapshot"),
        state=state, inventory=inventory,
    )
    payload = command_attestation_payload(
        state, inventory, document["compile_database_sha256"], entries,
        transport_snapshot,
    )
    policy_sha = sha256_bytes(
        json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    )
    require(exact_json_equal(document.get("entries"), entries)
            and document.get("policy_sha256") == policy_sha
            and document.get("manifest_sha256") == state["manifest_sha256"]
            and document.get("toolchain_fingerprint") == state["toolchain_fingerprint"]
            and document.get("configure_policy_sha256") == inventory["policy_sha256"],
            "generated compiler command policy differs")
    require(authority.read_text(command_policy_stamp_path(build_dir), encoding="ascii")
            == policy_sha + "\n", "generated command policy stamp differs")
    return document


def configured_inventory_source_for_command(
    build_dir: Path,
    source_dir: Path,
    target: str,
    command: list[str],
    cwd: Path,
) -> tuple[Path, str, dict]:
    """Attribute only the final argv token to an exact inventory source.

    CMake's attested COMPILE_OBJECT rule makes ``<SOURCE>`` the final token.
    Never search the rest of argv: a source path used as a separated `/I`,
    `/D`, or `/U` operand is not the compiler input.  The narrow raw inventory
    read exists only to select the one audit that can be invalidated safely;
    ``load_inventory()`` authenticates the full record before child spawn.
    """
    authority = active_build_authority()
    if len(command) < 2 or not _argument_text(command[-1]):
        raise CompilerAttributionError(
            "compiler command has no pinned final source token"
        )
    cache = authority.resident_producer_state_cache
    if cache is not None and active_resident_receipt_ledger() is not None:
        inventory = cache["inventory"]
    else:
        path = inventory_path(build_dir)
        try:
            inventory = strict_json_loads(authority.read_text(path))
        except (OSError, UnicodeError, json.JSONDecodeError, ByteIdentityError) as error:
            raise CompilerAttributionError(
                f"cannot attribute compiler source from configure inventory: {error}"
            ) from error
    if not (isinstance(inventory, dict)
            and isinstance(inventory.get("entries"), list)):
        raise CompilerAttributionError(
            "configure inventory cannot attribute compiler source"
        )
    candidates = []
    source_root = source_dir.resolve()
    for entry in inventory["entries"]:
        if not isinstance(entry, dict) or entry.get("target") != target:
            continue
        relative = entry.get("source")
        absolute = entry.get("source_path")
        language = entry.get("language")
        if not (isinstance(relative, str) and relative
                and isinstance(absolute, str) and absolute
                and language in SUPPORTED_SOURCE_LANGUAGES):
            raise CompilerAttributionError(
                "configure inventory source entry is malformed"
            )
        pure = PurePosixPath(relative)
        if pure.is_absolute() or ".." in pure.parts:
            raise CompilerAttributionError(
                "configure inventory source entry escapes the source tree"
            )
        source_path = Path(absolute).resolve()
        if source_path != (source_root / Path(*pure.parts)).resolve():
            raise CompilerAttributionError(
                "configure inventory source identity differs"
            )
        candidates.append((source_path, pure.as_posix(), entry))
    try:
        final_source = resolved_argument_path(
            _argument_text(command[-1]), cwd
        )
    except (OSError, ValueError) as error:
        raise CompilerAttributionError(
            f"compiler final source token is invalid: {error}"
        ) from error
    matches = [
        candidate for candidate in candidates if candidate[0] == final_source
    ]
    if len(matches) != 1:
        raise CompilerAttributionError(
            f"expected final token to name one configure-inventory source, found {len(matches)}"
        )
    source_path, relative, entry = matches[0]
    return source_path, relative, entry


def find_recipe(state: dict, recipe_id: str) -> dict:
    matches = [
        recipe for recipe in state["recipes"] if recipe["id"] == recipe_id
    ]
    require(len(matches) == 1, f"recipe is not uniquely declared: {recipe_id}")
    return matches[0]


def find_archive(state: dict, identity: str) -> dict:
    matches = [
        archive for archive in state["archives"]
        if archive["identity"] == identity
    ]
    require(len(matches) == 1,
            f"third-party archive is not uniquely declared: {identity}")
    return matches[0]


def command_materialize_locked(arguments: argparse.Namespace) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    invalidate_framework_verdict(arguments.build_dir)
    requested_parts = authority.parts(arguments.output)
    require(requested_parts[:2] == ("byte-identity", "generated")
            and len(requested_parts) == 3,
            "materialization output is outside the generated namespace")
    invalidate_build_paths([arguments.output])
    state = validate_manifest(arguments.manifest, arguments.source_dir, arguments.build_dir)
    declared_recipe = find_recipe(state, arguments.recipe_id)
    audit_path = (
        authority.build_root
        / "byte-identity/audit/materialization"
        / f"{declared_recipe['id']}.json"
    )
    expected_output = Path(declared_recipe["header_output"])
    require(authority.parts(arguments.output) == authority.parts(expected_output),
            "materialization output differs from the generated plan")
    invalidate_build_paths([audit_path])
    recipe = declared_recipe["recipe"]
    require(recipe["kind"] == "declaration_shape",
            "materialization recipe is not declaration_shape")
    data = entropy_generator.generate_shape(
        recipe["classes"], recipe["functions"]
    ).encode("utf-8")
    parameters = {
        "classes": recipe["classes"],
        "functions": recipe["functions"],
    }
    require(sha256_bytes(data) == recipe["generated_header_sha256"],
            "materialized declaration hash differs")
    atomic_write(expected_output, data, if_changed=True)
    audit = {
        "status": "MATERIALIZED_NON_EMITTING_DECLARATIONS",
        "manifest_sha256": state["manifest_sha256"],
        "recipe_id": declared_recipe["id"],
        "users": declared_recipe["users"],
        "kind": recipe["kind"],
        "parameters": parameters,
        "output": str(expected_output),
        "output_sha256": sha256_bytes(data),
        "emission_policy": recipe["emission_policy"],
    }
    atomic_json(audit_path, audit)
    print(json.dumps(audit, sort_keys=True))
    return 0


def command_materialize(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_materialize_locked(arguments)


def command_materialize_archive_locked(arguments: argparse.Namespace) -> int:
    """Copy only an explicitly authorized, hash-pinned third-party archive."""
    require_resident_producer_scope()
    authority = active_build_authority()
    invalidate_framework_verdict(arguments.build_dir)
    requested_parts = authority.parts(arguments.output)
    require(
        requested_parts[:2] == ("byte-identity", "third-party-archives")
        and len(requested_parts) == 4,
        "archive materialization output is outside its fixed namespace",
    )
    # Invalidate both claims before manifest/source validation so a failed
    # rematerialization can never leave a prior archive eligible for linking.
    requested_audit = archive_audit_path(arguments.build_dir, arguments.identity)
    invalidate_build_paths([arguments.output, requested_audit])
    state = validate_manifest(
        arguments.manifest, arguments.source_dir, arguments.build_dir
    )
    archive = find_archive(state, arguments.identity)
    expected_output = Path(archive["output"])
    expected_audit = Path(archive["audit"])
    require(
        authority.parts(arguments.output) == authority.parts(expected_output)
        and authority.parts(requested_audit) == authority.parts(expected_audit),
        "archive materialization output differs from the generated plan",
    )
    source = Path(archive["source_path"])
    data = authority.read_external_bytes(source)
    require(
        data.startswith(b"!<arch>\n")
        and len(data) == archive["source_size"]
        and sha256_bytes(data) == archive["source_sha256"],
        f"authorized {archive['identity']} source archive differs",
    )
    validate_third_party_archive_directives(
        archive["identity"], data,
        f"authorized {archive['identity']} archive",
    )
    atomic_write(expected_output, data, if_changed=True)
    installed = authority.read_bytes(expected_output)
    require(installed == data,
            f"authorized {archive['identity']} archive copy differs")
    audit = {
        "status": "AUTHORIZED_THIRD_PARTY_ARCHIVE_MATERIALIZED",
        "manifest_sha256": state["manifest_sha256"],
        "kind": "third_party_reconstructed_archive",
        "identity": archive["identity"],
        "imported_target": archive["imported_target"],
        "payload_policy": THIRD_PARTY_RETAIL_ARCHIVE_POLICY,
        "copy_policy": "byte_exact_independent_build_authority_copy_v1",
        "source": archive["source_path"],
        "source_sha256": archive["source_sha256"],
        "source_size": archive["source_size"],
        "output": str(expected_output),
        "output_sha256": sha256_bytes(installed),
        "output_size": len(installed),
        "link_contract": archive["link_contract"],
    }
    exact_audit_keys(
        audit, ARCHIVE_MATERIALIZATION_AUDIT_KEYS,
        f"{archive['identity']} archive materialization audit",
    )
    atomic_json(expected_audit, audit)
    print(json.dumps(audit, sort_keys=True))
    return 0


def command_materialize_archive(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_materialize_archive_locked(arguments)


def stable_argv_sha256(argv: list[str]) -> str:
    require(isinstance(argv, list) and argv
            and all(isinstance(item, str) and item and "\0" not in item
                    for item in argv),
            "producer argv is empty or malformed")
    return sha256_bytes(json.dumps(
        argv, ensure_ascii=True, separators=(",", ":")
    ).encode("utf-8"))


def terminal_link_tool(state: dict, role: str) -> dict:
    tools = state.get("terminal_producers", {}).get("link", {}).get("tools", [])
    matches = [item for item in tools if item.get("role") == role]
    require(len(matches) == 1 and isinstance(matches[0].get("absolute_path"), str),
            f"terminal producer tool is not configured: {role}")
    return matches[0]


def _resident_file_identity(path: Path) -> tuple:
    return active_build_authority().stable_regular_file_identity(path)


def seed_resident_producer_state_cache(
    arguments: argparse.Namespace, state: dict, inventory: dict,
    command_inventory: dict, session: dict,
) -> dict:
    """Hold one authenticated producer policy for the resident transaction."""
    authority = active_build_authority()
    compiler = getattr(arguments, "configured_compiler", None)
    if compiler is None:
        compiler = getattr(arguments, "compiler", None)
    require(isinstance(compiler, str) and compiler,
            "resident producer cache compiler identity is absent")
    state["inventory"] = inventory
    state["inventory_sha256"] = sha256_file(inventory_path(arguments.build_dir))
    state["command_inventory"] = command_inventory
    state["command_inventory_sha256"] = sha256_file(
        command_inventory_path(arguments.build_dir)
    )
    state["command_policy_sha256"] = command_inventory["policy_sha256"]
    state["outer_session"] = session
    paths = [
        Path(arguments.manifest), inventory_path(arguments.build_dir),
        policy_stamp_path(arguments.build_dir),
        command_inventory_path(arguments.build_dir),
        command_policy_stamp_path(arguments.build_dir),
        authority.build_root / "compile_commands.json",
        active_session_path(arguments.build_dir),
        toolchain_snapshot_path(arguments.build_dir) / "snapshot.json",
        command_snapshot_path(arguments.build_dir) / "snapshot.json",
    ]
    cache = {
        "manifest": str(lexical_absolute_path(Path(arguments.manifest))),
        "source_dir": str(lexical_absolute_path(arguments.source_dir)),
        "build_dir": str(lexical_absolute_path(arguments.build_dir)),
        "configured_compiler": compiler,
        "session_nonce": session["nonce"],
        "session": session,
        "state": state,
        "inventory": inventory,
        "command_inventory": command_inventory,
        "paths": {str(path): _resident_file_identity(path) for path in paths},
    }
    authority.resident_producer_state_cache = cache
    return cache


def cached_resident_producer_state(
    arguments: argparse.Namespace,
) -> tuple[dict, dict, dict, dict] | None:
    authority = active_build_authority()
    cache = authority.resident_producer_state_cache
    if cache is None:
        return None
    compiler = getattr(arguments, "configured_compiler", None)
    if compiler is None:
        compiler = getattr(arguments, "compiler", None)
    require(
        cache["manifest"] == str(lexical_absolute_path(Path(arguments.manifest)))
        and cache["source_dir"] == str(lexical_absolute_path(arguments.source_dir))
        and cache["build_dir"] == str(lexical_absolute_path(arguments.build_dir))
        and cache["configured_compiler"] == compiler,
        "resident producer cached policy identity differs",
    )
    for path, expected in cache["paths"].items():
        require(_resident_file_identity(Path(path)) == expected,
                f"resident cached authority input changed: {path}")
    session = cache["session"]
    require(
        session["nonce"] == cache["session_nonce"]
        and os.environ.get(SESSION_NONCE_ENV) == session["nonce"]
        and process_exists(session["driver_pid"]),
        "resident cached outer session changed",
    )
    for key in (
        "toolchain:" + str(toolchain_snapshot_path(arguments.build_dir)),
        command_snapshot_cache_key(arguments.build_dir),
    ):
        held = authority.snapshot_validation_cache.get(key)
        require(held is not None,
                "resident cached producer state lost its held snapshot")
        held["holder"].revalidate()
    return (
        dict(cache["state"]), cache["inventory"],
        cache["command_inventory"], session,
    )


def load_producer_state(arguments: argparse.Namespace) -> tuple[dict, dict, dict, dict]:
    authority = active_build_authority()
    cached = cached_resident_producer_state(arguments)
    if cached is not None:
        return cached
    session = validate_active_session_authority(authority)
    require(session is not None,
            "producer launch requires the supported live outer build session")
    state = validate_manifest(
        arguments.manifest,
        arguments.source_dir,
        arguments.build_dir,
        configured_compiler=arguments.configured_compiler,
    )
    inventory = load_inventory(state, arguments.build_dir)
    command_inventory = load_command_inventory(state, inventory, arguments.build_dir)
    state["inventory"] = inventory
    state["inventory_sha256"] = sha256_file(inventory_path(arguments.build_dir))
    state["command_inventory"] = command_inventory
    state["command_inventory_sha256"] = sha256_file(
        command_inventory_path(arguments.build_dir)
    )
    state["outer_session"] = session
    seed_resident_producer_state_cache(
        arguments, state, inventory, command_inventory, session
    )
    return state, inventory, command_inventory, session


def validate_producer_state_postflight(
    arguments: argparse.Namespace, before: dict,
) -> tuple[dict, dict, dict, dict]:
    """Use held resident authority, or retain the standalone cold recheck."""
    if active_resident_receipt_ledger() is not None:
        cached = cached_resident_producer_state(arguments)
        require(cached is not None,
                "resident producer postflight cache is absent")
        state, inventory, command_inventory, session = cached
    else:
        state = validate_manifest(
            arguments.manifest, arguments.source_dir, arguments.build_dir,
            configured_compiler=arguments.configured_compiler,
        )
        inventory = load_inventory(state, arguments.build_dir)
        command_inventory = load_command_inventory(
            state, inventory, arguments.build_dir
        )
        session = validate_active_session_authority(
            active_build_authority()
        )
        require(session is not None,
                "producer postflight outer session is absent")
    require(
        state["manifest_sha256"] == before["manifest_sha256"]
        and state["toolchain_fingerprint"] == before["toolchain_fingerprint"]
        and state["framework_tool_sha256"] == before["framework_tool_sha256"]
        and state["backend_tool_sha256"] == before["backend_tool_sha256"]
        and state["entropy_tool_sha256"] == before["entropy_tool_sha256"],
        "manifest or toolchain changed during producer execution",
    )
    require(
        (inventory is before["inventory"]
         or exact_json_equal(inventory, before["inventory"]))
        and (command_inventory is before["command_inventory"]
             or exact_json_equal(
                 command_inventory, before["command_inventory"]
             )),
        "resident configure/command inventory changed during producer execution",
    )
    return state, inventory, command_inventory, session


def finalize_resident_producer_authority(
    arguments: argparse.Namespace,
) -> tuple[dict, dict, dict, dict]:
    """Cold-rederive every shared policy once before verification begins."""
    authority = active_build_authority()
    cached = authority.resident_producer_state_cache
    require(cached is not None,
            "resident terminal producer-state cache is absent")
    session = validate_active_session_authority(authority)
    require(session is not None and session["nonce"] == cached["session_nonce"],
            "resident terminal outer session differs")
    compiler = getattr(arguments, "compiler", None)
    if compiler is None:
        compiler = getattr(arguments, "configured_compiler", None)
    state = validate_manifest(
        arguments.manifest, arguments.source_dir, arguments.build_dir,
        configured_compiler=compiler,
    )
    inventory = load_inventory(state, arguments.build_dir)
    command_inventory = load_command_inventory(
        state, inventory, arguments.build_dir
    )
    require(
        state["manifest_sha256"] == cached["state"]["manifest_sha256"]
        and state["toolchain_fingerprint"]
        == cached["state"]["toolchain_fingerprint"]
        and exact_json_equal(inventory, cached["inventory"])
        and exact_json_equal(command_inventory, cached["command_inventory"]),
        "resident terminal policy rederivation differs from its held plan",
    )
    state["inventory"] = inventory
    state["inventory_sha256"] = sha256_file(
        inventory_path(arguments.build_dir)
    )
    state["command_inventory"] = command_inventory
    state["command_inventory_sha256"] = sha256_file(
        command_inventory_path(arguments.build_dir)
    )
    state["command_policy_sha256"] = command_inventory["policy_sha256"]
    state["outer_session"] = session
    finalize_command_snapshot_validation(
        command_inventory["entries"], arguments.build_dir,
        command_inventory["transport_snapshot"],
    )
    finalize_toolchain_snapshot_validation(state, arguments.build_dir)
    result = (state, inventory, command_inventory, session)
    authority.terminal_verification_state_cache = {
        "manifest": str(lexical_absolute_path(Path(arguments.manifest))),
        "source_dir": str(lexical_absolute_path(arguments.source_dir)),
        "build_dir": str(lexical_absolute_path(arguments.build_dir)),
        "compiler": compiler,
        "values": result,
    }
    return result


def resident_input_snapshot_roots(build_dir: Path) -> list[Path]:
    """Return the exact large resident-only input seats, in cleanup order."""
    return [
        runtime_bin_path(build_dir),
        toolchain_snapshot_path(build_dir),
        command_snapshot_path(build_dir),
        native_reccmp_snapshot_path(build_dir),
    ]


def close_resident_input_snapshot_holders(
    authority: BuildRootAuthority, build_dir: Path,
) -> None:
    """Close every held input descriptor independently before exact removal."""
    failures = []
    keys = [
        "toolchain:" + str(toolchain_snapshot_path(build_dir)),
        command_snapshot_cache_key(build_dir),
        _native_reccmp_cache_key(build_dir),
    ]
    closed = set()
    for key in keys:
        cached = authority.snapshot_validation_cache.pop(key, None)
        if cached is None:
            continue
        holders = []
        runtime = cached.get("runtime_bin")
        if isinstance(runtime, dict):
            holders.append(runtime.get("holder"))
        holders.append(cached.get("holder"))
        for holder in holders:
            if not isinstance(
                holder, (HeldBuildDirectories, HeldRuntimeExecutables)
            ) or id(holder) in closed:
                continue
            closed.add(id(holder))
            try:
                holder.close()
            except BaseException as error:
                failures.append(f"{key}: {error}")
    authority.resident_producer_state_cache = None
    require(not failures,
            "resident input holder cleanup failed: " + "; ".join(failures))


def discard_resident_input_snapshots(
    authority: BuildRootAuthority, build_dir: Path, *,
    invalidate_receipt: bool,
) -> None:
    """Failure-atomically remove only the resident's large copied inputs."""
    # An active marker owns the one deterministic projection/prefix epoch.
    # Its retained runtime-bin/toolchain is the only authority allowed to
    # retry wineserver shutdown. Never discard that recovery authority before
    # the marker has been retracted after exact-root removal.
    journal = execution_projection_recovery_path(build_dir)
    if authority.lstat(journal) is not None:
        if invalidate_receipt:
            invalidate_build_paths([resident_input_retirement_path(build_dir)])
            authority.resident_input_retirement_receipt = None
            authority.terminal_verification_state_cache = None
        return
    failures = []
    try:
        close_resident_input_snapshot_holders(authority, build_dir)
    except BaseException as error:
        failures.append(f"snapshot holders: {error}")
    try:
        rollback_exact_private_roots(
            authority, resident_input_snapshot_roots(build_dir),
            "resident input snapshot removal could not be proven",
        )
    except BaseException as error:
        failures.append(f"snapshot roots: {error}")
    if invalidate_receipt:
        try:
            invalidate_build_paths([resident_input_retirement_path(build_dir)])
            authority.resident_input_retirement_receipt = None
            authority.terminal_verification_state_cache = None
        except BaseException as error:
            failures.append(f"retirement receipt: {error}")
    require(not failures,
            "resident input cleanup failed: " + "; ".join(failures))


def retire_resident_input_snapshots(
    state: dict, build_dir: Path,
) -> tuple[dict, list[Path]]:
    """Remove terminally scanned copied inputs and publish compact evidence."""
    authority = active_build_authority()
    receipt_path = resident_input_retirement_path(build_dir)
    invalidate_build_paths([receipt_path])
    toolchain_key = "toolchain:" + str(toolchain_snapshot_path(build_dir))
    command_key = command_snapshot_cache_key(build_dir)
    native_key = _native_reccmp_cache_key(build_dir)
    toolchain = authority.snapshot_validation_cache.get(toolchain_key)
    command = authority.snapshot_validation_cache.get(command_key)
    native = authority.snapshot_validation_cache.get(native_key)
    require(
        all(isinstance(item, dict) and item.get("finalized") is True
            for item in (toolchain, command, native)),
        "resident input snapshots were not terminally scanned before removal",
    )
    runtime = toolchain.get("runtime_bin")
    require(isinstance(runtime, dict),
            "resident strict runtime seat was not held before removal")
    validate_runtime_bin(state, build_dir)
    descriptors = [
        {
            "role": "toolchain",
            "root": str(toolchain_snapshot_path(build_dir)),
            "descriptor_sha256": toolchain["descriptor_sha256"],
            "terminal_scan_complete": True,
            "removed": True,
        },
        {
            "role": "commands",
            "root": str(command_snapshot_path(build_dir)),
            "descriptor_sha256": command["descriptor_sha256"],
            "terminal_scan_complete": True,
            "removed": True,
        },
        {
            "role": "native_reccmp",
            "root": str(native_reccmp_snapshot_path(build_dir)),
            "descriptor_sha256": native["descriptor_sha256"],
            "terminal_scan_complete": True,
            "removed": True,
        },
    ]
    projection_path = execution_projection_finalization_path(build_dir)
    projection_data = authority.read_bytes(projection_path)
    roots = resident_input_snapshot_roots(build_dir)
    receipt = {
        "schema": 1,
        "status": "RESIDENT_INPUT_SNAPSHOTS_FINALIZED_AND_REMOVED",
        "manifest_sha256": state["manifest_sha256"],
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "execution_projection_receipt_sha256": sha256_bytes(projection_data),
        "snapshots": descriptors,
        "runtime_bin": {
            "path": str(runtime_bin_path(build_dir)),
            "target_count": len(runtime["targets"]),
            "targets_sha256": sha256_bytes(canonical_json_bytes(
                runtime["targets"]
            )),
            "removed": True,
        },
        "cache_holders_closed": True,
        "roots_removed": True,
    }
    discard_resident_input_snapshots(
        authority, build_dir, invalidate_receipt=False
    )
    raw = atomic_json(receipt_path, receipt)
    require(authority.read_bytes(receipt_path) == raw,
            "resident input retirement receipt changed during publication")
    authority.resident_input_retirement_receipt = json.loads(json.dumps(receipt))
    validate_resident_input_retirement_evidence(authority, build_dir)
    return receipt, roots


def validate_resident_input_retirement_evidence(
    authority: BuildRootAuthority, build_dir: Path,
) -> dict:
    """Trust only this transaction's in-memory removal receipt."""
    expected = authority.resident_input_retirement_receipt
    require(isinstance(expected, dict),
            "resident input retirement lacks in-memory authority")
    path = resident_input_retirement_path(build_dir)
    raw = authority.read_bytes(path)
    document = strict_json_loads(raw)
    require(isinstance(document, dict) and exact_json_equal(document, expected),
            "resident input retirement receipt differs from memory")
    exact_audit_keys(document, {
        "schema", "status", "manifest_sha256", "toolchain_fingerprint",
        "execution_projection_receipt_sha256", "snapshots", "runtime_bin",
        "cache_holders_closed", "roots_removed",
    }, "resident input retirement receipt")
    require(
        document.get("schema") == 1
        and document.get("status")
        == "RESIDENT_INPUT_SNAPSHOTS_FINALIZED_AND_REMOVED"
        and document.get("cache_holders_closed") is True
        and document.get("roots_removed") is True,
        "resident input retirement policy differs",
    )
    snapshots = document.get("snapshots")
    require(isinstance(snapshots, list) and len(snapshots) == 3,
            "resident input retirement snapshot universe differs")
    expected_roles = ["toolchain", "commands", "native_reccmp"]
    expected_roots = resident_input_snapshot_roots(build_dir)[1:]
    for index, (record, role, root) in enumerate(zip(
        snapshots, expected_roles, expected_roots, strict=True
    )):
        context = f"resident input retirement snapshot[{index}]"
        require(isinstance(record, dict), f"{context} is not an object")
        exact_audit_keys(record, {
            "role", "root", "descriptor_sha256",
            "terminal_scan_complete", "removed",
        }, context)
        require(
            record.get("role") == role and record.get("root") == str(root)
            and SHA256_RE.fullmatch(record.get("descriptor_sha256", ""))
            is not None
            and record.get("terminal_scan_complete") is True
            and record.get("removed") is True,
            f"{context} differs",
        )
    runtime = document.get("runtime_bin")
    require(isinstance(runtime, dict),
            "resident input retirement runtime record is invalid")
    exact_audit_keys(runtime, {
        "path", "target_count", "targets_sha256", "removed",
    }, "resident input retirement runtime")
    require(
        runtime.get("path") == str(runtime_bin_path(build_dir))
        and type(runtime.get("target_count")) is int
        and runtime["target_count"] > 0
        and SHA256_RE.fullmatch(runtime.get("targets_sha256", "")) is not None
        and runtime.get("removed") is True,
        "resident input retirement runtime record differs",
    )
    projection = authority.read_bytes(
        execution_projection_finalization_path(build_dir)
    )
    require(
        sha256_bytes(projection)
        == document.get("execution_projection_receipt_sha256"),
        "resident input retirement projection receipt changed",
    )
    for root in resident_input_snapshot_roots(build_dir):
        authority.assert_absent(root)
    for key in (
        "toolchain:" + str(toolchain_snapshot_path(build_dir)),
        command_snapshot_cache_key(build_dir),
        _native_reccmp_cache_key(build_dir),
    ):
        require(key not in authority.snapshot_validation_cache,
                "retired resident snapshot retained a validation cache")
    return document


def terminal_verification_inputs(
    arguments: argparse.Namespace,
) -> tuple[dict, dict, dict, dict]:
    """Reuse the resident's just-completed cold terminal policy validation."""
    authority = active_build_authority()
    cached = authority.terminal_verification_state_cache
    compiler = getattr(arguments, "compiler", None)
    if compiler is None:
        compiler = getattr(arguments, "configured_compiler", None)
    if cached is not None:
        require(
            cached["manifest"]
            == str(lexical_absolute_path(Path(arguments.manifest)))
            and cached["source_dir"]
            == str(lexical_absolute_path(arguments.source_dir))
            and cached["build_dir"]
            == str(lexical_absolute_path(arguments.build_dir))
            and cached["compiler"] == compiler,
            "terminal verification cache identity differs",
        )
        return cached["values"]
    session = validate_active_session_authority(authority)
    state = validate_manifest(
        arguments.manifest, arguments.source_dir, arguments.build_dir,
        configured_compiler=compiler,
    )
    inventory = load_inventory(state, arguments.build_dir)
    command_inventory = load_command_inventory(
        state, inventory, arguments.build_dir
    )
    state["inventory"] = inventory
    state["inventory_sha256"] = sha256_file(inventory_path(arguments.build_dir))
    state["command_inventory"] = command_inventory
    state["command_inventory_sha256"] = sha256_file(
        command_inventory_path(arguments.build_dir)
    )
    state["command_policy_sha256"] = command_inventory["policy_sha256"]
    state["outer_session"] = session
    return state, inventory, command_inventory, session


def invalidate_terminal_outputs(build_dir: Path) -> None:
    """Invalidate every descendant of resource/archive/link/reccmp mutation."""
    authority = active_build_authority()
    paths = [
        final_link_audit_path(build_dir, "LEGO1"),
        final_reccmp_audit_path(build_dir, "LEGO1"),
        final_report_path(build_dir, "LEGO1"),
        final_image_path(build_dir, "LEGO1"),
        final_pdb_path(build_dir, "LEGO1"),
        final_map_path(build_dir, "LEGO1"),
        final_implib_path(build_dir, "LEGO1"),
        final_exp_path(build_dir, "LEGO1"),
        final_link_log_path(build_dir, "LEGO1"),
        final_analysis_image_path(build_dir, "LEGO1"),
        final_analysis_map_path(build_dir, "LEGO1"),
        final_analysis_implib_path(build_dir, "LEGO1"),
        final_analysis_exp_path(build_dir, "LEGO1"),
        final_analysis_link_log_path(build_dir, "LEGO1"),
        final_reccmp_log_path(build_dir, "LEGO1"),
    ]
    invalidate_build_paths(paths)
    invalidate_framework_verdict(build_dir)
    for path in paths:
        authority.assert_absent(path)


def producer_child(arguments: argparse.Namespace) -> list[str]:
    child = list(arguments.child)
    if child and child[0] == "--":
        child.pop(0)
    require(child and not raw_argument_token_errors(child),
            "producer command is empty or contains literal quote bytes")
    return child


def decode_response_file(data: bytes, context: str) -> str:
    require(data and b"\0" not in data and len(data) <= 64 * 1024 * 1024,
            f"{context} is empty, binary, or too large")
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        try:
            return data.decode("cp1252")
        except UnicodeDecodeError as error:
            raise ByteIdentityError(
                f"{context} encoding is unsupported: {error}"
            ) from error


def expand_producer_response_files(
    argv: list[str], cwd: Path,
) -> tuple[list[str], list[dict], list[Path]]:
    """Expand exact build-tree response files for provenance, never execution."""
    authority = active_build_authority()
    expanded = []
    records = []
    paths = []
    for index, token in enumerate(argv):
        if not token.startswith("@"):
            expanded.append(token)
            continue
        require(len(token) > 1 and index > 0,
                "producer response-file token is malformed")
        path = lexical_argument_path(token[1:], cwd)
        authority.parts(path)
        data = authority.read_bytes(path, max_bytes=64 * 1024 * 1024)
        text = decode_response_file(data, f"producer response file {path}")
        try:
            tokens = shlex.split(text, comments=False, posix=True)
        except ValueError as error:
            raise ByteIdentityError(
                f"producer response file quoting is invalid: {path}: {error}"
            ) from error
        require(tokens and not any(value.startswith("@") for value in tokens),
                "nested or empty producer response files are forbidden")
        require(not raw_argument_token_errors(tokens),
                "producer response file contains literal quote bytes")
        records.append({
            "path": str(path), "sha256": sha256_bytes(data),
            "size": len(data), "tokens": tokens,
        })
        paths.append(path)
        expanded.extend(tokens)
    require(records == sorted(records, key=lambda item: item["path"])
            or len(records) == 1,
            "producer response-file order is noncanonical")
    return expanded, records, paths


def attached_msvc_option_values(argv: list[str], name: str) -> list[str]:
    values = []
    prefix = name.casefold() + ":"
    for token in argv[1:]:
        folded = token.casefold()
        if folded.startswith(("/" + prefix, "-" + prefix)):
            value = token[len(name) + 2:]
            require(value, f"/{name}: has an empty producer value")
            values.append(value)
        elif folded in ("/" + name.casefold(), "-" + name.casefold()):
            raise ByteIdentityError(
                f"/{name} producer value must be attached with a colon"
            )
    return values


def unique_producer_output(
    argv: list[str], option: str, cwd: Path, expected: Path | None = None,
) -> Path:
    values = attached_msvc_option_values(argv, option)
    require(len(values) == 1,
            f"producer command must contain exactly one /{option}: output")
    path = lexical_argument_path(values[0], cwd)
    authority = active_build_authority()
    authority.parts(path)
    if expected is not None:
        require(authority.parts(path) == authority.parts(expected),
                f"producer /{option}: output differs from its fixed seat")
    return path


def projected_tool_sha256(state: dict, tool: dict) -> str:
    """Return the exact copied tool SHA, including typed wrapper transforms."""
    authority = active_build_authority()
    root = toolchain_snapshot_path(Path(state["build_dir"]))
    cached = authority.snapshot_validation_cache.get("toolchain:" + str(root))
    require(cached is not None, "projected tool lacks held toolchain authority")
    receipts = cached["descriptor"].get("msvc_wrapper_transforms")
    require(isinstance(receipts, list),
            "projected wrapper transform receipts are absent")
    matches = [
        item for item in receipts
        if item.get("source_path") == tool["absolute_path"]
    ]
    if not matches:
        return tool["sha256"]
    require(
        len(matches) == 1
        and matches[0].get("source_sha256") == tool["sha256"],
        f"projected wrapper transform receipt differs: {tool['role']}",
    )
    return require_sha(
        matches[0].get("output_sha256"),
        f"projected wrapper transform {tool['role']} output SHA-256",
    )


def snapshotted_tool_path(run: dict, state: dict, tool: dict) -> Path:
    return validate_projected_immutable_file_identity(
        run["projection"], Path(tool["absolute_path"]),
        projected_tool_sha256(state, tool),
        f"run-private producer tool {tool['role']}", executable=True,
    )


def held_runtime_executable_path(
    state: dict, build_dir: Path, name: str,
) -> Path:
    """Resolve one exact runtime-bin entry without an ambient shebang hop."""
    matches = [
        item for item in state["runtime_executables"]
        if item["name"] == name
    ]
    require(len(matches) == 1,
            f"strict runtime executable is not uniquely pinned: {name}")
    runtime = matches[0]
    validate_runtime_bin(state, build_dir)
    target = runtime_target_path(build_dir, runtime)
    entry = runtime_bin_path(build_dir) / name
    authority = active_build_authority()
    cache = authority.snapshot_validation_cache[
        "toolchain:" + str(toolchain_snapshot_path(build_dir))
    ]["runtime_bin"]
    entry_metadata = authority.lstat(entry)
    require(
        entry_metadata is not None and stat.S_ISLNK(entry_metadata.st_mode)
        and authority.readlink(entry) == str(target)
        and authority.stable_regular_file_identity(target)
        == tuple(cache["identities"][name]),
        f"held strict runtime executable differs: {name}",
    )
    return entry


def projected_compiler_support_sha256(state: dict, item: dict) -> str:
    """Return source SHA or an authorized transformed transport SHA."""
    environment = state["transport"]["msvc_environment"]
    root_policy = environment["root_transform"]
    argument_policy = environment["argument_path_transform"]
    authority = active_build_authority()
    root = toolchain_snapshot_path(Path(state["build_dir"]))
    cached = authority.snapshot_validation_cache.get("toolchain:" + str(root))
    require(cached is not None,
            "MSVC environment transform lacks held toolchain authority")
    wrapper_matches = [
        receipt
        for receipt in cached["descriptor"].get("msvc_wrapper_transforms", [])
        if receipt.get("source_path") == item["absolute_path"]
    ]
    if wrapper_matches:
        require(
            len(wrapper_matches) == 1
            and wrapper_matches[0].get("source_sha256") == item["sha256"],
            "held MSVC wrapper transform receipt differs",
        )
        return require_sha(
            wrapper_matches[0].get("output_sha256"),
            "held MSVC wrapper transform output SHA-256",
        )
    if item["path"] not in (root_policy["script"], argument_policy["script"]):
        return item["sha256"]
    if item["path"] == root_policy["script"]:
        receipt = cached["descriptor"].get("msvc_environment_transform")
        schema = MSVC_ENVIRONMENT_ROOT_TRANSFORM_SCHEMA
        context = "environment"
    else:
        receipt = cached["descriptor"].get("msvc_argument_transform")
        schema = MSVC_WINE_ARGUMENT_TRANSFORM_SCHEMA
        context = "argument"
    require(isinstance(receipt, dict) and receipt.get("schema") == schema
            and receipt.get("source_path") == item["absolute_path"]
            and receipt.get("source_sha256") == item["sha256"],
            f"held MSVC {context} transform receipt differs")
    return require_sha(
        receipt.get("output_sha256"),
        f"held MSVC {context} transform output SHA-256",
    )


def snapshotted_compiler_command(
    run: dict, state: dict, generated: list[str],
) -> list[str]:
    """Execute the held wrapper through held bash, never its ambient shebang."""
    require(
        isinstance(generated, list) and generated
        and lexical_absolute_path(Path(generated[0]))
        == lexical_absolute_path(Path(state["compiler_path"])),
        "generated compiler command does not begin with the configured wrapper",
    )
    tool = compiler_wrapper_tool(state)
    return [
        str(held_runtime_executable_path(
            state, Path(state["build_dir"]), "bash"
        )),
        str(snapshotted_tool_path(run, state, tool)),
        *generated[1:],
    ]


def compiler_wrapper_tool(state: dict) -> dict:
    return {
        "role": "compiler_wrapper",
        "absolute_path": state["compiler_path"],
        "sha256": state["compiler_sha256"],
    }


def validate_snapshotted_compiler_command_hash(
    state: dict, generated: list[str], transport: dict,
    observed_sha256: object, context: str,
) -> None:
    """Rederive the sole generated-to-executed compiler argv substitution."""
    projection = Path(transport.get("execution_projection_root", ""))
    expected = [
        str(runtime_bin_path(Path(state["build_dir"])) / "bash"),
        str(absolute_snapshot_seat(
            projection / "z", Path(state["compiler_path"])
        )),
        *generated[1:],
    ]
    require(
        require_sha(observed_sha256, f"{context} SHA-256")
        == stable_argv_sha256(expected),
        f"{context} does not map to the held compiler wrapper",
    )


def producer_input_record(path: Path, role: str) -> dict:
    authority = active_build_authority()
    path = lexical_absolute_path(path)
    if active_authority_for_path(path) is authority:
        data = authority.read_bytes(path, max_bytes=1 << 30)
    else:
        data = authority.read_external_bytes(path, max_bytes=1 << 30)
    return {
        "role": role, "path": str(path), "sha256": sha256_bytes(data),
        "size": len(data),
    }


def sealed_producer_input_record(
    logical: Path, snapshot: Path, role: str,
) -> dict:
    """Bind one logical external input to bytes in immutable build authority."""
    authority = active_build_authority()
    logical = lexical_absolute_path(logical)
    authority.parts(snapshot)
    data = authority.read_bytes(snapshot, max_bytes=1 << 30)
    metadata = authority.lstat(snapshot)
    require(metadata is not None and stat.S_ISREG(metadata.st_mode)
            and not (stat.S_IMODE(metadata.st_mode) & 0o222),
            f"sealed producer input is absent or writable: {snapshot}")
    return {
        "role": role,
        "path": str(logical),
        "snapshot_path": str(snapshot),
        "sha256": sha256_bytes(data),
        "size": len(data),
    }


def compiler_output_records(
    state: dict, inventory: dict, *, target: str | None = None,
) -> list[dict]:
    authority = active_build_authority()
    result = []
    for entry in inventory["entries"]:
        if target is not None and entry["target"] != target:
            continue
        audit_path = Path(entry["audit"])
        audit = read_unique_audit(audit_path, authority.build_root, "compiler producer audit")
        keys = LISTED_COMPILER_AUDIT_KEYS if entry["listed"] else UNLISTED_COMPILER_AUDIT_KEYS
        exact_audit_keys(audit, keys, f"compiler producer audit {audit_path}")
        require(audit.get("manifest_sha256") == state["manifest_sha256"]
                and audit.get("target") == entry["target"]
                and audit.get("source") == entry["source"],
                f"compiler producer audit ownership differs: {audit_path}")
        output = Path(audit.get("object", ""))
        authority.parts(output)
        record = producer_input_record(output, "compiler_object")
        require(record["sha256"] == audit.get("object_sha256"),
                f"compiler producer object differs: {output}")
        record.update({
            "target": entry["target"], "source": entry["source"],
            "target_ordinal": entry["target_ordinal"],
            "audit": str(audit_path), "audit_sha256": sha256_file(audit_path),
        })
        result.append(record)
    return sorted(result, key=lambda item: (
        item["target"], item["target_ordinal"]
    ))


def resource_output_records(
    state: dict, inventory: dict, *, target: str | None = None,
) -> list[dict]:
    authority = active_build_authority()
    result = []
    for item in inventory["inputs"]:
        if item["kind"] != "RC" or (target is not None and item["target"] != target):
            continue
        audit_path = Path(item["audit"])
        audit = read_unique_audit(audit_path, authority.build_root, "resource producer audit")
        exact_audit_keys(audit, RESOURCE_PRODUCER_AUDIT_KEYS,
                         f"resource producer audit {audit_path}")
        validate_producer_support_audit(
            state, "resource", audit.get("producer_support"),
            f"resource producer support {audit_path}",
        )
        require(audit.get("schema") == 1
                and audit.get("status") == "RESOURCE_OUTPUT_PRODUCED"
                and audit.get("manifest_sha256") == state["manifest_sha256"]
                and audit.get("target") == item["target"]
                and audit.get("source") == item["source"]
                and audit.get("source_sha256") == item["source_sha256"],
                f"resource producer audit ownership differs: {audit_path}")
        session = state.get("outer_session")
        require(session is not None
                and audit.get("inventory_sha256") == state["inventory_sha256"]
                and audit.get("command_inventory_sha256")
                == state["command_inventory_sha256"],
                f"resource producer session/inventory differs: {audit_path}")
        rc_wrapper = terminal_link_tool(state, "rc_wrapper")
        rc_binary = terminal_link_tool(state, "rc_binary")
        generated = audit.get("generated_argv")
        executed = audit.get("executed_argv")
        require(isinstance(generated, list)
                and not raw_argument_token_errors(generated)
                and stable_argv_sha256(generated)
                == audit.get("generated_argv_sha256")
                and isinstance(executed, list)
                and stable_argv_sha256(executed)
                == audit.get("executed_argv_sha256"),
                f"resource producer argv hash differs: {audit_path}")
        require(generated[0].casefold() in {
                    "rc", "rc.exe", rc_wrapper["absolute_path"].casefold()
                }, f"resource producer wrapper differs: {audit_path}")
        cwd = Path(audit.get("cwd", ""))
        authority.parts(cwd, allow_root=True)
        parsed_source, parsed_output, parsed_roles = parse_resource_command(
            generated, cwd
        )
        require(parsed_source == Path(item["source_path"])
                and authority.parts(parsed_output)
                == authority.parts(Path(audit.get("output", "")))
                and audit.get("tool") == rc_wrapper["absolute_path"]
                and audit.get("tool_sha256") == rc_wrapper["sha256"]
                and audit.get("tool_binary") == rc_binary["absolute_path"]
                and audit.get("tool_binary_sha256") == rc_binary["sha256"],
                f"resource producer tool/source/output grammar differs: {audit_path}")
        validate_virtual_z_executed_argv(
            state, generated, executed, Path(rc_wrapper["absolute_path"]),
            f"resource producer {audit_path}",
        )
        validate_execution_projection_evidence(
            audit.get("execution_projection_root"),
            audit.get("execution_projection_descriptor_sha256"),
            Path(state["build_dir"]), f"resource producer {audit_path}",
        )
        closure = audit.get("input_closure")
        require(isinstance(closure, dict),
                f"resource producer input closure is invalid: {audit_path}")
        exact_audit_keys(
            closure, {"policy", "roles", "command_snapshot"},
            f"resource producer input closure {audit_path}",
        )
        require(closure.get("policy")
                == "immutable_virtual_z_command_and_toolchain_snapshots_v1"
                and exact_json_equal(closure.get("roles"), parsed_roles)
                and exact_json_equal(
                    closure.get("command_snapshot"),
                    state["command_inventory"]["transport_snapshot"]["z"],
                ), f"resource producer input closure differs: {audit_path}")
        validate_producer_snapshot_hashes(
            state, audit, f"resource producer {audit_path}"
        )
        require_nonnegative_finite_number(
            audit.get("elapsed_seconds"),
            f"resource producer {audit_path} elapsed_seconds",
        )
        output = Path(audit.get("output", ""))
        authority.parts(output)
        record = producer_input_record(output, "resource_output")
        require(record["sha256"] == audit.get("output_sha256")
                and record["size"] == require_exact_int(
                    audit.get("output_size"),
                    f"resource producer {audit_path} output_size", minimum=1,
                ),
                f"resource output differs: {output}")
        record.update({
            "target": item["target"], "source": item["source"],
            "target_ordinal": item["target_ordinal"],
            "audit": str(audit_path), "audit_sha256": sha256_file(audit_path),
        })
        result.append(record)
    return sorted(result, key=lambda item: (
        item["target"], item["target_ordinal"]
    ))


def target_output_records(
    state: dict, inventory: dict, target: str,
) -> list[dict]:
    """Return the exact CMake source occurrence order for one target."""
    records = [
        *compiler_output_records(state, inventory, target=target),
        *resource_output_records(state, inventory, target=target),
    ]
    require(records and len({item["target_ordinal"] for item in records})
                        == len(records),
            f"target output source ordinals are empty or duplicated: {target}")
    return sorted(records, key=lambda item: item["target_ordinal"])


def producer_run_environment(
    state: dict, build_dir: Path, run: dict, temporary: Path,
) -> dict[str, str]:
    return strict_child_environment(state, build_dir, temporary, run=run)


def execute_virtual_z_producer(
    *, state: dict, run: dict, argv: list[str], tool: dict,
    timeout: int, use_compiler_slot: bool, logical_temporary: Path,
) -> tuple[bytes, float]:
    executed = [
        str(held_runtime_executable_path(
            state, Path(state["build_dir"]), "bash"
        )),
        str(snapshotted_tool_path(run, state, tool)),
        *argv[1:],
    ]
    environment = producer_run_environment(
        state, Path(state["build_dir"]), run, logical_temporary
    )
    started = time.monotonic()
    slot = (
        compiler_slot(Path(state["build_dir"]), timeout)
        if use_compiler_slot else nullcontext()
    )
    with slot:
        run["holder"].revalidate()
        drain_run_private_wineserver(run, state, environment, phase="preflight")
        try:
            validate_virtual_z_prelaunch(run, state, tool)
            mark_virtual_z_child_started(run)
            returncode, output, timed_out = run_child(
                executed, timeout, environment, cwd=run["cwd"]
            )
        finally:
            drain_run_private_wineserver(run, state, environment, phase="postflight")
        run["holder"].revalidate()
    require(not timed_out, "producer child timed out")
    require(returncode == 0,
            f"producer child exited with status {returncode}: "
            + output.decode("utf-8", errors="replace")[:2000])
    verify_virtual_z_inputs(run, state)
    run["executed_argv"] = executed
    return output, time.monotonic() - started


def parse_resource_command(
    argv: list[str], cwd: Path,
) -> tuple[Path, Path, list[dict]]:
    require(len(argv) >= 4 and not any(token.startswith("@") for token in argv),
            "resource command is too short or uses a response file")
    source = lexical_argument_path(argv[-1], cwd)
    roles = []
    output_values = []
    index = 1
    while index < len(argv) - 1:
        token = argv[index]
        folded = token.casefold()
        if folded in ("/fo", "-fo"):
            require(index + 1 < len(argv) - 1,
                    "resource /fo output operand is absent")
            output_values.append(argv[index + 1])
            roles.append({"role": "output", "value": argv[index + 1],
                          "separate": True})
            index += 2
            continue
        require(not folded.startswith(("/fo", "-fo")),
                "resource /fo must use CMake's exact separated grammar")
        if folded in ("/d", "-d", "/i", "-i"):
            require(index + 1 < len(argv) - 1,
                    f"resource option operand is absent: {token}")
            roles.append({
                "role": folded[1:].upper(), "value": argv[index + 1],
                "separate": True,
            })
            index += 2
            continue
        if (folded.startswith(("/d", "-d", "/i", "-i"))
                and len(token) > 2):
            roles.append({
                "role": token[1].upper(), "value": token[2:],
                "separate": False,
            })
            index += 1
            continue
        raise ByteIdentityError(f"unsupported resource compiler option: {token}")
    require(len(output_values) == 1,
            "resource command must contain exactly one /fo output")
    output = lexical_argument_path(output_values[0], cwd)
    authority = active_build_authority()
    authority.parts(output)
    return source, output, roles


def invalidate_resource_target(build_dir: Path, target: str) -> None:
    authority = active_build_authority()
    root = authority.build_root / "byte-identity/audit/resources" / target
    metadata = authority.lstat(root)
    if metadata is None:
        return
    require(stat.S_ISDIR(metadata.st_mode),
            f"resource audit target root is redirected: {root}")
    for name in authority.list_names(root):
        path = root / name
        try:
            audit = strict_json_loads(authority.read_text(path))
            if isinstance(audit, dict) and isinstance(audit.get("output"), str):
                output = Path(audit["output"])
                authority.parts(output)
                invalidate_build_paths([output])
        except (ByteIdentityError, OSError, UnicodeError, json.JSONDecodeError):
            pass
    authority.remove_tree(root)


def command_resource_launch_locked(arguments: argparse.Namespace) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    require(TARGET_RE.fullmatch(arguments.target) is not None,
            "resource producer target is invalid")
    invalidate_terminal_outputs(arguments.build_dir)
    invalidate_resource_target(arguments.build_dir, arguments.target)
    child = producer_child(arguments)
    cwd = lexical_absolute_path(Path.cwd())
    source, output, roles = parse_resource_command(child, cwd)
    authority.parts(output)
    invalidate_build_paths([output])
    state, inventory, command_inventory, session = load_producer_state(arguments)
    candidates = [
        item for item in inventory["inputs"]
        if item["kind"] == "RC" and item["target"] == arguments.target
        and Path(item["source_path"]) == source
    ]
    require(len(candidates) == 1,
            "resource command does not name one configured RC input")
    item = candidates[0]
    audit_path = Path(item["audit"])
    invalidate_build_paths([audit_path])
    sealed_source = absolute_snapshot_seat(
        command_snapshot_path(arguments.build_dir) / "z", source
    )
    require(sha256_file(sealed_source) == item["source_sha256"],
            "sealed resource source differs from configure inventory")
    rc_wrapper = terminal_link_tool(state, "rc_wrapper")
    rc_binary = terminal_link_tool(state, "rc_binary")
    require(child[0].casefold() in {
                "rc", "rc.exe", str(Path(rc_wrapper["absolute_path"])).casefold()
            }, "resource command does not begin with the pinned RC wrapper")
    source_tree = state["command_inventory"]["transport_snapshot"]["z"]
    temporary = (
        authority.build_root / "byte-identity/work/resources"
        / arguments.target
        / hashlib.sha256(item["source"].encode("utf-8")).hexdigest()[:16]
        / "tmp"
    )
    authority.remove_tree(temporary.parent)
    authority.mkdirs(temporary)
    started = time.monotonic()
    run = prepare_virtual_z_run(
        state=state, build_dir=arguments.build_dir, target=arguments.target,
        source_relative=item["source"], role="resource", cwd=cwd,
        logical_outputs=[output], temporary=temporary,
    )
    try:
        log, _ = execute_virtual_z_producer(
            state=state, run=run, argv=child, tool=rc_wrapper,
            timeout=state["terminal_producers"]["link"]["max_child_seconds"],
            use_compiler_slot=True, logical_temporary=temporary,
        )
        physical = run["outputs"][0]
        data = run["holder"].read_bytes(physical)
        require(data and run["holder"].membership(physical.parent)
                == {physical.name: "file"},
                "resource compiler emitted an undeclared output")
        require(not run["holder"].membership(run["temporary"]),
                "resource compiler temporary namespace is not empty")
        executed_argv = run["executed_argv"]
        cleanup_virtual_z_run(run)
        audit = {
            "schema": 1,
            "status": "RESOURCE_OUTPUT_PRODUCED",
            "manifest_sha256": state["manifest_sha256"],
            "inventory_sha256": state["inventory_sha256"],
            "command_inventory_sha256": state["command_inventory_sha256"],
            "target": arguments.target,
            "source": item["source"],
            "source_sha256": item["source_sha256"],
            "input_closure": {
                "policy": "immutable_virtual_z_command_and_toolchain_snapshots_v1",
                "roles": roles,
                "command_snapshot": source_tree,
            },
            "tool": rc_wrapper["absolute_path"],
            "tool_sha256": rc_wrapper["sha256"],
            "tool_binary": rc_binary["absolute_path"],
            "tool_binary_sha256": rc_binary["sha256"],
            "generated_argv": child,
            "generated_argv_sha256": stable_argv_sha256(child),
            "executed_argv": executed_argv,
            "executed_argv_sha256": stable_argv_sha256(executed_argv),
            "cwd": str(cwd),
            "toolchain_snapshot_sha256": run["toolchain_snapshot_sha256"],
            "command_snapshot_sha256": run["command_snapshot_sha256"],
            "producer_support": run["producer_support"],
            **execution_projection_audit_identity(run),
            "output": str(output),
            "output_sha256": sha256_bytes(data),
            "output_size": len(data),
            "elapsed_seconds": float(time.monotonic() - started),
        }
        exact_audit_keys(audit, RESOURCE_PRODUCER_AUDIT_KEYS,
                         "resource producer audit")
        atomic_write(output, data)
        atomic_json(audit_path, audit)
        sys.stdout.buffer.write(log)
        sys.stdout.buffer.flush()
    except BaseException:
        invalidate_build_paths([output, audit_path])
        raise
    finally:
        cleanup_virtual_z_runs_aggregate([run])
    print(json.dumps({"resource": audit}, sort_keys=True))
    return 0


def command_resource_launch(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_resource_launch_locked(arguments)


def command_compile_dispatch(arguments: argparse.Namespace) -> int:
    """Target-level outer dispatcher for C/C++ and RC compile rules.

    CMake ignores source-level RULE_LAUNCH_COMPILE for RC on the supported
    generators.  Target scope is reliable, but it also wraps ordinary C/C++
    commands.  Those already contain the exact compile-launch prefix and are
    forwarded byte-for-byte; only a terminal inventoried `.rc` source is
    routed to the resource producer.
    """
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    require(TARGET_RE.fullmatch(arguments.target) is not None,
            "compile dispatcher target is invalid")
    child = producer_child(arguments)
    cwd = lexical_absolute_path(Path.cwd())
    terminal = lexical_argument_path(child[-1], cwd)
    if terminal.suffix.casefold() == ".rc":
        routed = argparse.Namespace(
            manifest=arguments.manifest,
            source_dir=arguments.source_dir,
            build_dir=arguments.build_dir,
            target=arguments.target,
            configured_compiler=arguments.configured_compiler,
            child=["--", *child],
        )
        return command_resource_launch(routed)

    expected = [
        str(Path(sys.executable).resolve()), "-I", "-B",
        str(Path(__file__).resolve()), "compile-launch",
        "--manifest", str(arguments.manifest),
        "--source-dir", str(arguments.source_dir),
        "--build-dir", str(arguments.build_dir),
        "--target", arguments.target,
        "--configured-compiler", arguments.configured_compiler,
        "--",
    ]
    require(child[:len(expected)] == expected,
            "compile dispatcher C/C++ child differs from the pinned launcher chain")
    returncode, output, timed_out = run_child(
        child, 900, dict(os.environ), cwd=cwd
    )
    sys.stdout.buffer.write(output)
    sys.stdout.buffer.flush()
    require(not timed_out, "compile dispatcher child timed out")
    return returncode


def invalidate_first_party_archive_target(build_dir: Path, target: str) -> None:
    authority = active_build_authority()
    audit_path = first_party_archive_audit_path(build_dir, target)
    metadata = authority.lstat(audit_path)
    if metadata is not None and stat.S_ISREG(metadata.st_mode):
        try:
            prior = strict_json_loads(authority.read_text(audit_path))
            if isinstance(prior, dict) and isinstance(prior.get("output"), str):
                output = Path(prior["output"])
                authority.parts(output)
                invalidate_build_paths([output])
        except (ByteIdentityError, OSError, UnicodeError, json.JSONDecodeError):
            pass
    invalidate_build_paths([audit_path])


def parse_archive_command(
    argv: list[str], cwd: Path,
) -> tuple[Path, list[Path], list[dict], list[Path], list[str]]:
    expanded, response_files, response_paths = expand_producer_response_files(
        argv, cwd
    )
    output = unique_producer_output(expanded, "out", cwd)
    inputs = []
    for token in expanded[1:]:
        folded = token.casefold()
        if folded in ("/nologo", "-nologo", "/machine:i386", "-machine:i386"):
            continue
        if folded.startswith(("/out:", "-out:")):
            continue
        suffix = PurePosixPath(token.replace("\\", "/")).suffix.casefold()
        if suffix in (".obj", ".res"):
            path = lexical_argument_path(token, cwd)
            active_build_authority().parts(path)
            inputs.append(path)
            continue
        raise ByteIdentityError(f"unsupported archive producer token: {token}")
    require(inputs and len(inputs) == len(set(map(str, inputs))),
            "archive producer inputs are empty or duplicated")
    return output, inputs, response_files, response_paths, expanded


def ordered_first_party_archive_inputs(
    input_paths: list[Path], expected_records: list[dict], context: str,
) -> list[dict]:
    """Bind LIB inputs to the exact audited compiler/resource output seats.

    A content hash is deliberately insufficient here.  In particular, a
    scratch or external object that happens to contain the same bytes as an
    authenticated compiler output is still an opaque first-party payload and
    may not be substituted for that output's fixed build-authority pathname.
    """
    authority = active_build_authority()
    expected_by_path: dict[str, dict] = {}
    for index, record in enumerate(expected_records):
        item_context = f"{context} expected input[{index}]"
        require(isinstance(record, dict), f"{item_context} is not an object")
        require(record.get("role") in {"compiler_object", "resource_output"},
                f"{item_context} has an unsupported producer role")
        value = record.get("path")
        require(isinstance(value, str) and value,
                f"{item_context} path is absent")
        path = lexical_absolute_path(Path(value))
        authority.parts(path)
        require(str(path) == value and value not in expected_by_path,
                f"{item_context} path is noncanonical or duplicated")
        expected_by_path[value] = record
    canonical_inputs = []
    for index, path in enumerate(input_paths):
        canonical = lexical_absolute_path(path)
        authority.parts(canonical)
        require(str(canonical) == str(path),
                f"{context} input[{index}] path is noncanonical")
        canonical_inputs.append(str(canonical))
    expected_sequence = [record["path"] for record in expected_records]
    require(expected_by_path and canonical_inputs == expected_sequence,
            f"{context} input order/occurrences differ from the exact "
            "audited target object/resource sequence")
    return [expected_by_path[path] for path in canonical_inputs]


def command_archive_launch_locked(arguments: argparse.Namespace) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    require(TARGET_RE.fullmatch(arguments.target) is not None,
            "archive producer target is invalid")
    invalidate_terminal_outputs(arguments.build_dir)
    invalidate_first_party_archive_target(arguments.build_dir, arguments.target)
    child = producer_child(arguments)
    cwd = lexical_absolute_path(Path.cwd())
    output, input_paths, response_files, response_paths, expanded = (
        parse_archive_command(child, cwd)
    )
    invalidate_build_paths([output])
    state, inventory, command_inventory, session = load_producer_state(arguments)
    target_records = [
        item for item in inventory["targets"]
        if item["target"] == arguments.target
    ]
    require(len(target_records) == 1
            and target_records[0]["kind"] == "STATIC_LIBRARY",
            "archive producer target is not an inventoried static library")
    lib_wrapper = terminal_link_tool(state, "lib_wrapper")
    lib_binary = terminal_link_tool(state, "lib_binary")
    require(Path(child[0]).resolve(strict=True)
            == Path(lib_wrapper["absolute_path"]),
            "archive command does not begin with the pinned LIB wrapper")
    expected_records = target_output_records(
        state, inventory, arguments.target
    )
    ordered_inputs = ordered_first_party_archive_inputs(
        input_paths, expected_records, "archive producer",
    )
    generated_inputs = [*response_paths, *input_paths]
    temporary = (
        authority.build_root / "byte-identity/work/first-party-archives"
        / arguments.target / "tmp"
    )
    authority.remove_tree(temporary.parent)
    authority.mkdirs(temporary)
    audit_path = first_party_archive_audit_path(
        arguments.build_dir, arguments.target
    )
    started = time.monotonic()
    run = prepare_virtual_z_run(
        state=state, build_dir=arguments.build_dir, target=arguments.target,
        source_relative=f"archive/{arguments.target}", role="archive",
        cwd=cwd, logical_outputs=[output], temporary=temporary,
        generated_inputs=generated_inputs,
    )
    try:
        log, _ = execute_virtual_z_producer(
            state=state, run=run, argv=child, tool=lib_wrapper,
            timeout=state["terminal_producers"]["link"]["max_child_seconds"],
            use_compiler_slot=False, logical_temporary=temporary,
        )
        physical = run["outputs"][0]
        data = run["holder"].read_bytes(physical)
        require(data.startswith(b"!<arch>\n")
                and run["holder"].membership(physical.parent)
                == {physical.name: "file"},
                "LIB did not produce one exact archive output")
        validate_first_party_archive_payload(
            data, ordered_inputs,
            f"resident first-party archive {arguments.target}",
        )
        require(not run["holder"].membership(run["temporary"]),
                "LIB temporary namespace is not empty")
        executed_argv = run["executed_argv"]
        cleanup_virtual_z_run(run)
        audit = {
            "schema": 1,
            "status": "FIRST_PARTY_ARCHIVE_PRODUCED",
            "manifest_sha256": state["manifest_sha256"],
            "inventory_sha256": state["inventory_sha256"],
            "command_inventory_sha256": state["command_inventory_sha256"],
            "target": arguments.target,
            "tool": lib_wrapper["absolute_path"],
            "tool_sha256": lib_wrapper["sha256"],
            "tool_binary": lib_binary["absolute_path"],
            "tool_binary_sha256": lib_binary["sha256"],
            "generated_argv": child,
            "generated_argv_sha256": stable_argv_sha256(child),
            "executed_argv": executed_argv,
            "executed_argv_sha256": stable_argv_sha256(executed_argv),
            "cwd": str(cwd),
            "response_files": response_files,
            "ordered_inputs": ordered_inputs,
            "toolchain_snapshot_sha256": run["toolchain_snapshot_sha256"],
            "command_snapshot_sha256": run["command_snapshot_sha256"],
            "producer_support": run["producer_support"],
            **execution_projection_audit_identity(run),
            "output": str(output),
            "output_sha256": sha256_bytes(data),
            "output_size": len(data),
            "elapsed_seconds": float(time.monotonic() - started),
        }
        exact_audit_keys(audit, FIRST_PARTY_ARCHIVE_AUDIT_KEYS,
                         "first-party archive producer audit")
        atomic_write(output, data)
        atomic_json(audit_path, audit)
        sys.stdout.buffer.write(log)
        sys.stdout.buffer.flush()
    except BaseException:
        invalidate_build_paths([output, audit_path])
        raise
    finally:
        cleanup_virtual_z_runs_aggregate([run])
    print(json.dumps({"first_party_archive": audit}, sort_keys=True))
    return 0


def command_archive_launch(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_archive_launch_locked(arguments)


def first_party_archive_records(
    state: dict, inventory: dict, session: dict,
) -> list[dict]:
    authority = active_build_authority()
    require(isinstance(session, dict)
            and state.get("outer_session", {}).get("nonce") == session.get("nonce"),
            "first-party archive verification requires the live outer session")
    records = []
    for target in inventory["targets"]:
        if target["kind"] != "STATIC_LIBRARY":
            continue
        audit_path = first_party_archive_audit_path(
            Path(state["build_dir"]), target["target"]
        )
        audit = read_unique_audit(
            audit_path, authority.build_root, "first-party archive producer audit"
        )
        exact_audit_keys(audit, FIRST_PARTY_ARCHIVE_AUDIT_KEYS,
                         f"first-party archive audit {audit_path}")
        validate_producer_support_audit(
            state, "archive", audit.get("producer_support"),
            f"first-party archive support {audit_path}",
        )
        require(audit.get("schema") == 1
                and audit.get("status") == "FIRST_PARTY_ARCHIVE_PRODUCED"
                and audit.get("manifest_sha256") == state["manifest_sha256"]
                and audit.get("inventory_sha256") == state["inventory_sha256"]
                and audit.get("command_inventory_sha256")
                == state["command_inventory_sha256"]
                and audit.get("target") == target["target"],
                f"first-party archive producer policy differs: {audit_path}")
        lib_wrapper = terminal_link_tool(state, "lib_wrapper")
        lib_binary = terminal_link_tool(state, "lib_binary")
        generated = audit.get("generated_argv")
        executed = audit.get("executed_argv")
        require(isinstance(generated, list)
                and not raw_argument_token_errors(generated)
                and stable_argv_sha256(generated)
                == audit.get("generated_argv_sha256")
                and isinstance(executed, list)
                and stable_argv_sha256(executed)
                == audit.get("executed_argv_sha256"),
                f"first-party archive argv hash differs: {audit_path}")
        require(Path(generated[0]).resolve(strict=True)
                == Path(lib_wrapper["absolute_path"]),
                f"first-party archive wrapper differs: {audit_path}")
        cwd = Path(audit.get("cwd", ""))
        authority.parts(cwd, allow_root=True)
        (parsed_output, parsed_inputs, parsed_responses, _response_paths,
         _expanded) = parse_archive_command(generated, cwd)
        require(audit.get("tool") == lib_wrapper["absolute_path"]
                and audit.get("tool_sha256") == lib_wrapper["sha256"]
                and audit.get("tool_binary") == lib_binary["absolute_path"]
                and audit.get("tool_binary_sha256") == lib_binary["sha256"]
                and authority.parts(parsed_output)
                == authority.parts(Path(audit.get("output", "")))
                and exact_json_equal(parsed_responses,
                                     audit.get("response_files")),
                f"first-party archive tool/output/response grammar differs: {audit_path}")
        validate_producer_response_records(audit.get("response_files"))
        validate_virtual_z_executed_argv(
            state, generated, executed, Path(lib_wrapper["absolute_path"]),
            f"first-party archive {audit_path}",
        )
        validate_execution_projection_evidence(
            audit.get("execution_projection_root"),
            audit.get("execution_projection_descriptor_sha256"),
            Path(state["build_dir"]), f"first-party archive {audit_path}",
        )
        validate_producer_snapshot_hashes(
            state, audit, f"first-party archive {audit_path}"
        )
        require_nonnegative_finite_number(
            audit.get("elapsed_seconds"),
            f"first-party archive {audit_path} elapsed_seconds",
        )
        output = Path(audit.get("output", ""))
        authority.parts(output)
        record = producer_input_record(output, "first_party_archive")
        require(record["sha256"] == audit.get("output_sha256")
                and record["size"] == require_exact_int(
                    audit.get("output_size"),
                    f"first-party archive {audit_path} output_size", minimum=8,
                ),
                f"first-party archive output differs: {output}")
        expected = target_output_records(
            state, inventory, target["target"]
        )
        expected_order = ordered_first_party_archive_inputs(
            parsed_inputs, expected, f"first-party archive {audit_path}",
        )
        require(exact_json_equal(audit.get("ordered_inputs"), expected_order),
                f"first-party archive ordered input records differ: {audit_path}")
        for item in audit["ordered_inputs"]:
            current = producer_input_record(Path(item["path"]), item["role"])
            require(current["sha256"] == item.get("sha256")
                    and current["size"] == item.get("size"),
                    f"first-party archive input changed: {item.get('path')}")
        record.update({
            "target": target["target"], "audit": str(audit_path),
            "audit_sha256": sha256_file(audit_path),
        })
        records.append(record)
    return sorted(records, key=lambda item: item["path"])


def authorized_archive_records(state: dict) -> list[dict]:
    authority = active_build_authority()
    records = []
    require({item["identity"] for item in state["archives"]}
            == REQUIRED_THIRD_PARTY_ARCHIVES,
            "terminal link requires exactly SmartHeap and Smacker archives")
    for archive in state["archives"]:
        audit_path = Path(archive["audit"])
        audit = read_unique_audit(
            audit_path, authority.build_root, "authorized archive audit"
        )
        exact_audit_keys(audit, ARCHIVE_MATERIALIZATION_AUDIT_KEYS,
                         f"authorized archive audit {audit_path}")
        require(audit.get("status")
                == "AUTHORIZED_THIRD_PARTY_ARCHIVE_MATERIALIZED"
                and audit.get("identity") == archive["identity"]
                and audit.get("manifest_sha256") == state["manifest_sha256"]
                and audit.get("payload_policy") == THIRD_PARTY_RETAIL_ARCHIVE_POLICY,
                f"authorized archive audit policy differs: {audit_path}")
        output = Path(archive["output"])
        record = producer_input_record(output, "authorized_third_party_archive")
        require(record["sha256"] == archive["source_sha256"]
                and record["sha256"] == audit.get("output_sha256")
                and record["size"] == audit.get("output_size"),
                f"authorized archive output differs: {output}")
        validate_third_party_archive_directives(
            archive["identity"], authority.read_bytes(output, max_bytes=1 << 30),
            f"authorized {archive['identity']} archive",
        )
        record.update({
            "identity": archive["identity"], "audit": str(audit_path),
            "audit_sha256": sha256_file(audit_path),
        })
        records.append(record)
    return sorted(records, key=lambda item: item["path"])


def casefold_regular_child(directory: Path, name: str) -> Path | None:
    authority = active_authority_for_path(directory)
    try:
        names = (
            authority.list_names(directory) if authority is not None
            else sorted(item.name for item in directory.iterdir())
        )
    except (FileNotFoundError, NotADirectoryError, OSError):
        return None
    matches = [item for item in names if item.casefold() == name.casefold()]
    require(len(matches) <= 1,
            f"linker library search has a casefold collision: {directory}/{name}")
    if not matches:
        return None
    path = directory / matches[0]
    if authority is not None:
        require(authority.is_regular_file(path),
                f"linker input is not a regular build file: {path}")
    else:
        require(path.resolve(strict=True) == path and path.is_file()
                and not path.is_symlink(),
                f"linker input is redirected or non-regular: {path}")
    return path


def link_search_directories(
    expanded: list[str], cwd: Path, state: dict,
) -> list[tuple[Path, Path]]:
    directories = [cwd]
    for token in expanded[1:]:
        folded = token.casefold()
        for prefix in ("/libpath:", "-libpath:"):
            if folded.startswith(prefix):
                value = token[len(prefix):]
                require(value, "linker /LIBPATH value is empty")
                directories.append(lexical_argument_path(value, cwd))
                break
    directories.extend(
        Path(item["absolute_path"])
        for item in state["terminal_producers"]["link"]["library_trees"]
    )
    authority = active_build_authority()
    source_root = Path(state["source_dir"])
    command_z = command_snapshot_path(Path(state["build_dir"])) / "z"
    toolchain_z = toolchain_snapshot_path(Path(state["build_dir"])) / "z"
    library_roots = [
        Path(item["absolute_path"])
        for item in state["terminal_producers"]["link"]["library_trees"]
    ]
    result = []
    seen = set()
    for directory in directories:
        directory = lexical_absolute_path(directory)
        if active_authority_for_path(directory) is authority:
            physical = directory
        elif directory == source_root or directory.is_relative_to(source_root):
            physical = absolute_snapshot_seat(command_z, directory)
        elif any(directory == root or directory.is_relative_to(root)
                 for root in library_roots):
            physical = absolute_snapshot_seat(toolchain_z, directory)
        else:
            raise ByteIdentityError(
                f"linker search directory is outside sealed build/source/toolchain inputs: {directory}"
            )
        identity = str(directory)
        if identity not in seen:
            seen.add(identity)
            result.append((directory, physical))
    return result


def resolve_link_input(
    token: str, cwd: Path, search_directories: list[tuple[Path, Path]], state: dict,
    planned_inputs: dict[str, Path] | None = None,
) -> Path:
    normalized = token.replace("\\", "/")
    pathish = Path(normalized).is_absolute() or "/" in normalized
    if pathish:
        candidate = lexical_argument_path(normalized, cwd)
        authority = active_authority_for_path(candidate)
        if authority is not None:
            require(authority.is_regular_file(candidate)
                    or candidate in set((planned_inputs or {}).values()),
                    f"linker build input is absent: {candidate}")
        else:
            source_root = Path(state["source_dir"])
            library_roots = [
                Path(item["absolute_path"])
                for item in state["terminal_producers"]["link"]["library_trees"]
            ]
            if candidate == source_root or candidate.is_relative_to(source_root):
                snapshot = absolute_snapshot_seat(
                    command_snapshot_path(Path(state["build_dir"])) / "z",
                    candidate,
                )
            elif any(candidate == root or candidate.is_relative_to(root)
                     for root in library_roots):
                snapshot = absolute_snapshot_seat(
                    toolchain_snapshot_path(Path(state["build_dir"])) / "z",
                    candidate,
                )
            else:
                raise ByteIdentityError(
                    f"linker external input is outside sealed snapshots: {candidate}"
                )
            require(active_build_authority().is_regular_file(snapshot),
                    f"sealed linker external input is absent: {candidate}")
        return candidate
    planned = (planned_inputs or {}).get(token.casefold())
    if planned is not None:
        return planned
    matches = []
    for logical_directory, physical_directory in search_directories:
        match = casefold_regular_child(physical_directory, token)
        if match is not None:
            matches.append(logical_directory / match.name)
            # LINK uses first-match search order; later duplicates remain
            # relevant only as negative shadow state captured by tree Merkle.
            break
    require(len(matches) == 1, f"linker library cannot be resolved: {token}")
    return matches[0]


def parse_link_command(
    argv: list[str], cwd: Path, state: dict,
    planned_inputs: dict[str, Path] | None = None,
) -> dict:
    expanded, response_files, response_paths = expand_producer_response_files(
        argv, cwd
    )
    image = unique_producer_output(expanded, "out", cwd,
                                   final_image_path(Path(state["build_dir"]), "LEGO1"))
    implib = unique_producer_output(
        expanded, "implib", cwd,
        final_implib_path(Path(state["build_dir"]), "LEGO1")
    )
    pdb = unique_producer_output(
        expanded, "pdb", cwd,
        final_pdb_path(Path(state["build_dir"]), "LEGO1")
    )
    map_path = unique_producer_output(
        expanded, "map", cwd,
        final_map_path(Path(state["build_dir"]), "LEGO1")
    )
    require(sum(token.casefold() in ("/verbose:lib", "-verbose:lib")
                for token in expanded) == 1,
            "terminal link requires exactly one /VERBOSE:LIB")
    require(not any(token.casefold().startswith(("/debug", "-debug"))
                    for token in expanded),
            "release terminal link must not enable /DEBUG")
    require(sum(token.casefold() in ("/dll", "-dll") for token in expanded) == 1,
            "terminal LEGO1 link must be exactly one DLL link")
    def_inputs = []
    lib_tokens = []
    direct_tokens = []
    allowed_exact = {
        "/nologo", "-nologo", "/dll", "-dll",
        "/verbose:lib", "-verbose:lib",
    }
    allowed_prefixes = (
        "/out:", "-out:", "/implib:", "-implib:", "/pdb:", "-pdb:",
        "/map:", "-map:", "/version:", "-version:",
        "/machine:", "-machine:", "/incremental:", "-incremental:",
        "/def:", "-def:", "/opt:", "-opt:",
        "/libpath:", "-libpath:", "/subsystem:", "-subsystem:",
    )
    for token in expanded[1:]:
        folded = token.casefold()
        if folded in allowed_exact:
            continue
        if folded.startswith(allowed_prefixes):
            if folded.startswith(("/def:", "-def:")):
                def_inputs.append(lexical_argument_path(token.split(":", 1)[1], cwd))
            continue
        suffix = PurePosixPath(token.replace("\\", "/")).suffix.casefold()
        if suffix in (".obj", ".res"):
            direct_tokens.append(token)
        elif suffix == ".lib":
            lib_tokens.append(token)
        else:
            raise ByteIdentityError(f"unsupported terminal linker token: {token}")
    require(len(def_inputs) == 1,
            "terminal LEGO1 link requires exactly one /DEF input")
    require(any(item["kind"] == "LINKER_DEF"
                and Path(item["source_path"]) == def_inputs[0]
                for item in state["inventory"]["inputs"]),
            "terminal link /DEF input is absent from configure inventory")
    search = link_search_directories(expanded, cwd, state)
    direct = [resolve_link_input(token, cwd, search, state, planned_inputs)
              for token in direct_tokens]
    libraries = [resolve_link_input(token, cwd, search, state, planned_inputs)
                 for token in lib_tokens]
    return {
        "generated": argv, "expanded": expanded,
        "response_files": response_files, "response_paths": response_paths,
        "image": image, "implib": implib, "pdb": pdb, "map": map_path,
        "definition": def_inputs[0], "direct": direct,
        "libraries": libraries,
    }


def terminal_generator_standard_library_tail(
    state: dict, inventory: dict,
) -> list[str]:
    standard_libraries = inventory.get("generator_standard_libraries")
    require(isinstance(standard_libraries, dict)
            and exact_json_equal(
                standard_libraries,
                state["terminal_producers"]["link"][
                    "generator_standard_libraries"
                ],
            ), "terminal generator standard-library inventory differs")
    return [
        *standard_libraries["base"],
        *standard_libraries["configuration_specific"],
    ]


def require_terminal_generator_standard_library_suffix(
    state: dict, inventory: dict, logical_libraries: list[str], context: str,
) -> list[str]:
    tail = terminal_generator_standard_library_tail(state, inventory)
    require(not tail or logical_libraries[-len(tail):] == tail,
            f"{context} generator standard-library suffix differs")
    return tail


def terminal_link_graph_authority(
    state: dict, inventory: dict,
) -> tuple[set[str], set[str], set[str]]:
    """Return reachable normal targets, imported targets, and raw libraries."""
    graph = {item["target"]: item for item in inventory["link_graph"]}
    require(len(graph) == len(inventory["link_graph"]) and "lego1" in graph,
            "terminal link graph has no unique lego1 root")
    imported = {
        item["name"]: item
        for item in state["terminal_producers"]["link"]["imported_targets"]
    }
    require(len(imported) == len(REQUIRED_IMPORTED_TARGETS),
            "terminal imported-target contract is duplicated")
    reachable_normal: set[str] = set()
    reachable_imported: set[str] = set()
    raw_libraries: set[str] = set()
    for name in terminal_generator_standard_library_tail(state, inventory):
        raw_libraries.add(name)

    def consume_token(token: str, context: str) -> None:
        if token in graph:
            visit_normal(token)
            return
        if token in imported:
            visit_imported(token)
            return
        require(re.fullmatch(r"[A-Za-z0-9_+.\-]+(?:\.lib)?", token) is not None,
                f"{context} is not a target or a simple library name: {token}")
        raw_libraries.add(
            token.casefold() if token.casefold().endswith(".lib")
            else token.casefold() + ".lib"
        )

    def visit_normal(target: str) -> None:
        if target in reachable_normal:
            return
        reachable_normal.add(target)
        for index, token in enumerate(graph[target]["resolved_links"]):
            consume_token(token, f"normal target {target} link[{index}]")

    def visit_imported(target: str) -> None:
        if target in reachable_imported:
            return
        reachable_imported.add(target)
        contract = imported[target]
        for index, token in enumerate(
            contract["properties"]["INTERFACE_LINK_LIBRARIES"]
        ):
            for resolved in _resolve_link_graph_token(
                token, f"imported target {target} link[{index}]"
            ):
                consume_token(resolved, f"imported target {target} link[{index}]")

    visit_normal("lego1")
    return reachable_normal, reachable_imported, raw_libraries


def terminal_link_ordered_inputs(
    state: dict, inventory: dict, session: dict, parsed: dict,
) -> list[dict]:
    """Reconstruct the exact generated LINK input order and provenance roles."""
    direct_expected = target_output_records(state, inventory, "lego1")
    direct_by_path = {item["path"]: item for item in direct_expected}
    expected_direct_sequence = [item["path"] for item in direct_expected]
    require(len(direct_by_path) == len(direct_expected)
            and list(map(str, parsed["direct"])) == expected_direct_sequence,
            "terminal direct OBJ/RES order/occurrences differ from the exact "
            "lego1 source sequence")
    reachable_normal, reachable_imported, raw_library_names = (
        terminal_link_graph_authority(state, inventory)
    )
    logical_library_sequence = [path.name.casefold() for path in parsed["libraries"]]
    link_policy = state["terminal_producers"]["link"]
    require_terminal_generator_standard_library_suffix(
        state, inventory, logical_library_sequence, "terminal"
    )
    require(
        len(logical_library_sequence)
        == link_policy["ordered_library_occurrence_count"]
        and sha256_bytes((
            "\n".join(logical_library_sequence) + "\n"
        ).encode("utf-8"))
        == link_policy["ordered_library_identity_sha256"],
        "terminal library order/multiplicity differs from the manifest-pinned "
        "logical occurrence sequence",
    )
    known_libraries = [
        *first_party_archive_records(state, inventory, session),
        *authorized_archive_records(state),
    ]
    known_by_path = {item["path"]: item for item in known_libraries}
    require(len(known_by_path) == len(known_libraries),
            "terminal library provenance paths are duplicated")
    sdk_by_path = {}
    for item in state["terminal_producers"]["link"]["project_sdk_libraries"]:
        path = Path(item["absolute_path"])
        snapshot = absolute_snapshot_seat(
            command_snapshot_path(Path(state["build_dir"])) / "z", path
        )
        record = sealed_producer_input_record(
            path, snapshot, "sealed_project_sdk_library"
        )
        require(record["sha256"] == item["sha256"],
                f"sealed project SDK library changed: {path}")
        sdk_by_path[str(path)] = record
    require(len(sdk_by_path) == len(REQUIRED_PROJECT_SDK_LIBRARIES),
            "sealed project SDK library path universe differs")
    ordered_inputs = [direct_by_path[str(path)] for path in parsed["direct"]]
    original = Path(state["images"][0]["original_path"])
    for path in parsed["libraries"]:
        require(path != original,
                "retail final image is forbidden as a linker input")
        record = known_by_path.get(str(path))
        if record is None:
            record = sdk_by_path.get(str(path))
        if record is None:
            # All remaining import/CRT libraries must resolve inside one of
            # the exact MSVC/MFC content-Merkle roots. A new source-tree .lib
            # can never become an implicitly admitted linker payload.
            allowed_roots = [
                Path(item["absolute_path"])
                for item in state["terminal_producers"]["link"]["library_trees"]
            ]
            require(any(path.is_relative_to(root) for root in allowed_roots),
                    f"linker library is outside every exact manifest pin: {path}")
            require(path.name.casefold() in raw_library_names,
                    f"sealed MSVC library is absent from the transitive CMake graph: {path.name}")
            snapshot = absolute_snapshot_seat(
                toolchain_snapshot_path(Path(state["build_dir"])) / "z", path
            )
            record = sealed_producer_input_record(
                path, snapshot, "sealed_msvc_library"
            )
        if record["role"] == "first_party_archive":
            require(record["target"] in reachable_normal,
                    f"first-party archive is not reachable from lego1: {record['target']}")
        elif record["role"] == "authorized_third_party_archive":
            expected_target = next(
                item["imported_target"] for item in state["archives"]
                if item["identity"] == record["identity"]
            )
            require(expected_target in reachable_imported,
                    f"authorized archive is not reachable from lego1: {record['identity']}")
        elif record["role"] == "sealed_project_sdk_library":
            require(path.name.casefold() in raw_library_names,
                    f"project SDK library is absent from the transitive CMake graph: {path.name}")
        ordered_inputs.append(record)
    definition_snapshot = absolute_snapshot_seat(
        command_snapshot_path(Path(state["build_dir"])) / "z",
        parsed["definition"],
    )
    ordered_inputs.append(sealed_producer_input_record(
        parsed["definition"], definition_snapshot, "linker_definition"
    ))
    consumed_authorized = {
        item.get("identity") for item in ordered_inputs
        if item.get("role") == "authorized_third_party_archive"
    }
    require(consumed_authorized == REQUIRED_THIRD_PARTY_ARCHIVES,
            "terminal link did not consume exactly SmartHeap and Smacker")
    reachable_first_party = {
        item["target"] for item in inventory["targets"]
        if item["kind"] == "STATIC_LIBRARY"
        and item["target"] in reachable_normal
    }
    consumed_first_party = {
        item.get("target") for item in ordered_inputs
        if item.get("role") == "first_party_archive"
    }
    require(consumed_first_party == reachable_first_party,
            "terminal link omitted or added a reachable first-party archive")
    return ordered_inputs


def pe_text_record(data: bytes) -> dict:
    require(len(data) >= 0x100 and data[:2] == b"MZ", "link image is not a PE file")
    pe_offset, = struct.unpack_from("<I", data, 0x3C)
    require(pe_offset <= len(data) - 24 and data[pe_offset:pe_offset + 4] == b"PE\0\0",
            "link image PE header is invalid")
    section_count, = struct.unpack_from("<H", data, pe_offset + 6)
    optional_size, = struct.unpack_from("<H", data, pe_offset + 20)
    optional = pe_offset + 24
    require(optional_size >= 32 and optional <= len(data) - optional_size,
            "link image optional header is invalid")
    magic, = struct.unpack_from("<H", data, optional)
    require(magic == 0x10B, "terminal link image is not PE32")
    image_base, = struct.unpack_from("<I", data, optional + 28)
    sections = optional + optional_size
    matches = []
    for index in range(section_count):
        offset = sections + index * 40
        require(offset <= len(data) - 40, "link image section table is truncated")
        name = data[offset:offset + 8].rstrip(b"\0")
        virtual_size, rva, raw_size, raw_offset = struct.unpack_from(
            "<IIII", data, offset + 8
        )
        if name == b".text":
            require(raw_size and raw_offset <= len(data) - raw_size,
                    "link image .text raw data is invalid")
            body = data[raw_offset:raw_offset + raw_size]
            matches.append({
                "rva": rva, "va": image_base + rva,
                "virtual_size": virtual_size, "size": raw_size,
                "sha256": sha256_bytes(body), "body": body,
            })
    require(len(matches) == 1, "link image has no unique .text section")
    return matches[0]


def validate_link_evidence(
    map_data: bytes, verbose_data: bytes, policy: dict,
) -> tuple[list[dict], list[dict]]:
    map_text = decode_response_file(map_data, "terminal LINK map")
    verbose_text = decode_response_file(verbose_data, "terminal LINK verbose log")
    verified_map = []
    for expected in policy["map_evidence"]:
        library_stem = PurePosixPath(expected["library"]).stem.casefold()
        expected_address = expected["address"].removeprefix("0x").casefold()
        matches = []
        for line in map_text.splitlines():
            fields = line.split()
            if (expected["symbol"] not in fields
                    or expected_address not in {
                        field.removeprefix("0x").casefold() for field in fields
                    }):
                continue
            tail = fields[-1]
            if ":" not in tail:
                continue
            library, member = tail.rsplit(":", 1)
            if (PurePosixPath(library).stem.casefold() == library_stem
                    and member.casefold() == expected["member"].casefold()):
                matches.append(line)
        require(len(matches) == 1,
                f"terminal map evidence is absent or duplicated: {expected['symbol']}")
        verified_map.append(dict(expected))
    lines = verbose_text.splitlines()
    verified_members = []
    for expected in policy["member_evidence"]:
        found_indices = [
            index for index, line in enumerate(lines)
            if line.strip() == f"Found {expected['symbol']}"
        ]
        matching_blocks = 0
        for start in found_indices:
            end = start + 1
            while end < len(lines) and not lines[end].lstrip().startswith(
                ("Found ", "Searching ")
            ):
                end += 1
            block = "\n".join(line.strip() for line in lines[start:end])
            reference = f"Referenced in {expected['referenced_in']}"
            loaded = f"Loaded {expected['library']}({expected['member']})"
            if reference in block and loaded.casefold() in block.casefold():
                matching_blocks += 1
        require(matching_blocks >= 1,
                f"terminal member-pull evidence is absent: {expected['symbol']}")
        verified_members.append(dict(expected))
    return verified_map, verified_members


def _directive_defaultlibs(raw: bytes, context: str) -> list[str]:
    """Parse the finite classic-LINK directive grammar without normalization."""
    try:
        text = raw.decode("ascii", "strict")
    except UnicodeDecodeError as error:
        raise ByteIdentityError(f"{context} .drectve is not ASCII") from error
    require(text and "\0" not in text and "\t" not in text
            and "\r" not in text and "\n" not in text,
            f"{context} .drectve whitespace differs")
    tokens = text.split(" ")
    if tokens[-1] == "":
        tokens.pop()
    require(tokens and all(tokens) and text in {
                " ".join(tokens), " ".join(tokens) + " "
            }, f"{context} .drectve token spacing differs")
    defaults = []
    for token in tokens:
        folded = token.casefold()
        if folded.startswith("-defaultlib:"):
            value = token.split(":", 1)[1]
            require(re.fullmatch(r"[A-Za-z0-9_+.-]+", value) is not None,
                    f"{context} .drectve default library is invalid")
            name = value.casefold()
            defaults.append(name if name.endswith(".lib") else name + ".lib")
            continue
        require(
            (folded.startswith("-export:") and len(token) > len("-export:"))
            or (folded.startswith("/include:")
                and len(token) > len("/include:")),
            f"{context} .drectve contains an unsupported LINK option",
        )
    return defaults


def _verbose_library_path(value: str, cwd: Path) -> Path:
    normalized = value.strip().strip('"').replace("\\", "/")
    if re.match(r"^[zZ]:/", normalized):
        normalized = normalized[2:]
    require(not re.match(r"^[A-Ya-y]:", normalized) and "\0" not in normalized,
            f"terminal /VERBOSE:LIB contains an unknown drive: {value}")
    if normalized.startswith("/"):
        return lexical_absolute_path(Path(normalized))
    return lexical_absolute_path(Path(normalized), cwd)


def _archive_directive_for_loaded_member(
    *, data: bytes, member: str, role: str, identity: str | None,
    context: str,
) -> tuple[bytes | None, str]:
    members = [
        (name, payload) for name, payload in parse_coff_archive_members(data, context)
        if PurePosixPath(name).name.casefold()
        == PurePosixPath(member.replace("\\", "/")).name.casefold()
    ]
    require(len(members) == 1,
            f"{context} loaded member is absent or ambiguous: {member}")
    name, payload = members[0]
    raw = raw_coff_directive(payload, f"{context} member {name}")
    if raw is None:
        return None, name
    if role == "first_party_archive":
        validate_first_party_object_directive(
            payload, f"{context} member {name}"
        )
    elif role == "authorized_third_party_archive":
        require(identity in REQUIRED_THIRD_PARTY_ARCHIVES,
                f"{context} authorized archive identity differs")
        expected = (
            SMARTHEAP_DIRECTIVE_MEMBERS
            if identity == "SmartHeap" else SMACKER_DIRECTIVE_MEMBERS
        )
        require(expected.get(PurePosixPath(name).name.casefold()) == raw,
                f"{context} member {name} directive differs from its exact allowlist")
    _directive_defaultlibs(raw, f"{context} member {name}")
    return raw, name


def parse_vc42_verbose_library_log(verbose_data: bytes) -> dict:
    """Parse VC4.2's detailed search pass and final deduplicated list."""
    text = decode_response_file(verbose_data, "terminal LINK verbose log")
    lines = text.splitlines()
    search_headers = [
        index for index, line in enumerate(lines)
        if line == "Searching Libraries"
    ]
    done_headers = [
        index for index, line in enumerate(lines)
        if line == "Done Searching Libraries"
    ]
    pass2 = [
        index for index, line in enumerate(lines) if line == "Start Pass2"
    ]
    require(len(search_headers) == 2 and len(done_headers) == 2
            and len(pass2) == 1
            and search_headers[0] < done_headers[0] < search_headers[1]
            < done_headers[1] < pass2[0],
            "terminal /VERBOSE:LIB pass grammar differs")
    processed_re = re.compile(r"Processed /DEFAULTLIB:([A-Za-z0-9_+.-]+)")
    search_re = re.compile(r"    Searching (.+):")
    loaded_re = re.compile(r"        Loaded ([^()]+)\(([^()]*)\)")
    events = []
    for index, line in enumerate(lines[:done_headers[0] + 1], start=1):
        match = processed_re.fullmatch(line)
        if match is not None:
            events.append({
                "kind": "processed", "line": index, "value": match.group(1)
            })
            continue
        if index - 1 < search_headers[0]:
            continue
        match = search_re.fullmatch(line)
        if match is not None:
            events.append({
                "kind": "search", "line": index, "value": match.group(1)
            })
            continue
        match = loaded_re.fullmatch(line)
        if match is not None:
            events.append({
                "kind": "loaded", "line": index,
                "library": match.group(1), "member": match.group(2),
            })
    flat = []
    for index in range(search_headers[1] + 1, done_headers[1]):
        line = lines[index]
        if not line:
            continue
        match = search_re.fullmatch(line)
        require(match is not None,
                "terminal /VERBOSE:LIB flat search list grammar differs")
        flat.append({"line": index + 1, "value": match.group(1)})
    require(any(item["kind"] == "search" for item in events)
            and any(item["kind"] == "loaded" for item in events)
            and flat,
            "terminal /VERBOSE:LIB resolution evidence is empty")
    return {
        "schema": "vc42_verbose_library_log_v1",
        "events": events,
        "flat": flat,
        "start_pass2_line": pass2[0] + 1,
    }


def validate_verbose_library_resolution_closure(
    verbose_data: bytes, explicit_libraries: list[Path], state: dict,
    ordered_inputs: list[dict], cwd: Path,
) -> dict:
    """Reconstruct the exact VC4.2 library-search and member-pull closure."""
    structure = parse_vc42_verbose_library_log(verbose_data)

    authority = active_build_authority()
    library_roles = {
        "first_party_archive", "authorized_third_party_archive",
        "sealed_project_sdk_library", "sealed_msvc_library",
    }
    input_records = [
        item for item in ordered_inputs
        if isinstance(item, dict) and item.get("role") in library_roles
    ]
    explicit_keys = {}
    for path in explicit_libraries:
        matches = [item for item in input_records if item.get("path") == str(path)]
        require(len(matches) >= 1,
                f"terminal explicit library has no ordered provenance: {path}")
        key = str(lexical_absolute_path(path)).casefold()
        require(key not in explicit_keys
                or explicit_keys[key].get("sha256") == matches[0].get("sha256"),
                f"terminal explicit library identity is ambiguous: {path}")
        explicit_keys[key] = matches[0]

    direct_defaults: set[str] = set()
    for item in ordered_inputs:
        if not isinstance(item, dict) or item.get("role") != "compiler_object":
            continue
        path = Path(item["path"])
        data = authority.read_bytes(path, max_bytes=1 << 30)
        require(sha256_bytes(data) == item.get("sha256"),
                f"terminal direct object changed: {path}")
        raw = validate_first_party_object_directive(
            data, f"terminal direct object {item.get('target')}:{item.get('source')}"
        )
        direct_defaults.update(_directive_defaultlibs(
            raw, f"terminal direct object {item.get('target')}:{item.get('source')}"
        ))

    library_trees = [
        (Path(item["absolute_path"]), absolute_snapshot_seat(
            toolchain_snapshot_path(Path(state["build_dir"])) / "z",
            Path(item["absolute_path"]),
        ))
        for item in state["terminal_producers"]["link"]["library_trees"]
    ]

    def resolved_record(value: str) -> tuple[Path, Path, dict]:
        logical = _verbose_library_path(value, cwd)
        explicit = explicit_keys.get(str(logical).casefold())
        if explicit is not None:
            physical = Path(explicit.get("snapshot_path", explicit["path"]))
            return Path(explicit["path"]), physical, explicit
        matches = []
        for logical_root, physical_root in library_trees:
            if str(logical.parent).casefold() != str(logical_root).casefold():
                continue
            child = casefold_regular_child(physical_root, logical.name)
            if child is not None:
                matches.append((logical_root / child.name, child, {
                    "role": "implicit_msvc_directive_library",
                    "path": str(logical_root / child.name),
                    "snapshot_path": str(child),
                    "sha256": sha256_file(child),
                    "size": child.stat(follow_symlinks=False).st_size,
                }))
        require(len(matches) == 1,
                f"terminal /VERBOSE:LIB path is outside exact inputs: {value}")
        return matches[0]

    processed: list[str] = []
    discovered = set(direct_defaults)
    searched: list[dict] = []
    loaded: list[dict] = []
    member_directives: list[dict] = []
    archive_cache: dict[str, bytes] = {}
    current: tuple[Path, Path, dict] | None = None
    for event in structure["events"]:
        index = event["line"]
        if event["kind"] == "processed":
            name = event["value"].casefold()
            name = name if name.endswith(".lib") else name + ".lib"
            require(name in discovered,
                    f"terminal LINK processed an unjustified /DEFAULTLIB: {name}")
            if name not in processed:
                processed.append(name)
            continue
        if event["kind"] == "search":
            current = resolved_record(event["value"])
            logical, _physical, record = current
            implicit = record["role"] == "implicit_msvc_directive_library"
            require(not implicit or logical.name.casefold() in processed,
                    f"terminal LINK searched an unprocessed implicit library: {logical}")
            searched.append({
                "line": index, "path": str(logical),
                "role": record["role"], "sha256": record["sha256"],
            })
            continue
        require(current is not None,
                "terminal LINK loaded a member without a current search path")
        logical, physical, record = current
        require(PurePosixPath(event["library"].replace("\\", "/")).name.casefold()
                == logical.name.casefold(),
                "terminal LINK loaded member library differs from its search path")
        key = str(physical)
        if key not in archive_cache:
            archive_cache[key] = authority.read_bytes(
                physical, max_bytes=1 << 30
            )
            require(sha256_bytes(archive_cache[key]) == record["sha256"],
                    f"terminal loaded archive changed: {logical}")
        raw, canonical_member = _archive_directive_for_loaded_member(
            data=archive_cache[key], member=event["member"],
            role=record["role"], identity=record.get("identity"),
            context=f"terminal loaded archive {logical}",
        )
        loaded.append({
            "line": index, "path": str(logical),
            "member": canonical_member,
            "member_sha256": next(
                sha256_bytes(payload)
                for name, payload in parse_coff_archive_members(
                    archive_cache[key], f"terminal loaded archive {logical}"
                )
                if PurePosixPath(name).name.casefold()
                == PurePosixPath(canonical_member).name.casefold()
            ),
        })
        if raw is not None:
            defaults = _directive_defaultlibs(
                raw, f"terminal loaded archive {logical} member {canonical_member}"
            )
            discovered.update(defaults)
            member_directives.append({
                "path": str(logical), "member": canonical_member,
                "raw_hex": raw.hex(), "defaultlibs": defaults,
            })

    flat = []
    for item in structure["flat"]:
        logical, _physical, record = resolved_record(item["value"])
        require(record["role"] != "implicit_msvc_directive_library"
                or logical.name.casefold() in processed,
                f"terminal flat list contains an unjustified library: {logical}")
        flat.append(str(logical))
    require(flat and len(flat) == len(set(value.casefold() for value in flat)),
            "terminal /VERBOSE:LIB flat search list is empty or duplicated")
    searched_unique = list(dict.fromkeys(item["path"].casefold() for item in searched))
    require(set(searched_unique) == {value.casefold() for value in flat}
            and set(explicit_keys) <= set(searched_unique),
            "terminal /VERBOSE:LIB detailed/flat/explicit library closure differs")
    require(loaded and set(processed) <= discovered,
            "terminal /VERBOSE:LIB member/defaultlib closure is incomplete")
    implicit = [
        value for value in flat if value.casefold() not in explicit_keys
    ]
    return {
        "schema": "vc42_verbose_library_closure_v1",
        "processed_defaultlibs": processed,
        "direct_defaultlibs": sorted(direct_defaults),
        "discovered_defaultlibs": sorted(discovered),
        "searched": searched,
        "flat_paths": flat,
        "loaded_members": loaded,
        "member_directives": member_directives,
        "implicit_libraries": implicit,
    }


def derive_analysis_link_argv(
    release: list[str], cwd: Path, build_dir: Path,
) -> list[str]:
    replacements = {
        "out": final_analysis_image_path(build_dir, "LEGO1"),
        "implib": final_analysis_implib_path(build_dir, "LEGO1"),
        "pdb": final_pdb_path(build_dir, "LEGO1"),
        "map": final_analysis_map_path(build_dir, "LEGO1"),
    }
    result = []
    seen = set()
    for token in release:
        replacement = None
        for name, path in replacements.items():
            if token.casefold().startswith((f"/{name}:", f"-{name}:")):
                replacement = f"/{name.upper()}:{path}"
                seen.add(name)
                break
        result.append(replacement if replacement is not None else token)
    require(seen == set(replacements), "release link output grammar is incomplete")
    result.insert(1, "/DEBUG")
    return result


def require_run_output_membership(run: dict, context: str) -> None:
    expected: dict[Path, dict[str, str]] = defaultdict(dict)
    for path in run["outputs"]:
        expected[path.parent][path.name] = "file"
    for parent, members in expected.items():
        require(run["holder"].membership(parent) == members,
                f"{context} emitted an undeclared output in {parent}")


def command_link_launch_locked(arguments: argparse.Namespace) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    require(arguments.target == "lego1" and arguments.identity == "LEGO1",
            "terminal link launcher supports only lego1/LEGO1")
    invalidate_terminal_outputs(arguments.build_dir)
    child = producer_child(arguments)
    cwd = lexical_absolute_path(Path.cwd())
    state, inventory, command_inventory, session = load_producer_state(arguments)
    parsed = parse_link_command(child, cwd, state)
    link_wrapper = terminal_link_tool(state, "link_wrapper")
    link_binary = terminal_link_tool(state, "link_binary")
    require(Path(child[0]).resolve(strict=True)
            == Path(link_wrapper["absolute_path"]),
            "terminal command does not begin with the pinned LINK wrapper")

    ordered_inputs = terminal_link_ordered_inputs(
        state, inventory, session, parsed
    )

    generated_inputs = list(dict.fromkeys([
        *parsed["response_paths"], *parsed["direct"], *parsed["libraries"],
        parsed["definition"],
    ]))
    release_outputs = [
        parsed["image"], parsed["implib"], final_exp_path(arguments.build_dir, "LEGO1"),
        parsed["map"],
    ]
    analysis_outputs = [
        final_analysis_image_path(arguments.build_dir, "LEGO1"),
        final_analysis_implib_path(arguments.build_dir, "LEGO1"),
        final_analysis_exp_path(arguments.build_dir, "LEGO1"),
        final_pdb_path(arguments.build_dir, "LEGO1"),
        final_analysis_map_path(arguments.build_dir, "LEGO1"),
    ]
    temporary_root = authority.build_root / "byte-identity/work/final-link"
    authority.remove_tree(temporary_root)
    release_tmp = temporary_root / "release/tmp"
    analysis_tmp = temporary_root / "analysis/tmp"
    authority.mkdirs(release_tmp)
    authority.mkdirs(analysis_tmp)
    analysis_argv = derive_analysis_link_argv(child, cwd, arguments.build_dir)
    audit_path = final_link_audit_path(arguments.build_dir, "LEGO1")
    installed_paths = [
        *release_outputs, *analysis_outputs,
        final_link_log_path(arguments.build_dir, "LEGO1"),
        final_analysis_link_log_path(arguments.build_dir, "LEGO1"), audit_path,
    ]
    started = time.monotonic()
    release_run = None
    analysis_run = None
    try:
        release_run = prepare_virtual_z_run(
            state=state, build_dir=arguments.build_dir, target="lego1",
            source_relative="terminal/LEGO1-release", role="release-link",
            cwd=cwd, logical_outputs=release_outputs, temporary=release_tmp,
            generated_inputs=generated_inputs,
        )
    except BaseException:
        cleanup_virtual_z_runs_aggregate([release_run, analysis_run])
        raise
    try:
        release_log, _ = execute_virtual_z_producer(
            state=state, run=release_run, argv=child, tool=link_wrapper,
            timeout=state["terminal_producers"]["link"]["max_child_seconds"],
            use_compiler_slot=False, logical_temporary=release_tmp,
        )
        release_data = [
            release_run["holder"].read_bytes(path)
            for path in release_run["outputs"]
        ]
        require_run_output_membership(release_run, "release LINK")
        require(not release_run["holder"].membership(release_run["temporary"]),
                "release LINK temporary namespace is not empty")
        cleanup_virtual_z_run(release_run)

        analysis_run = prepare_virtual_z_run(
            state=state, build_dir=arguments.build_dir, target="lego1",
            source_relative="terminal/LEGO1-analysis", role="analysis-link",
            cwd=cwd, logical_outputs=analysis_outputs, temporary=analysis_tmp,
            generated_inputs=generated_inputs,
        )
        analysis_log, _ = execute_virtual_z_producer(
            state=state, run=analysis_run, argv=analysis_argv, tool=link_wrapper,
            timeout=state["terminal_producers"]["link"]["max_child_seconds"],
            use_compiler_slot=False, logical_temporary=analysis_tmp,
        )
        analysis_data = [
            analysis_run["holder"].read_bytes(path)
            for path in analysis_run["outputs"]
        ]
        require_run_output_membership(analysis_run, "diagnostic LINK")
        require(not analysis_run["holder"].membership(analysis_run["temporary"]),
                "diagnostic LINK temporary namespace is not empty")
        cleanup_virtual_z_run(analysis_run)
        release_text = pe_text_record(release_data[0])
        analysis_text = pe_text_record(analysis_data[0])
        require(release_text["rva"] == analysis_text["rva"]
                and release_text["va"] == analysis_text["va"]
                and release_text["size"] == analysis_text["size"]
                and release_text["body"] == analysis_text["body"],
                "release and diagnostic LINK .text spans differ")
        verified_map, verified_members = validate_link_evidence(
            release_data[3], release_log,
            state["terminal_producers"]["link"],
        )
        release_resolution = validate_verbose_library_resolution_closure(
            release_log, parsed["libraries"], state, ordered_inputs, cwd
        )
        analysis_resolution = validate_verbose_library_resolution_closure(
            analysis_log, parsed["libraries"], state, ordered_inputs, cwd
        )
        projection_identity = execution_projection_audit_identity(release_run)
        require(
            exact_json_equal(
                projection_identity,
                execution_projection_audit_identity(analysis_run),
            ),
            "release and diagnostic LINK used different execution projections",
        )
        require(
            exact_json_equal(
                release_run["producer_support"],
                analysis_run["producer_support"],
            ),
            "release and diagnostic LINK used different support closures",
        )
        values = {
            "image": (release_outputs[0], release_data[0]),
            "import_library": (release_outputs[1], release_data[1]),
            "export_file": (release_outputs[2], release_data[2]),
            "map": (release_outputs[3], release_data[3]),
            "analysis_image": (analysis_outputs[0], analysis_data[0]),
            "analysis_import_library": (analysis_outputs[1], analysis_data[1]),
            "analysis_export_file": (analysis_outputs[2], analysis_data[2]),
            "pdb": (analysis_outputs[3], analysis_data[3]),
            "analysis_map": (analysis_outputs[4], analysis_data[4]),
            "verbose_log": (
                final_link_log_path(arguments.build_dir, "LEGO1"), release_log
            ),
            "analysis_verbose_log": (
                final_analysis_link_log_path(arguments.build_dir, "LEGO1"),
                analysis_log,
            ),
        }
        audit = {
            "schema": 1,
            "status": "AUTHENTICATED_DUAL_LINK_PRODUCED",
            "manifest_sha256": state["manifest_sha256"],
            "outer_session_nonce": session["nonce"],
            "target": "lego1", "identity": "LEGO1",
            "tool": link_wrapper["absolute_path"],
            "tool_sha256": link_wrapper["sha256"],
            "link_binary": link_binary["absolute_path"],
            "link_binary_sha256": link_binary["sha256"],
            "generated_argv": child,
            "generated_argv_sha256": stable_argv_sha256(child),
            "expanded_argv": parsed["expanded"],
            "expanded_argv_sha256": stable_argv_sha256(parsed["expanded"]),
            "release_executed_argv": release_run["executed_argv"],
            "release_executed_argv_sha256": stable_argv_sha256(
                release_run["executed_argv"]
            ),
            "analysis_executed_argv": analysis_run["executed_argv"],
            "analysis_executed_argv_sha256": stable_argv_sha256(
                analysis_run["executed_argv"]
            ),
            "cwd": str(cwd),
            "response_files": parsed["response_files"],
            "ordered_inputs": ordered_inputs,
            "text_rva": release_text["rva"],
            "text_size": release_text["size"],
            "text_sha256": release_text["sha256"],
            "map_evidence": verified_map,
            "member_evidence": verified_members,
            "library_resolution": release_resolution,
            "analysis_library_resolution": analysis_resolution,
            "toolchain_snapshot_sha256": release_run["toolchain_snapshot_sha256"],
            "command_snapshot_sha256": release_run["command_snapshot_sha256"],
            "producer_support": release_run["producer_support"],
            **projection_identity,
            "command_inventory_sha256": state["command_inventory_sha256"],
            "inventory_sha256": state["inventory_sha256"],
            "elapsed_seconds": float(time.monotonic() - started),
        }
        for name, (path, data) in values.items():
            audit[name] = str(path)
            audit[f"{name}_sha256"] = sha256_bytes(data)
            audit[f"{name}_size"] = len(data)
        exact_audit_keys(audit, FINAL_LINK_AUDIT_KEYS, "terminal link audit")
        # Publish artifacts only from bytes consumed through held run-private
        # descriptors, after both private namespaces are gone. Audit is last;
        # any exception removes the whole chain.
        for path, data in values.values():
            atomic_write(path, data)
        atomic_json(audit_path, audit)
        sys.stdout.buffer.write(release_log)
        sys.stdout.buffer.flush()
    except BaseException:
        invalidate_build_paths(installed_paths)
        raise
    finally:
        cleanup_virtual_z_runs_aggregate([release_run, analysis_run])
    print(json.dumps({"terminal_link": audit}, sort_keys=True))
    return 0


def command_link_launch(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_link_launch_locked(arguments)


def validate_producer_response_records(records: object) -> list[dict]:
    require(isinstance(records, list), "producer response_files is not an array")
    authority = active_build_authority()
    result = []
    for index, item in enumerate(records):
        context = f"producer response_files[{index}]"
        require(isinstance(item, dict), f"{context} is not an object")
        exact_audit_keys(item, {"path", "sha256", "size", "tokens"}, context)
        path = Path(item.get("path", ""))
        authority.parts(path)
        data = authority.read_bytes(path, max_bytes=64 * 1024 * 1024)
        require(sha256_bytes(data) == item.get("sha256")
                and len(data) == item.get("size"),
                f"{context} bytes changed")
        text = decode_response_file(data, context)
        try:
            tokens = shlex.split(text, comments=False, posix=True)
        except ValueError as error:
            raise ByteIdentityError(f"{context} quoting changed: {error}") from error
        require(exact_json_equal(tokens, item.get("tokens")),
                f"{context} tokenization changed")
        result.append(item)
    return result


def validate_virtual_z_executed_argv(
    state: dict, generated: object, executed: object,
    original_tool: Path, context: str,
) -> list[str]:
    """Bind an audit invocation to the held transaction projection tool copy.

    The projection is deliberately deleted before an audit can be consumed,
    so validation proves its unpredictable lexical seat, exact tool suffix,
    complete forwarded argv, and continued absence.  The copied tool bytes are
    independently pinned by the retained toolchain snapshot hash.
    """
    require(isinstance(generated, list) and isinstance(executed, list)
            and generated and len(executed) >= 2,
            f"{context} argv is empty or malformed")
    require(exact_json_equal(executed[2:], generated[1:]),
            f"{context} forwarded argv differs")
    authority = active_build_authority()
    executed_bash = Path(executed[0])
    expected_bash = held_runtime_executable_path(
        state, Path(state["build_dir"]), "bash"
    )
    require(authority.parts(executed_bash) == authority.parts(expected_bash),
            f"{context} did not use the held bash runtime")
    executed_tool = Path(executed[1])
    parts = authority.parts(executed_tool)
    require(
        len(parts) >= 5
        and parts[:2] == ("byte-identity", "execution-projections")
        and re.fullmatch(r"session-[0-9a-f]{32}", parts[2]) is not None
        and parts[3] == "z",
        f"{context} tool is outside a transaction execution projection",
    )
    z_index = 3
    expected_suffix = tuple(lexical_absolute_path(original_tool).parts[1:])
    require(parts[z_index + 1:] == expected_suffix,
            f"{context} tool does not use the pinned snapshot seat")
    authority.pin_build_absence(executed_tool)
    return executed


def validate_producer_snapshot_hashes(state: dict, audit: dict, context: str) -> None:
    build_dir = Path(state["build_dir"])
    expected_toolchain = sha256_file(
        toolchain_snapshot_path(build_dir) / "snapshot.json"
    )
    expected_command = sha256_file(
        command_snapshot_path(build_dir) / "snapshot.json"
    )
    require(audit.get("toolchain_snapshot_sha256") == expected_toolchain
            and audit.get("command_snapshot_sha256") == expected_command,
            f"{context} immutable input snapshot hashes differ")


def validate_final_link_audit(
    state: dict, inventory: dict, session: dict,
) -> tuple[dict, bytes]:
    authority = active_build_authority()
    audit_path = final_link_audit_path(Path(state["build_dir"]), "LEGO1")
    audit = read_unique_audit(audit_path, authority.build_root, "terminal link audit")
    exact_audit_keys(audit, FINAL_LINK_AUDIT_KEYS, "terminal link audit")
    validate_producer_support_audit(
        state, "link", audit.get("producer_support"),
        "terminal LINK producer support",
    )
    link_wrapper = terminal_link_tool(state, "link_wrapper")
    link_binary = terminal_link_tool(state, "link_binary")
    require(type(audit.get("schema")) is int and audit.get("schema") == 1
            and audit.get("status") == "AUTHENTICATED_DUAL_LINK_PRODUCED"
            and audit.get("manifest_sha256") == state["manifest_sha256"]
            and audit.get("outer_session_nonce") == session["nonce"]
            and audit.get("target") == "lego1"
            and audit.get("identity") == "LEGO1"
            and audit.get("tool") == link_wrapper["absolute_path"]
            and audit.get("tool_sha256") == link_wrapper["sha256"]
            and audit.get("link_binary") == link_binary["absolute_path"]
            and audit.get("link_binary_sha256") == link_binary["sha256"]
            and audit.get("inventory_sha256") == state["inventory_sha256"]
            and audit.get("command_inventory_sha256")
            == state["command_inventory_sha256"],
            "terminal link audit producer/session policy differs")
    cwd = Path(audit.get("cwd", ""))
    require(authority.parts(cwd, allow_root=True) == (),
            "terminal link cwd differs from the fixed build root")
    for name in (
        "generated_argv", "expanded_argv", "release_executed_argv",
        "analysis_executed_argv",
    ):
        argv = audit.get(name)
        require(isinstance(argv, list)
                and stable_argv_sha256(argv) == audit.get(f"{name}_sha256"),
                f"terminal link {name} hash differs")
    generated = audit["generated_argv"]
    require(not raw_argument_token_errors(generated)
            and Path(generated[0]).resolve(strict=True)
            == Path(link_wrapper["absolute_path"]),
            "terminal link generated command does not use the pinned wrapper")
    parsed = parse_link_command(generated, cwd, state)
    require(exact_json_equal(parsed["expanded"], audit.get("expanded_argv"))
            and exact_json_equal(parsed["response_files"],
                                 audit.get("response_files")),
            "terminal link generated/expanded response grammar differs")
    validate_producer_response_records(audit.get("response_files"))
    analysis_generated = derive_analysis_link_argv(
        generated, cwd, Path(state["build_dir"])
    )
    validate_virtual_z_executed_argv(
        state, generated, audit["release_executed_argv"],
        Path(link_wrapper["absolute_path"]), "terminal release LINK",
    )
    validate_virtual_z_executed_argv(
        state, analysis_generated, audit["analysis_executed_argv"],
        Path(link_wrapper["absolute_path"]), "terminal diagnostic LINK",
    )
    validate_execution_projection_evidence(
        audit.get("execution_projection_root"),
        audit.get("execution_projection_descriptor_sha256"),
        Path(state["build_dir"]), "terminal dual LINK",
    )
    validate_producer_snapshot_hashes(state, audit, "terminal LINK")
    expected_inputs = terminal_link_ordered_inputs(
        state, inventory, session, parsed
    )
    require(exact_json_equal(expected_inputs, audit.get("ordered_inputs")),
            "terminal link ordered input provenance differs")
    artifact_names = (
        "image", "analysis_image", "pdb", "map", "analysis_map",
        "import_library", "export_file", "analysis_import_library",
        "analysis_export_file", "verbose_log", "analysis_verbose_log",
    )
    artifact_data = {}
    for name in artifact_names:
        path = Path(audit.get(name, ""))
        authority.parts(path)
        data = authority.read_bytes(path, max_bytes=1 << 30)
        require(sha256_bytes(data) == audit.get(f"{name}_sha256")
                and len(data) == audit.get(f"{name}_size"),
                f"terminal link artifact changed: {name}")
        artifact_data[name] = data
    expected_paths = {
        "image": final_image_path(Path(state["build_dir"]), "LEGO1"),
        "analysis_image": final_analysis_image_path(Path(state["build_dir"]), "LEGO1"),
        "pdb": final_pdb_path(Path(state["build_dir"]), "LEGO1"),
        "map": final_map_path(Path(state["build_dir"]), "LEGO1"),
        "analysis_map": final_analysis_map_path(Path(state["build_dir"]), "LEGO1"),
        "import_library": final_implib_path(Path(state["build_dir"]), "LEGO1"),
        "export_file": final_exp_path(Path(state["build_dir"]), "LEGO1"),
        "analysis_import_library": final_analysis_implib_path(
            Path(state["build_dir"]), "LEGO1"
        ),
        "analysis_export_file": final_analysis_exp_path(
            Path(state["build_dir"]), "LEGO1"
        ),
        "verbose_log": final_link_log_path(Path(state["build_dir"]), "LEGO1"),
        "analysis_verbose_log": final_analysis_link_log_path(
            Path(state["build_dir"]), "LEGO1"
        ),
    }
    require(all(authority.parts(Path(audit[name])) == authority.parts(path)
                for name, path in expected_paths.items()),
            "terminal link artifact paths differ from fixed seats")
    release_text = pe_text_record(artifact_data["image"])
    analysis_text = pe_text_record(artifact_data["analysis_image"])
    require(release_text["rva"] == analysis_text["rva"]
            and release_text["va"] == analysis_text["va"]
            and release_text["body"] == analysis_text["body"]
            and release_text["rva"] == audit.get("text_rva")
            and release_text["size"] == audit.get("text_size")
            and release_text["sha256"] == audit.get("text_sha256"),
            "terminal release/diagnostic .text attestation differs")
    verified_map, verified_members = validate_link_evidence(
        artifact_data["map"], artifact_data["verbose_log"],
        state["terminal_producers"]["link"],
    )
    require(exact_json_equal(verified_map, audit.get("map_evidence"))
            and exact_json_equal(verified_members, audit.get("member_evidence")),
            "terminal map/member-pull evidence differs")
    release_resolution = validate_verbose_library_resolution_closure(
        artifact_data["verbose_log"], parsed["libraries"], state,
        expected_inputs, cwd,
    )
    analysis_resolution = validate_verbose_library_resolution_closure(
        artifact_data["analysis_verbose_log"], parsed["libraries"], state,
        expected_inputs, cwd,
    )
    require(exact_json_equal(
                release_resolution, audit.get("library_resolution")
            ) and exact_json_equal(
                analysis_resolution, audit.get("analysis_library_resolution")
            ), "terminal /VERBOSE:LIB resolution evidence differs")
    inputs = audit.get("ordered_inputs")
    require(isinstance(inputs, list) and inputs,
            "terminal link ordered_inputs is empty")
    authorized = set()
    strstr = False
    for index, item in enumerate(inputs):
        require(isinstance(item, dict),
                f"terminal link ordered_inputs[{index}] is not an object")
        role = item.get("role")
        require(role in {
            "compiler_object", "resource_output", "first_party_archive",
            "authorized_third_party_archive", "sealed_project_sdk_library",
            "sealed_msvc_library", "linker_definition",
        }, f"terminal link input role is unsupported: {role}")
        expected_keys = {"role", "path", "sha256", "size"}
        if role in ("compiler_object", "resource_output"):
            expected_keys |= {"target", "source", "audit", "audit_sha256"}
        elif role == "first_party_archive":
            expected_keys |= {"target", "audit", "audit_sha256"}
        elif role == "authorized_third_party_archive":
            expected_keys |= {"identity", "audit", "audit_sha256"}
        elif role in {
            "sealed_project_sdk_library", "sealed_msvc_library",
            "linker_definition",
        }:
            expected_keys |= {"snapshot_path"}
        exact_audit_keys(item, expected_keys,
                         f"terminal link ordered_inputs[{index}]")
        current = (
            sealed_producer_input_record(
                Path(item.get("path", "")),
                Path(item.get("snapshot_path", "")), role,
            )
            if "snapshot_path" in item
            else producer_input_record(Path(item.get("path", "")), role)
        )
        require(current["sha256"] == item.get("sha256")
                and current["size"] == item.get("size"),
                f"terminal link input changed: {item.get('path')}")
        if role == "authorized_third_party_archive":
            authorized.add(item.get("identity"))
        if (role == "sealed_msvc_library"
                and Path(item["path"]).name.casefold() == "libcmt.lib"):
            strstr = True
    require(authorized == REQUIRED_THIRD_PARTY_ARCHIVES,
            "terminal audit omits an actually consumed authorized archive")
    require(strstr, "terminal audit omits the unmodified libcmt.lib input")
    require_nonnegative_finite_number(
        audit.get("elapsed_seconds"), "terminal link elapsed_seconds"
    )
    return audit, authority.read_bytes(audit_path)


def terminal_reccmp_closure(state: dict) -> list[dict]:
    """Read the closure exclusively from the held native reccmp snapshot."""
    descriptor = validate_native_reccmp_snapshot(
        state, Path(state["build_dir"])
    )
    result = []
    for item in descriptor["closures"]:
        snapshot = item["tree"]
        result.append({
            "role": item["role"], "path": item["logical_path"],
            "snapshot_path": item["snapshot_path"],
            "entry_count": snapshot["entry_count"],
            "max_depth": snapshot["max_depth"],
            "membership_sha256": snapshot["membership_sha256"],
            "content_sha256": snapshot["content_sha256"],
        })
    return result


def _native_reccmp_tree_copy(
    source: Path, destination: Path, expected_pin: dict,
    expected_records: list[dict], context: str,
) -> dict:
    """Clone one held tree with exact per-file source/copy proof.

    The full source tree was hashed when the resident materialized the held
    descriptor. Re-enumerate its exact membership and hash each file exactly
    as it is copied, avoiding another whole-tree pre-scan.
    """
    authority = active_build_authority()
    require(isinstance(expected_records, list) and expected_records,
            f"{context} held records are absent")
    by_parent: dict[tuple[str, ...], dict[str, str]] = defaultdict(dict)
    directories = []
    files = []
    for record in expected_records:
        relative = record.get("path")
        kind = record.get("type")
        require(isinstance(relative, str)
                and kind in {"directory", "file"},
                f"{context} held record is invalid")
        parts = () if relative == "." else PurePosixPath(relative).parts
        if parts:
            require(parts[-1] not in by_parent[parts[:-1]],
                    f"{context} held record is duplicated")
            by_parent[parts[:-1]][parts[-1]] = kind
        (directories if kind == "directory" else files).append((parts, record))
    require(any(not parts for parts, _ in directories),
            f"{context} held root record is absent")

    source_identities = {}
    for parts, record in sorted(directories, key=lambda item: len(item[0])):
        directory = source.joinpath(*parts)
        metadata = authority.lstat(directory)
        observed_members = {}
        for name in authority.list_names(directory):
            child_metadata = authority.lstat(directory / name)
            require(child_metadata is not None,
                    f"{context} held source member disappeared: "
                    f"{directory / name}")
            observed_members[name] = (
                "directory" if stat.S_ISDIR(child_metadata.st_mode)
                else "file" if stat.S_ISREG(child_metadata.st_mode)
                else "unsupported"
            )
        require(metadata is not None and stat.S_ISDIR(metadata.st_mode)
                and stat.S_IMODE(metadata.st_mode) == record["mode"]
                and observed_members == by_parent.get(parts, {}),
                f"{context} held source membership differs: {directory}")
        source_identities[parts] = (
            metadata.st_dev, metadata.st_ino, metadata.st_mtime_ns
        )
    authority.mkdirs(destination)
    for parts, record in sorted(directories, key=lambda item: len(item[0])):
        if parts:
            authority.mkdirs(destination.joinpath(*parts))
    for parts, record in files:
        logical = source.joinpath(*parts)
        metadata = authority.lstat(logical)
        data = authority.read_bytes(logical, max_bytes=1 << 30)
        require(metadata is not None and stat.S_ISREG(metadata.st_mode)
                and stat.S_IMODE(metadata.st_mode) == record["mode"]
                and len(data) == record["size"]
                and sha256_bytes(data) == record["sha256"],
                f"{context} held source file differs: {logical}")
        target = destination.joinpath(*parts)
        authority.atomic_write(target, data, mode=record["mode"])
        copied_metadata = authority.lstat(target)
        require(copied_metadata is not None
                and (metadata.st_dev, metadata.st_ino)
                != (copied_metadata.st_dev, copied_metadata.st_ino),
                f"{context} private file was not independently copied: {target}")
    for parts, record in sorted(
        directories, key=lambda item: len(item[0]), reverse=True
    ):
        authority.chmod_directory(
            destination.joinpath(*parts), record["mode"]
        )
    for parts, identity in source_identities.items():
        metadata = authority.lstat(source.joinpath(*parts))
        require(metadata is not None
                and (metadata.st_dev, metadata.st_ino, metadata.st_mtime_ns)
                == identity,
                f"{context} held source directory changed while copied")
    expected_destination = new_snapshot_destination_expectation(destination)
    add_expected_snapshot_tree(
        expected_destination, destination, expected_records,
        directory_policy="exact",
    )
    copied = validate_expected_snapshot_destination(
        expected_destination, f"{context} private tree copy",
        max_entries=expected_pin["entry_count"],
        max_depth=expected_pin["max_depth"],
    )
    require(copied["entry_count"] == expected_pin["entry_count"]
            and copied["max_depth"] == expected_pin["max_depth"],
            f"{context} private tree copy bounds differ")
    return _tree_pin(copied)


def _prepare_native_reccmp_wine_transport(
    run_root: Path, wine_bin: Path, prefix: Path,
    state: dict, build_dir: Path,
) -> dict:
    """Create the exact private Wine projection used only by cvdump."""
    authority = active_build_authority()
    shared_runtime_bin = validate_runtime_bin(state, build_dir)
    required = ("wine", "winepath", "wineserver")
    available = {item["name"] for item in state["runtime_executables"]}
    require(set(required) <= available,
            "native reccmp cvdump Wine runtime is incomplete")
    for name in required:
        source = shared_runtime_bin / name
        metadata = authority.lstat(source)
        require(metadata is not None and stat.S_ISLNK(metadata.st_mode),
                f"held cvdump Wine runtime entry is not a link: {name}")
        target = Path(authority.readlink(source))
        # The strict runtime executes the pinned host bundle in place, so the
        # link target legitimately lives outside the build root; its identity
        # is the per-entry hash pin re-verified by validate_runtime_bin.
        try:
            target_metadata = target.stat(follow_symlinks=False)
        except OSError:
            target_metadata = None
        require(target.is_absolute() and target_metadata is not None
                and stat.S_ISREG(target_metadata.st_mode),
                f"held cvdump Wine runtime target is absent: {name}")
        authority.atomic_symlink(wine_bin / name, target)

    template = toolchain_snapshot_path(build_dir) / "prefix-template"
    for item in state["transport"]["prefix_template_files"]:
        data = authority.read_bytes(template / item["name"])
        require(sha256_bytes(data) == item["sha256"],
                f"sealed cvdump Wine prefix template differs: {item['name']}")
        if item["name"] == ".update-timestamp":
            # wineboot owns the stamp: omitting it triggers the one-shot
            # placeholder-creating update at prefix initialization.
            continue
        # wineserver rewrites the registry with 0644 on every shutdown;
        # seeding with the same mode keeps the prefix identity stable.
        authority.atomic_write(prefix / item["name"], data, mode=0o644)
    for relative in state["transport"]["prefix_directories"]:
        authority.mkdirs(prefix.joinpath(*PurePosixPath(relative).parts))
    dosdevices = prefix / "dosdevices"
    authority.mkdirs(dosdevices)
    authority.atomic_symlink(dosdevices / "c:", Path("../drive_c"))
    z_target = Path(os.path.relpath(run_root, dosdevices))
    require(not z_target.is_absolute(),
            "native reccmp private Wine Z mapping is not relative")
    authority.atomic_symlink(dosdevices / "z:", z_target)
    require_exact_build_namespace(
        authority, dosdevices, {"c:": "symlink", "z:": "symlink"},
        "native reccmp private Wine drive namespace",
    )
    initialize_wine_prefix_with_wineboot(
        state, build_dir, prefix, run_root / "home"
    )
    authority.chmod_directory(wine_bin, 0o500)
    authority.chmod_directory(dosdevices, 0o500)
    require_exact_build_namespace(
        authority, wine_bin, {name: "symlink" for name in required},
        "native reccmp private Wine runtime namespace",
    )
    prefix_snapshot = snapshot_run_prefix(prefix, run_root)
    prefix_metadata = authority.lstat(prefix)
    require(prefix_metadata is not None and stat.S_ISDIR(prefix_metadata.st_mode),
            "native reccmp private Wine prefix identity is absent")
    runtime_targets = {
        name: str(Path(authority.readlink(wine_bin / name)))
        for name in required
    }
    return {
        "schema": "run_private_cvdump_wine_v1",
        "bin": wine_bin,
        "prefix": prefix,
        "dosdevices": dosdevices,
        "runtime_targets": runtime_targets,
        "runtime_snapshot": toolchain_snapshot_path(build_dir) / "host",
        "toolchain_snapshot_sha256": sha256_file(
            toolchain_snapshot_path(build_dir) / "snapshot.json"
        ),
        "prefix_snapshot": prefix_snapshot,
        "prefix_metadata": shared_prefix_metadata_identity(prefix),
        "server_preflight_clear": False,
        "server_postflight_clear": False,
        "server_seat_path": str(expected_wine_server_seat(prefix)),
        "server_seat_prefix_identity": {
            "device": f"{prefix_metadata.st_dev:x}",
            "inode": f"{prefix_metadata.st_ino:x}",
        },
        "server_seat_preflight": None,
        "server_seat_postflight": None,
    }


def rollback_exact_private_run(
    authority: BuildRootAuthority, run_root: Path,
) -> None:
    """Close held descendants and remove only one admitted nonce root."""
    root_parts = authority.parts(run_root)
    for holder in authority.compiler_holders:
        if any(parts[:len(root_parts)] == root_parts
               for parts in holder.directories):
            holder.close()
    authority.remove_tree(run_root)
    authority.assert_absent(run_root)


def rollback_exact_private_roots(
    authority: BuildRootAuthority, roots: list[Path], context: str,
) -> None:
    """Attempt every exact-root rollback before reporting any failure."""
    failures = []
    for root in roots:
        try:
            rollback_exact_private_run(authority, root)
        except BaseException as error:
            failures.append(f"{root}: {error}")
    require(not failures, f"{context}: " + "; ".join(failures))


def _prepare_native_reccmp_run_at_root(
    *, state: dict, build_dir: Path, executable: Path,
    source_snapshot: Path, source_pin: dict,
    generated_inputs: list[tuple[str, Path, bytes]], run_root: Path,
) -> dict:
    """Populate one already-created held host-native reccmp namespace.

    Python and reccmp are native and independently copied.  Their internal
    cvdump invocation receives only a narrow, authenticated private Wine
    runtime/prefix projection rooted in this same unpredictable namespace.
    """
    authority = active_build_authority()
    runtime = run_root / "runtime"
    tool = run_root / "tool"
    closures = run_root / "closures"
    pythonpath = run_root / "pythonpath"
    source = run_root / "source"
    inputs = run_root / "inputs"
    output = run_root / "output"
    temporary = run_root / "tmp"
    home = run_root / "home"
    wine_bin = run_root / "wine-bin"
    wine_prefix = run_root / "wine-prefix"
    for directory in (
        tool, closures, pythonpath, inputs, output, temporary, home,
        wine_bin, wine_prefix,
    ):
        authority.mkdirs(directory)
    expected_tool = new_snapshot_destination_expectation(tool)
    expected_inputs = new_snapshot_destination_expectation(inputs)

    descriptor = validate_native_reccmp_snapshot(state, build_dir)
    sealed_root = native_reccmp_snapshot_path(build_dir)
    sealed_runtime = sealed_root / "runtime"
    runtime_descriptor = descriptor["runtime"]
    runtime_pin = runtime_descriptor["tree"]
    copied_runtime = _native_reccmp_tree_copy(
        sealed_runtime, runtime, runtime_pin, runtime_descriptor["records"],
        "private reccmp runtime",
    )
    expected_runtime = new_snapshot_destination_expectation(runtime)
    add_expected_snapshot_tree(
        expected_runtime, runtime, runtime_descriptor["records"],
        directory_policy="exact",
    )

    require(str(executable)
            == state["terminal_producers"]["reccmp"]["executable_path"],
            "native reccmp logical executable differs")
    sealed_executable = sealed_root / "tool/reccmp.py"
    executable_data = authority.read_bytes(sealed_executable)
    require(sha256_bytes(executable_data)
            == state["terminal_producers"]["reccmp"]["executable_sha256"],
            "sealed reccmp executable changed before native copy")
    private_executable = tool / "reccmp.py"
    authority.atomic_write(private_executable, executable_data, mode=0o400)
    add_expected_snapshot_file(expected_tool, private_executable, {
        "mode": 0o400, "size": len(executable_data),
        "sha256": sha256_bytes(executable_data),
    })
    sealed_source_interpreter = sealed_root / "interpreter/pinned-interpreter"
    source_interpreter_data = authority.read_bytes(sealed_source_interpreter)
    require(sha256_bytes(source_interpreter_data)
            == state["terminal_producers"]["reccmp"]["interpreter_sha256"],
            "sealed native reccmp source interpreter changed before copy")
    private_source_interpreter = tool / "pinned-interpreter"
    authority.atomic_write(
        private_source_interpreter, source_interpreter_data, mode=0o400
    )
    add_expected_snapshot_file(expected_tool, private_source_interpreter, {
        "mode": 0o400, "size": len(source_interpreter_data),
        "sha256": sha256_bytes(source_interpreter_data),
    })

    closure_records = []
    closure_paths = []
    closure_expectations = []
    for item in descriptor["closures"]:
        role = item["role"]
        require(role in {"reccmp_source", "reccmp_environment"},
                f"private reccmp closure role is invalid: {role}")
        destination = (
            pythonpath / "reccmp"
            if role == "reccmp_source"
            else closures / "reccmp_environment"
        )
        copied = _native_reccmp_tree_copy(
            Path(item["snapshot_path"]), destination, item["tree"],
            item["records"],
            f"private reccmp closure {role}",
        )
        expected_closure = new_snapshot_destination_expectation(destination)
        add_expected_snapshot_tree(
            expected_closure, destination, item["records"],
            directory_policy="exact",
        )
        closure_expectations.append((role, expected_closure))
        closure_records.append({
            "role": role,
            "logical_path": item["logical_path"],
            "private_path": str(destination),
            "tree": copied,
        })
        if role == "reccmp_environment":
            closure_paths.append(destination)

    copied_source = _native_reccmp_tree_copy(
        source_snapshot, source, _tree_pin(source_pin),
        source_pin["records"], "private reccmp source",
    )
    expected_source = new_snapshot_destination_expectation(source)
    add_expected_snapshot_tree(
        expected_source, source, source_pin["records"],
        directory_policy="exact",
    )
    private_inputs = []
    seen_roles = set()
    for role, logical, data in generated_inputs:
        require(TARGET_RE.fullmatch(role) is not None and role not in seen_roles,
                f"private reccmp input role is invalid or duplicated: {role}")
        require(isinstance(data, bytes) and data,
                f"private reccmp input is empty: {role}")
        seen_roles.add(role)
        basename = logical.name
        require(basename not in {"", ".", ".."}
                and PurePosixPath(basename).name == basename,
                f"private reccmp input basename is invalid: {role}")
        role_root = inputs / role
        authority.mkdirs(role_root)
        physical = role_root / basename
        authority.atomic_write(physical, data, mode=0o400)
        add_expected_snapshot_file(expected_inputs, physical, {
            "mode": 0o400, "size": len(data), "sha256": sha256_bytes(data),
        })
        private_inputs.append({
            "role": role,
            "logical": str(logical),
            "physical": str(physical),
            "sha256": sha256_bytes(data),
        })

    report = output / "producer-report.json"
    # Generic sealing is suitable here: every copied leaf is already an
    # independent readonly regular file, and only these three exact host seats
    # are writable by the native child.
    seal_virtual_z_directories(
        run_root, [output, temporary, home, wine_bin, wine_prefix]
    )
    for expectation in (
        expected_runtime, expected_tool, expected_source, expected_inputs,
        *(item[1] for item in closure_expectations),
    ):
        set_expected_snapshot_directory_modes(expectation, 0o500)
    wine_transport = _prepare_native_reccmp_wine_transport(
        run_root, wine_bin, wine_prefix, state, build_dir
    )
    runtime_snapshot = validate_expected_snapshot_destination(
        expected_runtime, "private reccmp run runtime", max_entries=30000
    )
    copied_runtime = _tree_pin(runtime_snapshot)
    tool_snapshot = validate_expected_snapshot_destination(
        expected_tool, "private reccmp run tools"
    )
    source_snapshot_observed = validate_expected_snapshot_destination(
        expected_source, "private reccmp run source", max_entries=30000
    )
    copied_source = _tree_pin(source_snapshot_observed)
    inputs_snapshot = validate_expected_snapshot_destination(
        expected_inputs, "private reccmp run generated inputs"
    )
    expectations_by_role = dict(closure_expectations)
    closure_snapshots = {}
    for record in closure_records:
        closure_snapshot = validate_expected_snapshot_destination(
            expectations_by_role[record["role"]],
            f"private reccmp run closure {record['role']}",
            max_entries=30000,
        )
        closure_snapshots[record["role"]] = closure_snapshot
        record["tree"] = _tree_pin(closure_snapshot)
    require_exact_build_namespace(
        authority, pythonpath, {"reccmp": "directory"},
        "private reccmp PYTHONPATH namespace",
    )
    require_exact_build_namespace(
        authority, closures,
        {
            Path(record["private_path"]).name: "directory"
            for record in closure_records
            if Path(record["private_path"]).parent == closures
        },
        "private reccmp environment-closure namespace",
    )
    require_exact_build_namespace(
        authority, tool,
        {"reccmp.py": "file", "pinned-interpreter": "file"},
        "private reccmp tool namespace",
    )
    require_exact_build_namespace(
        authority, inputs,
        {item["role"]: "directory" for item in private_inputs},
        "private reccmp generated-input namespace",
    )
    holder = authority.retain_directories([
        run_root, runtime, tool, closures, pythonpath,
        pythonpath / "reccmp", source, inputs,
        output, temporary, home, wine_bin, wine_prefix,
        wine_transport["dosdevices"], *closure_paths,
    ])
    holder.revalidate()
    return {
        "run": run_root,
        "runtime": runtime,
        "tool": tool,
        "closures": closures,
        "closure_paths": closure_paths,
        "pythonpath": pythonpath,
        "source": source,
        "inputs": private_inputs,
        "output": output,
        "report": report,
        "temporary": temporary,
        "home": home,
        "wine_transport": wine_transport,
        "prefix": wine_prefix,
        "prefix_snapshot": wine_transport["prefix_snapshot"],
        "server_preflight_clear": False,
        "server_postflight_clear": False,
        "cwd": run_root,
        "interpreter": runtime / "bin/python3.12",
        "source_interpreter": private_source_interpreter,
        "executable": private_executable,
        "holder": holder,
        "runtime_tree": copied_runtime,
        "source_tree": copied_source,
        "closure_records": closure_records,
        "_held_snapshots": {
            "runtime": runtime_snapshot,
            "tool": tool_snapshot,
            "source": source_snapshot_observed,
            "inputs": inputs_snapshot,
            **{
                f"closure:{role}": snapshot
                for role, snapshot in closure_snapshots.items()
            },
        },
        "_expected_tool": expected_tool,
        "_expected_inputs": expected_inputs,
    }


def prepare_native_reccmp_run(
    *, state: dict, build_dir: Path, executable: Path,
    source_snapshot: Path, source_pin: dict,
    generated_inputs: list[tuple[str, Path, bytes]],
) -> dict:
    """Create the sole native reccmp seat under this transaction root."""
    require_posix_reccmp_backend(state, "native reccmp preparation")
    authority = active_build_authority()
    projection = materialize_execution_projection(state, build_dir)
    require(
        projection.get("transaction_binding") is not None
        and projection.get("lease") is None
        and projection.get("removed") is False
        and projection.get("poisoned") is False,
        "native reccmp requires the held resident transaction root",
    )
    if projection.get("marker_child_started") is not True:
        update_execution_transaction_marker(
            projection, "child-may-have-started"
        )
        projection["marker_child_started"] = True
    run_root = native_reccmp_transaction_path(
        build_dir, projection["transaction_binding"]["session_nonce"]
    )
    require(run_root == Path(projection["root"]) / "native-reccmp",
            "native reccmp transaction root differs from its projection")
    require(authority.lstat(run_root) is None,
            "native reccmp transaction seat is not empty")
    recovery = {
        "run": run_root,
        "prefix": run_root / "wine-prefix",
        "producer_child_started": False,
        "_wine_drain_attempted": False,
        "transaction_projection": projection,
    }
    projection["native_reccmp_run"] = recovery
    created = False
    try:
        authority.mkdir_exclusive(run_root)
        created = True
        result = _prepare_native_reccmp_run_at_root(
            state=state, build_dir=build_dir, executable=executable,
            source_snapshot=source_snapshot, source_pin=source_pin,
            generated_inputs=generated_inputs, run_root=run_root,
        )
        result["transaction_projection"] = projection
        projection["native_reccmp_run"] = result
        projection["native_reccmp_prefix"] = str(result["prefix"])
        projection["native_reccmp_prefix_server_seat_path"] = (
            result["wine_transport"]["server_seat_path"]
        )
        update_execution_transaction_marker(
            projection, "child-may-have-started"
        )
        return result
    except BaseException:
        if created:
            rollback_exact_private_run(authority, run_root)
        projection["native_reccmp_run"] = None
        raise


def validate_native_reccmp_run_direct_inputs(
    run: dict, *, before_spawn: bool,
) -> None:
    """Recheck the small direct Python/tool operand universe around spawn."""
    authority = active_build_authority()
    validate_expected_snapshot_destination(
        run["_expected_tool"], "private reccmp direct tools"
    )
    validate_expected_snapshot_destination(
        run["_expected_inputs"], "private reccmp direct generated inputs"
    )
    require_exact_build_namespace(
        authority, run["pythonpath"], {"reccmp": "directory"},
        "private reccmp PYTHONPATH namespace",
        replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["tool"],
        {"reccmp.py": "file", "pinned-interpreter": "file"},
        "private reccmp tool namespace",
        replace_pin=True,
    )
    require_exact_build_namespace(
        authority, Path(run["inputs"][0]["physical"]).parents[1],
        {item["role"]: "directory" for item in run["inputs"]},
        "private reccmp generated-input namespace",
        replace_pin=True,
    )
    closures = run["closures"]
    require_exact_build_namespace(
        authority, closures,
        {
            Path(record["private_path"]).name: "directory"
            for record in run["closure_records"]
            if Path(record["private_path"]).parent == closures
        },
        "private reccmp closure parent namespace", replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["wine_transport"]["bin"],
        {
            name: "symlink"
            for name in run["wine_transport"]["runtime_targets"]
        },
        "private reccmp Wine runtime namespace", replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["output"],
        {} if before_spawn else {run["report"].name: "file"},
        "private reccmp output namespace", replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["temporary"], {},
        "private reccmp temporary namespace", replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["home"], {},
        "private reccmp HOME namespace", replace_pin=True,
    )
    require_exact_build_namespace(
        authority, run["run"], {
            "runtime": "directory", "tool": "directory",
            "closures": "directory", "pythonpath": "directory",
            "source": "directory", "inputs": "directory",
            "output": "directory", "tmp": "directory",
            "home": "directory", "wine-bin": "directory",
            "wine-prefix": "directory",
        }, "private reccmp top-level namespace", replace_pin=True,
    )


def native_reccmp_environment(run: dict) -> dict[str, str]:
    wine = run["wine_transport"]
    environment = {
        "PATH": str(wine["bin"]),
        "HOME": str(run["home"]),
        "TEMP": str(run["temporary"]),
        "TMP": str(run["temporary"]),
        "TMPDIR": str(run["temporary"]),
        "LANG": "C",
        "LC_ALL": "C",
        "PYTHONHOME": str(run["runtime"]),
        "PYTHONPATH": os.pathsep.join(map(str, [
            run["pythonpath"], *run["closure_paths"],
        ])),
        "PYTHONNOUSERSITE": "1",
        "PYTHONSAFEPATH": "1",
        "PYTHONDONTWRITEBYTECODE": "1",
        "DYLD_PRINT_LIBRARIES": "1",
        "WINEPREFIX": str(wine["prefix"]),
        "WINEDEBUG": "-all",
    }
    require(set(environment) == {
        "PATH", "HOME", "TEMP", "TMP", "TMPDIR", "LANG", "LC_ALL",
        "PYTHONHOME", "PYTHONPATH", "PYTHONNOUSERSITE",
        "PYTHONDONTWRITEBYTECODE", "PYTHONSAFEPATH", "DYLD_PRINT_LIBRARIES",
        "WINEPREFIX", "WINEDEBUG",
    }, "native reccmp environment key set differs")
    return environment


_DYLD_TRACE_RE = re.compile(rb"^dyld\[[0-9]+\]:\s+(?:<[^>]+>\s+)?(/.*)$")
_SYSTEM_DYLD_PREFIXES = (
    "/usr/lib/", "/System/Library/",
    "/System/Volumes/Preboot/Cryptexes/OS/usr/lib/",
    "/System/Volumes/Preboot/Cryptexes/OS/System/Library/",
)


def split_native_reccmp_loader_trace(
    output: bytes, run: dict,
) -> tuple[bytes, list[dict]]:
    """Separate dyld evidence and reject every ambient non-system image."""
    authority = active_build_authority()
    program = []
    images = []
    private_roots = [
        ("private_runtime", None, run["runtime"]),
        *(
            ("private_closure", record["role"], Path(record["private_path"]))
            for record in run["closure_records"]
        ),
        (
            "private_cvdump_wine_runtime", None,
            run["wine_transport"]["runtime_snapshot"],
        ),
    ]
    for raw_line in output.splitlines(keepends=True):
        line = raw_line.rstrip(b"\r\n")
        if not line.startswith(b"dyld["):
            program.append(raw_line)
            continue
        match = _DYLD_TRACE_RE.fullmatch(line)
        require(match is not None,
                "native reccmp emitted an unparseable dyld trace line")
        try:
            value = match.group(1).decode("utf-8", errors="strict")
        except UnicodeDecodeError as error:
            raise ByteIdentityError(
                "native reccmp dyld image path is not UTF-8"
            ) from error
        path = lexical_absolute_path(Path(value))
        matched_private = False
        for scope, role, root in private_roots:
            try:
                relative = path.relative_to(root)
            except ValueError:
                continue
            require(relative.parts and authority.is_regular_file(path),
                    f"native reccmp loaded image is absent: {path}")
            record = {
                "scope": scope,
                "role": role,
                "path": relative.as_posix(),
                "sha256": sha256_file(path),
            }
            images.append(record)
            matched_private = True
            break
        if matched_private:
            continue
        require(any(str(path).startswith(prefix)
                    for prefix in _SYSTEM_DYLD_PREFIXES),
                f"native reccmp loaded an ambient non-system image: {path}")
        images.append({
            "scope": "system", "role": None,
            "path": str(path), "sha256": None,
        })
    require(images,
            "native reccmp produced no actual dyld loaded-image evidence")
    require(any(item["scope"] == "private_runtime"
                and item["path"] == "lib/Python" for item in images),
            "native reccmp did not load its private Python framework")
    return b"".join(program), images


def cleanup_native_reccmp_run(run: dict) -> None:
    authority = active_build_authority()
    if run.get("_namespace_removed") is True:
        authority.assert_absent(Path(run["run"]))
        return
    require_run_private_wine_quiescent(run)
    holder = run.get("holder")
    if isinstance(holder, HeldBuildDirectories):
        holder.close()
    root = run.get("run")
    require(isinstance(root, Path), "native reccmp run has no cleanup identity")
    authority.remove_tree(root)
    authority.assert_absent(root)
    run["_namespace_removed"] = True
    projection = run.get("transaction_projection")
    if isinstance(projection, dict):
        require(projection.get("native_reccmp_run") is run,
                "native reccmp transaction ownership changed")
        projection["native_reccmp_run"] = None


def publish_native_reccmp_outputs_after_cleanup(
    *, run: dict, report_path: Path, report: bytes, log_path: Path,
    log: bytes, audit_path: Path, audit: dict,
) -> None:
    """Remove the private namespace before publishing its terminal evidence."""
    installed = [report_path, log_path, audit_path]
    invalidate_build_paths(installed)
    try:
        cleanup_native_reccmp_run(run)
        run["_namespace_removed"] = True
        audit["native_transport"]["run_private_namespace_removed"] = True
        atomic_write(report_path, report)
        atomic_write(log_path, log)
        atomic_json(audit_path, audit)
    except BaseException:
        # A cleanup or partial-publication failure cannot leave a report, log,
        # or audit that claims the private producer namespace was removed.
        invalidate_build_paths(installed)
        raise


def rollback_failed_native_reccmp_invocation(
    run: dict, installed: list[Path],
) -> None:
    """Independently invalidate claims and recover one prepared analysis run."""
    failures = []
    try:
        invalidate_build_paths(installed)
    except BaseException as error:
        failures.append(f"published paths: {error}")
    if run.get("_namespace_removed") is not True:
        try:
            cleanup_native_reccmp_run(run)
        except BaseException as error:
            failures.append(f"private run: {error}")
    require(
        not failures,
        "native reccmp rollback failed: " + "; ".join(failures),
    )


def prepared_native_reccmp_invocation(
    *, run: dict, policy: dict, original: Path, image: Path, pdb: Path,
    map_path: Path, source_snapshot: Path, logical_source_root: Path,
    source_pin_sha: str,
    link_audit: dict, image_gate: dict,
) -> dict:
    """Derive the exact invocation while the prepared namespace is owned."""
    physical_report = run["report"]
    generated_by_role = {item["role"]: item for item in run["inputs"]}
    require(set(generated_by_role) == {
        "retail_oracle", "recompiled_image", "analysis_pdb", "release_map",
    }, "native reccmp private operand role universe differs")
    consumed_inputs = []
    for role, producer_input, logical_operand, physical_operand, content_sha in (
        (
            "retail_oracle", original, original,
            Path(generated_by_role["retail_oracle"]["physical"]),
            image_gate["original_sha256"],
        ),
        (
            "recompiled_image", image, image,
            Path(generated_by_role["recompiled_image"]["physical"]),
            link_audit["image_sha256"],
        ),
        (
            "analysis_pdb", pdb, pdb,
            Path(generated_by_role["analysis_pdb"]["physical"]),
            link_audit["pdb_sha256"],
        ),
        (
            "release_map", map_path, map_path,
            Path(generated_by_role["release_map"]["physical"]),
            link_audit["map_sha256"],
        ),
        (
            "source_snapshot", source_snapshot, logical_source_root,
            Path(run["source"]), source_pin_sha,
        ),
    ):
        consumed_inputs.append({
            "role": role,
            "producer_input": str(producer_input),
            "logical_operand": str(logical_operand),
            "physical_operand": str(physical_operand),
            "sha256": content_sha,
        })
    consumed_by_role = {item["role"]: item for item in consumed_inputs}
    replacements = {
        "<ORIGINAL>": consumed_by_role["retail_oracle"]["physical_operand"],
        "<IMAGE>": consumed_by_role["recompiled_image"]["physical_operand"],
        "<PDB>": consumed_by_role["analysis_pdb"]["physical_operand"],
        "<SOURCE_ROOT>": consumed_by_role["source_snapshot"]["physical_operand"],
        "<REPORT>": str(physical_report),
    }
    reccmp_arguments = [
        replacements.get(token, token) for token in policy["argv_template"]
    ]
    executed = [
        str(run["interpreter"]), "-S", str(run["executable"]),
        *reccmp_arguments,
    ]
    return {
        "physical_report": physical_report,
        "consumed_inputs": consumed_inputs,
        "executed": executed,
        "environment": native_reccmp_environment(run),
    }


def validate_reccmp_effective_source_snapshot(
    state: dict, source_snapshot: dict, context: str,
) -> None:
    """Prove every typed output is present in reccmp's held source view."""
    overlay = state["source_overlay"]
    if not overlay["enabled"]:
        return
    records = source_snapshot.get("records")
    require(isinstance(records, list),
            f"{context} source snapshot records are absent")
    by_path = {record.get("path"): record for record in records}
    require(len(by_path) == len(records),
            f"{context} source snapshot paths are duplicated")
    for output in overlay["outputs"]:
        relative = output["logical_path"]
        expected = overlay["effective_by_path"][relative]
        record = by_path.get(relative)
        require(
            isinstance(record, dict) and record.get("type") == "file"
            and record.get("sha256") == expected["sha256"]
            and record.get("size") == expected["size"],
            f"{context} lacks the typed effective source: {relative}",
        )


def command_reccmp_launch_locked(arguments: argparse.Namespace) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    invalidate_framework_verdict(arguments.build_dir)
    invalidate_build_paths([
        final_reccmp_audit_path(arguments.build_dir, "LEGO1"),
        final_report_path(arguments.build_dir, "LEGO1"),
        final_reccmp_log_path(arguments.build_dir, "LEGO1"),
    ])
    state, inventory, command_inventory, session = load_producer_state(arguments)
    require(arguments.identity == "LEGO1" and len(state["images"]) == 1,
            "reccmp producer supports only the declared LEGO1 image")
    link_audit, link_audit_bytes = validate_final_link_audit(
        state, inventory, session
    )
    policy = state["terminal_producers"]["reccmp"]
    require_posix_reccmp_backend(state, "terminal reccmp execution")
    executable = Path(policy["executable_path"])
    native_root = native_reccmp_snapshot_path(arguments.build_dir)
    private_descriptor = validate_native_reccmp_snapshot(
        state, arguments.build_dir
    )["runtime"]
    sealed_executable = native_root / "tool/reccmp.py"
    private_runtime_root = native_root / "runtime"
    sealed_interpreter = private_runtime_root / "bin/python3.12"
    sealed_interpreter_sha = sha256_file(sealed_interpreter)
    require(sha256_file(sealed_executable) == policy["executable_sha256"],
            "sealed terminal reccmp executable differs")
    closure_before = terminal_reccmp_closure(state)
    closure_sha = sha256_bytes(json.dumps(
        closure_before, sort_keys=True, separators=(",", ":")
    ).encode("utf-8"))
    image_gate = state["images"][0]
    original = Path(image_gate["original_path"])
    original_data = authority.read_external_bytes(original, max_bytes=1 << 30)
    require(len(original_data) == image_gate["original_size"]
            and sha256_bytes(original_data) == image_gate["original_sha256"]
            and md5_bytes(original_data) == image_gate["original_md5"],
            "retail oracle changed before reccmp launch")
    image = Path(link_audit["image"])
    pdb = Path(link_audit["pdb"])
    map_path = Path(link_audit["map"])
    projection = materialize_execution_projection(state, arguments.build_dir)
    require(
        projection.get("removed") is False
        and projection.get("finalized") is False
        and projection.get("poisoned") is False,
        "terminal reccmp requires the live effective execution projection",
    )
    source_snapshot = absolute_snapshot_seat(
        Path(projection["z"]), Path(state["source_dir"])
    )
    source_pin = canonical_tree_snapshot(source_snapshot, hash_files=True)
    validate_reccmp_effective_source_snapshot(
        state, source_pin, "terminal reccmp held projection"
    )
    source_pin_sha = sha256_bytes(json.dumps(
        _tree_pin(source_pin), sort_keys=True, separators=(",", ":")
    ).encode("utf-8"))
    require(projection.get("reccmp_source_snapshot") is None,
            "terminal reccmp source snapshot was captured twice")
    projection["reccmp_source_snapshot"] = str(source_snapshot)
    projection["reccmp_source_pin"] = source_pin
    projection["reccmp_source_pin_sha256"] = source_pin_sha
    validate_execution_projection_source_overlay_evidence(
        state, projection, "terminal reccmp held projection"
    )
    generated_data = {
        "retail_oracle": original_data,
        "recompiled_image": authority.read_bytes(image, max_bytes=1 << 30),
        "analysis_pdb": authority.read_bytes(pdb, max_bytes=1 << 30),
        "release_map": authority.read_bytes(map_path, max_bytes=1 << 30),
    }
    require(
        sha256_bytes(generated_data["recompiled_image"])
        == link_audit["image_sha256"]
        and sha256_bytes(generated_data["analysis_pdb"])
        == link_audit["pdb_sha256"]
        and sha256_bytes(generated_data["release_map"])
        == link_audit["map_sha256"],
        "LINK operands changed before native reccmp snapshot",
    )
    audit_path = final_reccmp_audit_path(arguments.build_dir, "LEGO1")
    report_path = final_report_path(arguments.build_dir, "LEGO1")
    log_path = final_reccmp_log_path(arguments.build_dir, "LEGO1")
    started = time.monotonic()
    run = prepare_native_reccmp_run(
        state=state,
        build_dir=arguments.build_dir,
        executable=executable,
        source_snapshot=source_snapshot,
        source_pin=source_pin,
        generated_inputs=[
            ("retail_oracle", original, generated_data["retail_oracle"]),
            ("recompiled_image", image, generated_data["recompiled_image"]),
            ("analysis_pdb", pdb, generated_data["analysis_pdb"]),
            ("release_map", map_path, generated_data["release_map"]),
        ],
    )
    try:
        invocation = prepared_native_reccmp_invocation(
            run=run, policy=policy, original=original, image=image, pdb=pdb,
            map_path=map_path, source_snapshot=source_snapshot,
            logical_source_root=Path(state["source_dir"]),
            source_pin_sha=source_pin_sha, link_audit=link_audit,
            image_gate=image_gate,
        )
    except BaseException as original:
        try:
            rollback_failed_native_reccmp_invocation(
                run, [report_path, log_path, audit_path]
            )
        except BaseException as cleanup_error:
            raise ByteIdentityError(str(cleanup_error)) from original
        raise
    physical_report = invocation["physical_report"]
    consumed_inputs = invocation["consumed_inputs"]
    executed = invocation["executed"]
    environment = invocation["environment"]
    try:
        run["holder"].revalidate()
        drain_run_private_wineserver(
            run, state, environment, phase="preflight"
        )
        validate_native_reccmp_run_direct_inputs(run, before_spawn=True)
        try:
            run["producer_child_started"] = True
            returncode, combined_output, timed_out = run_child(
                executed, policy["max_child_seconds"], environment,
                cwd=run["cwd"],
            )
        finally:
            drain_run_private_wineserver(
                run, state, environment, phase="postflight"
            )
        run["holder"].revalidate()
        validate_native_reccmp_run_direct_inputs(run, before_spawn=False)
        output, loaded_images = split_native_reccmp_loader_trace(
            combined_output, run
        )
        require(not timed_out and returncode == 0,
                f"terminal reccmp producer failed with status {returncode}: "
                + output.decode("utf-8", errors="replace")[:2000])
        report = run["holder"].read_bytes(physical_report)
        require(run["holder"].membership(run["output"])
                == {physical_report.name: "file"},
                "terminal reccmp emitted an undeclared output")
        require(not run["holder"].membership(run["temporary"]),
                "terminal reccmp temporary namespace is not empty")
        require(not run["holder"].membership(run["home"]),
                "terminal reccmp HOME namespace is not empty")
        require(exact_json_equal(
                    shared_prefix_metadata_identity(run["prefix"]),
                    run["wine_transport"]["prefix_metadata"],
                ) and run["server_preflight_clear"] is True
                and run["server_postflight_clear"] is True,
                "terminal reccmp private cvdump Wine state changed or leaked")
        server_seat_path = run["wine_transport"]["server_seat_path"]
        validate_wine_server_seat_record(
            run["wine_transport"]["server_seat_preflight"],
            server_seat_path, "terminal reccmp preflight Wine server seat",
        )
        validate_wine_server_seat_record(
            run["wine_transport"]["server_seat_postflight"],
            server_seat_path, "terminal reccmp postflight Wine server seat",
        )
        report_result = validate_reccmp_report_snapshot(report, image_gate)
        if session["mode"] == "iterate":
            report_result = validate_iteration_reccmp_report(report, image_gate)
        else:
            require(session["mode"] == "build",
                    "reccmp producer requires iteration or terminal mode")
        held_snapshots = run["_held_snapshots"]
        require_held_snapshot_unchanged(
            held_snapshots["runtime"],
            canonical_tree_snapshot(
                run["runtime"], hash_files=True,
                include_metadata_records=True,
            ),
            "native reccmp private runtime",
        )
        require_held_snapshot_unchanged(
            held_snapshots["source"],
            canonical_tree_snapshot(
                run["source"], hash_files=True,
                include_metadata_records=True,
            ),
            "native reccmp private source",
        )
        require_held_snapshot_unchanged(
            held_snapshots["tool"],
            canonical_tree_snapshot(
                run["tool"], hash_files=True,
                include_metadata_records=True,
            ),
            "native reccmp private tools",
        )
        require_held_snapshot_unchanged(
            held_snapshots["inputs"],
            canonical_tree_snapshot(
                Path(run["inputs"][0]["physical"]).parents[1],
                hash_files=True, include_metadata_records=True,
            ),
            "native reccmp private generated inputs",
        )
        for record in run["closure_records"]:
            require_held_snapshot_unchanged(
                held_snapshots[f"closure:{record['role']}"],
                canonical_tree_snapshot(
                    Path(record["private_path"]), hash_files=True,
                    include_metadata_records=True,
                ),
                f"native reccmp private closure {record['role']}",
            )
        closure_after = terminal_reccmp_closure(state)
        require(exact_json_equal(closure_after, closure_before),
                "terminal reccmp closure changed during execution")
        require(sha256_file(sealed_executable) == policy["executable_sha256"]
                and sha256_file(sealed_interpreter)
                == sealed_interpreter_sha,
                "sealed terminal reccmp executable/interpreter changed")
        post_source = canonical_tree_snapshot(source_snapshot, hash_files=True)
        require(exact_json_equal(_tree_pin(post_source), _tree_pin(source_pin)),
                "terminal reccmp source snapshot changed during execution")
        audit = {
            "schema": 1,
            "status": "AUTHENTICATED_RECCMP_REPORT_PRODUCED",
            "manifest_sha256": state["manifest_sha256"],
            "outer_session_nonce": session["nonce"],
            "identity": "LEGO1",
            "tool": str(executable),
            "tool_sha256": policy["executable_sha256"],
            "interpreter": str(sealed_interpreter),
            "interpreter_sha256": sealed_interpreter_sha,
            "tool_closure": closure_before,
            "tool_closure_sha256": closure_sha,
            "executed_argv": executed,
            "executed_argv_sha256": stable_argv_sha256(executed),
            "cwd": str(run["cwd"]),
            "consumed_inputs": consumed_inputs,
            "link_audit": str(final_link_audit_path(arguments.build_dir, "LEGO1")),
            "link_audit_sha256": sha256_bytes(link_audit_bytes),
            "image": str(image), "image_sha256": sha256_file(image),
            "pdb": str(pdb), "pdb_sha256": sha256_file(pdb),
            "map": str(map_path), "map_sha256": sha256_file(map_path),
            "source_snapshot": str(source_snapshot),
            "source_snapshot_sha256": source_pin_sha,
            "source_overlay_enabled": projection[
                "source_overlay_enabled"
            ],
            "source_overlay_policy_sha256": projection[
                "source_overlay_policy_sha256"
            ],
            "source_overlay_actual_records_sha256": projection[
                "source_overlay_actual_records_sha256"
            ],
            "source_overlay_receipt_sha256": projection[
                "source_overlay_receipt_sha256"
            ],
            "source_overlay_output_count": projection[
                "source_overlay_output_count"
            ],
            "report": str(report_path),
            "report_sha256": sha256_bytes(report),
            "report_size": len(report),
            "log": str(log_path), "log_sha256": sha256_bytes(output),
            "log_size": len(output),
            "native_transport": {
                "backend": policy["backend"],
                "schema": "backend_reccmp_transport_v1",
                "details": {
                    "schema": "native_held_reccmp_private_cvdump_wine_v1",
                    "transaction_root": str(
                        run["transaction_projection"]["root"]
                    ),
                    "execution_projection_descriptor_sha256": (
                        run["transaction_projection"]["descriptor_sha256"]
                    ),
                    "runtime_tree": run["runtime_tree"],
                    "source_tree": run["source_tree"],
                    "closure_trees": run["closure_records"],
                    "cvdump_wine": {
                        "schema": run["wine_transport"]["schema"],
                        "runtime_targets": run["wine_transport"][
                            "runtime_targets"
                        ],
                        "runtime_snapshot": str(run["wine_transport"][
                            "runtime_snapshot"
                        ]),
                        "toolchain_snapshot_sha256": run["wine_transport"][
                            "toolchain_snapshot_sha256"
                        ],
                        "prefix_snapshot": run["prefix_snapshot"],
                        "server_preflight_clear": True,
                        "server_postflight_clear": True,
                        "server_seat": {
                            "path": server_seat_path,
                            "prefix_identity": run["wine_transport"][
                                "server_seat_prefix_identity"
                            ],
                            "preflight": run["wine_transport"][
                                "server_seat_preflight"
                            ],
                            "postflight": run["wine_transport"][
                                "server_seat_postflight"
                            ],
                        },
                    },
                    "wine_environment_isolated": True,
                },
                "run_private_namespace_removed": False,
            },
            "loaded_images": loaded_images,
            "loaded_images_sha256": sha256_bytes(json.dumps(
                loaded_images, sort_keys=True, separators=(",", ":")
            ).encode("utf-8")),
            "elapsed_seconds": float(time.monotonic() - started),
        }
        exact_audit_keys(audit, FINAL_RECCMP_AUDIT_KEYS,
                         "terminal reccmp producer audit")
        run["holder"].revalidate()
        publish_native_reccmp_outputs_after_cleanup(
            run=run, report_path=report_path, report=report,
            log_path=log_path, log=output, audit_path=audit_path, audit=audit,
        )
    except BaseException as original:
        try:
            rollback_failed_native_reccmp_invocation(
                run, [report_path, log_path, audit_path]
            )
        except BaseException as cleanup_error:
            raise ByteIdentityError(str(cleanup_error)) from original
        raise
    print(json.dumps({"terminal_reccmp": audit}, sort_keys=True))
    return 0


def command_reccmp_launch(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_reccmp_launch_locked(arguments)


def validate_final_reccmp_audit(
    state: dict, inventory: dict, session: dict, link_audit: dict,
    link_audit_bytes: bytes,
) -> tuple[dict, bytes]:
    authority = active_build_authority()
    policy = state["terminal_producers"]["reccmp"]
    require_posix_reccmp_backend(state, "terminal reccmp audit validation")
    audit_path = final_reccmp_audit_path(Path(state["build_dir"]), "LEGO1")
    audit = read_unique_audit(audit_path, authority.build_root, "terminal reccmp audit")
    exact_audit_keys(audit, FINAL_RECCMP_AUDIT_KEYS, "terminal reccmp audit")
    native_root = native_reccmp_snapshot_path(Path(state["build_dir"]))
    sealed_private_interpreter = (
        native_root / "runtime/bin/python3.12"
    )
    require(type(audit.get("schema")) is int and audit.get("schema") == 1
            and audit.get("status") == "AUTHENTICATED_RECCMP_REPORT_PRODUCED"
            and audit.get("manifest_sha256") == state["manifest_sha256"]
            and audit.get("outer_session_nonce") == session["nonce"]
            and audit.get("identity") == "LEGO1"
            and audit.get("tool") == policy["executable_path"]
            and audit.get("tool_sha256") == policy["executable_sha256"]
            and audit.get("interpreter") == str(sealed_private_interpreter)
            and audit.get("interpreter_sha256")
            == sha256_file(sealed_private_interpreter),
            "terminal reccmp producer/session policy differs")
    require(
        sha256_file(native_root / "tool/reccmp.py") == audit["tool_sha256"]
        and sha256_file(sealed_private_interpreter)
        == audit["interpreter_sha256"],
        "sealed terminal reccmp executable/interpreter changed",
    )
    closure = terminal_reccmp_closure(state)
    closure_sha = sha256_bytes(json.dumps(
        closure, sort_keys=True, separators=(",", ":")
    ).encode("utf-8"))
    require(exact_json_equal(closure, audit.get("tool_closure"))
            and closure_sha == audit.get("tool_closure_sha256"),
            "terminal reccmp closure audit differs")
    require(audit.get("link_audit")
            == str(final_link_audit_path(Path(state["build_dir"]), "LEGO1"))
            and audit.get("link_audit_sha256") == sha256_bytes(link_audit_bytes),
            "terminal reccmp audit is not bound to the current LINK producer")
    fixed_artifacts = {
        "image": Path(link_audit["image"]),
        "pdb": Path(link_audit["pdb"]),
        "map": Path(link_audit["map"]),
        "report": final_report_path(Path(state["build_dir"]), "LEGO1"),
        "log": final_reccmp_log_path(Path(state["build_dir"]), "LEGO1"),
    }
    data = {}
    for name, expected in fixed_artifacts.items():
        require(authority.parts(Path(audit.get(name, "")))
                == authority.parts(expected),
                f"terminal reccmp {name} path differs")
        value = authority.read_bytes(expected, max_bytes=512 * 1024 * 1024)
        require(sha256_bytes(value) == audit.get(f"{name}_sha256"),
                f"terminal reccmp {name} bytes differ")
        if name in ("report", "log"):
            require(len(value) == audit.get(f"{name}_size"),
                    f"terminal reccmp {name} size differs")
        data[name] = value
    projection = authority.execution_projection
    require(
        isinstance(projection, dict)
        and projection.get("finalized") is True
        and projection.get("removed") is True
        and projection.get("transaction_binding", {}).get("session_nonce")
        == session["nonce"],
        "terminal reccmp source lacks same-transaction projection authority",
    )
    source_snapshot = absolute_snapshot_seat(
        Path(projection["z"]), Path(state["source_dir"])
    )
    require(audit.get("source_snapshot") == str(source_snapshot),
            "terminal reccmp source snapshot path differs")
    source_pin = projection.get("reccmp_source_pin")
    require(isinstance(source_pin, dict),
            "terminal reccmp effective source pin is absent")
    source_sha = sha256_bytes(json.dumps(
        _tree_pin(source_pin), sort_keys=True, separators=(",", ":")
    ).encode("utf-8"))
    require(
            projection.get("reccmp_source_snapshot") == str(source_snapshot)
            and projection.get("reccmp_source_pin_sha256") == source_sha
            and source_sha == audit.get("source_snapshot_sha256"),
            "terminal reccmp source snapshot differs")
    validate_reccmp_effective_source_snapshot(
        state, source_pin, "terminal reccmp audit"
    )
    validate_execution_projection_source_overlay_evidence(
        state, audit, "terminal reccmp audit"
    )
    authority.pin_build_absence(source_snapshot)
    original_data = authority.read_external_bytes(
        Path(state["images"][0]["original_path"]), max_bytes=1 << 30
    )
    require(
        sha256_bytes(original_data) == state["images"][0]["original_sha256"]
        and len(original_data) == state["images"][0]["original_size"]
        and md5_bytes(original_data) == state["images"][0]["original_md5"],
        "terminal reccmp retail oracle differs",
    )
    expected_consumed = [
        {
            "role": "retail_oracle",
            "producer_input": state["images"][0]["original_path"],
            "logical_operand": state["images"][0]["original_path"],
            "sha256": state["images"][0]["original_sha256"],
        },
        {
            "role": "recompiled_image",
            "producer_input": str(fixed_artifacts["image"]),
            "logical_operand": str(fixed_artifacts["image"]),
            "sha256": sha256_bytes(data["image"]),
        },
        {
            "role": "analysis_pdb",
            "producer_input": str(fixed_artifacts["pdb"]),
            "logical_operand": str(fixed_artifacts["pdb"]),
            "sha256": sha256_bytes(data["pdb"]),
        },
        {
            "role": "release_map",
            "producer_input": str(fixed_artifacts["map"]),
            "logical_operand": str(fixed_artifacts["map"]),
            "sha256": sha256_bytes(data["map"]),
        },
        {
            "role": "source_snapshot",
            "producer_input": str(source_snapshot),
            "logical_operand": state["source_dir"],
            "sha256": source_sha,
        },
    ]
    consumed = audit.get("consumed_inputs")
    require(isinstance(consumed, list)
            and len(consumed) == len(expected_consumed),
            "terminal reccmp consumed-input universe differs")
    expected_run_root = native_reccmp_transaction_path(
        Path(state["build_dir"]), session["nonce"]
    )
    expected_run_parts = authority.parts(expected_run_root)
    run_parts = None
    consumed_by_role = {}
    for index, (record, expected) in enumerate(zip(consumed, expected_consumed)):
        context = f"terminal reccmp consumed_inputs[{index}]"
        require(isinstance(record, dict), f"{context} is not an object")
        exact_audit_keys(record, RECCMP_CONSUMED_INPUT_KEYS, context)
        require(
            all(record.get(key) == value for key, value in expected.items())
            and SHA256_RE.fullmatch(record.get("sha256", "")) is not None,
            f"{context} provenance differs",
        )
        physical = Path(record.get("physical_operand", ""))
        parts, observed_run_parts = validate_native_reccmp_transaction_operand(
            physical, Path(state["build_dir"]), session["nonce"], context
        )
        require(observed_run_parts == expected_run_parts,
                "terminal reccmp private run authority differs")
        if run_parts is None:
            run_parts = expected_run_parts
        require(parts[:len(run_parts)] == run_parts,
                "terminal reccmp consumed inputs span multiple run snapshots")
        if record["role"] == "source_snapshot":
            require(parts == (*run_parts, "source"),
                    "terminal reccmp source operand has the wrong private seat")
        else:
            require(parts == (
                        *run_parts, "inputs", record["role"],
                        Path(record["logical_operand"]).name,
                    ),
                    f"{context} has the wrong private input seat")
        authority.pin_build_absence(physical)
        consumed_by_role[record["role"]] = record
    executed = audit.get("executed_argv")
    require(run_parts is not None,
            "terminal reccmp consumed-input run snapshot is absent")
    run_root = authority.path(run_parts)
    require(run_root == expected_run_root,
            "terminal reccmp run root differs from its session-owned seat")
    expected_interpreter = run_root / "runtime/bin/python3.12"
    expected_executable = run_root / "tool/reccmp.py"
    require(isinstance(executed, list)
            and stable_argv_sha256(executed) == audit.get("executed_argv_sha256")
            and not raw_argument_token_errors(executed)
            and executed[:3] == [
                str(expected_interpreter), "-S", str(expected_executable)
            ],
            "terminal reccmp executed argv hash differs")
    authority.pin_build_absence(expected_interpreter)
    authority.pin_build_absence(expected_executable)
    expected_arguments = []
    report_operand = None
    for token in policy["argv_template"]:
        if token == "<ORIGINAL>":
            expected_arguments.append(
                consumed_by_role["retail_oracle"]["physical_operand"]
            )
        elif token == "<IMAGE>":
            expected_arguments.append(
                consumed_by_role["recompiled_image"]["physical_operand"]
            )
        elif token == "<PDB>":
            expected_arguments.append(
                consumed_by_role["analysis_pdb"]["physical_operand"]
            )
        elif token == "<SOURCE_ROOT>":
            expected_arguments.append(
                consumed_by_role["source_snapshot"]["physical_operand"]
            )
        elif token == "<REPORT>":
            report_operand = executed[len(expected_arguments) + 3]
            report_path = Path(report_operand)
            parts = authority.parts(report_path)
            require(parts == (*run_parts, "output", "producer-report.json"),
                    "terminal reccmp private report operand is outside its run")
            authority.pin_build_absence(report_path)
            expected_arguments.append(report_operand)
        else:
            expected_arguments.append(token)
    require(exact_json_equal(executed, [
                str(expected_interpreter), "-S", str(expected_executable),
                *expected_arguments,
            ])
            and audit.get("cwd") == str(run_root),
            "terminal reccmp executed invocation differs from the exact policy")
    transport = audit.get("native_transport")
    require(isinstance(transport, dict),
            "terminal reccmp native transport audit is invalid")
    exact_audit_keys(transport, {
        "backend", "schema", "details", "run_private_namespace_removed",
    }, "terminal reccmp native transport")
    require(transport.get("backend") == policy.get("backend")
            == state["execution_backend"]["id"] == POSIX_WINE_BACKEND
            and transport.get("schema") == "backend_reccmp_transport_v1"
            and transport.get("run_private_namespace_removed") is True,
            "terminal reccmp did not use the exact native held transport")
    details = transport.get("details")
    require(isinstance(details, dict),
            "terminal reccmp backend transport details are absent")
    exact_audit_keys(details, {
        "schema", "transaction_root",
        "execution_projection_descriptor_sha256",
        "runtime_tree", "source_tree", "closure_trees",
        "cvdump_wine", "wine_environment_isolated",
    }, "terminal POSIX reccmp transport details")
    require(details.get("schema")
            == "native_held_reccmp_private_cvdump_wine_v1"
            and details.get("wine_environment_isolated") is True,
            "terminal POSIX reccmp transport details differ")
    expected_transaction_root = native_reccmp_transaction_path(
        Path(state["build_dir"]), session["nonce"]
    ).parent
    require(
        details.get("transaction_root") == str(expected_transaction_root),
        "terminal reccmp transaction root differs from its outer nonce",
    )
    validate_execution_projection_evidence(
        details.get("transaction_root"),
        details.get("execution_projection_descriptor_sha256"),
        Path(state["build_dir"]), "terminal reccmp producer",
    )
    cvdump_wine = details.get("cvdump_wine")
    require(isinstance(cvdump_wine, dict),
            "terminal reccmp cvdump Wine transport is absent")
    exact_audit_keys(cvdump_wine, {
        "schema", "runtime_targets", "runtime_snapshot",
        "toolchain_snapshot_sha256", "prefix_snapshot",
        "server_preflight_clear", "server_postflight_clear",
        "server_seat",
    }, "terminal reccmp cvdump Wine transport")
    held_host = toolchain_snapshot_path(Path(state["build_dir"])) / "host"
    runtime_bin = validate_runtime_bin(state, Path(state["build_dir"]))
    expected_runtime_targets = {
        name: str(Path(active_build_authority().readlink(runtime_bin / name)))
        for name in ("wine", "winepath", "wineserver")
    }
    prefix_snapshot = cvdump_wine.get("prefix_snapshot")
    require(cvdump_wine.get("schema") == "run_private_cvdump_wine_v1"
            and cvdump_wine.get("runtime_targets")
            == expected_runtime_targets
            and cvdump_wine.get("runtime_snapshot") == str(held_host)
            and cvdump_wine.get("toolchain_snapshot_sha256")
            == sha256_file(toolchain_snapshot_path(Path(state["build_dir"]))
                           / "snapshot.json")
            and isinstance(prefix_snapshot, dict)
            and set(prefix_snapshot) == {"entry_count", "content_sha256"}
            and type(prefix_snapshot.get("entry_count")) is int
            and prefix_snapshot["entry_count"] > 0
            and SHA256_RE.fullmatch(prefix_snapshot.get("content_sha256", ""))
            and cvdump_wine.get("server_preflight_clear") is True
            and cvdump_wine.get("server_postflight_clear") is True,
            "terminal reccmp cvdump Wine transport differs")
    server_seat = cvdump_wine.get("server_seat")
    require(isinstance(server_seat, dict),
            "terminal reccmp Wine server-seat evidence is absent")
    exact_audit_keys(server_seat, {
        "path", "prefix_identity", "preflight", "postflight",
    }, "terminal reccmp Wine server seat")
    prefix_identity = server_seat.get("prefix_identity")
    require(isinstance(prefix_identity, dict),
            "terminal reccmp Wine prefix identity is absent")
    exact_audit_keys(prefix_identity, {"device", "inode"},
                     "terminal reccmp Wine prefix identity")
    require(
        all(isinstance(prefix_identity.get(key), str)
            and re.fullmatch(r"[0-9a-f]+", prefix_identity[key]) is not None
            for key in ("device", "inode")),
        "terminal reccmp Wine prefix identity differs",
    )
    expected_server_seat = str(
        Path("/tmp").resolve(strict=True)
        / f".wine-{os.getuid()}"
        / (f"server-{prefix_identity['device']}-{prefix_identity['inode']}")
    )
    require(server_seat.get("path") == expected_server_seat,
            "terminal reccmp Wine server seat path differs")
    validate_wine_server_seat_record(
        server_seat.get("preflight"), expected_server_seat,
        "terminal reccmp Wine server seat preflight",
    )
    validate_wine_server_seat_record(
        server_seat.get("postflight"), expected_server_seat,
        "terminal reccmp Wine server seat postflight",
    )
    authority.pin_build_absence(run_root / "wine-bin")
    authority.pin_build_absence(run_root / "wine-prefix")

    runtime_tree = details.get("runtime_tree")
    source_tree = details.get("source_tree")
    for tree, expected_root, context in (
        (runtime_tree, run_root / "runtime", "runtime"),
        (source_tree, run_root / "source", "source"),
    ):
        require(isinstance(tree, dict)
                and set(tree) == {
                    "root", "entry_count", "max_depth",
                    "membership_sha256", "content_sha256",
                }
                and tree.get("root") == str(expected_root)
                and type(tree.get("entry_count")) is int
                and tree["entry_count"] > 0
                and type(tree.get("max_depth")) is int
                and tree["max_depth"] >= 0,
                f"terminal reccmp private {context} tree pin differs")
        require_sha(tree.get("membership_sha256"),
                    f"terminal reccmp private {context} membership")
        require_sha(tree.get("content_sha256"),
                    f"terminal reccmp private {context} content")
    private_runtime_descriptor = validate_native_reccmp_snapshot(
        state, Path(state["build_dir"])
    )["runtime"]
    require(runtime_tree["entry_count"]
            == private_runtime_descriptor["tree"]["entry_count"]
            and runtime_tree["max_depth"]
            == private_runtime_descriptor["tree"]["max_depth"]
            and source_tree["entry_count"] == source_pin["entry_count"]
            and source_tree["max_depth"] == source_pin["max_depth"]
            and source_tree["membership_sha256"]
            == source_pin["membership_sha256"]
            and source_tree["content_sha256"]
            == source_pin["content_sha256"],
            "terminal reccmp private runtime/source universe differs")

    closure_trees = details.get("closure_trees")
    require(isinstance(closure_trees, list)
            and len(closure_trees) == len(closure),
            "terminal reccmp private closure tree universe differs")
    closure_by_role = {}
    for index, (item, expected) in enumerate(zip(closure_trees, closure)):
        context = f"terminal reccmp native closure_trees[{index}]"
        require(isinstance(item, dict), f"{context} is not an object")
        exact_audit_keys(
            item, {"role", "logical_path", "private_path", "tree"}, context
        )
        role = expected["role"]
        private_path = (
            run_root / "pythonpath/reccmp"
            if role == "reccmp_source"
            else run_root / "closures/reccmp_environment"
        )
        tree = item.get("tree")
        require(item.get("role") == role
                and item.get("logical_path") == expected["path"]
                and item.get("private_path") == str(private_path)
                and isinstance(tree, dict)
                and tree.get("root") == str(private_path)
                and tree.get("entry_count") == expected["entry_count"]
                and tree.get("max_depth") == expected["max_depth"],
                f"{context} identity differs")
        closure_by_role[role] = expected

    loaded_images = audit.get("loaded_images")
    require(isinstance(loaded_images, list) and loaded_images,
            "terminal reccmp loaded-image evidence is absent")
    require(sha256_bytes(json.dumps(
                loaded_images, sort_keys=True, separators=(",", ":")
            ).encode("utf-8")) == audit.get("loaded_images_sha256"),
            "terminal reccmp loaded-image evidence hash differs")
    saw_private_python = False
    saw_private_cvdump_wine = False
    for index, item in enumerate(loaded_images):
        context = f"terminal reccmp loaded_images[{index}]"
        require(isinstance(item, dict), f"{context} is not an object")
        exact_audit_keys(item, {"scope", "role", "path", "sha256"}, context)
        scope = item.get("scope")
        value = item.get("path")
        require(isinstance(value, str) and value,
                f"{context}.path is invalid")
        if scope == "system":
            require(item.get("role") is None and item.get("sha256") is None
                    and any(value.startswith(prefix)
                            for prefix in _SYSTEM_DYLD_PREFIXES),
                    f"{context} is not an admitted system image")
            continue
        relative = PurePosixPath(value)
        require(not relative.is_absolute() and ".." not in relative.parts,
                f"{context} private image path escapes")
        if scope == "private_runtime":
            require(item.get("role") is None,
                    f"{context} private runtime role differs")
            sealed = native_reccmp_snapshot_path(
                Path(state["build_dir"])
            ).joinpath("runtime", *relative.parts)
            saw_private_python |= value == "lib/Python"
        elif scope == "private_closure":
            role = item.get("role")
            require(role in closure_by_role,
                    f"{context} private closure role differs")
            sealed = Path(closure_by_role[role]["snapshot_path"]).joinpath(
                *relative.parts
            )
        elif scope == "private_cvdump_wine_runtime":
            require(item.get("role") is None,
                    f"{context} private cvdump Wine role differs")
            sealed = held_host.joinpath(*relative.parts)
            saw_private_cvdump_wine = True
        else:
            raise ByteIdentityError(f"{context}.scope is unsupported")
        require(authority.is_regular_file(sealed)
                and require_sha(item.get("sha256"), f"{context}.sha256")
                == sha256_file(sealed),
                f"{context} private image differs from the sealed runtime")
    require(saw_private_python,
            "terminal reccmp loaded-image evidence omits private Python")
    require(saw_private_cvdump_wine,
            "terminal reccmp loaded-image evidence omits private cvdump Wine")
    authority.pin_build_absence(run_root)
    require_nonnegative_finite_number(
        audit.get("elapsed_seconds"), "terminal reccmp elapsed_seconds"
    )
    return audit, data["report"]


def resolved_argument_path(value: str, cwd: Path) -> Path:
    path = Path(value)
    return (cwd / path).resolve() if not path.is_absolute() else path.resolve()


def lexical_argument_path(value: str, cwd: Path) -> Path:
    return lexical_absolute_path(Path(value), cwd)


def _argument_text(value: str) -> str:
    # The OS has already removed shell quoting.  Literal quote bytes here are
    # compiler input, not syntax, and must never be normalized into an
    # apparently policy-compatible token.
    return value


def raw_argument_token_errors(arguments: list[str]) -> list[str]:
    errors = []
    for index, value in enumerate(arguments):
        if not isinstance(value, str) or not value or "\0" in value:
            errors.append(f"compiler argv token {index} is empty or invalid")
            continue
        if '"' in value or "'" in value:
            errors.append(
                f"compiler argv token {index} contains literal wrapping/escape quotes"
            )
    return errors


ADMITTED_NO_OPERAND_OPTIONS = {
    "/nologo", "-nologo", "/W3", "-W3", "/WX", "-WX",
    "/GX", "-GX", "/Zi", "-Zi", "/O1", "-O1", "/O2", "-O2",
    "/Od", "-Od", "/Ox", "-Ox", "/Ob0", "-Ob0", "/Ob1", "-Ob1",
    "/Ob2", "-Ob2", "/Oy", "-Oy", "/Oy-", "-Oy-",
    "/Gm", "-Gm", "/Gm-", "-Gm-", "/GR", "-GR", "/GR-", "-GR-",
    "/c", "-c", "/TC", "-TC", "/TP", "-TP",
    "/MD", "-MD", "/MDd", "-MDd", "/MT", "-MT", "/MTd", "-MTd",
}


def _admitted_warning_option(token: str) -> bool:
    return re.fullmatch(r"[/-](?:W[0-4]|WX|w[devo]?[0-9]+)", token) is not None


def lex_compile_arguments(arguments: list[str]) -> dict:
    """Classify every token before the attested final source by role.

    Only `/D`, `/U`, and `/I` intentionally admit a separate operand.  The
    output and force-include options are collected even in their forbidden
    separated form so pre-gate cleanup can use the same lexer as semantic
    validation.  An unknown option or any earlier positional token is fatal.
    """
    valued: dict[str, list[tuple[int, str, bool]]] = {
        "Fo": [], "Fd": [], "FI": [], "D": [], "U": [], "I": [],
    }
    role_operands = []
    compile_only = []
    compile_only_indices = []
    debug_format = []
    language_modes = []
    roles = [{"index": 0, "role": "compiler", "token": arguments[0]}] if arguments else []
    errors = []
    errors.extend(raw_argument_token_errors(arguments))
    if len(arguments) < 2 or not _argument_text(arguments[-1]):
        errors.append("compiler command has no final positional source")
        final_source = ""
        limit = len(arguments)
    else:
        final_source = _argument_text(arguments[-1])
        limit = len(arguments) - 1

    index = 1
    while index < limit:
        token = _argument_text(arguments[index])
        matched = False
        for option in ("FI", "Fd", "Fo"):
            for sigil in ("/", "-"):
                prefix = sigil + option
                if token == prefix:
                    if index + 1 < limit and _argument_text(arguments[index + 1]):
                        value = _argument_text(arguments[index + 1])
                        valued[option].append((index, value, True))
                        role_operands.append((option, value))
                        roles.append({
                            "index": index, "role": option, "token": token,
                            "value": value, "separate": True,
                        })
                        errors.append(
                            f"/{option} value must be attached to its exact option token"
                        )
                        index += 2
                    else:
                        errors.append(f"missing value after {token}")
                        index += 1
                    matched = True
                    break
                if token.startswith(prefix):
                    value = token[len(prefix):]
                    if value:
                        valued[option].append((index, value, False))
                        role_operands.append((option, value))
                        roles.append({
                            "index": index, "role": option, "token": token,
                            "value": value, "separate": False,
                        })
                    else:
                        errors.append(f"missing value after {prefix}")
                    index += 1
                    matched = True
                    break
            if matched:
                break
        if matched:
            continue

        for option in ("D", "U", "I"):
            for sigil in ("/", "-"):
                prefix = sigil + option
                if token == prefix:
                    if index + 1 < limit and _argument_text(arguments[index + 1]):
                        value = _argument_text(arguments[index + 1])
                        valued[option].append((index, value, True))
                        role_operands.append((option, value))
                        roles.append({
                            "index": index, "role": option, "token": token,
                            "value": value, "separate": True,
                        })
                        index += 2
                    else:
                        errors.append(f"missing value after {token}")
                        index += 1
                    matched = True
                    break
                if token.startswith(prefix):
                    value = token[len(prefix):]
                    if value:
                        valued[option].append((index, value, False))
                        role_operands.append((option, value))
                        roles.append({
                            "index": index, "role": option, "token": token,
                            "value": value, "separate": False,
                        })
                    else:
                        errors.append(f"missing value after {prefix}")
                    index += 1
                    matched = True
                    break
            if matched:
                break
        if matched:
            continue

        if token in ADMITTED_NO_OPERAND_OPTIONS or _admitted_warning_option(token):
            roles.append({"index": index, "role": "flag", "token": token})
            if token in ("/c", "-c"):
                compile_only.append(token)
                compile_only_indices.append(index)
            elif token in ("/Zi", "-Zi"):
                debug_format.append(token)
            elif token in ("/TC", "-TC"):
                language_modes.append("C")
            elif token in ("/TP", "-TP"):
                language_modes.append("CXX")
            index += 1
            continue

        folded = token.casefold()
        if folded in ("/c", "-c"):
            errors.append("compile-only mode must use exact lowercase /c or -c")
        elif folded in ("/zi", "-zi"):
            errors.append("debug format must use exact /Zi or -Zi")
        elif any(
            folded.startswith((sigil + option).casefold())
            for option in ("FI", "Fd", "Fo") for sigil in ("/", "-")
        ):
            errors.append(f"compiler option collides with exact output grammar: {token}")
        elif folded.startswith(("/y", "-y")):
            errors.append(f"the complete /Y compiler state family is forbidden: {token}")
        elif re.match(r"^[/-]b(?:$|1|2|x)", token, re.IGNORECASE):
            errors.append("compiler component/pass override options are forbidden")
        elif folded in FORBIDDEN_CONVENIENCE_OPTIONS:
            errors.append(f"preprocess compiler convenience mode is forbidden: {token}")
        elif folded in ("/link", "-link") or folded.startswith(("/link:", "-link:")):
            errors.append("compiler link-tail mode is forbidden")
        elif folded.startswith((
            "/fi", "-fi", "/fr", "-fr", "/fp", "-fp",
            "/fc", "-fc", "/fs", "-fs", "/fu", "-fu", "/fx", "-fx",
            "/fe", "-fe", "/fm", "-fm", "/fa", "-fa",
            "/tc", "-tc", "/tp", "-tp", "/ld", "-ld",
            "/zs", "-zs", "/gl", "-gl", "/z7", "-z7",
            "/ai", "-ai", "/doc", "-doc", "/analyze", "-analyze",
            "/ifc", "-ifc", "/interface", "-interface",
            "/internalpartition", "-internalpartition",
            "/exportheader", "-exportheader", "/headerunit", "-headerunit",
            "/reference", "-reference", "/sourcedependencies", "-sourcedependencies",
            "/scandependencies", "-scandependencies", "/clr", "-clr",
            "/zw", "-zw",
        )):
            errors.append(f"unsupported compiler input/output/link mode: {token}")
        elif token.startswith(("/", "-")):
            errors.append(f"unsupported compiler option: {token}")
        else:
            errors.append(f"extra positional compiler input before final source: {token}")
        index += 1

    if len(valued["Fo"]) != 1:
        errors.append(f"expected one exact /Fo, found {len(valued['Fo'])}")
    if len(valued["Fd"]) != 1:
        errors.append(f"expected one exact /Fd, found {len(valued['Fd'])}")
    if len(compile_only) != 1:
        errors.append(f"expected one exact /c or -c, found {len(compile_only)}")
    if len(debug_format) != 1:
        errors.append(f"expected one exact /Zi or -Zi, found {len(debug_format)}")
    if len(language_modes) > 1:
        errors.append(
            f"expected at most one exact /TC or /TP, found {len(language_modes)}"
        )
    if (len(valued["Fo"]) == 1 and len(valued["Fd"]) == 1
            and len(compile_only_indices) == 1):
        if (
            valued["Fo"][0][0] != len(arguments) - 4
            or valued["Fo"][0][2]
            or valued["Fd"][0][0] != len(arguments) - 3
            or valued["Fd"][0][2]
            or compile_only_indices[0] != len(arguments) - 2
        ):
            errors.append(
                "compiler command must end with attached /Fo, attached /Fd, "
                "exact -c, and the configured source"
            )
    return {
        "valued": valued,
        "role_operands": role_operands,
        "compile_only": compile_only,
        "compile_only_indices": compile_only_indices,
        "debug_format": debug_format,
        "language_modes": language_modes,
        "roles": [
            *roles,
            ({"index": len(arguments) - 1, "role": "source", "token": final_source}
             if final_source else {}),
        ] if final_source else roles,
        "source_token": final_source,
        "errors": errors,
    }


def provisional_valued_options(
    arguments: list[str], names: tuple[str, ...] = ("FI", "Fd", "Fo")
) -> dict[str, list[tuple[int, str, bool]]]:
    """Collect visible exact output roles through the shared argv lexer."""
    parsed = lex_compile_arguments(arguments)
    return {name: parsed["valued"][name] for name in names}


def validate_compile_arguments(arguments: list[str]) -> dict:
    """Enforce the closed, case-aware VC4.2 compiler argv grammar."""
    parsed = lex_compile_arguments(arguments)
    require(not parsed["errors"], "; ".join(parsed["errors"]))
    valued = parsed["valued"]
    return {
        "Fo": valued["Fo"][0],
        "Fd": valued["Fd"][0],
        "force_includes": valued["FI"],
        "definitions": valued["D"],
        "undefinitions": valued["U"],
        "include_paths": valued["I"],
        "role_operands": parsed["role_operands"],
        "source_token": parsed["source_token"],
        "compile_only": parsed["compile_only"][0],
        "debug_format": parsed["debug_format"][0],
        "language_mode": (
            parsed["language_modes"][0] if parsed["language_modes"] else None
        ),
        "roles": parsed["roles"],
    }


def validate_generated_cxx_semantic_profile(parsed: dict, context: str) -> None:
    """Bind every generated CXX command to the optimized-debug baseline."""
    flags = [
        item["token"] for item in parsed["roles"]
        if item.get("role") == "flag"
    ]
    require(flags.count("/Zi") == 1,
            f"{context} must contain exactly one literal /Zi")
    require(flags.count("/O2") == 1,
            f"{context} must contain exactly one literal /O2")
    normalized_flags = {
        "/" + token[1:].casefold()
        for token in flags if token.startswith(("/", "-"))
    }
    require("/od" not in normalized_flags,
            f"{context} may not enable /Od")
    require("/gm" not in normalized_flags,
            f"{context} may not enable /Gm")
    definition_names = [
        value.split("=", 1)[0] for _, value, _ in parsed["definitions"]
    ]
    require(definition_names.count("NDEBUG") == 1,
            f"{context} must define exact NDEBUG exactly once")
    require(not any(name.casefold() == "_debug" for name in definition_names),
            f"{context} may not define _DEBUG")
    undefinition_names = [
        value.split("=", 1)[0] for _, value, _ in parsed["undefinitions"]
    ]
    require(not any(name.casefold() == "ndebug"
                    for name in undefinition_names),
            f"{context} may not undefine NDEBUG")


def option_value(arguments: list[str], option: str) -> tuple[int, str, bool]:
    require(option in ("Fo", "Fd"), f"unsupported rewritten option: /{option}")
    return validate_compile_arguments(arguments)[option]


def replace_option(arguments: list[str], option: str, new_value: Path) -> tuple[list[str], Path]:
    index, old_value, separate = option_value(arguments, option)
    result = list(arguments)
    if separate:
        result[index + 1] = str(new_value)
    else:
        prefix = result[index][: len(option) + 1]
        result[index] = prefix + str(new_value)
    return result, lexical_argument_path(old_value, Path.cwd())


def force_include_arguments(arguments: list[str], cwd: Path) -> list[Path]:
    parsed = validate_compile_arguments(arguments)
    return [
        resolved_argument_path(value, cwd)
        for _, value, _ in parsed["force_includes"]
    ]


def reject_convenience_arguments(arguments: list[str]) -> None:
    validate_compile_arguments(arguments)


def implicit_cmake_source_language(source: Path) -> str | None:
    """Return the language established by CMake's advertised extension alone."""
    extension = source.suffix[1:] if source.suffix.startswith(".") else ""
    if extension in {"c", "m"}:
        return "C"
    if extension in {
        "C", "M", "c++", "cc", "cpp", "cxx", "mm", "mpp", "CPP",
        "ixx", "cppm", "ccm", "cxxm", "c++m",
    }:
        return "CXX"
    return None


PDB_REFERENCE_RE = re.compile(
    rb"(?i)(?:[a-z]:[\\/]|/)[^\x00\r\n]{1,2048}?[.]pdb(?=\x00)"
)


def embedded_pdb_references_bytes(
    data: bytes, object_path: Path, expected_pdb: Path
) -> list[str]:
    """Prove the object names the exact private PDB that remains installed."""
    references = [
        match.group(0).decode("ascii", "strict")
        for match in PDB_REFERENCE_RE.finditer(data)
    ]
    require(references, f"compiler object has no embedded PDB path: {object_path}")
    normalized = set()
    for reference in references:
        value = reference.replace("\\", "/")
        if re.match(r"^[A-Za-z]:/", value):
            require(value[:2].casefold() == "z:",
                    f"compiler object embeds a non-host Wine PDB path: {object_path}")
            value = value[2:]
        normalized.add(value.casefold())
    authority = active_authority_for_path(expected_pdb)
    expected_path = (
        authority.path(authority.parts(expected_pdb))
        if authority is not None else expected_pdb.resolve()
    )
    expected = expected_path.as_posix().casefold()
    require(normalized == {expected},
            f"compiler object embedded PDB path differs: {object_path}")
    return references


def embedded_pdb_references(object_path: Path, expected_pdb: Path) -> list[str]:
    authority = active_authority_for_path(object_path)
    data = (
        authority.read_bytes(object_path)
        if authority is not None else object_path.read_bytes()
    )
    return embedded_pdb_references_bytes(data, object_path, expected_pdb)


def process_group_exists(group_id: int) -> bool:
    try:
        os.killpg(group_id, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def signal_process_group(group_id: int, signum: int) -> None:
    try:
        os.killpg(group_id, signum)
    except ProcessLookupError:
        pass


def terminate_and_reap_process_group(process: subprocess.Popen) -> None:
    """Boundedly terminate the owned group and reap its direct leader."""
    signal_process_group(process.pid, signal.SIGTERM)
    if process.poll() is None:
        try:
            process.wait(timeout=2)
        except subprocess.TimeoutExpired:
            signal_process_group(process.pid, signal.SIGKILL)
            try:
                process.wait(timeout=2)
            except subprocess.TimeoutExpired as error:
                raise ByteIdentityError(
                    "compiler process did not exit after SIGKILL"
                ) from error
    deadline = time.monotonic() + 2
    while process_group_exists(process.pid) and time.monotonic() < deadline:
        time.sleep(COMPILER_SLOT_POLL_SECONDS)
    if process_group_exists(process.pid):
        signal_process_group(process.pid, signal.SIGKILL)
        deadline = time.monotonic() + 2
        while process_group_exists(process.pid) and time.monotonic() < deadline:
            time.sleep(COMPILER_SLOT_POLL_SECONDS)
    require(not process_group_exists(process.pid),
            "compiler process group survived bounded cancellation cleanup")


def run_child_windows(
    command: list[str], timeout: int, environment: dict[str, str],
    *, cwd: Path | None = None,
) -> tuple[int, bytes, bool]:
    """Run one child in a kill-on-close Job Object, assigned while suspended."""
    previous_handlers = {}

    def cancel_handler(signum, _frame):
        raise CompilerCancellation(
            f"compiler launch cancelled by signal {signum}"
        )

    for signum in (signal.SIGINT, signal.SIGTERM):
        try:
            previous_handlers[signum] = signal.getsignal(signum)
            signal.signal(signum, cancel_handler)
        except ValueError:
            pass

    process = None
    job = WindowsJob()
    timed_out = False
    forced_postflight = False
    try:
        with tempfile.TemporaryFile() as capture:
            process = subprocess.Popen(
                command,
                stdout=capture,
                stderr=subprocess.STDOUT,
                env=environment,
                cwd=(str(cwd) if cwd is not None else None),
                creationflags=windows_creationflags(),
            )
            job.assign_and_resume(process)
            try:
                process.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                timed_out = True
                job.terminate(0xED)
                try:
                    process.wait(timeout=2)
                except subprocess.TimeoutExpired as error:
                    raise ByteIdentityError(
                        "Windows compiler job leader survived termination"
                    ) from error

            drain_deadline = time.monotonic() + 2
            while job.active_processes() and time.monotonic() < drain_deadline:
                time.sleep(COMPILER_SLOT_POLL_SECONDS)
            forced_postflight = job.active_processes() != 0
            if forced_postflight:
                job.terminate(0xEC)
                try:
                    process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    pass
            capture.seek(0)
            output = capture.read()
        require(
            not forced_postflight,
            "compiler descendants failed the bounded Windows Job postflight drain",
        )
        return process.returncode, output, timed_out
    except BaseException:
        for signum in previous_handlers:
            signal.signal(signum, signal.SIG_IGN)
        try:
            if job.active_processes():
                job.terminate(0xEB)
        except BackendError:
            # Closing the Job below is still an unconditional descendant-kill
            # fallback.  The direct process needs separate cleanup because a
            # cancellation can land after CreateProcess(CREATE_SUSPENDED) but
            # before AssignProcessToJobObject transfers authority to the Job.
            pass
        finally:
            if process is not None and process.poll() is None:
                try:
                    process.terminate()
                except OSError:
                    pass
                try:
                    process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    try:
                        process.kill()
                    except OSError:
                        pass
                    try:
                        process.wait(timeout=2)
                    except subprocess.TimeoutExpired as error:
                        raise ByteIdentityError(
                            "Windows compiler leader survived bounded cancellation cleanup"
                        ) from error
        raise
    finally:
        job.close()
        for signum, handler in previous_handlers.items():
            signal.signal(signum, handler)


def run_child(
    command: list[str], timeout: int, environment: dict[str, str],
    *, cwd: Path | None = None,
) -> tuple[int, bytes, bool]:
    if os.name == "nt":
        return run_child_windows(command, timeout, environment, cwd=cwd)
    # A real file avoids the classic communicate() hang where a detached
    # grandchild inherits the stdout pipe and keeps its write end open.
    previous_handlers = {}

    def cancel_handler(signum, _frame):
        raise CompilerCancellation(
            f"compiler launch cancelled by signal {signum}"
        )

    for signum in (signal.SIGINT, signal.SIGTERM):
        try:
            previous_handlers[signum] = signal.getsignal(signum)
            signal.signal(signum, cancel_handler)
        except ValueError:
            # Only the main Python thread can install signal handlers. All
            # production launcher calls are main-thread calls; a non-main test
            # still gets BaseException cleanup below.
            pass

    process = None
    try:
        with tempfile.TemporaryFile() as capture:
            # Do not expose the fork/exec-to-assignment window to cancellation:
            # a signal there could otherwise raise before ``process`` names the
            # already-started group. Restoring the mask delivers any pending
            # signal only after the group leader is available to the cleanup.
            previous_mask = signal.pthread_sigmask(
                signal.SIG_BLOCK, {signal.SIGINT, signal.SIGTERM}
            )
            try:
                process = subprocess.Popen(
                    command,
                    stdout=capture,
                    stderr=subprocess.STDOUT,
                    env=environment,
                    cwd=(str(cwd) if cwd is not None else None),
                    start_new_session=True,
                )
            finally:
                signal.pthread_sigmask(signal.SIG_SETMASK, previous_mask)
            timed_out = False
            try:
                process.wait(timeout=timeout)
            except subprocess.TimeoutExpired:
                timed_out = True
                terminate_and_reap_process_group(process)

            # A normal parent exit is not enough: Wine helpers that remain in
            # the owned group can wedge the next compile. Give them a short
            # drain, then clean only this invocation's group and fail closed.
            drain_deadline = time.monotonic() + 2
            while (process_group_exists(process.pid)
                   and time.monotonic() < drain_deadline):
                time.sleep(COMPILER_SLOT_POLL_SECONDS)
            forced_postflight = process_group_exists(process.pid)
            if forced_postflight:
                terminate_and_reap_process_group(process)
            capture.seek(0)
            output = capture.read()
        require(not forced_postflight,
                "compiler descendants failed the bounded owned-group postflight drain")
        return process.returncode, output, timed_out
    except BaseException:
        # Cancellation can arrive during wait, postflight, or capture. Ignore
        # repeats only while completing cleanup, and do not release the caller's
        # compiler slot until the owned group is gone and its leader is reaped.
        for signum in previous_handlers:
            signal.signal(signum, signal.SIG_IGN)
        if (process is not None
                and (process.poll() is None or process_group_exists(process.pid))):
            terminate_and_reap_process_group(process)
        raise
    finally:
        for signum, handler in previous_handlers.items():
            signal.signal(signum, handler)


SESSION_NONCE_ENV = "ISLE_BYTE_IDENTITY_SESSION_NONCE"
SESSION_PYTHON_ENV = "ISLE_BYTE_IDENTITY_PYTHON"
SESSION_CONTROLLER_ENV = "ISLE_BYTE_IDENTITY_CONTROLLER_ROOT"


def process_exists(process_id: int) -> bool:
    try:
        return process_is_alive(process_id)
    except BackendError as error:
        raise ByteIdentityError(
            f"cannot validate outer-driver process identity: {error}"
        ) from error


def read_session_document(
    authority: BuildRootAuthority, path: Path, context: str,
) -> dict:
    metadata = authority.lstat(path)
    require(metadata is not None and stat.S_ISREG(metadata.st_mode),
            f"{context} is absent or redirected")
    try:
        value = strict_json_loads(authority.read_text(path))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot read {context}: {error}") from error
    require(isinstance(value, dict), f"{context} must be an object")
    return value


def validate_active_session_authority(
    authority: BuildRootAuthority, nonce: str | None = None,
) -> dict | None:
    """Authenticate the supported outer driver when hard mode is marked.

    Unit-level native fixtures deliberately have no hard-mode marker. A real
    byte-identical build gets the marker before CMake starts, after which every
    framework transaction is bound to the same live outer-driver process and
    nonce. Missing or malformed session state therefore fails before any old
    verdict can survive the transaction cleanup.
    """
    marker_path = hard_mode_marker_path(authority.build_root)
    marker_metadata = authority.lstat(marker_path)
    if marker_metadata is None:
        return None
    require(stat.S_ISREG(marker_metadata.st_mode),
            "byte-identity hard-mode marker is redirected")
    marker = read_session_document(
        authority, marker_path, "byte-identity hard-mode marker"
    )
    exact_audit_keys(
        marker,
        {
            "schema", "status", "source_root", "build_root",
            "bootstrap_python", "bootstrap_python_sha256",
            "bootstrap_framework", "bootstrap_framework_sha256",
            "bootstrap_backend", "bootstrap_backend_sha256",
            "controller_root", "controller_descriptor_sha256",
            "python", "python_sha256", "framework", "framework_sha256",
            "backend", "backend_tool", "backend_tool_sha256",
            "configure_init", "configure_init_sha256",
            "configure_probe_policy", "configure_tools", "host_roots",
        },
        "byte-identity hard-mode marker",
    )
    require(type(marker.get("schema")) is int and marker.get("schema") == 1
            and marker.get("status") == "BYTE_IDENTITY_OUTER_DRIVER_REQUIRED",
            "byte-identity hard-mode marker schema/status differs")
    require(marker.get("build_root") == str(authority.build_root),
            "byte-identity hard-mode marker build root differs")
    controller = load_controller_snapshot(
        authority, Path(marker.get("controller_root", "")),
        require_sha(marker.get("controller_descriptor_sha256"),
                    "hard-mode controller descriptor hash"),
    )
    python = Path(marker.get("python", ""))
    framework = Path(marker.get("framework", ""))
    backend_tool = Path(marker.get("backend_tool", ""))
    require(
        marker.get("backend") == selected_backend()
        and str(python) == controller["python_path"]
        and marker.get("python_sha256") == controller["python"]["sha256"]
        and str(framework) == controller["tool_path"]
        and marker.get("framework_sha256")
        == controller["framework"]["tool"]["sha256"]
        and str(backend_tool) == controller["backend_path"]
        and marker.get("backend_tool_sha256")
        == controller["framework"]["backend"]["sha256"],
        "byte-identity controller identity differs from its snapshot",
    )
    active = read_session_document(
        authority, active_session_path(authority.build_root),
        "active byte-identity outer session",
    )
    exact_audit_keys(
        active,
        {
            "schema", "status", "nonce", "mode", "driver_pid",
            "source_root", "build_root", "cmake", "cmake_sha256",
            "bootstrap_python", "bootstrap_python_sha256",
            "bootstrap_framework", "bootstrap_framework_sha256",
            "bootstrap_backend", "bootstrap_backend_sha256",
            "controller_root", "controller_descriptor_sha256",
            "python", "python_sha256", "framework", "framework_sha256",
            "backend", "backend_tool", "backend_tool_sha256",
            "configure_init", "configure_init_sha256",
            "configure_probe_policy", "configure_tools", "host_roots",
            "started_monotonic",
        },
        "active byte-identity outer session",
    )
    require(type(active.get("schema")) is int and active.get("schema") == 1
            and active.get("status") == "BYTE_IDENTITY_OUTER_SESSION_ACTIVE"
            and active.get("mode") in ("configure", "iterate", "build"),
            "active byte-identity outer session schema/status differs")
    active_nonce = active.get("nonce")
    supplied_nonce = nonce if nonce is not None else os.environ.get(SESSION_NONCE_ENV)
    require(isinstance(active_nonce, str) and len(active_nonce) == 64
            and re.fullmatch(r"[0-9a-f]{64}", active_nonce) is not None
            and supplied_nonce == active_nonce,
            "active byte-identity outer session nonce differs")
    driver_pid = require_exact_int(
        active.get("driver_pid"), "outer session driver_pid", minimum=1
    )
    require(process_exists(driver_pid),
            "byte-identity outer-driver process is no longer alive")
    require_nonnegative_finite_number(
        active.get("started_monotonic"), "outer session started_monotonic"
    )
    shared_keys = {
        "source_root", "build_root", "bootstrap_python",
        "bootstrap_python_sha256", "bootstrap_framework",
        "bootstrap_framework_sha256", "bootstrap_backend",
        "bootstrap_backend_sha256", "controller_root",
        "controller_descriptor_sha256", "python", "python_sha256",
        "framework", "framework_sha256", "backend", "backend_tool",
        "backend_tool_sha256", "configure_init", "configure_init_sha256",
        "configure_probe_policy", "configure_tools", "host_roots",
    }
    require(all(active.get(key) == marker.get(key) for key in shared_keys),
            "active byte-identity outer session differs from hard-mode marker")
    require(isinstance(active.get("host_roots"), dict)
            and exact_json_equal(active["host_roots"], manifest_host_roots()),
            "active byte-identity host-root selection changed")
    resident = os.getpid() == driver_pid
    if resident:
        require(
            Path(marker["bootstrap_python"]).resolve(strict=True)
            == Path(sys.executable).resolve(strict=True)
            and sha256_file(Path(sys.executable).resolve(strict=True))
            == marker["bootstrap_python_sha256"]
            and Path(marker["bootstrap_framework"]).resolve(strict=True)
            == Path(__file__).resolve(strict=True)
            and sha256_file(Path(__file__).resolve(strict=True))
            == marker["bootstrap_framework_sha256"]
            and Path(marker["bootstrap_backend"]).resolve(strict=True)
            == Path(execution_backend_module.__file__).resolve(strict=True)
            and sha256_file(Path(execution_backend_module.__file__).resolve(strict=True))
            == marker["bootstrap_backend_sha256"],
            "resident outer-driver bootstrap identity changed",
        )
    else:
        actual_descendant = {
            "python": str(Path(sys.executable).resolve(strict=True)),
            "framework": str(Path(__file__).resolve(strict=True)),
            "backend": str(Path(
                execution_backend_module.__file__
            ).resolve(strict=True)),
        }
        expected_descendant = {
            "python": str(python.resolve(strict=True)),
            "framework": str(framework.resolve(strict=True)),
            "backend": str(backend_tool.resolve(strict=True)),
        }
        require(
            actual_descendant == expected_descendant,
            "descendant controller did not execute from the hash-pinned snapshot: "
            f"expected={expected_descendant} actual={actual_descendant}",
        )
    cmake = Path(active.get("cmake", ""))
    require(cmake.is_absolute() and cmake.resolve(strict=True) == cmake
            and cmake.is_file() and os.access(cmake, os.X_OK)
            and sha256_file(cmake) == active.get("cmake_sha256"),
            "active byte-identity CMake identity differs")
    init = Path(active.get("configure_init", ""))
    configure_tools = active.get("configure_tools")
    require(
        isinstance(configure_tools, dict)
        and set(configure_tools) == {"compiler", "rc", "lib", "link"}
        and all(
            Path(value).is_absolute()
            and Path(value).resolve(strict=True) == Path(value)
            and Path(value).is_file()
            and os.access(value, os.X_OK)
            for value in configure_tools.values()
        )
        and
        authority.parts(init)
        == authority.parts(configure_init_path(authority.build_root))
        and authority.is_regular_file(init)
        and authority.read_bytes(init)
        == render_configure_init(active.get("configure_tools"))
        and sha256_file(init) == active.get("configure_init_sha256")
        and active.get("configure_probe_policy")
        == "zero_compiler_actions_forced_manifest_facts_v1",
        "resident configure probe-suppression authority differs",
    )
    return active


@contextmanager
def build_transaction(
    build_dir: Path, *, exclusive: bool,
    bootstrap_outer_session: bool = False,
):
    """Serialize verdict publication against all build-state mutations."""
    require(not ACTIVE_BUILD_AUTHORITIES,
            "nested byte-identity build transactions are forbidden")
    with anchored_build_root(build_dir) as (root_fd, build_root):
        authority = BuildRootAuthority(build_dir, root_fd, build_root)
        ACTIVE_BUILD_AUTHORITIES.append(authority)
        handle = None
        try:
            lock_path = build_root / "byte-identity/locks/transaction.lock"
            handle = authority.open_lock(lock_path)
            platform_lock = PlatformFileLock(handle)
            deadline = time.monotonic() + TRANSACTION_LOCK_WAIT_SECONDS
            while True:
                try:
                    platform_lock.acquire(
                        exclusive=exclusive, nonblocking=True
                    )
                    break
                except BackendLockBusy:
                    remaining = deadline - time.monotonic()
                    require(remaining > 0,
                            "build transaction lock wait timed out")
                    time.sleep(min(COMPILER_SLOT_POLL_SECONDS, remaining))
            authority.revalidate_locks()
            if not bootstrap_outer_session:
                validate_active_session_authority(authority)
            try:
                try:
                    yield authority
                    authority.revalidate_locks()
                    # Standalone producer transactions also get the same
                    # terminal projection proof.  The resident path normally
                    # finalizes earlier, before receipt/verdict publication,
                    # making this an idempotent safety net.
                    finalize_execution_projection(authority)
                except BaseException as error:
                    projection_error = None
                    try:
                        abort_execution_projection(authority)
                    except BaseException as cleanup_error:
                        projection_error = cleanup_error
                    try:
                        verdict = (
                            authority.build_root
                            / "byte-identity/audit/framework-verdict.json"
                        )
                        authority.prune_leaf_or_redirect(verdict)
                        authority.assert_absent(verdict)
                    except BaseException as cleanup_error:
                        raise ByteIdentityError(
                            f"transaction failed and verdict invalidation could not be proven: {cleanup_error}"
                        ) from error
                    if projection_error is not None:
                        raise ByteIdentityError(
                            "transaction failed and execution projection "
                            f"cleanup could not be proven: {projection_error}"
                        ) from error
                    raise
            finally:
                platform_lock.release()
        except BaseException as error:
            try:
                verdict = (
                    authority.build_root
                    / "byte-identity/audit/framework-verdict.json"
                )
                authority.prune_leaf_or_redirect(verdict)
                authority.assert_absent(verdict)
            except BaseException as cleanup_error:
                raise ByteIdentityError(
                    f"transaction setup failed and verdict invalidation could not be proven: {cleanup_error}"
                ) from error
            raise
        finally:
            if handle is not None:
                handle.close()
            authority.close()
            popped = ACTIVE_BUILD_AUTHORITIES.pop()
            require(popped is authority, "build-root authority stack corrupted")


@contextmanager
def compiler_slot(build_dir: Path, wait_seconds: float):
    """Hold one of four build-wide compiler slots across child postflight.

    POSIX advisory locks are released by the kernel if a launcher crashes, so
    stale files cannot wedge a later build.  Acquisition is non-blocking and
    polled only until the explicit deadline.
    """
    require(isinstance(wait_seconds, (int, float))
            and not isinstance(wait_seconds, bool) and wait_seconds > 0,
            "compiler semaphore wait must be positive and bounded")
    authority = active_build_authority()
    slot_directory = authority.build_root / "byte-identity/locks/compiler-slots"
    expected_slots = {
        f"slot-{index}.lock" for index in range(MAX_COMPILER_PROCESSES)
    }
    require(set(authority.list_names(slot_directory)) == expected_slots,
            "compiler semaphore namespace differs from configure inventory")
    deadline = time.monotonic() + wait_seconds
    while True:
        for index in range(MAX_COMPILER_PROCESSES):
            handle = authority.open_lock(slot_directory / f"slot-{index}.lock")
            platform_lock = PlatformFileLock(handle)
            try:
                platform_lock.acquire(exclusive=True, nonblocking=True)
            except BackendLockBusy:
                handle.close()
                continue
            except BaseException:
                handle.close()
                raise
            try:
                authority.revalidate_locks()
                yield index
            finally:
                try:
                    platform_lock.release()
                finally:
                    handle.close()
            return
        remaining = deadline - time.monotonic()
        require(remaining > 0,
                "build-wide max-4 compiler semaphore wait timed out")
        time.sleep(min(COMPILER_SLOT_POLL_SECONDS, remaining))


def acquire_build_lock(path: Path, owner: str) -> None:
    authority = active_build_authority()
    handle = authority.open_lock(path)
    platform_lock = PlatformFileLock(handle)
    try:
        platform_lock.acquire(exclusive=True, nonblocking=True)
    except BackendLockBusy as error:
        handle.close()
        raise ByteIdentityError(f"another byte-identity compile owns {owner}") from error
    try:
        authority.revalidate_locks()
    except BaseException:
        platform_lock.release()
        handle.close()
        raise
    ACTIVE_LOCKS.append((platform_lock, handle))


def validate_runtime_bin(state: dict, build_dir: Path) -> Path:
    authority = active_build_authority()
    validate_toolchain_snapshot(state, build_dir)
    directory = runtime_bin_path(build_dir)
    toolchain_cache = authority.snapshot_validation_cache.get(
        "toolchain:" + str(toolchain_snapshot_path(build_dir))
    )
    require(toolchain_cache is not None,
            "strict runtime bin lacks its held toolchain authority")
    runtime_cache = toolchain_cache.get("runtime_bin")
    if runtime_cache is not None:
        require(
            runtime_cache["path"] == str(directory)
            and runtime_cache["toolchain_fingerprint"]
            == state["toolchain_fingerprint"],
            "held strict runtime bin identity differs",
        )
        runtime_cache["holder"].revalidate()
        require(set(authority.list_names(directory))
                == set(runtime_cache["targets"]),
                "held strict runtime bin membership changed")
        for name, target_value in runtime_cache["targets"].items():
            entry = directory / name
            target = Path(target_value)
            metadata = authority.lstat(entry)
            require(
                metadata is not None and stat.S_ISLNK(metadata.st_mode)
                and authority.readlink(entry) == str(target)
                and authority.stable_regular_file_identity(target)
                == tuple(runtime_cache["identities"][name]),
                f"held strict runtime executable changed: {name}",
            )
        runtime_cache["holder"].revalidate()
        return directory
    try:
        names = authority.list_names(directory)
    except (FileNotFoundError, ByteIdentityError) as error:
        raise ByteIdentityError("strict runtime bin is absent or redirected") from error
    expected = {item["name"]: item for item in state["runtime_executables"]}
    require(set(names) == set(expected),
            "strict runtime bin entry set differs")
    for name, runtime in expected.items():
        entry = directory / name
        target = runtime_target_path(build_dir, runtime)
        metadata = authority.lstat(entry)
        require(metadata is not None and stat.S_ISLNK(metadata.st_mode)
                and authority.readlink(entry) == str(target)
                and stat.S_ISREG(target.stat(follow_symlinks=False).st_mode)
                and bool(target.stat(follow_symlinks=False).st_mode & 0o111)
                and sha256_file(target) == runtime["sha256"],
                f"strict runtime executable differs: {name}")
    runtime_holder = HeldRuntimeExecutables(
        authority.retain_directories([directory]),
        [
            runtime_target_path(build_dir, runtime)
            for runtime in expected.values()
            if is_system_direct_runtime(runtime)
        ],
    )
    runtime_holder.revalidate()
    toolchain_cache["runtime_bin"] = {
        "path": str(directory),
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "targets": {
            name: str(runtime_target_path(build_dir, runtime))
            for name, runtime in expected.items()
        },
        "identities": {
            name: list(authority.stable_regular_file_identity(
                runtime_target_path(build_dir, runtime)
            ))
            for name, runtime in expected.items()
        },
        "holder": runtime_holder,
    }
    return directory


def validate_runtime_executable_for_recovery(
    state: dict, build_dir: Path, name: str,
) -> Path:
    """Authenticate one runtime seat without trusting unrelated poisoned leaves."""
    require_posix_toolchain_backend(state, "Wine runtime recovery")
    authority = active_build_authority()
    validate_runtime_bin(state, build_dir)
    root = toolchain_snapshot_path(build_dir)
    cached = authority.snapshot_validation_cache.get("toolchain:" + str(root))
    require(cached is not None
            and cached["descriptor"].get("toolchain_fingerprint")
            == state["toolchain_fingerprint"],
            "Wine runtime recovery lacks the held toolchain snapshot")
    cached["holder"].revalidate()
    matches = [
        item for item in state["runtime_executables"]
        if item["name"] == name
    ]
    require(len(matches) == 1,
            f"Wine runtime recovery executable is undeclared: {name}")
    runtime = matches[0]
    target = runtime_target_path(build_dir, runtime)
    entry = runtime_bin_path(build_dir) / name
    metadata = authority.lstat(entry)
    runtime_cache = cached.get("runtime_bin")
    require(
        isinstance(runtime_cache, dict)
        and metadata is not None and stat.S_ISLNK(metadata.st_mode)
        and authority.readlink(entry) == str(target)
        and authority.stable_regular_file_identity(target)
        == tuple(runtime_cache["identities"][name]),
        f"Wine runtime recovery executable differs: {name}",
    )
    return entry


def _validated_snapshot_records(root: Path, pin: dict) -> list[dict]:
    authority = active_build_authority()
    for cached in authority.snapshot_validation_cache.values():
        trees = cached.get("trees")
        if not isinstance(trees, dict) or str(root) not in trees:
            continue
        snapshot = trees[str(root)]
        require(exact_json_equal(_tree_pin(snapshot), pin),
                f"held input snapshot pin differs: {root}")
        cached["holder"].revalidate()
        return snapshot["records"]
    snapshot = canonical_tree_snapshot(root, hash_files=True)
    require(exact_json_equal(_tree_pin(snapshot), pin),
            f"sealed input snapshot differs: {root}")
    return snapshot["records"]


def snapshot_run_prefix(
    prefix: Path, run_root: Path, *, z_root: Path | None = None,
    expected_records: list[dict] | None = None,
) -> dict:
    """Hash a run-private prefix, allowing only its two internal drive links."""
    authority = active_build_authority()
    prefix_parts = authority.parts(prefix)
    run_parts = authority.parts(run_root)
    expected_z_parts = authority.parts(
        lexical_absolute_path(z_root if z_root is not None else run_root)
    )
    records = []

    def walk(directory: Path, relative: PurePosixPath, depth: int) -> None:
        require(depth <= 32, "run-private Wine prefix is too deep")
        names = authority.list_names(directory)
        folded = [name.casefold() for name in names]
        require(len(folded) == len(set(folded)),
                "run-private Wine prefix has a casefold collision")
        for name in names:
            child = directory / name
            child_relative = relative / name
            metadata = authority.lstat(child)
            require(metadata is not None,
                    f"run-private Wine prefix entry vanished: {child}")
            mode = stat.S_IMODE(metadata.st_mode)
            if stat.S_ISDIR(metadata.st_mode):
                records.append({
                    "path": child_relative.as_posix(),
                    "type": "directory", "mode": mode,
                })
                walk(child, child_relative, depth + 1)
            elif stat.S_ISREG(metadata.st_mode):
                data = authority.read_bytes(child)
                require(metadata.st_nlink == 1,
                        f"run-private Wine prefix file is hardlinked: {child}")
                records.append({
                    "path": child_relative.as_posix(),
                    "type": "file", "mode": mode, "size": len(data),
                    "sha256": sha256_bytes(data),
                })
            elif stat.S_ISLNK(metadata.st_mode):
                require(
                    child_relative.as_posix() in ("dosdevices/c:", "dosdevices/z:"),
                    f"run-private Wine prefix has an undeclared symlink: {child}",
                )
                target = authority.readlink(child)
                require(target and not Path(target).is_absolute(),
                        f"run-private Wine drive mapping is not relative: {child}")
                lexical_target = lexical_absolute_path(child.parent / target)
                target_parts = authority.parts(lexical_target, allow_root=True)
                if child.name == "c:":
                    require(
                        target_parts[:len(run_parts)] == run_parts
                        and target_parts[:len(prefix_parts)] == prefix_parts,
                        f"run-private Wine C mapping escapes its execution: {child}",
                    )
                else:
                    require(
                        target_parts == expected_z_parts,
                        f"run-private Wine Z mapping differs from its held projection: {child}",
                    )
                records.append({
                    "path": child_relative.as_posix(),
                    "type": "symlink", "mode": mode, "target": target,
                })
            else:
                raise ByteIdentityError(
                    f"run-private Wine prefix contains an unsupported entry: {child}"
                )
            require(len(records) <= 20000,
                    "run-private Wine prefix is too large")

    root_metadata = authority.lstat(prefix)
    require(root_metadata is not None and stat.S_ISDIR(root_metadata.st_mode),
            "run-private Wine prefix is absent")
    records.append({
        "path": ".", "type": "directory",
        "mode": stat.S_IMODE(root_metadata.st_mode),
    })
    walk(prefix, PurePosixPath(), 0)
    if expected_records is not None:
        key = lambda item: (item["path"].casefold(), item["path"])
        require(
            sorted(records, key=key) == sorted(expected_records, key=key),
            "run-private Wine prefix differs from authenticated inputs",
        )
    return {
        "entry_count": len(records),
        "content_sha256": sha256_bytes(json.dumps(
            records, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")),
    }


def expected_initial_run_prefix_records(
    state: dict, prefix: Path, run_root: Path, *, z_root: Path,
    dosdevices_mode: int,
) -> list[dict]:
    """Derive the fresh prefix universe without using destination bytes."""
    authority = active_build_authority()
    records = {
        ".": {"path": ".", "type": "directory", "mode": 0o700},
    }

    def add_directory(relative: str, mode: int = 0o700) -> None:
        parts = PurePosixPath(relative).parts
        for depth in range(1, len(parts) + 1):
            current = PurePosixPath(*parts[:depth]).as_posix()
            prior = records.get(current)
            require(prior is None or prior["type"] == "directory",
                    f"run-private prefix path conflicts: {current}")
            records.setdefault(current, {
                "path": current, "type": "directory", "mode": 0o700,
            })
        records[relative]["mode"] = mode

    for relative in state["transport"]["prefix_directories"]:
        add_directory(PurePosixPath(relative).as_posix())
    add_directory("dosdevices", dosdevices_mode)
    for item in state["transport"]["prefix_template_files"]:
        cache = authority.snapshot_validation_cache.get(
            "toolchain:" + str(toolchain_snapshot_path(Path(state["build_dir"])))
        )
        require(isinstance(cache, dict),
                "fresh prefix lacks held toolchain authority")
        template_root = toolchain_snapshot_path(
            Path(state["build_dir"])
        ) / "prefix-template"
        template = cache["trees"].get(str(template_root))
        require(isinstance(template, dict),
                "fresh prefix template records are absent")
        matches = [
            record for record in template["records"]
            if record.get("path") == item["name"]
        ]
        require(len(matches) == 1
                and matches[0].get("type") == "file"
                and matches[0].get("sha256") == item["sha256"],
                f"fresh prefix template differs: {item['name']}")
        records[item["name"]] = {
            "path": item["name"], "type": "file", "mode": 0o644,
            "size": matches[0]["size"], "sha256": item["sha256"],
        }
    dosdevices = prefix / "dosdevices"
    targets = {
        "dosdevices/c:": "../drive_c",
        "dosdevices/z:": os.path.relpath(z_root, dosdevices),
    }
    for relative, target in targets.items():
        link = prefix.joinpath(*PurePosixPath(relative).parts)
        metadata = authority.lstat(link)
        require(metadata is not None and stat.S_ISLNK(metadata.st_mode)
                and authority.readlink(link) == target,
                f"fresh prefix drive mapping differs: {relative}")
        records[relative] = {
            "path": relative, "type": "symlink",
            "mode": stat.S_IMODE(metadata.st_mode), "target": target,
        }
    require(
        lexical_absolute_path(dosdevices / targets["dosdevices/c:"])
        == prefix / "drive_c"
        and lexical_absolute_path(dosdevices / targets["dosdevices/z:"])
        == lexical_absolute_path(z_root)
        and lexical_absolute_path(prefix).is_relative_to(
            lexical_absolute_path(run_root)
        ),
        "fresh prefix drive targets escape their private authority",
    )
    return list(records.values())


def virtual_run_prefix_owner(run: dict) -> Path:
    projection = run.get("projection")
    if (isinstance(projection, dict)
            and run.get("prefix") == projection.get("prefix")):
        return Path(projection["root"])
    return Path(run["run"])


WINE_REGISTRY_KEY_HEADER_RE = re.compile(rb"^(\[.*\]) \d+$")
WINE_PREFIX_REGISTRY_LEAVES = {"system.reg", "user.reg", "userdef.reg"}
# Wine registers its own bundled fonts (marlett/symbol) under the absolute
# unix path of the LOADED bundle's share/wine/fonts directory.  The held
# snapshot seat differs from the pinned host bundle location, so that prefix
# is transport, not identity: the bundle content is separately hash-pinned.
WINE_REGISTRY_BUNDLE_FONT_RE = re.compile(
    rb'="\\\\\?\?\\\\unix\\\\.*\\\\share\\\\wine\\\\fonts\\\\([^"]+)"$'
)


def wine_registry_normalized_sha256(data: bytes) -> str:
    """Hash registry content modulo Wine's per-boot key timestamps.

    wineserver rewrites the prefix registry on every producer shutdown: key
    header epochs and `#time=` lines move even when every value is unchanged
    (the font subsystem re-touches its keys each boot).  Values, key names,
    ordering, and everything else remain byte-authoritative, except the
    loaded-bundle font directory prefix, which is collapsed to a token.
    """
    normalized = []
    for line in data.split(b"\n"):
        if line.startswith(b"#time="):
            continue
        match = WINE_REGISTRY_KEY_HEADER_RE.match(line)
        if match is not None:
            normalized.append(match.group(1))
            continue
        line = WINE_REGISTRY_BUNDLE_FONT_RE.sub(
            rb'="<WINEDATADIR>\\fonts\\\1"', line
        )
        normalized.append(line)
    return sha256_bytes(b"\n".join(normalized))


def shared_prefix_metadata_identity(prefix: Path) -> list[dict]:
    """Capture the exact prefix namespace with content-pinned files.

    Wine's benign churn (registry rewrite inodes/mtimes, directory mtimes on
    atomic renames) is excluded; in exchange every regular file's CONTENT is
    pinned - byte-exact, or timestamp-normalized for the three registry
    leaves wineserver rewrites on every shutdown.
    """
    authority = active_build_authority()
    result = []
    # The identity covers the full wineboot-initialized placeholder tree.
    max_entries = 8192
    max_depth = 24

    def walk(
        directory: Path, relative: PurePosixPath, depth: int,
    ) -> None:
        require(depth <= max_depth,
                "shared Wine prefix exceeds its maximum depth")
        names = authority.list_names(directory)
        folded = [name.casefold() for name in names]
        require(len(folded) == len(set(folded)),
                "shared Wine prefix contains a casefold collision")
        for name in names:
            child = directory / name
            child_relative = relative / name
            metadata = authority.lstat(child)
            require(metadata is not None,
                    f"shared Wine prefix entry vanished: {child}")
            value = {
                "path": child_relative.as_posix(),
                "mode": stat.S_IMODE(metadata.st_mode),
            }
            if stat.S_ISDIR(metadata.st_mode):
                value["type"] = "directory"
                result.append(value)
                require(len(result) <= max_entries,
                        "shared Wine prefix exceeds its entry bound")
                walk(child, child_relative, depth + 1)
            elif stat.S_ISREG(metadata.st_mode):
                value["type"] = "file"
                require(metadata.st_nlink == 1,
                        f"shared Wine prefix file is hardlinked: {child}")
                data = authority.read_bytes(
                    child, max_bytes=MAX_AUDIT_FILE_BYTES
                )
                if (depth == 0
                        and name in WINE_PREFIX_REGISTRY_LEAVES):
                    value["registry_normalized_sha256"] = (
                        wine_registry_normalized_sha256(data)
                    )
                else:
                    value["size"] = len(data)
                    value["content_sha256"] = sha256_bytes(data)
                result.append(value)
            elif stat.S_ISLNK(metadata.st_mode):
                value["type"] = "symlink"
                value["target"] = authority.readlink(child)
                result.append(value)
            else:
                raise ByteIdentityError(
                    f"shared Wine prefix has unsupported entry: {child}"
                )
            require(len(result) <= max_entries,
                    "shared Wine prefix exceeds its entry bound")

    metadata = authority.lstat(prefix)
    require(metadata is not None and stat.S_ISDIR(metadata.st_mode),
            "shared Wine prefix root is absent")
    result.append({
        "path": ".", "type": "directory",
        "mode": stat.S_IMODE(metadata.st_mode),
    })
    walk(prefix, PurePosixPath(), 0)
    return sorted(result, key=lambda item: (item["path"].casefold(), item["path"]))


def initialize_wine_prefix_with_wineboot(
    state: dict, build_dir: Path, prefix: Path, scratch_home: Path,
) -> None:
    """Let wineboot create the placeholder tree once, then drain it.

    Wine's WOW64 loader resolves 32-bit builtin DLLs through the prefix's
    system32/syswow64 placeholder files, so a minimally seeded prefix cannot
    run the i386 toolchain at all.  The seeded registry omits
    `.update-timestamp`, which makes wineboot perform its one-shot
    placeholder-creating update at prefix initialization; the update is
    bounded and fully drained before the identity baseline is captured.
    """
    authority = active_build_authority()
    authority.mkdirs(scratch_home)
    wine = validate_runtime_executable_for_recovery(state, build_dir, "wine")
    environment = {
        "PATH": str(runtime_bin_path(build_dir)),
        "HOME": str(scratch_home),
        "TEMP": str(scratch_home), "TMP": str(scratch_home),
        "TMPDIR": str(scratch_home),
        "WINEPREFIX": str(prefix),
        "LANG": "C", "LC_ALL": "C", "WINEDEBUG": "-all",
    }
    timeout = max(float(state["max_child_seconds"]), 240.0)
    returncode, output, timed_out = run_child(
        [str(wine), "wineboot.exe", "--init"], timeout, environment,
        cwd=scratch_home,
    )
    require(not timed_out, "prefix wineboot initialization timed out")
    require(returncode == 0,
            f"prefix wineboot initialization exited {returncode}: "
            f"{output[-1500:]!r}")
    wineserver = validate_runtime_executable_for_recovery(
        state, build_dir, "wineserver"
    )
    returncode, output, timed_out = run_child(
        [str(wineserver), "-w"], timeout, environment, cwd=scratch_home,
    )
    require(not timed_out and returncode == 0,
            "prefix wineboot drain did not complete")
    # mountmgr auto-maps ambient host volumes during the update; the hermetic
    # prefix keeps exactly its internal c: and projection z: drives.  Later
    # boots do not re-create pruned volume links.
    dosdevices = prefix / "dosdevices"
    for name in authority.list_names(dosdevices):
        if name not in ("c:", "z:"):
            authority.prune_leaf_or_redirect(dosdevices / name)
    require(set(authority.list_names(dosdevices)) == {"c:", "z:"},
            "prefix drive namespace could not be pruned to c:/z:")


def validate_shared_execution_prefix(run: dict) -> None:
    projection = run.get("projection")
    require(isinstance(projection, dict)
            and run.get("prefix") == projection.get("prefix"),
            "producer does not reference the held shared Wine prefix")
    projection["holder"].revalidate()
    observed = shared_prefix_metadata_identity(Path(projection["prefix"]))
    expected = projection["prefix_metadata"]
    if not exact_json_equal(observed, expected):
        expected_by_path = {item["path"]: item for item in expected}
        observed_by_path = {item["path"]: item for item in observed}
        differences = []
        for path in sorted(set(expected_by_path) | set(observed_by_path)):
            before = expected_by_path.get(path)
            after = observed_by_path.get(path)
            if before != after:
                differences.append(f"{path}: {before!r} -> {after!r}")
        raise ByteIdentityError(
            "shared Wine prefix identity changed during producer epoch: "
            + "; ".join(differences[:8])
        )


def expected_wine_server_seat(prefix: Path) -> Path:
    """Derive Wine's unavoidable host server seat from the prefix identity."""
    authority = active_build_authority()
    metadata = authority.lstat(prefix)
    require(metadata is not None and stat.S_ISDIR(metadata.st_mode),
            "run-private Wine prefix has no stable directory identity")
    temporary = Path("/tmp").resolve(strict=True)
    require(temporary.is_dir(), "canonical host temporary directory is absent")
    return temporary / f".wine-{os.getuid()}" / (
        f"server-{metadata.st_dev:x}-{metadata.st_ino:x}"
    )


def snapshot_wine_server_seat(prefix: Path) -> dict:
    """Prove Wine's host-global server seat is absent or lock-only.

    Wine does not honor WINEPREFIX/TMPDIR for this pathname.  We never remove
    the ambient per-user parent or foreign server seats; the exact seat derived
    from the held private prefix may only be absent or retain Wine's zero-byte
    lock file after a bounded ``wineserver -k/-w`` drain.
    """
    seat = expected_wine_server_seat(prefix)
    parent = seat.parent
    try:
        parent_metadata = os.lstat(parent)
    except FileNotFoundError:
        return {"path": str(seat), "state": "absent", "lock": None}
    require(stat.S_ISDIR(parent_metadata.st_mode)
            and parent_metadata.st_uid == os.getuid(),
            "Wine server parent is redirected or has the wrong owner")
    parent_fd = os.open(parent, DIRECTORY_FD_FLAGS)
    try:
        try:
            seat_metadata = os.stat(
                seat.name, dir_fd=parent_fd, follow_symlinks=False
            )
        except FileNotFoundError:
            return {"path": str(seat), "state": "absent", "lock": None}
        require(stat.S_ISDIR(seat_metadata.st_mode)
                and seat_metadata.st_uid == os.getuid(),
                "Wine server seat is redirected or has the wrong owner")
        seat_fd = os.open(seat.name, DIRECTORY_FD_FLAGS, dir_fd=parent_fd)
        try:
            names = os.listdir(seat_fd)
            require(names == ["lock"],
                    "Wine server seat retains a socket or undeclared entry")
            lock_metadata = os.stat(
                "lock", dir_fd=seat_fd, follow_symlinks=False
            )
            require(stat.S_ISREG(lock_metadata.st_mode)
                    and lock_metadata.st_uid == os.getuid()
                    and stat.S_IMODE(lock_metadata.st_mode) == 0o600
                    and lock_metadata.st_size == 0,
                    "Wine server seat lock identity differs")
            return {
                "path": str(seat), "state": "lock_only",
                "lock": {"mode": 0o600, "size": 0},
            }
        finally:
            os.close(seat_fd)
    finally:
        os.close(parent_fd)


def validate_wine_server_seat_record(
    value: object, expected_path: str, context: str,
) -> dict:
    require(isinstance(value, dict), f"{context} is not an object")
    exact_audit_keys(value, {"path", "state", "lock"}, context)
    require(value.get("path") == expected_path
            and value.get("state") in {"absent", "lock_only"},
            f"{context} identity differs")
    if value["state"] == "absent":
        require(value.get("lock") is None,
                f"{context} absent seat has lock evidence")
    else:
        require(value.get("lock") == {"mode": 0o600, "size": 0},
                f"{context} lock-only evidence differs")
    return value


def seal_virtual_z_directories(
    z_root: Path, writable_directories: list[Path]
) -> None:
    """Make the fake drive readonly except exact compiler output/temp seats."""
    authority = active_build_authority()
    directories = []

    def walk(directory: Path) -> None:
        directories.append(directory)
        for name in authority.list_names(directory):
            child = directory / name
            metadata = authority.lstat(child)
            require(metadata is not None,
                    f"virtual-Z entry vanished while sealing: {child}")
            if stat.S_ISDIR(metadata.st_mode):
                walk(child)
            else:
                require(
                    stat.S_ISREG(metadata.st_mode)
                    and metadata.st_nlink == 1
                    and not (stat.S_IMODE(metadata.st_mode) & 0o222),
                    f"virtual-Z input is writable, linked, or non-regular: {child}",
                )

    walk(z_root)
    for directory in reversed(directories):
        authority.chmod_directory(directory, 0o500)
    writable_parts = set()
    for directory in writable_directories:
        parts = authority.parts(directory)
        require(authority.parts(z_root) == parts[:len(authority.parts(z_root))],
                f"virtual-Z writable directory escapes the fake drive: {directory}")
        writable_parts.add(parts)
        authority.chmod_directory(directory, 0o700)
    require(writable_parts,
            "virtual-Z compiler run has no declared writable directory")


def _projection_immutable_records(
    snapshot: dict, build_relative: PurePosixPath,
) -> list[dict]:
    """Exclude only the exact mutable logical build subtree from a Z scan."""
    prefix = build_relative.as_posix()
    require(prefix not in ("", ".") and not prefix.startswith("../"),
            "execution projection build-root identity is invalid")
    return [
        record for record in snapshot["records"]
        if record["path"] != prefix
        and not record["path"].startswith(prefix + "/")
    ]


def _projection_immutable_metadata_records(
    snapshot: dict, build_relative: PurePosixPath,
) -> list[dict]:
    """Filter metadata by the identical declared mutable-subtree boundary."""
    prefix = build_relative.as_posix()
    require(prefix not in ("", ".") and not prefix.startswith("../")
            and isinstance(snapshot.get("metadata_records"), list),
            "execution projection metadata identity is invalid")
    return [
        record for record in snapshot["metadata_records"]
        if record["path"] != prefix
        and not record["path"].startswith(prefix + "/")
    ]


def _projection_writable_membership(directory: Path) -> list[tuple[str, str]]:
    snapshot = canonical_tree_snapshot(
        directory, hash_files=False, max_entries=20000, max_depth=32
    )
    return sorted(
        (record["path"], record["type"])
        for record in snapshot["records"]
    )


def expected_projection_writable_membership(
    build_seat: Path, *, directories: list[Path], files: list[Path],
) -> list[tuple[str, str]]:
    """Derive the exact staged mutable topology before a producer starts."""
    expected = {(".", "directory")}

    def relative(path: Path) -> tuple[str, ...]:
        path = lexical_absolute_path(path)
        try:
            value = path.relative_to(build_seat)
        except ValueError as error:
            raise ByteIdentityError(
                f"staged writable path escapes the execution seat: {path}"
            ) from error
        return value.parts

    for directory in directories:
        parts = relative(directory)
        for depth in range(1, len(parts) + 1):
            expected.add((PurePosixPath(*parts[:depth]).as_posix(), "directory"))
    for file in files:
        parts = relative(file)
        require(parts, "staged writable input cannot replace the build seat")
        for depth in range(1, len(parts)):
            expected.add((PurePosixPath(*parts[:depth]).as_posix(), "directory"))
        expected.add((PurePosixPath(*parts).as_posix(), "file"))
    return sorted(expected)


def producer_support_role_for_run(run_role: str) -> str | None:
    if run_role == "resource":
        return "resource"
    if run_role == "archive":
        return "archive"
    if run_role in {"release-link", "analysis-link"}:
        return "link"
    return None


def expected_producer_support_audit(state: dict, role: str) -> dict:
    require(role in PRODUCER_SUPPORT_ROLES,
            f"producer support role is invalid: {role}")
    files = [{
        "path": item["absolute_path"], "sha256": item["sha256"],
    } for item in state["producer_support_files"] if role in item["roles"]]
    require(files and files == sorted(files, key=lambda item: item["path"]),
            f"producer support closure is empty or unordered: {role}")
    return {"role": role, "files": files}


def validate_producer_support_audit(
    state: dict, role: str, value: object, context: str,
) -> dict:
    require(isinstance(value, dict), f"{context} is not an object")
    exact_audit_keys(value, {"role", "files"}, context)
    files = value.get("files")
    require(isinstance(files, list), f"{context}.files is not an array")
    for index, item in enumerate(files):
        require(isinstance(item, dict),
                f"{context}.files[{index}] is not an object")
        exact_audit_keys(
            item, {"path", "sha256"}, f"{context}.files[{index}]"
        )
    require(exact_json_equal(
                value, expected_producer_support_audit(state, role)),
            f"{context} differs from the manifest role closure")
    return value


def bind_producer_support_to_projection(
    state: dict, role: str, z_root: Path,
    immutable_by_path: dict[str, dict],
) -> dict:
    """Authenticate every role-specific dynamic child/data leaf prelaunch."""
    authority = active_build_authority()
    audit = expected_producer_support_audit(state, role)
    for item in audit["files"]:
        logical = lexical_absolute_path(Path(item["path"]))
        physical = absolute_snapshot_seat(z_root, logical)
        relative = PurePosixPath(*logical.parts[1:]).as_posix()
        record = immutable_by_path.get(relative)
        metadata = authority.lstat(physical)
        require(
            record is not None and record.get("type") == "file"
            and record.get("sha256") == item["sha256"]
            and metadata is not None and stat.S_ISREG(metadata.st_mode)
            and metadata.st_nlink == 1
            and not (stat.S_IMODE(metadata.st_mode) & 0o222)
            and stat.S_IMODE(metadata.st_mode) == record.get("mode")
            and sha256_file(physical) == item["sha256"],
            f"producer support closure leaf differs for {role}: {logical}",
        )
    return audit


def validate_projected_immutable_file_identity(
    projection: dict, logical: Path, expected_sha256: str, context: str,
    *, executable: bool,
) -> Path:
    """O(1) child-cut proof for a file hashed in the initial Z scan."""
    logical = lexical_absolute_path(logical)
    relative = PurePosixPath(*logical.parts[1:]).as_posix()
    semantic = projection["immutable_by_path"].get(relative)
    identity = projection["immutable_metadata_by_path"].get(relative)
    path = absolute_snapshot_seat(Path(projection["z"]), logical)
    metadata = active_build_authority().lstat(path)
    require(
        semantic is not None and semantic.get("type") == "file"
        and semantic.get("sha256") == expected_sha256
        and identity is not None and identity.get("type") == "file"
        and metadata is not None and stat.S_ISREG(metadata.st_mode)
        and metadata.st_nlink == identity.get("nlink") == 1
        and metadata.st_dev == identity.get("dev")
        and metadata.st_ino == identity.get("ino")
        and stat.S_IMODE(metadata.st_mode) == identity.get("mode")
        and metadata.st_size == identity.get("size")
        and metadata.st_mtime_ns == identity.get("mtime_ns")
        and metadata.st_ctime_ns == identity.get("ctime_ns")
        and not (stat.S_IMODE(metadata.st_mode) & 0o222)
        and (not executable or bool(metadata.st_mode & 0o111)),
        f"{context} changed immediately before launch: {logical}",
    )
    return path


def _projection_merge_identity(record: dict) -> dict:
    """Return the exact immutable identity admitted at one logical Z path."""
    require(record.get("type") in {"directory", "file"},
            "execution projection input contains a non-regular leaf")
    keys = (
        ("type", "mode", "executable")
        if record.get("type") == "directory"
        else ("type", "mode", "executable", "size", "sha256")
    )
    expected = {key: record.get(key) for key in keys}
    require(
        type(expected["mode"]) is int
        and type(expected["executable"]) is bool
        and (
            expected["type"] == "directory"
            or (
                type(expected["size"]) is int
                and isinstance(expected["sha256"], str)
                and SHA256_RE.fullmatch(expected["sha256"]) is not None
            )
        ),
        "execution projection input record is malformed",
    )
    return expected


def merged_execution_projection_records(
    sources: list[tuple[Path, list[dict]]], build_relative: PurePosixPath,
) -> list[dict]:
    """Merge overlapping snapshots once, refusing any identity conflict."""
    mutable = build_relative.as_posix()
    merged: dict[str, dict] = {}
    folded_paths: dict[str, str] = {}
    for source_root, records in sources:
        require(isinstance(source_root, Path) and isinstance(records, list),
                "execution projection merge source is malformed")
        for record in records:
            relative = record.get("path")
            require(isinstance(relative, str) and relative,
                    "execution projection input path is malformed")
            if relative == ".":
                continue
            pure = PurePosixPath(relative)
            require(
                pure.as_posix() == relative
                and not pure.is_absolute() and ".." not in pure.parts
                and all(part not in ("", ".", "..") for part in pure.parts),
                "execution projection input path is unsafe",
            )
            folded = relative.casefold()
            prior_spelling = folded_paths.get(folded)
            require(prior_spelling is None or prior_spelling == relative,
                    f"execution projection has a casefold collision: {relative}")
            folded_paths[folded] = relative
            require(
                relative != mutable
                and not relative.startswith(mutable + "/"),
                "immutable execution input overlaps the writable build branch",
            )
            identity = _projection_merge_identity(record)
            previous = merged.get(relative)
            if previous is not None:
                require(
                    exact_json_equal(previous["identity"], identity),
                    f"execution projection input snapshots conflict: {relative}",
                )
                continue
            merged[relative] = {
                "path": relative,
                "identity": identity,
                "source_root": source_root,
            }
    for relative, item in merged.items():
        parts = PurePosixPath(relative).parts
        for depth in range(1, len(parts)):
            ancestor = PurePosixPath(*parts[:depth]).as_posix()
            prior = merged.get(ancestor)
            require(
                prior is None or prior["identity"]["type"] == "directory",
                f"execution projection file shadows a descendant: {relative}",
            )
        # The ancestor walk above already visits this file for every possible
        # descendant and rejects it as a non-directory prefix.  Do not repeat
        # that proof with an O(N^2) all-path descendant search.
    return [merged[path] for path in sorted(
        merged, key=lambda value: (
            len(PurePosixPath(value).parts),
            value.casefold(), value,
        )
    )]


def apply_source_overlay_to_execution_projection(
    state: dict, build_dir: Path, merged: list[dict],
) -> tuple[list[dict], dict | None]:
    """Replace/add effective source leaves before the projection's first seal.

    The renderer consumes the held clean command snapshot, never the mutable
    checkout and never authoring artifacts.  Existing source leaves are
    replaced in-memory before the one physical install; generated-only leaves
    require exact prior absence and an existing authenticated parent.
    """
    overlay = state["source_overlay"]
    if not overlay["enabled"]:
        return merged, None
    authority = active_build_authority()
    command_z = command_snapshot_path(build_dir) / "z"
    source_root = lexical_absolute_path(Path(state["source_dir"]))
    actual_by_path = {
        item["logical_path"]: item for item in overlay["actual_records"]
    }
    clean_inputs = {}
    merged_by_path = {item["path"]: item for item in merged}
    require(len(merged_by_path) == len(merged),
            "source overlay projection inputs contain duplicate paths")
    for output in overlay["outputs"]:
        relative = output["logical_path"]
        logical = source_root.joinpath(*PurePosixPath(relative).parts)
        projection_relative = PurePosixPath(*logical.parts[1:]).as_posix()
        clean = output["clean"]
        seat = absolute_snapshot_seat(command_z, logical)
        item = merged_by_path.get(projection_relative)
        if clean["state"] == "absent":
            require(item is None and authority.lstat(seat) is None,
                    f"generated-only source entered clean command inputs: {relative}")
            clean_inputs[relative] = b""
            continue
        require(item is not None and item["identity"]["type"] == "file",
                f"clean overlay source is outside command inputs: {relative}")
        data = authority.read_bytes(seat, max_bytes=64 * 1024 * 1024)
        actual = actual_by_path[relative]
        require(
            len(data) == actual["clean_size"]
            and sha256_bytes(data) == actual["clean_sha256"],
            f"held clean overlay source differs: {relative}",
        )
        clean_inputs[relative] = data

    evidence = []
    rendered = render_source_overlay_outputs(
        overlay, clean_inputs, evidence_out=evidence
    )
    require(exact_json_equal(evidence, overlay["anchor_evidence"]),
            "held source overlay anchor resolution differs from planning")
    for output in overlay["outputs"]:
        relative = output["logical_path"]
        logical = source_root.joinpath(*PurePosixPath(relative).parts)
        projection_relative = PurePosixPath(*logical.parts[1:]).as_posix()
        data = rendered[relative]
        actual = overlay["effective_by_path"][relative]
        require(
            len(data) == actual["size"]
            and sha256_bytes(data) == actual["sha256"],
            f"held effective source overlay differs: {relative}",
        )
        existing = merged_by_path.get(projection_relative)
        if existing is None:
            parent = PurePosixPath(projection_relative).parent.as_posix()
            parent_item = merged_by_path.get(parent)
            require(parent_item is not None
                    and parent_item["identity"]["type"] == "directory",
                    f"generated source overlay parent is not authenticated: {relative}")
            existing = {
                "path": projection_relative,
                "identity": {
                    "type": "file", "mode": 0o444, "executable": False,
                    "size": len(data), "sha256": sha256_bytes(data),
                },
                "source_root": None,
                "payload": data,
            }
            merged_by_path[projection_relative] = existing
        else:
            require(existing["identity"]["type"] == "file",
                    f"source overlay output shadows a directory: {relative}")
            existing = {
                **existing,
                "identity": {
                    **existing["identity"],
                    "size": len(data), "sha256": sha256_bytes(data),
                },
                "payload": data,
            }
            merged_by_path[projection_relative] = existing

    folded = {}
    for path, item in merged_by_path.items():
        prior = folded.get(path.casefold())
        require(prior is None or prior == path,
                f"effective source overlay has a casefold collision: {path}")
        folded[path.casefold()] = path
        parts = PurePosixPath(path).parts
        for depth in range(1, len(parts)):
            ancestor = PurePosixPath(*parts[:depth]).as_posix()
            ancestor_item = merged_by_path.get(ancestor)
            require(ancestor_item is None
                    or ancestor_item["identity"]["type"] == "directory",
                    f"effective source overlay has a file ancestor: {path}")
    effective_merged = [merged_by_path[path] for path in sorted(
        merged_by_path, key=lambda value: (
            len(PurePosixPath(value).parts), value.casefold(), value,
        )
    )]
    records = [
        {
            **actual_by_path[item["logical_path"]],
            "operation_ids": [
                operation["id"] for operation in item["operations"]
            ],
        }
        for item in overlay["outputs"]
    ]
    receipt = {
        "schema": 1,
        "status": "TYPED_SOURCE_OVERLAY_MATERIALIZED",
        "manifest_sha256": state["manifest_sha256"],
        "renderer": SOURCE_OVERLAY_RENDERER,
        "policy_sha256": overlay["policy_sha256"],
        "command_snapshot_sha256": sha256_file(
            command_snapshot_path(build_dir) / "snapshot.json"
        ),
        "actual_records_sha256": overlay["actual_records_sha256"],
        "anchor_evidence_sha256": overlay["anchor_evidence_sha256"],
        "physical_output_count": len(records),
        "records": records,
        "anchor_evidence": evidence,
    }
    return effective_merged, receipt


def copy_merged_execution_projection(
    destination: Path, merged: list[dict],
) -> None:
    """Install every unique merged directory/file exactly once."""
    authority = active_build_authority()
    authority.mkdirs(destination)
    for item in merged:
        relative = item["path"]
        identity = item["identity"]
        target = destination.joinpath(*PurePosixPath(relative).parts)
        if identity["type"] == "directory":
            authority.mkdirs(target)
            continue
        payload = item.get("payload")
        if payload is None:
            source_root = item.get("source_root")
            require(isinstance(source_root, Path),
                    f"execution projection input has no source: {relative}")
            source = source_root.joinpath(*PurePosixPath(relative).parts)
            require(isinstance(source, Path),
                    f"execution projection input has no source: {relative}")
            data = authority.read_bytes(source)
        else:
            require(isinstance(payload, bytes),
                    f"execution projection payload is invalid: {relative}")
            data = payload
            source = Path("<typed-source-overlay>") / relative
        require(
            len(data) == identity["size"]
            and sha256_bytes(data) == identity["sha256"],
            f"execution projection merged input changed: {source}",
        )
        authority.atomic_write(target, data, mode=identity["mode"])


def expected_execution_projection_immutable_identity(
    merged: list[dict], build_relative: PurePosixPath,
) -> list[dict]:
    """Derive the semantic post-seal identity from authenticated inputs."""
    expected = {
        ".": {
            "path": ".", "type": "directory",
            "mode": 0o500, "executable": True,
        },
    }
    for item in merged:
        identity = item["identity"]
        relative = item["path"]
        if identity["type"] == "directory":
            value = {
                "path": relative, "type": "directory",
                "mode": 0o500, "executable": True,
            }
        else:
            value = {
                "path": relative, "type": "file",
                "mode": identity["mode"],
                "executable": identity["executable"],
                "size": identity["size"], "sha256": identity["sha256"],
            }
        expected[relative] = value

    # Creating the one mutable build seat may introduce ancestors which are
    # not themselves present in either authenticated input snapshot.  Those
    # ancestors are an exact consequence of the pinned logical build root and
    # are sealed alongside every input directory.
    parts = build_relative.parts
    for depth in range(1, len(parts)):
        relative = PurePosixPath(*parts[:depth]).as_posix()
        previous = expected.get(relative)
        require(
            previous is None or previous["type"] == "directory",
            "execution projection build branch has a non-directory ancestor",
        )
        expected.setdefault(relative, {
            "path": relative, "type": "directory",
            "mode": 0o500, "executable": True,
        })
    return sorted(
        expected.values(),
        key=lambda item: (item["path"].casefold(), item["path"]),
    )


def observed_execution_projection_immutable_identity(
    records: list[dict],
) -> list[dict]:
    """Project a cold Z scan onto the fields authenticated before copying."""
    result = []
    for record in records:
        value = {
            "path": record["path"], "type": record["type"],
            "mode": record["mode"], "executable": record["executable"],
        }
        if record["type"] == "file":
            value.update({
                "size": record["size"], "sha256": record["sha256"],
            })
        result.append(value)
    return sorted(
        result, key=lambda item: (item["path"].casefold(), item["path"])
    )


EXECUTION_TRANSACTION_PHASES = frozenset({
    "projection-reserved", "projection-ready", "child-may-have-started",
    "root-removing", "root-removed",
    "controller-removing", "controller-removed",
})


def execution_recovery_policy_from_manifest(manifest: object) -> dict:
    """Strictly parse only the immutable policy needed to drain old Wine.

    This deliberately does not enumerate or hash translation units, source
    trees, installed CMake/Python, compiler inputs, or retail state.  Recovery
    therefore survives ordinary source edits while still executing only the
    manifest-pinned wineserver and its preserved snapshot closure.
    """
    require(isinstance(manifest, dict),
            "execution recovery manifest root is not an object")
    exact_keys(manifest, {
        "schema", "phase", "toolchain", "target_policies",
        "translation_units", "archives", "images", "execution_backends",
        "terminal_producers", "source_overlay", "diagnostic_policy",
    }, "execution recovery manifest")
    require(manifest.get("schema") == SCHEMA_VERSION
            and manifest.get("phase") == PHASE,
            "execution recovery manifest identity differs")
    backend = validate_execution_backends(manifest.get("execution_backends"))
    require(backend["id"] == POSIX_WINE_BACKEND,
            "execution recovery is implemented only for POSIX/Wine")
    toolchain = manifest.get("toolchain")
    profile, _legacy = select_toolchain_backend_profile(
        toolchain,
        explicit_registry=(
            isinstance(toolchain, dict) and "backend_profiles" in toolchain
        ),
        execution_backend=backend,
    )
    timeout = require_exact_int(
        toolchain.get("max_child_seconds"),
        "execution recovery child timeout", minimum=1, maximum=900,
    )
    runtimes = profile.get("runtime_executables")
    require(isinstance(runtimes, list) and runtimes,
            "execution recovery runtime list is empty")
    normalized_runtimes = []
    names = set()
    for index, item in enumerate(runtimes):
        context = f"execution recovery runtime[{index}]"
        require(isinstance(item, dict), f"{context} is not an object")
        exact_keys(item, {"name", "sha256"}, context)
        name = item.get("name")
        require(isinstance(name, str) and TARGET_RE.fullmatch(name) is not None
                and name not in names,
                f"{context}.name is invalid or duplicated")
        names.add(name)
        normalized_runtimes.append({
            "name": name,
            "sha256": require_sha(item.get("sha256"), f"{context}.sha256"),
        })
    require({"wine", "winepath", "wineserver"} <= names,
            "execution recovery Wine runtime is incomplete")

    closure = profile.get("runtime_closure")
    require(isinstance(closure, dict),
            "execution recovery Wine closure is not an object")
    exact_audit_keys(closure, {
        "schema", "membership_roots", "loaded_files", "host_identity",
        "system_imports", "resolution_policy",
    }, "execution recovery Wine closure")
    require(
        closure.get("schema") == "wine_runtime_closure_v1"
        and closure.get("resolution_policy")
        == "casefold_unique_first_match_v1",
        "execution recovery Wine closure policy differs",
    )
    loaded = closure.get("loaded_files")
    require(isinstance(loaded, list) and loaded,
            "execution recovery loaded-image closure is empty")
    normalized_loaded = []
    loaded_roles = set()
    for index, item in enumerate(loaded):
        context = f"execution recovery loaded file[{index}]"
        require(isinstance(item, dict), f"{context} is not an object")
        exact_audit_keys(item, {"role", "path", "sha256"}, context)
        role = item.get("role")
        path = item.get("path")
        require(isinstance(role, str) and TARGET_RE.fullmatch(role) is not None
                and role not in loaded_roles
                and isinstance(path, str)
                and (
                    MANIFEST_HOST_PATH_RE.fullmatch(path) is not None
                    or Path(path).is_absolute()
                ),
                f"{context} role/path is invalid or duplicated")
        loaded_roles.add(role)
        normalized_loaded.append({
            "role": role, "path": path,
            "sha256": require_sha(item.get("sha256"), f"{context}.sha256"),
        })

    transport = profile.get("transport")
    require(isinstance(transport, dict),
            "execution recovery transport is not an object")
    exact_audit_keys(transport, {
        "schema", "copy_policy", "runtime_snapshot_policy",
        "prefix_template_files", "prefix_directories", "dosdevices",
        "server_shutdown", "msvc_environment",
    }, "execution recovery transport")
    require(
        transport.get("schema") == "wine_virtual_z_v1"
        and transport.get("server_shutdown")
        == "prefix_scoped_kill_wait_bounded_v1",
        "execution recovery Wine shutdown policy differs",
    )
    require(exact_json_equal(
                profile.get("child_environment"), CHILD_ENVIRONMENT_POLICY
            ), "execution recovery child environment policy differs")
    return {
        "schema": 1,
        "backend": backend,
        "transport_schema": profile["transport_schema"],
        "server_shutdown": transport["server_shutdown"],
        "max_child_seconds": timeout,
        "runtime_executables": normalized_runtimes,
        "loaded_files": normalized_loaded,
        "child_environment": CHILD_ENVIRONMENT_POLICY,
    }


def execution_recovery_policy_sha256(manifest: object) -> str:
    return sha256_bytes(canonical_json_bytes(
        execution_recovery_policy_from_manifest(manifest)
    ))


def resident_execution_transaction_binding(state: dict) -> dict | None:
    """Return the live resident/session authority for durable cleanup."""
    ledger = active_resident_receipt_ledger()
    if ledger is None:
        return None
    authority = active_build_authority()
    session = state.get("outer_session")
    marker_exists = authority.lstat(hard_mode_marker_path(authority.build_root))
    if marker_exists is not None:
        require(isinstance(session, dict)
                and session.get("nonce") == ledger.nonce,
                "resident transaction outer-session binding differs")
    controller_sha = (
        session.get("controller_descriptor_sha256")
        if isinstance(session, dict) else None
    )
    if controller_sha is None:
        # Native unit fixtures may exercise a resident ledger without an outer
        # marker. Production hard mode takes the strict branch above.
        controller_sha = "0" * 64
    require(SHA256_RE.fullmatch(controller_sha) is not None,
            "resident transaction controller binding is invalid")
    return {
        "session_nonce": ledger.nonce,
        "controller_descriptor_sha256": controller_sha,
        "manifest_sha256": state["manifest_sha256"],
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "framework_tool_sha256": state["framework_tool_sha256"],
        "backend_tool_sha256": state["backend_tool_sha256"],
        "recovery_policy_sha256": execution_recovery_policy_sha256(
            state["manifest"]
        ),
    }


def update_execution_transaction_marker(
    projection: dict, phase: str,
) -> None:
    """Stamp one closed ownership state before allocating/launching children."""
    binding = projection.get("transaction_binding")
    if binding is None:
        return
    require(phase in EXECUTION_TRANSACTION_PHASES,
            "execution transaction phase is invalid")
    authority = active_build_authority()
    path = execution_projection_recovery_path(authority.build_root)
    root = Path(projection["root"])
    nonce = binding["session_nonce"]
    require(root == authority.build_root / (
                "byte-identity/execution-projections/session-" + nonce
            ), "execution transaction root is not nonce-derived")
    descriptor_sha = projection.get("descriptor_sha256")
    prefix_snapshot = projection.get("prefix_snapshot")
    prefix_metadata = projection.get("prefix_metadata")
    prefix_server_seat_path = projection.get("prefix_server_seat_path")
    require(descriptor_sha is None
            or SHA256_RE.fullmatch(descriptor_sha) is not None,
            "execution transaction descriptor binding is invalid")
    document = {
        "schema": 2,
        "status": "EXECUTION_TRANSACTION_ACTIVE",
        **binding,
        "toolchain_snapshot_sha256": projection.get(
            "toolchain_snapshot_sha256"
        ),
        "phase": phase,
        "projection_root": str(root),
        "projection_descriptor_sha256": descriptor_sha,
        "prefix": str(projection["prefix"]),
        "prefix_snapshot": prefix_snapshot,
        "prefix_metadata": prefix_metadata,
        "prefix_server_seat_path": prefix_server_seat_path,
        "native_reccmp_prefix": projection.get("native_reccmp_prefix"),
        "native_reccmp_prefix_server_seat_path": projection.get(
            "native_reccmp_prefix_server_seat_path"
        ),
        "z": str(projection["z"]),
    }
    raw = atomic_json(path, document)
    require(authority.read_bytes(path) == raw,
            "execution transaction marker changed after publication")
    projection["recovery_journal"] = path


def validate_live_execution_transaction_marker(projection: dict) -> None:
    """Bind an in-memory held projection to its prepublished marker."""
    authority = active_build_authority()
    binding = projection.get("transaction_binding")
    marker = execution_projection_recovery_path(authority.build_root)
    if binding is None:
        require(authority.lstat(marker) is None,
                "diagnostic projection encountered a resident marker")
        return
    document = strict_json_loads(authority.read_bytes(marker))
    require(
        isinstance(document, dict)
        and document.get("schema") == 2
        and document.get("status") == "EXECUTION_TRANSACTION_ACTIVE"
        and document.get("phase") in {
            "projection-ready", "child-may-have-started",
        }
        and all(document.get(key) == value for key, value in binding.items())
        and document.get("toolchain_snapshot_sha256")
        == projection["toolchain_snapshot_sha256"]
        and document.get("projection_root") == str(projection["root"])
        and document.get("projection_descriptor_sha256")
        == projection["descriptor_sha256"]
        and document.get("prefix") == str(projection["prefix"])
        and exact_json_equal(
            document.get("prefix_snapshot"), projection["prefix_snapshot"]
        )
        and exact_json_equal(
            document.get("prefix_metadata"), projection["prefix_metadata"]
        )
        and document.get("prefix_server_seat_path")
        == projection["prefix_server_seat_path"]
        and document.get("native_reccmp_prefix")
        == projection.get("native_reccmp_prefix")
        and document.get("native_reccmp_prefix_server_seat_path")
        == projection.get("native_reccmp_prefix_server_seat_path")
        and document.get("z") == str(projection["z"]),
        "live execution transaction marker differs from held authority",
    )
    require(
        (document["phase"] == "child-may-have-started")
        == (projection.get("marker_child_started") is True),
        "live execution transaction phase is not monotonic",
    )


def _darwin_process_environment(process_id: int) -> bytes | None:
    """Read one process's argv/environment without an ambient ps executable."""
    libc = ctypes.CDLL(None, use_errno=True)
    sysctl = libc.sysctl
    sysctl.argtypes = [
        ctypes.POINTER(ctypes.c_int), ctypes.c_uint,
        ctypes.c_void_p, ctypes.POINTER(ctypes.c_size_t),
        ctypes.c_void_p, ctypes.c_size_t,
    ]
    sysctl.restype = ctypes.c_int
    argmax = ctypes.c_int()
    size = ctypes.c_size_t(ctypes.sizeof(argmax))
    mib = (ctypes.c_int * 2)(1, 8)  # CTL_KERN, KERN_ARGMAX
    if sysctl(mib, 2, ctypes.byref(argmax), ctypes.byref(size), None, 0) != 0:
        raise ByteIdentityError("cannot query Darwin process argument bound")
    require(0 < argmax.value <= 16 * 1024 * 1024,
            "Darwin process argument bound is invalid")
    buffer = ctypes.create_string_buffer(argmax.value)
    size = ctypes.c_size_t(argmax.value)
    mib = (ctypes.c_int * 3)(1, 49, process_id)  # KERN_PROCARGS2
    if sysctl(mib, 3, buffer, ctypes.byref(size), None, 0) != 0:
        error = ctypes.get_errno()
        if error in (1, 3, 22):  # EPERM, ESRCH, EINVAL
            return None
        raise ByteIdentityError(
            f"cannot inspect Darwin process {process_id}: errno {error}"
        )
    return bytes(buffer.raw[:size.value])


def _transaction_process_ids() -> list[int]:
    if sys.platform == "darwin":
        libproc = ctypes.CDLL("/usr/lib/libproc.dylib", use_errno=True)
        list_all = libproc.proc_listallpids
        list_all.argtypes = [ctypes.c_void_p, ctypes.c_int]
        list_all.restype = ctypes.c_int
        count = list_all(None, 0)
        require(0 < count <= 1_000_000,
                "Darwin process universe bound is invalid")
        values = (ctypes.c_int * (count + 64))()
        used = list_all(values, ctypes.sizeof(values))
        require(used >= 0, "cannot enumerate Darwin processes")
        return sorted({value for value in values[:used] if value > 1})
    if sys.platform.startswith("linux"):
        try:
            return sorted(
                int(name) for name in os.listdir("/proc") if name.isdigit()
            )
        except OSError as error:
            raise ByteIdentityError(
                f"cannot enumerate Linux processes: {error}"
            ) from error
    raise ByteIdentityError(
        "POSIX/Wine recovery has no process-environment adapter for this host"
    )


def _transaction_process_environment(process_id: int) -> bytes | None:
    if sys.platform == "darwin":
        return _darwin_process_environment(process_id)
    try:
        return Path(f"/proc/{process_id}/environ").read_bytes()
    except (FileNotFoundError, ProcessLookupError, PermissionError):
        return None
    except OSError as error:
        if error.errno in (1, 2, 3, 13):
            return None
        raise ByteIdentityError(
            f"cannot inspect Linux process {process_id}: {error}"
        ) from error


def execution_transaction_process_groups(root: Path) -> set[int]:
    """Find only groups whose inherited environment names this exact root."""
    prefix = root / "prefix"
    z_root = root / "z"
    tokens = {
        b"WINEPREFIX=" + os.fsencode(prefix),
        b"ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT=" + os.fsencode(z_root),
    }
    groups = set()
    own_group = os.getpgrp()
    for process_id in _transaction_process_ids():
        environment = _transaction_process_environment(process_id)
        if environment is None:
            continue
        fields = set(environment.split(b"\0"))
        # Native reccmp does not export the logical-Z marker, but every one of
        # its paths is nested below this same deterministic transaction root.
        native_prefix = b"WINEPREFIX=" + os.fsencode(root / "native-reccmp/wine-prefix")
        if not (tokens <= fields or native_prefix in fields):
            continue
        try:
            group = os.getpgid(process_id)
        except ProcessLookupError:
            continue
        require(group > 1 and group != own_group,
                "owned recovery process escaped its private process group")
        groups.add(group)
    return groups


def terminate_execution_transaction_processes(root: Path) -> None:
    """Conservatively drain every environment-bound group before deletion."""
    groups = execution_transaction_process_groups(root)
    for group in groups:
        signal_process_group(group, signal.SIGTERM)
    deadline = time.monotonic() + 2
    while any(process_group_exists(group) for group in groups) \
            and time.monotonic() < deadline:
        time.sleep(COMPILER_SLOT_POLL_SECONDS)
    for group in groups:
        if process_group_exists(group):
            signal_process_group(group, signal.SIGKILL)
    deadline = time.monotonic() + 2
    while any(process_group_exists(group) for group in groups) \
            and time.monotonic() < deadline:
        time.sleep(COMPILER_SLOT_POLL_SECONDS)
    require(not any(process_group_exists(group) for group in groups)
            and not execution_transaction_process_groups(root),
            "owned execution transaction process group survived recovery")


def validate_preserved_execution_recovery_runtime(
    policy: dict, marker: dict, build_dir: Path,
) -> tuple[Path, HeldRuntimeExecutables]:
    """Authenticate the preserved runtime without current source-tree scans."""
    authority = active_build_authority()
    toolchain_root = toolchain_snapshot_path(build_dir)
    descriptor_path = toolchain_root / "snapshot.json"
    raw = authority.read_bytes(descriptor_path)
    require(
        sha256_bytes(raw) == marker["toolchain_snapshot_sha256"],
        "recovery toolchain descriptor differs from its transaction marker",
    )
    descriptor = strict_json_loads(raw)
    require(
        isinstance(descriptor, dict)
        and descriptor.get("schema") == 1
        and descriptor.get("status")
        == "IMMUTABLE_VIRTUAL_Z_TOOLCHAIN_SNAPSHOT"
        and descriptor.get("toolchain_fingerprint")
        == marker["toolchain_fingerprint"]
        and descriptor.get("root") == str(toolchain_root)
        and exact_json_equal(
            _tree_pin(canonical_tree_snapshot(
                toolchain_root / "host", hash_files=True,
                include_metadata_records=True,
            )),
            descriptor.get("host"),
        ),
        "preserved recovery toolchain host closure differs",
    )
    runtime = runtime_bin_path(build_dir)
    expected = {
        item["name"]: item["sha256"]
        for item in policy["runtime_executables"]
    }
    require(set(authority.list_names(runtime)) == set(expected),
            "preserved recovery runtime namespace differs")
    targets = []
    wineserver = None
    host_parts = authority.parts(toolchain_root / "host")
    for name, expected_sha in expected.items():
        entry = runtime / name
        metadata = authority.lstat(entry)
        require(metadata is not None and stat.S_ISLNK(metadata.st_mode),
                f"preserved recovery runtime entry differs: {name}")
        target = Path(authority.readlink(entry))
        target_metadata = target.stat(follow_symlinks=False)
        payload = (
            authority.read_bytes(target)
            if active_authority_for_path(target) is authority
            else authority.read_external_bytes(target)
        )
        require(
            target.is_absolute()
            and stat.S_ISREG(target_metadata.st_mode)
            and not target.is_symlink()
            and not (stat.S_IMODE(target_metadata.st_mode) & 0o022)
            and bool(stat.S_IMODE(target_metadata.st_mode) & 0o111)
            and sha256_bytes(payload) == expected_sha,
            f"preserved recovery runtime target differs: {name}",
        )
        if name in {"wine", "winepath", "wineserver"}:
            require(
                active_authority_for_path(target) is authority
                and authority.parts(target)[:len(host_parts)] == host_parts,
                f"preserved Wine runtime escaped its held host tree: {name}",
            )
        targets.append(target)
        if name == "wineserver":
            wineserver = target
    require(isinstance(wineserver, Path),
            "preserved recovery wineserver is absent")
    holder = HeldRuntimeExecutables(
        authority.retain_directories([
            runtime, toolchain_root, toolchain_root / "host",
        ]), targets,
    )
    holder.revalidate()
    return wineserver, holder


def execution_recovery_policy_and_controller(
    marker: dict, build_dir: Path, current_manifest: Path,
) -> tuple[dict, dict | None]:
    """Bind recovery only to the old controller's copied framework freeze."""
    authority = active_build_authority()
    nonce = marker["session_nonce"]
    controller_sha = marker["controller_descriptor_sha256"]
    controller = None
    if controller_sha != "0" * 64:
        controller = load_controller_snapshot_for_cleanup(
            authority, controller_snapshot_path(build_dir, nonce),
            controller_sha,
        )
        copied_manifest_record = controller["framework"]["manifest"]
        copied_manifest = authority.read_bytes(
            Path(copied_manifest_record["snapshot_path"])
        )
        require(
            sha256_bytes(copied_manifest) == marker["manifest_sha256"]
            == copied_manifest_record["sha256"],
            "recovery controller manifest binding differs",
        )
        require(
            controller["framework"]["tool"]["sha256"]
            == marker["framework_tool_sha256"]
            and controller["framework"]["backend"]["sha256"]
            == marker["backend_tool_sha256"],
            "recovery controller framework binding differs",
        )
    else:
        copied_manifest = authority.read_external_bytes(current_manifest)
        require(
            sha256_bytes(copied_manifest) == marker["manifest_sha256"]
            and sha256_file(Path(__file__).resolve())
            == marker["framework_tool_sha256"]
            and sha256_file(Path(execution_backend_module.__file__).resolve())
            == marker["backend_tool_sha256"],
            "diagnostic recovery framework/manifest freeze differs",
        )
    manifest = strict_json_loads(copied_manifest)
    policy = execution_recovery_policy_from_manifest(manifest)
    require(
        sha256_bytes(canonical_json_bytes(policy))
        == marker["recovery_policy_sha256"],
        "execution recovery backend policy differs",
    )
    return policy, controller


def drain_recovered_wine_prefix(
    *, prefix: Path, root: Path, policy: dict, marker: dict,
    build_dir: Path, context: str,
) -> None:
    """Drain one marker-owned prefix through the preserved exact wineserver."""
    authority = active_build_authority()
    metadata = authority.lstat(prefix)
    require(metadata is not None and stat.S_ISDIR(metadata.st_mode),
            f"{context} prefix is absent or redirected")
    expected_seat = str(expected_wine_server_seat(prefix))
    if prefix == root / "prefix":
        require(marker.get("prefix_server_seat_path") == expected_seat,
                f"{context} prefix inode/server-seat binding differs")
    else:
        require(
            marker.get("native_reccmp_prefix") == str(prefix)
            and marker.get("native_reccmp_prefix_server_seat_path")
            == expected_seat,
            f"{context} prefix inode/server-seat binding differs",
        )
    wineserver, holder = validate_preserved_execution_recovery_runtime(
        policy, marker, build_dir
    )
    recovery = root / "recovery"
    temporary = recovery / "tmp"
    home = recovery / "home"
    authority.mkdirs(temporary)
    authority.mkdirs(home)
    environment = {
        "PATH": str(runtime_bin_path(build_dir)),
        "HOME": str(home), "TEMP": str(temporary), "TMP": str(temporary),
        "TMPDIR": str(temporary), "WINEPREFIX": str(prefix),
        **CHILD_ENVIRONMENT_POLICY["fixed"],
    }
    try:
        for option in ("-k", "-w"):
            holder.revalidate()
            returncode, output, timed_out = run_child(
                [str(wineserver), option],
                min(30, policy["max_child_seconds"]), environment, cwd=root,
            )
            no_server = (
                option == "-k" and not timed_out
                and returncode == 1 and output == b""
            )
            if no_server:
                validate_wine_server_seat_record(
                    snapshot_wine_server_seat(prefix), expected_seat,
                    f"{context} no-server seat",
                )
            require(not timed_out and (returncode == 0 or no_server),
                    f"{context} {option} failed with status {returncode}")
        holder.revalidate()
    finally:
        holder.close()
    validate_wine_server_seat_record(
        snapshot_wine_server_seat(prefix), expected_seat,
        f"{context} terminal server seat",
    )


def recover_execution_projection_if_needed(
    build_dir: Path, *, current_manifest: Path,
) -> None:
    """Drain/remove the one marker-owned prior epoch before current planning."""
    authority = active_build_authority()
    journal_path = execution_projection_recovery_path(build_dir)
    metadata = authority.lstat(journal_path)
    if metadata is None:
        return
    require(stat.S_ISREG(metadata.st_mode),
            "execution projection recovery marker is redirected")
    document = strict_json_loads(authority.read_bytes(journal_path))
    require(isinstance(document, dict),
            "execution projection recovery marker is invalid")
    exact_audit_keys(document, {
        "schema", "status", "session_nonce",
        "controller_descriptor_sha256", "manifest_sha256",
        "toolchain_fingerprint", "framework_tool_sha256",
        "backend_tool_sha256", "recovery_policy_sha256",
        "toolchain_snapshot_sha256", "phase", "projection_root",
        "projection_descriptor_sha256", "prefix", "prefix_snapshot",
        "prefix_metadata", "prefix_server_seat_path",
        "native_reccmp_prefix", "native_reccmp_prefix_server_seat_path",
        "z",
    }, "execution transaction marker")
    nonce = document.get("session_nonce")
    require(
        document.get("schema") == 2
        and document.get("status") == "EXECUTION_TRANSACTION_ACTIVE"
        and SHA256_RE.fullmatch(nonce or "") is not None
        and all(SHA256_RE.fullmatch(document.get(key, "")) is not None
                for key in (
                    "controller_descriptor_sha256", "manifest_sha256",
                    "toolchain_fingerprint", "framework_tool_sha256",
                    "backend_tool_sha256", "recovery_policy_sha256",
                    "toolchain_snapshot_sha256",
                ))
        and document.get("phase") in EXECUTION_TRANSACTION_PHASES,
        "execution transaction recovery identity differs",
    )
    root = Path(document["projection_root"])
    require(root == authority.build_root / (
                "byte-identity/execution-projections/session-" + nonce
            ), "execution transaction recovery root differs")
    prefix = Path(document["prefix"])
    z_root = Path(document["z"])
    require(prefix == root / "prefix" and z_root == root / "z",
            "execution transaction recovery layout differs")

    def retire_bound_controller() -> None:
        # The earlier outer-session marker owns the controller, resident plan,
        # and CMake process group. Execution recovery only retracts its nested
        # projection marker; outer recovery runs immediately afterwards.
        if authority.lstat(outer_session_recovery_path(build_dir)) is not None:
            invalidate_build_paths([journal_path])
            authority.assert_absent(journal_path)
            return
        controller_sha = document["controller_descriptor_sha256"]
        if controller_sha != "0" * 64:
            controller_root = controller_snapshot_path(build_dir, nonce)
            controller_metadata = authority.lstat(controller_root)
            phase = document["phase"]
            if controller_metadata is None:
                require(phase in {"controller-removing", "controller-removed"},
                        "journal-bound controller disappeared")
            else:
                require(stat.S_ISDIR(controller_metadata.st_mode),
                        "journal-bound controller is redirected")
                require(phase != "controller-removed",
                        "removed journal-bound controller reappeared")
                if phase != "controller-removing":
                    load_controller_snapshot_for_cleanup(
                        authority, controller_root, controller_sha
                    )
                    document["phase"] = "controller-removing"
                    atomic_json(journal_path, document)
                rollback_exact_private_run(authority, controller_root)
            document["phase"] = "controller-removed"
            atomic_json(journal_path, document)
        invalidate_build_paths([journal_path])
        authority.assert_absent(journal_path)

    root_metadata = authority.lstat(root)
    if root_metadata is None:
        require(document["phase"] in {
                    "projection-reserved", "root-removing", "root-removed",
                    "controller-removing", "controller-removed",
                }, "owned execution transaction root disappeared")
        retire_bound_controller()
        return
    require(stat.S_ISDIR(root_metadata.st_mode),
            "owned execution transaction root is redirected")
    if document["phase"] == "root-removed":
        raise ByteIdentityError("removed execution transaction root reappeared")

    phase = document["phase"]
    if phase in {"projection-reserved", "projection-ready", "root-removing"}:
        # These monotonic states precede every child launch, or follow an
        # already-proven drain.  Cleanup must remain independent of current
        # source/framework/toolchain state and tolerate partial root removal.
        document["phase"] = "root-removing"
        atomic_json(journal_path, document)
        rollback_exact_private_run(authority, root)
        document["phase"] = "root-removed"
        atomic_json(journal_path, document)
        retire_bound_controller()
        return
    require(phase == "child-may-have-started",
            "execution transaction root survived a controller cleanup phase")

    descriptor = root / "snapshot.json"
    descriptor_metadata = authority.lstat(descriptor)
    if descriptor_metadata is not None:
        require(
            stat.S_ISREG(descriptor_metadata.st_mode)
            and SHA256_RE.fullmatch(
                document.get("projection_descriptor_sha256") or ""
            ) is not None
            and sha256_file(descriptor)
            == document["projection_descriptor_sha256"],
            "execution transaction recovery descriptor differs",
        )
        terminate_execution_transaction_processes(root)
        policy, _controller = execution_recovery_policy_and_controller(
            document, build_dir, current_manifest
        )
        if authority.lstat(prefix) is not None:
            drain_recovered_wine_prefix(
                prefix=prefix, root=root, policy=policy, marker=document,
                build_dir=build_dir, context="recovered shared Wine",
            )
        native_prefix = root / "native-reccmp/wine-prefix"
        if (authority.lstat(native_prefix) is not None
                and document.get("native_reccmp_prefix")
                == str(native_prefix)):
            drain_recovered_wine_prefix(
                prefix=native_prefix, root=root, policy=policy,
                marker=document, build_dir=build_dir,
                context="recovered native reccmp Wine",
            )
    else:
        raise ByteIdentityError(
            "started execution transaction lost its projection descriptor"
        )
    document["phase"] = "root-removing"
    atomic_json(journal_path, document)
    rollback_exact_private_run(authority, root)
    document["phase"] = "root-removed"
    atomic_json(journal_path, document)
    retire_bound_controller()


def materialize_execution_projection(state: dict, build_dir: Path) -> dict:
    """Create one held immutable logical-Z input view per transaction.

    This is the POSIX-Wine adapter for the backend-neutral execution-seat
    lifecycle.  The expensive command/toolchain snapshots are independently
    copied exactly once.  Only the logical build-root branch is writable and
    it is leased by at most one producer invocation at a time.
    """
    require_posix_toolchain_backend(state, "execution projection materialization")
    authority = active_build_authority()
    existing = authority.execution_projection
    if existing is not None:
        require(
            existing.get("removed") is not True
            and existing.get("poisoned") is not True
            and existing["toolchain_snapshot_sha256"]
            == sha256_file(toolchain_snapshot_path(build_dir) / "snapshot.json")
            and existing["command_snapshot_sha256"]
            == sha256_file(command_snapshot_path(build_dir) / "snapshot.json")
            and (
                not state["source_overlay"]["enabled"]
                or existing.get("source_overlay_policy_sha256")
                == state["source_overlay"]["policy_sha256"]
            ),
            "execution projection authority differs",
        )
        existing["holder"].revalidate()
        validate_live_execution_transaction_marker(existing)
        return existing
    recover_execution_projection_if_needed(
        build_dir, current_manifest=Path(state["manifest_path"])
    )

    toolchain_audit = validate_toolchain_snapshot(state, build_dir)
    command_audit = state["command_inventory"]["transport_snapshot"]
    validate_command_snapshot(
        state["command_inventory"]["entries"], build_dir, command_audit,
        state=state, inventory=state["inventory"],
    )
    transaction_binding = resident_execution_transaction_binding(state)
    root = (
        authority.build_root / "byte-identity/execution-projections"
        / (
            "session-" + transaction_binding["session_nonce"]
            if transaction_binding is not None
            else f"session-{uuid.uuid4().hex}"
        )
    )
    z_root = root / "z"
    prefix = root / "prefix"
    runs_root = root / "runs"
    build_relative = PurePosixPath(*authority.build_root.parts[1:])
    build_seat = z_root.joinpath(*build_relative.parts)
    finalization = execution_projection_finalization_path(build_dir)
    overlay_receipt_path = source_overlay_receipt_path(build_dir)
    created = False
    holder = None
    reservation = {
        "root": root, "z": z_root, "prefix": prefix,
        "state": state, "transaction_binding": transaction_binding,
        "toolchain_snapshot_sha256": sha256_file(
            toolchain_snapshot_path(build_dir) / "snapshot.json"
        ),
        "descriptor_sha256": None, "prefix_snapshot": None,
        "prefix_metadata": None, "prefix_server_seat_path": None,
        "native_reccmp_prefix": None,
        "native_reccmp_prefix_server_seat_path": None,
    }
    try:
        invalidate_build_paths([finalization, overlay_receipt_path])
        update_execution_transaction_marker(
            reservation, "projection-reserved"
        )
        authority.mkdir_exclusive(root)
        created = True
        authority.mkdirs(z_root)
        authority.mkdirs(runs_root)
        sources = []
        source_record_count = 0
        for source_root, pin in (
            (toolchain_snapshot_path(build_dir) / "z", toolchain_audit["z"]),
            (command_snapshot_path(build_dir) / "z", command_audit["z"]),
        ):
            records = _validated_snapshot_records(source_root, pin)
            sources.append((source_root, records))
            source_record_count += sum(
                record.get("path") != "." for record in records
            )
        merged = merged_execution_projection_records(
            sources, build_relative
        )
        merged, overlay_receipt = apply_source_overlay_to_execution_projection(
            state, build_dir, merged
        )
        if overlay_receipt is not None:
            source_record_count += len(state["source_overlay"]["outputs"])
        absent_relatives = {
            PurePosixPath(*path.parts[1:]).as_posix()
            for path in required_absent_toolchain_paths(state)
        }
        require(not absent_relatives.intersection(
                    item["path"] for item in merged
                ), "required-absent toolchain file entered projection inputs")
        copy_merged_execution_projection(z_root, merged)
        authority.mkdirs(build_seat)
        seal_virtual_z_directories(z_root, [build_seat])
        require_exact_build_namespace(
            authority, build_seat, {},
            "new execution projection writable build branch",
        )
        authority.mkdirs(prefix)
        prefix_template = toolchain_snapshot_path(build_dir) / "prefix-template"
        for item in state["transport"]["prefix_template_files"]:
            data = authority.read_bytes(prefix_template / item["name"])
            require(sha256_bytes(data) == item["sha256"],
                    f"sealed prefix template differs: {item['name']}")
            if item["name"] == ".update-timestamp":
                # wineboot owns the stamp: omitting it triggers the one-shot
                # placeholder-creating update at prefix initialization.
                continue
            # wineserver rewrites the registry with 0644 on every shutdown;
            # seeding with the same mode keeps the prefix identity stable.
            authority.atomic_write(prefix / item["name"], data, mode=0o644)
        for relative in state["transport"]["prefix_directories"]:
            authority.mkdirs(prefix.joinpath(*PurePosixPath(relative).parts))
        dosdevices = prefix / "dosdevices"
        authority.mkdirs(dosdevices)
        authority.atomic_symlink(dosdevices / "c:", Path("../drive_c"))
        z_target = Path(os.path.relpath(z_root, dosdevices))
        require(not z_target.is_absolute()
                and lexical_absolute_path(dosdevices / z_target) == z_root,
                "shared Wine Z mapping differs from its projection")
        authority.atomic_symlink(dosdevices / "z:", z_target)
        initialize_wine_prefix_with_wineboot(
            state, build_dir, prefix, root / "wineboot-home"
        )
        prefix_snapshot = snapshot_run_prefix(prefix, root, z_root=z_root)
        prefix_metadata = shared_prefix_metadata_identity(prefix)
        prefix_server_seat = snapshot_wine_server_seat(prefix)
        validate_wine_server_seat_record(
            prefix_server_seat, str(expected_wine_server_seat(prefix)),
            "new shared Wine server seat",
        )
        observed = canonical_tree_snapshot(
            z_root, hash_files=True, max_entries=20000, max_depth=32,
            include_metadata_records=True,
        )
        immutable_records = _projection_immutable_records(
            observed, build_relative
        )
        immutable_metadata_records = _projection_immutable_metadata_records(
            observed, build_relative
        )
        require(
            exact_json_equal(
                observed_execution_projection_immutable_identity(
                    immutable_records
                ),
                expected_execution_projection_immutable_identity(
                    merged, build_relative
                ),
            ),
            "transaction execution projection differs from authenticated inputs",
        )
        immutable_by_path = {
            record["path"]: record for record in immutable_records
        }
        require(not absent_relatives.intersection(immutable_by_path),
                "required-absent toolchain file entered execution projection")
        require(
            len(immutable_by_path) == len(immutable_records),
            "transaction execution projection paths are duplicated",
        )
        metadata_by_path = {
            record["path"]: record
            for record in observed["metadata_records"]
            if record["path"] in immutable_by_path
            and record["type"] == "file"
        }
        immutable_files = {
            path: record for path, record in immutable_by_path.items()
            if record["type"] == "file"
        }
        require(
            set(metadata_by_path) == set(immutable_files)
            and all(
                metadata_by_path[path]["type"] == "file"
                and metadata_by_path[path]["mode"] == record["mode"]
                and metadata_by_path[path]["size"] == record["size"]
                for path, record in immutable_files.items()
            ),
            "transaction execution projection metadata authority differs",
        )
        immutable_sha = sha256_bytes(json.dumps(
            immutable_records, sort_keys=True, separators=(",", ":")
        ).encode("utf-8"))
        overlay_receipt_sha = None
        if overlay_receipt is not None:
            overlay_projection_records = []
            source_root = lexical_absolute_path(Path(state["source_dir"]))
            for output in state["source_overlay"]["outputs"]:
                relative = output["logical_path"]
                logical = source_root.joinpath(*PurePosixPath(relative).parts)
                projection_relative = PurePosixPath(*logical.parts[1:]).as_posix()
                record = immutable_by_path.get(projection_relative)
                actual = state["source_overlay"]["effective_by_path"][relative]
                require(
                    record is not None and record.get("type") == "file"
                    and record.get("sha256") == actual["sha256"]
                    and record.get("size") == actual["size"],
                    f"effective source overlay is absent from projection: {relative}",
                )
                overlay_projection_records.append({
                    "logical_path": relative,
                    "projection_relative_path": projection_relative,
                    "mode": record["mode"], "size": record["size"],
                    "sha256": record["sha256"],
                })
            overlay_receipt.update({
                "execution_projection_root": str(root),
                "execution_projection_immutable_records_sha256": immutable_sha,
                "effective_projection_records_sha256": sha256_bytes(
                    canonical_json_bytes(overlay_projection_records)
                ),
                "effective_projection_records": overlay_projection_records,
            })
            overlay_receipt_bytes = atomic_json(
                overlay_receipt_path, overlay_receipt
            )
            overlay_receipt_sha = sha256_bytes(overlay_receipt_bytes)
        source_overlay_identity = {
            "source_overlay_enabled": overlay_receipt is not None,
            "source_overlay_policy_sha256": (
                state["source_overlay"]["policy_sha256"]
                if overlay_receipt is not None else None
            ),
            "source_overlay_actual_records_sha256": (
                state["source_overlay"]["actual_records_sha256"]
                if overlay_receipt is not None else None
            ),
            "source_overlay_receipt_sha256": overlay_receipt_sha,
            "source_overlay_output_count": (
                len(state["source_overlay"]["outputs"])
                if overlay_receipt is not None else 0
            ),
        }
        descriptor = {
            "schema": 1,
            "status": "TRANSACTION_SCOPED_IMMUTABLE_LOGICAL_Z_PROJECTION",
            "backend": state["execution_backend"]["id"],
            "transport_schema": state["transport"]["schema"],
            "root": str(root),
            "z": str(z_root),
            "writable_build_root": str(build_seat),
            "writable_build_relative": build_relative.as_posix(),
            "toolchain_snapshot_sha256": sha256_file(
                toolchain_snapshot_path(build_dir) / "snapshot.json"
            ),
            "command_snapshot_sha256": sha256_file(
                command_snapshot_path(build_dir) / "snapshot.json"
            ),
            "immutable_entry_count": len(immutable_records),
            "immutable_records_sha256": immutable_sha,
            "source_record_count": source_record_count,
            "unique_record_install_count": len(merged),
            "projection_materialization_count": 1,
            "seat_capacity": 1,
            "prefix_path": str(prefix),
            "prefix_initial_snapshot": prefix_snapshot,
            "prefix_materialization_count": 1,
            **source_overlay_identity,
        }
        descriptor_bytes = atomic_json(root / "snapshot.json", descriptor)
        descriptor_sha = sha256_bytes(descriptor_bytes)
        holder = authority.retain_directories([
            root, z_root, build_seat, prefix, dosdevices, runs_root,
        ])
        require(holder.read_bytes(root / "snapshot.json") == descriptor_bytes,
                "execution projection descriptor changed before hold")
        holder.revalidate()
        result = {
            **descriptor,
            "descriptor": root / "snapshot.json",
            "descriptor_sha256": descriptor_sha,
            "immutable_records": immutable_records,
            "immutable_metadata_records": immutable_metadata_records,
            "immutable_by_path": immutable_by_path,
            "immutable_metadata_by_path": metadata_by_path,
            "prefix": prefix,
            "runs_root": runs_root,
            "prefix_snapshot": prefix_snapshot,
            "prefix_metadata": prefix_metadata,
            "prefix_server_seat_path": str(expected_wine_server_seat(prefix)),
            "prefix_server_seat_initial": prefix_server_seat,
            "prefix_use_count": 0,
            "prefix_quiescent": True,
            "holder": holder,
            "lease": None,
            "lease_count": 0,
            "owned_run": None,
            "native_reccmp_run": None,
            "native_reccmp_prefix": None,
            "native_reccmp_prefix_server_seat_path": None,
            "poisoned": False,
            "finalized": False,
            "removed": False,
            "state": state,
            "transaction_binding": transaction_binding,
            "recovery_journal": reservation.get("recovery_journal"),
            "marker_child_started": False,
            "source_overlay_receipt": overlay_receipt,
            "source_overlay_receipt_path": (
                overlay_receipt_path if overlay_receipt is not None else None
            ),
        }
        update_execution_transaction_marker(result, "projection-ready")
        authority.execution_projection = result
        return result
    except BaseException as original:
        failures = []
        try:
            invalidate_build_paths([overlay_receipt_path])
        except BaseException as error:
            failures.append(f"source overlay receipt: {error}")
        if holder is not None:
            try:
                holder.close()
            except BaseException as error:
                failures.append(f"projection holder: {error}")
        if created:
            try:
                rollback_exact_private_run(authority, root)
            except BaseException as error:
                failures.append(f"projection root: {error}")
        marker = reservation.get("recovery_journal")
        if marker is not None:
            try:
                invalidate_build_paths([Path(marker)])
                authority.assert_absent(Path(marker))
            except BaseException as error:
                failures.append(f"recovery marker: {error}")
        if failures:
            raise ByteIdentityError(
                "source overlay projection rollback failed: "
                + "; ".join(failures)
            ) from original
        raise


def acquire_execution_projection(
    state: dict, build_dir: Path, *, role: str, run_root: Path,
) -> tuple[dict, str]:
    """Lease the one transaction projection without rescanning its base."""
    authority = active_build_authority()
    projection = materialize_execution_projection(state, build_dir)
    require(projection["poisoned"] is False
            and projection["removed"] is False
            and projection["lease"] is None,
            "transaction execution projection is busy or poisoned")
    projection["holder"].revalidate()
    validate_shared_execution_prefix({
        "projection": projection, "prefix": projection["prefix"]
    })
    require(projection.get("prefix_quiescent") is True,
            "shared Wine prefix is not quiescent before lease")
    require_exact_build_namespace(
        authority, Path(projection["writable_build_root"]), {},
        "execution projection writable branch before lease",
    )
    token = uuid.uuid4().hex
    projection["lease"] = {
        "token": token, "role": role, "run_root": str(run_root),
    }
    projection["lease_count"] += 1
    projection["prefix_use_count"] += 1
    return projection, token


def _clear_execution_projection_writable_branch(projection: dict) -> None:
    authority = active_build_authority()
    writable = Path(projection["writable_build_root"])
    authority.chmod_directory(writable, 0o700)
    for name in authority.list_names(writable):
        authority.remove_tree(writable / name)
    require_exact_build_namespace(
        authority, writable, {},
        "execution projection writable branch after cleanup",
        replace_pin=True,
    )


def release_execution_projection(run: dict) -> None:
    """Clear a producer's tiny branch and release its serial execution seat."""
    projection = run.get("projection")
    token = run.get("projection_lease")
    require(isinstance(projection, dict) and isinstance(token, str),
            "producer run has no execution projection lease")
    lease = projection.get("lease")
    require(isinstance(lease, dict) and lease.get("token") == token,
            "producer execution projection lease changed")
    try:
        validate_shared_execution_prefix(run)
        require(projection.get("prefix_quiescent") is True,
                "shared Wine prefix is not quiescent at lease release")
        _clear_execution_projection_writable_branch(projection)
        projection["holder"].revalidate()
    except BaseException:
        projection["poisoned"] = True
        raise
    projection["lease"] = None
    projection["owned_run"] = None
    run["projection_lease_released"] = True


def finalize_execution_projection(authority: BuildRootAuthority) -> None:
    """Terminally rescan, then remove, the exact transaction projection."""
    projection = authority.execution_projection
    if projection is None or projection.get("removed") is True:
        return
    require(projection.get("lease") is None
            and projection.get("poisoned") is False
            and projection.get("prefix_quiescent") is True
            and projection.get("native_reccmp_run") is None,
            "execution projection cannot finalize while leased or poisoned")
    projection["holder"].revalidate()
    # The raw prefix snapshot moves with every wineserver registry rewrite;
    # the normalized content identity is the terminal authority.  The raw
    # terminal snapshot is still recorded in the finalization receipt.
    terminal_prefix = snapshot_run_prefix(
        Path(projection["prefix"]), Path(projection["root"]),
        z_root=Path(projection["z"]),
    )
    require(exact_json_equal(
                shared_prefix_metadata_identity(Path(projection["prefix"])),
                projection["prefix_metadata"],
            ), "shared Wine prefix changed before completion")
    validate_wine_server_seat_record(
        snapshot_wine_server_seat(Path(projection["prefix"])),
        str(expected_wine_server_seat(Path(projection["prefix"]))),
        "terminal shared Wine server seat",
    )
    require_exact_build_namespace(
        authority, Path(projection["writable_build_root"]), {},
        "terminal execution projection writable branch",
        replace_pin=True,
    )
    require_exact_build_namespace(
        authority, Path(projection["runs_root"]), {},
        "terminal execution transaction run namespace",
        replace_pin=True,
    )
    authority.assert_absent(Path(projection["root"]) / "native-reccmp")
    observed = canonical_tree_snapshot(
        Path(projection["z"]), hash_files=True,
        max_entries=20000, max_depth=32,
        include_metadata_records=True,
    )
    immutable = _projection_immutable_records(
        observed, PurePosixPath(projection["writable_build_relative"])
    )
    terminal_paths = {record["path"] for record in immutable}
    for logical in required_absent_toolchain_paths(projection["state"]):
        relative = PurePosixPath(*logical.parts[1:]).as_posix()
        require(relative not in terminal_paths
                and authority.lstat(absolute_snapshot_seat(
                    Path(projection["z"]), logical
                )) is None,
                f"required-absent toolchain file appeared: {logical}")
    immutable_sha = sha256_bytes(json.dumps(
        immutable, sort_keys=True, separators=(",", ":")
    ).encode("utf-8"))
    require(
        len(immutable) == projection["immutable_entry_count"]
        and immutable_sha == projection["immutable_records_sha256"]
        and exact_json_equal(immutable, projection["immutable_records"])
        and exact_json_equal(
            _projection_immutable_metadata_records(
                observed,
                PurePosixPath(projection["writable_build_relative"]),
            ),
            projection["immutable_metadata_records"],
        ),
        "transaction execution projection changed before completion",
    )
    if projection["source_overlay_enabled"]:
        overlay_path = projection.get("source_overlay_receipt_path")
        overlay_receipt = projection.get("source_overlay_receipt")
        require(
            isinstance(overlay_path, Path)
            and isinstance(overlay_receipt, dict)
            and sha256_file(overlay_path)
            == projection["source_overlay_receipt_sha256"]
            and exact_json_equal(
                strict_json_loads(authority.read_bytes(overlay_path)),
                overlay_receipt,
            ),
            "typed source overlay receipt changed before completion",
        )
        terminal_by_path = {record["path"]: record for record in immutable}
        require(
            len(terminal_by_path) == len(immutable)
            and all(
                terminal_by_path.get(item["projection_relative_path"], {}).get(
                    "type"
                ) == "file"
                and terminal_by_path[item["projection_relative_path"]]["sha256"]
                == item["sha256"]
                and terminal_by_path[item["projection_relative_path"]]["size"]
                == item["size"]
                for item in overlay_receipt["effective_projection_records"]
            ),
            "typed source overlay terminal projection records differ",
        )
    projection["holder"].revalidate()
    projection["holder"].close()
    root = Path(projection["root"])
    update_execution_transaction_marker(projection, "root-removing")
    authority.remove_tree(root)
    authority.assert_absent(root)
    update_execution_transaction_marker(projection, "root-removed")
    marker = projection.get("recovery_journal")
    if marker is not None:
        invalidate_build_paths([Path(marker)])
        authority.assert_absent(Path(marker))
    receipt = {
        "schema": 1,
        "status": "EXECUTION_PROJECTION_FINALIZED_AND_REMOVED",
        "backend": projection["backend"],
        "transport_schema": projection["transport_schema"],
        "projection_root": str(root),
        "projection_descriptor_sha256": projection["descriptor_sha256"],
        "toolchain_snapshot_sha256": projection["toolchain_snapshot_sha256"],
        "command_snapshot_sha256": projection["command_snapshot_sha256"],
        "immutable_entry_count": projection["immutable_entry_count"],
        "immutable_records_sha256": projection["immutable_records_sha256"],
        "terminal_immutable_records_sha256": immutable_sha,
        "source_record_count": projection["source_record_count"],
        "unique_record_install_count": projection["unique_record_install_count"],
        "projection_materialization_count": 1,
        "seat_capacity": projection["seat_capacity"],
        "lease_count": projection["lease_count"],
        "prefix_materialization_count": 1,
        "prefix_use_count": projection["prefix_use_count"],
        "prefix_initial_content_sha256": projection["prefix_snapshot"][
            "content_sha256"
        ],
        "prefix_terminal_content_sha256": terminal_prefix["content_sha256"],
        "prefix_server_quiescent": True,
        "writable_build_branch_empty": True,
        "projection_removed": True,
        "source_overlay_enabled": projection["source_overlay_enabled"],
        "source_overlay_policy_sha256": projection[
            "source_overlay_policy_sha256"
        ],
        "source_overlay_actual_records_sha256": projection[
            "source_overlay_actual_records_sha256"
        ],
        "source_overlay_receipt_sha256": projection[
            "source_overlay_receipt_sha256"
        ],
        "source_overlay_output_count": projection[
            "source_overlay_output_count"
        ],
    }
    receipt_path = execution_projection_finalization_path(
        authority.build_root
    )
    atomic_json(receipt_path, receipt)
    require(
        exact_json_equal(
            strict_json_loads(authority.read_bytes(receipt_path)), receipt
        ),
        "execution projection finalization receipt differs after publication",
    )
    projection["finalized"] = True
    projection["removed"] = True
    projection["finalization_receipt"] = receipt_path
    authority.execution_projection_receipt = receipt


def _abort_execution_projection_impl(authority: BuildRootAuthority) -> None:
    """Quiesce and remove the exact held projection without publishing."""
    projection = authority.execution_projection
    receipt_path = execution_projection_finalization_path(
        authority.build_root
    )
    invalidate_build_paths([receipt_path])
    authority.execution_projection_receipt = None
    if projection is None:
        return
    if projection.get("removed") is True:
        return
    overlay_receipt = projection.get("source_overlay_receipt_path")
    if isinstance(overlay_receipt, Path):
        invalidate_build_paths([overlay_receipt])
    native = projection.get("native_reccmp_run")
    if isinstance(native, dict):
        require_run_private_wine_quiescent(native)
        holder = native.get("holder")
        if isinstance(holder, HeldBuildDirectories):
            holder.close()
        native_root = Path(native["run"])
        authority.remove_tree(native_root)
        authority.assert_absent(native_root)
        native["_namespace_removed"] = True
        projection["native_reccmp_run"] = None
    lease = projection.get("lease")
    if lease is not None:
        owned = projection.get("owned_run")
        if isinstance(owned, dict):
            require_run_private_wine_quiescent(owned)
            holder = owned.get("holder")
            if isinstance(holder, HeldBuildDirectories):
                holder.close()
            run_root = Path(owned["run"])
            authority.remove_tree(run_root)
            authority.assert_absent(run_root)
            owned["_namespace_removed"] = True
        _clear_execution_projection_writable_branch(projection)
        projection["lease"] = None
        projection["owned_run"] = None
    require(projection.get("prefix_quiescent") is True,
            "shared Wine prefix quiescence is unproven during abort")
    require_exact_build_namespace(
        authority, Path(projection["runs_root"]), {},
        "aborted execution transaction run namespace",
        replace_pin=True,
    )
    validate_shared_execution_prefix({
        "projection": projection, "prefix": projection["prefix"]
    })
    validate_wine_server_seat_record(
        snapshot_wine_server_seat(Path(projection["prefix"])),
        str(expected_wine_server_seat(Path(projection["prefix"]))),
        "aborted shared Wine server seat",
    )
    projection["holder"].close()
    root = Path(projection["root"])
    update_execution_transaction_marker(projection, "root-removing")
    authority.remove_tree(root)
    authority.assert_absent(root)
    update_execution_transaction_marker(projection, "root-removed")
    marker = projection.get("recovery_journal")
    if marker is not None:
        invalidate_build_paths([Path(marker)])
        authority.assert_absent(Path(marker))
    projection["removed"] = True


def abort_execution_projection(authority: BuildRootAuthority) -> None:
    """Abort one pre-journaled transaction; failures retain its marker."""
    _abort_execution_projection_impl(authority)


def _prepare_virtual_z_run_at_root(
    *, state: dict, build_dir: Path, target: str, source_relative: str,
    role: str, cwd: Path, logical_outputs: list[Path], temporary: Path,
    run: Path,
    generated_inputs: list[Path] | None = None,
    generated_external_inputs: list[tuple[Path, bytes]] | None = None,
) -> dict:
    """Bind one tiny private invocation to the held transaction Z view."""
    require_posix_toolchain_backend(state, "compiler transport preparation")
    authority = active_build_authority()
    require(TARGET_RE.fullmatch(role) is not None,
            f"virtual-Z run role is invalid: {role}")
    prefix = None
    home = run / "home"
    projection = None
    lease_token = None
    holder = None
    recovery = None
    try:
        projection, lease_token = acquire_execution_projection(
            state, build_dir, role=role, run_root=run
        )
        prefix = Path(projection["prefix"])
        z_root = Path(projection["z"])
        build_seat = Path(projection["writable_build_root"])
        recovery = {
            "run": run, "prefix": prefix, "projection": projection,
            "projection_lease": lease_token,
            "_wine_drain_attempted": False,
            "producer_child_started": False,
        }
        projection["owned_run"] = recovery
        authority.mkdirs(home)

        cwd = lexical_absolute_path(cwd)
        temporary = lexical_absolute_path(temporary)
        authority.parts(cwd, allow_root=True)
        authority.parts(temporary)
        physical_cwd = absolute_snapshot_seat(z_root, cwd)
        physical_temporary = absolute_snapshot_seat(z_root, temporary)
        require(
            physical_cwd == build_seat
            or physical_cwd.is_relative_to(build_seat),
            "virtual-Z cwd is outside the writable build branch",
        )
        require(physical_temporary.is_relative_to(build_seat),
                "virtual-Z temporary directory is outside the writable build branch")

        physical_outputs = []
        logical_output_values = []
        for logical in logical_outputs:
            logical = lexical_absolute_path(logical)
            authority.parts(logical)
            physical = absolute_snapshot_seat(z_root, logical)
            require(physical.is_relative_to(build_seat),
                    "virtual-Z output is outside the writable build branch")
            require(authority.lstat(physical) is None,
                    f"virtual-Z output already exists: {logical}")
            physical_outputs.append(physical)
            logical_output_values.append(logical)
        require(
            physical_outputs
            and len(set(map(str, physical_outputs))) == len(physical_outputs),
            "virtual-Z output set is empty or duplicated",
        )

        immutable_by_path = projection["immutable_by_path"]
        support_role = producer_support_role_for_run(role)
        producer_support = (
            bind_producer_support_to_projection(
                state, support_role, z_root, immutable_by_path
            )
            if support_role is not None else None
        )
        compiler_immutable_inputs = (
            compiler_command_immutable_inputs(
                state, build_dir, projection
            )
            if role in {"dependencies", "seed"}
            or role.startswith("donor-")
            else []
        )
        generated_records = []
        seen_generated = set()
        for generated in generated_inputs or []:
            generated = lexical_absolute_path(generated)
            require(str(generated) not in seen_generated,
                    f"virtual-Z generated input is duplicated: {generated}")
            seen_generated.add(str(generated))
            physical = absolute_snapshot_seat(z_root, generated)
            if active_authority_for_path(generated) is authority:
                authority.parts(generated)
                require(physical.is_relative_to(build_seat),
                        "generated build input is outside the writable build branch")
                data = authority.read_bytes(generated)
                authority.atomic_write(physical, data, mode=0o400)
                mode = 0o400
                provenance = "generated_build_input_copy"
            else:
                relative = PurePosixPath(*generated.parts[1:]).as_posix()
                record = immutable_by_path.get(relative)
                metadata = authority.lstat(physical)
                require(
                    record is not None and record["type"] == "file"
                    and metadata is not None
                    and stat.S_ISREG(metadata.st_mode)
                    and metadata.st_nlink == 1
                    and not (stat.S_IMODE(metadata.st_mode) & 0o222),
                    f"held immutable external input is absent: {generated}",
                )
                data = authority.read_bytes(physical)
                mode = stat.S_IMODE(metadata.st_mode)
                require(
                    len(data) == record["size"]
                    and sha256_bytes(data) == record["sha256"]
                    and mode == record["mode"],
                    f"held immutable external input differs: {generated}",
                )
                provenance = "held_projection_input"
            generated_records.append({
                "logical": str(generated), "physical": str(physical),
                "sha256": sha256_bytes(data), "size": len(data), "mode": mode,
                "provenance": provenance,
            })
        for logical, data in generated_external_inputs or []:
            logical = lexical_absolute_path(logical)
            require(str(logical) not in seen_generated,
                    f"virtual-Z external input is duplicated: {logical}")
            seen_generated.add(str(logical))
            require(isinstance(data, bytes) and data,
                    f"virtual-Z external input is empty: {logical}")
            physical = absolute_snapshot_seat(z_root, logical)
            relative = PurePosixPath(*logical.parts[1:]).as_posix()
            record = immutable_by_path.get(relative)
            metadata = authority.lstat(physical)
            require(
                record is not None and record["type"] == "file"
                and metadata is not None and stat.S_ISREG(metadata.st_mode)
                and metadata.st_nlink == 1
                and not (stat.S_IMODE(metadata.st_mode) & 0o222)
                and len(data) == record["size"]
                and sha256_bytes(data) == record["sha256"]
                and authority.read_bytes(physical) == data,
                f"external generated input is not an identical held leaf: {logical}",
            )
            generated_records.append({
                "logical": str(logical), "physical": str(physical),
                "sha256": record["sha256"], "size": record["size"],
                "mode": record["mode"],
                "provenance": "held_projection_input",
            })
        require(
            not ({record["physical"] for record in generated_records}
                 & set(map(str, physical_outputs)))
            and all(
                not Path(record["physical"]).is_relative_to(
                    physical_temporary
                )
                for record in generated_records
            ),
            "generated input aliases an output or temporary namespace",
        )

        dosdevices = prefix / "dosdevices"
        require_exact_build_namespace(
            authority, dosdevices, {"c:": "symlink", "z:": "symlink"},
            "shared Wine drive namespace",
        )

        authority.mkdirs(physical_cwd)
        for physical in physical_outputs:
            authority.mkdirs(physical.parent)
        authority.mkdirs(physical_temporary)
        optional_outputs = []
        object_outputs = [
            path for path in physical_outputs
            if path.suffix.casefold() == ".obj"
        ]
        pdb_outputs = [
            path for path in physical_outputs
            if path.suffix.casefold() == ".pdb"
        ]
        if len(object_outputs) == 1 and len(pdb_outputs) == 1:
            optional_outputs = [
                object_outputs[0].with_suffix(".idb"),
                object_outputs[0].parent / f"{object_outputs[0].name}.sbr",
            ]
        expected_writable_before = expected_projection_writable_membership(
            build_seat,
            directories=[
                physical_cwd, physical_temporary,
                *(path.parent for path in physical_outputs),
            ],
            files=[
                Path(record["physical"])
                for record in generated_records
                if Path(record["physical"]).is_relative_to(build_seat)
            ],
        )
        writable_before = _projection_writable_membership(build_seat)
        require(
            writable_before == expected_writable_before,
            "producer writable branch differs from its staged recipe topology",
        )
        holder = authority.retain_directories([
            run, z_root, build_seat, home, physical_cwd,
            physical_temporary, *(path.parent for path in physical_outputs),
        ])
        holder.revalidate()
        result = {
            "run": run,
            "role": role,
            "z": z_root,
            "prefix": prefix,
            "home": home,
            "cwd": physical_cwd,
            "temporary": physical_temporary,
            "outputs": physical_outputs,
            "logical_outputs": logical_output_values,
            "holder": holder,
            "generated_inputs": generated_records,
            "producer_support": producer_support,
            "compiler_immutable_inputs": compiler_immutable_inputs,
            "writable_before_membership": writable_before,
            "allowed_output_paths": sorted(
                str(path) for path in [*physical_outputs, *optional_outputs]
            ),
            "projection": projection,
            "projection_lease": lease_token,
            "projection_lease_released": False,
            "producer_child_started": False,
            "server_preflight_clear": False,
            "server_postflight_clear": False,
            "toolchain_snapshot_sha256": projection[
                "toolchain_snapshot_sha256"
            ],
            "command_snapshot_sha256": projection[
                "command_snapshot_sha256"
            ],
        }
        result["prefix_snapshot"] = projection["prefix_snapshot"]
        result["shared_prefix"] = True
        projection["owned_run"] = result
        return result
    except BaseException as original:
        cleanup_error = None
        if holder is not None:
            holder.close()
        if projection is not None and lease_token is not None:
            candidate = recovery or {
                "run": run, "prefix": prefix, "projection": projection,
                "projection_lease": lease_token,
            }
            try:
                release_execution_projection(candidate)
            except BaseException as error:
                projection["poisoned"] = True
                cleanup_error = error
        if cleanup_error is not None:
            raise ByteIdentityError(
                "virtual-Z preparation failed and its shared seat could not "
                f"be cleared: {cleanup_error}"
            ) from original
        raise


def prepare_virtual_z_run(
    *, state: dict, build_dir: Path, target: str, source_relative: str,
    role: str, cwd: Path, logical_outputs: list[Path], temporary: Path,
    generated_inputs: list[Path] | None = None,
    generated_external_inputs: list[tuple[Path, bytes]] | None = None,
) -> dict:
    """Create one failure-atomic fake-Z + sealed prefix execution."""
    authority = active_build_authority()
    require(TARGET_RE.fullmatch(role) is not None,
            f"virtual-Z run role is invalid: {role}")
    source_id = hashlib.sha256(source_relative.encode("utf-8")).hexdigest()[:16]
    projection = materialize_execution_projection(state, build_dir)
    runs_root = Path(projection["runs_root"])
    require_exact_build_namespace(
        authority, runs_root, {},
        "execution transaction run namespace before allocation",
        replace_pin=True,
    )
    run = (
        runs_root
        / f"{target}-{source_id}-{role}-{uuid.uuid4().hex}"
    )
    created = False
    try:
        authority.mkdir_exclusive(run)
        created = True
        result = _prepare_virtual_z_run_at_root(
            state=state, build_dir=build_dir, target=target,
            source_relative=source_relative, role=role, cwd=cwd,
            logical_outputs=logical_outputs, temporary=temporary, run=run,
            generated_inputs=generated_inputs,
            generated_external_inputs=generated_external_inputs,
        )
        return result
    except BaseException:
        if created:
            lease = (
                projection.get("lease")
                if isinstance(projection, dict) else None
            )
            if not (
                isinstance(lease, dict)
                and lease.get("run_root") == str(run)
            ):
                rollback_exact_private_run(authority, run)
                require_exact_build_namespace(
                    authority, runs_root, {},
                    "execution transaction run namespace after rollback",
                    replace_pin=True,
                )
        raise


def reject_virtual_z_path_leak(data: bytes, run: dict, context: str) -> None:
    physical_roots = {
        str(run["run"]), str(run["z"]),
        str(run["projection"]["root"]),
    }
    variants = set()
    for physical in physical_roots:
        variants.update({
            physical.encode("utf-8"),
            physical.replace("/", "\\").encode("utf-8"),
            physical.encode("utf-16le"),
            physical.replace("/", "\\").encode("utf-16le"),
        })
    require(not any(value and value in data for value in variants),
            f"{context} embeds a private execution projection path")


def verify_virtual_z_inputs(run: dict, state: dict) -> None:
    """Verify only the tiny mutable seat; the immutable base is terminally scanned."""
    authority = active_build_authority()
    projection = run.get("projection")
    lease = projection.get("lease") if isinstance(projection, dict) else None
    require(
        projection is authority.execution_projection
        and projection.get("poisoned") is False
        and isinstance(lease, dict)
        and lease.get("token") == run.get("projection_lease")
        and Path(projection["z"]) == Path(run["z"]),
        "producer execution projection authority changed",
    )
    projection["holder"].revalidate()
    run["holder"].revalidate()
    # Every pinned wrapper has `#!/usr/bin/env bash`, but the kernel would
    # resolve that absolute ambient `/usr/bin/env` before our strict PATH.
    # Producer argv therefore invokes this exact held bash explicitly; prove
    # its symlink and copied target again after Wine preflight/drain.
    held_runtime_executable_path(
        state, Path(state["build_dir"]), "bash"
    )
    for record in run.get("compiler_immutable_inputs", []):
        validate_projected_immutable_file_identity(
            projection, Path(record["logical"]), record["sha256"],
            "compiler immutable input postflight", executable=False,
        )
    for record in run["generated_inputs"]:
        path = Path(record["physical"])
        metadata = authority.lstat(path)
        data = authority.read_bytes(path)
        require(
            metadata is not None and stat.S_ISREG(metadata.st_mode)
            and metadata.st_nlink == 1
            and stat.S_IMODE(metadata.st_mode) == record["mode"]
            and sha256_bytes(data) == record["sha256"],
            f"run-private generated compiler input changed: {record['logical']}",
        )
    validate_shared_execution_prefix(run)
    require(projection.get("prefix_quiescent") is True,
            "shared Wine prefix is not quiescent after compiler execution")
    require_exact_build_namespace(
        authority, run["home"], {}, "run-private compiler HOME namespace"
    )
    before = set(map(tuple, run["writable_before_membership"]))
    after = set(_projection_writable_membership(
        Path(projection["writable_build_root"])
    ))
    require(before <= after,
            "producer removed a declared generated build input")
    allowed = set(run["allowed_output_paths"])
    additions = after - before
    require(
        all(
            kind == "file"
            and str(
                Path(projection["writable_build_root"]).joinpath(
                    *PurePosixPath(relative).parts
                )
            ) in allowed
            for relative, kind in additions
        ),
        "producer emitted an undeclared writable-branch entry",
    )
    run["input_postflight_clear"] = True


def validate_virtual_z_prelaunch(
    run: dict, state: dict, tool: dict,
) -> None:
    """Prove the exact staged writable topology at the child cut point."""
    authority = active_build_authority()
    projection = run.get("projection")
    lease = projection.get("lease") if isinstance(projection, dict) else None
    require(
        projection is authority.execution_projection
        and projection.get("poisoned") is False
        and isinstance(lease, dict)
        and lease.get("token") == run.get("projection_lease"),
        "producer prelaunch projection authority changed",
    )
    for logical in required_absent_toolchain_paths(state):
        authority.assert_absent(absolute_snapshot_seat(
            Path(projection["z"]), logical
        ))
    projection["holder"].revalidate()
    run["holder"].revalidate()
    # Bypass the wrappers' absolute `/usr/bin/env` shebang and bind execution
    # to the held bash seat at the final post-drain child cut point.
    held_runtime_executable_path(
        state, Path(state["build_dir"]), "bash"
    )
    observed = _projection_writable_membership(
        Path(projection["writable_build_root"])
    )
    require(
        observed == run["writable_before_membership"],
        "producer writable branch changed after staging and before launch",
    )
    present = {
        str(
            Path(projection["writable_build_root"]).joinpath(
                *PurePosixPath(relative).parts
            )
        )
        for relative, kind in observed
        if kind != "directory"
    }
    require(
        not present.intersection(run["allowed_output_paths"]),
        "producer output existed immediately before launch",
    )
    for record in run["generated_inputs"]:
        path = Path(record["physical"])
        metadata = authority.lstat(path)
        data = authority.read_bytes(path)
        require(
            metadata is not None and stat.S_ISREG(metadata.st_mode)
            and metadata.st_nlink == 1
            and stat.S_IMODE(metadata.st_mode) == record["mode"]
            and len(data) == record["size"]
            and sha256_bytes(data) == record["sha256"],
            f"staged producer input changed immediately before launch: "
            f"{record['logical']}",
        )
    run_role = run.get("role")
    support_role = producer_support_role_for_run(run_role)
    supports = [
        *state["compiler_support_files"],
        *([] if support_role is None else [
            item for item in state["producer_support_files"]
            if support_role in item["roles"]
        ]),
    ]
    admitted = [
        {
            "context": f"producer tool {tool['role']}",
            "path": tool["absolute_path"],
            "sha256": projected_tool_sha256(state, tool),
            "executable": True,
        },
        *(
            {
                "context": "compiler support",
                "path": item["absolute_path"],
                "sha256": projected_compiler_support_sha256(state, item),
                "executable": False,
            }
            for item in supports
        ),
    ]
    seen = set()
    for item in admitted:
        logical = str(item["path"])
        if logical in seen:
            continue
        seen.add(logical)
        validate_projected_immutable_file_identity(
            projection, Path(logical), item["sha256"], item["context"],
            executable=item["executable"],
        )
    for record in run.get("compiler_immutable_inputs", []):
        validate_projected_immutable_file_identity(
            projection, Path(record["logical"]), record["sha256"],
            "compiler immutable input", executable=False,
        )
    run["input_preflight_clear"] = True


def strict_child_environment(
    state: dict, build_dir: Path, temporary: Path, *, run: dict | None = None,
) -> dict[str, str]:
    require_posix_toolchain_backend(state, "compiler child environment")
    runtime_bin = validate_runtime_bin(state, build_dir)
    authority = active_build_authority()
    require(run is not None, "compiler child requires a run-private virtual-Z transport")
    home = run["home"]
    wine_prefix = run["prefix"]
    for directory in (home, wine_prefix, run["temporary"]):
        descriptor = authority.open_directory_parts(authority.parts(directory))
        os.close(descriptor)
    environment = {
        "PATH": str(runtime_bin),
        "HOME": str(home),
        # Preserve the logical absolute spelling that the pinned wrapper maps
        # through its run-private z: drive.  The physical counterpart exists in
        # run/z and is held for the whole child/output-consumption boundary.
        "TEMP": str(temporary),
        "TMP": str(temporary),
        "TMPDIR": str(temporary),
        "WINEPREFIX": str(wine_prefix),
        "ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT": str(run["z"]),
        **CHILD_ENVIRONMENT_POLICY["fixed"],
    }
    require(set(environment) == {
        "PATH", "HOME", "TEMP", "TMP", "TMPDIR", "WINEPREFIX",
        "ISLE_BYTE_IDENTITY_VIRTUAL_Z_ROOT", "LANG", "LC_ALL", "WINEDEBUG",
    }, "strict compiler child environment key set differs")
    return environment


def drain_run_private_wineserver(
    run: dict, state: dict, environment: dict[str, str], *, phase: str,
) -> None:
    """Boundedly stop/wait only the current run's private Wine server."""
    require(phase in ("preflight", "postflight"),
            "run-private wineserver drain phase is invalid")
    run["_wine_drain_attempted"] = True
    run["_wine_state"] = state
    run["_wine_environment"] = dict(environment)
    projection = run.get("projection")
    shared = (
        isinstance(projection, dict)
        and run.get("prefix") == projection.get("prefix")
    )
    if shared and phase == "preflight" and projection.get("prefix_quiescent"):
        validate_shared_execution_prefix(run)
        run["server_preflight_clear"] = True
        seat = snapshot_wine_server_seat(run["prefix"])
        run["server_seat_preflight"] = seat
        return
    runtime_names = {item["name"] for item in state["runtime_executables"]}
    if "wineserver" in runtime_names:
        executable = validate_runtime_executable_for_recovery(
            state, Path(state["build_dir"]), "wineserver"
        )
        timeout = min(30.0, float(state["max_child_seconds"]))
        require(timeout > 0, "run-private wineserver timeout is invalid")
        for option in ("-k", "-w"):
            returncode, output, timed_out = run_child(
                [str(executable), option], timeout, environment, cwd=run["cwd"]
            )
            # Wine can return status 1 for ``wineserver -k`` when the private
            # prefix has no lock owner, but the status alone is not proof of
            # quiescence.  Admit that one nonzero shape only with silent output
            # and an immediate independent proof that this prefix's
            # inode-derived server seat is absent or contains only Wine's
            # unlocked lock-file residue.  ``-w`` must still run and succeed
            # afterwards.
            no_server = (
                option == "-k"
                and not timed_out
                and returncode == 1
                and output == b""
            )
            if no_server:
                no_server_seat = snapshot_wine_server_seat(run["prefix"])
                validate_wine_server_seat_record(
                    no_server_seat,
                    str(expected_wine_server_seat(run["prefix"])),
                    f"run-private wineserver {phase} no-server seat",
                )
            require(
                not timed_out and (returncode == 0 or no_server),
                "run-private wineserver "
                f"{phase} {option} failed with status {returncode}: "
                + output.decode("utf-8", errors="replace")[:400],
            )
    run[f"server_{phase}_clear"] = True
    server_seat = snapshot_wine_server_seat(run["prefix"])
    require(
        server_seat["path"]
        == str(expected_wine_server_seat(run["prefix"])),
        "run-private Wine server seat identity changed",
    )
    run[f"server_seat_{phase}"] = server_seat
    if shared:
        validate_shared_execution_prefix(run)
        projection["prefix_quiescent"] = True
    wine_transport = run.get("wine_transport")
    if isinstance(wine_transport, dict):
        require(
            wine_transport.get("server_seat_path") == server_seat["path"],
            "native reccmp Wine server seat differs from its prefix",
        )
        wine_transport[f"server_seat_{phase}"] = server_seat
        wine_transport[f"server_{phase}_clear"] = True
    if phase == "preflight" and not shared:
        # The starting state consumed by VC is the state after a bounded proof
        # that no server owns the fresh prefix.
        run["prefix_snapshot"] = snapshot_run_prefix(
            run["prefix"], run["run"], z_root=run.get("z")
        )


def mark_virtual_z_child_started(run: dict) -> None:
    projection = run.get("projection")
    require(isinstance(projection, dict)
            and projection.get("prefix_quiescent") is True,
            "shared Wine prefix was not quiescent at child start")
    validate_shared_execution_prefix(run)
    if projection.get("marker_child_started") is not True:
        update_execution_transaction_marker(
            projection, "child-may-have-started"
        )
        projection["marker_child_started"] = True
    projection["prefix_quiescent"] = False
    run["producer_child_started"] = True


def require_run_private_wine_quiescent(run: dict) -> dict:
    """Retry a failed postflight drain before relinquishing prefix authority."""
    if run.get("_wine_drain_attempted") is not True:
        require(run.get("producer_child_started") is not True,
                "private producer child started without Wine drain authority")
        return {"path": None, "state": "never_launched", "lock": None}
    prefix = run.get("prefix")
    require(isinstance(prefix, Path),
            "private producer run has no Wine prefix identity")
    if (run.get("_wine_drain_attempted") is True
            and run.get("server_postflight_clear") is not True):
        state = run.get("_wine_state")
        environment = run.get("_wine_environment")
        require(isinstance(state, dict) and isinstance(environment, dict),
                "private producer Wine cleanup has no retry authority")
        drain_run_private_wineserver(
            run, state, environment, phase="postflight"
        )
    require(run.get("_wine_drain_attempted") is not True
            or run.get("server_postflight_clear") is True,
            "private producer Wine postflight drain is unproven")
    seat = snapshot_wine_server_seat(prefix)
    expected = str(expected_wine_server_seat(prefix))
    validate_wine_server_seat_record(
        seat, expected, "private producer cleanup Wine server seat"
    )
    run["server_seat_cleanup"] = seat
    wine_transport = run.get("wine_transport")
    if isinstance(wine_transport, dict):
        require(wine_transport.get("server_seat_path") == expected,
                "native reccmp cleanup Wine server seat differs")
        wine_transport["server_seat_cleanup"] = seat
    return seat


def coff_unpack(format_string: str, data: bytes, offset: int, context: str) -> tuple:
    size = struct.calcsize(format_string)
    require(0 <= offset <= len(data) - size, f"{context} is outside the COFF file")
    return struct.unpack_from(format_string, data, offset)


class CoffObject:
    """Strict reader for the classic i386 COFF emitted by VC4.2."""

    def __init__(self, data: bytes):
        self.data = data
        require(len(data) >= 20, "COFF header is truncated")
        (
            self.machine,
            self.section_count,
            self.timestamp,
            self.symbol_offset,
            self.symbol_count,
            optional_size,
            self.characteristics,
        ) = coff_unpack("<HHIIIHH", data, 0, "COFF header")
        require(self.machine == 0x14C, "only i386 COFF objects are supported")
        require(optional_size == 0, "COFF optional headers are unsupported")
        require(0 < self.section_count < 0x10000, "COFF section count is invalid")
        require(self.symbol_count > 0, "COFF object has no symbol table")
        self.string_offset = self.symbol_offset + self.symbol_count * 18
        string_size, = coff_unpack("<I", data, self.string_offset, "COFF string table")
        require(string_size >= 4 and self.string_offset <= len(data) - string_size,
                "COFF string table is invalid")
        self.string_end = self.string_offset + string_size
        require(self.string_end == len(data), "bytes after the COFF string table are unsupported")

        table_end = 20 + self.section_count * 40
        require(table_end <= len(data), "COFF section table is truncated")
        self.sections = []
        for index in range(self.section_count):
            header_offset = 20 + index * 40
            raw_name = data[header_offset : header_offset + 8]
            name = self._section_name(raw_name)
            (
                _, _, raw_size, raw_offset, relocation_offset, line_offset,
                relocation_count, line_count, characteristics,
            ) = coff_unpack("<IIIIIIHHI", data, header_offset + 8,
                            f"section {index + 1} header")
            if raw_size:
                require(raw_offset >= table_end and raw_offset <= len(data) - raw_size,
                        f"section {index + 1} raw data is invalid")
            else:
                require(raw_offset == 0 or raw_offset >= table_end,
                        f"section {index + 1} empty raw pointer is invalid")
            if relocation_count:
                require(relocation_offset >= table_end
                        and relocation_offset <= len(data) - relocation_count * 10,
                        f"section {index + 1} relocation table is invalid")
            if line_count:
                require(line_offset >= table_end
                        and line_offset <= len(data) - line_count * 6,
                        f"section {index + 1} line table is invalid")
            self.sections.append(
                {
                    "number": index + 1,
                    "header_offset": header_offset,
                    "name": name,
                    "raw_size": raw_size,
                    "raw_offset": raw_offset,
                    "relocation_offset": relocation_offset,
                    "relocation_count": relocation_count,
                    "line_offset": line_offset,
                    "line_count": line_count,
                    "characteristics": characteristics,
                }
            )

        require(self.symbol_offset >= table_end
                and self.symbol_offset <= len(data) - self.symbol_count * 18,
                "COFF symbol table is invalid")
        self.symbols = {}
        symbol_index = 0
        while symbol_index < self.symbol_count:
            offset = self.symbol_offset + symbol_index * 18
            name = self._symbol_name(data[offset : offset + 8])
            value, section, symbol_type, storage, auxiliary_count = coff_unpack(
                "<IhHBB", data, offset + 8, f"symbol {symbol_index}"
            )
            require(symbol_index + auxiliary_count < self.symbol_count,
                    f"symbol {symbol_index} auxiliary records are truncated")
            self.symbols[symbol_index] = {
                "index": symbol_index,
                "name": name,
                "value": value,
                "section": section,
                "type": symbol_type,
                "storage": storage,
                "aux_count": auxiliary_count,
            }
            symbol_index += 1 + auxiliary_count

    def _string(self, relative: int, context: str) -> str:
        require(4 <= relative < self.string_end - self.string_offset,
                f"{context} string offset is invalid")
        absolute = self.string_offset + relative
        end = self.data.find(b"\0", absolute, self.string_end)
        require(end >= 0, f"{context} is not NUL-terminated")
        return self.data[absolute:end].decode("ascii", "strict")

    def _section_name(self, raw: bytes) -> str:
        if raw.startswith(b"/"):
            digits = raw[1:].rstrip(b"\0")
            require(digits.isdigit(), "long COFF section name is invalid")
            return self._string(int(digits), "section name")
        return raw.rstrip(b"\0").decode("ascii", "strict")

    def _symbol_name(self, raw: bytes) -> str:
        if raw[:4] == b"\0\0\0\0":
            relative, = coff_unpack("<I", raw, 4, "long symbol name")
            return self._string(relative, "symbol name")
        return raw.rstrip(b"\0").decode("ascii", "strict")

    def function_section(self, mangled: str) -> dict:
        matches = [
            symbol
            for symbol in self.symbols.values()
            if symbol["name"] == mangled
            and symbol["section"] > 0
            and symbol["value"] == 0
            and symbol["type"] == 0x20
            and symbol["storage"] in (2, 3)
        ]
        require(len(matches) == 1,
                f"expected one definition of {mangled!r}, found {len(matches)}")
        section = self.sections[matches[0]["section"] - 1]
        require(section["name"].startswith(".text"),
                f"{mangled!r} is not in a text section")
        require(section["characteristics"] & 0x1000,
                f"{mangled!r} is not in a COMDAT section")
        return section


def coff_body(coff: CoffObject, section: dict) -> bytes:
    if not section["raw_size"]:
        return b""
    start = section["raw_offset"]
    return coff.data[start : start + section["raw_size"]]


def raw_coff_directive(data: bytes, context: str) -> bytes | None:
    """Return the exact classic-COFF `.drectve` bytes, if present."""
    if len(data) < 20:
        return None
    machine, section_count = struct.unpack_from("<HH", data, 0)
    if machine != 0x14C:
        return None
    require(0 < section_count < 0x10000
            and 20 + section_count * 40 <= len(data),
            f"{context} COFF section table is invalid")
    directives = []
    for index in range(section_count):
        offset = 20 + index * 40
        raw_name = data[offset:offset + 8]
        name = raw_name.rstrip(b"\0")
        if name != b".drectve":
            continue
        raw_size, raw_offset = struct.unpack_from("<II", data, offset + 16)
        require(raw_size > 0 and raw_offset <= len(data) - raw_size,
                f"{context} .drectve body is invalid")
        directives.append(data[raw_offset:raw_offset + raw_size])
    require(len(directives) <= 1,
            f"{context} contains duplicate .drectve sections")
    return directives[0] if directives else None


def validate_first_party_object_directive(data: bytes, context: str) -> bytes:
    raw = raw_coff_directive(data, context)
    require(raw is not None and raw in FIRST_PARTY_DIRECTIVE_PATTERNS,
            f"{context} raw .drectve bytes/order are not allowlisted")
    # The raw-pattern gate is authoritative.  Token validation makes the
    # finite implicit LINK surface explicit and rejects malformed whitespace.
    tokens = raw.decode("ascii", "strict").split()
    require(tokens and raw == (" ".join(tokens) + " ").encode("ascii"),
            f"{context} .drectve spacing differs")
    allowed_prefixes = ("-defaultlib:", "-export:", "/include:")
    require(all(token.startswith(allowed_prefixes) for token in tokens),
            f"{context} .drectve contains an unsupported option")
    return raw


def parse_coff_archive_members(data: bytes, context: str) -> list[tuple[str, bytes]]:
    """Parse the bounded Microsoft archive member stream without tool help."""
    require(data.startswith(b"!<arch>\n"), f"{context} is not a COFF archive")
    offset = 8
    long_names = b""
    pending: list[tuple[bytes, bytes]] = []
    while offset < len(data):
        require(offset + 60 <= len(data), f"{context} member header is truncated")
        header = data[offset:offset + 60]
        require(header[58:60] == b"`\n",
                f"{context} member header trailer differs")
        raw_size = header[48:58].strip()
        require(raw_size.isdigit(), f"{context} member size is invalid")
        size = int(raw_size)
        start = offset + 60
        require(start <= len(data) - size,
                f"{context} member payload is truncated")
        raw_name = header[:16].rstrip(b" ")
        payload = data[start:start + size]
        if raw_name == b"//":
            long_names = payload
        elif raw_name != b"/":
            pending.append((raw_name, payload))
        offset = start + size + (size & 1)
    require(offset == len(data), f"{context} archive alignment differs")
    result = []
    for raw_name, payload in pending:
        if raw_name.startswith(b"/") and raw_name[1:].isdigit():
            name_offset = int(raw_name[1:])
            require(name_offset < len(long_names),
                    f"{context} long member name offset is invalid")
            end = long_names.find(b"/\n", name_offset)
            require(end >= 0, f"{context} long member name is unterminated")
            name_bytes = long_names[name_offset:end]
        else:
            name_bytes = raw_name[:-1] if raw_name.endswith(b"/") else raw_name
        name = name_bytes.decode("ascii", "strict").replace("\\", "/")
        require(name and "\0" not in name,
                f"{context} member name is invalid")
        result.append((name, payload))
    return result


def validate_first_party_archive_payload(
    data: bytes, input_records: list[dict], context: str,
) -> None:
    members = parse_coff_archive_members(data, context)
    actual_payloads = [sha256_bytes(payload) for _, payload in members]
    expected_payloads = []
    expected_directives = Counter()
    authority = active_build_authority()
    for record in input_records:
        payload = authority.read_bytes(Path(record["path"]), max_bytes=1 << 30)
        require(sha256_bytes(payload) == record["sha256"],
                f"{context} input changed before archive validation")
        expected_payloads.append(record["sha256"])
        if record["role"] == "compiler_object":
            expected_directives[validate_first_party_object_directive(
                payload, f"{context} input {record['source']}"
            )] += 1
    require(actual_payloads == expected_payloads,
            f"{context} member payload/order universe differs from resident inputs")
    actual_directives = Counter()
    for name, payload in members:
        raw = raw_coff_directive(payload, f"{context} member {name}")
        if raw is not None:
            actual_directives[validate_first_party_object_directive(
                payload, f"{context} member {name}"
            )] += 1
    require(actual_directives == expected_directives,
            f"{context} member .drectve multiset differs from resident objects")


def validate_third_party_archive_directives(
    identity: str, data: bytes, context: str,
) -> None:
    expected = (
        SMARTHEAP_DIRECTIVE_MEMBERS
        if identity == "SmartHeap" else SMACKER_DIRECTIVE_MEMBERS
        if identity == "Smacker" else None
    )
    require(expected is not None,
            f"{context} is not an authorized third-party archive")
    observed = {}
    for name, payload in parse_coff_archive_members(data, context):
        raw = raw_coff_directive(payload, f"{context} member {name}")
        if raw is not None:
            basename = PurePosixPath(name).name.casefold()
            require(basename not in observed,
                    f"{context} has duplicate directive-bearing member {basename}")
            observed[basename] = raw
    require(observed == expected,
            f"{context} exact archive-member .drectve allowlist differs")


def coff_table(coff: CoffObject, section: dict, kind: str) -> bytes:
    if kind == "relocations":
        start = section["relocation_offset"]
        size = section["relocation_count"] * 10
    elif kind == "lines":
        start = section["line_offset"]
        size = section["line_count"] * 6
    else:
        raise ByteIdentityError(f"unknown COFF table kind: {kind}")
    return coff.data[start : start + size] if size else b""


def coff_auxiliary(coff: CoffObject, symbol_index: int, symbol: dict) -> bytes:
    require(symbol["aux_count"] >= 1,
            f"symbol {symbol['name']!r} has no auxiliary record")
    offset = coff.symbol_offset + (symbol_index + 1) * 18
    return coff.data[offset : offset + 18]


def unique_symbol(coff: CoffObject, predicate, description: str) -> tuple[int, dict]:
    matches = [
        (index, symbol)
        for index, symbol in coff.symbols.items()
        if predicate(symbol)
    ]
    require(len(matches) == 1, f"expected one {description}, found {len(matches)}")
    return matches[0]


def function_symbol(coff: CoffObject, mangled: str, section_number: int) -> tuple[int, dict]:
    return unique_symbol(
        coff,
        lambda symbol: (
            symbol["name"] == mangled
            and symbol["section"] == section_number
            and symbol["value"] == 0
            and symbol["type"] == 0x20
            and symbol["storage"] in (2, 3)
        ),
        f"function symbol {mangled!r}",
    )


def section_symbol(coff: CoffObject, section: dict) -> tuple[int, dict]:
    return unique_symbol(
        coff,
        lambda symbol: (
            symbol["name"] == section["name"]
            and symbol["section"] == section["number"]
            and symbol["storage"] == 3
            and symbol["aux_count"] >= 1
        ),
        f"section-definition symbol for section {section['number']}",
    )


def marker_symbol(coff: CoffObject, name: str, section_number: int) -> tuple[int, dict]:
    return unique_symbol(
        coff,
        lambda symbol: (
            symbol["name"] == name
            and symbol["section"] == section_number
            and symbol["storage"] == 101
            and symbol["aux_count"] >= 1
        ),
        f"{name} symbol for section {section_number}",
    )


def section_definitions(coff: CoffObject) -> dict[int, dict]:
    result = {}
    for index, symbol in coff.symbols.items():
        if not (
            0 < symbol["section"] <= len(coff.sections)
            and symbol["storage"] == 3
            and symbol["aux_count"] >= 1
        ):
            continue
        section = coff.sections[symbol["section"] - 1]
        if symbol["name"] != section["name"]:
            continue
        auxiliary = coff_auxiliary(coff, index, symbol)
        associated = (
            int.from_bytes(auxiliary[12:14], "little")
            | (int.from_bytes(auxiliary[16:18], "little") << 16)
        )
        result[section["number"]] = {
            "symbol_index": index,
            "raw": auxiliary,
            "length": int.from_bytes(auxiliary[0:4], "little"),
            "relocations": int.from_bytes(auxiliary[4:6], "little"),
            "lines": int.from_bytes(auxiliary[6:8], "little"),
            "checksum": int.from_bytes(auxiliary[8:12], "little"),
            "associated": associated,
            "selection": auxiliary[14],
        }
    return result


def associated_sections(
    coff: CoffObject, definitions: dict[int, dict], parent: int
) -> tuple[tuple[int, str], ...]:
    return tuple(
        (section["number"], section["name"])
        for section in coff.sections
        if definitions.get(section["number"], {}).get("selection") == 5
        and definitions[section["number"]]["associated"] == parent
    )


def function_multiset(coff: CoffObject) -> Counter:
    return Counter(
        symbol["name"]
        for symbol in coff.symbols.values()
        if symbol["type"] == 0x20
        and symbol["section"] > 0
        and symbol["value"] == 0
        and symbol["storage"] in (2, 3)
        and coff.sections[symbol["section"] - 1]["name"].startswith(".text")
        and coff.sections[symbol["section"] - 1]["raw_size"] > 0
    )


RELOCATION_WIDTHS = {
    0x0006: 4,  # IMAGE_REL_I386_DIR32
    0x0007: 4,  # IMAGE_REL_I386_DIR32NB
    0x000A: 2,  # IMAGE_REL_I386_SECTION
    0x000B: 4,  # IMAGE_REL_I386_SECREL
    0x0014: 4,  # IMAGE_REL_I386_REL32
}


def detailed_relocations(coff: CoffObject, section: dict) -> list[dict]:
    result = []
    for ordinal in range(section["relocation_count"]):
        offset = section["relocation_offset"] + ordinal * 10
        virtual_address, symbol_index, relocation_type = coff_unpack(
            "<IIH", coff.data, offset, f"section {section['number']} relocation {ordinal}"
        )
        require(symbol_index in coff.symbols,
                f"section {section['number']} relocation {ordinal} references an auxiliary symbol")
        width = RELOCATION_WIDTHS.get(relocation_type)
        require(width is not None,
                f"unsupported i386 relocation type 0x{relocation_type:04x}")
        require(virtual_address <= section["raw_size"] - width,
                f"section {section['number']} relocation {ordinal} operand is outside raw data")
        addend = int.from_bytes(
            coff.data[
                section["raw_offset"] + virtual_address:
                section["raw_offset"] + virtual_address + width
            ],
            "little",
        )
        target = coff.symbols[symbol_index]
        result.append(
            {
                "ordinal": ordinal,
                "offset": virtual_address,
                "symbol_index": symbol_index,
                "type": relocation_type,
                "width": width,
                "addend": addend,
                "target": target["name"],
                "target_section": target["section"],
                "target_value": target["value"],
                "target_type": target["type"],
                "target_storage": target["storage"],
            }
        )
    return result


def local_symbol_kind(name: str) -> str | None:
    if len(name) > 2 and name[0] == "$" and name[1] in "LT" and name[2:].isdigit():
        return name[1]
    if name.startswith("$done$") and name[6:].isdigit():
        return "done"
    return None


def relocation_compatibility(
    seed_rows: list[dict], donor_rows: list[dict], seed_primary: int, donor_primary: int
) -> dict | None:
    """Pair primary relocations by semantic target/type/addend, not file offset."""
    if len(seed_rows) != len(donor_rows):
        return None
    local_updates = {}
    pairs = []
    for seed, donor in zip(seed_rows, donor_rows):
        if not (
            seed["type"] == donor["type"]
            and seed["width"] == donor["width"]
            and seed["addend"] == donor["addend"]
            and seed["target_type"] == donor["target_type"]
            and seed["target_storage"] == donor["target_storage"]
        ):
            return None
        seed_internal = seed["target_section"] == seed_primary
        donor_internal = donor["target_section"] == donor_primary
        if seed_internal != donor_internal:
            return None
        seed_kind = local_symbol_kind(seed["target"])
        donor_kind = local_symbol_kind(donor["target"])
        if seed_kind or donor_kind:
            if not (seed_internal and donor_internal and seed_kind == donor_kind):
                return None
            previous = local_updates.setdefault(seed["symbol_index"], donor["target_value"])
            if previous != donor["target_value"]:
                return None
        elif not (
            seed["target"] == donor["target"]
            and (
                (seed_internal and seed["target_value"] == donor["target_value"])
                or (
                    not seed_internal
                    and seed["target_section"] == donor["target_section"]
                    and seed["target_value"] == donor["target_value"]
                )
            )
        ):
            return None
        pairs.append(
            {
                "ordinal": seed["ordinal"],
                "seed_offset": seed["offset"],
                "donor_offset": donor["offset"],
                "type": donor["type"],
                "addend": donor["addend"],
                "seed_target": seed["target"],
                "donor_target": donor["target"],
            }
        )
    return {"pairs": pairs, "local_updates": local_updates}


def linker_payload_multiset(coff: CoffObject) -> Counter:
    """Fingerprint every non-code, non-CodeView linker contribution.

    This intentionally includes `.drectve`, `.xdata`, import/CRT/tls families,
    and unknown section names.  A declaration shape is not allowed to create
    or perturb any such payload even though the final composition retains the
    seed copy. Raw relocation-table bytes are deliberately excluded because
    their symbol-index field is object bookkeeping; the ordered resolved tuple
    below retains offset, type, addend, target identity, section, value, type,
    and storage while the section-body digest retains the relocated operands.
    """
    result = Counter()
    for section in coff.sections:
        if section["name"].startswith(".text") or section["name"].startswith(".debug"):
            continue
        relocations = tuple(
            (
                item["offset"], item["type"], item["addend"],
                local_symbol_kind(item["target"]) or item["target"],
                item["target_section"], item["target_value"],
                item["target_type"], item["target_storage"],
            )
            for item in detailed_relocations(coff, section)
        )
        result[
            (
                section["name"], section["raw_size"], section["characteristics"],
                sha256_bytes(coff_body(coff, section)), relocations,
            )
        ] += 1
    return result


def declaration_identifiers(header: bytes) -> set[str]:
    text = header.decode("ascii", "strict")
    require("Generated declaration-only entropy shape. Emits no code or data." in text,
            "generated declaration shape marker is absent")
    identifiers = set(re.findall(r"\b(?:Class|Function)[A-Za-z]+\b", text))
    require(identifiers, "generated declaration shape has no identifiers")
    return identifiers


def verify_non_emitting_donor(
    seed: CoffObject, donor: CoffObject, identifiers: set[str]
) -> dict:
    require(function_multiset(seed) == function_multiset(donor),
            "declaration shape changed the complete function multiset")
    require(len(seed.sections) == len(donor.sections),
            "declaration shape changed the section count")
    require(
        all(
            left["name"] == right["name"]
            and left["characteristics"] == right["characteristics"]
            for left, right in zip(seed.sections, donor.sections)
        ),
        "declaration shape changed section order or characteristics",
    )
    leaked_symbols = sorted(
        symbol["name"]
        for symbol in donor.symbols.values()
        if any(identifier in symbol["name"] for identifier in identifiers)
    )
    require(not leaked_symbols,
            f"declaration shape emitted COFF symbols: {leaked_symbols[:5]}")
    require(linker_payload_multiset(seed) == linker_payload_multiset(donor),
            "declaration shape added or altered non-code/directive/import/CRT linker payload")

    # VC4.2 can place CodeView type records in an ordinary `.debug$S` stream
    # (not only `.debug$T`).  Such records are compiler metadata, not linker
    # payload, and none of them is copied into the seed-based composition.
    debug_type_ranges = [
        (section["raw_offset"], section["raw_offset"] + section["raw_size"])
        for section in donor.sections
        if section["name"] in (".debug$S", ".debug$T") and section["raw_size"]
    ]
    for identifier in identifiers:
        needle = identifier.encode("ascii")
        start = 0
        while True:
            occurrence = donor.data.find(needle, start)
            if occurrence < 0:
                break
            require(any(left <= occurrence < right for left, right in debug_type_ranges),
                    f"declaration identifier escaped CodeView types: {identifier}")
            start = occurrence + 1
    return {
        "function_count": sum(function_multiset(seed).values()),
        "section_count": len(seed.sections),
        "defined_or_undefined_shape_symbols": [],
        "noncode_directive_import_crt_payload_identical": True,
    }


def normalized_donor_lines(
    seed: CoffObject,
    donor: CoffObject,
    seed_section: dict,
    donor_section: dict,
    seed_function_index: int,
    donor_function_index: int,
) -> bytes:
    require(seed_section["line_count"] > 0 and donor_section["line_count"] > 0,
            "FPO composer requires COFF line tables")
    seed_lines = coff_table(seed, seed_section, "lines")
    donor_lines = bytearray(coff_table(donor, donor_section, "lines"))
    require(struct.unpack_from("<IH", seed_lines, 0) == (seed_function_index, 0),
            "seed COFF line sentinel is invalid")
    require(struct.unpack_from("<IH", donor_lines, 0) == (donor_function_index, 0),
            "donor COFF line sentinel is invalid")
    struct.pack_into("<I", donor_lines, 0, seed_function_index)
    previous = -1
    for index in range(1, donor_section["line_count"]):
        offset, line = struct.unpack_from("<IH", donor_lines, index * 6)
        require(line != 0 and previous <= offset < donor_section["raw_size"],
                f"donor COFF line row {index} is outside or nonmonotonic")
        previous = offset
    return bytes(donor_lines)


def apply_replacements(data: bytes, replacements: list[tuple[int, int, bytes]]) -> bytes:
    ordered = sorted(replacements, key=lambda item: item[0])
    cursor = 0
    chunks = []
    for start, end, replacement in ordered:
        require(cursor <= start <= end <= len(data), "COFF replacement ranges overlap")
        chunks.extend((data[cursor:start], replacement))
        cursor = end
    chunks.append(data[cursor:])
    return b"".join(chunks)


def shifted_pointer(pointer: int, replacements: list[tuple[int, int, bytes]]) -> int:
    if pointer == 0:
        return 0
    delta = 0
    for start, end, replacement in sorted(replacements, key=lambda item: item[0]):
        if pointer < start:
            break
        if pointer == start:
            return start + delta
        require(pointer >= end, "COFF pointer falls inside a replaced range")
        delta += len(replacement) - (end - start)
    return pointer + delta


FPO_RECORD_KEYS = {
    "ulOffStart", "cbProcSize", "cdwLocals", "cdwParams", "cbProlog",
    "cbRegs", "fHasSEH", "fUseBP", "reserved", "cbFrame", "raw_sha256",
}


def parse_fpo_data(raw: bytes, *, expected_proc_size: int | None = None) -> dict:
    """Decode and structurally validate one classic 16-byte FPO_DATA row."""
    require(isinstance(raw, bytes) and len(raw) == 16,
            "associated FPO record is not exactly 16 bytes")
    ul_off_start, cb_proc_size, cdw_locals, cdw_params = struct.unpack_from(
        "<IIIH", raw, 0
    )
    cb_prolog = raw[14]
    packed = raw[15]
    result = {
        "ulOffStart": ul_off_start,
        "cbProcSize": cb_proc_size,
        "cdwLocals": cdw_locals,
        "cdwParams": cdw_params,
        "cbProlog": cb_prolog,
        "cbRegs": packed & 0x7,
        "fHasSEH": (packed >> 3) & 0x1,
        "fUseBP": (packed >> 4) & 0x1,
        "reserved": (packed >> 5) & 0x1,
        "cbFrame": (packed >> 6) & 0x3,
        "raw_sha256": sha256_bytes(raw),
    }
    require(result["ulOffStart"] == 0,
            "associative function FPO ulOffStart must be zero")
    require(result["cbProcSize"] > 0,
            "FPO cbProcSize must be positive")
    if expected_proc_size is not None:
        require(type(expected_proc_size) is int and expected_proc_size > 0
                and result["cbProcSize"] == expected_proc_size,
                "FPO cbProcSize differs from its function section")
    require(result["cbProlog"] <= result["cbProcSize"],
            "FPO cbProlog exceeds cbProcSize")
    require(result["reserved"] == 0,
            "FPO reserved bit must remain zero")
    require(result["cdwLocals"] <= 0x3FFFFFFF,
            "FPO local DWORD count overflows its byte range")
    require(result["cdwParams"] <= 0x7FFF,
            "FPO parameter WORD count overflows its byte range")
    return result


def validate_manifest_fpo_record(value: object, context: str) -> dict:
    require(isinstance(value, dict), f"{context} must be an object")
    exact_audit_keys(value, FPO_RECORD_KEYS, context)
    integer_ranges = {
        "ulOffStart": (0, 0xFFFFFFFF),
        "cbProcSize": (1, 0xFFFFFFFF),
        "cdwLocals": (0, 0x3FFFFFFF),
        "cdwParams": (0, 0x7FFF),
        "cbProlog": (0, 0xFF),
        "cbRegs": (0, 7),
        "fHasSEH": (0, 1),
        "fUseBP": (0, 1),
        "reserved": (0, 0),
        "cbFrame": (0, 3),
    }
    normalized = {}
    for name, (minimum, maximum) in integer_ranges.items():
        item = value.get(name)
        require(type(item) is int and minimum <= item <= maximum,
                f"{context}.{name} is invalid")
        normalized[name] = item
    normalized["raw_sha256"] = require_sha(
        value.get("raw_sha256"), f"{context}.raw_sha256"
    )
    require(normalized["ulOffStart"] == 0
            and normalized["cbProlog"] <= normalized["cbProcSize"],
            f"{context} is structurally invalid")
    return normalized


def compose_equal_linked_span_fpo(
    seed_bytes: bytes,
    donor_bytes: bytes,
    function: dict,
    shape_identifiers: set[str],
) -> tuple[bytes, dict]:
    """Compose one compiler-produced FPO COMDAT and prove its full closure."""
    seed = CoffObject(seed_bytes)
    donor = CoffObject(donor_bytes)
    mangled = function["mangled"]
    seed_primary = seed.function_section(mangled)
    donor_primary = donor.function_section(mangled)
    require(
        seed_primary["number"] == donor_primary["number"]
        == function["expected_section_number"],
        "target COMDAT section seat changed",
    )
    require(seed_primary["raw_size"] == function["expected_seed_length"],
            "seed target length changed")
    require(donor_primary["raw_size"] == function["expected_donor_length"],
            "donor target length changed")
    require(
        ((seed_primary["raw_size"] + 15) // 16) * 16
        == function["expected_linked_span"]
        == ((donor_primary["raw_size"] + 15) // 16) * 16,
        "target 16-byte linked contribution span changed",
    )
    require(
        seed_primary["name"] == donor_primary["name"]
        and seed_primary["characteristics"] == donor_primary["characteristics"]
        == function["expected_characteristics"],
        "target section kind or characteristics changed",
    )
    require((seed_primary["characteristics"] & 0x00F00000) == 0x00500000,
            "target COMDAT does not declare 16-byte section alignment")
    require(
        seed_primary["relocation_count"] == donor_primary["relocation_count"]
        == function["expected_relocation_count"],
        "target relocation count changed",
    )
    require(seed_primary["line_count"] == function["expected_seed_line_count"]
            and donor_primary["line_count"] == function["expected_donor_line_count"],
            "target COFF line count changed")

    seed_definitions = section_definitions(seed)
    donor_definitions = section_definitions(donor)
    require(seed_primary["number"] in seed_definitions
            and donor_primary["number"] in donor_definitions,
            "target Section Definition auxiliary record is absent")
    require(
        seed_definitions[seed_primary["number"]]["selection"]
        == donor_definitions[donor_primary["number"]]["selection"]
        == function["expected_selection"],
        "target COMDAT selection changed",
    )
    seed_associated = associated_sections(seed, seed_definitions, seed_primary["number"])
    donor_associated = associated_sections(donor, donor_definitions, donor_primary["number"])
    require(seed_associated == donor_associated,
            "target associative-section seats changed")
    require(tuple(sorted(name for _, name in seed_associated)) == (".debug$F", ".debug$S"),
            "target closure is not exactly .debug$S + .debug$F; xdata is unsupported")
    provenance = verify_non_emitting_donor(seed, donor, shape_identifiers)
    seed_closure = {
        name: seed.sections[number - 1] for number, name in seed_associated
    }
    donor_closure = {
        name: donor.sections[number - 1] for number, name in donor_associated
    }
    for name in (".debug$S", ".debug$F"):
        left = seed_closure[name]
        right = donor_closure[name]
        require(
            left["number"] == right["number"]
            and left["raw_size"] == right["raw_size"]
            and left["relocation_count"] == right["relocation_count"]
            and left["line_count"] == right["line_count"] == 0
            and left["characteristics"] == right["characteristics"],
            f"{name} closure geometry changed",
        )
        left_rows = detailed_relocations(seed, left)
        right_rows = detailed_relocations(donor, right)
        require(
            [
                (
                    row["offset"], row["type"], row["addend"], row["target"],
                    row["target_section"], row["target_value"],
                    row["target_type"], row["target_storage"],
                )
                for row in left_rows
            ]
            == [
                (
                    row["offset"], row["type"], row["addend"], row["target"],
                    row["target_section"], row["target_value"],
                    row["target_type"], row["target_storage"],
                )
                for row in right_rows
            ],
            f"{name} relocation target/type/addend closure changed",
        )

    seed_relocations = detailed_relocations(seed, seed_primary)
    donor_relocations = detailed_relocations(donor, donor_primary)
    compatibility = relocation_compatibility(
        seed_relocations,
        donor_relocations,
        seed_primary["number"],
        donor_primary["number"],
    )
    require(compatibility is not None,
            "primary relocation target/type/addend semantics changed")
    require(len(compatibility["local_updates"])
            == function["expected_local_symbol_updates"],
            "primary local-symbol update count changed")
    donor_body = coff_body(donor, donor_primary)
    require(sha256_bytes(donor_body) == function["compiler_output_body_sha256"],
            "compiler donor body hash differs from the retail-approved oracle pin")

    seed_function_index, seed_function = function_symbol(
        seed, mangled, seed_primary["number"]
    )
    donor_function_index, donor_function = function_symbol(
        donor, mangled, donor_primary["number"]
    )
    donor_lines = normalized_donor_lines(
        seed, donor, seed_primary, donor_primary,
        seed_function_index, donor_function_index,
    )
    replacements = [
        (
            seed_primary["raw_offset"],
            seed_primary["raw_offset"] + seed_primary["raw_size"],
            donor_body,
        ),
        (
            seed_primary["line_offset"],
            seed_primary["line_offset"] + seed_primary["line_count"] * 6,
            donor_lines,
        ),
    ]
    output = bytearray(apply_replacements(seed_bytes, replacements))
    total_delta = sum(len(replacement) - (end - start)
                      for start, end, replacement in replacements)
    new_symbol_offset = shifted_pointer(seed.symbol_offset, replacements)
    struct.pack_into("<I", output, 8, new_symbol_offset)

    expected_headers = bytearray(seed.data[20 : 20 + seed.section_count * 40])
    for section in seed.sections:
        relative_header = (section["number"] - 1) * 40
        if section["number"] == seed_primary["number"]:
            struct.pack_into("<I", expected_headers, relative_header + 16,
                             donor_primary["raw_size"])
            struct.pack_into("<H", expected_headers, relative_header + 34,
                             donor_primary["line_count"])
        for field, relative in (
            ("raw_offset", 20), ("relocation_offset", 24), ("line_offset", 28)
        ):
            struct.pack_into(
                "<I", expected_headers, relative_header + relative,
                shifted_pointer(section[field], replacements),
            )
    output[20 : 20 + len(expected_headers)] = expected_headers

    new_primary_relocation_offset = shifted_pointer(
        seed_primary["relocation_offset"], replacements
    )
    for ordinal, (seed_row, donor_row) in enumerate(
        zip(seed_relocations, donor_relocations)
    ):
        struct.pack_into(
            "<IIH", output, new_primary_relocation_offset + ordinal * 10,
            donor_row["offset"], seed_row["symbol_index"], donor_row["type"],
        )

    expected_symbols = bytearray(
        seed.data[seed.symbol_offset : seed.symbol_offset + seed.symbol_count * 18]
    )
    shifted_function_line_pointers = 0
    for symbol_index, symbol in seed.symbols.items():
        if symbol["type"] != 0x20 or symbol["aux_count"] < 1:
            continue
        auxiliary_offset = (symbol_index + 1) * 18
        line_pointer, = struct.unpack_from("<I", expected_symbols, auxiliary_offset + 8)
        mapped = shifted_pointer(line_pointer, replacements)
        if mapped != line_pointer:
            struct.pack_into("<I", expected_symbols, auxiliary_offset + 8, mapped)
            shifted_function_line_pointers += 1
    for symbol_index, donor_value in compatibility["local_updates"].items():
        struct.pack_into("<I", expected_symbols, symbol_index * 18 + 8, donor_value)

    donor_function_auxiliary = coff_auxiliary(
        donor, donor_function_index, donor_function
    )
    seed_function_auxiliary = coff_auxiliary(
        seed, seed_function_index, seed_function
    )
    require(
        seed_function["type"] == donor_function["type"]
        and seed_function["storage"] == donor_function["storage"]
        and seed_function["aux_count"] == donor_function["aux_count"] == 1
        and seed_function_auxiliary[:4] == donor_function_auxiliary[:4]
        and seed_function_auxiliary[12:] == donor_function_auxiliary[12:],
        "Function Definition tag/next-function auxiliary metadata changed",
    )
    seed_total_size, seed_line_pointer = struct.unpack_from(
        "<II", seed_function_auxiliary, 4
    )
    donor_total_size, donor_line_pointer = struct.unpack_from(
        "<II", donor_function_auxiliary, 4
    )
    require(seed_total_size == seed_primary["raw_size"]
            and seed_line_pointer == seed_primary["line_offset"],
            "seed Function Definition size/line pointer is stale")
    require(donor_total_size == donor_primary["raw_size"]
            and donor_line_pointer == donor_primary["line_offset"],
            "donor Function Definition size/line pointer is stale")
    struct.pack_into("<I", expected_symbols, (seed_function_index + 1) * 18 + 4,
                     donor_total_size)

    seed_begin_index, seed_begin = marker_symbol(seed, ".bf", seed_primary["number"])
    donor_begin_index, donor_begin = marker_symbol(donor, ".bf", donor_primary["number"])
    seed_begin_auxiliary = coff_auxiliary(seed, seed_begin_index, seed_begin)
    donor_begin_auxiliary = coff_auxiliary(donor, donor_begin_index, donor_begin)
    require(
        seed_begin["aux_count"] == donor_begin["aux_count"] == 1
        and seed_begin["value"] == donor_begin["value"]
        and seed_begin["type"] == donor_begin["type"]
        and seed_begin["storage"] == donor_begin["storage"]
        and seed_begin_auxiliary[:4] == donor_begin_auxiliary[:4]
        and seed_begin_auxiliary[6:] == donor_begin_auxiliary[6:],
        ".bf tag/next-function auxiliary metadata changed",
    )
    expected_symbols[(seed_begin_index + 1) * 18 + 4:
                     (seed_begin_index + 1) * 18 + 6] = donor_begin_auxiliary[4:6]

    seed_end_index, seed_end = marker_symbol(seed, ".ef", seed_primary["number"])
    donor_end_index, donor_end = marker_symbol(donor, ".ef", donor_primary["number"])
    require(seed_end["value"] == seed_primary["raw_size"],
            "seed .ef value is stale")
    require(donor_end["value"] == donor_primary["raw_size"],
            "donor .ef value is stale")
    seed_end_auxiliary = coff_auxiliary(seed, seed_end_index, seed_end)
    donor_end_auxiliary = coff_auxiliary(donor, donor_end_index, donor_end)
    require(
        seed_end["aux_count"] == donor_end["aux_count"] == 1
        and seed_end["type"] == donor_end["type"]
        and seed_end["storage"] == donor_end["storage"]
        and seed_end_auxiliary[:4] == donor_end_auxiliary[:4]
        and seed_end_auxiliary[6:] == donor_end_auxiliary[6:],
        ".ef tag/next-function auxiliary metadata changed",
    )
    struct.pack_into("<I", expected_symbols, seed_end_index * 18 + 8,
                     donor_end["value"])
    expected_symbols[(seed_end_index + 1) * 18 + 4:
                     (seed_end_index + 1) * 18 + 6] = donor_end_auxiliary[4:6]

    seed_section_index, seed_section_symbol = section_symbol(seed, seed_primary)
    donor_section_index, donor_section_symbol = section_symbol(donor, donor_primary)
    donor_section_auxiliary = coff_auxiliary(
        donor, donor_section_index, donor_section_symbol
    )
    seed_section_auxiliary = coff_auxiliary(
        seed, seed_section_index, seed_section_symbol
    )
    require(
        seed_section_symbol["aux_count"]
        == donor_section_symbol["aux_count"] == 1
        and seed_section_symbol["type"] == donor_section_symbol["type"]
        and seed_section_symbol["storage"] == donor_section_symbol["storage"]
        and seed_section_auxiliary[12:] == donor_section_auxiliary[12:]
        and int.from_bytes(seed_section_auxiliary[0:4], "little")
        == seed_primary["raw_size"]
        and int.from_bytes(seed_section_auxiliary[4:6], "little")
        == seed_primary["relocation_count"]
        and int.from_bytes(seed_section_auxiliary[6:8], "little")
        == seed_primary["line_count"]
        and int.from_bytes(donor_section_auxiliary[0:4], "little")
        == donor_primary["raw_size"]
        and int.from_bytes(donor_section_auxiliary[4:6], "little")
        == donor_primary["relocation_count"]
        and int.from_bytes(donor_section_auxiliary[6:8], "little")
        == donor_primary["line_count"]
        and donor_section_auxiliary[14] == function["expected_selection"],
        "donor Section Definition auxiliary record is stale",
    )
    expected_symbols[(seed_section_index + 1) * 18:
                     (seed_section_index + 2) * 18] = donor_section_auxiliary
    output[new_symbol_offset:new_symbol_offset + len(expected_symbols)] = expected_symbols

    seed_debug_s_raw = coff_body(seed, seed_closure[".debug$S"])
    donor_debug_s_raw = coff_body(donor, donor_closure[".debug$S"])
    require(len(seed_debug_s_raw) == len(donor_debug_s_raw) >= 28,
            "CodeView procedure record size changed or is truncated")
    require(seed_debug_s_raw[2:4] == donor_debug_s_raw[2:4] == b"\x05\x02",
            "associated CodeView record is not S_*PROC32")
    donor_cbproc, donor_dbgstart, donor_dbgend = struct.unpack_from(
        "<III", donor_debug_s_raw, 16
    )
    require(donor_cbproc == donor_primary["raw_size"]
            and 0 <= donor_dbgstart <= donor_dbgend < donor_cbproc,
            "donor CodeView procedure range is invalid")
    expected_debug_s = bytearray(seed_debug_s_raw)
    expected_debug_s[16:28] = donor_debug_s_raw[16:28]
    debug_s_offset = shifted_pointer(seed_closure[".debug$S"]["raw_offset"], replacements)
    output[debug_s_offset:debug_s_offset + len(expected_debug_s)] = expected_debug_s

    seed_debug_f_raw = coff_body(seed, seed_closure[".debug$F"])
    donor_debug_f_raw = coff_body(donor, donor_closure[".debug$F"])
    seed_fpo = parse_fpo_data(
        seed_debug_f_raw, expected_proc_size=seed_primary["raw_size"]
    )
    donor_fpo = parse_fpo_data(
        donor_debug_f_raw, expected_proc_size=donor_primary["raw_size"]
    )
    require(exact_json_equal(donor_fpo, function["expected_donor_fpo"]),
            "compiler donor FPO record differs from the manifest pin")
    require(donor_fpo["cbProcSize"] == donor_cbproc,
            "donor FPO and CodeView procedure sizes differ")
    debug_f_offset = shifted_pointer(seed_closure[".debug$F"]["raw_offset"], replacements)
    output[debug_f_offset:debug_f_offset + 16] = donor_debug_f_raw
    output_bytes = bytes(output)

    checked = CoffObject(output_bytes)
    checked_primary = checked.function_section(mangled)
    require(len(output_bytes) == len(seed_bytes) + total_delta,
            "composed COFF file length delta is wrong")
    require(function_multiset(checked) == function_multiset(seed),
            "composed COFF function multiset changed")
    require(coff_body(checked, checked_primary) == donor_body,
            "composed target body differs from compiler donor")
    require(coff_table(checked, checked_primary, "lines") == donor_lines,
            "composed COFF line table differs from normalized donor")
    checked_relocations = detailed_relocations(checked, checked_primary)
    require(
        [
            (row["offset"], row["symbol_index"], row["type"], row["addend"])
            for row in checked_relocations
        ]
        == [
            (donor_row["offset"], seed_row["symbol_index"], donor_row["type"], donor_row["addend"])
            for seed_row, donor_row in zip(seed_relocations, donor_relocations)
        ],
        "composed primary relocation table is incoherent",
    )
    checked_definitions = section_definitions(checked)
    checked_associated = associated_sections(
        checked, checked_definitions, checked_primary["number"]
    )
    require(checked_associated == seed_associated,
            "composed associative closure changed")
    expected_closure_raw = {
        seed_closure[".debug$S"]["number"]: bytes(expected_debug_s),
        seed_closure[".debug$F"]["number"]: donor_debug_f_raw,
    }
    for before, after in zip(seed.sections, checked.sections):
        require(before["number"] == after["number"]
                and before["name"] == after["name"]
                and before["characteristics"] == after["characteristics"],
                "composed section order/characteristics changed")
        number = before["number"]
        if number in expected_closure_raw:
            require(coff_body(checked, after) == expected_closure_raw[number],
                    f"composed debug closure raw bytes differ: section {number}")
            require(coff_table(seed, before, "relocations")
                    == coff_table(checked, after, "relocations"),
                    f"composed debug closure relocations changed: section {number}")
        elif number != seed_primary["number"]:
            require(coff_body(seed, before) == coff_body(checked, after),
                    f"non-target raw section changed: section {number}")
            require(coff_table(seed, before, "relocations")
                    == coff_table(checked, after, "relocations"),
                    f"non-target relocation table changed: section {number}")
        if number != seed_primary["number"]:
            require(coff_table(seed, before, "lines")
                    == coff_table(checked, after, "lines"),
                    f"non-target COFF line table changed: section {number}")

    require(
        checked.data[checked.symbol_offset:
                     checked.symbol_offset + checked.symbol_count * 18]
        == bytes(expected_symbols),
        "composed symbol/auxiliary table differs from the proven reconstruction",
    )
    checked_function_index, checked_function = function_symbol(
        checked, mangled, checked_primary["number"]
    )
    checked_function_auxiliary = coff_auxiliary(
        checked, checked_function_index, checked_function
    )
    require(struct.unpack_from("<I", checked_function_auxiliary, 4)[0]
            == donor_primary["raw_size"]
            and struct.unpack_from("<I", checked_function_auxiliary, 8)[0]
            == checked_primary["line_offset"],
            "composed Function Definition auxiliary record is stale")
    checked_begin_index, checked_begin = marker_symbol(
        checked, ".bf", checked_primary["number"]
    )
    require(coff_auxiliary(checked, checked_begin_index, checked_begin)[4:6]
            == donor_begin_auxiliary[4:6],
            "composed .bf line is stale")
    checked_end_index, checked_end = marker_symbol(
        checked, ".ef", checked_primary["number"]
    )
    require(checked_end["value"] == donor_primary["raw_size"]
            and coff_auxiliary(checked, checked_end_index, checked_end)
            == coff_auxiliary(donor, donor_end_index, donor_end),
            "composed .ef metadata differs from donor")
    checked_section_index, checked_section_symbol = section_symbol(checked, checked_primary)
    require(coff_auxiliary(checked, checked_section_index, checked_section_symbol)
            == donor_section_auxiliary,
            "composed Section Definition auxiliary record differs from donor")
    require(not any(identifier.encode("ascii") in output_bytes
                    for identifier in shape_identifiers),
            "declaration-shape identifiers leaked into the composed object")

    return output_bytes, {
        "mangled": mangled,
        "address": function["retail_oracle"]["address"],
        "retail_oracle": dict(function["retail_oracle"]),
        "retail_payload_bytes_read": 0,
        "section_number": checked_primary["number"],
        "seed_length": seed_primary["raw_size"],
        "donor_length": donor_primary["raw_size"],
        "linked_span": function["expected_linked_span"],
        "file_size_delta": total_delta,
        "relocation_count": len(checked_relocations),
        "relocation_offsets_moved": sum(
            left["offset"] != right["offset"]
            for left, right in zip(seed_relocations, donor_relocations)
        ),
        "local_symbols_updated": len(compatibility["local_updates"]),
        "function_line_pointers_shifted": shifted_function_line_pointers,
        "coff_line_policy": "whole_donor_normalized_function_index",
        "coff_line_rows": donor_primary["line_count"],
        "codeview_policy": "seed_types_names_locals_with_donor_cbProc_DbgStart_DbgEnd",
        "codeview_range": {
            "cbProc": donor_cbproc,
            "DbgStart": donor_dbgstart,
            "DbgEnd": donor_dbgend,
        },
        "fpo_policy": "whole_donor_debug_F_record",
        "seed_fpo": seed_fpo,
        "donor_fpo": donor_fpo,
        "target_body_sha256": sha256_bytes(donor_body),
        "input_sha256": sha256_bytes(seed_bytes),
        "donor_sha256": sha256_bytes(donor_bytes),
        "output_sha256": sha256_bytes(output_bytes),
        "provenance": provenance,
    }


def derive_dependency_command(command: list[str], output: Path) -> list[str]:
    parsed = validate_compile_arguments(command)
    remove_indices = {
        parsed["Fo"][0], parsed["Fd"][0],
        command.index(parsed["compile_only"]),
    }
    # The dependency pass is a preprocessor-only diagnostic. Debug and
    # incremental-state switches do not affect macro/include selection, but
    # VC4.2 may use them to create an ambient PDB/IDB even with /P.
    for index, token in enumerate(command[:-1]):
        if token.casefold() in ("/zi", "-zi", "/gm", "-gm"):
            remove_indices.add(index)
    require(not parsed["Fo"][2] and not parsed["Fd"][2],
            "dependency derivation requires attached compiler outputs")
    result = [
        token for index, token in enumerate(command[:-1])
        if index not in remove_indices
    ]
    result.extend(["/P", f"/Fi{output}", command[-1]])
    return result


def parse_preprocessed_dependencies(
    data: bytes, source: Path, allowed_roots: list[dict],
    *, virtual_z_root: Path | None = None,
    virtual_z_records: dict[str, dict] | None = None,
) -> list[dict]:
    require(data and b"\0" not in data,
            "compiler dependency preprocessor output is empty or binary")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        try:
            text = data.decode("cp1252")
        except UnicodeDecodeError as error:
            raise ByteIdentityError(
                f"compiler dependency output encoding is unsupported: {error}"
            ) from error
    marker = re.compile(r'^\s*#\s*line\s+[0-9]+\s+"([^"\r\n]+)"(?:\s.*)?$')
    paths = []
    for line in text.splitlines():
        if re.match(r"^\s*#\s*line\b", line):
            match = marker.fullmatch(line)
            require(match is not None,
                    "compiler dependency output contains a malformed #line record")
            value = match.group(1).replace("\\", "/")
            if re.match(r"^[zZ]:/", value):
                value = value[2:]
            require(not re.match(r"^[A-Za-z]:", value),
                    f"compiler dependency output contains an unknown drive: {value}")
            candidate = Path(value)
            require(candidate.is_absolute(),
                    f"compiler dependency path is not absolute: {value}")
            # The compiler consumed the immutable fake-Z counterpart.  Do not
            # reopen or resolve the mutable live tree after the child exits;
            # retain only the canonical logical spelling and hash the exact
            # snapshotted file below.
            canonical = lexical_absolute_path(candidate)
            if not paths or canonical != paths[-1]:
                paths.append(canonical)
    source = lexical_absolute_path(source)
    require(source in paths,
            "compiler dependency output does not name the configured source")
    allowed = [lexical_absolute_path(Path(item["root"])) for item in allowed_roots]
    records = []
    seen = set()
    for path in paths:
        if path in seen:
            continue
        seen.add(path)
        consumed_path = (
            absolute_snapshot_seat(virtual_z_root, path)
            if virtual_z_root is not None else path
        )
        if virtual_z_root is not None:
            authority = active_build_authority()
            if virtual_z_records is None:
                require(authority.is_regular_file(consumed_path),
                        f"compiler dependency is not a regular snapshotted file: {path}")
        else:
            require(consumed_path.is_file(),
                    f"compiler dependency is not a regular file: {path}")
        within = False
        for root in allowed:
            try:
                path.relative_to(root)
                within = True
                break
            except ValueError:
                continue
        require(within,
                f"compiler consumed an input outside the sealed include closure: {path}")
        if virtual_z_records is None:
            consumed_sha = sha256_file(consumed_path)
        else:
            relative = PurePosixPath(*path.parts[1:]).as_posix()
            admitted = virtual_z_records.get(relative)
            require(
                admitted is not None and admitted.get("type") == "file"
                and admitted.get("path") == relative,
                f"compiler dependency lacks its held projection record: {path}",
            )
            consumed_sha = admitted["sha256"]
        records.append({"path": str(path), "sha256": consumed_sha})
    require(records and records[0]["path"] == str(source),
            "configured source is not the first compiler dependency record")
    return records


def held_command_snapshot_file_record(
    build_dir: Path, logical: Path,
) -> dict:
    """Return one prehashed command-snapshot leaf through held authority."""
    authority = active_build_authority()
    cached = authority.snapshot_validation_cache.get(
        command_snapshot_cache_key(build_dir)
    )
    require(cached is not None,
            "compiler dependency lacks the held command snapshot")
    relative = PurePosixPath(*lexical_absolute_path(logical).parts[1:]).as_posix()
    by_path = cached.get("records_by_path")
    if by_path is None:
        by_path = {
            item["path"]: item for item in cached["tree"]["records"]
        }
        require(len(by_path) == len(cached["tree"]["records"]),
                "held command snapshot record paths are duplicated")
        cached["records_by_path"] = by_path
    record = by_path.get(relative)
    require(record is not None and record["type"] == "file",
            f"compiler dependency is absent from the command snapshot: {logical}")
    path = absolute_snapshot_seat(
        command_snapshot_path(build_dir) / "z", logical
    )
    require(authority.is_regular_file(path),
            f"held compiler dependency disappeared: {logical}")
    cached["holder"].revalidate()
    return record


def source_overlay_output_for_logical_path(
    state: dict, logical: Path,
) -> tuple[str, dict] | None:
    """Return the typed-overlay owner for one canonical logical source seat."""
    overlay = state.get("source_overlay")
    if not isinstance(overlay, dict) or not overlay.get("enabled"):
        return None
    logical = lexical_absolute_path(logical)
    source_root = lexical_absolute_path(Path(state["source_dir"]))
    try:
        relative = logical.relative_to(source_root).as_posix()
    except ValueError:
        return None
    matches = [
        output for output in overlay["outputs"]
        if output["logical_path"] == relative
    ]
    require(len(matches) <= 1,
            f"typed source overlay logical path is duplicated: {logical}")
    return (relative, matches[0]) if matches else None


def held_compiler_input_projection_record(
    state: dict, build_dir: Path, projection: dict, logical: Path,
    context: str,
) -> tuple[Path, dict, bool]:
    """Bind a compiler input to clean-snapshot or typed-overlay authority."""
    logical = lexical_absolute_path(logical)
    relative = PurePosixPath(*logical.parts[1:]).as_posix()
    record = projection["immutable_by_path"].get(relative)
    require(record is not None and record.get("type") == "file",
            f"{context} is absent from the held execution projection: {logical}")
    overlay_owner = source_overlay_output_for_logical_path(state, logical)
    if overlay_owner is None:
        command_record = held_command_snapshot_file_record(build_dir, logical)
        require(
            record["sha256"] == command_record["sha256"]
            and record["size"] == command_record["size"],
            f"{context} differs from the held clean command snapshot: {logical}",
        )
        typed = False
    else:
        relative_source, _output = overlay_owner
        expected = state["source_overlay"]["effective_by_path"][relative_source]
        receipt = projection.get("source_overlay_receipt")
        require(
            projection.get("source_overlay_enabled") is True
            and projection.get("source_overlay_policy_sha256")
            == state["source_overlay"]["policy_sha256"]
            and projection.get("source_overlay_actual_records_sha256")
            == state["source_overlay"]["actual_records_sha256"]
            and projection.get("source_overlay_output_count")
            == len(state["source_overlay"]["outputs"])
            and isinstance(receipt, dict)
            and receipt.get("policy_sha256")
            == state["source_overlay"]["policy_sha256"]
            and record["sha256"] == expected["sha256"]
            and record["size"] == expected["size"],
            f"{context} differs from its typed source overlay receipt: {logical}",
        )
        typed = True
    physical = validate_projected_immutable_file_identity(
        projection, logical, record["sha256"], context, executable=False
    )
    return physical, record, typed


def compiler_command_immutable_inputs(
    state: dict, build_dir: Path, projection: dict,
) -> list[dict]:
    """Capture the source and declared force-includes consumed by VC."""
    inventory_entry = state.get("inventory_entry")
    command_entry = state.get("command_entry")
    require(isinstance(inventory_entry, dict)
            and isinstance(command_entry, dict),
            "compiler run lacks its inventory/command authority")
    logical_inputs = [Path(inventory_entry["source_path"])]
    policies = [
        policy for policy in state["target_policies"]
        if policy["target"] == inventory_entry["target"]
    ]
    require(len(policies) == 1,
            "compiler run lacks one force-include policy")
    logical_inputs.extend(
        Path(item["absolute_path"])
        for item in policies[0]["allowed_force_includes"]
    )
    result = []
    seen = set()
    for index, logical in enumerate(logical_inputs):
        logical = lexical_absolute_path(logical)
        require(str(logical) not in seen,
                f"compiler immutable input is duplicated: {logical}")
        seen.add(str(logical))
        physical, record, typed = held_compiler_input_projection_record(
            state, build_dir, projection, logical,
            "compiler source" if index == 0 else "compiler force-include",
        )
        result.append({
            "logical": str(logical), "physical": str(physical),
            "sha256": record["sha256"], "size": record["size"],
            "typed_source_overlay": typed,
        })
    return result


def _capture_compiler_dependencies(
    *, arguments: argparse.Namespace, state: dict, command: list[str],
    source: Path, area: Path,
) -> tuple[object, list[str], list[str], bytes, list[dict], dict]:
    authority = active_build_authority()
    authority.remove_tree(area)
    temporary = area / "tmp"
    authority.mkdirs(temporary)
    output = area / "dependencies.i"
    holder = authority.retain_directories([area, temporary])
    holder.revalidate()
    dependency_command = derive_dependency_command(command, output)
    run = prepare_virtual_z_run(
        state=state, build_dir=arguments.build_dir,
        target=arguments.target, source_relative=state["inventory_entry"]["source"],
        role="dependencies", cwd=Path(state["command_entry"]["directory"]),
        logical_outputs=[output], temporary=temporary,
    )
    accepted = None
    try:
        environment = strict_child_environment(
            state, arguments.build_dir, temporary, run=run
        )
        executed_dependency_command = snapshotted_compiler_command(
            run, state, dependency_command
        )
        with compiler_slot(arguments.build_dir, state["max_child_seconds"]):
            run["holder"].revalidate()
            drain_run_private_wineserver(
                run, state, environment, phase="preflight"
            )
            try:
                validate_virtual_z_prelaunch(
                    run, state, compiler_wrapper_tool(state)
                )
                mark_virtual_z_child_started(run)
                returncode, compiler_output, timed_out = run_child(
                    executed_dependency_command,
                    state["max_child_seconds"], environment,
                    cwd=run["cwd"],
                )
            finally:
                drain_run_private_wineserver(
                    run, state, environment, phase="postflight"
                )
            run["holder"].revalidate()
        require(not timed_out, "compiler dependency pass timed out")
        require(returncode == 0,
                f"compiler dependency pass exited with status {returncode}: "
                f"{compiler_output[-2000:]!r}")
        data = run["holder"].read_bytes(run["outputs"][0])
        reject_virtual_z_path_leak(data, run, "compiler dependency output")
        verify_virtual_z_inputs(run, state)
        require(run["holder"].membership(run["outputs"][0].parent)
                == {
                    run["outputs"][0].name: "file",
                    run["temporary"].name: "directory",
                }
                and not run["holder"].membership(run["temporary"]),
                "compiler dependency pass emitted an undeclared private output")
        records = parse_preprocessed_dependencies(
            data, source, state["command_entry"]["input_trees"],
            virtual_z_root=run["z"],
            virtual_z_records=run["projection"]["immutable_by_path"],
        )
        ledger = require_resident_producer_scope()
        command_z = command_snapshot_path(arguments.build_dir) / "z"
        for record in records:
            logical = Path(record["path"])
            _physical, snapshot_record, typed_overlay = (
                held_compiler_input_projection_record(
                    state, arguments.build_dir, run["projection"], logical,
                    "resident compiler dependency",
                )
            )
            require(snapshot_record["sha256"] == record["sha256"],
                    f"resident compiler dependency snapshot differs: {logical}")
            if ledger is not None and not typed_overlay:
                snapshot = absolute_snapshot_seat(command_z, logical)
                role = "compiler_dependency:" + hashlib.sha256(
                    str(logical).encode("utf-8")
                ).hexdigest()
                ledger.record_root_once(snapshot, role=role)
        cleanup_virtual_z_run(run)
        projection = run["projection"]
        dependency_transport = {
            "schema": 1,
            "policy": "preauthenticated_projection_dependency_pass_v1",
            **execution_projection_audit_identity(run),
            "immutable_entry_count": projection["immutable_entry_count"],
            "immutable_records_sha256": projection[
                "immutable_records_sha256"
            ],
            "toolchain_snapshot_sha256": projection[
                "toolchain_snapshot_sha256"
            ],
            "command_snapshot_sha256": projection[
                "command_snapshot_sha256"
            ],
            "writable_build_branch_cleared": True,
            "run_private_namespace_removed": True,
        }
        accepted = (
            holder, dependency_command, executed_dependency_command,
            data, records,
            dependency_transport,
        )
    finally:
        cleanup_virtual_z_run(run)
    require(accepted is not None,
            "compiler dependency capture produced no accepted result")
    atomic_write(output, accepted[3])
    require(holder.membership(area) == {
                "dependencies.i": "file", "tmp": "directory"
            }
            and holder.membership(temporary) == {},
            "retained compiler dependency namespace differs")
    holder.revalidate()
    return accepted


def capture_compiler_dependencies(
    *, arguments: argparse.Namespace, state: dict, command: list[str],
    source: Path, area: Path,
) -> tuple[object, list[str], list[str], bytes, list[dict], dict]:
    """Capture dependencies or roll back the exact retained dependency area."""
    authority = active_build_authority()
    try:
        return _capture_compiler_dependencies(
            arguments=arguments, state=state, command=command,
            source=source, area=area,
        )
    except BaseException:
        rollback_exact_private_run(authority, area)
        raise


def _consume_virtual_compile_outputs(
    *, run: dict, state: dict, logical_object: Path, logical_pdb: Path,
    retained_object: Path, retained_pdb: Path, retained_temporary: Path,
) -> tuple[bytes, bytes, list[str], list[dict]]:
    """Consume compiler outputs through held fake-Z descriptors, then retain."""
    authority = active_build_authority()
    physical_object, physical_pdb = run["outputs"]
    holder = run["holder"]
    object_bytes = holder.read_bytes(physical_object)
    pdb_bytes = holder.read_bytes(physical_pdb)
    require(object_bytes and pdb_bytes,
            "compiler did not produce its run-private OBJ/PDB")
    reject_virtual_z_path_leak(object_bytes, run, "compiler object")
    reject_virtual_z_path_leak(pdb_bytes, run, "compiler PDB")
    references = embedded_pdb_references_bytes(
        object_bytes, physical_object, logical_pdb
    )
    require(physical_object.parent == physical_pdb.parent,
            "virtual-Z compiler OBJ/PDB physical parents differ")
    membership = holder.membership(physical_object.parent)
    required_names = {physical_object.name, physical_pdb.name}
    optional_names = {
        physical_object.with_suffix(".idb").name: "incremental_state",
        f"{physical_object.name}.sbr": "wrapper_browser_database",
    }
    require(all(membership.get(name) == "file" for name in required_names)
            and set(membership) <= required_names | set(optional_names),
            "virtual-Z compiler output namespace contains undeclared entries")
    require(not holder.membership(run["temporary"]),
            "virtual-Z compiler temporary namespace is not empty")
    physical_auxiliary = []
    for name in sorted(set(membership) & set(optional_names)):
        data = holder.read_bytes(physical_object.parent / name)
        physical_auxiliary.append({
            "kind": optional_names[name], "name": name,
            "path": str(physical_object.parent / name),
            "sha256": sha256_bytes(data), "size": len(data),
        })
    verify_virtual_z_inputs(run, state)

    atomic_write(retained_object, object_bytes)
    atomic_write(retained_pdb, pdb_bytes)
    auxiliary = []
    for record in physical_auxiliary:
        if record["kind"] == "incremental_state":
            name = retained_object.with_suffix(".idb").name
        else:
            name = f"{retained_object.name}.sbr"
        data = holder.read_bytes(Path(record["path"]))
        retained = retained_object.parent / name
        atomic_write(retained, data)
        auxiliary.append({
            "kind": record["kind"], "name": name, "path": str(retained),
            "sha256": sha256_bytes(data), "size": len(data),
        })
    require(not active_build_authority().list_names(retained_temporary),
            "retained compiler temporary directory is not empty")
    holder.revalidate()
    return object_bytes, pdb_bytes, references, auxiliary


def consume_virtual_compile_outputs(
    *, run: dict, state: dict, logical_object: Path, logical_pdb: Path,
    retained_object: Path, retained_pdb: Path, retained_temporary: Path,
) -> tuple[bytes, bytes, list[str], list[dict]]:
    """Consume one run and remove its namespace on success or refusal."""
    authority = active_build_authority()
    try:
        return _consume_virtual_compile_outputs(
            run=run,
            state=state,
            logical_object=logical_object,
            logical_pdb=logical_pdb,
            retained_object=retained_object,
            retained_pdb=retained_pdb,
            retained_temporary=retained_temporary,
        )
    finally:
        cleanup_virtual_z_run(run)


def cleanup_virtual_z_run(run: dict) -> None:
    """Drain Wine, clear/release the shared seat, then remove the tiny run."""
    authority = active_build_authority()
    if run.get("_namespace_removed") is True:
        authority.assert_absent(Path(run["run"]))
        require(run.get("projection_lease_released") is True,
                "removed producer run retains its projection lease")
        return
    require_run_private_wine_quiescent(run)
    holder = run.get("holder")
    if isinstance(holder, HeldBuildDirectories):
        holder.close()
    if run.get("projection_lease_released") is not True:
        release_execution_projection(run)
    run_path = run.get("run")
    require(isinstance(run_path, Path), "virtual-Z run has no cleanup identity")
    authority.remove_tree(run_path)
    authority.assert_absent(run_path)
    run["_namespace_removed"] = True
    require_exact_build_namespace(
        authority, Path(run["projection"]["runs_root"]), {},
        "execution transaction run namespace after cleanup",
        replace_pin=True,
    )


def cleanup_virtual_z_runs_aggregate(runs: list[dict | None]) -> None:
    """Attempt every owned cleanup and fail unless all absences are proven."""
    errors = []
    for run in runs:
        if run is None or run.get("_namespace_removed") is True:
            continue
        try:
            cleanup_virtual_z_run(run)
            run["_namespace_removed"] = True
        except BaseException as error:
            errors.append(f"{run.get('run')}: {error}")
    require(not errors,
            "private producer aggregate cleanup could not be proven: "
            + "; ".join(errors))


def execution_projection_audit_identity(run: dict) -> dict:
    projection = run.get("projection")
    require(
        isinstance(projection, dict)
        and run.get("projection_lease_released") is True
        and run.get("_namespace_removed") is True
        and run.get("input_postflight_clear") is True,
        "producer projection evidence precedes cleanup/postflight",
    )
    return {
        "execution_projection_root": projection["root"],
        "execution_projection_descriptor_sha256": projection[
            "descriptor_sha256"
        ],
    }


def virtual_transport_audit(run: dict, cwd: Path, object_path: Path, pdb_path: Path) -> dict:
    projection = run["projection"]
    require(
        run.get("projection_lease_released") is True
        and run.get("_namespace_removed") is True
        and run.get("input_postflight_clear") is True,
        "compiler transport audit precedes private namespace cleanup",
    )
    return {
        "schema": 1,
        "policy": "transaction_execution_projection_v1",
        "backend": projection["backend"],
        "backend_details": {
            "schema": "posix_wine_private_prefix_v1",
            "server_shutdown_policy": "prefix_scoped_kill_wait_bounded_v1",
            "server_preflight_clear": run["server_preflight_clear"],
            "server_postflight_clear": run["server_postflight_clear"],
        },
        "logical_cwd": str(cwd),
        "logical_object": str(object_path),
        "logical_pdb": str(pdb_path),
        "toolchain_snapshot_sha256": run["toolchain_snapshot_sha256"],
        "command_snapshot_sha256": run["command_snapshot_sha256"],
        **execution_projection_audit_identity(run),
        "execution_projection_policy":
            "transaction_scoped_immutable_inputs_single_writable_build_seat_v1",
        "execution_projection_seat_capacity": projection["seat_capacity"],
        "execution_projection_writable_empty_prelease": True,
        "execution_projection_input_postflight_clear": True,
        "execution_projection_lease_released": True,
        "run_private_namespace_removed": True,
    }


def validate_compiler_logical_input_policy(
    state: dict, logical: Path, expected_sha256: str, context: str,
) -> str:
    """Validate clean inputs now; defer typed bytes to the held projection."""
    require(SHA256_RE.fullmatch(expected_sha256) is not None,
            f"{context} expected SHA-256 is invalid")
    owner = source_overlay_output_for_logical_path(state, logical)
    if owner is None:
        require(sha256_file(logical) == expected_sha256,
                f"{context} changed: {logical}")
        return expected_sha256
    relative, _output = owner
    effective = state["source_overlay"]["effective_by_path"][relative]
    require(effective["sha256"] == expected_sha256,
            f"{context} typed source overlay identity differs: {logical}")
    return expected_sha256


def compile_unlisted_atomically(
    *,
    arguments: argparse.Namespace,
    state: dict,
    child: list[str],
    configured: Path,
    source: Path,
    source_relative: str,
    expected_object: Path,
    expected_pdb: Path,
) -> int:
    """Run an unlisted TU through the same atomic/process-safety envelope.

    ``CXX_COMPILER_LAUNCHER`` is target-wide, so every source in a target that
    owns one manifest-listed TU passes through this program.  Unlisted sources
    do not receive entropy or claim composition, but they must not bypass the
    sanitized environment, private outputs, watchdog, or post-compile pins.
    """
    authority = active_build_authority()
    inventory_entry = state["inventory_entry"]
    source_before = (
        inventory_entry["effective_source_sha256"]
        if state["source_overlay"]["enabled"] else sha256_file(source)
    )
    validate_compiler_logical_input_policy(
        state, source, source_before, "unlisted compiler source"
    )
    audit_path = audit_unlisted_path(
        arguments.build_dir, arguments.target, source_relative
    )
    require(authority.parts(Path(state["inventory_entry"]["audit"]))
            == authority.parts(audit_path),
            "unlisted compiler audit output differs from configure inventory")
    folded = [value.casefold() for value in child]
    require("/zi" in folded or "-zi" in folded,
            "unlisted byte-identity compile is missing /Zi")
    require("/c" in folded or "-c" in folded,
            "unlisted byte-identity compile is not compile-only")
    require(not any(
        value.startswith(prefix)
        for value in folded
        for prefix in ("/gl", "-gl", "/z7", "-z7")
    ), "unlisted byte-identity compile uses a forbidden code/debug mode")

    observed_force_includes = force_include_arguments(child, Path.cwd().resolve())
    target_policies = [
        policy for policy in state["target_policies"]
        if policy["target"] == arguments.target
    ]
    require(len(target_policies) == 1,
            "unlisted compile has no unique manifest policy for its target")
    declared_force_includes = [
        (Path(item["absolute_path"]).resolve(), item["sha256"])
        for item in target_policies[0]["allowed_force_includes"]
    ]
    require(
        observed_force_includes == [path for path, _ in declared_force_includes],
        "unlisted compiler force-include set/order differs from pinned policy",
    )
    for path, expected in declared_force_includes:
        validate_compiler_logical_input_policy(
            state, path, expected, "unlisted force-include"
        )

    source_id = hashlib.sha256(source_relative.encode("utf-8")).hexdigest()[:16]
    work = (
        authority.build_root
        / "byte-identity/work/unlisted-pass-through"
        / arguments.target
        / source_id
    )
    compile_area = work / "seed"
    temporary = compile_area / "tmp"
    authority.mkdirs(work)
    (
        dependency_holder,
        dependency_command,
        dependency_executed_command,
        dependency_bytes,
        consumed_dependencies,
        dependency_transport,
    ) = capture_compiler_dependencies(
        arguments=arguments,
        state=state,
        command=child,
        source=source,
        area=work / "dependencies",
    )
    # `/Gm` consumes compiler state derived from `/Fo`/`/Fd`.  Removing the
    # complete area, rather than only the public OBJ/PDB leaves, makes an IDB
    # from a prior or attacker-seeded invocation impossible to consume.
    authority.remove_tree(compile_area)
    authority.mkdirs(temporary)
    private_object = compile_area / "output.obj"
    private_pdb = compile_area / "output.pdb"
    final_object = expected_object
    final_pdb = expected_pdb
    authority.mkdirs(final_object.parent)
    authority.mkdirs(final_pdb.parent)
    started = time.monotonic()
    private_paths = authority.retain_directories(
        [private_object.parent, private_pdb.parent, temporary]
    )
    run = None
    try:
        require_fresh_compiler_area(
            private_paths, compile_area, temporary
        )
        run = prepare_virtual_z_run(
            state=state, build_dir=arguments.build_dir,
            target=arguments.target, source_relative=source_relative,
            role="seed", cwd=Path(state["command_entry"]["directory"]),
            logical_outputs=[final_object, final_pdb], temporary=temporary,
        )
        environment = strict_child_environment(
            state, arguments.build_dir, temporary, run=run
        )
        executed_command = snapshotted_compiler_command(run, state, child)
        with compiler_slot(arguments.build_dir, state["max_child_seconds"]):
            run["holder"].revalidate()
            drain_run_private_wineserver(
                run, state, environment, phase="preflight"
            )
            try:
                validate_virtual_z_prelaunch(
                    run, state, compiler_wrapper_tool(state)
                )
                mark_virtual_z_child_started(run)
                returncode, output, timed_out = run_child(
                    executed_command,
                    state["max_child_seconds"],
                    environment,
                    cwd=run["cwd"],
                )
            finally:
                drain_run_private_wineserver(
                    run, state, environment, phase="postflight"
                )
            run["holder"].revalidate()
        sys.stdout.buffer.write(output)
        sys.stdout.buffer.flush()
        if timed_out:
            raise ByteIdentityError(
                f"compiler timed out after {state['max_child_seconds']} seconds"
            )
        require(returncode == 0, f"compiler exited with status {returncode}")
        (
            private_object_bytes,
            private_pdb_bytes,
            private_pdb_references,
            private_auxiliary_outputs,
        ) = consume_virtual_compile_outputs(
            run=run, state=state,
            logical_object=final_object, logical_pdb=final_pdb,
            retained_object=private_object, retained_pdb=private_pdb,
            retained_temporary=temporary,
        )
        transport_audit = virtual_transport_audit(
            run, Path(state["command_entry"]["directory"]),
            final_object, final_pdb,
        )
        private_paths.revalidate()
    except BaseException as error:
        cleanup_errors = []
        if run is not None:
            try:
                cleanup_virtual_z_run(run)
            except (ByteIdentityError, OSError, ValueError) as cleanup_error:
                cleanup_errors.append(str(cleanup_error))
        try:
            invalidate_build_paths([private_object, private_pdb])
        except (ByteIdentityError, OSError, ValueError) as cleanup_error:
            cleanup_errors.append(str(cleanup_error))
        try:
            authority.remove_tree(compile_area)
        except (ByteIdentityError, OSError, ValueError) as cleanup_error:
            cleanup_errors.append(str(cleanup_error))
        if cleanup_errors:
            raise ByteIdentityError(
                "private unlisted compiler failure cleanup could not be proven: "
                + "; ".join(cleanup_errors)
            ) from error
        raise

    validate_producer_state_postflight(arguments, state)
    validate_compiler_logical_input_policy(
        state, source, source_before, "unlisted compiler source postflight"
    )
    for path, expected in declared_force_includes:
        validate_compiler_logical_input_policy(
            state, path, expected, "unlisted force-include postflight"
        )

    audit = {
        "status": "unlisted_atomic_pass_through",
        "may_claim_byte_identity": False,
        "manifest_sha256": state["manifest_sha256"],
        "compiler_sha256": sha256_file(configured),
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "framework_tool_sha256": state["framework_tool_sha256"],
        "backend_tool_sha256": state["backend_tool_sha256"],
        "entropy_tool_sha256": state["entropy_tool_sha256"],
        "target": arguments.target,
        "source": source_relative,
        "source_sha256": source_before,
        "input_command_sha256": sha256_bytes(
            json.dumps(child, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
        ),
        "executed_command_sha256": sha256_bytes(
            json.dumps(
                executed_command, ensure_ascii=True, separators=(",", ":")
            ).encode("utf-8")
        ),
        "python_sha256": state["python_sha256"],
        "python_version": state["python_version"],
        "child_environment": state["child_environment"],
        "inventory_sha256": state["inventory_sha256"],
        "policy_sha256": state["inventory"]["policy_sha256"],
        "command_inventory_sha256": state["command_inventory_sha256"],
        "command_policy_sha256": state["command_policy_sha256"],
        "configured_argv_sha256": state["command_entry"]["argv_sha256"],
        "transport": transport_audit,
        "dependency_output": str(work / "dependencies/dependencies.i"),
        "dependency_output_sha256": sha256_bytes(dependency_bytes),
        "dependency_command_sha256": sha256_bytes(json.dumps(
            dependency_command, ensure_ascii=True, separators=(",", ":")
        ).encode("utf-8")),
        "dependency_executed_command_sha256": stable_argv_sha256(
            dependency_executed_command
        ),
        "consumed_dependencies": consumed_dependencies,
        "dependency_transport": dependency_transport,
        "compiler_semaphore_max": MAX_COMPILER_PROCESSES,
        "object": str(final_object),
        "object_sha256": sha256_bytes(private_object_bytes),
        "pdb": str(final_pdb),
        "pdb_sha256": sha256_bytes(private_pdb_bytes),
        "private_object": str(private_object),
        "private_object_sha256": sha256_bytes(private_object_bytes),
        "private_pdb": str(private_pdb),
        "private_pdb_sha256": sha256_bytes(private_pdb_bytes),
        "embedded_pdb_references": private_pdb_references,
        "private_auxiliary_outputs": private_auxiliary_outputs,
        "elapsed_seconds": round(time.monotonic() - started, 6),
    }
    validate_first_party_object_directive(
        private_object_bytes,
        f"compiler output {arguments.target}:{source_relative}",
    )
    try:
        atomic_write(final_pdb, private_pdb_bytes)
        atomic_write(final_object, private_object_bytes)
        atomic_json(audit_path, audit)
        private_paths.revalidate()
        dependency_holder.revalidate()
    except BaseException:
        invalidate_build_paths([final_object, final_pdb, audit_path])
        raise
    return 0


def command_compile_launch_locked(
    arguments: argparse.Namespace, child: list[str]
) -> int:
    require_resident_producer_scope()
    authority = active_build_authority()
    cwd = Path.cwd().resolve()
    source, source_relative, provisional_entry = (
        configured_inventory_source_for_command(
            arguments.build_dir,
            arguments.source_dir,
            arguments.target,
            child,
            cwd,
        )
    )
    lock_identity = str(source)
    lock_id = hashlib.sha256(lock_identity.encode("utf-8")).hexdigest()[:16]
    acquire_build_lock(
        authority.build_root
        / "byte-identity/locks"
        / arguments.target
        / f"{lock_id}.lock",
        f"{arguments.target}:{lock_identity}",
    )
    # The narrow inventory attribution above is enough to remove both possible
    # audit dispositions before trusting the manifest or the rest of argv.
    invalidate_build_paths([
        audit_object_path(arguments.build_dir, arguments.target, source_relative),
        audit_unlisted_path(arguments.build_dir, arguments.target, source_relative),
    ])
    provisional = provisional_valued_options(child)
    output_paths = []
    for option in ("Fo", "Fd"):
        matches = provisional[option]
        if len(matches) == 1 and matches[0][1]:
            candidate = lexical_argument_path(matches[0][1], cwd)
            authority.parts(candidate)
            output_paths.append(candidate)
    invalidate_build_paths(output_paths)
    parsed_command = validate_compile_arguments(child)
    expected_object = lexical_argument_path(parsed_command["Fo"][1], cwd)
    expected_pdb = lexical_argument_path(parsed_command["Fd"][1], cwd)
    authority.parts(expected_object)
    authority.parts(expected_pdb)
    state, inventory, command_inventory, _session = load_producer_state(
        arguments
    )
    inventory_matches = [
        entry for entry in inventory["entries"]
        if entry["target"] == arguments.target
        and entry["source"] == source_relative
    ]
    require(len(inventory_matches) == 1,
            "compiler TU is absent or duplicated in configure inventory")
    inventory_entry = inventory_matches[0]
    require(exact_json_equal(inventory_entry, provisional_entry),
            "compiler source attribution changed during inventory authentication")
    command_matches = [
        entry for entry in command_inventory["entries"]
        if entry["target"] == arguments.target
        and entry["source"] == source_relative
    ]
    require(len(command_matches) == 1,
            "compiler TU has no unique generated command policy")
    command_entry = command_matches[0]
    require(exact_json_equal(child, command_entry["argv"]),
            "runtime compiler argv differs from the generated command inventory")
    if inventory_entry["language"] == "CXX":
        validate_generated_cxx_semantic_profile(
            parsed_command, "runtime generated CXX command"
        )
    require(cwd == Path(command_entry["directory"]),
            "runtime compiler working directory differs from command inventory")
    require(expected_object == Path(command_entry["object"])
            and expected_pdb == Path(command_entry["pdb"]),
            "runtime compiler outputs differ from command inventory")
    require(
        resolved_argument_path(parsed_command["source_token"], cwd) == source,
        "compiler final source differs from configure inventory",
    )
    for role, value in parsed_command["role_operands"]:
        try:
            reused_source = resolved_argument_path(value, cwd) == source
        except (OSError, ValueError):
            reused_source = False
        require(
            not reused_source,
            f"configured source is reused as a /{role} option operand",
        )
    if parsed_command["language_mode"] is not None:
        require(
            parsed_command["language_mode"] == inventory_entry["language"],
            "compiler-wide /TC or /TP language mode differs from configure inventory",
        )
    implicit_language = implicit_cmake_source_language(source)
    if implicit_language != inventory_entry["language"]:
        require(
            parsed_command["language_mode"] == inventory_entry["language"],
            "compiler command needs exact /TC or /TP to prove the configured source language",
        )
    state["inventory"] = inventory
    state["inventory_entry"] = inventory_entry
    state["inventory_sha256"] = sha256_file(inventory_path(arguments.build_dir))
    state["command_inventory"] = command_inventory
    state["command_entry"] = command_entry
    state["command_inventory_sha256"] = sha256_file(
        command_inventory_path(arguments.build_dir)
    )
    state["command_policy_sha256"] = command_inventory["policy_sha256"]
    configured = compiler_path(arguments.configured_compiler)
    compiler_positions = []
    for index, value in enumerate(child):
        try:
            if Path(value).exists() and Path(value).resolve() == configured:
                compiler_positions.append(index)
        except OSError:
            pass
    require(compiler_positions == [0],
            "child command must begin with the pinned compiler exactly once")

    matches = [
        unit
        for unit in state["translation_units"]
        if unit["target"] == arguments.target and unit["source"] == source_relative
    ]
    if not matches:
        require(inventory_entry["listed"] is False,
                "unlisted compiler TU has a listed inventory disposition")
        return compile_unlisted_atomically(
            arguments=arguments,
            state=state,
            child=child,
            configured=configured,
            source=source,
            source_relative=source_relative,
            expected_object=expected_object,
            expected_pdb=expected_pdb,
        )
    require(len(matches) == 1, "manifest translation unit is not unique")
    require(inventory_entry["listed"] is True,
            "listed compiler TU has an unlisted inventory disposition")
    unit = matches[0]
    audit_path = audit_object_path(arguments.build_dir, unit["target"], source_relative)
    require(authority.parts(Path(inventory_entry["audit"]))
            == authority.parts(audit_path),
            "listed compiler audit output differs from configure inventory")
    invalidate_build_paths([audit_path])
    validate_compiler_logical_input_policy(
        state, source, unit["source_sha256"], "listed compiler source"
    )
    for required in unit["command_policy"]["required_flags"]:
        require(required in child, f"required exact compiler flag is absent: {required}")
    folded = [value.casefold() for value in child]
    for prefix in unit["command_policy"]["forbidden_prefixes"]:
        require(not any(value.startswith(prefix.casefold()) for value in folded),
                f"forbidden compiler option is present: {prefix}")
    observed_force_includes = force_include_arguments(child, cwd)
    allowed_force_includes = [
        Path(item["absolute_path"]).resolve()
        for item in unit["command_policy"]["allowed_force_includes"]
    ]
    require(observed_force_includes == allowed_force_includes,
            "compiler force-include set/order differs from the pinned policy")
    for item in unit["command_policy"]["allowed_force_includes"]:
        validate_compiler_logical_input_policy(
            state, Path(item["absolute_path"]), item["sha256"],
            "listed force-include",
        )
    for donor in unit["donors"]:
        output = Path(donor["header_output"])
        require(authority.is_regular_file(output),
                f"materialized declaration header is absent: {output}")
        require(sha256_file(output) == donor["recipe"]["generated_header_sha256"],
                f"materialized declaration header changed: {output}")

    source_id = hashlib.sha256(source_relative.encode("utf-8")).hexdigest()[:16]
    work = (
        authority.build_root
        / "byte-identity/work"
        / arguments.target
        / source_id
    )
    authority.mkdirs(work)
    private_holders = []

    (
        dependency_holder,
        dependency_command,
        dependency_executed_command,
        dependency_bytes,
        consumed_dependencies,
        dependency_transport,
    ) = capture_compiler_dependencies(
        arguments=arguments,
        state=state,
        command=child,
        source=source,
        area=work / "dependencies",
    )
    private_holders.append(dependency_holder)

    def fresh_compile_area(name: str) -> tuple[Path, Path, Path]:
        area = work / name
        authority.parts(area)
        require(area != work, "private compiler area aliases its TU work directory")
        authority.remove_tree(area)
        temporary = area / "tmp"
        authority.mkdirs(temporary)
        return area / "output.obj", area / "output.pdb", temporary

    def compile_one(
        command: list[str], private_object: Path, private_pdb: Path,
        temporary: Path, log_name: str, role: str,
        generated_inputs: list[Path] | None = None,
    ) -> tuple[list[str], bytes, bytes, list[str], list[dict], dict]:
        run = None
        try:
            run = prepare_virtual_z_run(
                state=state, build_dir=arguments.build_dir,
                target=arguments.target, source_relative=source_relative,
                role=role, cwd=cwd,
                logical_outputs=[expected_object, expected_pdb],
                temporary=temporary, generated_inputs=generated_inputs,
            )
            environment = strict_child_environment(
                state, arguments.build_dir, temporary, run=run
            )
            executed_command = snapshotted_compiler_command(
                run, state, command
            )
            private_paths = authority.retain_directories(
                [private_object.parent, private_pdb.parent, temporary]
            )
            private_holders.append(private_paths)
            require_fresh_compiler_area(
                private_paths, private_object.parent, temporary
            )
            with compiler_slot(arguments.build_dir, state["max_child_seconds"]):
                run["holder"].revalidate()
                drain_run_private_wineserver(
                    run, state, environment, phase="preflight"
                )
                try:
                    validate_virtual_z_prelaunch(
                        run, state, compiler_wrapper_tool(state)
                    )
                    mark_virtual_z_child_started(run)
                    returncode, compiler_output, timed_out = run_child(
                        executed_command,
                        state["max_child_seconds"],
                        environment,
                        cwd=run["cwd"],
                    )
                finally:
                    drain_run_private_wineserver(
                        run, state, environment, phase="postflight"
                    )
                run["holder"].revalidate()
            sys.stdout.buffer.write(compiler_output)
            sys.stdout.buffer.flush()
            if timed_out:
                raise ByteIdentityError(
                    f"compiler timed out after {state['max_child_seconds']} seconds"
                )
            require(returncode == 0, f"compiler exited with status {returncode}")
            (
                object_bytes, pdb_bytes, references, auxiliary_outputs,
            ) = consume_virtual_compile_outputs(
                run=run, state=state,
                logical_object=expected_object, logical_pdb=expected_pdb,
                retained_object=private_object, retained_pdb=private_pdb,
                retained_temporary=temporary,
            )
            transport_audit = virtual_transport_audit(
                run, cwd, expected_object, expected_pdb
            )
            private_paths.revalidate()
            return (
                executed_command,
                object_bytes,
                pdb_bytes,
                references,
                auxiliary_outputs,
                transport_audit,
            )
        except BaseException as error:
            cleanup_errors = []
            if run is not None:
                try:
                    cleanup_virtual_z_run(run)
                except (ByteIdentityError, OSError, ValueError) as cleanup_error:
                    cleanup_errors.append(str(cleanup_error))
            try:
                invalidate_build_paths([private_object, private_pdb])
            except (ByteIdentityError, OSError, ValueError) as cleanup_error:
                cleanup_errors.append(str(cleanup_error))
            try:
                authority.remove_tree(private_object.parent)
            except (ByteIdentityError, OSError, ValueError) as cleanup_error:
                cleanup_errors.append(str(cleanup_error))
            if cleanup_errors:
                raise ByteIdentityError(
                    "private compiler failure cleanup could not be proven: "
                    + "; ".join(cleanup_errors)
                ) from error
            raise

    seed_object, seed_pdb, seed_temporary = fresh_compile_area("seed")
    final_object = expected_object
    final_pdb = expected_pdb
    authority.mkdirs(final_object.parent)
    authority.mkdirs(final_pdb.parent)
    started = time.monotonic()
    (
        seed_command,
        seed_object_bytes,
        seed_pdb_bytes,
        seed_pdb_references,
        seed_auxiliary_outputs,
        seed_transport,
    ) = compile_one(
        child, seed_object, seed_pdb, seed_temporary,
        "seed-compile.log", "seed",
    )
    seed_object_sha = sha256_bytes(seed_object_bytes)
    seed_pdb_sha = sha256_bytes(seed_pdb_bytes)

    donor_outputs = {}
    donor_audits = []
    if unit["mode"] == "compose_equal_linked_span_fpo":
        for donor in unit["donors"]:
            donor_object, donor_pdb, donor_temporary = fresh_compile_area(
                f"donor-{donor['id']}"
            )
            header = authority.path(authority.parts(Path(donor["header_output"])))
            # The launcher and Wine wrapper do not have a shared, contractual
            # working directory.  Pass the pinned build-tree header absolutely
            # so the wrapper can translate it to an unambiguous DOS path.
            donor_command = list(child)
            # Preserve the attested terminal /Fo /Fd -c <SOURCE> quartet.
            # Declaration-only shape inputs are ordinary pre-source options.
            donor_command.insert(parsed_command["Fo"][0], f"/FI{header}")
            require(
                force_include_arguments(donor_command, cwd)
                == [*allowed_force_includes, header],
                "derived donor command has an unexpected force-include order",
            )
            (
                executed,
                object_bytes,
                pdb_bytes,
                pdb_references,
                auxiliary_outputs,
                donor_transport,
            ) = compile_one(
                donor_command,
                donor_object,
                donor_pdb,
                donor_temporary,
                f"donor-{donor['id']}-compile.log",
                f"donor-{donor['id']}",
                [header],
            )
            donor_outputs[donor["id"]] = object_bytes
            donor_audits.append(
                {
                    "recipe_id": donor["id"],
                    "header": str(header),
                    "header_sha256": sha256_file(header),
                    "object": str(donor_object),
                    "object_sha256": sha256_bytes(object_bytes),
                    "pdb": str(donor_pdb),
                    "pdb_sha256": sha256_bytes(pdb_bytes),
                    "embedded_pdb_references": pdb_references,
                    "auxiliary_outputs": auxiliary_outputs,
                    "transport": donor_transport,
                    "executed_command_sha256": sha256_bytes(
                        json.dumps(executed, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
                    ),
                }
            )
    post_state, _post_inventory, _post_commands, _post_session = (
        validate_producer_state_postflight(arguments, state)
    )
    post_matches = [
        candidate
        for candidate in post_state["translation_units"]
        if candidate["target"] == arguments.target
        and candidate["source"] == source_relative
    ]
    require(len(post_matches) == 1, "translation unit changed during compilation")
    post_unit = post_matches[0]
    require(exact_json_equal(post_unit, unit),
            "translation-unit recipe changed during compilation")
    validate_compiler_logical_input_policy(
        post_state, source, post_unit["source_sha256"],
        "listed compiler source postflight",
    )
    for item in post_unit["command_policy"]["allowed_force_includes"]:
        validate_compiler_logical_input_policy(
            post_state, Path(item["absolute_path"]), item["sha256"],
            "listed force-include postflight",
        )
    for donor in post_unit["donors"]:
        require(sha256_file(Path(donor["header_output"]))
                == donor["recipe"]["generated_header_sha256"],
                f"materialized declaration header changed during compile: {donor['header_output']}")
    composition = []
    output_bytes = seed_object_bytes
    if unit["mode"] == "compose_equal_linked_span_fpo":
        donors_by_id = {donor["id"]: donor for donor in post_unit["donors"]}
        for function in post_unit["functions"]:
            donor = donors_by_id[function["donor"]]
            header_bytes = authority.read_bytes(Path(donor["header_output"]))
            output_bytes, detail = compose_equal_linked_span_fpo(
                output_bytes,
                donor_outputs[donor["id"]],
                function,
                declaration_identifiers(header_bytes),
            )
            detail["recipe_id"] = donor["id"]
            composition.append(detail)
        private_final_object = work / "composed.obj"
        atomic_write(private_final_object, output_bytes)
        status = "compiler_output_fpo_composed"
    else:
        private_final_object = seed_object
        status = "pass_through_not_composed"

    audit = {
        "status": status,
        "may_claim_byte_identity": False,
        "manifest_sha256": state["manifest_sha256"],
        "compiler_sha256": sha256_file(configured),
        "toolchain_fingerprint": state["toolchain_fingerprint"],
        "framework_tool_sha256": state["framework_tool_sha256"],
        "backend_tool_sha256": state["backend_tool_sha256"],
        "entropy_tool_sha256": state["entropy_tool_sha256"],
        "python_sha256": state["python_sha256"],
        "python_version": state["python_version"],
        "child_environment": state["child_environment"],
        "inventory_sha256": state["inventory_sha256"],
        "policy_sha256": state["inventory"]["policy_sha256"],
        "command_inventory_sha256": state["command_inventory_sha256"],
        "command_policy_sha256": state["command_policy_sha256"],
        "configured_argv_sha256": state["command_entry"]["argv_sha256"],
        "transport": seed_transport,
        "dependency_output": str(work / "dependencies/dependencies.i"),
        "dependency_output_sha256": sha256_bytes(dependency_bytes),
        "dependency_command_sha256": sha256_bytes(json.dumps(
            dependency_command, ensure_ascii=True, separators=(",", ":")
        ).encode("utf-8")),
        "dependency_executed_command_sha256": stable_argv_sha256(
            dependency_executed_command
        ),
        "consumed_dependencies": consumed_dependencies,
        "dependency_transport": dependency_transport,
        "compiler_semaphore_max": MAX_COMPILER_PROCESSES,
        "target": unit["target"],
        "source": source_relative,
        "source_sha256": unit["source_sha256"],
        "input_command_sha256": sha256_bytes(
            json.dumps(child, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
        ),
        "seed_executed_command_sha256": sha256_bytes(
            json.dumps(seed_command, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
        ),
        "recipes": [donor["id"] for donor in unit["donors"]],
        "recipes_materialized_but_not_injected": unit["mode"] == "pass_through",
        "recipes_compiled_and_injected": unit["mode"] == "compose_equal_linked_span_fpo",
        "seed_object": str(seed_object),
        "seed_object_sha256": seed_object_sha,
        "seed_pdb": str(seed_pdb),
        "seed_pdb_sha256": seed_pdb_sha,
        "seed_embedded_pdb_references": seed_pdb_references,
        "seed_auxiliary_outputs": seed_auxiliary_outputs,
        "donors": donor_audits,
        "composition": composition,
        "retail_payload_bytes_read": 0,
        "object": str(final_object),
        "object_sha256": sha256_bytes(output_bytes),
        "pdb": str(final_pdb),
        "pdb_sha256": seed_pdb_sha,
        "elapsed_seconds": round(time.monotonic() - started, 6),
        "completion": unit["completion"],
    }
    validate_first_party_object_directive(
        output_bytes, f"compiler output {unit['target']}:{source_relative}"
    )
    try:
        atomic_write(final_pdb, seed_pdb_bytes)
        atomic_write(final_object, output_bytes)
        atomic_json(audit_path, audit)
        for private_paths in private_holders:
            private_paths.revalidate()
    except BaseException:
        invalidate_build_paths([final_object, final_pdb, audit_path])
        raise
    print(json.dumps({"byte_identity": audit}, sort_keys=True))
    return 0


def command_compile_launch(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    child = list(arguments.child)
    if child and child[0] == "--":
        child.pop(0)
    has_response_file = any(
        value.strip().lstrip("\"'").startswith("@") for value in child
    )
    if has_response_file:
        with build_transaction(arguments.build_dir, exclusive=True):
            invalidate_response_file_compiler_state(
                arguments.build_dir, child, Path.cwd().resolve()
            )
            raise ByteIdentityError("compiler response-file arguments are forbidden")
    raw_errors = raw_argument_token_errors(child)
    if raw_errors:
        # Literal shell quoting/escaping makes even the final source token
        # unattributable.  Drain shared compiles and remove the complete prior
        # compiler claim universe rather than selecting a possibly forged TU.
        with build_transaction(arguments.build_dir, exclusive=True):
            invalidate_response_file_compiler_state(
                arguments.build_dir, child, Path.cwd().resolve()
            )
        raise ByteIdentityError("; ".join(raw_errors))
    try:
        with build_transaction(arguments.build_dir, exclusive=False):
            if not child:
                raise CompilerAttributionError(
                    "compile-launch received no compiler command"
                )
            if TARGET_RE.fullmatch(arguments.target) is None:
                raise CompilerAttributionError("compile-launch target is invalid")
            invalidate_framework_verdict(arguments.build_dir)
            return command_compile_launch_locked(arguments, child)
    except CompilerAttributionError:
        # Without one exact final inventory source, no per-TU namespace can be
        # selected soundly. Drain shared compiles, then invalidate the entire
        # prior compiler claim/output universe under exclusive authority.
        with build_transaction(arguments.build_dir, exclusive=True):
            invalidate_response_file_compiler_state(
                arguments.build_dir, child, Path.cwd().resolve()
            )
        raise


def expected_top_level_audit_namespace(
    state: dict, inventory: dict, *, include_reccmp: bool = False,
) -> dict[str, str]:
    expected = {}
    if state.get("source_overlay", {}).get("enabled"):
        expected["source-overlay.json"] = "file"
    if state["recipes"]:
        expected["materialization"] = "directory"
    if state["archives"]:
        expected["archives"] = "directory"
    if state["images"] and any(
        item["kind"] == "RC" for item in inventory.get("inputs", [])
    ):
        expected["resources"] = "directory"
    if state["images"] and any(
        item["kind"] == "STATIC_LIBRARY"
        for item in inventory.get("targets", [])
    ):
        expected["first-party-archives"] = "directory"
    if state["images"]:
        expected["links"] = "directory"
        if include_reccmp:
            expected["reccmp"] = "directory"
    if any(entry["listed"] is True for entry in inventory["entries"]):
        expected["objects"] = "directory"
    if any(entry["listed"] is False for entry in inventory["entries"]):
        expected["unlisted-pass-through"] = "directory"
    return expected


def expected_terminal_final_namespace(*, include_reccmp: bool) -> dict[str, str]:
    expected = {
        "LEGO1.map": "file",
        "LEGO1-link.log": "file",
        "LEGO1-analysis.dll": "file",
        "LEGO1-analysis.lib": "file",
        "LEGO1-analysis.exp": "file",
        "LEGO1-analysis.map": "file",
        "LEGO1-analysis-link.log": "file",
    }
    if include_reccmp:
        expected.update({
            "LEGO1.json": "file",
            "LEGO1-reccmp.log": "file",
        })
    return expected


def framework_source_overlay_verdict_identity(state: dict) -> dict:
    """Return the compact same-transaction overlay identity for a verdict."""
    overlay = state["source_overlay"]
    if not overlay["enabled"]:
        return {
            "source_overlay_enabled": False,
            "source_overlay_policy_sha256": None,
            "source_overlay_actual_records_sha256": None,
            "source_overlay_receipt_sha256": None,
            "source_overlay_output_count": 0,
        }
    authority = active_build_authority()
    projection = authority.execution_projection
    receipt = authority.execution_projection_receipt
    require(
        isinstance(projection, dict)
        and projection.get("finalized") is True
        and projection.get("removed") is True
        and isinstance(receipt, dict),
        "framework verdict lacks the terminal same-transaction source overlay",
    )
    validate_execution_projection_source_overlay_evidence(
        state, receipt, "framework verdict"
    )
    return {
        key: receipt[key] for key in (
            "source_overlay_enabled", "source_overlay_policy_sha256",
            "source_overlay_actual_records_sha256",
            "source_overlay_receipt_sha256", "source_overlay_output_count",
        )
    }


def command_verify_locked(
    arguments: argparse.Namespace, *, publish: bool = True,
    include_reccmp: bool = False,
) -> int | dict:
    authority = active_build_authority()
    verdict_path = invalidate_framework_verdict(arguments.build_dir)
    authority.begin_verification_epoch()
    state, inventory, command_inventory, outer_session = (
        terminal_verification_inputs(arguments)
    )
    inventory_sha = state["inventory_sha256"]
    command_inventory_sha = state["command_inventory_sha256"]
    command_by_owner = {
        (entry["target"], entry["source"]): entry
        for entry in command_inventory["entries"]
    }
    require(len(command_by_owner) == len(command_inventory["entries"]),
            "generated command inventory contains duplicate owners")
    require_exact_build_namespace(
        authority,
        authority.build_root / "byte-identity/locks/compiler-slots",
        {
            f"slot-{index}.lock": "file"
            for index in range(MAX_COMPILER_PROCESSES)
        },
        "compiler semaphore namespace",
    )
    inventory_by_owner = {
        (entry["target"], entry["source"]): entry
        for entry in inventory["entries"]
    }
    require(len(inventory_by_owner) == len(inventory["entries"]),
            "configure inventory contains duplicate owners")
    build_root = authority.build_root
    expected_audits = {
        authority.path(authority.parts(Path(entry["audit"])))
        for entry in inventory["entries"]
    }
    audit_root = authority.build_root / "byte-identity/audit"
    audit_root_expected = expected_top_level_audit_namespace(
        state, inventory, include_reccmp=include_reccmp
    )
    require_exact_build_namespace(
        authority,
        audit_root,
        audit_root_expected,
        "top-level byte-identity audit namespace",
    )
    actual_audits = set(compiler_audit_files(arguments.build_dir))
    require(actual_audits == expected_audits,
            "compiler audit universe has missing or extra outputs")
    audit_roots = {tuple(root.parts) for root in COMPILER_AUDIT_RELATIVE_ROOTS}
    allowed_audit_directories = set(audit_roots)
    required_audit_directories = set()
    for audit_path in expected_audits:
        audit_parts = authority.parts(audit_path)
        matching_roots = [
            root for root in audit_roots
            if audit_parts[:len(root)] == root
        ]
        require(len(matching_roots) == 1,
                f"compiler audit is outside its declared root: {audit_path}")
        root = matching_roots[0]
        for length in range(len(root), len(audit_parts)):
            directory_parts = audit_parts[:length]
            allowed_audit_directories.add(directory_parts)
            required_audit_directories.add(directory_parts)
    actual_audit_directories = {
        parts for parts in authority.directory_membership_pins
        if any(parts[:len(root)] == root for root in audit_roots)
    }
    require(
        required_audit_directories <= actual_audit_directories
        and actual_audit_directories <= allowed_audit_directories,
        "compiler audit directory topology has missing or extra directories",
    )
    if state["recipes"]:
        require_exact_flat_build_namespace(
            authority,
            authority.build_root / "byte-identity/generated",
            {
                Path(recipe["header_output"]).name
                for recipe in state["recipes"]
            },
            "generated declaration namespace",
        )
        require_exact_flat_build_namespace(
            authority,
            authority.build_root / "byte-identity/audit/materialization",
            {f"{recipe['id']}.json" for recipe in state["recipes"]},
            "materialization audit namespace",
        )
    if state["archives"]:
        require_exact_flat_build_namespace(
            authority,
            authority.build_root / "byte-identity/audit/archives",
            {f"{archive['identity']}.json" for archive in state["archives"]},
            "authorized archive audit namespace",
        )
        require_exact_build_namespace(
            authority,
            authority.build_root / "byte-identity/third-party-archives",
            {archive["identity"]: "directory" for archive in state["archives"]},
            "authorized archive root namespace",
        )
    resource_inputs = [
        item for item in inventory.get("inputs", []) if item["kind"] == "RC"
    ] if state["images"] else []
    if resource_inputs:
        resource_targets = sorted({item["target"] for item in resource_inputs})
        require_exact_build_namespace(
            authority,
            authority.build_root / "byte-identity/audit/resources",
            {target: "directory" for target in resource_targets},
            "resource producer audit root",
        )
        for target in resource_targets:
            require_exact_flat_build_namespace(
                authority,
                authority.build_root / "byte-identity/audit/resources" / target,
                {
                    Path(item["audit"]).name for item in resource_inputs
                    if item["target"] == target
                },
                f"resource producer audit namespace for {target}",
            )
    static_targets = [
        item for item in inventory.get("targets", [])
        if item["kind"] == "STATIC_LIBRARY"
    ] if state["images"] else []
    if static_targets:
        require_exact_flat_build_namespace(
            authority,
            authority.build_root / "byte-identity/audit/first-party-archives",
            {f"{item['target']}.json" for item in static_targets},
            "first-party archive producer audit namespace",
        )
    if state["images"]:
        require_exact_build_namespace(
            authority,
            authority.build_root / "byte-identity/final",
            expected_terminal_final_namespace(include_reccmp=include_reccmp),
            "terminal final artifact namespace",
        )
        require_exact_flat_build_namespace(
            authority,
            authority.build_root / "byte-identity/audit/links",
            {"LEGO1.json"},
            "terminal link producer audit namespace",
        )
        if include_reccmp:
            require_exact_flat_build_namespace(
                authority,
                authority.build_root / "byte-identity/audit/reccmp",
                {"LEGO1.json"},
                "terminal reccmp producer audit namespace",
            )
    verified_object_outputs = set()
    verified_pdb_outputs = set()
    verified_recipes = []
    verified_archives = []
    verified_units = []
    for declared_recipe in state["recipes"]:
        output = Path(declared_recipe["header_output"])
        recipe = declared_recipe["recipe"]
        require(authority.is_regular_file(output),
                f"materialized header is absent: {output}")
        require(sha256_file(output) == recipe["generated_header_sha256"],
                f"materialized header hash differs: {output}")
        materialization_audit_path = (
            authority.build_root
            / "byte-identity/audit/materialization"
            / f"{declared_recipe['id']}.json"
        )
        materialization_audit = read_unique_audit(
            materialization_audit_path, build_root, "materialization audit"
        )
        exact_audit_keys(
            materialization_audit,
            MATERIALIZATION_AUDIT_KEYS,
            f"materialization audit {materialization_audit_path}",
        )
        require(recipe["kind"] == "declaration_shape",
                "verified materialization recipe is not declaration_shape")
        expected_parameters = {
            "classes": recipe["classes"],
            "functions": recipe["functions"],
        }
        require(
            materialization_audit.get("status")
            == "MATERIALIZED_NON_EMITTING_DECLARATIONS"
            and materialization_audit.get("manifest_sha256") == state["manifest_sha256"]
            and materialization_audit.get("recipe_id") == declared_recipe["id"]
            and exact_json_equal(materialization_audit.get("users"), declared_recipe["users"])
            and materialization_audit.get("kind") == recipe["kind"]
            and exact_json_equal(materialization_audit.get("parameters"), expected_parameters)
            and authority.parts(Path(materialization_audit.get("output", "")))
            == authority.parts(output)
            and materialization_audit.get("output_sha256")
            == recipe["generated_header_sha256"]
            and materialization_audit.get("emission_policy")
            == "non_emitting_declarations_only",
            f"materialization audit differs: {materialization_audit_path}",
        )
        verified_recipes.append(declared_recipe["id"])
    for archive in state["archives"]:
        identity = archive["identity"]
        output = Path(archive["output"])
        audit_path = Path(archive["audit"])
        require_exact_flat_build_namespace(
            authority,
            output.parent,
            {output.name},
            f"authorized {identity} archive namespace",
        )
        output_data = authority.read_bytes(output)
        source_data = authority.read_external_bytes(Path(archive["source_path"]))
        require(
            output_data == source_data
            and output_data.startswith(b"!<arch>\n")
            and len(output_data) == archive["source_size"]
            and sha256_bytes(output_data) == archive["source_sha256"],
            f"authorized {identity} archive copy differs",
        )
        audit = read_unique_audit(
            audit_path, build_root, "authorized archive audit"
        )
        exact_audit_keys(
            audit,
            ARCHIVE_MATERIALIZATION_AUDIT_KEYS,
            f"authorized archive audit {audit_path}",
        )
        expected_audit = {
            "status": "AUTHORIZED_THIRD_PARTY_ARCHIVE_MATERIALIZED",
            "manifest_sha256": state["manifest_sha256"],
            "kind": "third_party_reconstructed_archive",
            "identity": identity,
            "imported_target": archive["imported_target"],
            "payload_policy": THIRD_PARTY_RETAIL_ARCHIVE_POLICY,
            "copy_policy": "byte_exact_independent_build_authority_copy_v1",
            "source": archive["source_path"],
            "source_sha256": archive["source_sha256"],
            "source_size": archive["source_size"],
            "output": str(output),
            "output_sha256": archive["source_sha256"],
            "output_size": archive["source_size"],
            "link_contract": archive["link_contract"],
        }
        require(
            exact_json_equal(audit, expected_audit),
            f"authorized archive audit differs: {audit_path}",
        )
        verified_archives.append(identity)
    for unit in state["translation_units"]:
        audit_path = audit_object_path(arguments.build_dir, unit["target"], unit["source"])
        inventory_entry = inventory_by_owner.get((unit["target"], unit["source"]))
        require(inventory_entry is not None and inventory_entry["listed"] is True
                and authority.parts(Path(inventory_entry["audit"]))
                == authority.parts(audit_path),
                f"listed compiler inventory output differs: {audit_path}")
        audit = read_unique_audit(
            audit_path, build_root, "compiler audit"
        )
        exact_audit_keys(
            audit,
            LISTED_COMPILER_AUDIT_KEYS,
            f"compiler audit {audit_path}",
        )
        require_sha(
            audit.get("input_command_sha256"),
            f"compiler audit {audit_path} input command hash",
        )
        require_sha(
            audit.get("seed_executed_command_sha256"),
            f"compiler audit {audit_path} seed command hash",
        )
        require_nonnegative_finite_number(
            audit.get("elapsed_seconds"),
            f"compiler audit {audit_path} elapsed time",
        )
        expected_status = (
            "compiler_output_fpo_composed"
            if unit["mode"] == "compose_equal_linked_span_fpo"
            else "pass_through_not_composed"
        )
        require(audit.get("status") == expected_status,
                f"compiler audit status differs: {audit_path}")
        require(audit.get("may_claim_byte_identity") is False,
                f"compiler audit may claim byte identity: {audit_path}")
        require(audit.get("manifest_sha256") == state["manifest_sha256"],
                f"compiler audit is stale: {audit_path}")
        require(audit.get("source_sha256") == unit["source_sha256"],
                f"compiler audit source hash differs: {audit_path}")
        require(audit.get("target") == unit["target"] and audit.get("source") == unit["source"],
                f"compiler audit owner differs: {audit_path}")
        require(audit.get("compiler_sha256") == state["compiler_sha256"],
                f"compiler audit toolchain hash differs: {audit_path}")
        require(audit.get("toolchain_fingerprint") == state["toolchain_fingerprint"],
                f"compiler audit transitive toolchain differs: {audit_path}")
        require(audit.get("framework_tool_sha256") == state["framework_tool_sha256"],
                f"compiler audit framework tool differs: {audit_path}")
        require(audit.get("backend_tool_sha256") == state["backend_tool_sha256"],
                f"compiler audit backend tool differs: {audit_path}")
        require(audit.get("entropy_tool_sha256") == state["entropy_tool_sha256"],
                f"compiler audit entropy tool differs: {audit_path}")
        require(audit.get("python_sha256") == state["python_sha256"]
                and audit.get("python_version") == state["python_version"],
                f"compiler audit Python pin differs: {audit_path}")
        require(exact_json_equal(audit.get("child_environment"), state["child_environment"]),
                f"compiler audit environment policy differs: {audit_path}")
        require(audit.get("inventory_sha256") == inventory_sha
                and audit.get("policy_sha256") == inventory["policy_sha256"],
                f"compiler audit inventory policy differs: {audit_path}")
        command_entry = command_by_owner.get((unit["target"], unit["source"]))
        require(command_entry is not None
                and audit.get("command_inventory_sha256") == command_inventory_sha
                and audit.get("command_policy_sha256") == command_inventory["policy_sha256"]
                and audit.get("configured_argv_sha256") == command_entry["argv_sha256"],
                f"compiler audit generated argv policy differs: {audit_path}")
        source_id = hashlib.sha256(unit["source"].encode("utf-8")).hexdigest()[:16]
        validate_dependency_audit(
            authority,
            state,
            audit,
            command_entry,
            Path(unit["source_path"]),
            authority.build_root / "byte-identity/work" / unit["target"]
            / source_id / "dependencies/dependencies.i",
            f"compiler audit {audit_path} dependency capture",
        )
        require(type(audit.get("compiler_semaphore_max")) is int
                and audit.get("compiler_semaphore_max") == MAX_COMPILER_PROCESSES,
                f"compiler audit semaphore policy differs: {audit_path}")
        require(audit.get("recipes") == [donor["id"] for donor in unit["donors"]],
                f"compiler audit recipe set differs: {audit_path}")
        require(audit.get("recipes_materialized_but_not_injected")
                is (unit["mode"] == "pass_through"),
                f"compiler audit recipe disposition differs: {audit_path}")
        require(audit.get("recipes_compiled_and_injected")
                is (unit["mode"] == "compose_equal_linked_span_fpo"),
                f"compiler audit compiler-output disposition differs: {audit_path}")
        require(type(audit.get("retail_payload_bytes_read")) is int
                and audit.get("retail_payload_bytes_read") == 0,
                f"compiler audit retail provenance differs: {audit_path}")
        require(exact_json_equal(audit.get("completion"), unit["completion"]),
                f"compiler audit completion differs: {audit_path}")
        donor_records = audit.get("donors")
        composition_records = audit.get("composition")
        require(isinstance(donor_records, list),
                f"compiler audit donors are not an array: {audit_path}")
        require(isinstance(composition_records, list),
                f"compiler audit composition is not an array: {audit_path}")
        for donor_index, donor_record in enumerate(donor_records):
            require(isinstance(donor_record, dict),
                    f"compiler donor audit is not an object: {audit_path}")
            exact_audit_keys(
                donor_record,
                DONOR_AUDIT_KEYS,
                f"compiler audit {audit_path} donor[{donor_index}]",
            )
            require_sha(
                donor_record.get("executed_command_sha256"),
                f"compiler audit {audit_path} donor[{donor_index}] command hash",
            )
        for composition_index, composition_record in enumerate(composition_records):
            validate_composition_audit_schema(
                composition_record,
                f"compiler audit {audit_path} composition[{composition_index}]",
            )
        if unit["mode"] == "pass_through":
            require(not donor_records and not composition_records,
                    f"pass-through audit contains donor/composition records: {audit_path}")
        object_path = Path(audit.get("object", ""))
        object_identity = authority.parts(object_path)
        require(authority.is_regular_file(object_path)
                and sha256_file(object_path) == audit.get("object_sha256"),
                f"compiler audit object differs: {audit_path}")
        require(object_identity not in verified_object_outputs,
                f"duplicate compiler object output: {object_path}")
        verified_object_outputs.add(object_identity)
        pdb_path = Path(audit.get("pdb", ""))
        pdb_identity = authority.parts(pdb_path)
        require(authority.is_regular_file(pdb_path)
                and sha256_file(pdb_path) == audit.get("pdb_sha256"),
                f"compiler audit PDB differs: {audit_path}")
        require(pdb_identity not in verified_pdb_outputs,
                f"duplicate compiler PDB output: {pdb_path}")
        verified_pdb_outputs.add(pdb_identity)
        seed_transport_audit = audit.get("transport")
        validate_transport_audit(
            authority,
            seed_transport_audit,
            state=state,
            command_inventory=command_inventory,
            command_entry=command_entry,
            object_path=object_path,
            pdb_path=pdb_path,
            context=f"compiler audit {audit_path} transport",
        )
        require(
            audit.get("input_command_sha256")
            == stable_argv_sha256(command_entry["argv"]),
            f"compiler audit generated input command differs: {audit_path}",
        )
        validate_snapshotted_compiler_command_hash(
            state, command_entry["argv"], seed_transport_audit,
            audit.get("seed_executed_command_sha256"),
            f"compiler audit {audit_path} seed executed command",
        )
        seed_path = Path(audit.get("seed_object", ""))
        authority.parts(seed_path)
        require(authority.is_regular_file(seed_path)
                and sha256_file(seed_path) == audit.get("seed_object_sha256"),
                f"compiler audit seed object differs: {audit_path}")
        seed_pdb_path = Path(audit.get("seed_pdb", ""))
        authority.parts(seed_pdb_path)
        require(authority.is_regular_file(seed_pdb_path)
                and sha256_file(seed_pdb_path) == audit.get("seed_pdb_sha256")
                and audit.get("seed_pdb_sha256") == audit.get("pdb_sha256"),
                f"compiler audit private seed PDB differs: {audit_path}")
        require(
            embedded_pdb_references(seed_path, pdb_path)
            == audit.get("seed_embedded_pdb_references"),
            f"compiler audit seed PDB reference differs: {audit_path}",
        )
        require(
            embedded_pdb_references(object_path, pdb_path)
            == audit.get("seed_embedded_pdb_references"),
            f"installed object PDB reference differs: {audit_path}",
        )
        validate_private_auxiliary_audit(
            authority,
            audit.get("seed_auxiliary_outputs"),
            seed_path,
            seed_pdb_path,
            f"compiler audit {audit_path} seed auxiliary outputs",
        )
        if unit["mode"] == "pass_through":
            require(
                authority.read_bytes(seed_path)
                == authority.read_bytes(object_path),
                f"pass-through installed object differs from private seed: {audit_path}",
            )
        if unit["mode"] == "compose_equal_linked_span_fpo":
            require(isinstance(donor_records, list)
                    and [item.get("recipe_id") for item in donor_records]
                    == [donor["id"] for donor in unit["donors"]],
                    f"compiler audit donor order differs: {audit_path}")
            donor_paths = {}
            for donor, record in zip(unit["donors"], donor_records):
                donor_path = Path(record.get("object", ""))
                authority.parts(donor_path)
                require(authority.is_regular_file(donor_path)
                        and sha256_file(donor_path) == record.get("object_sha256"),
                        f"compiler donor object differs: {audit_path}")
                donor_pdb_path = Path(record.get("pdb", ""))
                authority.parts(donor_pdb_path)
                require(authority.is_regular_file(donor_pdb_path)
                        and sha256_file(donor_pdb_path) == record.get("pdb_sha256"),
                        f"compiler donor PDB differs: {audit_path}")
                require(
                    embedded_pdb_references(donor_path, pdb_path)
                    == record.get("embedded_pdb_references"),
                    f"compiler donor embedded PDB reference differs: {audit_path}",
                )
                donor_transport_audit = record.get("transport")
                validate_transport_audit(
                    authority,
                    donor_transport_audit,
                    state=state,
                    command_inventory=command_inventory,
                    command_entry=command_entry,
                    object_path=object_path,
                    pdb_path=pdb_path,
                    context=(
                        f"compiler audit {audit_path} donor "
                        f"{donor['id']} transport"
                    ),
                )
                validate_private_auxiliary_audit(
                    authority,
                    record.get("auxiliary_outputs"),
                    donor_path,
                    donor_pdb_path,
                    f"compiler audit {audit_path} donor auxiliary outputs",
                )
                header_path = Path(record.get("header", ""))
                require(authority.parts(header_path)
                        == authority.parts(Path(donor["header_output"]))
                        and authority.is_regular_file(header_path)
                        and sha256_file(header_path) == record.get("header_sha256")
                        and record.get("header_sha256")
                        == donor["recipe"]["generated_header_sha256"],
                        f"compiler donor header pin differs: {audit_path}")
                donor_generated = list(command_entry["argv"])
                donor_parsed = validate_compile_arguments(donor_generated)
                donor_generated.insert(
                    donor_parsed["Fo"][0], f"/FI{header_path}"
                )
                validate_snapshotted_compiler_command_hash(
                    state, donor_generated, donor_transport_audit,
                    record.get("executed_command_sha256"),
                    f"compiler audit {audit_path} donor executed command",
                )
                donor_paths[donor["id"]] = donor_path
            reconstructed = authority.read_bytes(seed_path)
            reconstructed_details = []
            donors_by_id = {donor["id"]: donor for donor in unit["donors"]}
            for function in unit["functions"]:
                donor = donors_by_id[function["donor"]]
                reconstructed, detail = compose_equal_linked_span_fpo(
                    reconstructed,
                    authority.read_bytes(donor_paths[donor["id"]]),
                    function,
                    declaration_identifiers(
                        authority.read_bytes(Path(donor["header_output"]))
                    ),
                )
                detail["recipe_id"] = donor["id"]
                reconstructed_details.append(detail)
            require(reconstructed == authority.read_bytes(object_path),
                    f"compiler composition cannot be reconstructed: {audit_path}")
            require(exact_json_equal(reconstructed_details, audit.get("composition")),
                    f"compiler composition audit differs on reconstruction: {audit_path}")
        verified_units.append(f"{unit['target']}:{unit['source']}")

    verified_unlisted = []
    unlisted_entries = [
        entry for entry in inventory["entries"] if entry["listed"] is False
    ]
    for inventory_entry in unlisted_entries:
        audit_path = Path(inventory_entry["audit"])
        audit = read_unique_audit(
            audit_path, build_root, "unlisted compiler audit"
        )
        exact_audit_keys(
            audit,
            UNLISTED_COMPILER_AUDIT_KEYS,
            f"unlisted compiler audit {audit_path}",
        )
        require_sha(
            audit.get("input_command_sha256"),
            f"unlisted compiler audit {audit_path} input command hash",
        )
        require_sha(
            audit.get("executed_command_sha256"),
            f"unlisted compiler audit {audit_path} executed command hash",
        )
        require_nonnegative_finite_number(
            audit.get("elapsed_seconds"),
            f"unlisted compiler audit {audit_path} elapsed time",
        )
        target = audit.get("target")
        source = audit.get("source")
        require(target == inventory_entry["target"]
                and source == inventory_entry["source"]
                and authority.parts(audit_path)
                == authority.parts(
                    audit_unlisted_path(arguments.build_dir, target, source)
                ),
                f"unlisted compiler audit owner/output is wrong: {audit_path}")
        source_relative = canonical_source_relative_path(
            source, "unlisted compiler audit source"
        )
        source_path = source_overlay_logical_path(
            arguments.source_dir, source_relative
        )
        expected_source_sha = (
            inventory_entry["effective_source_sha256"]
            if state["source_overlay"]["enabled"] else
            sha256_file(source_path)
        )
        require(source_relative == source
                and audit.get("source_sha256") == expected_source_sha,
                f"unlisted compiler audit source differs: {audit_path}")
        validate_compiler_logical_input_policy(
            state, source_path, expected_source_sha,
            "unlisted compiler audit source",
        )
        require(
            audit.get("status") == "unlisted_atomic_pass_through"
            and audit.get("may_claim_byte_identity") is False
            and audit.get("manifest_sha256") == state["manifest_sha256"]
            and audit.get("compiler_sha256") == state["compiler_sha256"]
            and audit.get("toolchain_fingerprint") == state["toolchain_fingerprint"]
            and audit.get("framework_tool_sha256") == state["framework_tool_sha256"]
            and audit.get("backend_tool_sha256") == state["backend_tool_sha256"]
            and audit.get("entropy_tool_sha256") == state["entropy_tool_sha256"]
            and audit.get("python_sha256") == state["python_sha256"]
            and audit.get("python_version") == state["python_version"]
            and exact_json_equal(audit.get("child_environment"), state["child_environment"])
            and audit.get("inventory_sha256") == inventory_sha
            and audit.get("policy_sha256") == inventory["policy_sha256"]
            and type(audit.get("compiler_semaphore_max")) is int
            and audit.get("compiler_semaphore_max") == MAX_COMPILER_PROCESSES,
            f"unlisted compiler audit policy differs: {audit_path}",
        )
        command_entry = command_by_owner.get((target, source))
        require(command_entry is not None
                and audit.get("command_inventory_sha256") == command_inventory_sha
                and audit.get("command_policy_sha256") == command_inventory["policy_sha256"]
                and audit.get("configured_argv_sha256") == command_entry["argv_sha256"],
                f"unlisted compiler generated argv policy differs: {audit_path}")
        source_id = hashlib.sha256(source.encode("utf-8")).hexdigest()[:16]
        validate_dependency_audit(
            authority,
            state,
            audit,
            command_entry,
            source_path,
            authority.build_root / "byte-identity/work/unlisted-pass-through"
            / target / source_id / "dependencies/dependencies.i",
            f"unlisted compiler audit {audit_path} dependency capture",
        )
        object_path = Path(audit.get("object", ""))
        final_pdb_path = Path(audit.get("pdb", ""))
        private_object_path = Path(audit.get("private_object", ""))
        private_pdb_path = Path(audit.get("private_pdb", ""))
        for artifact, label in (
            (object_path, "object"),
            (final_pdb_path, "PDB"),
            (private_object_path, "private object"),
            (private_pdb_path, "private PDB"),
        ):
            authority.parts(artifact)
            require(authority.is_regular_file(artifact),
                    f"unlisted compiler audit {label} is invalid: {audit_path}")
        unlisted_transport_audit = audit.get("transport")
        validate_transport_audit(
            authority,
            unlisted_transport_audit,
            state=state,
            command_inventory=command_inventory,
            command_entry=command_entry,
            object_path=object_path,
            pdb_path=final_pdb_path,
            context=f"unlisted compiler audit {audit_path} transport",
        )
        require(
            audit.get("input_command_sha256")
            == stable_argv_sha256(command_entry["argv"]),
            f"unlisted compiler generated input command differs: {audit_path}",
        )
        validate_snapshotted_compiler_command_hash(
            state, command_entry["argv"], unlisted_transport_audit,
            audit.get("executed_command_sha256"),
            f"unlisted compiler audit {audit_path} executed command",
        )
        require(sha256_file(object_path) == audit.get("object_sha256"),
                f"unlisted compiler object differs: {audit_path}")
        require(
            sha256_file(private_object_path)
            == audit.get("private_object_sha256")
            == audit.get("object_sha256")
            and authority.read_bytes(private_object_path)
            == authority.read_bytes(object_path),
            f"unlisted private/public objects differ: {audit_path}",
        )
        object_identity = authority.parts(object_path)
        require(object_identity not in verified_object_outputs,
                f"duplicate compiler object output: {object_path}")
        verified_object_outputs.add(object_identity)
        require(sha256_file(final_pdb_path) == audit.get("pdb_sha256")
                and sha256_file(private_pdb_path)
                == audit.get("private_pdb_sha256")
                == audit.get("pdb_sha256"),
                f"unlisted compiler PDB copies differ: {audit_path}")
        final_pdb_identity = authority.parts(final_pdb_path)
        require(final_pdb_identity not in verified_pdb_outputs,
                f"duplicate compiler PDB output: {final_pdb_path}")
        verified_pdb_outputs.add(final_pdb_identity)
        require(
            embedded_pdb_references(object_path, final_pdb_path)
            == audit.get("embedded_pdb_references"),
            f"unlisted compiler embedded PDB reference differs: {audit_path}",
        )
        require(
            embedded_pdb_references(private_object_path, final_pdb_path)
            == audit.get("embedded_pdb_references"),
            f"unlisted private object PDB reference differs: {audit_path}",
        )
        validate_private_auxiliary_audit(
            authority,
            audit.get("private_auxiliary_outputs"),
            private_object_path,
            private_pdb_path,
            f"unlisted compiler audit {audit_path} auxiliary outputs",
        )
        verified_unlisted.append(f"{target}:{source}")
    require(len(verified_units) + len(verified_unlisted) == len(inventory["entries"]),
            "verified compiler audit count differs from configure inventory")
    if resource_inputs:
        require(outer_session is not None,
                "resource verification requires an authenticated outer session")
        resource_records = resource_output_records(state, inventory)
        require(len(resource_records) == len(resource_inputs),
                "verified resource producer count differs from configure inventory")
    if static_targets:
        require(outer_session is not None,
                "archive verification requires an authenticated outer session")
        first_party_records = first_party_archive_records(
            state, inventory, outer_session
        )
        require(len(first_party_records) == len(static_targets),
                "verified first-party archive count differs from target inventory")
    if state["images"]:
        require(outer_session is not None,
                "terminal LINK verification requires an authenticated outer session")
        link_audit, link_audit_bytes = validate_final_link_audit(
            state, inventory, outer_session
        )
        if include_reccmp:
            validate_final_reccmp_audit(
                state, inventory, outer_session, link_audit, link_audit_bytes
            )
    result = {
        "status": "OBJECT_COMPOSITION_VERIFIED_FINAL_GATES_INCOMPLETE",
        "byte_identity_complete": False,
        "reason": (
            "Compiler outputs and authorized third-party archives are "
            "reconstructable; final image, 4933-row reccmp, and original-MD5 "
            "completion gates have not yet been invoked"
        ),
        "manifest_sha256": state["manifest_sha256"],
        "inventory_sha256": inventory_sha,
        "policy_sha256": inventory["policy_sha256"],
        "command_inventory_sha256": command_inventory_sha,
        "command_policy_sha256": command_inventory["policy_sha256"],
        "execution_backend": state["execution_backend"]["id"],
        "backend_tool_sha256": state["backend_tool_sha256"],
        **framework_source_overlay_verdict_identity(state),
        "outer_session_nonce": (
            outer_session["nonce"] if outer_session is not None else None
        ),
        "compiler_semaphore_max": MAX_COMPILER_PROCESSES,
        "recipes": verified_recipes,
        "archives": verified_archives,
        "iteration_images": [],
        "final_images": [],
        "translation_units": verified_units,
        "unlisted_translation_units": verified_unlisted,
    }
    validate_framework_verdict_document(result)
    if not publish:
        authority.revalidate_epoch()
        return result
    try:
        authority.revalidate_epoch()
        serialized = (
            json.dumps(result, indent=2, sort_keys=True) + "\n"
        ).encode("utf-8")
        atomic_write(verdict_path, serialized)
        require_exact_build_namespace(
            authority,
            audit_root,
            {**audit_root_expected, "framework-verdict.json": "file"},
            "published byte-identity audit namespace",
            replace_pin=True,
        )
        require(authority.read_bytes(verdict_path) == serialized,
                "published framework verdict cannot be read back exactly")
        authority.revalidate_epoch()
    except BaseException:
        authority.prune_leaf_or_redirect(verdict_path)
        authority.assert_absent(verdict_path)
        raise
    print(json.dumps(result, sort_keys=True))
    return 0


def command_verify(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    with build_transaction(arguments.build_dir, exclusive=True):
        result = command_verify_locked(
            arguments, publish=not getattr(arguments, "no_publish", False)
        )
        if isinstance(result, dict):
            print(json.dumps(result, sort_keys=True))
            return 0
        return result


FRAMEWORK_VERDICT_KEYS = {
    "status", "byte_identity_complete", "reason", "manifest_sha256",
    "inventory_sha256", "policy_sha256", "command_inventory_sha256",
    "command_policy_sha256", "execution_backend", "backend_tool_sha256",
    "outer_session_nonce",
    "compiler_semaphore_max", "recipes", "archives", "final_images",
    "iteration_images", "translation_units",
    "unlisted_translation_units",
    "source_overlay_enabled", "source_overlay_policy_sha256",
    "source_overlay_actual_records_sha256",
    "source_overlay_receipt_sha256", "source_overlay_output_count",
}

FINAL_IMAGE_VERDICT_KEYS = {
    "identity", "target", "original_sha256", "original_md5",
    "recompiled_sha256", "recompiled_md5", "image_size",
    "reccmp_report", "reccmp_report_sha256", "reccmp_schema",
    "row_identity_sha256", "row_count", "exact_row_count",
    "address_aligned_row_count", "link_audit", "link_audit_sha256",
    "reccmp_audit", "reccmp_audit_sha256",
}

ITERATION_IMAGE_VERDICT_KEYS = {
    "identity", "target", "retail_identity_claimed",
    "recompiled_image", "recompiled_sha256", "image_size",
    "analysis_pdb", "analysis_pdb_sha256", "release_map",
    "release_map_sha256", "reccmp_report", "reccmp_report_sha256",
    "link_audit", "link_audit_sha256", "reccmp_audit",
    "reccmp_audit_sha256", "row_count", "raw_1_0_count",
    "raw_1_0_address_aligned_count", "address_aligned_row_count",
    "row_identity_sha256", "accepted_row_identity_sha256",
}


def validate_framework_verdict_document(value: object) -> dict:
    """Validate the complete verdict schema with exact recursive JSON types."""
    require(isinstance(value, dict), "framework verdict must be an object")
    exact_audit_keys(value, FRAMEWORK_VERDICT_KEYS, "framework verdict")
    complete = value.get("byte_identity_complete")
    require(type(complete) is bool, "framework verdict completion must be boolean")
    expected_status = (
        "BYTE_IDENTITY_COMPLETE"
        if complete else "OBJECT_COMPOSITION_VERIFIED_FINAL_GATES_INCOMPLETE"
    )
    require(
        value.get("status") == expected_status
        and isinstance(value.get("reason"), str)
        and bool(value.get("reason")),
        "framework verdict status/completion schema differs",
    )
    for name in (
        "manifest_sha256", "inventory_sha256", "policy_sha256",
        "command_inventory_sha256", "command_policy_sha256",
        "backend_tool_sha256",
    ):
        require_sha(value.get(name), f"framework verdict {name}")
    require(
        value.get("execution_backend") == selected_backend(),
        "framework verdict execution backend differs from this host",
    )
    overlay_enabled = value.get("source_overlay_enabled")
    overlay_count = value.get("source_overlay_output_count")
    require(
        type(overlay_enabled) is bool
        and type(overlay_count) is int and overlay_count >= 0
        and (
            all(
                SHA256_RE.fullmatch(value.get(key) or "") is not None
                for key in (
                    "source_overlay_policy_sha256",
                    "source_overlay_actual_records_sha256",
                    "source_overlay_receipt_sha256",
                )
            )
            and overlay_count > 0
            if overlay_enabled else
            value.get("source_overlay_policy_sha256") is None
            and value.get("source_overlay_actual_records_sha256") is None
            and value.get("source_overlay_receipt_sha256") is None
            and overlay_count == 0
        ),
        "framework verdict typed source overlay identity differs",
    )
    nonce = value.get("outer_session_nonce")
    require(
        nonce is None
        or (isinstance(nonce, str) and SHA256_RE.fullmatch(nonce) is not None),
        "framework verdict outer session nonce is invalid",
    )
    require_exact_int(
        value.get("compiler_semaphore_max"),
        "framework verdict compiler_semaphore_max",
        minimum=MAX_COMPILER_PROCESSES,
        maximum=MAX_COMPILER_PROCESSES,
    )
    for name in (
        "recipes", "archives", "translation_units",
        "unlisted_translation_units",
    ):
        items = value.get(name)
        require(
            isinstance(items, list)
            and all(isinstance(item, str) and item for item in items)
            and len(items) == len(set(items)),
            f"framework verdict {name} must contain unique strings",
        )
    final_images = value.get("final_images")
    require(isinstance(final_images, list),
            "framework verdict final_images must be an array")
    require(bool(final_images) is complete,
            "framework verdict final image completion differs")
    iteration_images = value.get("iteration_images")
    require(isinstance(iteration_images, list)
            and len(iteration_images) <= 1
            and (not complete or not iteration_images),
            "framework verdict iteration image universe differs")
    for index, record in enumerate(iteration_images):
        context = f"framework verdict iteration_images[{index}]"
        require(isinstance(record, dict), f"{context} must be an object")
        exact_audit_keys(record, ITERATION_IMAGE_VERDICT_KEYS, context)
        require(record.get("identity") == "LEGO1"
                and record.get("target") == "lego1"
                and record.get("retail_identity_claimed") is False,
                f"{context} identity/claim differs")
        for name in (
            "recompiled_sha256", "analysis_pdb_sha256",
            "release_map_sha256", "reccmp_report_sha256",
            "link_audit_sha256", "reccmp_audit_sha256",
            "row_identity_sha256", "accepted_row_identity_sha256",
        ):
            require_sha(record.get(name), f"{context}.{name}")
        for name in (
            "recompiled_image", "analysis_pdb", "release_map",
            "reccmp_report", "link_audit", "reccmp_audit",
        ):
            require(isinstance(record.get(name), str) and record[name],
                    f"{context}.{name} is invalid")
        rows = require_exact_int(
            record.get("row_count"), f"{context}.row_count",
            minimum=4933, maximum=4933,
        )
        exact = require_exact_int(
            record.get("raw_1_0_count"), f"{context}.raw_1_0_count",
            minimum=1, maximum=rows,
        )
        require_exact_int(record.get("image_size"),
                          f"{context}.image_size", minimum=1)
        require(require_exact_int(
                    record.get("raw_1_0_address_aligned_count"),
                    f"{context}.raw_1_0_address_aligned_count",
                    minimum=0, maximum=exact,
                ) <= exact
                and require_exact_int(
                    record.get("address_aligned_row_count"),
                    f"{context}.address_aligned_row_count",
                    minimum=0, maximum=rows,
                ) <= rows,
                f"{context} alignment counts differ")
    identities = set()
    for index, record in enumerate(final_images):
        context = f"framework verdict final_images[{index}]"
        require(isinstance(record, dict), f"{context} must be an object")
        exact_audit_keys(record, FINAL_IMAGE_VERDICT_KEYS, context)
        identity = record.get("identity")
        require(identity == "LEGO1" and identity not in identities
                and record.get("target") == "lego1",
                f"{context} identity/target differs")
        identities.add(identity)
        for name in (
            "original_sha256", "recompiled_sha256",
            "reccmp_report_sha256", "row_identity_sha256",
            "link_audit_sha256", "reccmp_audit_sha256",
        ):
            require_sha(record.get(name), f"{context}.{name}")
        require_md5(record.get("original_md5"), f"{context}.original_md5")
        require_md5(record.get("recompiled_md5"), f"{context}.recompiled_md5")
        require(
            record.get("original_sha256") == record.get("recompiled_sha256")
            and record.get("original_md5") == record.get("recompiled_md5")
            and record.get("reccmp_schema")
            == "reccmp_json_diet_exact_rows_v1"
            and isinstance(record.get("reccmp_report"), str)
            and bool(record.get("reccmp_report")),
            f"{context} image/report identity differs",
        )
        row_count = require_exact_int(
            record.get("row_count"), f"{context}.row_count", minimum=4933,
            maximum=4933,
        )
        require_exact_int(
            record.get("image_size"), f"{context}.image_size", minimum=1
        )
        require(
            require_exact_int(
                record.get("exact_row_count"), f"{context}.exact_row_count",
                minimum=4933, maximum=4933,
            ) == row_count
            and require_exact_int(
                record.get("address_aligned_row_count"),
                f"{context}.address_aligned_row_count",
                minimum=4933, maximum=4933,
            ) == row_count,
            f"{context} row completion differs",
        )
    return value


def validate_reccmp_report_snapshot(data: bytes, image_gate: dict) -> dict:
    """Validate the fixed LEGO1 row universe and report exact score-set facts."""
    try:
        document = strict_json_loads(data)
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ByteIdentityError(f"cannot parse final reccmp report: {error}") from error
    require(isinstance(document, dict), "final reccmp report must be an object")
    exact_audit_keys(document, {"file", "format", "timestamp", "data"},
                     "final reccmp report")
    require(
        document.get("file") == "LEGO1.DLL"
        and type(document.get("format")) is int
        and document.get("format") == 1,
        "final reccmp report identity/schema differs",
    )
    require_nonnegative_finite_number(
        document.get("timestamp"), "final reccmp report timestamp"
    )
    rows = document.get("data")
    required_count = image_gate["required_row_count"]
    require(isinstance(rows, list) and len(rows) == required_count,
            f"final reccmp row count must be exactly {required_count}")
    identity_rows = []
    accepted_rows = []
    accepted_address_aligned = 0
    address_aligned = 0
    previous_address = -1
    seen_addresses = set()
    for index, row in enumerate(rows):
        context = f"final reccmp row[{index}]"
        require(isinstance(row, dict), f"{context} must be an object")
        required_keys = {"address", "name", "matching", "recomp", "type"}
        require(
            required_keys <= set(row)
            and set(row) <= required_keys | {"effective"},
            f"{context} schema differs",
        )
        address = row.get("address")
        name = row.get("name")
        row_type = row.get("type")
        require(
            isinstance(address, str)
            and ADDRESS_RE.fullmatch(address) is not None
            and isinstance(name, str) and bool(name)
            and type(row_type) is int and row_type in (1, 5),
            f"{context} identity is invalid",
        )
        numeric_address = int(address, 16)
        require(
            numeric_address > previous_address and address not in seen_addresses,
            f"{context} address order/uniqueness differs",
        )
        previous_address = numeric_address
        seen_addresses.add(address)
        matching = row.get("matching")
        recomp = row.get("recomp")
        require(type(matching) is float and math.isfinite(matching)
                and 0.0 <= matching <= 1.0,
                f"{context} raw matching score is invalid")
        require(isinstance(recomp, str)
                and ADDRESS_RE.fullmatch(recomp) is not None,
                f"{context} recompiled address is invalid")
        if "effective" in row:
            require(row["effective"] is True,
                    f"{context}.effective must be exact JSON true")
        identity_rows.append([address, name, row_type])
        if recomp == address:
            address_aligned += 1
        if matching == 1.0:
            accepted_rows.append([address, name, row_type])
            if recomp == address:
                accepted_address_aligned += 1
    identity_bytes = (
        "\n".join(
            json.dumps(row, separators=(",", ":"), ensure_ascii=True)
            for row in identity_rows
        ) + "\n"
    ).encode("utf-8")
    identity_sha = sha256_bytes(identity_bytes)
    require(
        identity_sha == image_gate["row_identity_sha256"],
        "final reccmp row identity/order universe differs from the retail pin",
    )
    accepted_bytes = (
        "\n".join(
            json.dumps(row, separators=(",", ":"), ensure_ascii=True)
            for row in accepted_rows
        ) + "\n"
    ).encode("utf-8")
    return {
        "row_count": len(rows),
        "raw_1_0_count": len(accepted_rows),
        "raw_1_0_address_aligned_count": accepted_address_aligned,
        "address_aligned_row_count": address_aligned,
        "accepted_row_identity_sha256": sha256_bytes(accepted_bytes),
        "row_identity_sha256": identity_sha,
    }


def validate_iteration_reccmp_report(data: bytes, image_gate: dict) -> dict:
    """Require the manifest-pinned accepted score set with zero losses/gains."""
    result = validate_reccmp_report_snapshot(data, image_gate)
    baseline = image_gate["iteration_baseline"]
    require(
        result["raw_1_0_count"] == baseline["exact_raw_1_0_count"]
        and result["accepted_row_identity_sha256"]
        == baseline["accepted_row_identity_sha256"],
        "iteration reccmp accepted raw-1.0 row set differs from its exact pin",
    )
    return result


def validate_complete_reccmp_report(data: bytes, image_gate: dict) -> dict:
    """Require every fixed row to be raw-exact and address-aligned."""
    result = validate_reccmp_report_snapshot(data, image_gate)
    required = image_gate["required_row_count"]
    require(result["raw_1_0_count"] == required
            and result["raw_1_0_address_aligned_count"] == required
            and result["address_aligned_row_count"] == required,
            "final reccmp report is not exactly 4933/4933 and address-aligned")
    return {
        "row_count": result["row_count"],
        "exact_row_count": result["raw_1_0_count"],
        "address_aligned_row_count": result["address_aligned_row_count"],
        "row_identity_sha256": result["row_identity_sha256"],
    }


def command_iteration_locked(arguments: argparse.Namespace) -> dict:
    """Publish no completion claim; pin the full current producer baseline."""
    authority = active_build_authority()
    base = command_verify_locked(
        arguments, publish=False, include_reccmp=True
    )
    require(isinstance(base, dict),
            "internal iteration verification result is invalid")
    session = validate_active_session_authority(authority)
    require(session is not None and session.get("mode") == "iterate"
            and session["nonce"] == base.get("outer_session_nonce"),
            "iteration verdict requires one live resident iteration session")
    state, inventory, command_inventory, cached_session = (
        terminal_verification_inputs(arguments)
    )
    require(cached_session is not None
            and cached_session["nonce"] == session["nonce"],
            "iteration terminal verification session differs")
    require(len(state["images"]) == 1
            and state["images"][0]["identity"] == "LEGO1",
            "iteration verdict requires the declared LEGO1 image")
    link_audit, link_bytes = validate_final_link_audit(
        state, inventory, session
    )
    reccmp_audit, report_data = validate_final_reccmp_audit(
        state, inventory, session, link_audit, link_bytes
    )
    row_result = validate_iteration_reccmp_report(
        report_data, state["images"][0]
    )
    image = Path(link_audit["image"])
    pdb = Path(link_audit["pdb"])
    map_path = Path(link_audit["map"])
    report = Path(reccmp_audit["report"])
    iteration_record = {
        "identity": "LEGO1", "target": "lego1",
        "retail_identity_claimed": False,
        "recompiled_image": str(image),
        "recompiled_sha256": sha256_file(image),
        "image_size": authority.lstat(image).st_size,
        "analysis_pdb": str(pdb),
        "analysis_pdb_sha256": sha256_file(pdb),
        "release_map": str(map_path),
        "release_map_sha256": sha256_file(map_path),
        "reccmp_report": str(report),
        "reccmp_report_sha256": sha256_bytes(report_data),
        "link_audit": str(final_link_audit_path(arguments.build_dir, "LEGO1")),
        "link_audit_sha256": sha256_bytes(link_bytes),
        "reccmp_audit": str(final_reccmp_audit_path(
            arguments.build_dir, "LEGO1"
        )),
        "reccmp_audit_sha256": sha256_file(final_reccmp_audit_path(
            arguments.build_dir, "LEGO1"
        )),
        **row_result,
    }
    result = {
        **base,
        "reason": (
            "The resident producer chain reproduced the manifest-pinned "
            f"{row_result['raw_1_0_count']}-row raw-1.0 iteration baseline "
            "with zero gains or losses. "
            "This verdict records current image/PDB/MAP/report hashes and "
            "does not claim retail SHA-256/MD5 identity or 4933/4933."
        ),
        "iteration_images": [iteration_record],
        "final_images": [],
    }
    validate_framework_verdict_document(result)
    authority.revalidate_epoch()
    return result


def command_complete_locked(
    arguments: argparse.Namespace, *, publish: bool = True,
) -> int | dict:
    """Publish completion only after objects, archives, rows, and image agree."""
    authority = active_build_authority()
    base = command_verify_locked(
        arguments, publish=False, include_reccmp=True
    )
    require(isinstance(base, dict), "internal object verification result is invalid")
    session = validate_active_session_authority(authority)
    require(session is not None
            and session["nonce"] == base.get("outer_session_nonce"),
            "byte-identity completion requires one live supported outer session")
    state, inventory, command_inventory, cached_session = (
        terminal_verification_inputs(arguments)
    )
    require(cached_session is not None
            and cached_session["nonce"] == session["nonce"],
            "completion terminal verification session differs")
    require(
        len(state["images"]) == 1
        and state["images"][0]["identity"] == "LEGO1",
        "byte-identity completion requires the declared LEGO1 final image gate",
    )
    image_gate = state["images"][0]
    link_audit, link_audit_bytes = validate_final_link_audit(
        state, inventory, session
    )
    reccmp_audit, report_data = validate_final_reccmp_audit(
        state, inventory, session, link_audit, link_audit_bytes
    )
    image_path = Path(link_audit["image"])
    report_path = Path(reccmp_audit["report"])
    require_exact_build_namespace(
        authority,
        report_path.parent,
        expected_terminal_final_namespace(include_reccmp=True),
        "final LINK/reccmp artifact namespace",
    )
    recompiled = authority.read_bytes(image_path, max_bytes=1 << 30)
    original = authority.read_external_bytes(
        Path(image_gate["original_path"]), max_bytes=1 << 30
    )
    require(
        recompiled.startswith(b"MZ")
        and recompiled == original
        and len(recompiled) == image_gate["original_size"]
        and sha256_bytes(recompiled) == image_gate["original_sha256"]
        and md5_bytes(recompiled) == image_gate["original_md5"],
        "recompiled LEGO1 image is not byte-identical to the retail oracle",
    )
    row_result = validate_complete_reccmp_report(report_data, image_gate)
    final_record = {
        "identity": "LEGO1",
        "target": "lego1",
        "original_sha256": image_gate["original_sha256"],
        "original_md5": image_gate["original_md5"],
        "recompiled_sha256": sha256_bytes(recompiled),
        "recompiled_md5": md5_bytes(recompiled),
        "image_size": len(recompiled),
        "reccmp_report": str(report_path),
        "reccmp_report_sha256": sha256_bytes(report_data),
        "reccmp_schema": image_gate["reccmp_schema"],
        "link_audit": str(final_link_audit_path(arguments.build_dir, "LEGO1")),
        "link_audit_sha256": sha256_bytes(link_audit_bytes),
        "reccmp_audit": str(final_reccmp_audit_path(arguments.build_dir, "LEGO1")),
        "reccmp_audit_sha256": sha256_file(
            final_reccmp_audit_path(arguments.build_dir, "LEGO1")
        ),
        **row_result,
    }
    result = {
        **base,
        "status": "BYTE_IDENTITY_COMPLETE",
        "byte_identity_complete": True,
        "reason": (
            "All 4933 pinned LEGO1 reccmp rows have raw matching 1.0 at "
            "their retail addresses, and the recompiled image is byte-for-byte "
            "identical with the original SHA-256 and MD5."
        ),
        "final_images": [final_record],
    }
    validate_framework_verdict_document(result)
    if not publish:
        authority.revalidate_epoch()
        return result
    audit_root = authority.build_root / "byte-identity/audit"
    expected_audit = expected_top_level_audit_namespace(
        state, inventory, include_reccmp=True
    )
    verdict_path = audit_root / "framework-verdict.json"
    serialized = (
        json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    try:
        authority.revalidate_epoch()
        atomic_write(verdict_path, serialized)
        require_exact_build_namespace(
            authority,
            audit_root,
            {**expected_audit, "framework-verdict.json": "file"},
            "published complete byte-identity audit namespace",
            replace_pin=True,
        )
        require(authority.read_bytes(verdict_path) == serialized,
                "published complete framework verdict differs")
        authority.revalidate_epoch()
    except BaseException:
        authority.prune_leaf_or_redirect(verdict_path)
        authority.assert_absent(verdict_path)
        raise
    print(json.dumps(result, sort_keys=True))
    return 0


def command_complete(arguments: argparse.Namespace) -> int:
    raise ByteIdentityError(
        "terminal completion is published only by the resident outer driver"
    )


def command_invalidate_locked(arguments: argparse.Namespace) -> int:
    invalidate_framework_verdict(arguments.build_dir)
    return 0


def command_invalidate(arguments: argparse.Namespace) -> int:
    with build_transaction(arguments.build_dir, exclusive=True):
        return command_invalidate_locked(arguments)


def command_preconfigure_check(arguments: argparse.Namespace) -> int:
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    cmake = lexical_absolute_path(arguments.cmake).resolve(strict=True)
    require(cmake.is_file() and os.access(cmake, os.X_OK),
            "preconfigure CMake is not executable")
    with build_transaction(arguments.build_dir, exclusive=True) as authority:
        # This operation is intentionally first. Even a later session, source,
        # or CMake mismatch cannot leave a verdict from a prior build visible.
        invalidate_framework_verdict(arguments.build_dir)
        session = validate_active_session_authority(authority, arguments.nonce)
        require(session is not None,
                "preconfigure check requires the supported outer driver")
        require(session["source_root"] == str(arguments.source_dir.resolve())
                and session["build_root"] == str(authority.build_root)
                and session["cmake"] == str(cmake)
                and session["cmake_sha256"] == sha256_file(cmake),
                "preconfigure invocation differs from the active outer session")
        seal = {
            "schema": 1,
            "status": "BYTE_IDENTITY_PRECONFIGURE_SESSION_ATTESTED",
            "nonce": session["nonce"],
            "mode": session["mode"],
            "source_root": session["source_root"],
            "build_root": session["build_root"],
            "cmake": session["cmake"],
            "cmake_sha256": session["cmake_sha256"],
            "bootstrap_python": session["bootstrap_python"],
            "bootstrap_python_sha256": session["bootstrap_python_sha256"],
            "bootstrap_framework": session["bootstrap_framework"],
            "bootstrap_framework_sha256": session["bootstrap_framework_sha256"],
            "bootstrap_backend": session["bootstrap_backend"],
            "bootstrap_backend_sha256": session["bootstrap_backend_sha256"],
            "controller_root": session["controller_root"],
            "controller_descriptor_sha256": session[
                "controller_descriptor_sha256"
            ],
            "python": session["python"],
            "python_sha256": session["python_sha256"],
            "framework": session["framework"],
            "framework_sha256": session["framework_sha256"],
            "backend": session["backend"],
            "backend_tool": session["backend_tool"],
            "backend_tool_sha256": session["backend_tool_sha256"],
            "configure_init": session["configure_init"],
            "configure_init_sha256": session["configure_init_sha256"],
            "configure_probe_policy": session["configure_probe_policy"],
            "configure_tools": session["configure_tools"],
            "host_roots": session["host_roots"],
        }
        atomic_json(preconfigure_seal_path(arguments.build_dir), seal)
    return 0


def _outer_cmake_commands(
    arguments: argparse.Namespace, controller: dict,
) -> list[list[str]]:
    cmake = Path(controller["cmake_path"])
    python = Path(controller["python_path"])
    controller_root = Path(controller["root"])
    configure_init = Path(controller["configure_init"])
    extra = list(arguments.cmake_args)
    if extra and extra[0] == "--":
        extra.pop(0)
    require(all(isinstance(token, str) and token and "\0" not in token
                for token in extra),
            "outer CMake arguments contain an empty or unsafe token")
    if arguments.mode == "configure":
        folded = [token.casefold() for token in extra]
        # CMake's source/build short options allow both a separated operand
        # and an attached path.  Reject that complete grammar without treating
        # unrelated long options as a root override.
        require(not any(
            token == "--build"
            or re.fullmatch(r"-[sb].*", token) is not None
            for token in folded
        ), "outer configure arguments may not override -S/-B or select build mode")
        require(not any(
            token.startswith("-disle_byte_identical=")
            or token.startswith("-disle_byte_identity_driver_python=")
            for token in folded
        ), "outer configure arguments may not override hard-mode authority variables")
        protected = (
            "-dcmake_cxx_compiler", "-dcmake_rc_compiler", "-dcmake_ar",
            "-dcmake_linker", "-dcmake_cxx_compiler_linker",
            "-dcmake_cxx_compiler_id", "-dcmake_cxx_compiler_version",
            "-dcmake_cxx_compiler_works", "-dcmake_cxx_abi_compiled",
            "-dcmake_system_", "-dcmake_try_compile_target_type",
            "-dcmake_build_type", "-dcmake_toolchain_file",
        )
        require(not any(token in {"-c", "--toolchain", "-g", "-u"}
                        or token.startswith(protected)
                        or token.startswith(("-c", "-g", "-u"))
                        for token in folded),
                "outer configure arguments may not override the resident toolchain/init")
        return [[
            str(cmake), "-C", str(configure_init),
            "-G", "Unix Makefiles",
            "-S", str(arguments.source_dir.resolve()),
            "-B", str(arguments.build_dir.resolve()), *extra,
            f"-DCMAKE_BUILD_TYPE={RESIDENT_CMAKE_BUILD_TYPE}",
            "-DISLE_BYTE_IDENTICAL=ON",
            f"-DPython3_EXECUTABLE={python}",
            f"-DISLE_BYTE_IDENTITY_DRIVER_PYTHON={python}",
            f"-DISLE_BYTE_IDENTITY_CONTROLLER_ROOT={controller_root}",
        ]]
    require(arguments.mode in ("iterate", "build"),
            "outer CMake mode is invalid")
    normalized_build_request = [token.casefold() for token in extra]
    require(
        not normalized_build_request
        or (arguments.mode == "build" and normalized_build_request in (
            ["--target", "byte-identity-complete"],
            ["--target=byte-identity-complete"],
        )),
        "resident build arguments differ from the selected iteration/terminal mode",
    )
    regenerate = [
        str(cmake), "-C", str(configure_init),
        "-G", "Unix Makefiles",
        "-S", str(arguments.source_dir.resolve()),
        "-B", str(arguments.build_dir.resolve()),
        f"-DCMAKE_BUILD_TYPE={RESIDENT_CMAKE_BUILD_TYPE}",
        "-DISLE_BYTE_IDENTICAL=ON",
        f"-DPython3_EXECUTABLE={python}",
        f"-DISLE_BYTE_IDENTITY_DRIVER_PYTHON={python}",
        f"-DISLE_BYTE_IDENTITY_CONTROLLER_ROOT={controller_root}",
    ]
    # CMake is a configure/plan producer only.  The resident executes every
    # compiler, RC, LIB, LINK, and reccmp action from the validated closed plan.
    return [regenerate]


PRECONFIGURE_SESSION_KEYS = {
    "schema", "status", "nonce", "mode", "source_root", "build_root",
    "cmake", "cmake_sha256", "bootstrap_python",
    "bootstrap_python_sha256", "bootstrap_framework",
    "bootstrap_framework_sha256", "bootstrap_backend",
    "bootstrap_backend_sha256", "controller_root",
    "controller_descriptor_sha256", "python", "python_sha256",
    "framework", "framework_sha256", "backend", "backend_tool",
    "backend_tool_sha256", "configure_init", "configure_init_sha256",
    "configure_probe_policy", "configure_tools", "host_roots",
}


def preconfigure_session_document(active: dict) -> dict:
    return {
        "schema": 1,
        "status": "BYTE_IDENTITY_PRECONFIGURE_SESSION_ATTESTED",
        **{
            key: active[key]
            for key in PRECONFIGURE_SESSION_KEYS - {"schema", "status"}
        },
    }


def validate_preconfigure_session_seal(
    authority: BuildRootAuthority, active: dict,
) -> dict:
    seal = read_session_document(
        authority,
        preconfigure_seal_path(authority.build_root),
        "outer CMake pre-project session seal",
    )
    exact_audit_keys(
        seal, PRECONFIGURE_SESSION_KEYS,
        "outer CMake pre-project session seal",
    )
    expected = preconfigure_session_document(active)
    require(
        exact_json_equal(seal, expected),
        "outer CMake pre-project session seal differs",
    )
    return seal


def resident_rederive_inventory_locked(
    arguments: argparse.Namespace, controller: dict,
) -> argparse.Namespace:
    """Replace configure-child state with resident-authored inventory state."""
    authority = active_build_authority()
    raw = strict_json_loads(authority.read_bytes(inventory_path(arguments.build_dir)))
    require(isinstance(raw, dict), "configure inventory is not an object")
    compiler = raw.get("configured_compiler")
    require(isinstance(compiler, str) and Path(compiler).is_absolute(),
            "configure inventory compiler identity is absent")
    raw_entries = raw.get("entries")
    raw_targets = raw.get("targets")
    raw_inputs = raw.get("inputs")
    raw_graph = raw.get("link_graph")
    require(all(isinstance(value, list) for value in (
                raw_entries, raw_targets, raw_inputs, raw_graph)),
            "configure inventory plan arrays are invalid")
    graph_count = []
    graph_item = []
    for item in raw_graph:
        require(isinstance(item, dict)
                and isinstance(item.get("properties"), dict),
                "configure link graph plan entry is invalid")
        target = item.get("target")
        for property_name in NORMAL_TARGET_LINK_PROPERTIES:
            values = item["properties"].get(property_name)
            require(isinstance(values, list),
                    "configure link graph property is absent")
            graph_count.append([target, property_name, str(len(values))])
            graph_item.extend(
                [target, property_name, value] for value in values
            )
    inventory_arguments = argparse.Namespace(
        manifest=Path(controller["manifest_path"]),
        source_dir=arguments.source_dir.resolve(),
        build_dir=arguments.build_dir,
        compiler=compiler,
        cmake_module=Path(controller["cmake_module_path"]),
        output=inventory_path(arguments.build_dir),
        cmake_output=inventory_plan_path(arguments.build_dir),
        policy_stamp=policy_stamp_path(arguments.build_dir),
        emit_cmake=False,
        entry=[
            [item.get("target"), item.get("source_path"), item.get("language"),
             str(item.get("target_ordinal"))]
            # The typed source overlay adds a fifth authority column; the
            # resident replays it and normalized_inventory_entries re-verifies
            # the claimed authority against the manifest overlay universe.
            + ([item["source_authority"]]
               if "source_authority" in item else [])
            for item in raw_entries if isinstance(item, dict)
        ],
        target_entry=[
            [item.get("target"), item.get("kind"),
             "TRUE" if item.get("default_build") is True else "FALSE"]
            for item in raw_targets if isinstance(item, dict)
        ],
        input_entry=[
            [item.get("target"), item.get("source_path"), item.get("kind"),
             str(item.get("target_ordinal"))]
            for item in raw_inputs if isinstance(item, dict)
        ],
        graph_count=graph_count,
        graph_item=graph_item,
        standard_library_configuration=(
            raw.get("generator_standard_libraries", {}).get("configuration")
            if isinstance(raw.get("generator_standard_libraries"), dict)
            else None
        ),
        standard_library_base_count=(
            str(len(raw["generator_standard_libraries"]["base"]))
            if isinstance(raw.get("generator_standard_libraries"), dict)
            and isinstance(raw["generator_standard_libraries"].get("base"), list)
            else None
        ),
        standard_library_base_item=(
            list(raw["generator_standard_libraries"]["base"])
            if isinstance(raw.get("generator_standard_libraries"), dict)
            and isinstance(raw["generator_standard_libraries"].get("base"), list)
            else []
        ),
        standard_library_config_count=(
            str(len(raw["generator_standard_libraries"]["configuration_specific"]))
            if isinstance(raw.get("generator_standard_libraries"), dict)
            and isinstance(raw["generator_standard_libraries"].get(
                "configuration_specific"
            ), list)
            else None
        ),
        standard_library_config_item=(
            list(raw["generator_standard_libraries"]["configuration_specific"])
            if isinstance(raw.get("generator_standard_libraries"), dict)
            and isinstance(raw["generator_standard_libraries"].get(
                "configuration_specific"
            ), list)
            else []
        ),
    )
    command_inventory_locked(inventory_arguments)
    command_arguments = argparse.Namespace(
        manifest=inventory_arguments.manifest,
        source_dir=inventory_arguments.source_dir,
        build_dir=inventory_arguments.build_dir,
        compiler=compiler,
        compile_commands=arguments.build_dir / "compile_commands.json",
        output=command_inventory_path(arguments.build_dir),
        policy_stamp=command_policy_stamp_path(arguments.build_dir),
    )
    command_attest_commands_locked(command_arguments)
    return argparse.Namespace(
        manifest=inventory_arguments.manifest,
        source_dir=inventory_arguments.source_dir,
        build_dir=inventory_arguments.build_dir,
        compiler=compiler,
    )


def _parse_cmake_set_file(data: bytes, context: str) -> dict[str, str]:
    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise ByteIdentityError(f"{context} is not UTF-8") from error
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped.startswith("set("):
            continue
        match = re.fullmatch(
            r'set\(([A-Za-z_][A-Za-z0-9_]*)'
            r'(?:\s+"((?:[^"\\]|\\.)*)"|\s+([^()\s]*))?\)',
            stripped,
        )
        require(match is not None, f"{context} has unsupported set grammar")
        name = match.group(1)
        require(name not in result, f"{context} duplicates {name}")
        quoted = match.group(2)
        result[name] = (
            bytes(quoted, "utf-8").decode("unicode_escape")
            if quoted is not None else (match.group(3) or "")
        )
    return result


def validate_resident_configure_metadata(
    build_dir: Path, compiler: Path, tools: dict[str, str],
) -> dict:
    """Prove configure used forced VC4.2 facts and emitted a Make plan."""
    authority = active_build_authority()
    cache_path = authority.build_root / "CMakeCache.txt"
    cache = {}
    for line in authority.read_text(cache_path).splitlines():
        if not line or line.startswith(("#", "//")) or "=" not in line:
            continue
        key_type, value = line.split("=", 1)
        if ":" not in key_type:
            continue
        key, _type = key_type.split(":", 1)
        require(key not in cache, f"CMake cache duplicates {key}")
        cache[key] = value
    require(cache.get("CMAKE_GENERATOR") == "Unix Makefiles"
            and cache.get("CMAKE_BUILD_TYPE") == RESIDENT_CMAKE_BUILD_TYPE
            and cache.get("CMAKE_EXPORT_COMPILE_COMMANDS") == "ON"
            and cache.get("CMAKE_SYSTEM_NAME") == "Windows"
            and cache.get("CMAKE_SYSTEM_PROCESSOR") == "x86"
            and cache.get("CMAKE_CXX_COMPILER_ID") == "MSVC"
            and cache.get("CMAKE_CXX_COMPILER_VERSION") == "10.20"
            and cache.get("CMAKE_CXX_PLATFORM_ID") == "Windows"
            and cache.get("CMAKE_CXX_COMPILER_ARCHITECTURE_ID") == "X86"
            and cache.get("CMAKE_CXX_COMPILER_ID_RUN") == "1"
            and cache.get("CMAKE_CXX_COMPILER_FORCED") == "TRUE"
            and cache.get("CMAKE_CXX_COMPILER_WORKS") == "TRUE"
            and cache.get("CMAKE_CXX_ABI_COMPILED") == "TRUE"
            and cache.get("CMAKE_RC_COMPILER") == tools["rc"]
            and cache.get("CMAKE_AR") == tools["lib"]
            and cache.get("CMAKE_LINKER") == tools["link"]
            and cache.get("CMAKE_CXX_COMPILER_LINKER") == tools["link"]
            and cache.get("CMAKE_CXX_COMPILER_LINKER_ID") == "MSVC"
            and cache.get("CMAKE_CXX_COMPILER_LINKER_VERSION") == "4.20"
            and cache.get("CMAKE_CXX_COMPILER_LINKER_FRONTEND_VARIANT") == "MSVC",
            "resident configure cache differs from the zero-probe policy")
    cached_compiler = cache.get("CMAKE_CXX_COMPILER")
    require(isinstance(cached_compiler, str)
            and lexical_absolute_path(Path(cached_compiler)).resolve(strict=True)
            == compiler.resolve(strict=True),
            "resident configure compiler path differs")
    candidates = []
    cmake_files = authority.build_root / "CMakeFiles"
    for name in authority.list_names(cmake_files):
        entry = cmake_files / name
        entry_metadata = authority.lstat(entry)
        require(entry_metadata is not None,
                "generated CMakeFiles entry disappeared")
        if not stat.S_ISDIR(entry_metadata.st_mode):
            continue
        candidate = entry / "CMakeCXXCompiler.cmake"
        metadata = authority.lstat(candidate)
        if metadata is not None:
            require(stat.S_ISREG(metadata.st_mode),
                    "generated CMake compiler metadata is redirected")
            candidates.append(candidate)
    require(len(candidates) == 1,
            "resident configure has no unique CMake compiler metadata")
    values = _parse_cmake_set_file(
        authority.read_bytes(candidates[0]), "CMake compiler metadata"
    )
    expected = {
        "CMAKE_CXX_COMPILER": str(compiler),
        "CMAKE_CXX_COMPILER_ID": "MSVC",
        "CMAKE_CXX_COMPILER_VERSION": "10.20",
        "CMAKE_CXX_PLATFORM_ID": "Windows",
        "CMAKE_CXX_COMPILER_ARCHITECTURE_ID": "X86",
        "CMAKE_CXX_COMPILER_LOADED": "1",
        "CMAKE_CXX_COMPILER_WORKS": "TRUE",
        "CMAKE_CXX_ABI_COMPILED": "TRUE",
        "CMAKE_CXX_COMPILER_ID_RUN": "1",
        "CMAKE_AR": tools["lib"],
        "CMAKE_LINKER": tools["link"],
        "CMAKE_CXX_COMPILER_LINKER": tools["link"],
        "CMAKE_CXX_COMPILER_LINKER_ID": "MSVC",
        "CMAKE_CXX_COMPILER_LINKER_VERSION": "4.20",
        "CMAKE_CXX_COMPILER_LINKER_FRONTEND_VARIANT": "MSVC",
        "CMAKE_CXX_SIZEOF_DATA_PTR": "4",
        "CMAKE_CXX_BYTE_ORDER": "LITTLE_ENDIAN",
        "CMAKE_CXX_IMPLICIT_INCLUDE_DIRECTORIES": "",
        "CMAKE_CXX_IMPLICIT_LINK_LIBRARIES": "",
        "CMAKE_CXX_IMPLICIT_LINK_DIRECTORIES": "",
        "CMAKE_CXX_IMPLICIT_LINK_FRAMEWORK_DIRECTORIES": "",
    }
    mismatches = {
        key: {"expected": value, "observed": values.get(key)}
        for key, value in expected.items() if values.get(key) != value
    }
    require(not mismatches,
            "generated CMake compiler metadata differs from forced VC4.2 facts: "
            + json.dumps(mismatches, sort_keys=True))
    return {
        "cache": str(cache_path), "cache_sha256": sha256_file(cache_path),
        "compiler_metadata": str(candidates[0]),
        "compiler_metadata_sha256": sha256_file(candidates[0]),
        "probe_policy": "zero_compiler_actions_forced_manifest_facts_v1",
    }


def _resident_make_variables(data: bytes, context: str) -> dict[str, str]:
    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise ByteIdentityError(f"{context} is not UTF-8") from error
    result = {}
    for line in text.splitlines():
        match = re.fullmatch(r"([A-Z][A-Z0-9_]*) = ?(.*)", line)
        if match is None:
            continue
        name, value = match.groups()
        require(name not in result, f"{context} duplicates {name}")
        result[name] = value
    required = {
        "CXX_DEFINES", "CXX_INCLUDES", "CXX_FLAGS",
        "RC_DEFINES", "RC_INCLUDES", "RC_FLAGS",
    }
    require(required <= set(result), f"{context} omits compiler variables")
    return result


def _resident_recipe_tokens(
    line: str, variables: dict[str, str], context: str,
) -> list[str]:
    expanded = line.lstrip("\t")
    for name, value in variables.items():
        expanded = expanded.replace(f"$({name})", value)
    require("$(" not in expanded and "`" not in expanded
            and "&&" not in expanded and "||" not in expanded,
            f"{context} retains a Make/shell expansion")
    return _command_database_tokens(expanded, context)


def _resident_expected_producer_prefix(
    session: dict, subcommand: str, target: str, compiler: str,
    *, identity: str | None = None,
) -> list[str]:
    require(subcommand in {"compile-dispatch", "archive-launch", "link-launch"},
            "resident producer prefix kind is invalid")
    prefix = [
        session["python"], "-I", "-B", session["framework"], subcommand,
        "--manifest", str(Path(session["controller_root"])
                          / "framework/tools/byte_identity_manifest.json"),
        "--source-dir", session["source_root"],
        "--build-dir", session["build_root"],
        "--target", target,
    ]
    if identity is not None:
        prefix.extend(["--identity", identity])
    prefix.extend(["--configured-compiler", compiler, "--"])
    return prefix


def _resident_expected_compile_prefix(
    session: dict, target: str, compiler: str,
) -> list[str]:
    return [
        session["python"], "-I", "-B", session["framework"],
        "compile-launch",
        "--manifest", str(Path(session["controller_root"])
                          / "framework/tools/byte_identity_manifest.json"),
        "--source-dir", session["source_root"],
        "--build-dir", session["build_root"],
        "--target", target,
        "--configured-compiler", compiler, "--",
    ]


def _resident_unwrap_producer(
    tokens: list[str], expected_prefix: list[str], context: str,
) -> list[str]:
    require(tokens[:len(expected_prefix)] == expected_prefix,
            f"{context} controller launcher prefix differs")
    child = tokens[len(expected_prefix):]
    require(child and not raw_argument_token_errors(child),
            f"{context} producer argv is empty or unsafe")
    return child


def _resident_rc_target_recipes(
    *, session: dict, compiler: str, target: str,
    resource_inputs: list[dict], compile_entries: list[dict],
    flags_data: bytes, make_data: bytes,
) -> tuple[list[dict], list[dict]]:
    """Authenticate one RC-bearing target's complete generated Make surface.

    CMake omits launcher prefixes from compile_commands.json, but its Make
    recipes retain the actual target RULE_LAUNCH_COMPILE and language launcher
    chains.  Bind both projections: raw compiler argv comes from the command
    database, while this parser requires every C/C++ recipe on an RC-bearing
    target to be compile-dispatch -> compile-launch -> that exact raw argv.
    The RC output is authoritative only after the analogous wrapped RC recipe
    has been parsed; configure inventory intentionally does not invent it.
    """
    authority = active_build_authority()
    variables = _resident_make_variables(
        flags_data, f"resident {target} flags.make"
    )
    try:
        make_text = make_data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as error:
        raise ByteIdentityError(
            f"resident {target} build.make is not UTF-8"
        ) from error
    lines = list(enumerate(make_text.splitlines(), start=1))
    dispatcher = _resident_expected_producer_prefix(
        session, "compile-dispatch", target, compiler
    )
    compiler_launcher = _resident_expected_compile_prefix(
        session, target, compiler
    )

    resources = []
    for item in sorted(resource_inputs,
                       key=lambda value: value["target_ordinal"]):
        matches = []
        for line_number, line in lines:
            if not line.startswith("\t") or item["source_path"] not in line:
                continue
            tokens = _resident_recipe_tokens(
                line, variables,
                f"resident {target} resource recipe line {line_number}",
            )
            if tokens[:len(dispatcher)] != dispatcher:
                continue
            child = _resident_unwrap_producer(
                tokens, dispatcher, f"resident {target} resource recipe"
            )
            source, output, _roles = parse_resource_command(
                child, authority.build_root
            )
            if source == Path(item["source_path"]):
                matches.append((child, output, tokens))
        require(len(matches) == 1,
                f"resident RC recipe is absent or duplicated: {item['source']}")
        child, output, tokens = matches[0]
        resources.append({
            "target": target, "source": item["source"],
            "target_ordinal": item["target_ordinal"],
            "cwd": str(authority.build_root), "argv": child,
            "argv_sha256": stable_argv_sha256(child),
            "output": str(output),
            "recipe_argv_sha256": stable_argv_sha256(tokens),
        })

    dispatches = []
    for entry in sorted(compile_entries,
                        key=lambda value: (value["target"], value["source"])):
        require(entry["target"] == target,
                "resident compiler recipe target differs")
        require(Path(entry["directory"]) == authority.build_root,
                f"resident {target} compiler recipe cwd is unsupported")
        matches = []
        for line_number, line in lines:
            if not line.startswith("\t") or entry["source_path"] not in line:
                continue
            tokens = _resident_recipe_tokens(
                line, variables,
                f"resident {target} compiler recipe line {line_number}",
            )
            if tokens[:len(dispatcher)] != dispatcher:
                continue
            nested = _resident_unwrap_producer(
                tokens, dispatcher, f"resident {target} compiler dispatcher"
            )
            if nested[:len(compiler_launcher)] != compiler_launcher:
                continue
            raw = _resident_unwrap_producer(
                nested, compiler_launcher,
                f"resident {target} compiler launcher",
            )
            if raw == entry["argv"]:
                matches.append(tokens)
        require(
            len(matches) == 1,
            "resident C/C++ dispatcher recipe is absent, duplicated, or "
            f"differs from the command database: {target}:{entry['source']}",
        )
        dispatches.append({
            "target": target, "source": entry["source"],
            "raw_argv_sha256": entry["argv_sha256"],
            "recipe_argv_sha256": stable_argv_sha256(matches[0]),
        })
    return resources, dispatches


def _resident_static_archive_order(inventory: dict) -> list[str]:
    static = {
        item["target"] for item in inventory["targets"]
        if item["kind"] == "STATIC_LIBRARY"
    }
    graph = {item["target"]: item for item in inventory["link_graph"]}
    require(static <= set(graph), "static archive target is absent from link graph")
    result = []
    temporary = set()
    complete = set()

    def visit(target: str) -> None:
        require(target not in temporary,
                f"first-party archive graph has a cycle at {target}")
        if target in complete:
            return
        temporary.add(target)
        for token in graph[target]["resolved_links"]:
            if token in static:
                visit(token)
        temporary.remove(target)
        complete.add(target)
        result.append(target)

    for target in sorted(static):
        visit(target)
    require(set(result) == static and len(result) == len(static),
            "first-party archive topological order differs")
    return result


def _derive_resident_closed_plan_at_root(
    arguments: argparse.Namespace, verification: argparse.Namespace,
    controller: dict, session: dict, plan_root: Path,
) -> dict:
    """Copy and authenticate only producer recipes; never execute Make."""
    authority = active_build_authority()
    state = validate_manifest(
        verification.manifest, verification.source_dir,
        verification.build_dir, configured_compiler=verification.compiler,
    )
    inventory = load_inventory(state, verification.build_dir)
    command_inventory = load_command_inventory(
        state, inventory, verification.build_dir
    )
    metadata = validate_resident_configure_metadata(
        verification.build_dir, Path(verification.compiler),
        session["configure_tools"],
    )
    file_records = []
    expected_plan = new_snapshot_destination_expectation(plan_root)

    def copy_recipe(path: Path, relative: Path) -> bytes:
        path = lexical_absolute_path(path)
        authority.parts(path)
        data = authority.read_bytes(path, max_bytes=64 * 1024 * 1024)
        destination = plan_root / relative
        authority.atomic_write(destination, data, mode=0o400)
        record = {
            "logical_path": str(path), "private_path": str(destination),
            "sha256": sha256_bytes(data), "size": len(data),
        }
        file_records.append(record)
        add_expected_snapshot_file(expected_plan, destination, {
            "mode": 0o400, "size": len(data),
            "sha256": record["sha256"],
        })
        return data

    copy_recipe(
        authority.build_root / "compile_commands.json",
        Path("compile_commands.json"),
    )
    resources = []
    compile_dispatches = []
    inputs_by_target: dict[str, list[dict]] = defaultdict(list)
    for item in inventory["inputs"]:
        if item["kind"] == "RC":
            inputs_by_target[item["target"]].append(item)
    for target in sorted(inputs_by_target):
        flags_data = copy_recipe(
            authority.build_root / f"CMakeFiles/{target}.dir/flags.make",
            Path(f"targets/{target}/flags.make"),
        )
        make_data = copy_recipe(
            authority.build_root / f"CMakeFiles/{target}.dir/build.make",
            Path(f"targets/{target}/build.make"),
        )
        target_resources, target_dispatches = _resident_rc_target_recipes(
            session=session, compiler=verification.compiler, target=target,
            resource_inputs=inputs_by_target[target],
            compile_entries=[
                item for item in command_inventory["entries"]
                if item["target"] == target
            ],
            flags_data=flags_data, make_data=make_data,
        )
        resources.extend(target_resources)
        compile_dispatches.extend(target_dispatches)

    archives = []
    for target in _resident_static_archive_order(inventory):
        link_data = copy_recipe(
            authority.build_root / f"CMakeFiles/{target}.dir/link.txt",
            Path(f"targets/{target}/link.txt"),
        )
        rsp = authority.build_root / f"CMakeFiles/{target}.dir/objects1.rsp"
        copy_recipe(rsp, Path(f"targets/{target}/objects1.rsp"))
        text = link_data.decode("utf-8", errors="strict")
        require(len([line for line in text.splitlines() if line.strip()]) == 1,
                f"resident {target} archive recipe is not one command")
        tokens = _command_database_tokens(text.strip(),
                                           f"resident {target} archive recipe")
        prefix = _resident_expected_producer_prefix(
            session, "archive-launch", target, verification.compiler
        )
        child = _resident_unwrap_producer(
            tokens, prefix, f"resident {target} archive recipe"
        )
        output, inputs, _records, response_paths, _expanded = (
            parse_archive_command(child, authority.build_root)
        )
        require(response_paths == [rsp],
                f"resident {target} archive response-file seat differs")
        archives.append({
            "target": target, "cwd": str(authority.build_root),
            "argv": child, "argv_sha256": stable_argv_sha256(child),
            "output": str(output), "ordered_inputs": list(map(str, inputs)),
            "response": str(rsp),
        })

    link_data = copy_recipe(
        authority.build_root / "CMakeFiles/lego1.dir/link.txt",
        Path("targets/lego1/link.txt"),
    )
    link_rsp = authority.build_root / "CMakeFiles/lego1.dir/objects1.rsp"
    copy_recipe(link_rsp, Path("targets/lego1/objects1.rsp"))
    link_text = link_data.decode("utf-8", errors="strict")
    require(len([line for line in link_text.splitlines() if line.strip()]) == 1,
            "resident LEGO1 link recipe is not one command")
    link_tokens = _command_database_tokens(
        link_text.strip(), "resident LEGO1 link recipe"
    )
    link_prefix = _resident_expected_producer_prefix(
        session, "link-launch", "lego1", verification.compiler,
        identity="LEGO1",
    )
    link_child = _resident_unwrap_producer(
        link_tokens, link_prefix, "resident LEGO1 link recipe"
    )
    state["inventory"] = inventory
    planned_inputs = {}
    resources_by_owner = {
        (item["target"], item["source"]): item for item in resources
    }
    for index, item in enumerate(command_inventory["entries"]):
        planned_inputs[f"@object:{index}"] = Path(item["object"])
    for index, item in enumerate(inventory["inputs"]):
        if item["kind"] == "RC":
            owner = resources_by_owner.get((item["target"], item["source"]))
            require(owner is not None,
                    "resident RC input has no authenticated recipe output")
            planned_inputs[f"@resource:{index}"] = Path(owner["output"])
    for item in archives:
        path = Path(item["output"])
        require(path.name.casefold() not in planned_inputs,
                f"resident planned archive basename collides: {path.name}")
        planned_inputs[path.name.casefold()] = path
    for item in state["archives"]:
        path = Path(item["output"])
        require(path.name.casefold() not in planned_inputs,
                f"resident authorized archive basename collides: {path.name}")
        planned_inputs[path.name.casefold()] = path
    parsed_link = parse_link_command(
        link_child, authority.build_root, state, planned_inputs=planned_inputs
    )
    require(parsed_link["response_paths"] == [link_rsp],
            "resident LEGO1 response-file seat differs")
    command_by_owner = {
        (item["target"], item["source"]): item
        for item in command_inventory["entries"]
    }
    expected_direct = []
    for item in sorted([
        *[entry for entry in inventory["entries"] if entry["target"] == "lego1"],
        *[entry for entry in inventory["inputs"]
          if entry["target"] == "lego1" and entry["kind"] == "RC"],
    ], key=lambda value: value["target_ordinal"]):
        expected_direct.append(
            command_by_owner[("lego1", item["source"])]["object"]
            if item.get("language") in SUPPORTED_SOURCE_LANGUAGES
            else resources_by_owner[("lego1", item["source"])]["output"]
        )
    require(list(map(str, parsed_link["direct"])) == expected_direct,
            "resident LEGO1 direct object/resource sequence differs")
    logical_libraries = [path.name.casefold() for path in parsed_link["libraries"]]
    link_policy = state["terminal_producers"]["link"]
    terminal_link_graph_authority(state, inventory)
    require_terminal_generator_standard_library_suffix(
        state, inventory, logical_libraries, "resident LEGO1"
    )
    require(len(logical_libraries)
            == link_policy["ordered_library_occurrence_count"]
            and sha256_bytes(("\n".join(logical_libraries) + "\n").encode())
            == link_policy["ordered_library_identity_sha256"],
            "resident LEGO1 library occurrence order differs")
    link = {
        "target": "lego1", "identity": "LEGO1",
        "cwd": str(authority.build_root), "argv": link_child,
        "argv_sha256": stable_argv_sha256(link_child),
        "direct_inputs": list(map(str, parsed_link["direct"])),
        "library_inputs": list(map(str, parsed_link["libraries"])),
        "response": str(link_rsp),
    }
    plan = {
        "schema": 1,
        "status": "RESIDENT_CLOSED_PRODUCER_PLAN",
        "nonce": session["nonce"],
        "root": str(plan_root),
        "manifest_sha256": state["manifest_sha256"],
        "configure_inventory_sha256": sha256_file(
            inventory_path(verification.build_dir)
        ),
        "command_inventory_sha256": sha256_file(
            command_inventory_path(verification.build_dir)
        ),
        "configure_metadata": metadata,
        "files": file_records,
        "compiles": [{
            "target": item["target"], "source": item["source"],
            "target_ordinal": item["target_ordinal"],
            "directory": item["directory"], "object": item["object"],
            "pdb": item["pdb"], "argv": item["argv"],
            "argv_sha256": item["argv_sha256"],
        } for item in command_inventory["entries"]],
        "compile_dispatches": compile_dispatches,
        "resources": resources,
        "archives": archives,
        "link": link,
        "producer_policy": "resident_direct_no_cmake_build_v1",
    }
    descriptor = plan_root / "plan.json"
    descriptor_data = (
        json.dumps(plan, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    authority.atomic_write(descriptor, descriptor_data, mode=0o400)
    add_expected_snapshot_file(expected_plan, descriptor, {
        "mode": 0o400, "size": len(descriptor_data),
        "sha256": sha256_bytes(descriptor_data),
    })
    validate_expected_snapshot_destination(
        expected_plan, "resident closed-plan snapshot"
    )
    holder = authority.retain_directories([
        plan_root,
        *(plan_root / "targets" / target
          for target in {item["target"] for item in [*resources, *archives, link]}),
    ])
    for item in file_records:
        require(
            sha256_bytes(holder.read_bytes(Path(item["private_path"])))
            == item["sha256"],
            f"resident copied recipe changed before hold: {item['logical_path']}",
        )
    require(holder.read_bytes(descriptor) == descriptor_data,
            "resident plan descriptor changed before hold")
    holder.revalidate()
    plan["descriptor"] = str(descriptor)
    plan["descriptor_sha256"] = sha256_bytes(descriptor_data)
    plan["holder"] = holder
    return plan


def derive_resident_closed_plan(
    arguments: argparse.Namespace, verification: argparse.Namespace,
    controller: dict, session: dict,
) -> dict:
    """Derive the one session-owned plan at its deterministic cleanup seat."""
    authority = active_build_authority()
    plan_root = resident_plan_path(authority.build_root, session["nonce"])
    authority.mkdirs(plan_root.parent)
    require(authority.lstat(plan_root) is None,
            "resident session plan seat is not empty")
    created = False
    try:
        authority.mkdir_exclusive(plan_root)
        created = True
        return _derive_resident_closed_plan_at_root(
            arguments, verification, controller, session, plan_root
        )
    except BaseException:
        if created:
            rollback_exact_private_run(authority, plan_root)
        raise


@contextmanager
def resident_working_directory(path: Path):
    previous = Path.cwd()
    os.chdir(path)
    try:
        yield
    finally:
        os.chdir(previous)


def resident_nonterminal_leaf_audits(
    state: dict, plan: dict, compiler_audits: dict[str, Path],
    resource_audits: dict[str, Path],
) -> list[Path]:
    """Return the exact manifest-pinned produced audits not feeding LEGO1."""
    consumed_outputs = set(plan["link"]["direct_inputs"])
    for archive in plan["archives"]:
        consumed_outputs.update(archive["ordered_inputs"])
    observed: dict[str, dict] = {}
    leaves: list[tuple[str, int, str, Path]] = []

    def add(target: str, kind: str, ordinal: int, output: str,
            audits: dict[str, Path]) -> None:
        if output in consumed_outputs:
            return
        audit = audits.get(output)
        require(audit is not None,
                f"resident nonterminal {kind} output lacks its audit: {output}")
        counts = observed.setdefault(target, {
            "target": target, "compiler_audit_count": 0,
            "resource_audit_count": 0,
        })
        counts[f"{kind}_audit_count"] += 1
        leaves.append((target, ordinal, kind, audit))

    for item in plan["compiles"]:
        add(item["target"], "compiler", item["target_ordinal"],
            item["object"], compiler_audits)
    for item in plan["resources"]:
        add(item["target"], "resource", item["target_ordinal"],
            item["output"], resource_audits)
    observed_policy = [observed[target] for target in sorted(observed)]
    expected_policy = state["terminal_producers"]["link"][
        "verified_nonterminal_leaf_audits"
    ]
    require(exact_json_equal(observed_policy, expected_policy),
            "resident verified nonterminal leaf-audit universe differs")
    leaves.sort(key=lambda item: (item[0], item[1], item[2], str(item[3])))
    require(len({str(item[3]) for item in leaves}) == len(leaves),
            "resident verified nonterminal leaf audit is duplicated")
    return [item[3] for item in leaves]


def resident_reccmp_backend_roots(
    state: dict, build_dir: Path,
) -> list[tuple[str, Path]]:
    """Return only roots authenticated by the selected reccmp adapter."""
    require_posix_reccmp_backend(state, "resident reccmp DAG")
    native = native_reccmp_snapshot_path(build_dir)
    return [
        ("native_reccmp_snapshot", native / "snapshot.json"),
        ("reccmp_tool", native / "tool/reccmp.py"),
        ("reccmp_source_interpreter",
         native / "interpreter/pinned-interpreter"),
        ("reccmp_private_interpreter", native / "runtime/bin/python3.12"),
        ("reccmp_private_framework", native / "runtime/lib/Python"),
    ]


def execute_resident_closed_plan(
    verification: argparse.Namespace, controller: dict, session: dict,
    plan: dict, ledger: ResidentReceiptLedger, *, terminal: bool,
) -> tuple[dict, list[HeldBuildDirectories]]:
    """Execute the complete producer DAG directly in the resident process."""
    authority = active_build_authority()
    state = validate_manifest(
        verification.manifest, verification.source_dir,
        verification.build_dir, configured_compiler=verification.compiler,
    )
    inventory = load_inventory(state, verification.build_dir)
    command_inventory = load_command_inventory(
        state, inventory, verification.build_dir
    )
    state["inventory"] = inventory
    state["command_inventory"] = command_inventory
    seed_resident_producer_state_cache(
        verification, state, inventory, command_inventory, session
    )
    holders = [plan["holder"]]
    plan["_resident_holders"] = holders
    stage_counts = Counter()
    expected_stage_counts = {
        name: 0 for name in RESIDENT_PRODUCER_STAGES
    }
    required_root_roles = set()

    def root(path: Path, role: str) -> Path:
        ledger.record_root_once(path, role=role)
        required_root_roles.add(role)
        return path

    def produced(
        path: Path, stage: str, role: str, inputs: list[Path],
    ) -> Path:
        record = ledger.record_produced(
            path, stage=stage, role=role, inputs=inputs
        )
        holder = authority.retain_directories([Path(record["path"]).parent])
        holder.read_bytes(Path(record["path"]))
        holders.append(holder)
        stage_counts[stage] += 1
        return path

    controller_descriptor = root(
        Path(controller["root"]) / "snapshot.json", "controller_snapshot"
    )
    configure_init = root(
        configure_init_path(verification.build_dir), "configure_init"
    )
    manifest = root(verification.manifest, "manifest")
    framework = root(Path(controller["tool_path"]), "resident_framework")
    backend = root(Path(controller["backend_path"]), "resident_backend")
    entropy = root(Path(controller["entropy_path"]), "resident_entropy")
    configure_inventory = root(
        inventory_path(verification.build_dir), "configure_inventory"
    )
    configure_policy = root(
        policy_stamp_path(verification.build_dir), "configure_policy"
    )
    generated_commands = root(
        command_inventory_path(verification.build_dir), "command_inventory"
    )
    generated_policy = root(
        command_policy_stamp_path(verification.build_dir), "command_policy"
    )
    compile_database = root(
        authority.build_root / "compile_commands.json", "compile_database"
    )
    toolchain_descriptor = root(
        toolchain_snapshot_path(verification.build_dir) / "snapshot.json",
        "toolchain_snapshot",
    )
    command_descriptor = root(
        command_snapshot_path(verification.build_dir) / "snapshot.json",
        "source_header_snapshot",
    )
    plan_descriptor = root(Path(plan["descriptor"]), "resident_closed_plan")
    configure_cache = root(
        Path(plan["configure_metadata"]["cache"]), "configure_cache"
    )
    compiler_metadata = root(
        Path(plan["configure_metadata"]["compiler_metadata"]),
        "configure_compiler_metadata",
    )
    sealed_z = toolchain_snapshot_path(verification.build_dir) / "z"
    compiler_tool = root(
        absolute_snapshot_seat(sealed_z, Path(verification.compiler)),
        "compiler_tool",
    )
    link_tools = {
        item["role"]: root(
            absolute_snapshot_seat(sealed_z, Path(item["absolute_path"])),
            "producer_tool:" + item["role"],
        )
        for item in state["terminal_producers"]["link"]["tools"]
    }
    common_plan_inputs = [
        controller_descriptor, configure_init, manifest, framework, backend,
        configure_inventory, configure_policy, generated_commands,
        generated_policy, compile_database, toolchain_descriptor,
        command_descriptor, plan_descriptor, configure_cache,
        compiler_metadata,
    ]
    expected_stage_counts.update({
        "source-overlay-materialization": (
            1 if state["source_overlay"]["enabled"] else 0
        ),
        "materialize-header": len(state["recipes"]),
        "materialize-audit": len(state["recipes"]),
        "vendor-archive": len(state["archives"]),
        "vendor-archive-audit": len(state["archives"]),
        "compiler-dependency": len(plan["compiles"]),
        "compiler-seed-object": len(plan["compiles"]),
        "compiler-seed-pdb": len(plan["compiles"]),
        "compiler-object": len(plan["compiles"]),
        "compiler-pdb": len(plan["compiles"]),
        "compiler-audit": len(plan["compiles"]),
        "resource-output": len(plan["resources"]),
        "resource-audit": len(plan["resources"]),
        "first-party-archive": len(plan["archives"]),
        "first-party-archive-audit": len(plan["archives"]),
        "dual-link-output": 11,
        "dual-link-audit": 1,
        "reccmp-report": 1,
        "reccmp-log": 1,
        "reccmp-audit": 1,
        "execution-projection-finalization": 1,
    })

    # The effective source universe is materialized into the one held
    # execution projection before any compiler can consume it.  Make its
    # in-memory-bound receipt a resident-produced ledger stage, rather than a
    # neighboring JSON document which later artifacts could cite without a
    # causal edge.
    if state["source_overlay"]["enabled"]:
        projection = materialize_execution_projection(
            state, verification.build_dir
        )
        overlay_receipt = source_overlay_receipt_path(
            verification.build_dir
        )
        require(
            projection.get("source_overlay_enabled") is True
            and projection.get("source_overlay_receipt_path")
            == overlay_receipt,
            "resident source overlay receipt lacks its held projection",
        )
        produced(
            overlay_receipt, "source-overlay-materialization",
            "source-overlay:materialization",
            [manifest, toolchain_descriptor, command_descriptor,
             plan_descriptor],
        )
        common_plan_inputs.append(overlay_receipt)

    materialization_outputs = {}
    for recipe in state["recipes"]:
        output = Path(recipe["header_output"])
        arguments = argparse.Namespace(
            manifest=verification.manifest,
            source_dir=verification.source_dir,
            build_dir=verification.build_dir,
            recipe_id=recipe["id"], output=output,
        )
        command_materialize_locked(arguments)
        inputs = [manifest, entropy, plan_descriptor]
        produced(output, "materialize-header", f"header:{recipe['id']}", inputs)
        audit = (
            authority.build_root / "byte-identity/audit/materialization"
            / f"{recipe['id']}.json"
        )
        produced(
            audit, "materialize-audit", f"header-audit:{recipe['id']}",
            [output, *inputs],
        )
        materialization_outputs[recipe["id"]] = (output, audit)

    authorized_outputs = {}
    for archive in state["archives"]:
        source = root(
            Path(archive["source_path"]),
            "authorized_archive_source:" + archive["identity"],
        )
        output = Path(archive["output"])
        arguments = argparse.Namespace(
            manifest=verification.manifest,
            source_dir=verification.source_dir,
            build_dir=verification.build_dir,
            identity=archive["identity"], output=output,
        )
        command_materialize_archive_locked(arguments)
        inputs = [manifest, plan_descriptor, source]
        produced(
            output, "vendor-archive", f"vendor:{archive['identity']}", inputs
        )
        audit = Path(archive["audit"])
        produced(
            audit, "vendor-archive-audit",
            f"vendor-audit:{archive['identity']}", [output, *inputs],
        )
        authorized_outputs[str(output)] = (output, audit)

    inventory_by_owner = {
        (item["target"], item["source"]): item for item in inventory["entries"]
    }
    compiler_audits = {}
    for item in plan["compiles"]:
        producer_arguments = argparse.Namespace(
            manifest=verification.manifest,
            source_dir=verification.source_dir,
            build_dir=verification.build_dir,
            target=item["target"],
            configured_compiler=verification.compiler,
        )
        with resident_working_directory(Path(item["directory"])):
            command_compile_launch_locked(producer_arguments, item["argv"])
        inventory_item = inventory_by_owner[(item["target"], item["source"])]
        audit_path = Path(inventory_item["audit"])
        audit = read_unique_audit(
            audit_path, authority.build_root, "resident compiler audit"
        )
        dependency_paths = []
        for dependency in audit["consumed_dependencies"]:
            logical = Path(dependency["path"])
            overlay_owner = source_overlay_output_for_logical_path(
                state, logical
            )
            if overlay_owner is not None:
                relative, _output = overlay_owner
                expected = state["source_overlay"]["effective_by_path"][
                    relative
                ]
                require(
                    dependency["sha256"] == expected["sha256"],
                    "resident compiler dependency differs from its typed "
                    f"source overlay: {logical}",
                )
                continue
            snapshot = absolute_snapshot_seat(
                command_snapshot_path(verification.build_dir) / "z", logical
            )
            role = "compiler_dependency:" + hashlib.sha256(
                str(logical).encode("utf-8")
            ).hexdigest()
            root(snapshot, role)
            dependency_paths.append(snapshot)
        recipe_inputs = []
        if inventory_item["listed"]:
            matches = [
                unit for unit in state["translation_units"]
                if unit["target"] == item["target"]
                and unit["source"] == item["source"]
            ]
            require(len(matches) == 1,
                    "resident compile has no unique manifest unit")
            for donor in matches[0]["donors"]:
                output, recipe_audit = materialization_outputs[donor["id"]]
                recipe_inputs.extend([output, recipe_audit])
        dependency_authority_inputs = [*common_plan_inputs, compiler_tool]
        compile_inputs = [
            *dependency_authority_inputs,
            *dependency_paths, *recipe_inputs,
        ]
        dependency_output = Path(audit["dependency_output"])
        produced(
            dependency_output, "compiler-dependency",
            f"dependency:{item['target']}:{item['source']}",
            dependency_authority_inputs,
        )
        internal_outputs = []
        if inventory_item["listed"]:
            seed_object = Path(audit["seed_object"])
            seed_pdb = Path(audit["seed_pdb"])
            produced(
                seed_object, "compiler-seed-object",
                f"seed-object:{item['target']}:{item['source']}",
                [*compile_inputs, dependency_output],
            )
            produced(
                seed_pdb, "compiler-seed-pdb",
                f"seed-pdb:{item['target']}:{item['source']}",
                [*compile_inputs, dependency_output],
            )
            internal_outputs.extend([seed_object, seed_pdb])
            expected_stage_counts["compiler-donor-object"] += len(
                audit["donors"]
            )
            expected_stage_counts["compiler-donor-pdb"] += len(
                audit["donors"]
            )
            expected_stage_counts["compiler-auxiliary"] += len(
                audit["seed_auxiliary_outputs"]
            ) + sum(
                len(donor["auxiliary_outputs"])
                for donor in audit["donors"]
            )
            for auxiliary in audit["seed_auxiliary_outputs"]:
                path = Path(auxiliary["path"])
                produced(
                    path, "compiler-auxiliary",
                    f"seed-aux:{item['target']}:{item['source']}:{auxiliary['name']}",
                    [*compile_inputs, dependency_output],
                )
                internal_outputs.append(path)
            donor_objects = []
            for donor in audit["donors"]:
                donor_inputs = [
                    *compile_inputs, dependency_output, Path(donor["header"]),
                ]
                donor_object = Path(donor["object"])
                donor_pdb = Path(donor["pdb"])
                produced(
                    donor_object, "compiler-donor-object",
                    f"donor-object:{item['target']}:{item['source']}:{donor['recipe_id']}",
                    donor_inputs,
                )
                produced(
                    donor_pdb, "compiler-donor-pdb",
                    f"donor-pdb:{item['target']}:{item['source']}:{donor['recipe_id']}",
                    donor_inputs,
                )
                donor_objects.append(donor_object)
                internal_outputs.extend([donor_object, donor_pdb])
                for auxiliary in donor["auxiliary_outputs"]:
                    path = Path(auxiliary["path"])
                    produced(
                        path, "compiler-auxiliary",
                        f"donor-aux:{item['target']}:{item['source']}:{donor['recipe_id']}:{auxiliary['name']}",
                        donor_inputs,
                    )
                    internal_outputs.append(path)
            final_object_inputs = [seed_object, *donor_objects, *recipe_inputs]
            final_pdb_inputs = [seed_pdb]
        else:
            private_object = Path(audit["private_object"])
            private_pdb = Path(audit["private_pdb"])
            produced(
                private_object, "compiler-seed-object",
                f"seed-object:{item['target']}:{item['source']}",
                [*compile_inputs, dependency_output],
            )
            produced(
                private_pdb, "compiler-seed-pdb",
                f"seed-pdb:{item['target']}:{item['source']}",
                [*compile_inputs, dependency_output],
            )
            internal_outputs.extend([private_object, private_pdb])
            expected_stage_counts["compiler-auxiliary"] += len(
                audit["private_auxiliary_outputs"]
            )
            for auxiliary in audit["private_auxiliary_outputs"]:
                path = Path(auxiliary["path"])
                produced(
                    path, "compiler-auxiliary",
                    f"seed-aux:{item['target']}:{item['source']}:{auxiliary['name']}",
                    [*compile_inputs, dependency_output],
                )
                internal_outputs.append(path)
            final_object_inputs = [private_object]
            final_pdb_inputs = [private_pdb]
        final_object = Path(item["object"])
        final_pdb = Path(item["pdb"])
        produced(
            final_object, "compiler-object",
            f"object:{item['target']}:{item['source']}", final_object_inputs,
        )
        produced(
            final_pdb, "compiler-pdb",
            f"pdb:{item['target']}:{item['source']}", final_pdb_inputs,
        )
        produced(
            audit_path, "compiler-audit",
            f"compiler-audit:{item['target']}:{item['source']}",
            [final_object, final_pdb, dependency_output, *internal_outputs],
        )
        compiler_audits[str(final_object)] = audit_path

    resource_outputs = {}
    for item in plan["resources"]:
        inventory_matches = [
            entry for entry in inventory["inputs"]
            if entry["kind"] == "RC" and entry["target"] == item["target"]
            and entry["source"] == item["source"]
        ]
        require(len(inventory_matches) == 1,
                "resident resource plan has no unique inventory input")
        inventory_item = inventory_matches[0]
        sealed_source = absolute_snapshot_seat(
            command_snapshot_path(verification.build_dir) / "z",
            Path(inventory_item["source_path"]),
        )
        source_role = "resource_source:" + hashlib.sha256(
            inventory_item["source_path"].encode("utf-8")
        ).hexdigest()
        root(sealed_source, source_role)
        producer_arguments = argparse.Namespace(
            manifest=verification.manifest,
            source_dir=verification.source_dir,
            build_dir=verification.build_dir,
            target=item["target"],
            configured_compiler=verification.compiler,
        )
        resource_cwd = Path(item["cwd"])
        parsed_source, parsed_output, _parsed_roles = parse_resource_command(
            item["argv"], resource_cwd
        )
        require(parsed_source == Path(inventory_item["source_path"])
                and parsed_output == Path(item["output"]),
                "resident resource execution recipe changed after planning")
        with resident_working_directory(resource_cwd):
            producer_arguments.child = ["--", *item["argv"]]
            command_resource_launch_locked(producer_arguments)
        output = Path(item["output"])
        inputs = [
            *common_plan_inputs, link_tools["rc_wrapper"],
            link_tools["rc_binary"], sealed_source,
        ]
        produced(
            output, "resource-output",
            f"resource:{item['target']}:{item['source']}", inputs,
        )
        audit = Path(inventory_item["audit"])
        produced(
            audit, "resource-audit",
            f"resource-audit:{item['target']}:{item['source']}",
            [output, *inputs],
        )
        resource_outputs[str(output)] = audit

    first_party_outputs = {}
    for item in plan["archives"]:
        producer_arguments = argparse.Namespace(
            manifest=verification.manifest,
            source_dir=verification.source_dir,
            build_dir=verification.build_dir,
            target=item["target"],
            configured_compiler=verification.compiler,
            child=["--", *item["argv"]],
        )
        ordered = [Path(path) for path in item["ordered_inputs"]]
        object_audits = [
            compiler_audits.get(str(path), resource_outputs.get(str(path)))
            for path in ordered
        ]
        require(all(path is not None for path in object_audits),
                f"resident archive inputs lack producer audits: {item['target']}")
        inputs = [
            *common_plan_inputs, link_tools["lib_wrapper"],
            link_tools["lib_binary"], *ordered,
        ]
        ledger.require_exact_inputs(inputs)
        with resident_working_directory(Path(item["cwd"])):
            command_archive_launch_locked(producer_arguments)
        output = Path(item["output"])
        produced(
            output, "first-party-archive",
            f"archive:{item['target']}", inputs,
        )
        audit = first_party_archive_audit_path(
            verification.build_dir, item["target"]
        )
        produced(
            audit, "first-party-archive-audit",
            f"archive-audit:{item['target']}",
            [output, *[Path(path) for path in object_audits]],
        )
        first_party_outputs[str(output)] = audit

    # Explicit DEF/DX/MSVC snapshot leaves are independent roots and are
    # consumed in their exact LINK occurrence positions below.
    link_plan = plan["link"]
    producer_arguments = argparse.Namespace(
        manifest=verification.manifest,
        source_dir=verification.source_dir,
        build_dir=verification.build_dir,
        target="lego1", identity="LEGO1",
        configured_compiler=verification.compiler,
        child=["--", *link_plan["argv"]],
    )
    parsed = parse_link_command(
        link_plan["argv"], authority.build_root, state
    )
    ordered_records = terminal_link_ordered_inputs(
        state, inventory, session, parsed
    )
    ordered_link_inputs = []
    ordered_link_audits = []
    for index, record in enumerate(ordered_records):
        path = Path(record.get("snapshot_path", record["path"]))
        if "snapshot_path" in record:
            role = "sealed_link_input:" + hashlib.sha256(
                str(path).encode("utf-8")
            ).hexdigest()
            root(path, role)
        ordered_link_inputs.append(path)
        if record["role"] in {
            "compiler_object", "resource_output", "first_party_archive",
            "authorized_third_party_archive",
        }:
            ordered_link_audits.append(Path(record["audit"]))
    definition_records = [
        record for record in ordered_records
        if record["role"] == "linker_definition"
    ]
    require(len(definition_records) == 1,
            "resident LINK plan has no unique DEF receipt")
    link_inputs = [
        *common_plan_inputs, link_tools["link_wrapper"],
        link_tools["link_binary"],
        *ordered_link_inputs, *ordered_link_audits,
    ]
    ledger.require_exact_inputs(link_inputs)
    with resident_working_directory(Path(link_plan["cwd"])):
        command_link_launch_locked(producer_arguments)
    link_audit_path = final_link_audit_path(verification.build_dir, "LEGO1")
    link_audit = read_unique_audit(
        link_audit_path, authority.build_root, "resident LINK audit"
    )
    link_artifact_names = (
        "image", "analysis_image", "pdb", "map", "analysis_map",
        "import_library", "export_file", "analysis_import_library",
        "analysis_export_file", "verbose_log", "analysis_verbose_log",
    )
    link_artifacts = []
    for name in link_artifact_names:
        path = Path(link_audit[name])
        produced(path, "dual-link-output", f"link:{name}", link_inputs)
        link_artifacts.append(path)
    produced(
        link_audit_path, "dual-link-audit", "link:audit",
        [*link_artifacts, *link_inputs],
    )

    original = root(
        Path(state["images"][0]["original_path"]), "retail_oracle"
    )
    # The native CPython/reccmp closure is needed only after every compiler,
    # resource, archive, and LINK producer has succeeded.  Materialize it now
    # from authenticated sources inside this same resident authority, retain
    # its holder through reccmp/finalization, and never pay its relocation or
    # large closure-copy cost on an earlier producer failure.
    materialize_native_reccmp_snapshot(state, verification.build_dir)
    reccmp_backend_roots = [
        root(path, role) for role, path in resident_reccmp_backend_roots(
            state, verification.build_dir
        )
    ]
    reccmp_inputs = [
        *common_plan_inputs, *reccmp_backend_roots, original, link_audit_path,
        Path(link_audit["image"]), Path(link_audit["pdb"]),
        Path(link_audit["map"]),
    ]
    ledger.require_exact_inputs(reccmp_inputs)
    reccmp_arguments = argparse.Namespace(
        manifest=verification.manifest,
        source_dir=verification.source_dir,
        build_dir=verification.build_dir,
        identity="LEGO1", configured_compiler=verification.compiler,
    )
    command_reccmp_launch_locked(reccmp_arguments)
    report = final_report_path(verification.build_dir, "LEGO1")
    log = final_reccmp_log_path(verification.build_dir, "LEGO1")
    reccmp_audit = final_reccmp_audit_path(verification.build_dir, "LEGO1")
    produced(report, "reccmp-report", "reccmp:report", reccmp_inputs)
    produced(log, "reccmp-log", "reccmp:log", reccmp_inputs)
    produced(
        reccmp_audit, "reccmp-audit", "reccmp:audit",
        [report, log, *reccmp_inputs],
    )
    verified_nonterminal_leaves = resident_nonterminal_leaf_audits(
        state, plan, compiler_audits, resource_outputs
    )
    if verified_nonterminal_leaves:
        ledger.require_exact_inputs(verified_nonterminal_leaves)

    # Close every shared-input trust interval before verification pins or a
    # verdict can exist.  The command/toolchain snapshots are cold-rederived,
    # the merged projection is terminally rescanned and removed, and its
    # durable receipt is then made a resident-produced causal stage.
    finalize_resident_producer_authority(verification)
    finalize_native_reccmp_snapshot_validation(state, verification.build_dir)
    finalize_execution_projection(authority)
    projection_receipt = execution_projection_finalization_path(
        verification.build_dir
    )
    transport_audits = sorted({
        *map(str, compiler_audits.values()),
        *map(str, resource_outputs.values()),
        *map(str, first_party_outputs.values()),
        str(link_audit_path),
    })
    produced(
        projection_receipt, "execution-projection-finalization",
        "execution-projection:finalization",
        [
            toolchain_descriptor, command_descriptor, plan_descriptor,
            *[Path(path) for path in transport_audits],
        ],
    )

    result = (
        command_complete_locked(verification, publish=False)
        if terminal else command_iteration_locked(verification)
    )
    require(isinstance(result, dict)
            and result.get("byte_identity_complete") is terminal,
            "resident result completion kind differs from the requested mode")
    require(stage_counts == Counter(expected_stage_counts),
            "resident producer stage cardinality differs from the closed plan")
    # Dependency/header roots are admitted only by the one-pass dependency
    # capture against the preauthenticated immutable projection; no other
    # unplanned root role is allowed.
    actual_root_roles = {
        record["role"] for record in ledger.records.values()
        if record["kind"] == "authenticated_input"
    }
    require(actual_root_roles == required_root_roles,
            "resident authenticated input role universe differs")
    ledger.finalize(
        expected_stage_counts=expected_stage_counts,
        required_root_roles=required_root_roles,
        terminal_inputs=[
            reccmp_audit, projection_receipt,
            *verified_nonterminal_leaves,
        ],
    )
    # Close the verification epoch that consumed the large snapshots, then
    # retire those exact copied seats.  A new epoch pins every surviving DAG
    # artifact plus the compact in-memory-bound removal receipt through verdict
    # publication; no gigabyte-scale cache is retained on success.
    authority.revalidate_epoch()
    authority.begin_verification_epoch()
    retirement, retired_roots = retire_resident_input_snapshots(
        state, verification.build_dir
    )
    ledger.mark_retired_roots(retired_roots, retirement)
    ledger.require_surviving_current()
    validate_resident_input_retirement_evidence(
        authority, verification.build_dir
    )
    for holder in holders:
        holder.revalidate()
    result["resident_receipt_count"] = len(ledger.records)
    result["resident_receipt_nonce"] = ledger.nonce
    result["resident_plan_sha256"] = plan["descriptor_sha256"]
    # The verdict schema intentionally excludes the private receipt fields;
    # retain them in memory until publication, then remove them from the
    # user-visible canonical verdict.
    result.pop("resident_receipt_count")
    result.pop("resident_receipt_nonce")
    result.pop("resident_plan_sha256")
    return result, holders


def resident_verification_arguments(
    arguments: argparse.Namespace, controller: dict,
    authority: BuildRootAuthority,
) -> argparse.Namespace:
    raw = strict_json_loads(authority.read_bytes(inventory_path(arguments.build_dir)))
    require(isinstance(raw, dict), "configure inventory is not an object")
    compiler = raw.get("configured_compiler")
    require(
        isinstance(compiler, str) and Path(compiler).is_absolute(),
        "configure inventory compiler identity is absent",
    )
    return argparse.Namespace(
        manifest=Path(controller["manifest_path"]),
        source_dir=arguments.source_dir.resolve(),
        build_dir=arguments.build_dir,
        compiler=compiler,
    )


def resident_publish_framework_verdict(
    arguments: argparse.Namespace,
    verification_arguments: argparse.Namespace,
    result: dict,
    *,
    include_reccmp: bool,
) -> str:
    """Publish exactly the resident process's independently recomputed result."""
    authority = active_build_authority()
    verdict_path = (
        authority.build_root / "byte-identity/audit/framework-verdict.json"
    )
    authority.assert_absent(verdict_path)
    validate_framework_verdict_document(result)
    validate_resident_input_retirement_evidence(
        authority, verification_arguments.build_dir
    )
    state, inventory, _command_inventory, _session = (
        terminal_verification_inputs(verification_arguments)
    )
    audit_root = authority.build_root / "byte-identity/audit"
    expected = expected_top_level_audit_namespace(
        state, inventory, include_reccmp=include_reccmp
    )
    require_exact_build_namespace(
        authority, audit_root, expected,
        "resident pre-publication byte-identity audit namespace",
        replace_pin=True,
    )
    serialized = (
        json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")
    try:
        authority.revalidate_epoch()
        validate_resident_input_retirement_evidence(
            authority, verification_arguments.build_dir
        )
        authority.atomic_write(verdict_path, serialized)
        require_exact_build_namespace(
            authority,
            audit_root,
            {**expected, "framework-verdict.json": "file"},
            "resident published byte-identity audit namespace",
            replace_pin=True,
        )
        published = authority.read_bytes(verdict_path)
        require(
            published == serialized
            and exact_json_equal(strict_json_loads(published), result),
            "resident framework verdict differs from its recomputed result",
        )
        authority.revalidate_epoch()
    except BaseException:
        authority.prune_leaf_or_redirect(verdict_path)
        authority.assert_absent(verdict_path)
        raise
    return sha256_bytes(serialized)


OUTER_RECOVERY_PHASES = frozenset({
    "prior-controller-removing", "prior-controller-removed",
    "controller-reserved", "controller-ready",
    "cmake-child-may-have-started",
    "controller-removing", "controller-removed",
})


def outer_prior_controller_identity(
    document: dict, build_dir: Path,
) -> tuple[Path | None, str | None]:
    """Validate the optional completed-controller seat owned by the marker."""
    root_value = document.get("prior_controller_root")
    sha_value = document.get("prior_controller_descriptor_sha256")
    if root_value is None or sha_value is None:
        require(root_value is None and sha_value is None,
                "outer prior-controller binding is partial")
        return None, None
    require(isinstance(root_value, str)
            and SHA256_RE.fullmatch(sha_value) is not None,
            "outer prior-controller binding is invalid")
    root = Path(root_value)
    parent = controller_snapshot_path(build_dir, "0" * 64).parent
    authority = active_build_authority()
    root_parts = authority.parts(root)
    parent_parts = authority.parts(parent)
    current_parts = authority.parts(Path(document["controller_root"]))
    require(
        root_parts[:-1] == parent_parts
        and SHA256_RE.fullmatch(root.name) is not None
        and root_parts != current_parts,
        "outer prior-controller root is not an exact inactive nonce seat",
    )
    return root, sha_value


def update_outer_session_recovery_marker(
    document: dict, build_dir: Path, phase: str,
) -> None:
    """Persist one bounded owner before controller/CMake session mutations."""
    require(phase in OUTER_RECOVERY_PHASES,
            "outer recovery phase is invalid")
    authority = active_build_authority()
    nonce = document.get("nonce")
    require(SHA256_RE.fullmatch(nonce or "") is not None
            and document.get("controller_root")
            == str(controller_snapshot_path(build_dir, nonce))
            and document.get("resident_plan_root")
            == str(resident_plan_path(build_dir, nonce)),
            "outer recovery marker paths differ")
    outer_prior_controller_identity(document, build_dir)
    document["phase"] = phase
    raw = atomic_json(outer_session_recovery_path(build_dir), document)
    require(authority.read_bytes(outer_session_recovery_path(build_dir)) == raw,
            "outer recovery marker changed after publication")


def outer_session_process_groups(nonce: str, controller_root: Path) -> set[int]:
    tokens = {
        os.fsencode(SESSION_NONCE_ENV + "=" + nonce),
        os.fsencode(SESSION_CONTROLLER_ENV + "=" + str(controller_root)),
    }
    groups = set()
    own_group = os.getpgrp()
    for process_id in _transaction_process_ids():
        environment = _transaction_process_environment(process_id)
        if environment is None or not tokens <= set(environment.split(b"\0")):
            continue
        try:
            group = os.getpgid(process_id)
        except ProcessLookupError:
            continue
        require(group > 1 and group != own_group,
                "outer CMake child escaped its private process group")
        groups.add(group)
    return groups


def terminate_outer_session_processes(
    nonce: str, controller_root: Path,
) -> None:
    groups = outer_session_process_groups(nonce, controller_root)
    for group in groups:
        signal_process_group(group, signal.SIGTERM)
    deadline = time.monotonic() + 2
    while any(process_group_exists(group) for group in groups) \
            and time.monotonic() < deadline:
        time.sleep(COMPILER_SLOT_POLL_SECONDS)
    for group in groups:
        if process_group_exists(group):
            signal_process_group(group, signal.SIGKILL)
    deadline = time.monotonic() + 2
    while any(process_group_exists(group) for group in groups) \
            and time.monotonic() < deadline:
        time.sleep(COMPILER_SLOT_POLL_SECONDS)
    require(not any(process_group_exists(group) for group in groups)
            and not outer_session_process_groups(nonce, controller_root),
            "outer CMake process group survived bounded recovery")


def recover_outer_session_if_needed(build_dir: Path) -> None:
    """Recover one prepublished controller/CMake/plan epoch structurally."""
    authority = active_build_authority()
    marker_path = outer_session_recovery_path(build_dir)
    metadata = authority.lstat(marker_path)
    if metadata is None:
        return
    require(stat.S_ISREG(metadata.st_mode),
            "outer recovery marker is redirected")
    document = strict_json_loads(authority.read_bytes(marker_path))
    require(isinstance(document, dict),
            "outer recovery marker is not an object")
    exact_audit_keys(document, {
        "schema", "status", "nonce", "phase", "build_root",
        "controller_root", "controller_descriptor_sha256",
        "resident_plan_root", "prior_controller_root",
        "prior_controller_descriptor_sha256",
    }, "outer recovery marker")
    nonce = document.get("nonce")
    require(
        document.get("schema") == 1
        and document.get("status") == "OUTER_SESSION_RECOVERY_ACTIVE"
        and SHA256_RE.fullmatch(nonce or "") is not None
        and document.get("phase") in OUTER_RECOVERY_PHASES
        and document.get("build_root") == str(authority.build_root)
        and document.get("controller_root")
        == str(controller_snapshot_path(build_dir, nonce))
        and document.get("resident_plan_root")
        == str(resident_plan_path(build_dir, nonce)),
        "outer recovery marker identity differs",
    )
    prior_controller, _prior_sha = outer_prior_controller_identity(
        document, build_dir
    )
    require(
        document["phase"] not in {
            "prior-controller-removing", "prior-controller-removed"
        } or prior_controller is not None,
        "outer prior-controller phase lacks its exact binding",
    )
    require(authority.lstat(execution_projection_recovery_path(build_dir)) is None,
            "outer session recovery cannot precede execution recovery")
    controller_root = Path(document["controller_root"])
    plan_root = Path(document["resident_plan_root"])
    terminate_outer_session_processes(nonce, controller_root)
    rollback_exact_private_run(authority, plan_root)

    phase = document["phase"]
    if prior_controller is not None:
        prior_metadata = authority.lstat(prior_controller)
        if phase == "prior-controller-removing":
            if prior_metadata is not None:
                require(stat.S_ISDIR(prior_metadata.st_mode),
                        "outer prior controller is redirected")
                rollback_exact_private_run(authority, prior_controller)
            document["phase"] = "prior-controller-removed"
            atomic_json(marker_path, document)
            phase = document["phase"]
        else:
            require(prior_metadata is None,
                    "removed outer prior controller reappeared")

    controller_metadata = authority.lstat(controller_root)
    phase = document["phase"]
    descriptor_sha = document.get("controller_descriptor_sha256")
    if controller_metadata is None:
        require(phase in {
                    "prior-controller-removing", "prior-controller-removed",
                    "controller-reserved", "controller-removing",
                    "controller-removed",
                }, "outer recovery controller disappeared")
    else:
        require(stat.S_ISDIR(controller_metadata.st_mode),
                "outer recovery controller is redirected")
        require(phase != "controller-removed",
                "removed outer recovery controller reappeared")
        if phase not in {"controller-reserved", "controller-removing"}:
            require(SHA256_RE.fullmatch(descriptor_sha or "") is not None,
                    "outer recovery controller descriptor pin is absent")
            load_controller_snapshot_for_cleanup(
                authority, controller_root, descriptor_sha
            )
        document["phase"] = "controller-removing"
        atomic_json(marker_path, document)
        rollback_exact_private_run(authority, controller_root)
    document["phase"] = "controller-removed"
    atomic_json(marker_path, document)
    invalidate_build_paths([
        hard_mode_marker_path(build_dir), active_session_path(build_dir),
        completed_session_path(build_dir), preconfigure_seal_path(build_dir),
        configure_init_path(build_dir),
    ])
    invalidate_framework_verdict(build_dir)
    discard_resident_input_snapshots(
        authority, build_dir, invalidate_receipt=True
    )
    invalidate_build_paths([marker_path])
    authority.assert_absent(marker_path)


def rollback_failed_outer_bootstrap(
    authority: BuildRootAuthority, build_dir: Path, controller_root: Path,
) -> None:
    """Invalidate every bootstrap claim and only this session's controller."""
    failures = []
    try:
        invalidate_framework_verdict(build_dir)
    except BaseException as error:
        failures.append(f"framework verdict: {error}")
    try:
        invalidate_build_paths([
            active_session_path(build_dir), completed_session_path(build_dir),
            preconfigure_seal_path(build_dir), hard_mode_marker_path(build_dir),
            configure_init_path(build_dir),
        ])
    except BaseException as error:
        failures.append(f"bootstrap publications: {error}")
    recovery_active = authority.lstat(
        execution_projection_recovery_path(build_dir)
    ) is not None
    outer_marker = outer_session_recovery_path(build_dir)
    outer_document = None
    if authority.lstat(outer_marker) is not None:
        try:
            candidate = strict_json_loads(authority.read_bytes(outer_marker))
            if isinstance(candidate, dict):
                outer_document = candidate
        except BaseException as error:
            failures.append(f"outer recovery marker: {error}")
    if isinstance(outer_document, dict) and not recovery_active:
        try:
            nonce = outer_document.get("nonce", "")
            require(
                SHA256_RE.fullmatch(nonce) is not None
                and outer_document.get("controller_root")
                == str(controller_root)
                and outer_document.get("resident_plan_root")
                == str(resident_plan_path(build_dir, nonce)),
                "current outer recovery marker differs",
            )
            prior_controller, _prior_sha = outer_prior_controller_identity(
                outer_document, build_dir
            )
            if prior_controller is not None:
                prior_metadata = authority.lstat(prior_controller)
                if outer_document.get("phase") == "prior-controller-removing":
                    if prior_metadata is not None:
                        require(stat.S_ISDIR(prior_metadata.st_mode),
                                "current prior controller is redirected")
                        rollback_exact_private_run(
                            authority, prior_controller
                        )
                    outer_document["phase"] = "prior-controller-removed"
                    atomic_json(outer_marker, outer_document)
                else:
                    require(prior_metadata is None,
                            "removed current prior controller reappeared")
            rollback_exact_private_run(
                authority, resident_plan_path(build_dir, nonce)
            )
            outer_document["phase"] = "controller-removing"
            atomic_json(outer_marker, outer_document)
            rollback_exact_private_run(authority, controller_root)
            outer_document["phase"] = "controller-removed"
            atomic_json(outer_marker, outer_document)
            discard_resident_input_snapshots(
                authority, build_dir, invalidate_receipt=True
            )
            invalidate_build_paths([outer_marker])
            authority.assert_absent(outer_marker)
        except BaseException as error:
            failures.append(f"outer recovery: {error}")
    else:
        if isinstance(outer_document, dict):
            try:
                rollback_exact_private_run(
                    authority,
                    resident_plan_path(
                        build_dir, outer_document.get("nonce", "")
                    ),
                )
            except BaseException as error:
                failures.append(f"resident plan: {error}")
        if not recovery_active:
            try:
                rollback_exact_private_run(authority, controller_root)
            except BaseException as error:
                failures.append(f"controller snapshot: {error}")
        try:
            discard_resident_input_snapshots(
                authority, build_dir, invalidate_receipt=True
            )
        except BaseException as error:
            failures.append(f"resident input snapshots: {error}")
    require(not failures,
            "outer bootstrap rollback failed: " + "; ".join(failures))


def inactive_completed_controller_root(
    authority: BuildRootAuthority, build_dir: Path,
) -> tuple[Path, str] | None:
    """Authenticate the sole prior completed controller before retirement.

    A new outer session may replace a completed session, but it must never
    evict an active controller or sweep the controller-snapshots parent.  The
    completed seal is the only authority for the one exact inactive root that
    can be retired after the seal itself has been invalidated.
    """
    active_path = active_session_path(build_dir)
    require(
        authority.lstat(active_path) is None,
        "a byte-identity outer session is already active",
    )
    completed_path = completed_session_path(build_dir)
    metadata = authority.lstat(completed_path)
    if metadata is None:
        return None
    require(stat.S_ISREG(metadata.st_mode),
            "completed byte-identity outer session is redirected")
    completed = read_session_document(
        authority, completed_path, "completed byte-identity outer session"
    )
    require(
        completed.get("schema") == 1
        and completed.get("status")
        == "BYTE_IDENTITY_OUTER_SESSION_COMPLETED"
        and completed.get("build_root") == str(authority.build_root)
        and completed.get("returncode") == 0
        and isinstance(completed.get("nonce"), str)
        and re.fullmatch(r"[0-9a-f]{64}", completed["nonce"]) is not None,
        "completed byte-identity outer session identity differs",
    )
    controller_root = Path(completed.get("controller_root", ""))
    expected_root = controller_snapshot_path(
        build_dir, completed["nonce"]
    )
    require(
        authority.parts(controller_root) == authority.parts(expected_root),
        "completed byte-identity controller root differs",
    )
    descriptor_sha = require_sha(
        completed.get("controller_descriptor_sha256"),
        "completed controller descriptor hash",
    )
    load_controller_snapshot(authority, controller_root, descriptor_sha)
    return controller_root, descriptor_sha


def command_drive_cmake(arguments: argparse.Namespace) -> int:
    requested_build = lexical_absolute_path(arguments.build_dir)
    if not requested_build.exists():
        canonical_parent = requested_build.parent.resolve(strict=True)
        require(canonical_parent == requested_build.parent,
                "outer build parent is redirected")
        parent_fd = os.open(canonical_parent, DIRECTORY_FD_FLAGS)
        try:
            os.mkdir(requested_build.name, mode=0o700, dir_fd=parent_fd)
        finally:
            os.close(parent_fd)
    arguments.build_dir = requested_build
    require_disjoint_source_build(arguments.source_dir, arguments.build_dir)
    require_exact_int(arguments.max_seconds, "outer CMake timeout", minimum=1,
                      maximum=86400)
    nonce = hashlib.sha256(os.urandom(64)).hexdigest()
    requested_manifest = (
        lexical_absolute_path(arguments.manifest)
        if arguments.manifest is not None
        else lexical_absolute_path(
            arguments.source_dir / "tools/byte_identity_manifest.json"
        )
    )
    controller = None
    marker = None
    active = None
    outer_recovery = None
    with build_transaction(
        arguments.build_dir,
        exclusive=True,
        bootstrap_outer_session=True,
    ) as authority:
        controller_root = controller_snapshot_path(arguments.build_dir, nonce)
        recovered_prior_transaction = False
        # Recovery precedes every mutation or retirement owned by the new
        # session. A prior failed epoch retains its exact controller/runtime
        # authority; no configure child may delete those seats first.
        had_execution_recovery = authority.lstat(
            execution_projection_recovery_path(arguments.build_dir)
        ) is not None
        if had_execution_recovery:
            recover_execution_projection_if_needed(
                arguments.build_dir, current_manifest=requested_manifest
            )
        had_outer_recovery = authority.lstat(
            outer_session_recovery_path(arguments.build_dir)
        ) is not None
        if had_outer_recovery:
            recover_outer_session_if_needed(arguments.build_dir)
        if had_execution_recovery or had_outer_recovery:
            discard_resident_input_snapshots(
                authority, arguments.build_dir, invalidate_receipt=True
            )
            invalidate_build_paths([
                completed_session_path(arguments.build_dir),
                preconfigure_seal_path(arguments.build_dir),
            ])
            recovered_prior_transaction = True
        # Only after a prior transaction and its retained runtime/controller
        # authority are gone may the new session inspect current toolchain,
        # source, CMake, Python, or compiler state.
        cmake = lexical_absolute_path(arguments.cmake).resolve(strict=True)
        require(cmake.is_file() and os.access(cmake, os.X_OK),
                "outer CMake executable is absent")
        bootstrap_python = Path(sys.executable).resolve(strict=True)
        bootstrap_framework = Path(__file__).resolve(strict=True)
        bootstrap_backend = Path(
            execution_backend_module.__file__
        ).resolve(strict=True)
        requested_manifest = requested_manifest.resolve(strict=True)
        configured_compiler = lexical_absolute_path(
            arguments.compiler
        ).resolve(strict=True)
        require(configured_compiler.is_file()
                and os.access(configured_compiler, os.X_OK),
                "resident configured compiler wrapper is absent")
        bootstrap_state = validate_manifest(
            requested_manifest, arguments.source_dir.resolve(),
            arguments.build_dir,
            configured_compiler=str(configured_compiler),
        )
        require(
            bootstrap_state.get("diagnostic_policy") is None,
            "outer CMake refuses non-authoritative diagnostic manifests",
        )
        configure_role_paths = {
            item["role"]: item["absolute_path"]
            for item in bootstrap_state.get("terminal_producers", {})
            .get("link", {}).get("tools", [])
        }
        # Manifest-only unit fixtures may omit the terminal image policy. The
        # production manifest supplies all producer wrappers.
        if not configure_role_paths:
            configure_role_paths = {
                "rc_wrapper": str(configured_compiler),
                "lib_wrapper": str(configured_compiler),
                "link_wrapper": str(configured_compiler),
            }
        configure_tools = {
            "compiler": str(configured_compiler),
            "rc": configure_role_paths["rc_wrapper"],
            "lib": configure_role_paths["lib_wrapper"],
            "link": configure_role_paths["link_wrapper"],
        }
        require(
            all(Path(value).is_absolute() for value in configure_tools.values()),
            "resident configure producer tool map is incomplete",
        )
        # This preflight predates every mutation owned by the new nonce.  A
        # live session or malformed completed seal must fail closed without a
        # rollback helper deleting the prior session's controller/state.  The
        # old verdict is independently invalidated because it cannot remain a
        # success claim once a requested replacement session is refused.
        invalidate_framework_verdict(arguments.build_dir)
        retired_controller = (
            None if recovered_prior_transaction
            else inactive_completed_controller_root(
                authority, arguments.build_dir
            )
        )
        try:
            retired_controller_root = (
                retired_controller[0]
                if retired_controller is not None else None
            )
            retired_controller_sha = (
                retired_controller[1]
                if retired_controller is not None else None
            )
            outer_recovery = {
                "schema": 1,
                "status": "OUTER_SESSION_RECOVERY_ACTIVE",
                "nonce": nonce,
                "phase": (
                    "prior-controller-removing"
                    if retired_controller is not None
                    else "controller-reserved"
                ),
                "build_root": str(authority.build_root),
                "controller_root": str(controller_root),
                "controller_descriptor_sha256": None,
                "resident_plan_root": str(resident_plan_path(
                    arguments.build_dir, nonce
                )),
                "prior_controller_root": (
                    str(retired_controller_root)
                    if retired_controller_root is not None else None
                ),
                "prior_controller_descriptor_sha256": retired_controller_sha,
            }
            update_outer_session_recovery_marker(
                outer_recovery, arguments.build_dir,
                outer_recovery["phase"],
            )
            invalidate_build_paths([
                completed_session_path(arguments.build_dir),
                preconfigure_seal_path(arguments.build_dir),
            ])
            if retired_controller_root is not None:
                rollback_exact_private_run(
                    authority, retired_controller_root
                )
                update_outer_session_recovery_marker(
                    outer_recovery, arguments.build_dir,
                    "prior-controller-removed",
                )
            update_outer_session_recovery_marker(
                outer_recovery, arguments.build_dir, "controller-reserved"
            )
            controller = materialize_controller_snapshot(
                build_dir=arguments.build_dir,
                source_dir=arguments.source_dir,
                cmake=cmake,
                nonce=nonce,
                manifest=requested_manifest,
            )
            outer_recovery["controller_descriptor_sha256"] = (
                controller["descriptor_sha256"]
            )
            update_outer_session_recovery_marker(
                outer_recovery, arguments.build_dir, "controller-ready"
            )
            init_path = configure_init_path(arguments.build_dir)
            authority.atomic_write(
                init_path, render_configure_init(configure_tools), mode=0o400
            )
            controller["configure_init"] = str(init_path)
            marker = {
                "schema": 1,
                "status": "BYTE_IDENTITY_OUTER_DRIVER_REQUIRED",
                "source_root": str(arguments.source_dir.resolve()),
                "build_root": str(authority.build_root),
                "bootstrap_python": str(bootstrap_python),
                "bootstrap_python_sha256": sha256_file(bootstrap_python),
                "bootstrap_framework": str(bootstrap_framework),
                "bootstrap_framework_sha256": sha256_file(bootstrap_framework),
                "bootstrap_backend": str(bootstrap_backend),
                "bootstrap_backend_sha256": sha256_file(bootstrap_backend),
                "controller_root": controller["root"],
                "controller_descriptor_sha256": controller["descriptor_sha256"],
                "python": controller["python_path"],
                "python_sha256": controller["python"]["sha256"],
                "framework": controller["tool_path"],
                "framework_sha256": controller["framework"]["tool"]["sha256"],
                "backend": selected_backend(),
                "backend_tool": controller["backend_path"],
                "backend_tool_sha256": controller["framework"]["backend"]["sha256"],
                "configure_init": str(init_path),
                "configure_init_sha256": sha256_file(init_path),
                "configure_probe_policy":
                    "zero_compiler_actions_forced_manifest_facts_v1",
                "configure_tools": configure_tools,
                "host_roots": bootstrap_state["host_roots"],
            }
            active = {
                **marker,
                "status": "BYTE_IDENTITY_OUTER_SESSION_ACTIVE",
                "nonce": nonce,
                "mode": arguments.mode,
                "driver_pid": os.getpid(),
                "cmake": controller["cmake_path"],
                "cmake_sha256": controller["cmake"]["sha256"],
                "started_monotonic": float(time.monotonic()),
            }
            atomic_json(hard_mode_marker_path(arguments.build_dir), marker)
            atomic_json(active_session_path(arguments.build_dir), active)
            if arguments.mode in ("iterate", "build"):
                # Each outer build receives a new nonce.  Remove the terminal
                # image and its complete producer chain before planning.
                invalidate_terminal_outputs(arguments.build_dir)
                atomic_json(
                    preconfigure_seal_path(arguments.build_dir),
                    preconfigure_session_document(active),
                )
        except BaseException as original:
            try:
                rollback_failed_outer_bootstrap(
                    authority, arguments.build_dir, controller_root
                )
            except BaseException as cleanup_error:
                raise ByteIdentityError(str(cleanup_error)) from original
            raise

    require(controller is not None and marker is not None and active is not None
            and outer_recovery is not None,
            "outer controller bootstrap did not complete")
    try:
        commands = _outer_cmake_commands(arguments, controller)
    except BaseException as original:
        try:
            with build_transaction(
                arguments.build_dir,
                exclusive=True,
                bootstrap_outer_session=True,
            ) as authority:
                rollback_failed_outer_bootstrap(
                    authority, arguments.build_dir,
                    controller_snapshot_path(arguments.build_dir, nonce),
                )
        except BaseException as cleanup_error:
            raise ByteIdentityError(str(cleanup_error)) from original
        raise

    previous_nonce = os.environ.get(SESSION_NONCE_ENV)
    previous_python = os.environ.get(SESSION_PYTHON_ENV)
    previous_controller = os.environ.get(SESSION_CONTROLLER_ENV)
    previous_pythonhome = os.environ.get("PYTHONHOME")
    environment = dict(os.environ)
    environment[SESSION_NONCE_ENV] = nonce
    environment[SESSION_PYTHON_ENV] = controller["python_path"]
    environment[SESSION_CONTROLLER_ENV] = controller["root"]
    environment["PYTHONHOME"] = str(Path(controller["python_path"]).parent.parent)
    environment["PYTHONDONTWRITEBYTECODE"] = "1"
    os.environ[SESSION_NONCE_ENV] = nonce
    os.environ[SESSION_PYTHON_ENV] = controller["python_path"]
    os.environ[SESSION_CONTROLLER_ENV] = controller["root"]
    os.environ["PYTHONHOME"] = environment["PYTHONHOME"]
    returncode = 2
    timed_out = False
    try:
        with build_transaction(
            arguments.build_dir, exclusive=True,
            bootstrap_outer_session=True,
        ):
            update_outer_session_recovery_marker(
                outer_recovery, arguments.build_dir,
                "cmake-child-may-have-started",
            )
        for command in commands:
            # This is the explicit pre-use half of the trusted-controller
            # boundary.  The matching postflight validation below detects any
            # persistent mutation.  Same-UID replace/execute/restore races of
            # the controller itself are intentionally outside this milestone;
            # all produced build evidence remains hostile and recomputed.
            with build_transaction(
                arguments.build_dir, exclusive=False
            ) as authority:
                live = validate_active_session_authority(authority, nonce)
                require(live is not None and exact_json_equal(live, active),
                        "outer session changed before CMake execution")
                validate_controller_snapshot(authority, controller)
            returncode, output, timed_out = run_child(
                command, arguments.max_seconds, environment,
                cwd=arguments.source_dir.resolve(),
            )
            sys.stdout.buffer.write(output)
            sys.stdout.buffer.flush()
            if timed_out or returncode != 0:
                break
        with build_transaction(arguments.build_dir, exclusive=True) as authority:
            live = validate_active_session_authority(authority, nonce)
            require(live is not None and exact_json_equal(live, active),
                    "outer session changed while CMake ran")
            validate_controller_snapshot(authority, controller)
            if not timed_out and returncode == 0:
                validate_preconfigure_session_seal(authority, active)
                verdict = (
                    authority.build_root
                    / "byte-identity/audit/framework-verdict.json"
                )
                verdict_sha = None
                if authority.lstat(verdict) is not None:
                    authority.prune_leaf_or_redirect(verdict)
                    authority.assert_absent(verdict)
                    raise ByteIdentityError(
                        "child CMake attempted to inject the resident-only framework verdict"
                    )
                if arguments.mode in ("iterate", "build"):
                    with resident_receipt_scope(nonce) as ledger:
                        plan = None
                        verification_arguments = None
                        try:
                            verification_arguments = (
                                resident_rederive_inventory_locked(
                                    arguments, controller
                                )
                            )
                            plan = derive_resident_closed_plan(
                                arguments, verification_arguments,
                                controller, live,
                            )
                            result, resident_holders = (
                                execute_resident_closed_plan(
                                    verification_arguments, controller, live,
                                    plan, ledger,
                                    terminal=arguments.mode == "build",
                                )
                            )
                            require(isinstance(result, dict),
                                    "resident production did not return a verdict")
                            verdict_sha = resident_publish_framework_verdict(
                                arguments,
                                verification_arguments,
                                result,
                                include_reccmp=True,
                            )
                            ledger.require_surviving_current()
                            validate_resident_input_retirement_evidence(
                                authority, arguments.build_dir
                            )
                            for holder in resident_holders:
                                holder.revalidate()
                        finally:
                            cleanup_failures = []
                            try:
                                abort_execution_projection(authority)
                            except BaseException as error:
                                cleanup_failures.append(
                                    f"execution transaction: {error}"
                                )
                            if plan is not None:
                                for holder in reversed(
                                    plan.get("_resident_holders", [
                                        plan.get("holder")
                                    ])
                                ):
                                    if isinstance(holder, HeldBuildDirectories):
                                        holder.close()
                                try:
                                    rollback_exact_private_run(
                                        authority, Path(plan["root"])
                                    )
                                except BaseException as error:
                                    cleanup_failures.append(
                                        f"resident plan: {error}"
                                    )
                            try:
                                discard_resident_input_snapshots(
                                    authority, arguments.build_dir,
                                    invalidate_receipt=verdict_sha is None,
                                )
                            except BaseException as error:
                                cleanup_failures.append(
                                    f"resident inputs: {error}"
                                )
                            require(
                                not cleanup_failures,
                                "resident terminal cleanup failed: "
                                + "; ".join(cleanup_failures),
                            )
                completion = {
                    **active,
                    "status": "BYTE_IDENTITY_OUTER_SESSION_COMPLETED",
                    "returncode": 0,
                    "completed_monotonic": float(time.monotonic()),
                    "framework_verdict_sha256": verdict_sha,
                }
                atomic_json(completed_session_path(arguments.build_dir), completion)
                invalidate_build_paths([active_session_path(arguments.build_dir)])
                invalidate_build_paths([
                    outer_session_recovery_path(arguments.build_dir)
                ])
                authority.assert_absent(
                    outer_session_recovery_path(arguments.build_dir)
                )
        require(not timed_out, "outer CMake invocation timed out")
        require(returncode == 0,
                f"outer CMake invocation exited with status {returncode}")
        return 0
    except BaseException as original:
        # The resident process is also the last-resort invalidator.  Use the
        # bootstrap path because a broken/mutated child session must never be
        # trusted merely to clean up its own authority claims.
        try:
            with build_transaction(
                arguments.build_dir,
                exclusive=True,
                bootstrap_outer_session=True,
            ) as authority:
                rollback_failed_outer_bootstrap(
                    authority, arguments.build_dir,
                    controller_snapshot_path(arguments.build_dir, nonce),
                )
        except BaseException as cleanup_error:
            raise ByteIdentityError(str(cleanup_error)) from original
        raise
    finally:
        if previous_nonce is None:
            os.environ.pop(SESSION_NONCE_ENV, None)
        else:
            os.environ[SESSION_NONCE_ENV] = previous_nonce
        if previous_python is None:
            os.environ.pop(SESSION_PYTHON_ENV, None)
        else:
            os.environ[SESSION_PYTHON_ENV] = previous_python
        if previous_controller is None:
            os.environ.pop(SESSION_CONTROLLER_ENV, None)
        else:
            os.environ[SESSION_CONTROLLER_ENV] = previous_controller
        if previous_pythonhome is None:
            os.environ.pop("PYTHONHOME", None)
        else:
            os.environ["PYTHONHOME"] = previous_pythonhome


def command_unfinalized_launch(arguments: argparse.Namespace) -> int:
    """Fail a compile inherited before final graph attestation."""
    with build_transaction(arguments.build_dir, exclusive=True):
        invalidate_framework_verdict(arguments.build_dir)
        raise ByteIdentityError(
            "C/C++ target was not admitted by end-of-configure byte-identity attestation"
        )


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser(description=__doc__)
    subcommands = result.add_subparsers(dest="command", required=True)

    drive = subcommands.add_parser("drive-cmake")
    drive.add_argument("--source-dir", type=Path, required=True)
    drive.add_argument("--build-dir", type=Path, required=True)
    drive.add_argument("--cmake", type=Path, required=True)
    drive.add_argument("--compiler", type=Path, required=True)
    drive.add_argument("--manifest", type=Path)
    drive.add_argument(
        "--mode", choices=("configure", "iterate", "build"), required=True
    )
    drive.add_argument("--max-seconds", type=int, default=3600)
    drive.add_argument("cmake_args", nargs=argparse.REMAINDER)
    drive.set_defaults(handler=command_drive_cmake)

    preconfigure = subcommands.add_parser("preconfigure-check")
    preconfigure.add_argument("--source-dir", type=Path, required=True)
    preconfigure.add_argument("--build-dir", type=Path, required=True)
    preconfigure.add_argument("--cmake", type=Path, required=True)
    preconfigure.add_argument("--nonce", required=True)
    preconfigure.set_defaults(handler=command_preconfigure_check)

    plan = subcommands.add_parser("plan")
    plan.add_argument("--manifest", type=Path, required=True)
    plan.add_argument("--source-dir", type=Path, required=True)
    plan.add_argument("--build-dir", type=Path, required=True)
    plan.add_argument("--compiler", required=True)
    plan.add_argument("--compiler-id", required=True)
    plan.add_argument("--compiler-version", required=True)
    plan.add_argument("--generator", required=True)
    plan.add_argument("--output", type=Path, required=True)
    plan.add_argument("--emit-cmake", action="store_true")
    plan.set_defaults(handler=command_plan)

    inventory = subcommands.add_parser("inventory")
    inventory.add_argument("--manifest", type=Path, required=True)
    inventory.add_argument("--source-dir", type=Path, required=True)
    inventory.add_argument("--build-dir", type=Path, required=True)
    inventory.add_argument("--compiler", required=True)
    inventory.add_argument("--cmake-module", type=Path, required=True)
    inventory.add_argument("--output", type=Path, required=True)
    inventory.add_argument("--cmake-output", type=Path, required=True)
    inventory.add_argument("--policy-stamp", type=Path, required=True)
    inventory.add_argument("--entry", nargs="+", action="append", required=True)
    inventory.add_argument(
        "--target-entry", nargs=3, action="append", required=True
    )
    inventory.add_argument(
        "--graph-count", nargs=3, action="append", required=True
    )
    inventory.add_argument(
        "--graph-item", nargs=3, action="append", default=[]
    )
    inventory.add_argument("--standard-library-configuration")
    inventory.add_argument("--standard-library-base-count")
    inventory.add_argument(
        "--standard-library-base-item", action="append", default=[]
    )
    inventory.add_argument("--standard-library-config-count")
    inventory.add_argument(
        "--standard-library-config-item", action="append", default=[]
    )
    inventory.add_argument(
        "--input-entry", nargs="+", action="append", default=[]
    )
    inventory.add_argument("--emit-cmake", action="store_true")
    inventory.set_defaults(handler=command_inventory)

    attest = subcommands.add_parser("attest-commands")
    attest.add_argument("--manifest", type=Path, required=True)
    attest.add_argument("--source-dir", type=Path, required=True)
    attest.add_argument("--build-dir", type=Path, required=True)
    attest.add_argument("--compiler", required=True)
    attest.add_argument("--compile-commands", type=Path, required=True)
    attest.add_argument("--output", type=Path, required=True)
    attest.add_argument("--policy-stamp", type=Path, required=True)
    attest.set_defaults(handler=command_attest_commands)

    materialize = subcommands.add_parser("materialize")
    materialize.add_argument("--manifest", type=Path, required=True)
    materialize.add_argument("--source-dir", type=Path, required=True)
    materialize.add_argument("--build-dir", type=Path, required=True)
    materialize.add_argument("--recipe-id", required=True)
    materialize.add_argument("--output", type=Path, required=True)
    materialize.set_defaults(handler=command_materialize)

    materialize_archive = subcommands.add_parser("materialize-archive")
    materialize_archive.add_argument("--manifest", type=Path, required=True)
    materialize_archive.add_argument("--source-dir", type=Path, required=True)
    materialize_archive.add_argument("--build-dir", type=Path, required=True)
    materialize_archive.add_argument("--identity", required=True)
    materialize_archive.add_argument("--output", type=Path, required=True)
    materialize_archive.set_defaults(handler=command_materialize_archive)

    resource_launch = subcommands.add_parser("resource-launch")
    resource_launch.add_argument("--manifest", type=Path, required=True)
    resource_launch.add_argument("--source-dir", type=Path, required=True)
