def main(argv: list[str] | None = None) -> int:
    try:
        arguments = parser().parse_args(argv)
        return arguments.handler(arguments)
    except (ByteIdentityError, BackendError, OSError, ValueError) as error:
        print(f"byte_identity: refusing: {error}", file=sys.stderr)
        seen = {id(error)}
        link = error.__cause__ or (
            None if error.__suppress_context__ else error.__context__
        )
        depth = 0
        while link is not None and id(link) not in seen and depth < 8:
            print(f"byte_identity: caused by: {link}", file=sys.stderr)
            seen.add(id(link))
            link = link.__cause__ or (
                None if link.__suppress_context__ else link.__context__
            )
            depth += 1
        return 2
    finally:
        while ACTIVE_LOCKS:
            platform_lock, handle = ACTIVE_LOCKS.pop()
            try:
                platform_lock.release()
            finally:
                handle.close()


if __name__ == "__main__":
    raise SystemExit(main())
